CREATE OR REPLACE FUNCTION "app_private"."access_profile_can_delegate_institution"("p_permission_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.has_platform_permission(delegation.platform_permission_code)
  from app_private.access_profile_institution_delegations delegation
  where delegation.institution_permission_id=p_permission_id and delegation.status='active'
$$;


ALTER FUNCTION "app_private"."access_profile_can_delegate_institution"("p_permission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_can_delegate_principal"("p_capability_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(bool_or(app_private.has_platform_permission(delegation.platform_permission_code)),false)
  from app_private.access_profile_principal_delegations delegation
  where delegation.capability_id=p_capability_id and delegation.status='active'
$$;


ALTER FUNCTION "app_private"."access_profile_can_delegate_principal"("p_capability_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_capability_catalog_guard"("p_domain" "text", "p_profile_id" "uuid" DEFAULT NULL::"uuid", "p_assignment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actual_profile_id uuid:=p_profile_id;valid_pair boolean:=true;
begin
  if p_assignment_id is not null then
    if p_domain='platform' then
      select membership.role_id, p_profile_id is null or membership.role_id=p_profile_id
        into actual_profile_id,valid_pair from public.platform_memberships membership where membership.id=p_assignment_id;
    elsif p_domain='institution' then
      select assignment.role_id, p_profile_id is null or assignment.role_id=p_profile_id
        into actual_profile_id,valid_pair from public.institution_role_assignments assignment where assignment.id=p_assignment_id;
    elsif p_domain='principal' then
      select context_permission.source_template_id,
        p_profile_id is null or context_permission.source_template_id=p_profile_id
        into actual_profile_id,valid_pair from public.guardian_context_permissions context_permission where context_permission.id=p_assignment_id;
    else raise invalid_parameter_value using message='unsupported profile domain';end if;
    if actual_profile_id is null or not coalesce(valid_pair,false) then
      raise no_data_found using message='assignment does not belong to profile';end if;
  end if;
  return app_private.superadmin_access_profile_capability_catalog(p_domain,actual_profile_id,p_assignment_id);
end $$;


ALTER FUNCTION "app_private"."access_profile_capability_catalog_guard"("p_domain" "text", "p_profile_id" "uuid", "p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_create_internal"("p_actor" "uuid", "p_draft" "jsonb", "p_source_template_id" "uuid" DEFAULT NULL::"uuid", "p_source_template_version" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare domain text:=p_draft->>'domain';profile_id uuid;generated_code text;target_institution_id uuid:=nullif(p_draft->>'institution_id','')::uuid;
  capability jsonb;capabilities jsonb:=coalesce(p_draft->'capabilities','[]'::jsonb);permission_id uuid;
begin
  if p_actor is distinct from app_private.current_person_id() or domain not in('platform','institution')
    or nullif(btrim(p_draft->>'name'),'') is null or char_length(btrim(p_draft->>'name'))>120
    or jsonb_typeof(capabilities)<>'array' or jsonb_array_length(capabilities)>500 then
    raise invalid_parameter_value using message='invalid profile draft';
  end if;
  generated_code:=trim(both '-' from regexp_replace(lower(btrim(p_draft->>'name')),'[^a-z0-9]+','-','g'))
    ||'-'||left(replace(gen_random_uuid()::text,'-',''),8);
  if domain='platform' then
    if coalesce(p_draft->>'max_scope_kind','platform') not in('platform','institution') then
      raise invalid_parameter_value using message='invalid platform profile scope';end if;
    for capability in select value from jsonb_array_elements(capabilities) loop
      if capability->>'effect' not in('allow','deny') or not exists(select 1 from public.platform_permissions
        where code=capability->>'code' and status='active') then raise invalid_parameter_value using message='unknown or invalid capability';end if;
      if capability->>'effect'='allow' and not app_private.has_platform_permission(capability->>'code') then
        raise insufficient_privilege using message='cannot delegate capability operator does not hold';end if;
    end loop;
    insert into public.platform_roles(code,name,description,status,is_system,created_by,max_scope_kind,source_template_id,source_template_version)
    values(generated_code,btrim(p_draft->>'name'),nullif(btrim(p_draft->>'description'),''),
      coalesce(p_draft->>'status','inactive')::public.record_status,false,p_actor,
      coalesce(p_draft->>'max_scope_kind','platform'),p_source_template_id,p_source_template_version) returning id into profile_id;
    insert into public.platform_role_permissions(role_id,permission_id,effect,conditions_json,granted_by,status)
    select profile_id,permission_record.id,(item.value->>'effect')::public.permission_effect,'{}',p_actor,'active'
    from jsonb_array_elements(capabilities) item join public.platform_permissions permission_record on permission_record.code=item.value->>'code';
  else
    if coalesce(p_draft->>'max_scope_kind','institution') not in('institution','unit','group') then
      raise invalid_parameter_value using message='invalid institution profile scope';end if;
    for capability in select value from jsonb_array_elements(capabilities) loop
      select id into permission_id from public.institution_permissions where code=capability->>'code' and status='active';
      if capability->>'effect' not in('allow','deny') or permission_id is null then
        raise invalid_parameter_value using message='unknown or invalid capability';end if;
      if capability->>'effect'='allow' and not app_private.access_profile_can_delegate_institution(permission_id) then
        raise insufficient_privilege using message='cannot delegate capability operator does not hold';end if;
    end loop;
    -- P31: sem institution_id o perfil e um modelo do sistema (is_system) da
    -- plataforma; com institution_id e um perfil proprio daquela instituicao.
    if target_institution_id is not null and not exists(select 1 from public.institutions institution
        where institution.id=target_institution_id and institution.status='active') then
      raise invalid_parameter_value using message='invalid institution for profile';end if;
    insert into public.institution_roles(institution_id,code,name,description,status,is_system,max_scope_kind,source_template_id,source_template_version)
    values(target_institution_id,generated_code,btrim(p_draft->>'name'),nullif(btrim(p_draft->>'description'),''),
      coalesce(p_draft->>'status','inactive')::public.record_status,target_institution_id is null,
      coalesce(p_draft->>'max_scope_kind','institution'),p_source_template_id,p_source_template_version) returning id into profile_id;
    insert into public.institution_role_permissions(role_id,permission_id,effect,conditions_json,granted_by,status)
    select profile_id,permission_record.id,(item.value->>'effect')::public.permission_effect,'{}',p_actor,'active'
    from jsonb_array_elements(capabilities) item join public.institution_permissions permission_record on permission_record.code=item.value->>'code';
  end if;
  return app_private.access_profile_detail_v2(domain,profile_id);
end $$;


ALTER FUNCTION "app_private"."access_profile_create_internal"("p_actor" "uuid", "p_draft" "jsonb", "p_source_template_id" "uuid", "p_source_template_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_csv_cell"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select '"'||replace(case when coalesce(p_value,'') ~ '^[=+@-]' then ''''||coalesce(p_value,'') else coalesce(p_value,'') end,'"','""')||'"'
$$;


ALTER FUNCTION "app_private"."access_profile_csv_cell"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_detail_v2"("p_domain" "text", "p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.require_profile_authority(p_domain);
  if p_domain='platform' then
    select to_jsonb(role_record)||jsonb_build_object('domain','platform',
      'linked_people_count',(select count(*) from public.platform_memberships membership
        where membership.role_id=role_record.id and membership.status='active' and membership.revoked_at is null),
      'capability_count',(select count(*) from public.platform_role_permissions grant_record
        where grant_record.role_id=role_record.id and grant_record.status='active' and grant_record.revoked_at is null))
    into result from public.platform_roles role_record where role_record.id=p_profile_id;
  elsif p_domain='institution' then
    select to_jsonb(role_record)||jsonb_build_object('domain','institution',
      'linked_people_count',(select count(*) from public.institution_role_assignments assignment
        where assignment.role_id=role_record.id and assignment.status='active'
          and (assignment.expires_at is null or assignment.expires_at>now())),
      'capability_count',(select count(*) from public.institution_role_permissions grant_record
        where grant_record.role_id=role_record.id and grant_record.status='active' and grant_record.revoked_at is null))
    into result from public.institution_roles role_record where role_record.id=p_profile_id;
  else raise invalid_parameter_value using message='unsupported profile domain'; end if;
  if result is null then raise no_data_found using message='access profile not found'; end if;
  return result;
end $$;


ALTER FUNCTION "app_private"."access_profile_detail_v2"("p_domain" "text", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_detail_v3"("p_domain" "text", "p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  can_read_audit boolean;
begin
  perform app_private.require_profile_authority(p_domain);
  can_read_audit := app_private.has_platform_permission('audit.read');

  if p_domain = 'platform' then
    select jsonb_build_object(
      'domain', 'platform',
      'id', coalesce(role_record.id::text, ''),
      'code', coalesce(role_record.code, ''),
      'name', coalesce(role_record.name, ''),
      'description', coalesce(role_record.description, ''),
      'status', coalesce(role_record.status, 'active'),
      'max_scope_kind', coalesce(role_record.max_scope_kind, 'platform'),
      'version', coalesce(role_record.version, 0),
      'is_system', coalesce(role_record.is_system, false),
      'membership_count', (
        select count(*)
        from public.platform_memberships membership
        where membership.role_id = role_record.id
          and membership.status = 'active'
          and membership.revoked_at is null
      ),
      'memberships', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', membership.id,
          'person_name', person_record.display_name,
          'scope', case
            when membership.scope_kind = 'platform' then 'Plataforma'
            else 'Instituição: ' || coalesce(institution_record.public_name,
              membership.scope_institution_id::text)
          end
        ) order by lower(person_record.display_name), membership.id)
        from public.platform_memberships membership
        join public.people person_record on person_record.id = membership.person_id
        left join public.institutions institution_record
          on institution_record.id = membership.scope_institution_id
        where membership.role_id = role_record.id
          and membership.status = 'active'
          and membership.revoked_at is null
      ), '[]'::jsonb),
      'permissions', coalesce((
        select jsonb_agg(jsonb_build_object(
          'code', permission_record.code,
          'module', permission_record.module_code,
          'screen_code', coalesce(permission_record.screen_code, 'general'),
          'action_code', permission_record.action_code,
          'module_label', permission_record.module_label,
          'screen_label', permission_record.screen_label,
          'action_label', permission_record.action_label,
          'name', coalesce(permission_record.description, permission_record.action_label),
          'description', permission_record.description,
          'risk', permission_record.risk_level,
          'requires_mfa', permission_record.requires_mfa,
          'selected', grant_record.id is not null and grant_record.effect = 'allow',
          'grantable', actor_grant.allowed,
          'inherited', false,
          'unavailable_reason', case
            when actor_grant.allowed then null
            else 'Você não pode conceder uma permissão que não possui.'
          end
        ) order by permission_record.module_code, permission_record.screen_code,
          permission_record.action_code, permission_record.code)
        from public.platform_permissions permission_record
        cross join lateral (
          select app_private.has_platform_permission(permission_record.code) as allowed
        ) actor_grant
        left join public.platform_role_permissions grant_record
          on grant_record.permission_id = permission_record.id
          and grant_record.role_id = role_record.id
          and grant_record.status = 'active'
          and grant_record.revoked_at is null
        where permission_record.status = 'active'
      ), '[]'::jsonb),
      'audit', case when can_read_audit then
        coalesce((
          select jsonb_agg(jsonb_build_object(
            'action', audit_record.action_code,
            'reason', audit_record.reason,
            'occurred_at', audit_record.occurred_at
          ) order by audit_record.occurred_at desc)
          from (
            select audit_row.action_code, audit_row.reason, audit_row.occurred_at
            from audit.audit_logs audit_row
            where audit_row.object_id = role_record.id
            order by audit_row.occurred_at desc
            limit 10
          ) audit_record
        ), '[]'::jsonb)
      else null end
    )
    into result
    from (
      select role_row.id, role_row.code, role_row.name, role_row.description,
        role_row.status::text as status, role_row.max_scope_kind,
        role_row.version, role_row.is_system
      from public.platform_roles role_row
      where role_row.id = p_profile_id
      union all
      select null::uuid, '', '', '', 'active', 'platform', 0::bigint, false
      where p_profile_id is null
      limit 1
    ) role_record;

  elsif p_domain = 'institution' then
    select jsonb_build_object(
      'domain', 'institution',
      'id', coalesce(role_record.id::text, ''),
      'institution_id', role_record.institution_id,
      'code', coalesce(role_record.code, ''),
      'name', coalesce(role_record.name, ''),
      'description', coalesce(role_record.description, ''),
      'status', coalesce(role_record.status, 'active'),
      'max_scope_kind', coalesce(role_record.max_scope_kind, 'institution'),
      'version', coalesce(role_record.version, 0),
      'is_system', coalesce(role_record.is_system, false),
      'membership_count', (
        select count(*)
        from public.institution_role_assignments assignment
        where assignment.role_id = role_record.id
          and assignment.status = 'active'
          and (assignment.expires_at is null or assignment.expires_at > now())
      ),
      'memberships', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', assignment.id,
          'person_name', person_record.display_name,
          'scope', case assignment.scope_kind
            when 'institution' then 'Instituição'
            when 'unit' then 'Unidade: ' || coalesce(unit_record.name, assignment.scope_unit_id::text)
            when 'group' then 'Turma: ' || coalesce(group_record.name, assignment.scope_group_id::text)
            else assignment.scope_kind
          end
        ) order by lower(person_record.display_name), assignment.id)
        from public.institution_role_assignments assignment
        join public.institution_memberships membership on membership.id = assignment.membership_id
        join public.people person_record on person_record.id = membership.person_id
        left join public.units unit_record on unit_record.id = assignment.scope_unit_id
        left join public.groups group_record on group_record.id = assignment.scope_group_id
        where assignment.role_id = role_record.id
          and assignment.status = 'active'
          and (assignment.expires_at is null or assignment.expires_at > now())
      ), '[]'::jsonb),
      'permissions', coalesce((
        select jsonb_agg(jsonb_build_object(
          'code', permission_record.code,
          'module', permission_record.module_code,
          'screen_code', coalesce(permission_record.screen_code, 'general'),
          'action_code', permission_record.action_code,
          'module_label', permission_record.module_label,
          'screen_label', permission_record.screen_label,
          'action_label', permission_record.action_label,
          'name', coalesce(permission_record.description, permission_record.action_label),
          'description', permission_record.description,
          'risk', permission_record.risk_level,
          'requires_mfa', permission_record.requires_mfa,
          'selected', grant_record.id is not null and grant_record.effect = 'allow',
          'grantable', actor_can_manage.allowed and coalesce(grant_record.effect, 'allow') <> 'deny',
          'inherited', false,
          'unavailable_reason', case
            when grant_record.effect = 'deny'
              then 'Uma negação explícita deve ser tratada separadamente.'
            when not actor_can_manage.allowed
              then 'Você não pode conceder permissões institucionais.'
            else null
          end
        ) order by permission_record.module_code, permission_record.screen_code,
          permission_record.action_code, permission_record.code)
        from public.institution_permissions permission_record
        cross join (
          select app_private.has_platform_permission('institution.roles.manage') as allowed
        ) actor_can_manage
        left join public.institution_role_permissions grant_record
          on grant_record.permission_id = permission_record.id
          and grant_record.role_id = role_record.id
          and grant_record.status = 'active'
          and grant_record.revoked_at is null
        where permission_record.status = 'active'
      ), '[]'::jsonb),
      'audit', case when can_read_audit then
        coalesce((
          select jsonb_agg(jsonb_build_object(
            'action', audit_record.action_code,
            'reason', audit_record.reason,
            'occurred_at', audit_record.occurred_at
          ) order by audit_record.occurred_at desc)
          from (
            select audit_row.action_code, audit_row.reason, audit_row.occurred_at
            from audit.audit_logs audit_row
            where audit_row.object_id = role_record.id
            order by audit_row.occurred_at desc
            limit 10
          ) audit_record
        ), '[]'::jsonb)
      else null end
    )
    into result
    from (
      select role_row.id, role_row.institution_id, role_row.code, role_row.name,
        role_row.description, role_row.status::text as status,
        role_row.max_scope_kind, role_row.version, role_row.is_system
      from public.institution_roles role_row
      where role_row.id = p_profile_id
      union all
      select null::uuid, null::uuid, '', '', '', 'active', 'institution', 0::bigint, false
      where p_profile_id is null
      limit 1
    ) role_record;

  else
    raise invalid_parameter_value using message = 'unsupported profile domain';
  end if;

  if result is null then
    raise no_data_found using message = 'access profile not found';
  end if;
  return result;
end
$$;


ALTER FUNCTION "app_private"."access_profile_detail_v3"("p_domain" "text", "p_profile_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."access_profile_detail_v3"("p_domain" "text", "p_profile_id" "uuid") IS 'Detalhe rico de perfil de acesso (platform/institution) para o formulario do Superadmin: rascunho em branco quando p_profile_id e nulo, matriz completa de permissoes com selected/grantable, vinculos ativos e auditoria quando o ator pode le-la. Autoriza por require_profile_authority.';



CREATE OR REPLACE FUNCTION "app_private"."access_profile_model_audit_success"("p_actor" "uuid", "p_domain" "text", "p_action" "text", "p_object_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context_record app_private.superadmin_internal_context;
  permission_code text:=p_domain||'.role_models.'||p_action;
begin
  select * into strict context_record
    from app_private.require_superadmin_internal_context(permission_code);
  if context_record.internal_identity_id is distinct from p_actor then
    raise insufficient_privilege using
      message='internal model actor changed',detail='SAI_PERMISSION_DENIED';
  end if;
  perform app_private.audit_append_superadmin_internal(
    context_record.internal_identity_id,context_record.internal_auth_link_id,
    context_record.internal_membership_id,context_record.session_id,
    permission_code,context_record.aal,
    'superadmin.access-profile-models.'||p_action,'success',
    'MODEL_'||upper(p_action),gen_random_uuid(),null,
    'access_profile_model',p_object_id);
end
$$;


ALTER FUNCTION "app_private"."access_profile_model_audit_success"("p_actor" "uuid", "p_domain" "text", "p_action" "text", "p_object_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_model_call"("p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;domain text;permission_action text;actor uuid;
  correlation uuid:=gen_random_uuid();error_code text;error_detail text;sql_state text;
  object_id uuid;
begin
  begin
    if p_operation in('list','detail','catalog') then
      perform app_private.access_profile_require_any_model_read();
    end if;
    domain:=case
      when p_operation in('list','create','export','import_preview','import_confirm')
        then coalesce(p_args->>'domain',p_args#>>'{draft,domain}')
      when p_operation='catalog' then 'platform'
      when p_operation in('detail','delete') then (
        select model.domain from public.access_profile_templates model
        where model.id=nullif(p_args->>'model_id','')::uuid)
      when p_operation='update' then (
        select model.domain from public.access_profile_templates model
        where model.id=nullif(p_args#>>'{draft,id}','')::uuid)
      when p_operation='duplicate' then (
        select model.domain from public.access_profile_templates model
        where model.id=nullif(p_args#>>'{draft,source_model_id}','')::uuid)
    end;
    permission_action:=case p_operation
      when 'list' then 'read' when 'detail' then 'read' when 'catalog' then 'read'
      when 'duplicate' then 'create' when 'import_preview' then 'import'
      when 'import_confirm' then 'import' else p_operation end;
    if p_operation='list' then
      result:=app_private.superadmin_access_profile_models_cursor(
        p_args->>'query',domain,p_args->>'status',p_args->>'scope',
        coalesce((p_args->>'limit')::integer,25),p_args->>'after_name',
        nullif(p_args->>'after_id','')::uuid);
    elsif p_operation='detail' then
      result:=app_private.access_profile_model_detail(
        nullif(p_args->>'model_id','')::uuid,true);
    elsif p_operation='create' then
      result:=app_private.superadmin_access_profile_model_create(
        nullif(p_args->>'request_id','')::uuid,p_args->'draft');
    elsif p_operation='update' then
      result:=app_private.superadmin_access_profile_model_update(
        nullif(p_args->>'request_id','')::uuid,p_args->'draft');
    elsif p_operation='delete' then
      result:=app_private.superadmin_access_profile_model_delete(
        nullif(p_args->>'request_id','')::uuid,
        nullif(p_args->>'model_id','')::uuid,(p_args->>'expected_version')::bigint,
        p_args->>'reason');
    elsif p_operation='duplicate' then
      result:=app_private.superadmin_access_profile_model_duplicate(
        nullif(p_args->>'request_id','')::uuid,p_args->'draft');
    elsif p_operation='export' then
      result:=app_private.superadmin_access_profile_models_export(domain);
    elsif p_operation='import_preview' then
      result:=app_private.superadmin_access_profile_models_import_preview(
        domain,p_args->'rows');
    elsif p_operation='import_confirm' then
      result:=app_private.superadmin_access_profile_models_import_confirm(
        nullif(p_args->>'request_id','')::uuid,domain,p_args->'rows',p_args->>'reason');
    elsif p_operation='catalog' then
      result:=app_private.superadmin_access_permission_catalog();
    else
      raise invalid_parameter_value using message='unsupported model operation';
    end if;
    if p_operation in('list','detail','catalog','import_preview') then
      actor:=app_private.access_profile_require_model_action(
        coalesce(domain,'platform'),permission_action,false);
      object_id:=case when p_operation='detail'
        then nullif(p_args->>'model_id','')::uuid else null end;
      perform app_private.access_profile_model_audit_success(
        actor,coalesce(domain,'platform'),permission_action,object_id);
    end if;
  exception when others then
    get stacked diagnostics error_detail=pg_exception_detail,sql_state=returned_sqlstate;
    error_code:=case
      when error_detail in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID',
        'SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
        'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED')
        then error_detail
      when sql_state='40001' then 'SAI_CONCURRENT_CHANGE'
      when sql_state in('22023','22P02','23514','23505','22001')
        then 'SAI_INVALID_ARGUMENT'
      when sql_state in('P0002','42501') then 'SAI_PERMISSION_DENIED'
      else 'SAI_INTERNAL_ERROR' end;
    perform app_private.audit_superadmin_internal_denial_if_identified(
      coalesce(case when domain in('platform','institution','principal')
        then domain else 'platform' end||'.role_models.'||
        coalesce(permission_action,'read'),'platform.role_models.read'),
      'superadmin.access-profile-models.'||coalesce(p_operation,'invalid'),
      error_code,correlation,null);
    return app_private.access_profile_model_error_envelope(error_code,correlation);
  end;
  return pg_catalog.jsonb_build_object('ok',true,'data',result,'error',null);
end
$$;


ALTER FUNCTION "app_private"."access_profile_model_call"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_model_create_internal"("p_actor" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  model_id uuid;
  domain text:=p_draft->>'domain';
  generated_code text;
  base_code text;
  capability_item jsonb;
  capabilities jsonb:=coalesce(p_draft->'capabilities','[]'::jsonb);
  scope_kind text:=p_draft->>'max_scope_kind';
begin
  if domain not in ('platform','institution','principal')
    or octet_length(pg_catalog.convert_to(p_draft::text,'UTF8'))>65536
    or char_length(btrim(coalesce(p_draft->>'name',''))) not between 2 and 120
    or coalesce(nullif(p_draft->>'status',''),'active') not in ('active','inactive')
    or jsonb_typeof(capabilities)<>'array'
    or jsonb_array_length(capabilities)>500 then
    raise invalid_parameter_value using message='invalid access model draft';
  end if;
  scope_kind:=coalesce(nullif(scope_kind,''),case domain
    when 'platform' then 'platform'
    when 'institution' then 'institution'
    else 'child_context' end);
  if (domain='platform' and scope_kind not in ('platform','institution'))
    or (domain='institution' and scope_kind not in ('institution','unit','group'))
    or (domain='principal' and scope_kind<>'child_context') then
    raise invalid_parameter_value using message='invalid access model scope';
  end if;
  if jsonb_array_length(capabilities)<>(
    select count(distinct item.value->>'code')
    from jsonb_array_elements(capabilities) item
  ) then
    raise invalid_parameter_value using message='duplicate access model capability';
  end if;
  for capability_item in select value from jsonb_array_elements(capabilities) loop
    if capability_item->>'effect' not in ('allow','deny') then
      raise invalid_parameter_value using message='invalid access model capability effect';
    end if;
    if domain='platform' and not exists(
      select 1 from public.platform_permissions permission_record
      where permission_record.code=capability_item->>'code' and permission_record.status='active'
    ) then
      raise invalid_parameter_value using message='unknown access model capability';
    elsif domain='institution' and not exists(
      select 1 from public.institution_permissions permission_record
      where permission_record.code=capability_item->>'code' and permission_record.status='active'
    ) then
      raise invalid_parameter_value using message='unknown access model capability';
    elsif domain='principal' and not exists(
      select 1 from public.guardian_permission_capabilities capability
      where capability.code=capability_item->>'code' and capability.status='active'
    ) then
      raise invalid_parameter_value using message='unknown access model capability';
    end if;
    if capability_item->>'effect'='allow'
      and not app_private.access_profile_model_internal_can_delegate(
        p_actor,domain,capability_item->>'code') then
      raise insufficient_privilege using message='cannot delegate capability operator does not hold';
    end if;
  end loop;
  base_code:=trim(both '-' from regexp_replace(
    lower(btrim(p_draft->>'name')),'[^a-z0-9]+','-','g'
  ));
  if char_length(base_code)<3 then base_code:='model'; end if;
  generated_code:=base_code||'-'||left(replace(gen_random_uuid()::text,'-',''),8);
  insert into public.access_profile_templates(
    domain,code,name,description,max_scope_kind,is_system,status,
    created_by_internal_identity_id
  ) values(
    domain,generated_code,btrim(p_draft->>'name'),
    nullif(btrim(p_draft->>'description'),''),scope_kind,false,
    coalesce(nullif(p_draft->>'status',''),'active')::public.record_status,p_actor
  ) returning id into model_id;
  if domain='platform' then
    insert into public.access_profile_template_platform_permissions(
      template_id,permission_id,effect
    )
    select model_id,permission_record.id,
      (item.value->>'effect')::public.permission_effect
    from jsonb_array_elements(capabilities) item
    join public.platform_permissions permission_record
      on permission_record.code=item.value->>'code';
  elsif domain='institution' then
    insert into public.access_profile_template_institution_permissions(
      template_id,permission_id,effect
    )
    select model_id,permission_record.id,
      (item.value->>'effect')::public.permission_effect
    from jsonb_array_elements(capabilities) item
    join public.institution_permissions permission_record
      on permission_record.code=item.value->>'code';
  else
    insert into public.access_profile_template_principal_capabilities(
      template_id,capability_id,effect
    )
    select model_id,capability.id,
      (item.value->>'effect')::public.permission_effect
    from jsonb_array_elements(capabilities) item
    join public.guardian_permission_capabilities capability
      on capability.code=item.value->>'code';
  end if;
  return app_private.access_profile_model_detail(model_id,false);
end
$$;


ALTER FUNCTION "app_private"."access_profile_model_create_internal"("p_actor" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_model_detail"("p_model_id" "uuid", "p_authorize" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  model_record public.access_profile_templates%rowtype;
  capabilities jsonb;
begin
  if p_authorize then
    perform app_private.access_profile_require_any_model_read();
  end if;
  select * into model_record
  from public.access_profile_templates model
  where model.id=p_model_id;
  if model_record.id is null then
    raise no_data_found using message='access profile model not found';
  end if;
  if p_authorize then
    perform app_private.access_profile_require_model_action(model_record.domain,'read',false);
  end if;
  if model_record.domain='platform' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'code',permission_record.code,'effect',model_permission.effect::text
    ) order by permission_record.code),'[]'::jsonb)
    into capabilities
    from public.access_profile_template_platform_permissions model_permission
    join public.platform_permissions permission_record
      on permission_record.id=model_permission.permission_id
    where model_permission.template_id=model_record.id;
  elsif model_record.domain='institution' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'code',permission_record.code,'effect',model_permission.effect::text
    ) order by permission_record.code),'[]'::jsonb)
    into capabilities
    from public.access_profile_template_institution_permissions model_permission
    join public.institution_permissions permission_record
      on permission_record.id=model_permission.permission_id
    where model_permission.template_id=model_record.id;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'code',capability.code,'effect',model_capability.effect::text
    ) order by capability.code),'[]'::jsonb)
    into capabilities
    from public.access_profile_template_principal_capabilities model_capability
    join public.guardian_permission_capabilities capability
      on capability.id=model_capability.capability_id
    where model_capability.template_id=model_record.id;
  end if;
  return to_jsonb(model_record)||jsonb_build_object(
    'application_code',case model_record.domain
      when 'platform' then 'superadmin'
      when 'institution' then 'admin'
      else 'principal' end,
    'capabilities',capabilities,
    'capability_count',jsonb_array_length(capabilities)
  );
end
$$;


ALTER FUNCTION "app_private"."access_profile_model_detail"("p_model_id" "uuid", "p_authorize" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_model_error_envelope"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select pg_catalog.jsonb_build_object('ok',false,'data',null,'error',
    pg_catalog.jsonb_build_object(
      'code',case when p_code in(
        'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
        'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED',
        'SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED','SAI_INVALID_ARGUMENT',
        'SAI_CONCURRENT_CHANGE') then p_code else 'SAI_INTERNAL_ERROR' end,
      'message',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 'Autenticação necessária.'
        when p_code='SAI_MFA_REQUIRED' then 'Confirme o segundo fator.'
        when p_code='SAI_INVALID_ARGUMENT' then 'Revise os dados informados.'
        when p_code='SAI_CONCURRENT_CHANGE' then 'O estado mudou. Recarregue e tente novamente.'
        when p_code in('SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
          'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED') then 'Acesso não autorizado.'
        else 'Não foi possível concluir a operação.' end,
      'correlation_id',p_correlation_id,
      'http_status',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 401
        when p_code='SAI_INVALID_ARGUMENT' then 400
        when p_code='SAI_CONCURRENT_CHANGE' then 409
        when p_code in('SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
          'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED') then 403
        else 500 end))
$$;


ALTER FUNCTION "app_private"."access_profile_model_error_envelope"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_model_internal_can_delegate"("p_actor" "uuid", "p_domain" "text", "p_capability_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists(
    select 1
    from app_private.superadmin_internal_memberships membership_record
    join public.platform_roles role_record
      on role_record.id=membership_record.platform_role_id
     and role_record.status='active'
    where membership_record.internal_identity_id=p_actor
      and membership_record.status='active'
      and membership_record.scope_kind='platform'
      and role_record.code='owner'
      and (
        p_domain in('institution','principal')
        or exists(
          select 1 from public.platform_role_permissions role_permission
          join public.platform_permissions permission_record
            on permission_record.id=role_permission.permission_id
           and permission_record.status='active'
          where role_permission.role_id=role_record.id
            and permission_record.code=p_capability_code
            and role_permission.effect='allow'
            and role_permission.status='active'
            and role_permission.revoked_at is null)))
$$;


ALTER FUNCTION "app_private"."access_profile_model_internal_can_delegate"("p_actor" "uuid", "p_domain" "text", "p_capability_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_model_replay_internal"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare receipt app_private.access_profile_model_command_receipts%rowtype;
  wanted_hash bytea;
begin
  if p_request_id is null then
    raise invalid_parameter_value using message='request id required';
  end if;
  wanted_hash:=extensions.digest(pg_catalog.convert_to(p_payload::text,'UTF8'),'sha256');
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('coelo.access-profile-model:'||p_request_id::text,0));
  select * into receipt from app_private.access_profile_model_command_receipts
    where request_id=p_request_id for update;
  if receipt.request_id is null then return null; end if;
  if receipt.actor_internal_identity_id is distinct from p_actor then
    raise insufficient_privilege using
      message='idempotency receipt actor mismatch',detail='SAI_PERMISSION_DENIED';
  end if;
  if receipt.command_kind<>p_command or receipt.request_hash<>wanted_hash then
    raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return receipt.result_json||pg_catalog.jsonb_build_object('replayed',true);
end
$$;


