CREATE OR REPLACE FUNCTION "app_private"."access_profile_replay"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
