CREATE OR REPLACE FUNCTION "app_private"."access_profile_require_any_model_read"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  read_domain text;
  denial_detail text;
begin
  foreach read_domain in array array['platform','institution','principal']::text[] loop
    begin
      perform app_private.access_profile_require_model_action(read_domain,'read',false);
      return;
    exception when insufficient_privilege then
      get stacked diagnostics denial_detail=pg_exception_detail;
      if denial_detail is distinct from 'SAI_PERMISSION_DENIED' then
        raise;
      end if;
    end;
  end loop;
  raise insufficient_privilege using
    message='access model read permission required',detail='SAI_PERMISSION_DENIED';
end
$$;


ALTER FUNCTION "app_private"."access_profile_require_any_model_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_require_model_action"("p_domain" "text", "p_action" "text", "p_require_mfa" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  context_record app_private.superadmin_internal_context;
  permission_code text;
begin
  if p_domain not in ('platform','institution','principal')
    or p_action not in ('read','create','update','delete','import','export') then
    raise invalid_parameter_value using message='unsupported access model action';
  end if;
  permission_code:=p_domain||'.role_models.'||p_action;
  select * into strict context_record
  from app_private.require_superadmin_internal_context(permission_code);
  if context_record.scope_kind<>'platform'
    or context_record.platform_role_code<>'owner' then
    raise insufficient_privilege using
      message='access model permission required',detail='SAI_PERMISSION_DENIED';
  end if;
  return context_record.internal_identity_id;
end
$$;


ALTER FUNCTION "app_private"."access_profile_require_model_action"("p_domain" "text", "p_action" "text", "p_require_mfa" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_require_mutation"("target_domain" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id(); required_permission text;
begin
  required_permission:=case target_domain when 'platform' then 'platform.roles.manage'
    when 'institution' then 'institution.roles.manage'
    when 'principal' then 'institution.roles.manage' end;
  if actor is null or required_permission is null or not app_private.has_platform_permission(required_permission) then
    raise insufficient_privilege using message='profile management permission required';
  end if;
  if not app_private.has_mfa_aal2() then raise insufficient_privilege using message='MFA AAL2 required'; end if;
  return actor;
end $$;


