CREATE OR REPLACE FUNCTION "app_private"."account_profile_projection"("p_person_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; email_value text; pending jsonb; role_value text; avatar_asset public.person_avatar_assets%rowtype;
begin
  select u.email into email_value from auth.users u join public.person_auth_links link on link.auth_user_id = u.id
    where link.person_id = p_person_id and link.status = 'active' order by link.linked_at desc limit 1;
  if email_value is null and p_person_id = app_private.current_person_id() then
    select u.email into email_value from auth.users u where u.id = auth.uid();
  end if;
  select jsonb_build_object('requested_email', request.requested_email, 'status', request.status,
    'requested_at', request.requested_at) into pending from public.account_email_change_requests request
    where request.person_id = p_person_id and request.status = 'pending' order by request.requested_at desc limit 1;
  select coalesce(role.name, role.code, 'Acesso interno') into role_value from public.platform_memberships membership
    join public.platform_roles role on role.id = membership.role_id
    where membership.person_id = p_person_id and membership.status = 'active' order by membership.created_at limit 1;
  select * into avatar_asset from public.person_avatar_assets where person_id = p_person_id
    and storage_provider = 'r2' and status = 'active' and revoked_at is null order by activated_at desc limit 1;
  select jsonb_build_object('avatar_contract_version', 3, 'first_name', person.first_name, 'last_name', person.last_name,
    'email', coalesce(email_value, ''), 'mobile_phone', coalesce(person.mobile_phone, ''),
    'avatar', jsonb_build_object('mode', case when avatar_asset.id is null then 'initials' else 'photo' end,
      'asset_id', avatar_asset.id, 'initials', coalesce(person.account_avatar_initials,
        left(upper(coalesce(nullif(left(trim(person.first_name), 1), ''), '') || coalesce(nullif(left(trim(person.last_name), 1), ''), '')), 2)),
      'background_color', coalesce(person.account_avatar_background_color, '#FFF1EB')),
    'access', jsonb_build_object('role', coalesce(role_value, 'Acesso interno'),
      'mfa_enabled', coalesce((select auth.jwt()->>'aal') = 'aal2', false),
      'capabilities', coalesce((select jsonb_agg(distinct permission.description) from public.platform_permissions permission
        where permission.status='active' and exists (select 1 from public.platform_memberships membership
          where membership.person_id=p_person_id and membership.status='active' and membership.revoked_at is null
            and app_private.has_platform_permission(permission.code,membership.scope_institution_id))), '[]'::jsonb),
      'capability_details', coalesce((select jsonb_agg(item order by item->>'module_label',item->>'scope_label',item->>'label') from (
        select distinct jsonb_build_object('code',permission.code,'label',permission.description,'module_code',permission.module_code,
          'module_label',permission.module_label,'scope_kind',membership.scope_kind,'scope_id',membership.scope_institution_id,
          'scope_label',case when membership.scope_kind='platform' then 'Plataforma' else institution.public_name end) item
        from public.platform_memberships membership join public.platform_roles role on role.id=membership.role_id and role.status='active'
          cross join public.platform_permissions permission left join public.institutions institution on institution.id=membership.scope_institution_id
        where membership.person_id=p_person_id and membership.status='active' and membership.revoked_at is null
          and permission.status='active' and app_private.has_platform_permission(permission.code,membership.scope_institution_id)) items), '[]'::jsonb)),
    'email_change', pending) into result from public.people person where person.id = p_person_id and person.deleted_at is null;
  if result is null then raise exception using errcode = 'P0002', message = 'account_profile_not_found'; end if;
  return result;
end
$$;


ALTER FUNCTION "app_private"."account_profile_projection"("p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."activity_location_authorize_v2"("p_permissions" "text"[], "p_expected" "app_private"."superadmin_internal_context" DEFAULT NULL::"app_private"."superadmin_internal_context") RETURNS "app_private"."superadmin_internal_context"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; fresh app_private.superadmin_internal_context; permission text;
begin
 if coalesce(cardinality(p_permissions),0)=0 then raise invalid_parameter_value; end if;
 select * into strict ctx from app_private.require_superadmin_internal_context(p_permissions[1]);
 foreach permission in array p_permissions loop
   select * into strict fresh from app_private.require_superadmin_internal_context(permission);
   if row(fresh.internal_identity_id,fresh.internal_auth_link_id,fresh.internal_membership_id,
     fresh.auth_user_id,fresh.session_id,fresh.platform_role_id,fresh.scope_kind,fresh.scope_institution_id,fresh.aal)
     is distinct from row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
     ctx.auth_user_id,ctx.session_id,ctx.platform_role_id,ctx.scope_kind,ctx.scope_institution_id,ctx.aal) then
     raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
   end if;
 end loop;
 if p_expected.internal_identity_id is not null and ctx is distinct from p_expected then
   raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
 end if;
 if not exists(select 1 from auth.sessions s where s.id=ctx.session_id and s.user_id=ctx.auth_user_id
   and (s.not_after is null or s.not_after>clock_timestamp())) then
   raise insufficient_privilege using detail='SAI_SESSION_INVALID';
 end if;
 return ctx;
end $$;


ALTER FUNCTION "app_private"."activity_location_authorize_v2"("p_permissions" "text"[], "p_expected" "app_private"."superadmin_internal_context") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."activity_management_payload"("p_activity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select to_jsonb(activity)||jsonb_build_object(
  'institution_name',institution.public_name,
  'active_unit_count',(select count(*) from public.activity_unit_links link
    where link.activity_id=activity.id and link.status='active'),
  'active_group_count',(select count(*) from public.activity_group_links link
    where link.activity_id=activity.id and link.status='active'),
  'active_professional_count',(select count(distinct assignment.person_id)
    from public.activity_group_assignments assignment
    join public.activity_group_links link on link.id=assignment.activity_group_link_id
    where link.activity_id=activity.id and link.status='active'
     and assignment.status='active' and assignment.revoked_at is null),
  'active_participant_count',(select count(*)
    from public.activity_group_participants participant
    join public.activity_group_links link on link.id=participant.activity_group_link_id
    where link.activity_id=activity.id and link.status='active'
     and participant.status='active' and participant.removed_at is null),
  'location_names','[]'::jsonb,
  'linked_units',coalesce((select jsonb_agg(jsonb_build_object(
    'id',unit.id,'name',unit.name,'institution_id',unit.institution_id)
    order by unit.name)
    from public.activity_unit_links link join public.units unit on unit.id=link.unit_id
    where link.activity_id=activity.id and link.status='active'),'[]'::jsonb),
  'linked_groups',coalesce((select jsonb_agg(jsonb_build_object(
    'id',group_record.id,'name',group_record.name,'unit_id',group_record.unit_id,
    'unit_name',unit.name) order by unit.name,group_record.name)
    from public.activity_group_links link
    join public.groups group_record on group_record.id=link.group_id
    join public.units unit on unit.id=group_record.unit_id
    where link.activity_id=activity.id and link.status='active'),'[]'::jsonb),
  'activity_unit_links',coalesce((select jsonb_agg(
    to_jsonb(link)||jsonb_build_object('units',
      jsonb_build_object('id',unit.id,'name',unit.name,'institution_id',unit.institution_id))
    order by unit.name)
    from public.activity_unit_links link join public.units unit on unit.id=link.unit_id
    where link.activity_id=activity.id),'[]'::jsonb),
  'activity_group_links',coalesce((select jsonb_agg(
    to_jsonb(link)||jsonb_build_object(
      'groups',jsonb_build_object('id',group_record.id,'name',group_record.name),
      'units',jsonb_build_object('id',unit.id,'name',unit.name),
      'activity_group_assignments',coalesce((select jsonb_agg(to_jsonb(assignment))
        from public.activity_group_assignments assignment
        where assignment.activity_group_link_id=link.id),'[]'::jsonb),
      'activity_group_participants',coalesce((select jsonb_agg(to_jsonb(participant))
        from public.activity_group_participants participant
        where participant.activity_group_link_id=link.id),'[]'::jsonb))
    order by unit.name,group_record.name)
    from public.activity_group_links link
    join public.groups group_record on group_record.id=link.group_id
    join public.units unit on unit.id=group_record.unit_id
    where link.activity_id=activity.id),'[]'::jsonb),
  'unit_ids',coalesce((select jsonb_agg(link.unit_id order by link.unit_id)
    from public.activity_unit_links link
    where link.activity_id=activity.id and link.status='active'),'[]'::jsonb),
  'group_ids',coalesce((select jsonb_agg(link.group_id order by link.group_id)
    from public.activity_group_links link
    where link.activity_id=activity.id and link.status='active'),'[]'::jsonb),
  'locations','[]'::jsonb
 ) from public.activity_definitions activity
 join public.institutions institution on institution.id=activity.institution_id
 where activity.id=p_activity_id
$$;


