CREATE OR REPLACE FUNCTION "app_private"."activity_v2_validate_participants"("p_institution_id" "uuid", "p_participants" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select case when jsonb_typeof(p_participants) is distinct from 'array' then false else
 jsonb_array_length(p_participants)<=1000
 and not exists(select 1 from jsonb_array_elements(p_participants) item
  where jsonb_typeof(item)<>'object' or not(item ?& array['group_id','child_group_link_id','belongs']) or item-array['group_id','child_group_link_id','belongs']<>'{}'::jsonb
   or jsonb_typeof(item->'group_id')<>'string' or jsonb_typeof(item->'child_group_link_id')<>'string'
   or jsonb_typeof(item->'belongs')<>'boolean'
   or case when jsonb_typeof(item->'belongs')='boolean' and (item->>'belongs')::boolean then
    not exists(select 1 from public.child_group_links cgl
     join public.child_unit_links cul on cul.id=cgl.child_unit_link_id and cul.status='active'
     join public.child_contexts cc on cc.id=cul.child_context_id and cc.status='active'
     join public.groups g on g.id=cgl.group_id and g.unit_id=cul.unit_id and g.institution_id=p_institution_id
     where cgl.id=app_private.activity_v2_safe_uuid(item->>'child_group_link_id') and cgl.group_id=app_private.activity_v2_safe_uuid(item->>'group_id') and cgl.status='active'
       and cc.institution_id=p_institution_id) else false end)
 and (select count(*)=count(distinct (item->>'group_id',item->>'child_group_link_id')) from jsonb_array_elements(p_participants) item) end
$$;


ALTER FUNCTION "app_private"."activity_v2_validate_participants"("p_institution_id" "uuid", "p_participants" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."activity_v2_validate_professionals"("p_institution_id" "uuid", "p_professionals" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select case when jsonb_typeof(p_professionals) is distinct from 'array' then false else
 jsonb_array_length(p_professionals)<=500
 and not exists(select 1 from jsonb_array_elements(p_professionals) item
  where jsonb_typeof(item)<>'object' or not(item ?& array['membership_id','role','group_id']) or item-array['membership_id','role','group_id']<>'{}'::jsonb
   or jsonb_typeof(item->'membership_id')<>'string' or jsonb_typeof(item->'role')<>'string'
   or item->>'role' not in('instructor','activity_admin')
   or (item->>'role'='instructor' and nullif(item->>'group_id','') is null)
   or (item->>'role'='instructor' and app_private.activity_v2_safe_uuid(item->>'group_id') is null)
   or (item->>'role'='activity_admin' and item->'group_id'<>'null'::jsonb)
   or not exists(select 1 from public.institution_memberships m join public.people p on p.id=m.person_id
    where m.id=app_private.activity_v2_safe_uuid(item->>'membership_id') and m.institution_id=p_institution_id
      and m.status='active' and m.revoked_at is null and p.person_type='adult' and p.status='active'))
 and (select count(*)=count(distinct (item->>'membership_id',item->>'role',coalesce(item->>'group_id',''))) from jsonb_array_elements(p_professionals) item) end
$$;


ALTER FUNCTION "app_private"."activity_v2_validate_professionals"("p_institution_id" "uuid", "p_professionals" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."agenda_actor_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    app_private.current_person_id(),
    (select auth_link.internal_identity_id
     from app_private.superadmin_internal_auth_links auth_link
     where auth_link.auth_user_id = (select auth.uid())
       and auth_link.status = 'active'
     order by auth_link.created_at desc limit 1))
$$;


ALTER FUNCTION "app_private"."agenda_actor_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."agenda_has_permission"("p_permission_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- Identidade interna primeiro: com vinculo interno ativo, so a membership interna
  -- de PLATAFORMA decide (a platform_membership espelhada pelas pontes de ator
  -- concederia agenda.* a identidades escopadas em instituicao).
  select case when exists (
      select 1 from app_private.superadmin_internal_auth_links auth_link
      where auth_link.auth_user_id = (select auth.uid()) and auth_link.status = 'active')
    then false else app_private.has_platform_permission(p_permission_code) end
  or (
    exists (
      select 1
      from app_private.superadmin_internal_auth_links auth_link
      join app_private.superadmin_internal_memberships membership
        on membership.internal_identity_id = auth_link.internal_identity_id
       and membership.status = 'active'
       and membership.scope_kind::text = 'platform'
      join public.platform_roles role_record
        on role_record.id = membership.platform_role_id and role_record.status = 'active'
      join public.platform_role_permissions grant_record
        on grant_record.role_id = role_record.id
       and grant_record.status = 'active' and grant_record.revoked_at is null
       and grant_record.effect = 'allow'
      join public.platform_permissions permission_record
        on permission_record.id = grant_record.permission_id
       and permission_record.code = p_permission_code and permission_record.status = 'active'
      where auth_link.auth_user_id = (select auth.uid()) and auth_link.status = 'active'
    )
    and not exists (
      select 1
      from app_private.superadmin_internal_auth_links auth_link
      join app_private.superadmin_internal_memberships membership
        on membership.internal_identity_id = auth_link.internal_identity_id
       and membership.status = 'active'
      join public.platform_role_permissions grant_record
        on grant_record.role_id = membership.platform_role_id
       and grant_record.status = 'active' and grant_record.revoked_at is null
       and grant_record.effect = 'deny'
      join public.platform_permissions permission_record
        on permission_record.id = grant_record.permission_id
       and permission_record.code = p_permission_code
      where auth_link.auth_user_id = (select auth.uid()) and auth_link.status = 'active'
    )
  )
$$;


ALTER FUNCTION "app_private"."agenda_has_permission"("p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."agenda_route_internal_actor"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare row_json jsonb := to_jsonb(new); base text; actor uuid;
begin
  foreach base in array tg_argv loop
    actor := (row_json ->> (base || '_person_id'))::uuid;
    if actor is not null and exists (
      select 1 from app_private.superadmin_internal_identities identity_record
      where identity_record.id = actor
    ) then
      row_json := row_json || jsonb_build_object(
        base || '_person_id', null, base || '_internal_identity_id', actor);
    elsif actor is not null then
      row_json := row_json || jsonb_build_object(base || '_internal_identity_id', null);
    end if;
  end loop;
  new := jsonb_populate_record(new, row_json);
  return new;
end
$$;


ALTER FUNCTION "app_private"."agenda_route_internal_actor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."apply_institution_management_children"("p_institution_id" "uuid", "p_actor_person_id" "uuid", "p_payload" "jsonb", "p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  merged jsonb;
  email_value text;
  phone_value text;
  mobile_value text;
  website_value text;
  whatsapp_value text;
begin
  if p_payload ? 'address' then
    select coalesce(to_jsonb(address_record), '{}'::jsonb)
      || (p_payload -> 'address') into merged
    from (select 1) seed
    left join public.institution_addresses address_record
      on address_record.institution_id = p_institution_id;
    insert into public.institution_addresses(
      institution_id, country, state, city, district, street, number,
      complement, postal_code, status, updated_at
    ) values (
      p_institution_id, coalesce(nullif(btrim(merged ->> 'country'), ''), 'BR'),
      nullif(btrim(merged ->> 'state'), ''),
      nullif(btrim(merged ->> 'city'), ''),
      nullif(btrim(merged ->> 'district'), ''),
      nullif(btrim(merged ->> 'street'), ''),
      nullif(btrim(merged ->> 'number'), ''),
      nullif(btrim(merged ->> 'complement'), ''),
      nullif(btrim(merged ->> 'postal_code'), ''), 'active', clock_timestamp()
    ) on conflict (institution_id) do update set
      country = excluded.country, state = excluded.state, city = excluded.city,
      district = excluded.district, street = excluded.street,
      number = excluded.number, complement = excluded.complement,
      postal_code = excluded.postal_code, status = 'active',
      updated_at = excluded.updated_at;
  end if;

  if p_payload ? 'contact' then
    select coalesce(to_jsonb(contact_record), '{}'::jsonb)
      || (p_payload -> 'contact') into merged
    from (select 1) seed
    left join public.institution_contacts contact_record
      on contact_record.institution_id = p_institution_id;
    email_value := nullif(btrim(merged ->> 'email'), '');
    phone_value := nullif(btrim(merged ->> 'phone'), '');
    mobile_value := nullif(btrim(merged ->> 'mobile_phone'), '');
    website_value := nullif(btrim(merged ->> 'website_url'), '');
    whatsapp_value := nullif(btrim(merged ->> 'whatsapp_number'), '');
    if num_nonnulls(
      email_value, phone_value, mobile_value, website_value, whatsapp_value
    ) = 0 then
      delete from public.institution_contacts
      where institution_id = p_institution_id;
    else
      insert into public.institution_contacts(
        institution_id, email, phone, mobile_phone, website_url,
        whatsapp_number, status, updated_at
      ) values (
        p_institution_id, email_value, phone_value, mobile_value,
        website_value, whatsapp_value, 'active', clock_timestamp()
      ) on conflict (institution_id) do update set
        email = excluded.email, phone = excluded.phone,
        mobile_phone = excluded.mobile_phone,
        website_url = excluded.website_url,
        whatsapp_number = excluded.whatsapp_number,
        status = 'active', updated_at = excluded.updated_at;
    end if;
  end if;

  if p_payload ? 'branding' then
    select coalesce(to_jsonb(branding_record), '{}'::jsonb)
      || (p_payload -> 'branding') into merged
    from (select 1) seed
    left join public.institution_branding branding_record
      on branding_record.institution_id = p_institution_id;
    insert into public.institution_branding(
      institution_id, display_name, logo_media_asset_id, cover_media_asset_id,
      accent_color, secondary_color, tertiary_color, text_color,
      secondary_text_color, tertiary_text_color, surface_color,
      approval_status, profile_bio, profile_links, updated_by, updated_at
    ) values (
      p_institution_id, nullif(btrim(merged ->> 'display_name'), ''),
      nullif(merged ->> 'logo_media_asset_id', '')::uuid,
      nullif(merged ->> 'cover_media_asset_id', '')::uuid,
      nullif(btrim(merged ->> 'accent_color'), ''),
      nullif(btrim(merged ->> 'secondary_color'), ''),
      nullif(btrim(merged ->> 'tertiary_color'), ''),
      nullif(btrim(merged ->> 'text_color'), ''),
      nullif(btrim(merged ->> 'secondary_text_color'), ''),
      nullif(btrim(merged ->> 'tertiary_text_color'), ''),
      nullif(btrim(merged ->> 'surface_color'), ''),
      coalesce(nullif(btrim(merged ->> 'approval_status'), ''), 'draft'),
      nullif(merged ->> 'profile_bio', ''),
      coalesce(merged -> 'profile_links', '[]'::jsonb),
      p_actor_person_id, clock_timestamp()
    ) on conflict (institution_id) do update set
      display_name = excluded.display_name,
      logo_media_asset_id = excluded.logo_media_asset_id,
      cover_media_asset_id = excluded.cover_media_asset_id,
      accent_color = excluded.accent_color,
      secondary_color = excluded.secondary_color,
      tertiary_color = excluded.tertiary_color,
      text_color = excluded.text_color,
      secondary_text_color = excluded.secondary_text_color,
      tertiary_text_color = excluded.tertiary_text_color,
      surface_color = excluded.surface_color,
      approval_status = excluded.approval_status,
      profile_bio = excluded.profile_bio,
      profile_links = excluded.profile_links,
      updated_by = excluded.updated_by,
      updated_at = excluded.updated_at;
  end if;

  if p_payload ? 'subscription' then
    insert into public.institution_subscriptions(
      institution_id, plan_id, status, starts_at, trial_ends_at,
      manual_reason, changed_by, paused_at, cancelled_at
    ) values (
      p_institution_id, p_plan_id,
      coalesce(p_payload -> 'subscription' ->> 'status', 'draft')
        ::public.subscription_status,
      nullif(p_payload -> 'subscription' ->> 'starts_at', '')::timestamptz,
      nullif(p_payload -> 'subscription' ->> 'trial_ends_at', '')::timestamptz,
      nullif(btrim(p_payload -> 'subscription' ->> 'manual_reason'), ''),
      p_actor_person_id,
      nullif(p_payload -> 'subscription' ->> 'paused_at', '')::timestamptz,
      nullif(p_payload -> 'subscription' ->> 'cancelled_at', '')::timestamptz
    );
  end if;
end;
$$;


