CREATE OR REPLACE FUNCTION "app_private"."assert_access_profile_assignment_delegable"("p_domain" "text", "p_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare missing_code text;
begin
  if p_domain='platform' then
    select permission_record.code into missing_code
    from public.platform_role_permissions grant_record
    join public.platform_permissions permission_record on permission_record.id=grant_record.permission_id
    where grant_record.role_id=p_profile_id and grant_record.effect='allow'
      and grant_record.status='active' and grant_record.revoked_at is null
      and not app_private.has_platform_permission(permission_record.code) limit 1;
  elsif p_domain='institution' then
    select permission_record.code into missing_code
    from public.institution_role_permissions grant_record
    join public.institution_permissions permission_record on permission_record.id=grant_record.permission_id
    where grant_record.role_id=p_profile_id and grant_record.effect='allow'
      and grant_record.status='active' and grant_record.revoked_at is null
      and not app_private.access_profile_can_delegate_institution(permission_record.id) limit 1;
  elsif p_domain='principal' then
    perform app_private.assert_access_profile_template_delegable(p_profile_id,'principal');
    return;
  else
    raise invalid_parameter_value using message='unsupported profile domain';
  end if;
  if missing_code is not null then
    raise insufficient_privilege using message='cannot delegate capability operator does not hold';
  end if;
end $$;


ALTER FUNCTION "app_private"."assert_access_profile_assignment_delegable"("p_domain" "text", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_access_profile_template_delegable"("p_template_id" "uuid", "p_domain" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare missing_code text;
begin
  if p_domain='platform' then
    select permission_record.code into missing_code
    from public.access_profile_template_platform_permissions item
    join public.platform_permissions permission_record on permission_record.id=item.permission_id
    where item.template_id=p_template_id and item.effect='allow'
      and not app_private.has_platform_permission(permission_record.code) limit 1;
  elsif p_domain='institution' then
    select permission_record.code into missing_code
    from public.access_profile_template_institution_permissions item
    join public.institution_permissions permission_record on permission_record.id=item.permission_id
    where item.template_id=p_template_id and item.effect='allow'
      and not app_private.access_profile_can_delegate_institution(permission_record.id) limit 1;
  elsif p_domain='principal' then
    select capability.code into missing_code
    from public.access_profile_template_principal_capabilities item
    join public.guardian_permission_capabilities capability on capability.id=item.capability_id
    where item.template_id=p_template_id and item.effect='allow'
      and not app_private.access_profile_can_delegate_principal(capability.id) limit 1;
  else
    raise invalid_parameter_value using message='unsupported profile domain';
  end if;
  if missing_code is not null then
    raise insufficient_privilege using message='cannot delegate capability operator does not hold';
  end if;
end $$;


ALTER FUNCTION "app_private"."assert_access_profile_template_delegable"("p_template_id" "uuid", "p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_account_actor"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception using errcode = '28000', message = 'authentication_required';
  end if;
  actor_id := app_private.current_person_id();
  if actor_id is null then
    raise exception using errcode = '42501', message = 'internal_actor_required';
  end if;
  if not app_private.has_platform_permission('platform.read') then
    raise exception using errcode = '42501', message = 'permission_denied';
  end if;
  return actor_id;
end;
$$;


