    if lower(v_question->>'title') ~ '(cpf|rg|diagn[oó]stico|medica[cç][aã]o|senha|biometria|cart[aã]o|conta banc[aá]ria)' then raise exception using errcode='22023',message='sensitive_question_not_allowed'; end if;
  end loop;
end; $$;


