CREATE OR REPLACE FUNCTION "app_private"."assert_support_permission"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception using errcode = '28000', message = 'authentication_required';
  end if;
  actor_id := app_private.current_person_id();
  if actor_id is null then
    raise exception using errcode = '42501', message = 'internal_actor_required';
  end if;
  if not app_private.has_platform_permission('support.manage') then
    raise exception using errcode = '42501', message = 'permission_denied';
  end if;
  return actor_id;
end;
$$;


ALTER FUNCTION "app_private"."assert_support_permission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_unit_file_access"("p_permission" "text", "p_institution_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();
begin
 if (select auth.uid()) is null or actor is null or not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='authenticated AAL2 required';
 end if;
 if p_institution_id is null then
  if not app_private.has_platform_permission(p_permission) then
   raise insufficient_privilege using message='unit file permission required';
  end if;
 elsif not app_private.has_scoped_platform_permission(p_permission,p_institution_id) then
  raise insufficient_privilege using message='unit file scope denied';
 end if;
 return actor;
end $$;


ALTER FUNCTION "app_private"."assert_unit_file_access"("p_permission" "text", "p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_activate_configuration"("request_id" "uuid", "configuration_id" "uuid", "expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context;
  config public.activity_assessment_configurations%rowtype; request_hash bytea; replay jsonb;
begin
  select * into config from public.activity_assessment_configurations c
  where c.id = configuration_id;
  if not found then raise no_data_found using detail = 'ASSESSMENT_NOT_FOUND'; end if;
  select * into strict ctx
  from app_private.assessment_v2_require_context('activities.manage', config.institution_id);
  request_hash := app_private.assessment_v2_hash(jsonb_build_object(
    'configuration_id', configuration_id, 'expected_version', expected_version));
  replay := app_private.assessment_v2_replay(ctx, request_id, 'configuration.activate', request_hash);
  if replay is not null then return replay; end if;
  select * into config from public.activity_assessment_configurations c
  where c.id = configuration_id for update;
  if config.management_version <> expected_version then
    raise serialization_failure using detail = 'SAI_CONCURRENT_CHANGE';
  end if;
  if config.status <> 'draft'
    or (select coalesce(sum(i.weight), 0) from public.assessment_instruments i
      where i.configuration_id = config.id) <> 100
    or not exists (select 1 from public.assessment_periods p where p.configuration_id = config.id) then
    raise check_violation using detail = 'ASSESSMENT_INVALID_STATE';
  end if;
  update public.activity_assessment_configurations c set status = 'archived', updated_at = now()
  where c.activity_id = config.activity_id and c.unit_id is not distinct from config.unit_id
    and c.status = 'active';
  update public.activity_assessment_configurations c set status = 'active',
    management_version = c.management_version + 1, updated_at = now()
  where c.id = config.id returning * into config;
  update public.assessment_periods p set status = 'open', updated_at = now()
  where p.configuration_id = config.id;
  return app_private.assessment_v2_finish(ctx, request_id, config.institution_id,
    config.id, 'configuration.activate', request_hash, config.management_version,
    config.status, null);
end $$;


ALTER FUNCTION "app_private"."assessment_v2_activate_configuration"("request_id" "uuid", "configuration_id" "uuid", "expected_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_configuration_snapshot"("p_configuration_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'configuration', jsonb_build_object(
      'id', c.id, 'activity_id', c.activity_id, 'institution_id', c.institution_id,
      'unit_id', c.unit_id, 'periodicity', c.periodicity,
      'result_scale_kind', c.result_scale_kind, 'scale_options', c.scale_options,
      'allow_final_override', c.allow_final_override,
      'management_version', c.management_version, 'status', c.status),
    'instruments', coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'name', i.name, 'weight', i.weight, 'sort_order', i.sort_order)
      order by i.sort_order, i.id) from public.assessment_instruments i
      where i.configuration_id = c.id), '[]'::jsonb),
    'concepts', coalesce((select jsonb_agg(jsonb_build_object(
      'id', s.id, 'code', s.code, 'label', s.label, 'sort_order', s.sort_order)
      order by s.sort_order, s.id) from public.assessment_scale_concepts s
      where s.configuration_id = c.id), '[]'::jsonb),
    'competencies', coalesce((select jsonb_agg(jsonb_build_object(
      'id', x.id, 'name', x.name, 'category', cat.name)
      order by cat.sort_order, x.sort_order, x.id)
      from public.assessment_competencies x
      join public.assessment_categories cat on cat.id = x.category_id
      where x.configuration_id = c.id), '[]'::jsonb),
    'available_competencies', coalesce((select jsonb_agg(jsonb_build_object(
      'id', x.id, 'name', x.name, 'category', cat.name)
      order by cat.sort_order, x.sort_order, x.id)
      from public.assessment_competencies x
      join public.assessment_categories cat on cat.id = x.category_id
      where x.configuration_id = c.id), '[]'::jsonb),
    'periods', coalesce((select jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.name, 'ordinal', p.ordinal,
      'academic_year', p.academic_year, 'starts_on', p.starts_on,
      'ends_on', p.ends_on, 'entry_closes_at', p.entry_closes_at,
      'family_release_at', p.family_release_at, 'timezone', p.timezone,
      'status', p.status) order by p.academic_year, p.ordinal, p.id)
      from public.assessment_periods p where p.configuration_id = c.id), '[]'::jsonb))
  from public.activity_assessment_configurations c where c.id = p_configuration_id
$$;


ALTER FUNCTION "app_private"."assessment_v2_configuration_snapshot"("p_configuration_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_denied"("p_permission_code" "text", "p_action_code" "text", "p_code" "text", "p_correlation_id" "uuid", "p_institution_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare normalized text := case when coalesce(p_code, '') in (
  'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
  'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED',
  'SAI_MFA_REQUIRED','SAI_CONCURRENT_CHANGE','ASSESSMENT_INVALID_INPUT',
  'ASSESSMENT_INVALID_REFERENCE','ASSESSMENT_NOT_FOUND','ASSESSMENT_INVALID_STATE')
  then p_code else 'SAI_INTERNAL_ERROR' end;
begin
  perform app_private.audit_superadmin_internal_denial_if_identified(
    p_permission_code, p_action_code, normalized, p_correlation_id, p_institution_id);
  return app_private.assessment_v2_error(normalized, p_correlation_id);
end $$;


ALTER FUNCTION "app_private"."assessment_v2_denied"("p_permission_code" "text", "p_action_code" "text", "p_code" "text", "p_correlation_id" "uuid", "p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_error"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('ok', false, 'data', null, 'error', jsonb_build_object(
    'code', case when p_code in (
      'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
      'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED',
      'SAI_MFA_REQUIRED','SAI_CONCURRENT_CHANGE','ASSESSMENT_INVALID_INPUT',
      'ASSESSMENT_INVALID_REFERENCE','ASSESSMENT_NOT_FOUND','ASSESSMENT_INVALID_STATE')
      then p_code else 'SAI_INTERNAL_ERROR' end,
    'message', case
      when p_code = 'SAI_AUTH_REQUIRED' then 'Autenticação necessária.'
      when p_code = 'SAI_SESSION_INVALID' then 'Sessão inválida.'
      when p_code = 'SAI_MFA_REQUIRED' then 'Confirmação adicional necessária.'
      when p_code = 'SAI_CONCURRENT_CHANGE' then 'Os dados foram alterados por outra sessão.'
      when p_code = 'ASSESSMENT_INVALID_INPUT' then 'Dados da avaliação inválidos.'
      when p_code = 'ASSESSMENT_INVALID_REFERENCE' then 'Referência da avaliação inválida.'
      when p_code = 'ASSESSMENT_NOT_FOUND' then 'Avaliação não encontrada.'
      when p_code = 'ASSESSMENT_INVALID_STATE' then 'A avaliação não permite esta ação.'
      else 'Acesso negado.' end,
    'http_status', case
      when p_code in ('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 401
      when p_code in ('SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
        'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED') then 403
      when p_code = 'ASSESSMENT_NOT_FOUND' then 404
      when p_code in ('SAI_CONCURRENT_CHANGE','ASSESSMENT_INVALID_STATE') then 409
      when p_code in ('ASSESSMENT_INVALID_INPUT','ASSESSMENT_INVALID_REFERENCE') then 422
      else 500 end,
    'correlation_id', p_correlation_id))
$$;


ALTER FUNCTION "app_private"."assessment_v2_error"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_finish"("p_ctx" "app_private"."superadmin_internal_context", "p_request_id" "uuid", "p_institution_id" "uuid", "p_aggregate_id" "uuid", "p_command_kind" "text", "p_request_hash" "bytea", "p_version" bigint, "p_status" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; correlation uuid := gen_random_uuid(); audit_id uuid;
begin
  result := jsonb_build_object(
    'id', p_aggregate_id, 'version', p_version, 'status', p_status,
    'correlation_id', correlation, 'replayed', false);
  select app_private.audit_append_superadmin_internal(
    p_ctx.internal_identity_id, p_ctx.internal_auth_link_id,
    p_ctx.internal_membership_id, p_ctx.session_id,
    'activities.manage', p_ctx.aal, 'assessment.' || p_command_kind,
    'success', null, correlation, p_institution_id, 'assessment', p_aggregate_id,
    jsonb_build_object('id', p_aggregate_id, 'status', p_status, 'management_version', p_version))
  into audit_id;
  if audit_id is null then raise exception using message = 'assessment audit append failed'; end if;
  insert into app_private.superadmin_internal_assessment_command_receipts(
    request_id, internal_identity_id, institution_id, aggregate_id, command_kind,
    request_hash, resulting_version, resulting_status, result_json, correlation_id)
  values (p_request_id, p_ctx.internal_identity_id, p_institution_id, p_aggregate_id,
    p_command_kind, p_request_hash, p_version, p_status, result, correlation);
  if p_command_kind like 'gradebook.%' then
    insert into app_private.superadmin_internal_assessment_events(
      gradebook_id, internal_identity_id, event_kind, reason, version, correlation_id)
    values (p_aggregate_id, p_ctx.internal_identity_id,
      case p_command_kind
        when 'gradebook.save' then 'saved'
        when 'gradebook.submit' then 'submitted'
        when 'gradebook.review' then 'reviewed'
        when 'gradebook.return' then 'returned'
        when 'gradebook.publish' then 'published'
        else 'scheduled' end,
      nullif(btrim(p_reason), ''), p_version, correlation);
  end if;
  return result;
end $$;


ALTER FUNCTION "app_private"."assessment_v2_finish"("p_ctx" "app_private"."superadmin_internal_context", "p_request_id" "uuid", "p_institution_id" "uuid", "p_aggregate_id" "uuid", "p_command_kind" "text", "p_request_hash" "bytea", "p_version" bigint, "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_gradebook_snapshot"("p_gradebook_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'gradebook', jsonb_build_object(
      'id', b.id, 'institution_id', b.institution_id,
      'institution_name', i.public_name, 'unit_id', b.unit_id, 'unit_name', u.name,
      'activity_group_link_id', b.activity_group_link_id,
      'group_id', gl.group_id, 'group_name', g.name,
      'activity_id', a.id, 'activity_name', a.name,
      'period_id', p.id, 'period_name', p.name,
      'configuration_id', b.configuration_id, 'status', b.status,
      'management_version', b.management_version,
      'family_release_at', b.family_release_at,
      'publish_scheduled_at', b.publish_scheduled_at,
      'published_at', b.published_at),
    'configuration', app_private.assessment_v2_configuration_snapshot(b.configuration_id),
    'students', b.students_payload || case when b.status='draft' then
      coalesce((select jsonb_agg(candidate || jsonb_build_object('id',candidate->>'child_context_id'))
        from jsonb_array_elements(app_private.assessment_v2_initial_students(b.activity_group_link_id)) candidate
        where not exists (select 1 from jsonb_array_elements(b.students_payload) saved
          where saved->>'child_context_id'=candidate->>'child_context_id')), '[]'::jsonb)
      else '[]'::jsonb end,
    'events', coalesce((select jsonb_agg(jsonb_build_object(
      'id', e.id, 'event_kind', e.event_kind, 'actor_person_id', null,
      'reason', coalesce(e.reason, ''), 'version', e.version,
      'created_at', e.created_at) order by e.created_at desc, e.id desc)
      from app_private.superadmin_internal_assessment_events e
      where e.gradebook_id = b.id), '[]'::jsonb))
  from public.assessment_gradebooks b
  join public.activity_group_links gl on gl.id = b.activity_group_link_id
  join public.activity_definitions a on a.id = gl.activity_id
  join public.institutions i on i.id = b.institution_id
  join public.units u on u.id = b.unit_id
  join public.groups g on g.id = gl.group_id
  join public.assessment_periods p on p.id = b.period_id
  where b.id = p_gradebook_id
$$;


ALTER FUNCTION "app_private"."assessment_v2_gradebook_snapshot"("p_gradebook_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_hash"("p_value" "jsonb") RETURNS "bytea"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$select extensions.digest(pg_catalog.convert_to(coalesce(p_value, 'null'::jsonb)::text, 'UTF8'), 'sha256')$$;


ALTER FUNCTION "app_private"."assessment_v2_hash"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_initial_students"("p_activity_group_link_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', gen_random_uuid(), 'child_context_id', child_context.id,
    'name', person.display_name, 'state', 'not_started',
    'suggested_numeric_value', null, 'final_numeric_value', null,
    'final_concept_code', null, 'final_boolean_value', null,
    'override_reason', '', 'family_comment', '', 'internal_note', '',
    'instruments', '[]'::jsonb, 'competencies', '[]'::jsonb)
    order by person.display_name, child_context.id), '[]'::jsonb)
  from public.activity_group_links activity_link
  join public.groups group_row on group_row.id=activity_link.group_id
    and group_row.institution_id=activity_link.institution_id
    and group_row.unit_id=activity_link.unit_id and group_row.status='active'
  join public.units unit_row on unit_row.id=group_row.unit_id
    and unit_row.institution_id=group_row.institution_id and unit_row.status='active'
  join public.child_group_links child_group on child_group.group_id=group_row.id and child_group.status='active'
  join public.child_unit_links child_unit on child_unit.id=child_group.child_unit_link_id
    and child_unit.unit_id=group_row.unit_id and child_unit.status='active'
  join public.child_contexts child_context on child_context.id=child_unit.child_context_id
    and child_context.institution_id=group_row.institution_id and child_context.status='active'
  join public.people person on person.id=child_context.child_person_id and person.status='active'
  where activity_link.id=p_activity_group_link_id and activity_link.status='active'
    and (activity_link.participation_mode='all' or exists (
      select 1 from public.activity_group_participants participant
      where participant.activity_group_link_id=activity_link.id
        and participant.child_group_link_id=child_group.id
        and participant.status='active' and participant.removed_at is null))
$$;


ALTER FUNCTION "app_private"."assessment_v2_initial_students"("p_activity_group_link_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_ok"("p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$select jsonb_build_object('ok', true, 'data', p_data, 'error', null)$$;


ALTER FUNCTION "app_private"."assessment_v2_ok"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_replay"("p_ctx" "app_private"."superadmin_internal_context", "p_request_id" "uuid", "p_command_kind" "text", "p_request_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare receipt app_private.superadmin_internal_assessment_command_receipts%rowtype;
begin
  if p_request_id is null then
    raise invalid_parameter_value using message = 'assessment request_id is required';
  end if;
  select * into receipt
  from app_private.superadmin_internal_assessment_command_receipts r
  where r.request_id = p_request_id
  for update;
  if not found then return null; end if;
  if receipt.internal_identity_id is distinct from p_ctx.internal_identity_id then
    raise insufficient_privilege using message = 'assessment receipt actor mismatch',
      detail = 'SAI_PERMISSION_DENIED';
  end if;
  if receipt.command_kind is distinct from p_command_kind
    or receipt.request_hash is distinct from p_request_hash then
    raise invalid_parameter_value using message = 'assessment idempotency key reused',
      detail = 'ASSESSMENT_INVALID_INPUT';
  end if;
  -- Revalidate session, lifecycle, capability and scope before replay.
  perform app_private.assessment_v2_require_context(
    case when p_command_kind like '%.%' then 'activities.manage' else 'activities.manage' end,
    receipt.institution_id);
  return receipt.result_json || jsonb_build_object('replayed', true);
end $$;


ALTER FUNCTION "app_private"."assessment_v2_replay"("p_ctx" "app_private"."superadmin_internal_context", "p_request_id" "uuid", "p_command_kind" "text", "p_request_hash" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_require_context"("p_permission_code" "text", "p_institution_id" "uuid" DEFAULT NULL::"uuid") RETURNS "app_private"."superadmin_internal_context"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context;
begin
  select * into strict ctx
  from app_private.require_superadmin_internal_context(p_permission_code);
  if p_institution_id is not null then
    if not exists (select 1 from public.institutions i where i.id = p_institution_id)
      or (ctx.scope_kind = 'institution'
        and ctx.scope_institution_id is distinct from p_institution_id) then
      raise insufficient_privilege using message = 'assessment access denied', detail = 'SAI_PERMISSION_DENIED';
    end if;
    ctx.resolved_institution_id := p_institution_id;
  end if;
  return ctx;
end $$;


ALTER FUNCTION "app_private"."assessment_v2_require_context"("p_permission_code" "text", "p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_save_configuration"("request_id" "uuid", "configuration_id" "uuid", "expected_version" bigint, "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_variable
declare
  ctx app_private.superadmin_internal_context; saved public.activity_assessment_configurations%rowtype;
  institution_id uuid; unit_id uuid; activity_id uuid; request_hash bytea; replay jsonb;
  instrument jsonb; concept jsonb; category jsonb; competency jsonb; period jsonb;
  v_category_id uuid; v_competency_id uuid; instrument_total numeric;
begin
  if payload is null or jsonb_typeof(payload) <> 'object'
    or exists (select 1 from jsonb_object_keys(payload) k where k not in (
      'activity_id','institution_id','unit_id','periodicity','result_scale_kind',
      'scale_options','concepts','periods','allow_final_override','instruments','categories'))
    or not (payload ?& array['activity_id','institution_id','periodicity','result_scale_kind',
      'scale_options','periods','allow_final_override','instruments','categories'])
    or jsonb_typeof(payload->'scale_options') <> 'object'
    or jsonb_typeof(payload->'periods') <> 'array'
    or jsonb_typeof(payload->'instruments') <> 'array'
    or jsonb_typeof(payload->'categories') <> 'array'
    or coalesce(jsonb_typeof(payload->'concepts'), 'array') <> 'array'
    or jsonb_array_length(payload->'periods') not between 1 and 12
    or jsonb_array_length(payload->'instruments') not between 1 and 30
    or jsonb_array_length(payload->'categories') > 30 then
    raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
  end if;
  begin
    activity_id := (payload->>'activity_id')::uuid;
    institution_id := (payload->>'institution_id')::uuid;
    unit_id := nullif(payload->>'unit_id', '')::uuid;
  exception when others then
    raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
  end;
  select * into strict ctx
  from app_private.assessment_v2_require_context('activities.manage', institution_id);
  if not exists (select 1 from public.activity_definitions a
    where a.id = activity_id and a.institution_id = institution_id
      and a.status in ('draft','active'))
    or (unit_id is not null and not exists (select 1 from public.units u
      where u.id = unit_id and u.institution_id = institution_id and u.status = 'active'))
    or payload->>'periodicity' not in ('bimonthly','trimester','semester','annual')
    or payload->>'result_scale_kind' not in (
      'numeric_0_10','numeric_0_100','concept','numeric_1_5','binary','stars_0_5') then
    raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_REFERENCE';
  end if;
  request_hash := app_private.assessment_v2_hash(jsonb_build_object(
    'configuration_id', configuration_id, 'expected_version', expected_version, 'payload', payload));
  replay := app_private.assessment_v2_replay(ctx, request_id, 'configuration.save', request_hash);
  if replay is not null then return replay; end if;

  if configuration_id is null then
    if expected_version <> 0 then raise serialization_failure using detail = 'SAI_CONCURRENT_CHANGE'; end if;
    insert into public.activity_assessment_configurations(
      activity_id, institution_id, unit_id, periodicity, result_scale_kind,
      scale_options, allow_final_override)
    values (activity_id, institution_id, unit_id, payload->>'periodicity',
      payload->>'result_scale_kind', payload->'scale_options',
      coalesce((payload->>'allow_final_override')::boolean, false))
    returning * into saved;
  else
    select * into saved from public.activity_assessment_configurations c
    where c.id = configuration_id and c.institution_id = institution_id for update;
    if not found then raise no_data_found using detail = 'ASSESSMENT_NOT_FOUND'; end if;
    if saved.management_version <> expected_version then
      raise serialization_failure using detail = 'SAI_CONCURRENT_CHANGE';
    end if;
    if saved.status <> 'draft' or saved.activity_id <> activity_id
      or saved.unit_id is distinct from unit_id then
      raise check_violation using detail = 'ASSESSMENT_INVALID_STATE';
    end if;
    update public.activity_assessment_configurations c set
      periodicity = payload->>'periodicity', result_scale_kind = payload->>'result_scale_kind',
      scale_options = payload->'scale_options',
      allow_final_override = coalesce((payload->>'allow_final_override')::boolean, false),
      management_version = c.management_version + 1, updated_at = now()
    where c.id = saved.id returning * into saved;
    delete from public.assessment_instruments item where item.configuration_id = saved.id;
    delete from public.assessment_categories item where item.configuration_id = saved.id;
    delete from public.assessment_scale_concepts item where item.configuration_id = saved.id;
    delete from public.assessment_periods item where item.configuration_id = saved.id;
  end if;

  for instrument in select value from jsonb_array_elements(payload->'instruments') loop
    if jsonb_typeof(instrument) <> 'object'
      or not (instrument ?& array['name','weight','sort_order'])
      or exists (select 1 from jsonb_object_keys(instrument) k
        where k not in ('name','weight','sort_order')) then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
    end if;
    insert into public.assessment_instruments(configuration_id, name, weight, sort_order)
    values (saved.id, btrim(instrument->>'name'), (instrument->>'weight')::numeric,
      (instrument->>'sort_order')::integer);
  end loop;
  select sum(i.weight) into instrument_total from public.assessment_instruments i
  where i.configuration_id = saved.id;
  if instrument_total <> 100 then
    raise check_violation using detail = 'ASSESSMENT_INVALID_INPUT';
  end if;

  for concept in select value from jsonb_array_elements(coalesce(payload->'concepts','[]'::jsonb)) loop
    if jsonb_typeof(concept) <> 'object' or not (concept ?& array['code','label','sort_order']) then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
    end if;
    insert into public.assessment_scale_concepts(configuration_id, code, label, sort_order)
    values (saved.id, btrim(concept->>'code'), btrim(concept->>'label'),
      (concept->>'sort_order')::integer);
  end loop;
  if saved.result_scale_kind = 'concept'
    and not exists (select 1 from public.assessment_scale_concepts s where s.configuration_id = saved.id) then
    raise check_violation using detail = 'ASSESSMENT_INVALID_INPUT';
  end if;

  for category in select value from jsonb_array_elements(payload->'categories') loop
    if jsonb_typeof(category) <> 'object' or not (category ?& array['name','competencies'])
      or jsonb_typeof(category->'competencies') <> 'array' then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
    end if;
    insert into public.assessment_categories(configuration_id, name, sort_order)
    values (saved.id, btrim(category->>'name'),
      coalesce((category->>'sort_order')::integer,
        (select count(*) from public.assessment_categories c where c.configuration_id = saved.id)))
    returning id into v_category_id;
    for competency in select value from jsonb_array_elements(category->'competencies') loop
      insert into public.assessment_competencies(category_id, configuration_id, name, sort_order)
      values (v_category_id, saved.id, btrim(competency->>'name'),
        coalesce((competency->>'sort_order')::integer, 0))
      returning id into v_competency_id;
      insert into public.assessment_configuration_competencies(configuration_id, competency_id, sort_order)
      values (saved.id, v_competency_id, coalesce((competency->>'sort_order')::integer, 0));
    end loop;
  end loop;

  for period in select value from jsonb_array_elements(payload->'periods') loop
    if jsonb_typeof(period) <> 'object'
      or not (period ?& array['name','ordinal','academic_year','starts_on','ends_on',
        'entry_closes_at','family_release_at']) then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
    end if;
    if not exists (select 1 from pg_catalog.pg_timezone_names z
      where z.name = coalesce(nullif(period->>'timezone',''), 'America/Sao_Paulo')) then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
    end if;
    insert into public.assessment_periods(
      configuration_id, institution_id, unit_id, name, periodicity, ordinal,
      academic_year, starts_on, ends_on, entry_closes_at, family_release_at,
      timezone, status)
    values (saved.id, saved.institution_id, saved.unit_id, btrim(period->>'name'),
      saved.periodicity, (period->>'ordinal')::smallint, (period->>'academic_year')::integer,
      (period->>'starts_on')::date, (period->>'ends_on')::date,
      (period->>'entry_closes_at')::timestamptz, (period->>'family_release_at')::timestamptz,
      coalesce(nullif(period->>'timezone',''), 'America/Sao_Paulo'), 'draft');
  end loop;
  return app_private.assessment_v2_finish(ctx, request_id, saved.institution_id,
    saved.id, 'configuration.save', request_hash, saved.management_version,
    saved.status, null);
end $$;


ALTER FUNCTION "app_private"."assessment_v2_save_configuration"("request_id" "uuid", "configuration_id" "uuid", "expected_version" bigint, "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_save_gradebook"("request_id" "uuid", "gradebook_id" "uuid", "expected_version" bigint, "payload" "jsonb", "reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; book public.assessment_gradebooks%rowtype;
  group_link public.activity_group_links%rowtype; config public.activity_assessment_configurations%rowtype;
  period public.assessment_periods%rowtype; request_hash bytea; replay jsonb; normalized jsonb;
begin
  if payload is null or jsonb_typeof(payload) <> 'object'
    or not (payload ?& array['activity_group_link_id','period_id','configuration_id','students'])
    or exists (select 1 from jsonb_object_keys(payload) k
      where k not in ('activity_group_link_id','period_id','configuration_id','students')) then
    raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
  end if;
  request_hash := app_private.assessment_v2_hash(jsonb_build_object(
    'gradebook_id', gradebook_id, 'expected_version', expected_version,
    'payload', payload, 'reason', coalesce(reason, '')));
  if gradebook_id is null then
    begin
      select * into group_link from public.activity_group_links gl
      where gl.id = (payload->>'activity_group_link_id')::uuid and gl.status = 'active';
      select * into config from public.activity_assessment_configurations c
      where c.id = (payload->>'configuration_id')::uuid and c.status = 'active';
      select * into period from public.assessment_periods p
      where p.id = (payload->>'period_id')::uuid and p.status = 'open';
    exception when others then raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT'; end;
    if group_link.id is null or config.id is null or period.id is null
      or group_link.activity_id <> config.activity_id
      or group_link.institution_id <> config.institution_id
      or (config.unit_id is not null and config.unit_id <> group_link.unit_id)
      or period.configuration_id <> config.id
      or period.institution_id <> group_link.institution_id
      or (period.unit_id is not null and period.unit_id <> group_link.unit_id) then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_REFERENCE';
    end if;
    select * into strict ctx
    from app_private.assessment_v2_require_context('activities.manage', group_link.institution_id);
    replay := app_private.assessment_v2_replay(ctx, request_id, 'gradebook.save', request_hash);
    if replay is not null then return replay; end if;
    if expected_version <> 0 then raise serialization_failure using detail = 'SAI_CONCURRENT_CHANGE'; end if;
    select * into book from public.assessment_gradebooks b
    where b.activity_group_link_id = group_link.id and b.period_id = period.id for update;
    if not found then
      insert into public.assessment_gradebooks(
        institution_id, unit_id, activity_group_link_id, period_id, configuration_id,
        students_payload, family_release_at)
      values (group_link.institution_id, group_link.unit_id, group_link.id, period.id,
        config.id, app_private.assessment_v2_initial_students(group_link.id), period.family_release_at)
      returning * into book;
    end if;
  else
    select * into book from public.assessment_gradebooks b where b.id = gradebook_id;
    if not found then raise no_data_found using detail = 'ASSESSMENT_NOT_FOUND'; end if;
    select * into strict ctx
    from app_private.assessment_v2_require_context('activities.manage', book.institution_id);
    replay := app_private.assessment_v2_replay(ctx, request_id, 'gradebook.save', request_hash);
    if replay is not null then return replay; end if;
    select * into book from public.assessment_gradebooks b where b.id = gradebook_id for update;
    if book.management_version <> expected_version then
      raise serialization_failure using detail = 'SAI_CONCURRENT_CHANGE';
    end if;
    if book.status <> 'draft' then raise check_violation using detail = 'ASSESSMENT_INVALID_STATE'; end if;
    if (payload->>'activity_group_link_id')::uuid <> book.activity_group_link_id
      or (payload->>'period_id')::uuid <> book.period_id
      or (payload->>'configuration_id')::uuid <> book.configuration_id then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_REFERENCE';
    end if;
    normalized := app_private.assessment_v2_validate_students(book, payload->'students');
    update public.assessment_gradebooks b set students_payload = normalized,
      management_version = b.management_version + 1, updated_at = now()
    where b.id = book.id returning * into book;
  end if;
  return app_private.assessment_v2_finish(ctx, request_id, book.institution_id,
    book.id, 'gradebook.save', request_hash, book.management_version,
    book.status, reason);
end $$;


ALTER FUNCTION "app_private"."assessment_v2_save_gradebook"("request_id" "uuid", "gradebook_id" "uuid", "expected_version" bigint, "payload" "jsonb", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_transition_gradebook"("request_id" "uuid", "gradebook_id" "uuid", "expected_version" bigint, "target_status" "text", "command_kind" "text", "reason" "text", "publish_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; book public.assessment_gradebooks%rowtype;
  request_hash bytea; replay jsonb;
begin
  select * into book from public.assessment_gradebooks b where b.id = gradebook_id;
  if not found then raise no_data_found using detail = 'ASSESSMENT_NOT_FOUND'; end if;
  select * into strict ctx
  from app_private.assessment_v2_require_context('activities.manage', book.institution_id);
  request_hash := app_private.assessment_v2_hash(jsonb_build_object(
    'gradebook_id', gradebook_id, 'expected_version', expected_version,
    'target_status', target_status, 'command_kind', command_kind,
    'reason', coalesce(reason, ''), 'publish_at', publish_at));
  replay := app_private.assessment_v2_replay(ctx, request_id, command_kind, request_hash);
  if replay is not null then return replay; end if;
  select * into book from public.assessment_gradebooks b where b.id = gradebook_id for update;
  if book.management_version <> expected_version then
    raise serialization_failure using detail = 'SAI_CONCURRENT_CHANGE';
  end if;
  if command_kind = 'gradebook.submit' and (book.status <> 'draft'
      or exists (select 1 from jsonb_array_elements(book.students_payload) student
        where student->>'state' not in ('complete','absent'))) then
    raise check_violation using detail = 'ASSESSMENT_INVALID_STATE';
  elsif command_kind = 'gradebook.review' and book.status <> 'submitted' then
    raise check_violation using detail = 'ASSESSMENT_INVALID_STATE';
  elsif command_kind = 'gradebook.return' and book.status not in ('submitted','reviewed') then
    raise check_violation using detail = 'ASSESSMENT_INVALID_STATE';
  elsif command_kind = 'gradebook.publish' and book.status <> 'reviewed' then
    raise check_violation using detail = 'ASSESSMENT_INVALID_STATE';
  elsif command_kind = 'gradebook.schedule' and (book.status <> 'reviewed'
      or publish_at is null or publish_at <= now()) then
    raise check_violation using detail = 'ASSESSMENT_INVALID_STATE';
  end if;
  update public.assessment_gradebooks b set
    status = target_status,
    management_version = b.management_version + 1,
    submitted_at = case when command_kind = 'gradebook.submit' then now() else b.submitted_at end,
    reviewed_at = case when command_kind = 'gradebook.review' then now() else b.reviewed_at end,
    published_at = case when command_kind = 'gradebook.publish' then now() else b.published_at end,
    publish_scheduled_at = case when command_kind = 'gradebook.schedule' then publish_at
      when command_kind in ('gradebook.return','gradebook.publish') then null
      else b.publish_scheduled_at end,
    updated_at = now()
  where b.id = book.id returning * into book;
  return app_private.assessment_v2_finish(ctx, request_id, book.institution_id,
    book.id, command_kind, request_hash, book.management_version, book.status, reason);
end $$;


ALTER FUNCTION "app_private"."assessment_v2_transition_gradebook"("request_id" "uuid", "gradebook_id" "uuid", "expected_version" bigint, "target_status" "text", "command_kind" "text", "reason" "text", "publish_at" timestamp with time zone) OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."assessment_gradebooks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "activity_group_link_id" "uuid" NOT NULL,
    "period_id" "uuid" NOT NULL,
    "configuration_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "management_version" bigint DEFAULT 1 NOT NULL,
    "students_payload" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "family_release_at" timestamp with time zone,
    "publish_scheduled_at" timestamp with time zone,
    "submitted_at" timestamp with time zone,
    "reviewed_at" timestamp with time zone,
    "published_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "assessment_gradebooks_management_version_check" CHECK (("management_version" > 0)),
    CONSTRAINT "assessment_gradebooks_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'reviewed'::"text", 'published'::"text"]))),
    CONSTRAINT "assessment_gradebooks_students_payload_check" CHECK (("jsonb_typeof"("students_payload") = 'array'::"text"))
);

ALTER TABLE ONLY "public"."assessment_gradebooks" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."assessment_gradebooks" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assessment_v2_validate_students"("p_gradebook" "public"."assessment_gradebooks", "p_students" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare item jsonb; normalized jsonb := '[]'::jsonb; old_item jsonb;
  child_context_id uuid; instrument jsonb; competency jsonb; config record;
begin
  if p_students is null or jsonb_typeof(p_students) <> 'array'
    or jsonb_array_length(p_students) > 500
    or (select count(*) from jsonb_array_elements(p_students)) <>
       (select count(distinct value->>'child_context_id') from jsonb_array_elements(p_students)) then
    raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
  end if;
  select c.result_scale_kind, c.scale_options into config
  from public.activity_assessment_configurations c where c.id = p_gradebook.configuration_id;
  for item in select value from jsonb_array_elements(p_students) loop
    if jsonb_typeof(item) <> 'object'
      or not (item ?& array['child_context_id','state','instruments','competencies'])
      or exists (select 1 from jsonb_object_keys(item) k where k not in (
        'child_context_id','state','final_numeric_value','final_concept_code',
        'final_boolean_value','override_reason','family_comment','internal_note',
        'instruments','competencies'))
      or item->>'state' not in ('not_started','pending','complete','absent')
      or jsonb_typeof(item->'instruments') <> 'array'
      or jsonb_typeof(item->'competencies') <> 'array'
      or char_length(coalesce(item->>'override_reason','')) > 500
      or char_length(coalesce(item->>'family_comment','')) > 2000
      or char_length(coalesce(item->>'internal_note','')) > 4000 then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
    end if;
    begin child_context_id := (item->>'child_context_id')::uuid;
    exception when others then raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT'; end;
    if not exists (
      select 1 from jsonb_array_elements(app_private.assessment_v2_initial_students(p_gradebook.activity_group_link_id)) candidate
      where candidate->>'child_context_id'=child_context_id::text
    ) then raise invalid_parameter_value using detail='ASSESSMENT_INVALID_REFERENCE'; end if;
    if (select count(*) from jsonb_array_elements(item->'instruments')) <>
       (select count(distinct value->>'instrument_id') from jsonb_array_elements(item->'instruments'))
      or (select count(*) from jsonb_array_elements(item->'competencies')) <>
       (select count(distinct value->>'competency_id') from jsonb_array_elements(item->'competencies')) then
      raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
    end if;
    for instrument in select value from jsonb_array_elements(item->'instruments') loop
      if not exists (select 1 from public.assessment_instruments i
        where i.id = (instrument->>'instrument_id')::uuid
          and i.configuration_id = p_gradebook.configuration_id)
        or coalesce((instrument->>'absent')::boolean, false) = false and
          num_nonnulls(instrument->>'numeric_value', instrument->>'concept_code',
            instrument->>'boolean_value') <> 1 then
        raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_REFERENCE';
      end if;
      if config.result_scale_kind = 'numeric_0_10'
        and (instrument->>'numeric_value')::numeric not between 0 and 10
        or config.result_scale_kind = 'numeric_0_100'
        and (instrument->>'numeric_value')::numeric not between 0 and 100
        or config.result_scale_kind in ('numeric_1_5')
        and (instrument->>'numeric_value')::numeric not between 1 and 5
        or config.result_scale_kind = 'stars_0_5'
        and (instrument->>'numeric_value')::numeric not between 0 and 5
        or config.result_scale_kind = 'concept' and not exists (
          select 1 from public.assessment_scale_concepts s
          where s.configuration_id = p_gradebook.configuration_id
            and s.code = instrument->>'concept_code') then
        raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_INPUT';
      end if;
    end loop;
    for competency in select value from jsonb_array_elements(item->'competencies') loop
      if not exists (select 1 from public.assessment_competencies c
        where c.id = (competency->>'competency_id')::uuid
          and c.configuration_id = p_gradebook.configuration_id)
        or (competency->>'score')::numeric not between 0 and 5 then
        raise invalid_parameter_value using detail = 'ASSESSMENT_INVALID_REFERENCE';
      end if;
    end loop;
    select value into old_item from jsonb_array_elements(p_gradebook.students_payload)
    where value->>'child_context_id' = child_context_id::text limit 1;
    normalized := normalized || jsonb_build_array(item || jsonb_build_object(
      'id', coalesce(old_item->>'id', gen_random_uuid()::text),
      'name', coalesce(old_item->>'name', (select person.display_name
        from public.child_contexts cc join public.people person on person.id = cc.child_person_id
        where cc.id = child_context_id)),
      'suggested_numeric_value', case
        when item->>'state' = 'absent' then null
        else (select round(sum((entry->>'numeric_value')::numeric * i.weight) /
          nullif(sum(i.weight), 0), 2)
          from jsonb_array_elements(item->'instruments') entry
          join public.assessment_instruments i
            on i.id = (entry->>'instrument_id')::uuid
          where not coalesce((entry->>'absent')::boolean, false)
            and entry->>'numeric_value' is not null) end));
  end loop;
  return normalized;
end $$;


ALTER FUNCTION "app_private"."assessment_v2_validate_students"("p_gradebook" "public"."assessment_gradebooks", "p_students" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."attendance_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "group_id" "uuid" NOT NULL,
    "activity_id" "uuid",
    "session_kind" "text" NOT NULL,
    "session_date" "date" NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "created_by_person_id" "uuid" NOT NULL,
    "closed_by_person_id" "uuid",
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "version" bigint DEFAULT 1 NOT NULL,
    "reopen_reason" "text",
    "reopened_by_person_id" "uuid",
    "reopened_at" timestamp with time zone,
    CONSTRAINT "attendance_sessions_dates_check" CHECK ((("ends_at" IS NULL) OR ("starts_at" IS NULL) OR ("ends_at" > "starts_at"))),
    CONSTRAINT "attendance_sessions_kind_check" CHECK (((("session_kind" = 'group'::"text") AND ("activity_id" IS NULL)) OR (("session_kind" = 'activity'::"text") AND ("activity_id" IS NOT NULL)))),
    CONSTRAINT "attendance_sessions_session_kind_check" CHECK (("session_kind" = ANY (ARRAY['group'::"text", 'activity'::"text"]))),
    CONSTRAINT "attendance_sessions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'open'::"text", 'reopened'::"text", 'closed'::"text", 'corrected'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "attendance_sessions_version_check" CHECK (("version" > 0))
);

ALTER TABLE ONLY "public"."attendance_sessions" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."attendance_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_audit"("p_actor" "uuid", "p_action_code" "text", "p_session" "public"."attendance_sessions", "p_object_type" "text", "p_object_id" "uuid", "p_reason" "text", "p_after" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- O guard de auditoria minimiza por desenho (LGPD): reason em texto livre
  -- vira '[redacted]' e after_json guarda so chaves da allowlist (ids, status,
  -- state, version). O motivo legivel de correcao fica em
  -- attendance_record_revisions.reason e o de reabertura em
  -- attendance_sessions.reopen_reason.
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, reason, after_json
  ) values (
    p_actor, coalesce(auth.jwt()->>'aal', 'aal1'), p_action_code, p_object_type, p_object_id,
    p_session.institution_id, 'success', p_reason, p_after
  )
$$;


ALTER FUNCTION "app_private"."attendance_audit"("p_actor" "uuid", "p_action_code" "text", "p_session" "public"."attendance_sessions", "p_object_type" "text", "p_object_id" "uuid", "p_reason" "text", "p_after" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_bump_version"("p_session_id" "uuid", "p_status" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.attendance_sessions
     set version = version + 1,
         status = coalesce(p_status, status),
         updated_at = now()
   where id = p_session_id
  returning version
$$;


ALTER FUNCTION "app_private"."attendance_bump_version"("p_session_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_call_payload"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_row public.attendance_sessions%rowtype;
  result jsonb;
begin
  select * into session_row from public.attendance_sessions where id = p_session_id;
  if session_row.id is null then
    return null;
  end if;

  select jsonb_build_object(
    'id', session_row.id,
    'institution_id', session_row.institution_id,
    'institution_name', coalesce(institution.public_name, ''),
    'unit_id', session_row.unit_id,
    'unit_name', coalesce(unit_row.name, ''),
    'group_id', session_row.group_id,
    'group_name', coalesce(group_row.name, ''),
    'activity_id', session_row.activity_id,
    'activity_name', activity.name,
    'session_date', session_row.session_date,
    'status', session_row.status,
    'responsible', coalesce(responsible.display_name, ''),
    'can_manage', app_private.can_access_attendance_child(
      session_row.institution_id, session_row.unit_id, session_row.group_id,
      session_row.activity_id, null, true),
    'updated_at', session_row.updated_at,
    'version', session_row.version,
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', expected.id,
        'participant_id', expected.child_context_id,
        'name', coalesce(child_person.display_name, ''),
        'state', coalesce(record_row.outcome, 'unmarked'),
        'note', coalesce(record_row.note, ''),
        'justification', case notice_row.review_status
          when 'pending' then 'pending' when 'confirmed' then 'accepted'
          when 'rejected' then 'rejected' else null end,
        'notice', case when notice_row.id is null then null
          else app_private.attendance_notice_payload(notice_row) end
      ) order by lower(child_person.display_name), expected.child_context_id)
      from public.attendance_expected_participants expected
      join public.child_contexts child_context on child_context.id = expected.child_context_id
      join public.people child_person on child_person.id = child_context.child_person_id
      left join public.attendance_records record_row
        on record_row.attendance_session_id = session_row.id
       and record_row.child_context_id = expected.child_context_id
       and record_row.status = 'active'
      left join lateral (
        select notice.* from public.attendance_notices notice
        where notice.child_context_id = expected.child_context_id
          and notice.group_id = session_row.group_id
          and notice.cancelled_at is null
          and session_row.session_date between (notice.starts_at at time zone 'UTC')::date
            and coalesce((notice.ends_at at time zone 'UTC')::date, (notice.starts_at at time zone 'UTC')::date)
        order by case notice.review_status when 'pending' then 0 else 1 end, notice.created_at desc
        limit 1
      ) notice_row on true
      where expected.attendance_session_id = session_row.id
        and expected.status = 'active'
    ), '[]'::jsonb),
    'revisions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'participant_id', record_row.child_context_id,
        'previous', coalesce(revision.before_json->>'outcome', 'unmarked'),
        'current', case when revision.action_code = 'reverted' then 'unmarked'
          else coalesce(revision.after_json->>'outcome', 'unmarked') end,
        'reason', coalesce(revision.reason, ''),
        'author', coalesce(author.display_name, ''),
        'changed_at', revision.created_at
      ) order by revision.created_at desc, revision.id)
      from public.attendance_record_revisions revision
      join public.attendance_records record_row on record_row.id = revision.attendance_record_id
      join public.people author on author.id = revision.changed_by_person_id
      where record_row.attendance_session_id = session_row.id
        and revision.action_code in ('corrected','reverted')
    ), '[]'::jsonb)
  ) into result
  from public.institutions institution
  join public.units unit_row on unit_row.id = session_row.unit_id
  join public.groups group_row on group_row.id = session_row.group_id
  left join public.activity_definitions activity on activity.id = session_row.activity_id
  left join public.people responsible on responsible.id = session_row.created_by_person_id
  where institution.id = session_row.institution_id;

  return result;
end $$;


ALTER FUNCTION "app_private"."attendance_call_payload"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_dashboard_access"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid:=app_private.current_person_id();
  membership_record record;
  scope_name text;
  child_ids jsonb;
  group_ids jsonb;
  activity_ids jsonb;
begin
  if actor is null then
    raise insufficient_privilege using message='authentication required';
  end if;

  if app_private.has_platform_permission('attendance.read')
     or app_private.has_platform_permission('attendance.manage') then
    return jsonb_build_object(
      'scope','platform','can_read',true,
      'can_create_call',app_private.has_platform_permission('attendance.manage'),
      'can_export',app_private.has_platform_permission('attendance.export'),
      'assigned_group_ids','[]'::jsonb,'assigned_activity_ids','[]'::jsonb,
      'child_ids','[]'::jsonb
    );
  end if;

  select membership.id,membership.institution_id,
         case
           when bool_or(assignment.scope_kind='institution') then 'institution'
           when bool_or(assignment.scope_kind='unit') then 'unit'
           else 'assignments'
         end as scope_kind,
         min(assignment.scope_unit_id::text)::uuid as unit_id
    into membership_record
  from public.institution_memberships membership
  join public.institution_role_assignments assignment
    on assignment.membership_id=membership.id
   and assignment.status='active'
   and (assignment.starts_at is null or assignment.starts_at<=now())
   and (assignment.expires_at is null or assignment.expires_at>now())
  where membership.person_id=actor and membership.status='active'
    and membership.revoked_at is null
    and (
      app_private.has_context_permission(membership.institution_id,'attendance.read',
        assignment.scope_unit_id,assignment.scope_group_id,null,null,false)
      or app_private.has_context_permission(membership.institution_id,'attendance.manage',
        assignment.scope_unit_id,assignment.scope_group_id,null,null,false)
    )
  group by membership.id,membership.institution_id
  order by case when bool_or(assignment.scope_kind='institution') then 0
                when bool_or(assignment.scope_kind='unit') then 1 else 2 end
  limit 1;

  if membership_record.id is not null then
    scope_name:=membership_record.scope_kind;
    select
      coalesce(jsonb_agg(distinct link.group_id)
        filter(where link.group_id is not null),'[]'::jsonb),
      coalesce(jsonb_agg(distinct link.activity_id)
        filter(where link.activity_id is not null),'[]'::jsonb)
      into group_ids,activity_ids
    from public.activity_group_assignments assignment
    join public.activity_group_links link
      on link.id=assignment.activity_group_link_id
     and link.institution_id=assignment.institution_id
    where assignment.membership_id=membership_record.id
      and assignment.person_id=actor
      and assignment.institution_id=membership_record.institution_id
      and assignment.status='active' and assignment.revoked_at is null
      and link.status='active' and link.starts_at<=now()
      and (link.ends_at is null or link.ends_at>now());

    return jsonb_build_object(
      'scope',scope_name,'can_read',true,
      'institution_id',membership_record.institution_id,
      'unit_id',case when scope_name='unit' then membership_record.unit_id else null end,
      'can_create_call',app_private.has_context_permission(
        membership_record.institution_id,'attendance.manage',membership_record.unit_id,null,null,null,false),
      'can_export',case when scope_name='assignments' then exists(
        select 1
        from public.groups authorized_group
        where authorized_group.institution_id=membership_record.institution_id
          and authorized_group.status='active'
          and group_ids ? authorized_group.id::text
          and app_private.has_context_permission(
            membership_record.institution_id,'attendance.export',
            authorized_group.unit_id,authorized_group.id,null,null,false)
      ) else app_private.has_context_permission(
        membership_record.institution_id,'attendance.export',membership_record.unit_id,null,null,null,false)
      end,
      'assigned_group_ids',coalesce(group_ids,'[]'::jsonb),
      'assigned_activity_ids',coalesce(activity_ids,'[]'::jsonb),
      'child_ids','[]'::jsonb
    );
  end if;

  select coalesce(jsonb_agg(distinct child_context.id),'[]'::jsonb)
    into child_ids
  from public.guardian_links guardian
  join public.child_contexts child_context on child_context.child_person_id=guardian.child_person_id
  where guardian.guardian_person_id=actor and guardian.status='active'
    and guardian.revoked_at is null and child_context.status='active'
    and app_private.guardian_has_capability(child_context.id,'manage_attendance_notices');

  if jsonb_array_length(child_ids)>0 then
    return jsonb_build_object(
      'scope','guardian','can_read',true,'can_create_call',false,'can_export',false,
      'assigned_group_ids','[]'::jsonb,'assigned_activity_ids','[]'::jsonb,
      'child_ids',child_ids
    );
  end if;

  raise insufficient_privilege using message='attendance.read required';
end $$;


ALTER FUNCTION "app_private"."attendance_dashboard_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_dashboard_ranking_page"("p_start" "date", "p_end" "date", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid", "p_child_id" "uuid", "p_kind" "text", "p_direction" "text", "p_page" integer, "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  access_payload jsonb;
  scope_name text;
begin
  if p_kind not in('institutions','units','groups','activities','students','teachers')
     or p_direction not in('highest','lowest') or p_page<1 or p_page_size not between 1 and 100 then
    raise invalid_parameter_value using message='invalid ranking request';
  end if;
  access_payload:=app_private.attendance_dashboard_access();
  scope_name:=access_payload->>'scope';
  if (scope_name='guardian' and p_kind<>'students')
     or (scope_name in('institution','unit','assignments') and p_kind='institutions')
     or (scope_name in('unit','assignments') and p_kind='units') then
    raise insufficient_privilege using message='ranking outside attendance scope';
  end if;

  if p_kind='teachers' then
    with authorized_sessions as materialized (
      select session.*
      from public.attendance_sessions session
      where session.session_date between p_start and p_end
        and session.status<>'cancelled'
        and (p_institution_id is null or session.institution_id=p_institution_id)
        and (p_unit_id is null or session.unit_id=p_unit_id)
        and (p_group_id is null or session.group_id=p_group_id)
        and (p_activity_id is null or session.activity_id=p_activity_id)
        and app_private.can_access_attendance_child(
          session.institution_id,session.unit_id,session.group_id,session.activity_id,null,false)
    ), ranked as (
      select person.id,person.display_name as label,
        count(*)::integer as total_records,
        count(*) filter(where session.status in('closed','corrected'))::integer as completed,
        case when count(*)=0 then null else
          count(*) filter(where session.status in('closed','corrected'))::numeric/count(*)*100 end as percent,
        count(*) over()::integer as total_items
      from authorized_sessions session
      join public.people person on person.id=session.created_by_person_id
      group by person.id,person.display_name
    ), paged as (
      select * from ranked
      order by case when p_direction='highest' then percent end desc nulls last,
               case when p_direction='lowest' then percent end asc nulls last,label,id
      offset (p_page-1)*p_page_size limit p_page_size
    )
    select jsonb_build_object(
      'kind',p_kind,'direction',p_direction,'total',coalesce(max(total_items),0),
      'items',coalesce(jsonb_agg(jsonb_build_object(
        'id',id,'label',label,'official_records',total_records,'percent',percent,
        'auxiliary_label',completed||' de '||total_records||' chamadas concluídas'
      )),'[]'::jsonb)
    ) into result from paged;
    return result;
  end if;

  with authorized_sessions as materialized (
    select session.*
    from public.attendance_sessions session
    where session.session_date between p_start and p_end
      and session.status in('closed','corrected')
      and (p_institution_id is null or session.institution_id=p_institution_id)
      and (p_unit_id is null or session.unit_id=p_unit_id)
      and (p_group_id is null or session.group_id=p_group_id)
      and (p_activity_id is null or session.activity_id=p_activity_id)
      and (
        app_private.can_access_attendance_child(
          session.institution_id,session.unit_id,session.group_id,session.activity_id,p_child_id,false)
        or (p_child_id is null and exists(
          select 1 from public.attendance_expected_participants expected
          where expected.attendance_session_id=session.id and expected.status='active'
            and app_private.can_access_attendance_child(
              session.institution_id,session.unit_id,session.group_id,session.activity_id,
              expected.child_context_id,false)
        ))
      )
  ), source_rows as (
    select
      case p_kind
        when 'institutions' then session.institution_id
        when 'units' then session.unit_id
        when 'groups' then session.group_id
        when 'activities' then session.activity_id
        when 'students' then record.child_context_id
      end as item_id,
      case p_kind
        when 'institutions' then institution.public_name
        when 'units' then unit_record.name
        when 'groups' then group_record.name
        when 'activities' then activity.name
        when 'students' then child_person.display_name
      end as label,
      record.outcome
    from authorized_sessions session
    join public.attendance_records record
      on record.attendance_session_id=session.id and record.status='active'
    join public.institutions institution on institution.id=session.institution_id
    join public.units unit_record on unit_record.id=session.unit_id
    join public.groups group_record on group_record.id=session.group_id
    left join public.activity_definitions activity on activity.id=session.activity_id
    join public.child_contexts child_context on child_context.id=record.child_context_id
    join public.people child_person on child_person.id=child_context.child_person_id
    where (p_child_id is null or record.child_context_id=p_child_id)
      and app_private.can_access_attendance_child(
        session.institution_id,session.unit_id,session.group_id,session.activity_id,
        record.child_context_id,false)
  ), ranked as (
    select item_id,label,count(*)::integer as official_records,
      count(*) filter(where outcome in('present','late_arrival','early_departure','late_and_early'))
        ::numeric/count(*)*100 as percent,
      count(*) over()::integer as total_items
    from source_rows where item_id is not null
    group by item_id,label
  ), paged as (
    select * from ranked
    order by case when p_direction='highest' then percent end desc,
             case when p_direction='lowest' then percent end asc,label,item_id
    offset (p_page-1)*p_page_size limit p_page_size
  )
  select jsonb_build_object(
    'kind',p_kind,'direction',p_direction,'total',coalesce(max(total_items),0),
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',item_id,'label',label,'official_records',official_records,'percent',percent
    )),'[]'::jsonb)
  ) into result from paged;
  return result;
end $$;


ALTER FUNCTION "app_private"."attendance_dashboard_ranking_page"("p_start" "date", "p_end" "date", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid", "p_child_id" "uuid", "p_kind" "text", "p_direction" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_dashboard_read"("p_start" "date", "p_end" "date", "p_granularity" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid", "p_child_id" "uuid", "p_search" "text", "p_statuses" "text"[], "p_responsible_id" "uuid", "p_sort" "text", "p_desc" boolean, "p_page" integer, "p_page_size" integer, "p_ranking_direction" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid:=app_private.current_person_id();
  access_payload jsonb;
  result jsonb;
  previous_start date;
  days integer;
begin
  if actor is null then raise insufficient_privilege using message='authentication required'; end if;
  if p_start is null or p_end is null or p_start>p_end
     or p_end-p_start>366 then raise invalid_parameter_value using message='invalid attendance period'; end if;
  if p_granularity not in('daily','weekly','monthly')
     or p_sort not in('context','date','responsible','presence','status')
     or p_page<1 or p_page_size not between 1 and 100
     or p_ranking_direction not in('highest','lowest')
     or coalesce(length(p_search),0)>120 then
    raise invalid_parameter_value using message='invalid dashboard query';
  end if;
  if p_statuses is not null and exists(
    select 1 from unnest(p_statuses) value where value not in('pending','completed','inReview')
  ) then raise invalid_parameter_value using message='invalid attendance status'; end if;

  access_payload:=app_private.attendance_dashboard_access();
  if access_payload->>'scope'='guardian' and (
    p_institution_id is not null or p_unit_id is not null or p_group_id is not null
    or p_activity_id is not null or p_responsible_id is not null
  ) then
    raise insufficient_privilege using message='filter outside attendance scope';
  end if;
  days:=p_end-p_start+1;
  previous_start:=p_start-days;

  with authorized_sessions as materialized (
    select session.*,institution.public_name as institution_name,unit_record.name as unit_name,
      group_record.name as group_name,activity.name as activity_name,
      responsible.display_name as responsible_name
    from public.attendance_sessions session
    join public.institutions institution on institution.id=session.institution_id
    join public.units unit_record on unit_record.id=session.unit_id
    join public.groups group_record on group_record.id=session.group_id
    left join public.activity_definitions activity on activity.id=session.activity_id
    join public.people responsible on responsible.id=session.created_by_person_id
    where session.session_date between previous_start and p_end and session.status<>'cancelled'
      and (p_institution_id is null or session.institution_id=p_institution_id)
      and (p_unit_id is null or session.unit_id=p_unit_id)
      and (p_group_id is null or session.group_id=p_group_id)
      and (p_activity_id is null or session.activity_id=p_activity_id)
      and (p_responsible_id is null or session.created_by_person_id=p_responsible_id)
      and (
        app_private.can_access_attendance_child(
          session.institution_id,session.unit_id,session.group_id,session.activity_id,p_child_id,false)
        or (p_child_id is null and exists(
          select 1 from public.attendance_expected_participants expected
          where expected.attendance_session_id=session.id and expected.status='active'
            and app_private.can_access_attendance_child(
              session.institution_id,session.unit_id,session.group_id,session.activity_id,
              expected.child_context_id,false)
        ))
      )
  ), official_records as materialized (
    select session.*,record.child_context_id,record.outcome
    from authorized_sessions session
    join public.attendance_records record
      on record.attendance_session_id=session.id and record.status='active'
    where session.status in('closed','corrected')
      and (p_child_id is null or record.child_context_id=p_child_id)
      and app_private.can_access_attendance_child(
        session.institution_id,session.unit_id,session.group_id,session.activity_id,
        record.child_context_id,false)
  ), current_metrics as (
    select count(*)::integer as official_records,
      count(*) filter(where outcome in('present','late_arrival','early_departure','late_and_early'))::integer as numerator,
      count(*) filter(where outcome='absent')::integer as absences
    from official_records where session_date between p_start and p_end
  ), pending as (
    select count(*)::integer as count from authorized_sessions
    where session_date between p_start and p_end and status in('draft','open','reopened')
  ), reviews as (
    select count(*)::integer as count
    from public.attendance_notices notice
    where notice.review_status='pending' and notice.cancelled_at is null
      and (notice.starts_at at time zone 'UTC')::date between p_start and p_end
      and (p_institution_id is null or notice.institution_id=p_institution_id)
      and (p_unit_id is null or notice.unit_id=p_unit_id)
      and (p_group_id is null or notice.group_id=p_group_id)
      and (p_activity_id is null or notice.activity_id=p_activity_id)
      and (p_child_id is null or notice.child_context_id=p_child_id)
      and app_private.can_access_attendance_child(
        notice.institution_id,notice.unit_id,notice.group_id,notice.activity_id,
        notice.child_context_id,false)
  ), calls_base as (
    select session.id,
      concat_ws(' · ',session.institution_name,session.unit_name,session.group_name,session.activity_name) as context,
      session.session_date,session.responsible_name,session.created_by_person_id,
      case when session.status in('closed','corrected') then 'completed' else 'pending' end as dashboard_status,
      count(record.*) filter(where record.status='active')::integer as official_records,
      count(record.*) filter(where record.status='active' and record.outcome in('present','late_arrival','early_departure','late_and_early'))::integer as numerator,
      count(record.*) filter(where record.status='active' and record.outcome='present')::integer as present,
      count(record.*) filter(where record.status='active' and record.outcome='absent')::integer as absent,
      count(record.*) filter(where record.status='active' and record.outcome in('late_arrival','late_and_early'))::integer as late
    from authorized_sessions session
    left join public.attendance_records record
      on record.attendance_session_id=session.id
     and app_private.can_access_attendance_child(
       session.institution_id,session.unit_id,session.group_id,session.activity_id,
       record.child_context_id,false)
    where session.session_date between p_start and p_end
    group by session.id,session.institution_name,session.unit_name,session.group_name,
      session.activity_name,session.session_date,session.responsible_name,
      session.created_by_person_id,session.status
  ), calls_filtered as (
    select *,count(*) over()::integer as total_items from calls_base
    where (coalesce(btrim(p_search),'')='' or context ilike '%'||btrim(p_search)||'%')
      and (p_statuses is null or cardinality(p_statuses)=0 or dashboard_status=any(p_statuses))
  ), calls_page as (
    select * from calls_filtered
    order by
      case when p_sort='date' and p_desc then session_date end desc,
      case when p_sort='date' and not p_desc then session_date end asc,
      case when p_sort='context' and p_desc then context end desc,
      case when p_sort='context' and not p_desc then context end asc,
      case when p_sort='responsible' and p_desc then responsible_name end desc,
      case when p_sort='responsible' and not p_desc then responsible_name end asc,
      case when p_sort='status' and p_desc then dashboard_status end desc,
      case when p_sort='status' and not p_desc then dashboard_status end asc,
      case when p_sort='presence' and p_desc then numerator/nullif(official_records,0)::numeric end desc nulls last,
      case when p_sort='presence' and not p_desc then numerator/nullif(official_records,0)::numeric end asc nulls last,
      session_date desc,id
    offset (p_page-1)*p_page_size limit p_page_size
  ), series_raw as (
    select case p_granularity
        when 'weekly' then date_trunc('week',session_date::timestamp)::date
        when 'monthly' then date_trunc('month',session_date::timestamp)::date
        else session_date end as bucket,
      session_date>=p_start as current_period,count(*)::integer as official_records,
      count(*) filter(where outcome in('present','late_arrival','early_departure','late_and_early'))::integer as numerator,
      count(*) filter(where outcome='absent')::integer as absences,
      count(*) filter(where outcome in('late_arrival','late_and_early'))::integer as late
    from official_records
    group by 1,2
  ), current_series as (
    select *,row_number() over(order by bucket) as ordinal from series_raw where current_period
  ), previous_series as (
    select *,row_number() over(order by bucket) as ordinal from series_raw where not current_period
  ), series as (
    select current_series.bucket,current_series.official_records,current_series.numerator,
      current_series.absences,current_series.late,
      previous_series.official_records as previous_records,
      previous_series.numerator as previous_numerator
    from current_series left join previous_series using(ordinal)
  )
  select jsonb_build_object(
    'access',access_payload,
    'context_label',case when access_payload->>'scope'='guardian' then 'Todas as crianças'
      else coalesce((select public_name from public.institutions where id=p_institution_id),'Todas as instituições') end,
    'kpis',jsonb_build_object(
      'presence',jsonb_build_object('official_records',metrics.official_records,
        'percent',case when metrics.official_records=0 then null else metrics.numerator::numeric/metrics.official_records*100 end),
      'pending_calls',pending.count,'absences',metrics.absences,'in_review',reviews.count
    ),
    'attention',jsonb_build_array(
      jsonb_build_object('id','pending-calls','label','Chamadas pendentes','detail','Aguardando conclusão','count',pending.count),
      jsonb_build_object('id','absences','label','Faltas no período','detail','Registros oficiais','count',metrics.absences),
      jsonb_build_object('id','reviews','label','Em revisão','detail','Avisos familiares pendentes','count',reviews.count)
    ),
    'rankings',case access_payload->>'scope'
      when 'platform' then jsonb_build_array(
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'institutions',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'units',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'groups',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'activities',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'students',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'teachers',p_ranking_direction,1,3))
      when 'institution' then jsonb_build_array(
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'units',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'groups',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'activities',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'students',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'teachers',p_ranking_direction,1,3))
      when 'guardian' then jsonb_build_array(
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'students',p_ranking_direction,1,3))
      else jsonb_build_array(
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'groups',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'activities',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'students',p_ranking_direction,1,3),
        app_private.attendance_dashboard_ranking_page(p_start,p_end,p_institution_id,p_unit_id,p_group_id,p_activity_id,p_child_id,'teachers',p_ranking_direction,1,3))
    end,
    'series',coalesce((select jsonb_agg(jsonb_build_object(
      'start',bucket,'label',to_char(bucket,'DD/MM'),'official_records',official_records,
      'percent',case when official_records=0 then null else numerator::numeric/official_records*100 end,
      'previous_official_records',previous_records,
      'previous_percent',case when previous_records=0 then null else previous_numerator::numeric/previous_records*100 end,
      'absences',absences,'late',late
    ) order by bucket) from series),'[]'::jsonb),
    'calls',jsonb_build_object(
      'page',p_page,'page_size',p_page_size,'total_items',coalesce((select max(total_items) from calls_page),0),
      'items',coalesce((select jsonb_agg(jsonb_build_object(
        'id',id,
        'context',case when access_payload->>'scope'='guardian' then 'Registro de assiduidade' else context end,
        'date',session_date,
        'responsible',case when access_payload->>'scope'='guardian' then 'Equipe responsável' else responsible_name end,
        'present',present,'absent',absent,'late',late,'official_records',official_records,
        'presence_percent',case when official_records=0 then null else numerator::numeric/official_records*100 end,
        'status',dashboard_status,'can_open',access_payload->>'scope'<>'guardian'
      ) order by session_date desc,id) from calls_page),'[]'::jsonb)
    )
  ) into result
  from current_metrics metrics cross join pending cross join reviews;
  return result;
end $$;


ALTER FUNCTION "app_private"."attendance_dashboard_read"("p_start" "date", "p_end" "date", "p_granularity" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid", "p_child_id" "uuid", "p_search" "text", "p_statuses" "text"[], "p_responsible_id" "uuid", "p_sort" "text", "p_desc" boolean, "p_page" integer, "p_page_size" integer, "p_ranking_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_dashboard_request_export"("p_request_id" "uuid", "p_kind" "text", "p_format" "text", "p_filters" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  access_payload jsonb;
begin
  if actor is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  if p_request_id is null or p_kind not in ('overview','table') or p_format not in ('csv','xlsx')
     or p_filters is null or jsonb_typeof(p_filters) <> 'object' then
    raise invalid_parameter_value using message = 'invalid attendance export request';
  end if;
  access_payload := app_private.attendance_dashboard_access();
  if access_payload->>'scope' = 'guardian' then
    raise insufficient_privilege using message = 'attendance.export required';
  end if;
  return jsonb_build_object(
    'id', p_request_id,
    'job_id', p_request_id,
    'state', 'failed',
    'file_name', null,
    'download_url', null,
    'error_code', 'EXPORT_UNAVAILABLE',
    'message', 'Exportação de assiduidade adiada para depois do MVP (ADR 0034).'
  );
end $$;


ALTER FUNCTION "app_private"."attendance_dashboard_request_export"("p_request_id" "uuid", "p_kind" "text", "p_format" "text", "p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_intent_digest"("p_command" "text", "p_aggregate_id" "uuid", "p_expected_version" bigint, "p_scope" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_command not in (
    'create_call','set_participant','mark_remaining_present',
    'clear_presence_marks','complete_call','reopen_call','undo_bulk'
  ) then
    raise invalid_parameter_value using message='invalid attendance command';
  end if;

  if p_command = 'create_call' then
    if p_scope is null
      or coalesce(btrim(p_scope->>'institution_id'), '') = ''
      or coalesce(btrim(p_scope->>'group_id'), '') = ''
      or coalesce(btrim(p_scope->>'session_date'), '') = '' then
      raise invalid_parameter_value using message='attendance call scope required';
    end if;
    return 'create_call:'
      || lower(btrim(p_scope->>'institution_id')) || ':'
      || lower(btrim(coalesce(p_scope->>'unit_id', ''))) || ':'
      || lower(btrim(p_scope->>'group_id')) || ':'
      || lower(btrim(coalesce(p_scope->>'activity_id', ''))) || ':'
      || ((p_scope->>'session_date')::date)::text;
  end if;

  if p_aggregate_id is null then
    raise invalid_parameter_value using message='attendance aggregate required';
  end if;
  -- Versao esperada faz parte da intencao: depois que a chamada avanca, a
  -- intencao antiga deixou de existir e a proxima reserva recebe outra chave.
  return p_command || ':' || p_aggregate_id::text || ':'
    || coalesce(p_expected_version::text, '');
end
$$;


ALTER FUNCTION "app_private"."attendance_intent_digest"("p_command" "text", "p_aggregate_id" "uuid", "p_expected_version" bigint, "p_scope" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."attendance_notices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "group_id" "uuid" NOT NULL,
    "activity_id" "uuid",
    "child_context_id" "uuid" NOT NULL,
    "child_group_link_id" "uuid" NOT NULL,
    "guardian_link_id" "uuid" NOT NULL,
    "notice_type" "text" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone,
    "reason_id" "uuid",
    "reason_detail" "text",
    "note" "text",
    "review_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "reviewed_by_person_id" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_note" "text",
    "created_by_person_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cancelled_at" timestamp with time zone,
    CONSTRAINT "attendance_notices_dates_check" CHECK ((("ends_at" IS NULL) OR ("ends_at" >= "starts_at"))),
    CONSTRAINT "attendance_notices_detail_check" CHECK ((("reason_detail" IS NULL) OR ("btrim"("reason_detail") <> ''::"text"))),
    CONSTRAINT "attendance_notices_notice_type_check" CHECK (("notice_type" = ANY (ARRAY['absence'::"text", 'expected_presence'::"text", 'late_arrival'::"text", 'early_departure'::"text"]))),
    CONSTRAINT "attendance_notices_review_check" CHECK (((("review_status" = 'pending'::"text") AND ("reviewed_by_person_id" IS NULL) AND ("reviewed_at" IS NULL)) OR (("review_status" = ANY (ARRAY['confirmed'::"text", 'rejected'::"text"])) AND ("reviewed_by_person_id" IS NOT NULL) AND ("reviewed_at" IS NOT NULL)))),
    CONSTRAINT "attendance_notices_review_status_check" CHECK (("review_status" = ANY (ARRAY['pending'::"text", 'confirmed'::"text", 'rejected'::"text"])))
);

ALTER TABLE ONLY "public"."attendance_notices" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."attendance_notices" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_notice_payload"("p_notice" "public"."attendance_notices") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', p_notice.id,
    'call_id', (
      select session_row.id from public.attendance_sessions session_row
      where session_row.group_id = p_notice.group_id
        and session_row.activity_id is not distinct from p_notice.activity_id
        and session_row.status <> 'cancelled'
        and session_row.session_date between (p_notice.starts_at at time zone 'UTC')::date
          and coalesce((p_notice.ends_at at time zone 'UTC')::date, (p_notice.starts_at at time zone 'UTC')::date)
      order by session_row.session_date desc, session_row.created_at desc limit 1
    ),
    'participant_id', p_notice.child_context_id,
    'participant_name', coalesce((
      select person.display_name from public.child_contexts child_context
      join public.people person on person.id = child_context.child_person_id
      where child_context.id = p_notice.child_context_id), ''),
    'intent', p_notice.notice_type,
    'reason', coalesce(p_notice.reason_detail, (
      select reason.name from public.attendance_reason_catalog reason where reason.id = p_notice.reason_id), ''),
    'start_date', (p_notice.starts_at at time zone 'UTC')::date,
    'end_date', (p_notice.ends_at at time zone 'UTC')::date,
    'note', coalesce(p_notice.note, ''),
    'pending', p_notice.review_status = 'pending' and p_notice.cancelled_at is null
  )
$$;


ALTER FUNCTION "app_private"."attendance_notice_payload"("p_notice" "public"."attendance_notices") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_replay_receipt"("p_actor" "uuid", "p_command" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reservation app_private.attendance_idempotency_reservations%rowtype;
begin
  if p_idempotency_key is null then
    raise invalid_parameter_value using message = 'attendance idempotency key required';
  end if;
  select * into reservation from app_private.attendance_idempotency_reservations
  where idempotency_key = p_idempotency_key and actor_person_id = p_actor
    and command = p_command
  for update;
  if reservation.id is null then
    raise invalid_parameter_value using message = 'attendance idempotency key not reserved';
  end if;
  return reservation.response;
end $$;


ALTER FUNCTION "app_private"."attendance_replay_receipt"("p_actor" "uuid", "p_command" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_require_call"("p_call_id" "uuid", "p_expected_version" bigint, "p_require_manage" boolean) RETURNS "public"."attendance_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  session_row public.attendance_sessions%rowtype;
begin
  if actor is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  if p_call_id is null then
    raise invalid_parameter_value using message = 'attendance call required';
  end if;
  select * into session_row from public.attendance_sessions
  where id = p_call_id and status <> 'cancelled' for update;
  if session_row.id is null or not app_private.can_access_attendance_child(
    session_row.institution_id, session_row.unit_id, session_row.group_id,
    session_row.activity_id, null, p_require_manage
  ) then
    raise insufficient_privilege using message = 'attendance call outside scope';
  end if;
  if p_expected_version is not null and p_expected_version <> session_row.version then
    raise exception using errcode = '40001',
      message = 'attendance call version conflict';
  end if;
  return session_row;
end $$;


ALTER FUNCTION "app_private"."attendance_require_call"("p_call_id" "uuid", "p_expected_version" bigint, "p_require_manage" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_reserve_idempotency_key"("p_command" "text", "p_aggregate_id" "uuid", "p_expected_version" bigint, "p_scope" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  digest text;
  reserved uuid;
begin
  if actor is null then
    raise insufficient_privilege using message='authentication required';
  end if;
  digest := app_private.attendance_intent_digest(
    p_command, p_aggregate_id, p_expected_version, p_scope);

  insert into app_private.attendance_idempotency_reservations(
    actor_person_id, command, aggregate_id, intent_digest, idempotency_key
  ) values (
    actor, p_command, p_aggregate_id, digest, gen_random_uuid()
  )
  on conflict (actor_person_id, command, intent_digest) do update
    set aggregate_id = excluded.aggregate_id
  returning idempotency_key into reserved;

  return reserved;
end
$$;


ALTER FUNCTION "app_private"."attendance_reserve_idempotency_key"("p_command" "text", "p_aggregate_id" "uuid", "p_expected_version" bigint, "p_scope" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_session_in_scope"("p_access" "jsonb", "p_session" "public"."attendance_sessions") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case p_access->>'scope'
    when 'platform' then true
    when 'institution' then p_session.institution_id = (p_access->>'institution_id')::uuid
    when 'unit' then p_session.institution_id = (p_access->>'institution_id')::uuid
      and p_session.unit_id = (p_access->>'unit_id')::uuid
    when 'assignments' then p_session.institution_id = (p_access->>'institution_id')::uuid
      and (
        (p_access->'assigned_group_ids') ? p_session.group_id::text
        or (p_session.activity_id is not null
          and (p_access->'assigned_activity_ids') ? p_session.activity_id::text)
      )
    else false end
  and app_private.can_access_attendance_child(
    p_session.institution_id, p_session.unit_id, p_session.group_id,
    p_session.activity_id, null, false)
$$;


ALTER FUNCTION "app_private"."attendance_session_in_scope"("p_access" "jsonb", "p_session" "public"."attendance_sessions") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_store_receipt"("p_actor" "uuid", "p_command" "text", "p_idempotency_key" "uuid", "p_aggregate_id" "uuid", "p_response" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update app_private.attendance_idempotency_reservations
     set consumed_at = coalesce(consumed_at, now()),
         aggregate_id = coalesce(aggregate_id, p_aggregate_id),
         response = p_response
   where idempotency_key = p_idempotency_key and actor_person_id = p_actor
     and command = p_command
$$;


ALTER FUNCTION "app_private"."attendance_store_receipt"("p_actor" "uuid", "p_command" "text", "p_idempotency_key" "uuid", "p_aggregate_id" "uuid", "p_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."attendance_write_state"("p_actor" "uuid", "p_session" "public"."attendance_sessions", "p_child_context_id" "uuid", "p_state" "text", "p_reason" "text", "p_note" "text" DEFAULT NULL::"text", "p_source_notice_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_record public.attendance_records%rowtype;
  new_record_id uuid;
begin
  if p_state not in ('unmarked','present','absent','late_arrival','early_departure','late_and_early') then
    raise invalid_parameter_value using message = 'invalid attendance state';
  end if;
  if not exists (
    select 1 from public.attendance_expected_participants expected
    where expected.attendance_session_id = p_session.id
      and expected.child_context_id = p_child_context_id
      and expected.status = 'active'
  ) then
    raise invalid_parameter_value using message = 'attendance participant not in call';
  end if;
  if not app_private.can_access_attendance_child(
    p_session.institution_id, p_session.unit_id, p_session.group_id,
    p_session.activity_id, p_child_context_id, true
  ) then
    raise insufficient_privilege using message = 'attendance participant outside scope';
  end if;

  select * into existing_record from public.attendance_records
  where attendance_session_id = p_session.id
    and child_context_id = p_child_context_id and status = 'active'
  for update;

  if p_state = 'unmarked' then
    if existing_record.id is null then
      return;
    end if;
    update public.attendance_records set
      status = 'inactive', reverted_by_person_id = p_actor, reverted_at = now(),
      revert_reason = coalesce(nullif(btrim(p_reason), ''), 'Marcação removida'),
      updated_at = now()
    where id = existing_record.id;
    insert into public.attendance_record_revisions(
      attendance_record_id, action_code, before_json, after_json, reason, changed_by_person_id
    ) select existing_record.id, 'reverted', to_jsonb(existing_record), to_jsonb(current_row),
      coalesce(nullif(btrim(p_reason), ''), 'Marcação removida'), p_actor
    from public.attendance_records current_row where current_row.id = existing_record.id;
    return;
  end if;

  if existing_record.id is null then
    insert into public.attendance_records(
      attendance_session_id, child_context_id, outcome, source_notice_id, note,
      confirmed_by_person_id
    ) values (
      p_session.id, p_child_context_id, p_state, p_source_notice_id,
      nullif(btrim(p_note), ''), p_actor
    ) returning id into new_record_id;
    insert into public.attendance_record_revisions(
      attendance_record_id, action_code, after_json, reason, changed_by_person_id
    ) select new_record_id, 'confirmed', to_jsonb(record_row), nullif(btrim(p_reason), ''), p_actor
    from public.attendance_records record_row where record_row.id = new_record_id;
  else
    if existing_record.outcome = p_state
       and existing_record.note is not distinct from nullif(btrim(p_note), '')
       and existing_record.source_notice_id is not distinct from coalesce(p_source_notice_id, existing_record.source_notice_id) then
      return;
    end if;
    update public.attendance_records set
      outcome = p_state,
      source_notice_id = coalesce(p_source_notice_id, source_notice_id),
      note = coalesce(nullif(btrim(p_note), ''), note),
      confirmed_by_person_id = p_actor, confirmed_at = now(), updated_at = now()
    where id = existing_record.id;
    insert into public.attendance_record_revisions(
      attendance_record_id, action_code, before_json, after_json, reason, changed_by_person_id
    ) select existing_record.id, 'corrected', to_jsonb(existing_record), to_jsonb(record_row),
      nullif(btrim(p_reason), ''), p_actor
    from public.attendance_records record_row where record_row.id = existing_record.id;
  end if;
end $$;


ALTER FUNCTION "app_private"."attendance_write_state"("p_actor" "uuid", "p_session" "public"."attendance_sessions", "p_child_context_id" "uuid", "p_state" "text", "p_reason" "text", "p_note" "text", "p_source_notice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_activity_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare row_data jsonb; before_data jsonb; after_data jsonb; target_institution_id uuid;
 target_object_id uuid; actor_person_id uuid; actor_membership_id uuid; marker_text text;
 marker jsonb; fresh app_private.superadmin_internal_context; suppress_legacy boolean:=false;
begin
  before_data:=case when tg_op in('UPDATE','DELETE') then to_jsonb(old) else null end;
  after_data:=case when tg_op in('INSERT','UPDATE') then to_jsonb(new) else null end;
  row_data:=coalesce(after_data,before_data); target_object_id:=(row_data->>'id')::uuid;
  if row_data?'institution_id' then target_institution_id:=(row_data->>'institution_id')::uuid;
  elsif tg_table_name='activity_permission_profile_capabilities' then select p.institution_id into target_institution_id from public.activity_permission_profiles p where p.id=(row_data->>'profile_id')::uuid;
  elsif tg_table_name='activity_assignment_permission_overrides' then select a.institution_id into target_institution_id from public.activity_group_assignments a where a.id=(row_data->>'assignment_id')::uuid; end if;
  marker_text:=nullif(current_setting('app_private.activity_v2_internal_marker',true),'');
  if marker_text is not null then
    begin
      marker:=marker_text::jsonb;
      perform app_private.require_activity_v2_internal_marker();
      select * into strict fresh from app_private.activity_v2_require_context(marker->>'permission_code',target_institution_id);
      suppress_legacy:=marker->>'internal_identity_id'=fresh.internal_identity_id::text
       and marker->>'internal_auth_link_id'=fresh.internal_auth_link_id::text
       and marker->>'internal_membership_id'=fresh.internal_membership_id::text
       and marker->>'auth_user_id'=fresh.auth_user_id::text
       and marker->>'session_id'=fresh.session_id::text;
    exception when others then suppress_legacy:=false; end;
    if suppress_legacy then return coalesce(new,old); end if;
  end if;
  actor_person_id:=app_private.current_person_id();
  select m.id into actor_membership_id from public.institution_memberships m where m.person_id=actor_person_id and m.institution_id=target_institution_id and m.status='active' and m.revoked_at is null limit 1;
  insert into audit.audit_logs(actor_person_id,actor_membership_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,reason,before_json,after_json)
  values(actor_person_id,actor_membership_id,auth.jwt()->>'aal','activity_'||lower(tg_op),tg_table_name,target_object_id,target_institution_id,'success',nullif(current_setting('coelo.audit_reason',true),''),before_data,after_data);
  return coalesce(new,old);
end $$;


ALTER FUNCTION "app_private"."audit_activity_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_actor_has_permission"("p_actor_person_id" "uuid", "p_permission_code" "text", "p_institution_id" "uuid" DEFAULT NULL::"uuid", "p_any_scope" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with memberships as (
    select membership.id,membership.role_id
    from public.platform_memberships membership
    join public.platform_roles role_record on role_record.id=membership.role_id
    where membership.person_id=p_actor_person_id
      and membership.status='active' and membership.revoked_at is null
      and role_record.status='active'
      and (
        p_any_scope
        or (p_institution_id is null and membership.scope_kind='platform' and membership.scope_institution_id is null)
        or (p_institution_id is not null and (
          (membership.scope_kind='platform' and membership.scope_institution_id is null)
          or (membership.scope_kind='institution' and membership.scope_institution_id=p_institution_id)
        ))
      )
  ), target as (
    select id from public.platform_permissions where code=p_permission_code and status='active'
  ), effects as (
    select grant_record.effect from memberships
    join public.platform_role_permissions grant_record on grant_record.role_id=memberships.role_id
      and grant_record.status='active' and grant_record.revoked_at is null
    join target on target.id=grant_record.permission_id
    union all
    select override_record.effect from memberships
    join public.platform_member_permission_overrides override_record on override_record.membership_id=memberships.id
      and override_record.status='active'
      and (override_record.starts_at is null or override_record.starts_at<=now())
      and (override_record.expires_at is null or override_record.expires_at>now())
    join target on target.id=override_record.permission_id
  )
  select exists(select 1 from effects where effect='allow')
    and not exists(select 1 from effects where effect='deny')
$$;


ALTER FUNCTION "app_private"."audit_actor_has_permission"("p_actor_person_id" "uuid", "p_permission_code" "text", "p_institution_id" "uuid", "p_any_scope" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_append_auth_session_denial"("p_session_id" "uuid", "p_permission_code" "text", "p_aal" "text", "p_action_code" "text", "p_reason_code" "text", "p_correlation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare event_id uuid:=gen_random_uuid();
begin
  insert into audit.audit_logs(
    id,hash_version,actor_kind,session_id_hash,permission_code,mfa_aal,action_code,
    outcome,reason_code,correlation_id,origin,context_kind,occurred_at)
  values(
    event_id,3,'auth_session',extensions.digest(
      pg_catalog.convert_to(p_session_id::text,'UTF8'),'sha256'),
    p_permission_code,p_aal,p_action_code,'denied',p_reason_code,
    p_correlation_id,'database','global',pg_catalog.now());
  return event_id;
end
$$;


