CREATE OR REPLACE FUNCTION "app_private"."audit_assert_permission"("p_permission_code" "text", "p_require_aal2" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();v_authorization jsonb;
begin
  if (select auth.uid()) is null or actor is null then
    raise insufficient_privilege using message=case when p_permission_code='audit.read' then 'audit.read required' else 'audit.export and AAL2 required' end;
  end if;
  v_authorization:=app_private.audit_authorization_scope(actor,p_permission_code);
  if (not coalesce((v_authorization->>'global')::boolean,false)
      and jsonb_array_length(coalesce(v_authorization->'institution_ids','[]'::jsonb))=0)
    or (p_require_aal2 and not app_private.has_mfa_aal2()) then
    raise insufficient_privilege using message=case when p_permission_code='audit.read' then 'audit.read required' else 'audit.export and AAL2 required' end;
  end if;
  return actor;
end;
$$;


ALTER FUNCTION "app_private"."audit_assert_permission"("p_permission_code" "text", "p_require_aal2" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_assert_worker"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce((select auth.jwt()->>'role'),
      nullif(current_setting('request.jwt.claim.role',true),''),
      nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','') <> 'service_role' then
    raise insufficient_privilege using message='audit worker authorization required';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."audit_assert_worker"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_authorization_scope"("p_actor_person_id" "uuid", "p_permission_code" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'global',app_private.audit_actor_has_permission(p_actor_person_id,p_permission_code,null,false),
    'institution_ids',coalesce((select jsonb_agg(scope.institution_id order by scope.institution_id)
      from (select distinct membership.scope_institution_id institution_id
        from public.platform_memberships membership
        where membership.person_id=p_actor_person_id and membership.status='active'
          and membership.revoked_at is null and membership.scope_kind='institution'
          and membership.scope_institution_id is not null
          and app_private.audit_actor_has_permission(p_actor_person_id,p_permission_code,
            membership.scope_institution_id,false)) scope),'[]'::jsonb),
    'denied_institution_ids',coalesce((select jsonb_agg(scope.institution_id order by scope.institution_id)
      from (select distinct membership.scope_institution_id institution_id
        from public.platform_memberships membership
        where membership.person_id=p_actor_person_id and membership.status='active'
          and membership.revoked_at is null and membership.scope_kind='institution'
          and membership.scope_institution_id is not null
          and not app_private.audit_actor_has_permission(p_actor_person_id,p_permission_code,
            membership.scope_institution_id,false)) scope),'[]'::jsonb)
  )
$$;


ALTER FUNCTION "app_private"."audit_authorization_scope"("p_actor_person_id" "uuid", "p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_authorize_export_download_for_superadmin"("p_export_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid;job public.import_jobs%rowtype;authorized_job jsonb;expires_at timestamptz;
begin
  actor:=app_private.audit_assert_permission('audit.export',true);
  perform app_private.audit_assert_permission('audit.read',false);
  authorized_job:=app_private.audit_get_export_job_for_superadmin(p_export_job_id);
  if authorized_job is null then return null; end if;
  select * into job from public.import_jobs where id=p_export_job_id
    and target_domain='audit_export' and created_by=actor and processing_state='SUCESSO';
  if job.id is null then return null; end if;
  begin
    expires_at:=(job.summary->>'retention_expires_at')::timestamptz;
  exception when others then return null;
  end;
  if expires_at is null or expires_at<=now() or nullif(job.summary->>'storage_path','') is null then
    return null;
  end if;
  return jsonb_build_object('job_id',job.id,'storage_path',job.summary->>'storage_path',
    'format',job.source_format,'row_count',job.summary->'row_count','retention_expires_at',expires_at);
end;
$$;


ALTER FUNCTION "app_private"."audit_authorize_export_download_for_superadmin"("p_export_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_complete_export_for_worker"("p_export_job_id" "uuid", "p_worker_token" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare job public.import_jobs%rowtype;expected_mime text;
  read_authorization jsonb;export_authorization jsonb;
begin
  perform app_private.audit_assert_worker();
  select * into job from public.import_jobs where id=p_export_job_id for update;
  expected_mime:=case job.source_format when 'csv' then 'text/csv'
    else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' end;
  if job.id is null or job.target_domain<>'audit_export' or job.processing_state<>'PROCESSANDO'
    or not exists(select 1 from app_private.audit_export_worker_claims
      where export_job_id=job.id and worker_token=p_worker_token and lease_until>now())
    or p_storage_path !~ ('^exports/audit/'||job.id||'/[0-9a-f-]+\.'||job.source_format||'$')
    or p_mime_type<>expected_mime or p_size_bytes not between 1 and 5242880
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$' or p_row_count<1
    or p_row_count<>(select count(*) from app_private.audit_export_snapshot_rows where export_job_id=job.id)
    or not exists(select 1 from storage.objects object_record
      where object_record.bucket_id='coelo-operations' and object_record.name=p_storage_path) then
    raise invalid_parameter_value using message='invalid audit export artifact';
  end if;
  read_authorization:=app_private.audit_authorization_scope(job.created_by,'audit.read');
  export_authorization:=app_private.audit_authorization_scope(job.created_by,'audit.export');
  if (not coalesce((read_authorization->>'global')::boolean,false)
      and jsonb_array_length(coalesce(read_authorization->'institution_ids','[]'::jsonb))=0)
    or (not coalesce((export_authorization->>'global')::boolean,false)
      and jsonb_array_length(coalesce(export_authorization->'institution_ids','[]'::jsonb))=0)
    or exists(
      select 1 from app_private.audit_export_snapshot_rows snapshot
      join audit.audit_logs log_record on log_record.id=snapshot.audit_log_id
      where snapshot.export_job_id=job.id
        and (not app_private.audit_actor_has_permission(job.created_by,'audit.read',log_record.institution_id,false)
          or not app_private.audit_actor_has_permission(job.created_by,'audit.export',log_record.institution_id,false))
    ) then
    raise insufficient_privilege using message='audit export authorization revoked';
  end if;
  insert into public.import_files(import_job_id,storage_path,file_name,mime_type,size_bytes,
    checksum_sha256,expires_at)
  values(job.id,p_storage_path,left(p_file_name,180),p_mime_type,p_size_bytes,
    p_checksum_sha256,now()+interval '24 hours');
  update public.import_results set completed_at=now() where import_job_id=job.id;
  update public.import_jobs set processing_state='SUCESSO',status='active',finished_at=now(),updated_at=now(),
    summary=summary||jsonb_build_object('phase','complete','storage_path',p_storage_path,
      'row_count',p_row_count,'retention_expires_at',now()+interval '24 hours') where id=job.id;
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,
    origin,context_kind,payload_contract_version,after_json)
  values(job.created_by,'aal2','audit.export.complete','import_job',job.id,'success','edge_function','global',1,
    jsonb_build_object('format',job.source_format,'state','SUCESSO','row_count',p_row_count,'pii_included',true));
  return jsonb_build_object('job_id',job.id,'state','SUCESSO','format',job.source_format,
    'row_count',p_row_count);
end;
$_$;


ALTER FUNCTION "app_private"."audit_complete_export_for_worker"("p_export_job_id" "uuid", "p_worker_token" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_contextual_sensitive_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  row_json jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  target_institution_id uuid;
begin
  select membership.institution_id into target_institution_id
  from public.institution_memberships membership
  where membership.id = (row_json ->> 'membership_id')::uuid;

  insert into audit.audit_logs(
    actor_person_id, action_code, object_type, object_id, institution_id,
    before_json, after_json
  ) values (
    app_private.current_person_id(),
    lower(tg_table_name || '.' || tg_op),
    tg_table_name,
    (row_json ->> 'id')::uuid,
    target_institution_id,
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end
  );
  return coalesce(new, old);
end
$$;


ALTER FUNCTION "app_private"."audit_contextual_sensitive_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_entry_digest"("p_chain_position" bigint, "p_previous_hash" "bytea", "p_id" "uuid", "p_actor_person_id" "uuid", "p_actor_role_code" "text", "p_correlation_id" "uuid", "p_origin" "text", "p_context_kind" "text", "p_context_id" "uuid", "p_action_code" "text", "p_object_type" "text", "p_object_id" "uuid", "p_institution_id" "uuid", "p_outcome" "public"."audit_outcome", "p_reason" "text", "p_before_json" "jsonb", "p_after_json" "jsonb", "p_occurred_at" timestamp with time zone) RETURNS "bytea"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select extensions.digest(pg_catalog.convert_to(jsonb_build_object(
    'chain_position',p_chain_position,
    'previous_hash',case when p_previous_hash is null then null else encode(p_previous_hash,'hex') end,
    'id',p_id,'actor_person_id',p_actor_person_id,'actor_role_code',p_actor_role_code,
    'correlation_id',p_correlation_id,'origin',p_origin,'context_kind',p_context_kind,
    'context_id',p_context_id,'action_code',p_action_code,'object_type',p_object_type,
    'object_id',p_object_id,'institution_id',p_institution_id,'outcome',p_outcome,
    'reason',p_reason,'before',p_before_json,'after',p_after_json,'occurred_at',p_occurred_at
  )::text,'UTF8'),'sha256')
$$;


ALTER FUNCTION "app_private"."audit_entry_digest"("p_chain_position" bigint, "p_previous_hash" "bytea", "p_id" "uuid", "p_actor_person_id" "uuid", "p_actor_role_code" "text", "p_correlation_id" "uuid", "p_origin" "text", "p_context_kind" "text", "p_context_id" "uuid", "p_action_code" "text", "p_object_type" "text", "p_object_id" "uuid", "p_institution_id" "uuid", "p_outcome" "public"."audit_outcome", "p_reason" "text", "p_before_json" "jsonb", "p_after_json" "jsonb", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_entry_digest_v2"("p_hash_version" smallint, "p_chain_position" bigint, "p_previous_hash" "bytea", "p_id" "uuid", "p_actor_person_id" "uuid", "p_actor_membership_id" "uuid", "p_support_session_id" "uuid", "p_actor_kind" "text", "p_actor_internal_identity_id" "uuid", "p_actor_internal_auth_link_id" "uuid", "p_actor_internal_membership_id" "uuid", "p_session_id_hash" "bytea", "p_permission_code" "text", "p_mfa_aal" "text", "p_reason_code" "text", "p_actor_role_code" "text", "p_correlation_id" "uuid", "p_origin" "text", "p_context_kind" "text", "p_context_id" "uuid", "p_action_code" "text", "p_object_type" "text", "p_object_id" "uuid", "p_institution_id" "uuid", "p_outcome" "public"."audit_outcome", "p_reason" "text", "p_payload_contract_version" smallint, "p_before_json" "jsonb", "p_after_json" "jsonb", "p_occurred_at" timestamp with time zone) RETURNS "bytea"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select extensions.digest(pg_catalog.convert_to(pg_catalog.jsonb_build_object(
    'hash_version',p_hash_version,'chain_position',p_chain_position,
    'previous_hash',case when p_previous_hash is null then null else pg_catalog.encode(p_previous_hash,'hex') end,
    'id',p_id,'actor_person_id',p_actor_person_id,
    'actor_membership_id',p_actor_membership_id,'support_session_id',p_support_session_id,
    'actor_kind',p_actor_kind,
    'actor_internal_identity_id',p_actor_internal_identity_id,
    'actor_internal_auth_link_id',p_actor_internal_auth_link_id,
    'actor_internal_membership_id',p_actor_internal_membership_id,
    'session_id_hash',pg_catalog.encode(p_session_id_hash,'hex'),
    'permission_code',p_permission_code,'mfa_aal',p_mfa_aal,'reason_code',p_reason_code,
    'actor_role_code',p_actor_role_code,
    'correlation_id',p_correlation_id,'origin',p_origin,'context_kind',p_context_kind,
    'context_id',p_context_id,'action_code',p_action_code,
    'object_type',p_object_type,'object_id',p_object_id,'institution_id',p_institution_id,
    'outcome',p_outcome,'reason',p_reason,
    'payload_contract_version',p_payload_contract_version,'before',p_before_json,
    'after',p_after_json,'occurred_at',p_occurred_at
  )::text,'UTF8'),'sha256')
$$;


ALTER FUNCTION "app_private"."audit_entry_digest_v2"("p_hash_version" smallint, "p_chain_position" bigint, "p_previous_hash" "bytea", "p_id" "uuid", "p_actor_person_id" "uuid", "p_actor_membership_id" "uuid", "p_support_session_id" "uuid", "p_actor_kind" "text", "p_actor_internal_identity_id" "uuid", "p_actor_internal_auth_link_id" "uuid", "p_actor_internal_membership_id" "uuid", "p_session_id_hash" "bytea", "p_permission_code" "text", "p_mfa_aal" "text", "p_reason_code" "text", "p_actor_role_code" "text", "p_correlation_id" "uuid", "p_origin" "text", "p_context_kind" "text", "p_context_id" "uuid", "p_action_code" "text", "p_object_type" "text", "p_object_id" "uuid", "p_institution_id" "uuid", "p_outcome" "public"."audit_outcome", "p_reason" "text", "p_payload_contract_version" smallint, "p_before_json" "jsonb", "p_after_json" "jsonb", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_entry_digest_v3"("p_chain_position" bigint, "p_previous_hash" "bytea", "p_id" "uuid", "p_session_id_hash" "bytea", "p_permission_code" "text", "p_mfa_aal" "text", "p_reason_code" "text", "p_correlation_id" "uuid", "p_origin" "text", "p_context_kind" "text", "p_context_id" "uuid", "p_action_code" "text", "p_object_type" "text", "p_object_id" "uuid", "p_institution_id" "uuid", "p_outcome" "public"."audit_outcome", "p_payload_contract_version" smallint, "p_before_json" "jsonb", "p_after_json" "jsonb", "p_occurred_at" timestamp with time zone) RETURNS "bytea"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select extensions.digest(pg_catalog.convert_to(pg_catalog.jsonb_build_object(
    'hash_version',3,'chain_position',p_chain_position,
    'previous_hash',case when p_previous_hash is null then null else pg_catalog.encode(p_previous_hash,'hex') end,
    'id',p_id,'actor_kind','auth_session',
    'session_id_hash',pg_catalog.encode(p_session_id_hash,'hex'),
    'permission_code',p_permission_code,'mfa_aal',p_mfa_aal,
    'reason_code',p_reason_code,'correlation_id',p_correlation_id,
    'origin',p_origin,'context_kind',p_context_kind,'context_id',p_context_id,
    'action_code',p_action_code,'object_type',p_object_type,'object_id',p_object_id,
    'institution_id',p_institution_id,'outcome',p_outcome,
    'payload_contract_version',p_payload_contract_version,'before',p_before_json,
    'after',p_after_json,'occurred_at',p_occurred_at
  )::text,'UTF8'),'sha256')
$$;


ALTER FUNCTION "app_private"."audit_entry_digest_v3"("p_chain_position" bigint, "p_previous_hash" "bytea", "p_id" "uuid", "p_session_id_hash" "bytea", "p_permission_code" "text", "p_mfa_aal" "text", "p_reason_code" "text", "p_correlation_id" "uuid", "p_origin" "text", "p_context_kind" "text", "p_context_id" "uuid", "p_action_code" "text", "p_object_type" "text", "p_object_id" "uuid", "p_institution_id" "uuid", "p_outcome" "public"."audit_outcome", "p_payload_contract_version" smallint, "p_before_json" "jsonb", "p_after_json" "jsonb", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_entry_matches_digest"("p_log" "audit"."audit_logs") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case p_log.hash_version
    when 1 then p_log.entry_hash=app_private.audit_entry_digest(
      p_log.chain_position,p_log.previous_hash,p_log.id,p_log.actor_person_id,
      p_log.actor_role_code,p_log.correlation_id,p_log.origin,p_log.context_kind,
      p_log.context_id,p_log.action_code,p_log.object_type,p_log.object_id,
      p_log.institution_id,p_log.outcome,p_log.reason,p_log.before_json,
      p_log.after_json,p_log.occurred_at)
    when 2 then p_log.entry_hash=app_private.audit_entry_digest_v2(
      p_log.hash_version,p_log.chain_position,p_log.previous_hash,p_log.id,
      p_log.actor_person_id,p_log.actor_membership_id,p_log.support_session_id,p_log.actor_kind,
      p_log.actor_internal_identity_id,p_log.actor_internal_auth_link_id,
      p_log.actor_internal_membership_id,p_log.session_id_hash,p_log.permission_code,
      p_log.mfa_aal,p_log.reason_code,p_log.actor_role_code,p_log.correlation_id,
      p_log.origin,p_log.context_kind,p_log.context_id,p_log.action_code,
      p_log.object_type,p_log.object_id,p_log.institution_id,p_log.outcome,
      p_log.reason,p_log.payload_contract_version,p_log.before_json,
      p_log.after_json,p_log.occurred_at)
    when 3 then p_log.entry_hash=app_private.audit_entry_digest_v3(
      p_log.chain_position,p_log.previous_hash,p_log.id,p_log.session_id_hash,
      p_log.permission_code,p_log.mfa_aal,p_log.reason_code,p_log.correlation_id,
      p_log.origin,p_log.context_kind,p_log.context_id,p_log.action_code,
      p_log.object_type,p_log.object_id,p_log.institution_id,p_log.outcome,
      p_log.payload_contract_version,p_log.before_json,p_log.after_json,p_log.occurred_at)
    else false end
$$;


ALTER FUNCTION "app_private"."audit_entry_matches_digest"("p_log" "audit"."audit_logs") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_expire_export_for_worker"("p_export_job_id" "uuid", "p_storage_path" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job public.import_jobs%rowtype;
begin
  perform app_private.audit_assert_worker();
  select * into job from public.import_jobs where id=p_export_job_id for update;
  if job.id is null or job.target_domain<>'audit_export'
    or job.processing_state<>'SUCESSO'
    or job.summary->>'storage_path' is distinct from p_storage_path
    or (job.summary->>'retention_expires_at')::timestamptz>now()
    or exists(select 1 from storage.objects where bucket_id='coelo-operations' and name=p_storage_path) then
    raise invalid_parameter_value using message='audit export cannot be expired';
  end if;
  -- Deleting the job is the canonical EXPIRADO/not-found state. Cascades erase
  -- import_files, the materialized PII snapshot and the worker claim together.
  delete from public.import_jobs where id=job.id;
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,
    outcome,origin,context_kind,payload_contract_version,after_json)
  values(job.created_by,'aal2','audit.export.expired','import_job',job.id,'success',
    'edge_function','global',1,jsonb_build_object('state','EXPIRADO'));
end;
$$;


ALTER FUNCTION "app_private"."audit_expire_export_for_worker"("p_export_job_id" "uuid", "p_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_expired_artifacts_for_worker"("p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.audit_assert_worker();
  if p_limit not between 1 and 25 then
    raise invalid_parameter_value using message='invalid audit cleanup limit';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('job_id',job.id,
      'storage_path',job.summary->>'storage_path') order by job.finished_at),'[]'::jsonb)
    into result
  from (select * from public.import_jobs candidate
    where candidate.target_domain='audit_export' and candidate.processing_state='SUCESSO'
      and (candidate.summary->>'retention_expires_at')::timestamptz<=now()
      and nullif(candidate.summary->>'storage_path','') is not null
    order by candidate.finished_at limit p_limit) job;
  return result;
end;
$$;


ALTER FUNCTION "app_private"."audit_expired_artifacts_for_worker"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_export_artifact_for_worker"("p_export_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.audit_assert_worker();
  select jsonb_build_object('storage_path',job.summary->>'storage_path','format',job.source_format,
      'retention_expires_at',job.summary->'retention_expires_at','row_count',job.summary->'row_count')
    into result from public.import_jobs job where job.id=p_export_job_id
      and job.target_domain='audit_export' and job.processing_state='SUCESSO';
  return result;
end;
$$;


ALTER FUNCTION "app_private"."audit_export_artifact_for_worker"("p_export_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_export_page_for_worker"("p_export_job_id" "uuid", "p_worker_token" "uuid", "p_after_ordinal" bigint DEFAULT NULL::bigint, "p_page_size" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare items jsonb;last_ordinal bigint;has_more boolean;
begin
  perform app_private.audit_assert_worker();
  if p_page_size not between 1 and 500 or coalesce(p_after_ordinal,0)<0
    or not exists(select 1 from public.import_jobs where id=p_export_job_id and target_domain='audit_export') then
    raise invalid_parameter_value using message='invalid audit export page';
  end if;
  if not exists(select 1 from app_private.audit_export_worker_claims
      where export_job_id=p_export_job_id and worker_token=p_worker_token and lease_until>now()) then
    raise insufficient_privilege using message='audit export worker claim unavailable';
  end if;
  with page as (
    select ordinal,row_payload from app_private.audit_export_snapshot_rows
    where export_job_id=p_export_job_id and ordinal>coalesce(p_after_ordinal,0)
    order by ordinal limit p_page_size
  ) select coalesce(jsonb_agg(row_payload order by ordinal),'[]'::jsonb),max(ordinal)
    into items,last_ordinal from page;
  has_more:=last_ordinal is not null and exists(select 1 from app_private.audit_export_snapshot_rows
    where export_job_id=p_export_job_id and ordinal>last_ordinal);
  return jsonb_build_object('items',items,'has_more',has_more,'next_cursor',
    case when has_more then jsonb_build_object('ordinal',last_ordinal) else null end);
end;
$$;


ALTER FUNCTION "app_private"."audit_export_page_for_worker"("p_export_job_id" "uuid", "p_worker_token" "uuid", "p_after_ordinal" bigint, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_fail_export_for_worker"("p_export_job_id" "uuid", "p_worker_token" "uuid", "p_error_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare job public.import_jobs%rowtype;
begin
  perform app_private.audit_assert_worker();
  select * into job from public.import_jobs where id=p_export_job_id for update;
  if job.id is null or job.target_domain<>'audit_export' or p_error_code!~'^[a-z0-9_]{1,80}$' then
    raise invalid_parameter_value using message='invalid audit export failure';
  end if;
  if job.processing_state in('SUCESSO','REJEICAO','ERRO') then return; end if;
  if job.processing_state<>'PROCESSANDO' or not exists(
    select 1 from app_private.audit_export_worker_claims
    where export_job_id=job.id and worker_token=p_worker_token
  ) then
    raise insufficient_privilege using message='audit export worker claim unavailable';
  end if;
  update public.import_jobs set processing_state='ERRO',status='draft',finished_at=now(),updated_at=now(),
    summary=summary||jsonb_build_object('phase','failed','error_code',p_error_code) where id=job.id;
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,
    origin,context_kind,payload_contract_version,after_json)
  values(job.created_by,'aal2','audit.export.failed','import_job',job.id,'failed','edge_function','global',1,
    jsonb_build_object('state','ERRO'));
end;
$_$;


ALTER FUNCTION "app_private"."audit_fail_export_for_worker"("p_export_job_id" "uuid", "p_worker_token" "uuid", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_get_event_for_superadmin"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  correlation uuid:=pg_catalog.gen_random_uuid();
  error_code text;
  result jsonb;
  event_institution_id uuid;
begin
  begin
    select * into strict ctx
    from app_private.require_superadmin_internal_context('audit.read');
    if ctx.scope_kind is null or ctx.scope_kind not in('platform','institution')
      or (ctx.scope_kind='platform' and ctx.scope_institution_id is not null)
      or (ctx.scope_kind='institution' and ctx.scope_institution_id is null)
      or ctx.aal is null or ctx.aal not in('aal1','aal2') then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    if p_event_id is null then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    select pg_catalog.jsonb_build_object(
      'id',log_record.id,
      'actor',pg_catalog.jsonb_build_object(
        'kind',coalesce(log_record.actor_kind,
          case when log_record.actor_person_id is null then 'system' else 'person' end),
        'id',coalesce(log_record.actor_internal_identity_id,log_record.actor_person_id),
        'display_name',case when log_record.actor_kind='superadmin_internal' then 'Usuário interno'
          when log_record.actor_kind='auth_session' then 'Sessão autenticada'
          when log_record.actor_person_id is null then 'Sistema'
          else coalesce(person.display_name,'Ator não disponível') end,
        'role_code',case
          when log_record.actor_kind='auth_session' then null
          when log_record.actor_kind='superadmin_internal'
            then coalesce(log_record.actor_role_code,'internal_unknown')
          when log_record.actor_person_id is null then 'system'
          else coalesce(log_record.actor_role_code,'legacy_unknown') end),
      'institution',case when log_record.institution_id is null then null else
        pg_catalog.jsonb_build_object('id',log_record.institution_id,'name',
          coalesce(institution.public_name,'Instituição não disponível')) end,
      'action_code',log_record.action_code,'permission_code',log_record.permission_code,
      'aal',log_record.mfa_aal,'object_type',log_record.object_type,
      'object_id',log_record.object_id,
      'outcome',case log_record.outcome::text when 'failed' then 'failure'
        else log_record.outcome::text end,
      'reason',coalesce(log_record.reason_code,
        app_private.audit_mask_reason(log_record.reason)),
      'before',app_private.audit_mask_payload(log_record.before_json),
      'after',app_private.audit_mask_payload(log_record.after_json),
      'correlation_id',log_record.correlation_id,'origin',log_record.origin,
      'context',pg_catalog.jsonb_build_object('kind',log_record.context_kind,'id',log_record.context_id),
      'occurred_at',log_record.occurred_at,
      'integrity',pg_catalog.jsonb_build_object(
        'version',log_record.hash_version,'position',log_record.chain_position,
        'previous_hash',case when log_record.previous_hash is null then null
          else pg_catalog.encode(log_record.previous_hash,'hex') end,
        'hash',pg_catalog.encode(log_record.entry_hash,'hex'),
        'verified',app_private.audit_verify_entry(log_record.id))) ,log_record.institution_id
      into result,event_institution_id
    from audit.audit_logs log_record
    left join public.people person on person.id=log_record.actor_person_id
    left join public.institutions institution on institution.id=log_record.institution_id
    where log_record.id=p_event_id
      and (ctx.scope_kind='platform' or log_record.institution_id=ctx.scope_institution_id);
  exception
    when invalid_parameter_value or invalid_text_representation then
      error_code:='SAI_INVALID_ARGUMENT';
    when others then
      get stacked diagnostics error_code=pg_exception_detail;
      if error_code is null or error_code not in(
        'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
        'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED',
        'SAI_MFA_REQUIRED') then
        error_code:='SAI_INTERNAL_ERROR';
      end if;
  end;
  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'audit.read','superadmin.audit.detail',error_code,correlation,
      case when ctx.scope_kind='institution' then ctx.scope_institution_id else null end);
    return app_private.audit_internal_error_envelope_v2(error_code,correlation);
  end if;
  if result is null then
    perform app_private.audit_append_superadmin_internal(
      ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
      ctx.session_id,'audit.read',ctx.aal,'superadmin.audit.detail','denied',
      'SAI_PERMISSION_DENIED',correlation,
      case when ctx.scope_kind='institution' then ctx.scope_institution_id else null end);
    return null;
  end if;
  perform app_private.audit_append_superadmin_internal(
    ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
    ctx.session_id,'audit.read',ctx.aal,'superadmin.audit.detail','success',null,
    correlation,event_institution_id,'audit_event',p_event_id);
  return result;
end
$$;


ALTER FUNCTION "app_private"."audit_get_event_for_superadmin"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_get_export_job_for_superadmin"("p_export_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid;job public.import_jobs%rowtype;
begin
  actor:=app_private.audit_assert_permission('audit.export',true);
  perform app_private.audit_assert_permission('audit.read',false);
  select * into job from public.import_jobs where id=p_export_job_id and target_domain='audit_export' and created_by=actor;
  if job.id is null then return null; end if;
  if exists(
    select 1 from app_private.audit_export_snapshot_rows snapshot
    join audit.audit_logs log_record on log_record.id=snapshot.audit_log_id
    where snapshot.export_job_id=job.id
      and (not app_private.audit_actor_has_permission(actor,'audit.read',log_record.institution_id,false)
        or not app_private.audit_actor_has_permission(actor,'audit.export',log_record.institution_id,false))
  ) then return null; end if;
  return jsonb_build_object('job_id',job.id,'state',job.processing_state,'format',job.source_format,
    'created_at',job.created_at,'summary',jsonb_strip_nulls(jsonb_build_object(
      'phase',job.summary->>'phase','row_count',job.summary->'row_count',
      'retention_expires_at',job.summary->'retention_expires_at')),
    'error_code',job.summary->>'error_code');
end $$;


ALTER FUNCTION "app_private"."audit_get_export_job_for_superadmin"("p_export_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_guard_append_only"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare expected_institution uuid;prior_hash bytea;
begin
  if tg_op in('UPDATE','DELETE') then
    raise object_not_in_prerequisite_state using message='audit logs are append-only';
  end if;
  new.origin:=coalesce(new.origin,'database');
  new.correlation_id:=coalesce(new.correlation_id,gen_random_uuid());
  new.context_kind:=coalesce(new.context_kind,case when new.institution_id is null then 'global' else 'institution' end);
  new.context_id:=coalesce(new.context_id,case when new.context_kind='institution' then new.institution_id else null end);
  if coalesce(new.hash_version,1)=1 then
    new.reason:=app_private.audit_mask_reason(new.reason);
    new.hash_version:=1;
    new.payload_contract_version:=1;
    new.actor_kind:=null;new.actor_internal_identity_id:=null;
    new.actor_internal_auth_link_id:=null;new.actor_internal_membership_id:=null;
    new.session_id_hash:=null;new.permission_code:=null;new.reason_code:=null;
    new.actor_role_code:=case when new.actor_person_id is null then 'system' else coalesce((
      select role_record.code from public.platform_memberships membership
      join public.platform_roles role_record on role_record.id=membership.role_id
      where membership.person_id=new.actor_person_id and membership.status='active'
        and membership.revoked_at is null and role_record.status='active'
      order by case membership.scope_kind when 'platform' then 0 else 1 end,membership.created_at limit 1
    ),(select membership.role_code from public.institution_memberships membership
      where membership.person_id=new.actor_person_id
        and (new.institution_id is null or membership.institution_id=new.institution_id)
        and membership.status='active' and membership.revoked_at is null
      order by membership.created_at limit 1)) end;
  elsif new.hash_version=2 then
    new.hash_version:=2;new.payload_contract_version:=2;
    new.actor_kind:='superadmin_internal';
    new.actor_person_id:=null;new.actor_membership_id:=null;
    new.support_session_id:=null;new.reason:=new.reason_code;
    if not exists(
      select 1 from app_private.superadmin_internal_auth_links auth_link
      join app_private.superadmin_internal_memberships membership
        on membership.id=new.actor_internal_membership_id
       and membership.internal_identity_id=auth_link.internal_identity_id
      where auth_link.id=new.actor_internal_auth_link_id
        and auth_link.internal_identity_id=new.actor_internal_identity_id) then
      raise foreign_key_violation using message='inconsistent internal audit actor';
    end if;
    select role_record.code into new.actor_role_code
      from app_private.superadmin_internal_memberships membership
      join public.platform_roles role_record on role_record.id=membership.platform_role_id
      where membership.id=new.actor_internal_membership_id;
  elsif new.hash_version=3 then
    if new.actor_person_id is not null or new.actor_membership_id is not null
      or new.support_session_id is not null or new.actor_internal_identity_id is not null
      or new.actor_internal_auth_link_id is not null
      or new.actor_internal_membership_id is not null or new.actor_role_code is not null then
      raise invalid_parameter_value using message='auth session audit cannot carry actor identifiers';
    end if;
    new.hash_version:=3;new.payload_contract_version:=3;
    new.actor_kind:='auth_session';new.reason:=new.reason_code;
  else
    raise invalid_parameter_value using message='invalid audit hash version';
  end if;
  if new.origin not in('database','edge_function','system','admin_ui','import')
    or new.action_code !~ '^[a-z0-9][a-z0-9._-]{0,119}$'
    or new.context_kind not in('global','institution','unit','group','activity','child') then
    raise invalid_parameter_value using message='invalid audit origin or context';
  end if;
  if new.context_kind='global' then
    if new.institution_id is not null or new.context_id is not null then
      raise invalid_parameter_value using message='invalid audit origin or context'; end if;
  elsif new.context_kind='institution' then expected_institution:=new.context_id;
  elsif new.context_kind='unit' then select institution_id into expected_institution from public.units where id=new.context_id;
  elsif new.context_kind='group' then select institution_id into expected_institution from public.groups where id=new.context_id;
  elsif new.context_kind='activity' then select institution_id into expected_institution from public.activity_definitions where id=new.context_id;
  elsif new.context_kind='child' then select institution_id into expected_institution from public.child_contexts where id=new.context_id;
  end if;
  if new.context_kind<>'global' and (expected_institution is null or expected_institution is distinct from new.institution_id) then
    raise invalid_parameter_value using message='invalid audit origin or context'; end if;
  new.before_json:=app_private.audit_minimize_payload(new.action_code,new.before_json);
  new.after_json:=app_private.audit_minimize_payload(new.action_code,new.after_json);
  perform pg_advisory_xact_lock(hashtextextended('audit.audit_logs.chain',0));
  new.chain_position:=nextval('audit.audit_log_chain_position_seq');
  select entry_hash into prior_hash from audit.audit_logs order by chain_position desc limit 1;
  new.previous_hash:=prior_hash;
  if new.hash_version=1 then
    new.entry_hash:=app_private.audit_entry_digest(new.chain_position,new.previous_hash,new.id,
      new.actor_person_id,new.actor_role_code,new.correlation_id,new.origin,new.context_kind,
      new.context_id,new.action_code,new.object_type,new.object_id,new.institution_id,new.outcome,
      new.reason,new.before_json,new.after_json,new.occurred_at);
  elsif new.hash_version=2 then
    new.entry_hash:=app_private.audit_entry_digest_v2(new.hash_version,new.chain_position,
      new.previous_hash,new.id,new.actor_person_id,new.actor_membership_id,new.support_session_id,
      new.actor_kind,new.actor_internal_identity_id,new.actor_internal_auth_link_id,
      new.actor_internal_membership_id,new.session_id_hash,new.permission_code,new.mfa_aal,
      new.reason_code,new.actor_role_code,new.correlation_id,new.origin,new.context_kind,
      new.context_id,new.action_code,new.object_type,new.object_id,new.institution_id,
      new.outcome,new.reason,new.payload_contract_version,new.before_json,new.after_json,new.occurred_at);
  elsif new.hash_version=3 then
    new.entry_hash:=app_private.audit_entry_digest_v3(new.chain_position,new.previous_hash,new.id,
      new.session_id_hash,new.permission_code,new.mfa_aal,new.reason_code,new.correlation_id,
      new.origin,new.context_kind,new.context_id,new.action_code,new.object_type,new.object_id,
      new.institution_id,new.outcome,new.payload_contract_version,new.before_json,new.after_json,new.occurred_at);
  else
    raise invalid_parameter_value using message='invalid audit hash version';
  end if;
  return new;
end
$_$;


ALTER FUNCTION "app_private"."audit_guard_append_only"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_has_permission"("p_permission_code" "text", "p_institution_id" "uuid" DEFAULT NULL::"uuid", "p_any_scope" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.audit_actor_has_permission(
    app_private.current_person_id(),p_permission_code,p_institution_id,p_any_scope
  )
$$;


ALTER FUNCTION "app_private"."audit_has_permission"("p_permission_code" "text", "p_institution_id" "uuid", "p_any_scope" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_internal_error_envelope_v2"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select pg_catalog.jsonb_build_object('ok',false,'data',null,'error',
    pg_catalog.jsonb_build_object(
      'code',case when p_code in(
        'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
        'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED',
        'SAI_MFA_REQUIRED','SAI_INVALID_ARGUMENT') then p_code else 'SAI_INTERNAL_ERROR' end,
      'message',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 'Autenticação necessária.'
        when p_code='SAI_INVALID_ARGUMENT' then 'Revise os dados enviados.'
        when p_code='SAI_MFA_REQUIRED' then 'Confirme o segundo fator.'
        when p_code like 'SAI_%DENIED' or p_code like 'SAI_MEMBERSHIP_%'
          then 'Acesso não autorizado.'
        else 'Não foi possível concluir a operação.' end,
      'correlation_id',p_correlation_id,
      'http_status',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 401
        when p_code='SAI_INVALID_ARGUMENT' then 400
        when p_code in('SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
          'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED') then 403
        else 500 end))
$$;


ALTER FUNCTION "app_private"."audit_internal_error_envelope_v2"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_list_events_for_superadmin"("p_search" "text" DEFAULT NULL::"text", "p_actor_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_context_kinds" "text"[] DEFAULT NULL::"text"[], "p_action_codes" "text"[] DEFAULT NULL::"text"[], "p_resource_types" "text"[] DEFAULT NULL::"text"[], "p_outcomes" "text"[] DEFAULT NULL::"text"[], "p_origins" "text"[] DEFAULT NULL::"text"[], "p_institution_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  correlation uuid:=pg_catalog.gen_random_uuid();
  error_code text;
  result jsonb;
  audit_institution_id uuid;
begin
  begin
    select * into strict ctx
    from app_private.require_superadmin_internal_context('audit.read');
    if ctx.scope_kind is null or ctx.scope_kind not in('platform','institution')
      or (ctx.scope_kind='platform' and ctx.scope_institution_id is not null)
      or (ctx.scope_kind='institution' and ctx.scope_institution_id is null)
      or ctx.aal is null or ctx.aal not in('aal1','aal2') then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    perform app_private.audit_validate_internal_list_filters_v2(
      p_search,p_actor_ids,p_context_kinds,p_action_codes,p_resource_types,p_outcomes,
      p_origins,p_from,p_to,p_cursor_occurred_at,p_cursor_id,p_limit);

    if p_cursor_id is not null and not exists(
      select 1
      from audit.audit_logs cursor_record
      left join public.people cursor_person on cursor_person.id=cursor_record.actor_person_id
      left join public.institutions cursor_institution on cursor_institution.id=cursor_record.institution_id
      where cursor_record.id=p_cursor_id
        and cursor_record.occurred_at=p_cursor_occurred_at
        and (ctx.scope_kind='platform' or cursor_record.institution_id=ctx.scope_institution_id)
        and (p_institution_id is null or cursor_record.institution_id=p_institution_id)
        and (p_actor_ids is null or pg_catalog.cardinality(p_actor_ids)=0
          or coalesce(cursor_record.actor_internal_identity_id,
            cursor_record.actor_person_id)=any(p_actor_ids))
        and (p_context_kinds is null or pg_catalog.cardinality(p_context_kinds)=0
          or cursor_record.context_kind=any(p_context_kinds))
        and (p_action_codes is null or pg_catalog.cardinality(p_action_codes)=0
          or cursor_record.action_code=any(p_action_codes))
        and (p_resource_types is null or pg_catalog.cardinality(p_resource_types)=0
          or cursor_record.object_type=any(p_resource_types))
        and (p_outcomes is null or pg_catalog.cardinality(p_outcomes)=0 or
          case cursor_record.outcome::text when 'failed' then 'failure'
            else cursor_record.outcome::text end=any(p_outcomes))
        and (p_origins is null or pg_catalog.cardinality(p_origins)=0
          or cursor_record.origin=any(p_origins))
        and (p_from is null or cursor_record.occurred_at>=p_from)
        and (p_to is null or cursor_record.occurred_at<=p_to)
        and (nullif(pg_catalog.btrim(p_search),'') is null
          or pg_catalog.strpos(pg_catalog.lower(pg_catalog.concat_ws(' ',
            cursor_record.action_code,cursor_record.object_type,cursor_record.object_id::text,
            cursor_record.correlation_id::text,
            case when cursor_record.actor_kind='superadmin_internal' then 'Usuário interno'
              when cursor_record.actor_kind='auth_session' then 'Sessão autenticada'
              else cursor_person.display_name end,cursor_institution.public_name)),
            pg_catalog.lower(pg_catalog.btrim(p_search)))>0)
    ) then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;

    with filtered as materialized(
      select log_record.*,person.display_name,institution.public_name institution_name,
        coalesce(log_record.actor_internal_identity_id,
          log_record.actor_person_id) effective_actor_id,
        case when log_record.actor_kind='superadmin_internal' then 'Usuário interno'
          when log_record.actor_kind='auth_session' then 'Sessão autenticada'
          when log_record.actor_person_id is null then 'Sistema'
          else coalesce(person.display_name,'Ator não disponível') end effective_actor_name
      from audit.audit_logs log_record
      left join public.people person on person.id=log_record.actor_person_id
      left join public.institutions institution on institution.id=log_record.institution_id
      where (ctx.scope_kind='platform' or log_record.institution_id=ctx.scope_institution_id)
        and (p_institution_id is null or log_record.institution_id=p_institution_id)
        and (p_actor_ids is null or pg_catalog.cardinality(p_actor_ids)=0
          or coalesce(log_record.actor_internal_identity_id,
            log_record.actor_person_id)=any(p_actor_ids))
        and (p_context_kinds is null or pg_catalog.cardinality(p_context_kinds)=0
          or log_record.context_kind=any(p_context_kinds))
        and (p_action_codes is null or pg_catalog.cardinality(p_action_codes)=0
          or log_record.action_code=any(p_action_codes))
        and (p_resource_types is null or pg_catalog.cardinality(p_resource_types)=0
          or log_record.object_type=any(p_resource_types))
        and (p_outcomes is null or pg_catalog.cardinality(p_outcomes)=0 or
          case log_record.outcome::text when 'failed' then 'failure'
            else log_record.outcome::text end=any(p_outcomes))
        and (p_origins is null or pg_catalog.cardinality(p_origins)=0
          or log_record.origin=any(p_origins))
        and (p_from is null or log_record.occurred_at>=p_from)
        and (p_to is null or log_record.occurred_at<=p_to)
        and (nullif(pg_catalog.btrim(p_search),'') is null
          or pg_catalog.strpos(pg_catalog.lower(pg_catalog.concat_ws(' ',
            log_record.action_code,log_record.object_type,log_record.object_id::text,
            log_record.correlation_id::text,
            case when log_record.actor_kind='superadmin_internal' then 'Usuário interno'
              when log_record.actor_kind='auth_session' then 'Sessão autenticada'
              else person.display_name end,institution.public_name)),
            pg_catalog.lower(pg_catalog.btrim(p_search)))>0)
    ),page_plus_one as materialized(
      select * from filtered
      where p_cursor_occurred_at is null
        or (occurred_at,id)<(p_cursor_occurred_at,p_cursor_id)
      order by occurred_at desc,id desc
      limit p_limit+1
    ),visible as materialized(
      select * from page_plus_one order by occurred_at desc,id desc limit p_limit
    )
    select pg_catalog.jsonb_build_object(
      'items',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'id',id,'actor',pg_catalog.jsonb_build_object(
          'kind',coalesce(actor_kind,
            case when actor_person_id is null then 'system' else 'person' end),
          'id',effective_actor_id,'display_name',effective_actor_name,
          'role_code',case
            when actor_kind='auth_session' then null
            when actor_kind='superadmin_internal' then coalesce(actor_role_code,'internal_unknown')
            when actor_person_id is null then 'system'
            else coalesce(actor_role_code,'legacy_unknown') end),
        'institution',case when institution_id is null then null else
          pg_catalog.jsonb_build_object('id',institution_id,'name',
            coalesce(institution_name,'Instituição não disponível')) end,
        'action_code',action_code,'permission_code',permission_code,'aal',mfa_aal,
        'object_type',object_type,'object_id',object_id,
        'outcome',case outcome::text when 'failed' then 'failure' else outcome::text end,
        'reason_code',reason_code,'correlation_id',correlation_id,'origin',origin,
        'context',pg_catalog.jsonb_build_object('kind',context_kind,'id',context_id),
        'occurred_at',occurred_at
      ) order by occurred_at desc,id desc) from visible),'[]'::jsonb),
      'has_more',(select pg_catalog.count(*) from page_plus_one)>p_limit,
      'next_cursor',case when (select pg_catalog.count(*) from page_plus_one)>p_limit then
        (select pg_catalog.jsonb_build_object('occurred_at',occurred_at,'event_id',id)
         from visible order by occurred_at,id limit 1) else null end,
      'total_count',(select pg_catalog.count(*) from filtered),
      'can_export',false
    ) into result;
  exception
    when invalid_parameter_value or invalid_text_representation or datetime_field_overflow
      or invalid_datetime_format or numeric_value_out_of_range then
      error_code:='SAI_INVALID_ARGUMENT';
    when others then
      get stacked diagnostics error_code=pg_exception_detail;
      if error_code is null or error_code not in(
        'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
        'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED',
        'SAI_MFA_REQUIRED') then
        error_code:='SAI_INTERNAL_ERROR';
      end if;
  end;
  select institution_record.id into audit_institution_id
  from public.institutions institution_record
  where institution_record.id=case
    when ctx.scope_kind='institution' then ctx.scope_institution_id
    when ctx.scope_kind='platform' then p_institution_id
    else null end;

  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'audit.read','superadmin.audit.list',error_code,correlation,
      audit_institution_id);
    return app_private.audit_internal_error_envelope_v2(error_code,correlation);
  end if;
  perform app_private.audit_append_superadmin_internal(
    ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
    ctx.session_id,'audit.read',ctx.aal,'superadmin.audit.list','success',null,
    correlation,audit_institution_id);
  return result;
end
$$;


ALTER FUNCTION "app_private"."audit_list_events_for_superadmin"("p_search" "text", "p_actor_ids" "uuid"[], "p_context_kinds" "text"[], "p_action_codes" "text"[], "p_resource_types" "text"[], "p_outcomes" "text"[], "p_origins" "text"[], "p_institution_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_cursor_occurred_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_mask_payload"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare result jsonb:='{}'::jsonb; item record; safe_counts jsonb;
begin
 if p_value is null then return null; end if;
 if jsonb_typeof(p_value)<>'object' then return null; end if;
 for item in select * from jsonb_each(p_value) loop
  if item.key in('id','scope_id','institution_id','unit_id','group_id','child_context_id','activity_id')
   and (jsonb_typeof(item.value)='null' or (jsonb_typeof(item.value)='string' and trim(both '"' from item.value::text)~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) then result:=result||jsonb_build_object(item.key,item.value);
  elsif item.key in('status','role_code','scope_kind','format','state') and jsonb_typeof(item.value)='string' and trim(both '"' from item.value::text)~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$' then result:=result||jsonb_build_object(item.key,item.value);
  elsif item.key in('version','management_version','row_count','valid_count','rejected_count','created_count','updated_count','linked_count','ignored_count') and jsonb_typeof(item.value)='number' then result:=result||jsonb_build_object(item.key,item.value);
  elsif item.key in('pii_included','replayed') and jsonb_typeof(item.value)='boolean' then result:=result||jsonb_build_object(item.key,item.value);
  elsif item.key in('created_at','updated_at') and jsonb_typeof(item.value)='string' and trim(both '"' from item.value::text)~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.+-]{8,35}Z?$' then result:=result||jsonb_build_object(item.key,item.value);
  elsif item.key='counts' and jsonb_typeof(item.value)='object' then
   select coalesce(jsonb_object_agg(entry.key,entry.value),'{}'::jsonb) into safe_counts from jsonb_each(item.value) entry
    where entry.key in('units','groups','participants','professionals','settings','actions') and jsonb_typeof(entry.value)='number' and (entry.value#>>'{}')::numeric>=0 and (entry.value#>>'{}')::numeric=trunc((entry.value#>>'{}')::numeric);
   result:=result||jsonb_build_object('counts',safe_counts);
  end if;
 end loop;
 return result;
end $_$;


ALTER FUNCTION "app_private"."audit_mask_payload"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_mask_reason"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when p_value is null then null
    when p_value ~ '^[a-z0-9][a-z0-9._-]{0,119}$' then p_value
    else '[redacted]'
  end
$_$;


ALTER FUNCTION "app_private"."audit_mask_reason"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_materialize_export_for_worker"("p_export_job_id" "uuid", "p_worker_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job public.import_jobs%rowtype;filters jsonb;row_count integer;
  read_authorization jsonb;export_authorization jsonb;
  claim app_private.audit_export_worker_claims%rowtype;
begin
  perform app_private.audit_assert_worker();
  if p_worker_token is null then
    raise invalid_parameter_value using message='invalid audit export worker claim';
  end if;
  select * into job from public.import_jobs where id=p_export_job_id for update;
  if job.id is null or job.target_domain<>'audit_export' then
    raise insufficient_privilege using message='audit export job unavailable';
  end if;
  read_authorization:=app_private.audit_authorization_scope(job.created_by,'audit.read');
  export_authorization:=app_private.audit_authorization_scope(job.created_by,'audit.export');
  if (not coalesce((read_authorization->>'global')::boolean,false)
      and jsonb_array_length(coalesce(read_authorization->'institution_ids','[]'::jsonb))=0)
    or (not coalesce((export_authorization->>'global')::boolean,false)
      and jsonb_array_length(coalesce(export_authorization->'institution_ids','[]'::jsonb))=0) then
    raise insufficient_privilege using message='audit export authorization revoked';
  end if;
  if exists(select 1 from app_private.audit_export_snapshot_rows snapshot
    join audit.audit_logs log_record on log_record.id=snapshot.audit_log_id
    where snapshot.export_job_id=job.id
      and (not app_private.audit_actor_has_permission(job.created_by,'audit.read',log_record.institution_id,false)
        or not app_private.audit_actor_has_permission(job.created_by,'audit.export',log_record.institution_id,false))) then
    raise insufficient_privilege using message='audit export authorization revoked';
  end if;
  if job.processing_state='SUCESSO' then
    return jsonb_build_object('job_id',job.id,'row_count',job.summary->'row_count',
      'state','SUCESSO','claimed',false);
  end if;
  if job.processing_state in('ERRO','REJEICAO') then
    raise object_not_in_prerequisite_state using message='audit export job is terminal';
  end if;
  filters:=coalesce(job.summary->'filters','{}'::jsonb);
  select * into claim from app_private.audit_export_worker_claims
    where export_job_id=job.id for update;
  if job.processing_state='PROCESSANDO' and claim.lease_until>now()
    and claim.worker_token<>p_worker_token then
    return jsonb_build_object('job_id',job.id,'state','PROCESSANDO','claimed',false);
  end if;
  insert into app_private.audit_export_worker_claims(export_job_id,worker_token,lease_until,claimed_at)
  values(job.id,p_worker_token,now()+interval '15 minutes',now())
  on conflict(export_job_id) do update set worker_token=excluded.worker_token,
    lease_until=excluded.lease_until,claimed_at=excluded.claimed_at;
  delete from app_private.audit_export_snapshot_rows where export_job_id=job.id;
  insert into app_private.audit_export_snapshot_rows(export_job_id,ordinal,audit_log_id,row_payload)
  select job.id,row_number() over(order by log_record.occurred_at desc,log_record.id desc),log_record.id,
    jsonb_build_object(
      'id',log_record.id,'occurred_at',log_record.occurred_at,
      'actor_kind',coalesce(log_record.actor_kind,
        case when log_record.actor_person_id is null then 'system' else 'person' end),
      'actor_id',coalesce(log_record.actor_internal_identity_id,log_record.actor_person_id),
      'actor_name',case when log_record.actor_kind='superadmin_internal' then 'Usuário interno'
        when log_record.actor_kind='auth_session' then 'Sessão autenticada'
        when log_record.actor_person_id is null then 'Sistema' else person.display_name end,
      'actor_role_code',log_record.actor_role_code,'permission_code',log_record.permission_code,
      'aal',log_record.mfa_aal,'reason_code',log_record.reason_code,
      'institution_name',institution.public_name,'action_code',log_record.action_code,
      'resource_type',log_record.object_type,'resource_id',log_record.object_id,
      'outcome',case log_record.outcome::text when 'failed' then 'failure' else log_record.outcome::text end,
      'correlation_id',log_record.correlation_id,'origin',log_record.origin,
      'context_kind',log_record.context_kind,'context_id',log_record.context_id)
  from audit.audit_logs log_record
  left join public.people person on person.id=log_record.actor_person_id
  left join public.institutions institution on institution.id=log_record.institution_id
  where (((read_authorization->>'global')::boolean and (log_record.institution_id is null
        or not((read_authorization->'denied_institution_ids')?log_record.institution_id::text)))
      or (log_record.institution_id is not null
        and (read_authorization->'institution_ids')?log_record.institution_id::text))
    and (((export_authorization->>'global')::boolean and (log_record.institution_id is null
        or not((export_authorization->'denied_institution_ids')?log_record.institution_id::text)))
      or (log_record.institution_id is not null
        and (export_authorization->'institution_ids')?log_record.institution_id::text))
    and (not(filters?'institution_id') or log_record.institution_id=(filters->>'institution_id')::uuid)
    and (not(filters?'actor_ids') or jsonb_array_length(filters->'actor_ids')=0
      or (filters->'actor_ids')?coalesce(log_record.actor_internal_identity_id,log_record.actor_person_id)::text)
    and (not(filters?'context_kinds') or jsonb_array_length(filters->'context_kinds')=0
      or (filters->'context_kinds')?log_record.context_kind)
    and (not(filters?'action_codes') or jsonb_array_length(filters->'action_codes')=0
      or (filters->'action_codes')?log_record.action_code)
    and (not(filters?'resource_types') or jsonb_array_length(filters->'resource_types')=0
      or (filters->'resource_types')?log_record.object_type)
    and (not(filters?'outcomes') or jsonb_array_length(filters->'outcomes')=0
      or (filters->'outcomes')?(case log_record.outcome::text when 'failed' then 'failure' else log_record.outcome::text end))
    and (not(filters?'origins') or jsonb_array_length(filters->'origins')=0
      or (filters->'origins')?log_record.origin)
    and (not(filters?'from') or log_record.occurred_at>=(filters->>'from')::timestamptz)
    and (not(filters?'to') or log_record.occurred_at<=(filters->>'to')::timestamptz)
    and (nullif(btrim(filters->>'search'),'') is null or position(lower(btrim(filters->>'search'))
      in lower(concat_ws(' ',log_record.action_code,log_record.object_type,
        log_record.object_id::text,log_record.correlation_id::text,
        case when log_record.actor_kind='superadmin_internal' then 'Usuário interno'
          when log_record.actor_kind='auth_session' then 'Sessão autenticada'
          else person.display_name end,institution.public_name)))>0)
  order by log_record.occurred_at desc,log_record.id desc limit 50001;
  get diagnostics row_count=row_count;
  if row_count>50000 then
    raise program_limit_exceeded using message='audit export exceeds maximum row count';
  end if;
  update public.import_jobs set processing_state='PROCESSANDO',status='active',
    started_at=coalesce(started_at,now()),updated_at=now(),
    summary=summary||jsonb_build_object('phase','materialized','row_count',row_count,
      'authorization_revalidated_at',now()) where id=job.id;
  return jsonb_build_object('job_id',job.id,'row_count',row_count,
    'state','PROCESSANDO','claimed',true);
end
$$;


ALTER FUNCTION "app_private"."audit_materialize_export_for_worker"("p_export_job_id" "uuid", "p_worker_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_minimize_payload"("p_action_code" "text", "p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p_value is null then null when p_action_code like 'audit.export.%' then
    coalesce((select jsonb_object_agg(item.key,item.value)
      from jsonb_each(app_private.audit_mask_payload(p_value)) item
      where item.key in('format','state','row_count','pii_included')),'{}'::jsonb)
  else app_private.audit_mask_payload(p_value) end
$$;


