CREATE OR REPLACE FUNCTION "app_private"."audit_spreadsheet_cell"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p_value~'^[=+@-]' or p_value~'^[\t\r]' then ''''||p_value else p_value end
$$;


