CREATE OR REPLACE FUNCTION "app_private"."audit_start_export_for_superadmin"("p_format" "text", "p_filters" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid;request_hash bytea;job public.import_jobs%rowtype;result jsonb;v_authorization jsonb;
begin
  actor:=app_private.audit_assert_permission('audit.export',true);
  perform app_private.audit_assert_permission('audit.read',false);
  if p_format not in('csv','xlsx') or p_idempotency_key is null then
    raise invalid_parameter_value using message='invalid audit export request';
  end if;
  perform app_private.audit_validate_export_filters(p_filters);
  v_authorization:=jsonb_build_object(
    'read',app_private.audit_authorization_scope(actor,'audit.read'),
    'export',app_private.audit_authorization_scope(actor,'audit.export')
  );
  request_hash:=extensions.digest(convert_to(jsonb_build_object('format',p_format,'filters',p_filters)::text,'UTF8'),'sha256');
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
  select * into job from public.import_jobs where request_id=p_idempotency_key;
  if job.id is not null then
    if job.created_by<>actor or job.request_hash<>request_hash or job.target_domain<>'audit_export' then
      raise invalid_parameter_value using message='idempotency key replay mismatch';
    end if;
    if job.processing_state='SUCESSO'
      and app_private.audit_get_export_job_for_superadmin(job.id) is null then
      raise insufficient_privilege using message='audit export unavailable';
    end if;
    return jsonb_build_object('job_id',job.id,'state',job.processing_state,'format',job.source_format,'created_at',job.created_at);
  end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':audit_export',0));
  if (select count(*) from public.import_jobs where created_by=actor
      and target_domain='audit_export' and created_at>now()-interval '1 hour')>=5 then
    raise program_limit_exceeded using message='audit export rate limit exceeded';
  end if;
  insert into public.import_jobs(request_id,request_hash,target_domain,target_table,source_format,
    source_locale,target_locale,status,processing_state,summary,created_by)
  values(p_idempotency_key,request_hash,'audit_export','audit_logs',p_format,'pt-BR','pt-BR',
    'draft','PENDENTE',jsonb_build_object('phase','queued','filters',p_filters,
      'storage_bucket','coelo-operations','retention_expires_at',now()+interval '24 hours',
      'authorization_snapshot',v_authorization,'formula_neutralization',true,'pii_included',true),actor)
  returning * into job;
  insert into public.import_results(import_job_id) values(job.id);
  insert into audit.audit_logs(actor_person_id,actor_role_code,mfa_aal,action_code,object_type,
    object_id,outcome,origin,context_kind,payload_contract_version,after_json)
  values(actor,null,'aal2','audit.export.request','import_job',job.id,'success','admin_ui','global',1,
    jsonb_build_object('format',p_format,'state','PENDENTE','pii_included',true));
  result:=jsonb_build_object('job_id',job.id,'state',job.processing_state,'format',job.source_format,'created_at',job.created_at);
  return result;
end;
$$;


ALTER FUNCTION "app_private"."audit_start_export_for_superadmin"("p_format" "text", "p_filters" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_superadmin_internal_denial_if_identified"("p_permission_code" "text", "p_action_code" "text", "p_reason_code" "text", "p_correlation_id" "uuid", "p_institution_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare current_auth_user_id uuid; current_session_id uuid; jwt_aal text;
  auth_link_id uuid; identity_id uuid; membership_id uuid;
  audit_institution_id uuid;
begin
  current_auth_user_id:=auth.uid();
  if current_auth_user_id is null then return; end if;
  begin current_session_id:=(auth.jwt()->>'session_id')::uuid;
  exception when others then return; end;
  if not exists(select 1 from auth.sessions session_record
    where session_record.id=current_session_id and session_record.user_id=current_auth_user_id
      and (session_record.not_after is null or session_record.not_after>pg_catalog.now())) then
    return;
  end if;
  jwt_aal:=auth.jwt()->>'aal';
  if jwt_aal not in('aal1','aal2') then return; end if;
  select auth_link.id,auth_link.internal_identity_id into auth_link_id,identity_id
  from app_private.superadmin_internal_auth_links auth_link
  where auth_link.auth_user_id=current_auth_user_id
  order by auth_link.created_at desc limit 1;
  if auth_link_id is null then
    perform app_private.audit_append_auth_session_denial(current_session_id,
      p_permission_code,jwt_aal,p_action_code,p_reason_code,p_correlation_id);
    return;
  end if;
  select membership.id into membership_id
  from app_private.superadmin_internal_memberships membership
  where membership.internal_identity_id=identity_id
  order by (membership.status='active') desc,membership.created_at desc limit 1;
  if membership_id is null then
    perform app_private.audit_append_auth_session_denial(current_session_id,
      p_permission_code,jwt_aal,p_action_code,p_reason_code,p_correlation_id);
    return;
  end if;
  select institution.id into audit_institution_id
  from public.institutions institution
  where institution.id=p_institution_id;
  perform app_private.audit_append_superadmin_internal(identity_id,auth_link_id,
    membership_id,current_session_id,p_permission_code,jwt_aal,p_action_code,
    'denied',p_reason_code,p_correlation_id,audit_institution_id,
    case when audit_institution_id is null then null else 'institution' end,
    audit_institution_id);
end
$$;


ALTER FUNCTION "app_private"."audit_superadmin_internal_denial_if_identified"("p_permission_code" "text", "p_action_code" "text", "p_reason_code" "text", "p_correlation_id" "uuid", "p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_validate_export_filters"("p_filters" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare item text;from_value timestamptz;to_value timestamptz;
begin
  begin
    if p_filters is null or jsonb_typeof(p_filters)<>'object'
      or p_filters-array['search','actor_ids','context_kinds','action_codes','resource_types',
        'outcomes','origins','institution_id','from','to']<>'{}'::jsonb
      or length(coalesce(p_filters->>'search',''))>200
      or coalesce(p_filters->>'search','')~'[[:cntrl:]]' then
      raise invalid_parameter_value;
    end if;
    foreach item in array array['actor_ids','context_kinds','action_codes','resource_types','outcomes','origins'] loop
      if p_filters?item and jsonb_typeof(p_filters->item)<>'array' then raise invalid_parameter_value; end if;
    end loop;
    if coalesce(jsonb_array_length(coalesce(p_filters->'actor_ids','[]')),0)>50
      or coalesce(jsonb_array_length(coalesce(p_filters->'context_kinds','[]')),0)>10
      or coalesce(jsonb_array_length(coalesce(p_filters->'action_codes','[]')),0)>20
      or coalesce(jsonb_array_length(coalesce(p_filters->'resource_types','[]')),0)>20
      or coalesce(jsonb_array_length(coalesce(p_filters->'outcomes','[]')),0)>10
      or coalesce(jsonb_array_length(coalesce(p_filters->'origins','[]')),0)>10 then raise invalid_parameter_value; end if;
    if exists(select 1 from jsonb_array_elements_text(coalesce(p_filters->'actor_ids','[]')) value
      where value!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
      or exists(select 1 from jsonb_array_elements_text(coalesce(p_filters->'context_kinds','[]')) value
        where value not in('global','institution','unit','group','activity','child'))
      or exists(select 1 from jsonb_array_elements_text(coalesce(p_filters->'action_codes','[]')) value
        where value!~'^[a-z0-9][a-z0-9._-]{0,119}$')
      or exists(select 1 from jsonb_array_elements_text(coalesce(p_filters->'resource_types','[]')) value
        where value!~'^[a-z0-9][a-z0-9._-]{0,119}$')
      or exists(select 1 from jsonb_array_elements_text(coalesce(p_filters->'outcomes','[]')) value
        where value not in('success','failure','denied'))
      or exists(select 1 from jsonb_array_elements_text(coalesce(p_filters->'origins','[]')) value
        where value not in('database','edge_function','system','admin_ui','import')) then raise invalid_parameter_value; end if;
    if p_filters?'institution_id' and (p_filters->>'institution_id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise invalid_parameter_value; end if;
    if p_filters?'from' then from_value:=(p_filters->>'from')::timestamptz; end if;
    if p_filters?'to' then to_value:=(p_filters->>'to')::timestamptz; end if;
    if from_value is not null and to_value is not null and from_value>to_value then raise invalid_parameter_value; end if;
  exception when others then
    raise invalid_parameter_value using message='invalid audit export request';
  end;
end;
$_$;


ALTER FUNCTION "app_private"."audit_validate_export_filters"("p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_validate_internal_list_filters_v2"("p_search" "text", "p_actor_ids" "uuid"[], "p_context_kinds" "text"[], "p_action_codes" "text"[], "p_resource_types" "text"[], "p_outcomes" "text"[], "p_origins" "text"[], "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_cursor_occurred_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
begin
  if p_limit is null or p_limit not between 1 and 100
    or pg_catalog.char_length(coalesce(p_search,''))>200
    or coalesce(p_search,'')~'[[:cntrl:]]'
    or (p_from is not null and not pg_catalog.isfinite(p_from))
    or (p_to is not null and not pg_catalog.isfinite(p_to))
    or (p_from is not null and p_to is not null and p_from>p_to)
    or ((p_cursor_occurred_at is null)<>(p_cursor_id is null))
    or (p_cursor_occurred_at is not null and not pg_catalog.isfinite(p_cursor_occurred_at))
    or coalesce(pg_catalog.cardinality(p_actor_ids),0)>50
    or coalesce(pg_catalog.cardinality(p_context_kinds),0)>10
    or coalesce(pg_catalog.cardinality(p_action_codes),0)>20
    or coalesce(pg_catalog.cardinality(p_resource_types),0)>20
    or coalesce(pg_catalog.cardinality(p_outcomes),0)>10
    or coalesce(pg_catalog.cardinality(p_origins),0)>10
    or exists(select 1 from pg_catalog.unnest(coalesce(p_actor_ids,'{}'::uuid[])) item
      where item is null)
    or exists(select 1 from pg_catalog.unnest(coalesce(p_context_kinds,'{}'::text[])) item
      where item is null or item not in('global','institution','unit','group','activity','child'))
    or exists(select 1 from pg_catalog.unnest(coalesce(p_action_codes,'{}'::text[])) item
      where item is null or item!~'^[a-z0-9][a-z0-9._-]{0,119}$')
    or exists(select 1 from pg_catalog.unnest(coalesce(p_resource_types,'{}'::text[])) item
      where item is null or item!~'^[a-z0-9][a-z0-9._-]{0,119}$')
    or exists(select 1 from pg_catalog.unnest(coalesce(p_outcomes,'{}'::text[])) item
      where item is null or item not in('success','failure','denied'))
    or exists(select 1 from pg_catalog.unnest(coalesce(p_origins,'{}'::text[])) item
      where item is null or item not in('database','edge_function','system','admin_ui','import')) then
    raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
  end if;
end
$_$;


ALTER FUNCTION "app_private"."audit_validate_internal_list_filters_v2"("p_search" "text", "p_actor_ids" "uuid"[], "p_context_kinds" "text"[], "p_action_codes" "text"[], "p_resource_types" "text"[], "p_outcomes" "text"[], "p_origins" "text"[], "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_cursor_occurred_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_validate_list_filters"("p_search" "text", "p_actor_ids" "uuid"[], "p_context_kinds" "text"[], "p_action_codes" "text"[], "p_resource_types" "text"[], "p_outcomes" "text"[], "p_origins" "text"[], "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_before_occurred_at" timestamp with time zone, "p_before_event_id" "uuid", "p_page_size" integer) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
begin
  if p_page_size not between 1 and 100
    or length(coalesce(p_search,''))>200 or coalesce(p_search,'')~'[[:cntrl:]]'
    or (p_from is not null and p_to is not null and p_from>p_to)
    or ((p_before_occurred_at is null)<>(p_before_event_id is null))
    or coalesce(cardinality(p_action_codes),0)>20
    or coalesce(cardinality(p_actor_ids),0)>50
    or coalesce(cardinality(p_context_kinds),0)>10
    or coalesce(cardinality(p_resource_types),0)>20
    or coalesce(cardinality(p_outcomes),0)>10
    or coalesce(cardinality(p_origins),0)>10
    or exists(select 1 from unnest(coalesce(p_action_codes,'{}')) item where item !~ '^[a-z0-9][a-z0-9._-]{0,119}$')
    or exists(select 1 from unnest(coalesce(p_context_kinds,'{}')) item where item not in('global','institution','unit','group','activity','child'))
    or exists(select 1 from unnest(coalesce(p_resource_types,'{}')) item where item !~ '^[a-z0-9][a-z0-9._-]{0,119}$')
    or exists(select 1 from unnest(coalesce(p_outcomes,'{}')) item where item not in('success','failure','denied'))
    or exists(select 1 from unnest(coalesce(p_origins,'{}')) item where item not in('database','edge_function','system','admin_ui','import')) then
    raise invalid_parameter_value using message='invalid audit list filters';
  end if;
end;
$_$;


ALTER FUNCTION "app_private"."audit_validate_list_filters"("p_search" "text", "p_actor_ids" "uuid"[], "p_context_kinds" "text"[], "p_action_codes" "text"[], "p_resource_types" "text"[], "p_outcomes" "text"[], "p_origins" "text"[], "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_before_occurred_at" timestamp with time zone, "p_before_event_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."audit_verify_entry"("p_audit_log_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.audit_entry_matches_digest(log_record)
    and log_record.previous_hash is not distinct from (
      select prior.entry_hash from audit.audit_logs prior
      where prior.chain_position<log_record.chain_position
      order by prior.chain_position desc limit 1)
  from audit.audit_logs log_record where log_record.id=p_audit_log_id
$$;


ALTER FUNCTION "app_private"."audit_verify_entry"("p_audit_log_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."block_form_identity_mode_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.first_published_at is not null and new.identity_mode <> old.identity_mode then
    raise check_violation using message = 'identity mode is immutable after first publication';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."block_form_identity_mode_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."block_published_form_definition_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare version_id uuid;
begin
  if tg_table_name = 'form_versions' then
    if tg_op = 'DELETE' and old.state <> 'working' then
      raise insufficient_privilege using message = 'published form version is immutable';
    end if;
    if tg_op = 'UPDATE' then
      if old.form_id <> new.form_id
         or old.version_number <> new.version_number
         or old.created_by_person_id is distinct from new.created_by_person_id
         or old.created_by_internal_identity_id is distinct from new.created_by_internal_identity_id
         or old.created_at <> new.created_at
         or not (
           (old.state = 'working' and new.state = 'published' and new.published_at is not null)
           or (old.state = 'published' and new.state = 'superseded' and new.published_at = old.published_at)
         ) then
        raise insufficient_privilege using message = 'published form version is immutable';
      end if;
    end if;
    return coalesce(new, old);
  end if;
  version_id := coalesce(new.form_version_id, old.form_version_id);
  if exists(select 1 from public.form_versions where id = version_id and state <> 'working') then
    raise insufficient_privilege using message = 'published form version is immutable';
  end if;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "app_private"."block_published_form_definition_mutation"() OWNER TO "postgres";


