CREATE OR REPLACE FUNCTION "app_private"."can_access_attendance_child"("target_institution_id" "uuid", "target_unit_id" "uuid", "target_group_id" "uuid", "target_activity_id" "uuid", "target_child_context_id" "uuid", "require_manage" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    -- Leitura de plataforma nunca alcanca o ramo de gestao. Gerir exige a
    -- capacidade de gestao, de plataforma ou contextual.
    (
      case when require_manage
        then app_private.has_platform_permission('attendance.manage')
        else app_private.has_platform_permission('platform.read')
          or app_private.has_platform_permission('attendance.manage')
      end
    )
    or app_private.has_context_permission(
      target_institution_id,
      case when require_manage then 'attendance.manage' else 'attendance.read' end,
      target_unit_id, target_group_id, target_activity_id, target_child_context_id, false
    )
    or (
      not require_manage
      and target_child_context_id is not null
      and app_private.guardian_has_capability(
        target_child_context_id, 'manage_attendance_notices'
      )
    )
    or (
      not require_manage
      and target_activity_id is not null
      and app_private.has_activity_capability(
        target_activity_id, target_group_id, 'attendance'
      )
    )
$$;


ALTER FUNCTION "app_private"."can_access_attendance_child"("target_institution_id" "uuid", "target_unit_id" "uuid", "target_group_id" "uuid", "target_activity_id" "uuid", "target_child_context_id" "uuid", "require_manage" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."can_access_chat_conversation"("target_conversation_id" "uuid", "require_write" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.conversations conversation_row
    where conversation_row.id = target_conversation_id
      and (not require_write or (
        conversation_row.status = 'active' and not conversation_row.is_read_only
      ))
      and (
        exists (
          select 1
          from public.conversation_participants participant
          where participant.conversation_id = conversation_row.id
            and participant.person_id = app_private.current_person_id()
            and participant.status = 'active'
            and participant.left_at is null
        )
        or app_private.has_context_permission(
          conversation_row.institution_id,
          case when require_write then 'chat.manage' else 'chat.read' end,
          conversation_row.unit_id,
          conversation_row.group_id,
          conversation_row.activity_id,
          null,
          conversation_row.scope_kind = 'institution'
        )
      )
  )
$$;


ALTER FUNCTION "app_private"."can_access_chat_conversation"("target_conversation_id" "uuid", "require_write" boolean) OWNER TO "postgres";


