CREATE OR REPLACE FUNCTION "app_private"."chat_mark_read"("p_conversation_id" "uuid", "p_through_message_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("updated_count" integer, "read_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid:=app_private.current_person_id();cutoff timestamptz;marked_at timestamptz:=now();
begin
 if actor_id is null then raise insufficient_privilege using message='authentication required'; end if;
 if not app_private.can_access_chat_conversation(p_conversation_id,false) then return query select 0,marked_at;return; end if;
 if p_through_message_id is not null then
  select created_at into cutoff from public.messages where id=p_through_message_id
   and conversation_id=p_conversation_id and status='active' and deleted_at is null;
  if cutoff is null then return query select 0,marked_at;return; end if;
 end if;
 insert into audit.audit_logs(actor_person_id,action_code,object_type,object_id,institution_id,outcome,after_json)
 select actor_id,'chat.conversation.read','conversation',conversation_row.id,
  conversation_row.institution_id,'success',jsonb_build_object('through_message_id',p_through_message_id)
 from public.conversations conversation_row where conversation_row.id=p_conversation_id;
 return query with written as(insert into public.message_receipts(message_id,person_id,delivered_at,read_at)
  select message_row.id,actor_id,marked_at,marked_at from public.messages message_row
  where message_row.conversation_id=p_conversation_id and message_row.status='active'
   and message_row.deleted_at is null and message_row.author_person_id is distinct from actor_id
   and(cutoff is null or message_row.created_at<=cutoff)
  on conflict(message_id,person_id) do update set
   delivered_at=coalesce(public.message_receipts.delivered_at,excluded.delivered_at),
   read_at=coalesce(public.message_receipts.read_at,excluded.read_at)
  where public.message_receipts.read_at is null returning 1)
 select count(*)::integer,marked_at from written;
end $$;


ALTER FUNCTION "app_private"."chat_mark_read"("p_conversation_id" "uuid", "p_through_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."chat_media_dispatch_expire_worker"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_url text;
declare worker_secret text;
declare request_id bigint;
begin
  select decrypted_secret into worker_url
    from vault.decrypted_secrets where name = 'chat_media_worker_url' limit 1;
  select decrypted_secret into worker_secret
    from vault.decrypted_secrets where name = 'chat_media_worker_secret' limit 1;
  if nullif(worker_url, '') is null or nullif(worker_secret, '') is null then
    return null;
  end if;
  select net.http_post(
    url := worker_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-worker-secret', worker_secret
    ),
    body := '{"action":"expire"}'::jsonb,
    timeout_milliseconds := 5000
  ) into request_id;
  return request_id;
end;
$$;


ALTER FUNCTION "app_private"."chat_media_dispatch_expire_worker"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."chat_send_message"("p_conversation_id" "uuid", "p_body_text" "text", "p_idempotency_key" "uuid", "p_child_context_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS TABLE("message_id" "uuid", "created_at" timestamp with time zone, "replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := app_private.current_person_id();
  participant_record public.conversation_participants%rowtype;
  created_message public.messages%rowtype;
  existing_receipt app_private.chat_command_receipts%rowtype;
  normalized_body text := nullif(btrim(p_body_text), '');
  request_hash text;
begin
  if actor_id is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  if p_idempotency_key is null then
    raise invalid_parameter_value using message = 'idempotency key required';
  end if;
  if normalized_body is null or char_length(normalized_body) > 4000 then
    raise invalid_parameter_value using message = 'message body must contain 1 to 4000 characters';
  end if;
  if not app_private.can_access_chat_conversation(p_conversation_id, true) then
    raise insufficient_privilege using message = 'conversation is not writable';
  end if;
  if exists (
    select 1 from unnest(coalesce(p_child_context_ids, array[]::uuid[])) child_id
    where not exists (
      select 1 from public.conversation_child_contexts conversation_child
      where conversation_child.conversation_id = p_conversation_id
        and conversation_child.child_context_id = child_id
    )
  ) then
    raise invalid_parameter_value using message = 'message child is outside conversation';
  end if;

  request_hash := encode(
    extensions.digest(
      pg_catalog.convert_to(
        p_conversation_id::text || '|' || normalized_body || '|' || coalesce((
          select string_agg(child_id::text, ',' order by child_id::text)
          from (select distinct unnest(coalesce(p_child_context_ids, array[]::uuid[])) as child_id) children
        ), ''),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(actor_id::text || p_idempotency_key::text, 0)
  );
  select * into existing_receipt
  from app_private.chat_command_receipts
  where chat_command_receipts.actor_person_id = actor_id
    and command_name = 'send_message'
    and idempotency_key = p_idempotency_key
  for update;
  if existing_receipt.idempotency_key is not null then
    if existing_receipt.request_hash <> request_hash then
      raise unique_violation using message = 'idempotency key replay mismatch';
    end if;
    return query
      select existing_receipt.message_id, message_row.created_at, true
      from public.messages message_row
      where message_row.id = existing_receipt.message_id
        and message_row.conversation_id = p_conversation_id
        and app_private.can_access_chat_conversation(message_row.conversation_id, false);
    return;
  end if;

  select * into participant_record
  from public.conversation_participants participant
  where participant.conversation_id = p_conversation_id
    and participant.person_id = actor_id
    and participant.status = 'active'
    and participant.left_at is null
  order by participant.joined_at desc
  limit 1;
  if participant_record.id is null then
    raise insufficient_privilege using message = 'active participant required to send';
  end if;

  insert into public.messages(
    conversation_id, author_person_id, body_text, message_type,
    author_membership_id, author_experience_kind, author_role_snapshot
  ) values (
    p_conversation_id, actor_id, normalized_body, 'text',
    participant_record.membership_id, participant_record.experience_kind,
    participant_record.role_snapshot
  ) returning * into created_message;
  insert into public.message_child_contexts(message_id, child_context_id)
  select created_message.id, child_id
  from (select distinct unnest(coalesce(p_child_context_ids, array[]::uuid[])) as child_id) children;
  insert into app_private.chat_command_receipts(
    idempotency_key, actor_person_id, command_name, request_hash, message_id
  ) values (
    p_idempotency_key, actor_id, 'send_message', request_hash, created_message.id
  );
  insert into audit.audit_logs(
    actor_person_id, actor_membership_id, action_code, object_type, object_id,
    institution_id, outcome, after_json
  )
  select actor_id, participant_record.membership_id, 'chat.message.send',
    'message', created_message.id, conversation_row.institution_id, 'success',
    jsonb_build_object('conversation_id', p_conversation_id, 'idempotency_key', p_idempotency_key)
  from public.conversations conversation_row
  where conversation_row.id = p_conversation_id;
  return query select created_message.id, created_message.created_at, false;
end
$$;


ALTER FUNCTION "app_private"."chat_send_message"("p_conversation_id" "uuid", "p_body_text" "text", "p_idempotency_key" "uuid", "p_child_context_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."child_care_notification_recipients_v1"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_child_context_id" "uuid", "p_actor_person_id" "uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with policy as (
    select coalesce(p.notify_unit, true) as notify_unit,
      coalesce(p.notify_child_hierarchy, true) as notify_child_hierarchy,
      coalesce(p.notify_other_guardians, true) as notify_other_guardians
    from (select 1) one left join public.unit_care_policies p on p.unit_id = p_unit_id
  ),
  child as (
    select cc.child_person_id from public.child_contexts cc where cc.id = p_child_context_id
  ),
  unit_people as (
    -- equipe da unidade: memberships ativas da instituicao com escopo na unidade ou na instituicao inteira
    select m.person_id from public.institution_memberships m
    where m.institution_id = p_institution_id and m.status = 'active' and m.revoked_at is null
      and (m.scope_kind = 'institution' or (m.scope_kind = 'unit' and m.scope_unit_id = p_unit_id))
      and m.role_code <> 'legal_representative'
      and (select notify_unit from policy)
  ),
  hierarchy_people as (
    -- profissionais atribuidos a crianca
    select m.person_id from public.professional_child_assignments a
    join public.institution_memberships m on m.id = a.membership_id
    where a.child_context_id = p_child_context_id and a.status = 'active' and a.revoked_at is null
      and m.status = 'active' and m.revoked_at is null
      and (select notify_child_hierarchy from policy)
    union
    -- professores (memberships com escopo na turma) das turmas da crianca
    select m.person_id from public.child_unit_links cul
    join public.child_group_links cgl on cgl.child_unit_link_id = cul.id and cgl.status = 'active'
    join public.institution_memberships m on m.scope_kind = 'group' and m.scope_group_id = cgl.group_id
      and m.status = 'active' and m.revoked_at is null
    where cul.child_context_id = p_child_context_id and cul.status = 'active' and cul.revoked_at is null
      and (select notify_child_hierarchy from policy)
  ),
  guardian_people as (
    select g.guardian_person_id from public.guardian_links g, child
    where g.child_person_id = child.child_person_id and g.status = 'active' and g.revoked_at is null
      and (select notify_other_guardians from policy)
  )
  select distinct all_people.person_id from (
    select person_id from unit_people
    union select person_id from hierarchy_people
    union select guardian_person_id from guardian_people
  ) all_people
  join public.people person on person.id = all_people.person_id
  -- pessoas de servico (espelho das identidades internas do Superadmin/Principal,
  -- 220400 e 20260911130000) nao recebem sino: o Superadmin nao e a unidade
  where person.person_type = 'adult' and person.deleted_at is null and person.status = 'active'
    and all_people.person_id is distinct from p_actor_person_id
$$;


ALTER FUNCTION "app_private"."child_care_notification_recipients_v1"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_child_context_id" "uuid", "p_actor_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."child_safety_acknowledge_alert"("p_request_id" "uuid", "p_alert_id" "uuid", "p_expected_version" bigint, "p_status" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare
  actor uuid:=app_private.current_person_id(); request_hash bytea; replay jsonb;
  current_row public.child_safety_alerts%rowtype; before_state jsonb; result jsonb;
begin
  if (select auth.uid()) is null or actor is null or p_request_id is null
    or p_expected_version is null or p_expected_version<1
    or not app_private.has_mfa_aal2()
    or p_status not in ('acknowledged','resolved')
    or char_length(btrim(coalesce(p_reason,''))) not between 3 and 500 then
    raise insufficient_privilege using message='child safety alert unavailable';
  end if;
  request_hash:=extensions.digest(convert_to(jsonb_build_object('alert_id',p_alert_id,
    'version',p_expected_version,'status',p_status,'reason',btrim(p_reason))::text,'utf8'),'sha256');
  perform pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_id::text,0));
  replay:=app_private.child_safety_receipt(p_request_id,actor,'acknowledge_alert',request_hash);
  if replay is not null then return replay; end if;
  select a.* into current_row from public.child_safety_alerts a
  where a.id=p_alert_id and app_private.child_safety_can_administer(
    a.institution_id,a.unit_id,a.child_context_id
  ) for update;
  if current_row.id is null then raise no_data_found using message='child safety record unavailable'; end if;
  if current_row.version<>p_expected_version then
    raise serialization_failure using message='stale child safety version';
  end if;
  before_state:=jsonb_build_object('status',current_row.status,'version',current_row.version);
  update public.child_safety_alerts set status=p_status::public.child_safety_alert_status,
    acknowledged_by_person_id=actor,acknowledged_at=coalesce(acknowledged_at,now()),
    resolution_reason=case when p_status='resolved' then btrim(p_reason) else resolution_reason end,
    version=version+1,updated_at=now() where id=current_row.id;
  result:=jsonb_build_object('alert_id',current_row.id,'status',p_status,
    'version',current_row.version+1);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,
    institution_id,outcome,reason,before_json,after_json)
  values(actor,auth.jwt()->>'aal','child_safety.alert.'||p_status,'child_safety_alert',
    current_row.id,current_row.institution_id,'success',btrim(p_reason),before_state,result);
  return app_private.child_safety_store_receipt(
    p_request_id,actor,'acknowledge_alert',request_hash,current_row.id,result
  );
end $$;


ALTER FUNCTION "app_private"."child_safety_acknowledge_alert"("p_request_id" "uuid", "p_alert_id" "uuid", "p_expected_version" bigint, "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."child_safety_add_unit_review_recipients"("p_event_id" "uuid", "p_institution_id" "uuid", "p_unit_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with memberships as (
    select m.id,m.person_id from public.institution_memberships m
    where m.institution_id=p_institution_id and m.status='active' and m.revoked_at is null
  ), effects as (
    select m.person_id,rp.effect from memberships m
    join public.institution_role_assignments a on a.membership_id=m.id
      and a.status='active' and a.scope_kind='unit' and a.scope_unit_id=p_unit_id
      and (a.starts_at is null or a.starts_at<=now())
      and (a.expires_at is null or a.expires_at>now())
    join public.institution_roles r on r.id=a.role_id and r.status='active'
      and (r.institution_id is null or r.institution_id=p_institution_id)
    join public.institution_role_permissions rp on rp.role_id=r.id
      and rp.status='active' and rp.revoked_at is null
    join public.institution_permissions p on p.id=rp.permission_id
      and p.code='authorized_people.manage' and p.status='active'
    union all
    select m.person_id,o.effect from memberships m
    join public.institution_member_permission_overrides o on o.membership_id=m.id
      and o.institution_id=p_institution_id and o.permission_code='authorized_people.manage'
      and o.scope_kind='unit' and o.scope_unit_id=p_unit_id
      and o.status='active' and o.revoked_at is null
      and (o.starts_at is null or o.starts_at<=now())
      and (o.expires_at is null or o.expires_at>now())
  ), allowed as (
    select person_id from effects group by person_id
    having bool_or(effect='allow') and not bool_or(effect='deny')
  )
  insert into public.context_notification_recipients(event_id,person_id)
    select p_event_id,person_id from allowed on conflict do nothing
$$;


ALTER FUNCTION "app_private"."child_safety_add_unit_review_recipients"("p_event_id" "uuid", "p_institution_id" "uuid", "p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."child_safety_authorization_care_notify_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    perform app_private.notify_child_care_event_v1(new.institution_id, new.unit_id, new.child_context_id,
      'child_safety.authorization.requested', 'authorized_person_authorization', new.id,
      jsonb_build_object('decision_status', new.decision_status::text, 'status', new.status::text), new.created_by_person_id);
  elsif new.decision_status is distinct from old.decision_status then
    perform app_private.notify_child_care_event_v1(new.institution_id, new.unit_id, new.child_context_id,
      'child_safety.authorization.' || new.decision_status::text, 'authorized_person_authorization', new.id,
      jsonb_build_object('decision_status', new.decision_status::text, 'status', new.status::text), new.decided_by_person_id);
  elsif new.status is distinct from old.status then
    perform app_private.notify_child_care_event_v1(new.institution_id, new.unit_id, new.child_context_id,
      'child_safety.authorization.' || new.status::text, 'authorized_person_authorization', new.id,
      jsonb_build_object('decision_status', new.decision_status::text, 'status', new.status::text),
      coalesce(new.suspended_by_person_id, new.created_by_person_id));
  end if;
  return new;
end $$;


ALTER FUNCTION "app_private"."child_safety_authorization_care_notify_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."child_safety_can_access_object"("p_name" "text", "p_write" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select exists(
  select 1 from public.child_safety_evidence e where e.object_path=p_name
    and (not p_write or e.created_by_person_id=app_private.current_person_id())
    and e.status=case when p_write then 'draft'::public.record_status else 'active'::public.record_status end
    and app_private.has_mfa_aal2()
    and (case when p_write then app_private.child_safety_can_manage(
      e.institution_id,e.unit_id,e.child_context_id
    ) else app_private.has_platform_permission('child_safety.read')
      or app_private.has_context_permission(e.institution_id,'authorized_people.manage',
        e.unit_id,null,null,e.child_context_id,false) end)
) $$;


