CREATE TABLE IF NOT EXISTS "app_private"."notice_publication_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "notice_id" "uuid" NOT NULL,
    "notice_version" bigint NOT NULL,
    "audience_snapshot" "jsonb" NOT NULL,
    "state" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "locked_at" timestamp with time zone,
    "locked_by" "text",
    "last_error_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "cursor_key" "text",
    "resolved_count" bigint DEFAULT 0 NOT NULL,
    CONSTRAINT "notice_publication_jobs_attempts_check" CHECK ((("attempts" >= 0) AND ("attempts" <= 20))),
    CONSTRAINT "notice_publication_jobs_state_check" CHECK (("state" = ANY (ARRAY['queued'::"text", 'processing'::"text", 'completed'::"text", 'failed'::"text"])))
);

ALTER TABLE ONLY "app_private"."notice_publication_jobs" FORCE ROW LEVEL SECURITY;


ALTER TABLE "app_private"."notice_publication_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."claim_notice_publication_jobs"("p_worker" "text", "p_limit" integer DEFAULT 20) RETURNS SETOF "app_private"."notice_publication_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.role() is distinct from 'service_role'
    or p_limit not between 1 and 100
    or length(trim(coalesce(p_worker, ''))) not between 1 and 120 then
    raise exception using errcode = '42501', message = 'not_authorized';
  end if;

  update app_private.notice_publication_jobs
  set state = 'failed', available_at = now(), locked_at = null, locked_by = null,
      last_error_code = 'lease_expired'
  where state = 'processing'
    and locked_at < now() - interval '5 minutes'
    and attempts < 20;

  return query
  with claimed as (
    select id from app_private.notice_publication_jobs
    where state in ('queued', 'failed') and available_at <= now() and attempts < 20
    order by available_at, created_at
    for update skip locked
    limit p_limit
  )
  update app_private.notice_publication_jobs job
  set state = 'processing', attempts = job.attempts + 1, locked_at = now(),
      locked_by = trim(p_worker), last_error_code = null
  from claimed
  where job.id = claimed.id
  returning job.*;
end
$$;


ALTER FUNCTION "app_private"."claim_notice_publication_jobs"("p_worker" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."claim_stale_circular_media"("p_limit" integer DEFAULT 50) RETURNS TABLE("asset_id" "uuid", "object_key" "text", "storage_provider" "text", "bucket_id" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return query with claimed as (
    select m.id from public.circular_media_assets m where m.status in ('pending','orphaned') and m.created_at<now()-interval '30 minutes'
      and (m.cleanup_attempted_at is null or m.cleanup_attempted_at<now()-interval '10 minutes') order by m.created_at for update skip locked limit least(greatest(coalesce(p_limit,50),1),200)
  ) update public.circular_media_assets m set status='orphaned',cleanup_attempted_at=now() from claimed where m.id=claimed.id returning m.id,m.object_key,m.storage_provider,m.bucket_id;
end $$;


ALTER FUNCTION "app_private"."claim_stale_circular_media"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."claim_stale_moments_media"("p_limit" integer DEFAULT 50) RETURNS TABLE("asset_id" "uuid", "object_key" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return query
  with claimed as (
    select media.id
    from public.moments_media_assets media
    where media.status in ('pending', 'orphaned')
      and media.created_at < now() - interval '30 minutes'
      and (
        media.cleanup_attempted_at is null
        or media.cleanup_attempted_at < now() - interval '10 minutes'
      )
    order by media.created_at
    for update skip locked
    limit least(greatest(coalesce(p_limit, 50), 1), 200)
  )
  update public.moments_media_assets media set
    status = 'orphaned',
    cleanup_attempted_at = now()
  from claimed
  where media.id = claimed.id
  returning media.id, media.object_key;
end
$$;


ALTER FUNCTION "app_private"."claim_stale_moments_media"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."close_incompatible_legal_representatives_for_person"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  update public.institution_legal_representatives representative_link
  set
    status = 'inactive',
    ends_on = coalesce(
      representative_link.ends_on,
      greatest(current_date, representative_link.starts_on)
    )
  where representative_link.person_id = new.id
    and representative_link.status = 'active'
    and (
      new.person_type <> 'adult'
      or new.date_of_birth is null
      or new.date_of_birth > (
        representative_link.starts_on - interval '18 years'
      )::date
    );

  return new;
end;
$$;


ALTER FUNCTION "app_private"."close_incompatible_legal_representatives_for_person"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."close_legal_representatives_for_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.status <> 'active' or new.revoked_at is not null then
    update public.institution_legal_representatives
    set
      status = 'inactive',
      ends_on = coalesce(ends_on, greatest(current_date, starts_on))
    where membership_id = new.id
      and status = 'active';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."close_legal_representatives_for_membership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."cnpj_digits_valid_v1"("p_digits" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  w1 integer[] := array[5,4,3,2,9,8,7,6,5,4,3,2];
  w2 integer[] := array[6,5,4,3,2,9,8,7,6,5,4,3,2];
  d integer[];
  s integer := 0;
  i integer;
  dv1 integer;
  dv2 integer;
begin
  if p_digits is null or p_digits !~ '^[0-9]{14}$' then
    return false;
  end if;
  if p_digits ~ '^(\d)\1{13}$' then
    return false;
  end if;
  for i in 1..14 loop
    d[i] := pg_catalog.substr(p_digits, i, 1)::integer;
  end loop;
  for i in 1..12 loop s := s + d[i] * w1[i]; end loop;
  dv1 := case when s % 11 < 2 then 0 else 11 - (s % 11) end;
  if dv1 <> d[13] then return false; end if;
  s := 0;
  for i in 1..13 loop s := s + d[i] * w2[i]; end loop;
  dv2 := case when s % 11 < 2 then 0 else 11 - (s % 11) end;
  return dv2 = d[14];
end
$_$;


ALTER FUNCTION "app_private"."cnpj_digits_valid_v1"("p_digits" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."coelo_profile_follow_sync"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  coelo constant uuid := 'c0e10000-0000-4000-8000-000000000001';
  touched integer := 0;
  n integer;
begin
  -- todos acompanham a Coelo
  insert into public.follow_links (follower_person_id, target_kind, target_id, origin)
  select person.id, 'person', coelo, 'manual'
  from public.people person
  where person.status = 'active' and person.deleted_at is null and person.id <> coelo
    and not exists (
      select 1 from public.follow_links link
      where link.follower_person_id = person.id and link.target_kind = 'person'
        and link.target_id = coelo and link.status = 'active'
    );
  get diagnostics n = row_count; touched := touched + n;
  -- a Coelo acompanha todos
  insert into public.follow_links (follower_person_id, target_kind, target_id, origin)
  select coelo, 'person', person.id, 'manual'
  from public.people person
  where person.status = 'active' and person.deleted_at is null and person.id <> coelo
    and not exists (
      select 1 from public.follow_links link
      where link.follower_person_id = coelo and link.target_kind = 'person'
        and link.target_id = person.id and link.status = 'active'
    );
  get diagnostics n = row_count; touched := touched + n;
  return touched;
end
$$;


ALTER FUNCTION "app_private"."coelo_profile_follow_sync"() OWNER TO "postgres";


