CREATE OR REPLACE FUNCTION "app_private"."confirm_attendance_record"("target_session_id" "uuid", "target_child_context_id" "uuid", "target_outcome" "text", "target_notice_id" "uuid", "target_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid:=app_private.current_person_id();
  session_record public.attendance_sessions%rowtype;
  existing_record public.attendance_records%rowtype;
  result_id uuid;
begin
  if target_outcome not in (
    'present','absent','late_arrival','early_departure','late_and_early'
  ) then raise exception 'invalid attendance outcome'; end if;
  select * into session_record from public.attendance_sessions
  where id=target_session_id and status in ('open','closed');
  if session_record.id is null then raise exception 'attendance session not found'; end if;
  if not app_private.can_access_attendance_child(
    session_record.institution_id,session_record.unit_id,session_record.group_id,
    session_record.activity_id,target_child_context_id,true
  ) then raise exception 'attendance management required'; end if;
  select * into existing_record from public.attendance_records
  where attendance_session_id=target_session_id
    and child_context_id=target_child_context_id and status='active'
  for update;
  if existing_record.id is null then
    insert into public.attendance_records(
      attendance_session_id,child_context_id,outcome,source_notice_id,note,
      confirmed_by_person_id
    ) values (
      target_session_id,target_child_context_id,target_outcome,target_notice_id,
      nullif(btrim(target_note),''),actor_person_id
    ) returning id into result_id;
    insert into public.attendance_record_revisions(
      attendance_record_id,action_code,after_json,changed_by_person_id
    ) select id,'confirmed',to_jsonb(record_row),actor_person_id
      from public.attendance_records record_row where id=result_id;
  else
    update public.attendance_records set
      outcome=target_outcome,source_notice_id=target_notice_id,
      note=nullif(btrim(target_note),''),confirmed_by_person_id=actor_person_id,
      confirmed_at=now(),updated_at=now()
    where id=existing_record.id returning id into result_id;
    insert into public.attendance_record_revisions(
      attendance_record_id,action_code,before_json,after_json,changed_by_person_id
    ) select result_id,'corrected',to_jsonb(existing_record),to_jsonb(record_row),
      actor_person_id from public.attendance_records record_row where id=result_id;
  end if;
  if target_notice_id is not null then
    update public.attendance_notices set review_status='confirmed',
      reviewed_by_person_id=actor_person_id,reviewed_at=now(),
      updated_at=now()
    where id=target_notice_id and child_context_id=target_child_context_id
      and institution_id=session_record.institution_id;
  end if;
  return result_id;
end;
$$;


ALTER FUNCTION "app_private"."confirm_attendance_record"("target_session_id" "uuid", "target_child_context_id" "uuid", "target_outcome" "text", "target_notice_id" "uuid", "target_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."cpf_digits_valid_v1"("p_digits" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  sum1 integer := 0;
  sum2 integer := 0;
  d integer[];
  i integer;
begin
  if p_digits is null or p_digits !~ '^[0-9]{11}$' then
    return false;
  end if;
  if p_digits ~ '^(\d)\1{10}$' then
    return false;
  end if;
  for i in 1..11 loop
    d[i] := pg_catalog.substr(p_digits, i, 1)::integer;
  end loop;
  for i in 1..9 loop
    sum1 := sum1 + d[i] * (11 - i);
  end loop;
  sum1 := (sum1 * 10) % 11;
  if sum1 = 10 then sum1 := 0; end if;
  if sum1 <> d[10] then return false; end if;
  for i in 1..10 loop
    sum2 := sum2 + d[i] * (12 - i);
  end loop;
  sum2 := (sum2 * 10) % 11;
  if sum2 = 10 then sum2 := 0; end if;
  return sum2 = d[11];
end
$_$;


ALTER FUNCTION "app_private"."cpf_digits_valid_v1"("p_digits" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."activity_definitions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "origin_scope_kind" "public"."activity_origin_scope" NOT NULL,
    "origin_unit_id" "uuid",
    "created_by_person_id" "uuid",
    "status" "public"."record_status" DEFAULT 'active'::"public"."record_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    "distribution_scope" "text" DEFAULT 'unit_local'::"text" NOT NULL,
    "governance_kind" "text" DEFAULT 'optional'::"text" NOT NULL,
    "promoted_by_person_id" "uuid",
    "promoted_at" timestamp with time zone,
    "handle_stem" "text" NOT NULL,
    "canonical_handle" "text" NOT NULL,
    "management_version" bigint DEFAULT 1 NOT NULL,
    "taxonomy_id" "uuid",
    "taxonomy_other_description" "text",
    "template_id" "uuid",
    "identity_mode" "text" DEFAULT 'initials'::"text" NOT NULL,
    "identity_storage_bucket" "text",
    "identity_storage_path" "text",
    "identity_initials" "text",
    "identity_color" "text",
    "identity_icon" "text",
    "identity_checksum_sha256" "text",
    "created_by_actor_kind" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("created_by_person_id" IS NULL) THEN 'superadmin_internal'::"text"
    ELSE 'person'::"text"
END) STORED,
    "handle_last_changed_at" timestamp with time zone,
    CONSTRAINT "activity_definitions_archive_check" CHECK (((("status" = 'archived'::"public"."record_status") AND ("archived_at" IS NOT NULL)) OR (("status" <> 'archived'::"public"."record_status") AND ("archived_at" IS NULL)))),
    CONSTRAINT "activity_definitions_canonical_handle_check" CHECK ((("canonical_handle" = "lower"("canonical_handle")) AND ("canonical_handle" ~ '^[a-z0-9-]+(?:\.[a-z0-9-]+)+$'::"text"))),
    CONSTRAINT "activity_definitions_description_not_blank" CHECK ((("description" IS NULL) OR ("btrim"("description") <> ''::"text"))),
    CONSTRAINT "activity_definitions_distribution_scope_check" CHECK (("distribution_scope" = ANY (ARRAY['institution_standard'::"text", 'unit_local'::"text"]))),
    CONSTRAINT "activity_definitions_governance_kind_check" CHECK (("governance_kind" = ANY (ARRAY['optional'::"text", 'mandatory'::"text", 'fixed'::"text"]))),
    CONSTRAINT "activity_definitions_handle_check" CHECK ((("handle_stem" = "lower"("handle_stem")) AND ("handle_stem" ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::"text"))),
    CONSTRAINT "activity_definitions_identity_checksum_sha256_check" CHECK ((("identity_checksum_sha256" IS NULL) OR ("identity_checksum_sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "activity_definitions_identity_color_check" CHECK ((("identity_color" IS NULL) OR ("identity_color" ~ '^#[0-9A-Fa-f]{6}$'::"text"))),
    CONSTRAINT "activity_definitions_identity_icon_check" CHECK ((("identity_icon" IS NULL) OR ("identity_icon" = ANY (ARRAY['pool'::"text", 'sports_soccer'::"text", 'music_note'::"text", 'palette'::"text", 'menu_book'::"text", 'science'::"text", 'school'::"text", 'fitness_center'::"text", 'eco'::"text", 'restaurant'::"text", 'psychology'::"text", 'sports_martial_arts'::"text"])))),
    CONSTRAINT "activity_definitions_identity_initials_check" CHECK ((("identity_initials" IS NULL) OR (("length"("btrim"("identity_initials")) >= 1) AND ("length"("btrim"("identity_initials")) <= 2)))),
    CONSTRAINT "activity_definitions_identity_mode_check" CHECK (("identity_mode" = ANY (ARRAY['photo'::"text", 'initials'::"text", 'icon'::"text"]))),
    CONSTRAINT "activity_definitions_identity_storage_check" CHECK (((("identity_storage_bucket" IS NULL) AND ("identity_storage_path" IS NULL)) OR (("identity_storage_bucket" = 'coelo-identities'::"text") AND ("identity_storage_path" ~~ (('activities/'::"text" || ("id")::"text") || '/%'::"text"))))),
    CONSTRAINT "activity_definitions_management_version_check" CHECK (("management_version" > 0)),
    CONSTRAINT "activity_definitions_name_not_blank" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "activity_definitions_origin_check" CHECK (((("origin_scope_kind" = 'institution'::"public"."activity_origin_scope") AND ("origin_unit_id" IS NULL)) OR (("origin_scope_kind" = 'unit'::"public"."activity_origin_scope") AND ("origin_unit_id" IS NOT NULL)))),
    CONSTRAINT "activity_definitions_promotion_check" CHECK (((("distribution_scope" = 'unit_local'::"text") AND ("promoted_by_person_id" IS NULL) AND ("promoted_at" IS NULL)) OR ("distribution_scope" = 'institution_standard'::"text"))),
    CONSTRAINT "activity_definitions_taxonomy_other_check" CHECK ((("taxonomy_other_description" IS NULL) OR (("btrim"("taxonomy_other_description") <> ''::"text") AND ("length"("taxonomy_other_description") <= 500))))
);

ALTER TABLE ONLY "public"."activity_definitions" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."activity_definitions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_activity_for_institution"("target_institution_id" "uuid", "initial_unit_id" "uuid", "activity_name" "text", "activity_description" "text" DEFAULT NULL::"text", "audit_reason" "text" DEFAULT NULL::"text") RETURNS "public"."activity_definitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid;
  created_activity public.activity_definitions;
begin
  actor_person_id := app_private.current_person_id();

  if auth.uid() is null or actor_person_id is null then
    raise insufficient_privilege using message = 'authenticated person is required';
  end if;

  if btrim(coalesce(activity_name, '')) = '' then
    raise check_violation using message = 'activity name is required';
  end if;

  if not exists (
    select 1
    from public.units unit_record
    where unit_record.id = initial_unit_id
      and unit_record.institution_id = target_institution_id
      and unit_record.status = 'active'
  ) then
    raise foreign_key_violation using
      message = 'initial unit must be active and belong to the institution';
  end if;

  if not app_private.has_institution_permission(
    target_institution_id,
    'activities.create',
    initial_unit_id,
    null,
    true
  ) then
    raise insufficient_privilege using
      message = 'activities.create at institution scope is required';
  end if;

  perform set_config('coelo.audit_reason', coalesce(audit_reason, ''), true);

  insert into public.activity_definitions(
    institution_id,
    name,
    description,
    origin_scope_kind,
    created_by_person_id
  ) values (
    target_institution_id,
    btrim(activity_name),
    nullif(btrim(coalesce(activity_description, '')), ''),
    'institution',
    actor_person_id
  )
  returning * into created_activity;

  insert into public.activity_unit_links(
    activity_id,
    institution_id,
    unit_id,
    linked_by_person_id
  ) values (
    created_activity.id,
    target_institution_id,
    initial_unit_id,
    actor_person_id
  );

  return created_activity;
end
$$;


ALTER FUNCTION "app_private"."create_activity_for_institution"("target_institution_id" "uuid", "initial_unit_id" "uuid", "activity_name" "text", "activity_description" "text", "audit_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_activity_for_unit"("origin_unit_id" "uuid", "activity_name" "text", "activity_description" "text" DEFAULT NULL::"text", "audit_reason" "text" DEFAULT NULL::"text") RETURNS "public"."activity_definitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid;
  derived_institution_id uuid;
  created_activity public.activity_definitions;
begin
  actor_person_id := app_private.current_person_id();

  if auth.uid() is null or actor_person_id is null then
    raise insufficient_privilege using message = 'authenticated person is required';
  end if;

  if btrim(coalesce(activity_name, '')) = '' then
    raise check_violation using message = 'activity name is required';
  end if;

  select unit_record.institution_id
  into derived_institution_id
  from public.units unit_record
  where unit_record.id = origin_unit_id
    and unit_record.status = 'active';

  if derived_institution_id is null then
    raise foreign_key_violation using message = 'active origin unit is required';
  end if;

  if not app_private.has_institution_permission(
    derived_institution_id,
    'activities.create',
    origin_unit_id,
    null,
    false

  ) then
    raise insufficient_privilege using
      message = 'activities.create for the origin unit is required';
  end if;

  perform set_config('coelo.audit_reason', coalesce(audit_reason, ''), true);

  insert into public.activity_definitions(
    institution_id,
    name,
    description,
    origin_scope_kind,
    origin_unit_id,
    created_by_person_id
  ) values (
    derived_institution_id,
    btrim(activity_name),
    nullif(btrim(coalesce(activity_description, '')), ''),
    'unit',
    origin_unit_id,
    actor_person_id
  )
  returning * into created_activity;

  insert into public.activity_unit_links(
    activity_id,
    institution_id,
    unit_id,
    linked_by_person_id
  ) values (
    created_activity.id,
    derived_institution_id,
    origin_unit_id,
    actor_person_id
  );

  return created_activity;
end
$$;


ALTER FUNCTION "app_private"."create_activity_for_unit"("origin_unit_id" "uuid", "activity_name" "text", "activity_description" "text", "audit_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_authorized_person_authorization"("target_child_context_id" "uuid", "target_unit_id" "uuid", "target_display_name" "text", "target_relationship_code" "text", "target_relationship_detail" "text", "target_document_ciphertext" "bytea", "target_document_fingerprint" "text", "target_document_last4" "text", "target_document_type" "text", "target_capability_codes" "text"[], "target_valid_from" "date", "target_valid_until" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid := app_private.current_person_id();
  target_institution_id uuid;
  guardian_link_id uuid;
  relationship_id uuid;
  authorized_person_id uuid;
  authorization_id uuid;
  notification_id uuid;
begin
  select child_context.institution_id into target_institution_id
  from public.child_contexts child_context
  where child_context.id = target_child_context_id
    and child_context.status = 'active';
  if target_institution_id is null or not exists (
    select 1 from public.units unit_record
    where unit_record.id = target_unit_id
      and unit_record.institution_id = target_institution_id
  ) then
    raise exception 'invalid child or unit context';
  end if;

  select guardian.id into guardian_link_id
  from public.guardian_links guardian
  join public.child_contexts child_context
    on child_context.child_person_id = guardian.child_person_id
  where child_context.id = target_child_context_id
    and guardian.guardian_person_id = actor_person_id
    and guardian.status = 'active'
    and guardian.revoked_at is null;

  if guardian_link_id is null
     or not app_private.guardian_has_capability(
       target_child_context_id, 'manage_authorized_people'
     ) then
    raise exception 'guardian cannot manage authorized people';
  end if;

  select relationship.id into relationship_id
  from public.family_relationship_types relationship
  where relationship.code = target_relationship_code and relationship.status = 'active';
  if relationship_id is null then raise exception 'invalid relationship code'; end if;
  if target_relationship_code = 'other'
     and nullif(btrim(target_relationship_detail), '') is null then
    raise exception 'relationship detail is required for other';
  end if;

  insert into public.authorized_people(
    institution_id, display_name, document_type, document_ciphertext,
    document_fingerprint, document_last4
  ) values (
    target_institution_id, btrim(target_display_name), target_document_type,
    target_document_ciphertext, target_document_fingerprint, target_document_last4
  ) returning id into authorized_person_id;

  insert into public.authorized_person_authorizations(
    authorized_person_id, institution_id, child_context_id, unit_id,
    relationship_type_id, relationship_detail, created_by_guardian_link_id,
    created_by_person_id, valid_from, valid_until
  ) values (
    authorized_person_id, target_institution_id, target_child_context_id,
    target_unit_id, relationship_id, nullif(btrim(target_relationship_detail), ''),
    guardian_link_id, actor_person_id, coalesce(target_valid_from, current_date),
    target_valid_until
  ) returning id into authorization_id;

  insert into public.authorized_person_authorization_capabilities(
    authorization_id, capability_code
  )
  select distinct authorization_id, capability_code
  from unnest(target_capability_codes) capability_code
  where capability_code in ('emergency_contact','pickup','transport');

  insert into public.context_notification_events(
    institution_id, unit_id, child_context_id, event_code, object_type,
    object_id, payload_json, created_by_person_id
  ) values (
    target_institution_id, target_unit_id, target_child_context_id,
    'authorized_person_created', 'authorized_person_authorization',
    authorization_id, jsonb_build_object('status', 'active'), actor_person_id
  ) returning id into notification_id;

  insert into public.context_notification_recipients(event_id, person_id)
  select notification_id, guardian.guardian_person_id
  from public.guardian_links guardian
  join public.child_contexts child_context
    on child_context.child_person_id = guardian.child_person_id
  where child_context.id = target_child_context_id
    and guardian.status = 'active' and guardian.revoked_at is null
  on conflict do nothing;

  return authorization_id;
end;
$$;


ALTER FUNCTION "app_private"."create_authorized_person_authorization"("target_child_context_id" "uuid", "target_unit_id" "uuid", "target_display_name" "text", "target_relationship_code" "text", "target_relationship_detail" "text", "target_document_ciphertext" "bytea", "target_document_fingerprint" "text", "target_document_last4" "text", "target_document_type" "text", "target_capability_codes" "text"[], "target_valid_from" "date", "target_valid_until" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."conversations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "scope_kind" "text" NOT NULL,
    "scope_id" "uuid",
    "conversation_type" "text" NOT NULL,
    "title" "text",
    "status" "public"."record_status" DEFAULT 'active'::"public"."record_status" NOT NULL,
    "policy_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "unit_id" "uuid",
    "group_id" "uuid",
    "activity_id" "uuid",
    "routing_team_id" "uuid",
    "is_read_only" boolean DEFAULT false NOT NULL,
    "read_only_reason" "text"
);


ALTER TABLE "public"."conversations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_context_conversation"("target_institution_id" "uuid", "target_scope_kind" "text", "target_unit_id" "uuid" DEFAULT NULL::"uuid", "target_group_id" "uuid" DEFAULT NULL::"uuid", "target_activity_id" "uuid" DEFAULT NULL::"uuid", "target_conversation_type" "text" DEFAULT 'direct'::"text", "target_title" "text" DEFAULT NULL::"text", "target_routing_team_id" "uuid" DEFAULT NULL::"uuid", "target_child_context_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS "public"."conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid := app_private.current_person_id();
  actor_membership public.institution_memberships%rowtype;
  created_conversation public.conversations%rowtype;
  is_context_manager boolean;
  is_family_initiator boolean;
begin
  if actor_person_id is null then
    raise exception 'authenticated person required';
  end if;
  if target_scope_kind not in ('institution', 'unit', 'group', 'activity') then
    raise exception 'invalid conversation scope';
  end if;
  if nullif(btrim(target_conversation_type), '') is null then
    raise exception 'conversation type required';
  end if;

  is_context_manager := app_private.has_context_permission(
    target_institution_id,
    'chat.manage',
    target_unit_id,
    target_group_id,
    target_activity_id,
    null,
    target_scope_kind = 'institution'
  );

  is_family_initiator :=
    coalesce(cardinality(target_child_context_ids), 0) > 0
    and not exists (
      select 1
      from unnest(target_child_context_ids) as requested_child(child_context_id)
      where not app_private.guardian_has_capability(
        requested_child.child_context_id,
        'message'
      )
    )
    and not exists (
      select 1
      from unnest(target_child_context_ids) as requested_child(child_context_id)
      where not exists (
        select 1
        from public.child_contexts child_context
        where child_context.id = requested_child.child_context_id
          and child_context.institution_id = target_institution_id
          and child_context.status = 'active'
          and (
            target_scope_kind = 'institution'
            or (
              target_scope_kind = 'unit'
              and exists (
                select 1
                from public.child_unit_links child_unit
                where child_unit.child_context_id = child_context.id
                  and child_unit.unit_id = target_unit_id
                  and child_unit.status in ('awaiting_allocation', 'active')
              )
            )
            or (
              target_scope_kind in ('group', 'activity')
              and exists (
                select 1
                from public.child_unit_links child_unit
                join public.child_group_links child_group
                  on child_group.child_unit_link_id = child_unit.id
                 and child_group.group_id = target_group_id
                 and child_group.status = 'active'
                where child_unit.child_context_id = child_context.id
                  and child_unit.unit_id = target_unit_id
                  and child_unit.status = 'active'
              )
            )
          )
      )
    );

  if is_family_initiator and target_scope_kind = 'institution' then
    is_family_initiator := coalesce((
      select setting.institution_chat_enabled
      from public.institution_chat_settings setting
      where setting.institution_id = target_institution_id
    ), true);
  elsif is_family_initiator and target_scope_kind = 'unit' then
    is_family_initiator :=
      coalesce((
        select setting.unit_chat_enabled
        from public.institution_chat_settings setting
        where setting.institution_id = target_institution_id
      ), true)
      and coalesce((
        select setting.is_enabled
        from public.unit_chat_settings setting
        where setting.unit_id = target_unit_id
          and setting.institution_id = target_institution_id
      ), true);
  end if;

  if not is_context_manager and not is_family_initiator then
    raise exception 'conversation creation denied';
  end if;

  if target_routing_team_id is not null and not exists (
    select 1
    from public.conversation_routing_teams team
    where team.id = target_routing_team_id
      and team.institution_id = target_institution_id
      and (team.unit_id is null or team.unit_id = target_unit_id)
      and team.status = 'active'
  ) then
    raise exception 'invalid routing team';
  end if;

  insert into public.conversations(
    institution_id,
    scope_kind,
    scope_id,
    conversation_type,
    title,
    created_by,
    unit_id,
    group_id,
    activity_id,
    routing_team_id
  )
  values (
    target_institution_id,
    target_scope_kind,
    case target_scope_kind
      when 'unit' then target_unit_id
      when 'group' then target_group_id
      when 'activity' then target_activity_id
      else null
    end,
    btrim(target_conversation_type),
    nullif(btrim(target_title), ''),
    actor_person_id,
    target_unit_id,
    target_group_id,
    target_activity_id,
    target_routing_team_id
  )
  returning * into created_conversation;

  select *
  into actor_membership
  from public.institution_memberships membership
  where membership.person_id = actor_person_id
    and membership.institution_id = target_institution_id
    and membership.status = 'active'
    and membership.revoked_at is null
  order by membership.created_at desc
  limit 1;

  insert into public.conversation_participants(
    conversation_id,
    person_id,
    membership_id,
    experience_kind,
    role_snapshot
  )
  values (
    created_conversation.id,
    actor_person_id,
    actor_membership.id,
    case when actor_membership.id is null then 'family' else 'professional' end,
    coalesce(nullif(actor_membership.role_code, ''), 'responsavel')
  );

  insert into public.conversation_child_contexts(
    conversation_id,
    child_context_id
  )
  select created_conversation.id, requested_child.child_context_id
  from (
    select distinct unnest(target_child_context_ids) as child_context_id
  ) requested_child;

  insert into public.conversation_participants(
    conversation_id,
    person_id,
    membership_id,
    experience_kind,
    role_snapshot
  )
  select
    created_conversation.id,
    membership.person_id,
    membership.id,
    'professional',
    membership.role_code
  from public.conversation_routing_team_members team_member
  join public.institution_memberships membership
    on membership.id = team_member.membership_id
   and membership.institution_id = target_institution_id
   and membership.status = 'active'
   and membership.revoked_at is null
  where team_member.team_id = target_routing_team_id
    and team_member.status = 'active'
    and team_member.removed_at is null
  on conflict do nothing;

  insert into audit.audit_logs(
    actor_person_id,
    actor_membership_id,
    action_code,
    object_type,
    object_id,
    institution_id,
    outcome,
    after_json
  )
  values (
    actor_person_id,
    actor_membership.id,
    'chat.conversation.create',
    'conversation',
    created_conversation.id,
    target_institution_id,
    'success',
    jsonb_build_object(
      'scope_kind', target_scope_kind,
      'unit_id', target_unit_id,
      'group_id', target_group_id,
      'activity_id', target_activity_id,
      'child_context_ids', target_child_context_ids
    )
  );

  return created_conversation;
end;
$$;


ALTER FUNCTION "app_private"."create_context_conversation"("target_institution_id" "uuid", "target_scope_kind" "text", "target_unit_id" "uuid", "target_group_id" "uuid", "target_activity_id" "uuid", "target_conversation_type" "text", "target_title" "text", "target_routing_team_id" "uuid", "target_child_context_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_institution_for_superadmin"("p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_variable
declare
  actor_person_id uuid;
  institution_id uuid;
  institution_type_id uuid;
  plan_id uuid;
  plan_code text;
  requested_status public.institution_status;
  request_hash bytea;
  result jsonb;
  prior_hash bytea;
  prior_actor uuid;
  prior_command text;
  prior_institution_id uuid;
  prior_result_management_version bigint;
  changed_fields jsonb;
  effective_payload jsonb;
  subscription_changed boolean := false;
begin
  perform effective_payload, subscription_changed; -- Reserved for parity with the update command.
  if p_request_id is null then
    raise invalid_parameter_value using message = 'request_id is required';
  end if;
  if (select auth.uid()) is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  actor_person_id := app_private.current_person_id();
  if actor_person_id is null then
    raise insufficient_privilege using message = 'active person identity required';
  end if;
  if not app_private.has_scoped_platform_permission('institution.activate', null) then
    raise insufficient_privilege using message = 'institution.activate required';
  end if;
  if not app_private.has_mfa_aal2() then
    raise insufficient_privilege using message = 'MFA AAL2 required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
  request_hash := app_private.institution_management_request_hash(p_payload);
  select receipt.request_hash, receipt.actor_person_id,
         receipt.command_kind, receipt.institution_id,
         receipt.result_management_version
    into prior_hash, prior_actor, prior_command, prior_institution_id,
         prior_result_management_version
  from app_private.institution_management_command_receipts receipt
  where receipt.request_id = p_request_id;
  if prior_institution_id is not null then
    if prior_actor is distinct from actor_person_id
       or prior_command is distinct from 'create'
       or prior_hash is distinct from request_hash then
      raise invalid_parameter_value using
        message = 'request_id already used with a different command payload';
    end if;
    result := app_private.institution_management_payload(prior_institution_id);
    if result is null then
      raise no_data_found using message = 'institution receipt target not found';
    end if;
    if (result ->> 'management_version')::bigint
       is distinct from prior_result_management_version then
      raise serialization_failure using
        message = 'receipt result version is no longer current';
    end if;
    return result;
  end if;

  perform app_private.assert_institution_management_payload(p_payload, true);
  requested_status := coalesce(p_payload ->> 'status', 'draft')
    ::public.institution_status;
  if requested_status <> 'draft'
     and not app_private.has_scoped_platform_permission('institution.status.change', null) then
    raise insufficient_privilege using
      message = 'institution.status.change required for non-draft create';
  end if;
  select type_record.id into institution_type_id
  from public.institution_types type_record
  where lower(type_record.name) = lower(btrim(p_payload ->> 'institution_type_name'))
    and type_record.status = 'active'
  limit 1;
  if institution_type_id is null then
    raise invalid_parameter_value using message = 'unknown or inactive institution type';
  end if;

  plan_id := null;
  if p_payload ? 'subscription' then
    if not app_private.has_scoped_platform_permission('plan.change', null) then
      raise insufficient_privilege using message = 'plan.change required';
    end if;
    plan_code := lower(btrim(p_payload -> 'subscription' ->> 'plan_code'));
    select plan_record.id into plan_id
    from public.plans plan_record
    where plan_record.code = plan_code and plan_record.status = 'active'
    limit 1;
    if plan_id is null then
      raise invalid_parameter_value using message = 'unknown or inactive plan';
    end if;
  end if;

  insert into public.institutions(
    public_name, trade_name, legal_name, slug, primary_domain, document_ref,
    document_type, status, timezone, locale, institution_type_id,
    created_by, management_version
  ) values (
    btrim(p_payload ->> 'public_name'),
    nullif(btrim(p_payload ->> 'trade_name'), ''),
    nullif(btrim(p_payload ->> 'legal_name'), ''),
    lower(btrim(p_payload ->> 'slug')),
    nullif(lower(btrim(p_payload ->> 'primary_domain')), ''),
    nullif(btrim(p_payload ->> 'document_ref'), ''),
    coalesce(nullif(btrim(p_payload ->> 'document_type'), ''), 'cnpj'),
    requested_status,
    coalesce(nullif(btrim(p_payload ->> 'timezone'), ''), 'America/Sao_Paulo'),
    coalesce(nullif(btrim(p_payload ->> 'locale'), ''), 'pt-BR'),
    institution_type_id, actor_person_id, 1
  ) returning id into institution_id;

  perform app_private.apply_institution_management_children(
    institution_id, actor_person_id, p_payload, plan_id
  );
  select coalesce(jsonb_agg(key_name order by key_name), '[]'::jsonb)
    into changed_fields from jsonb_object_keys(p_payload) key_name;
  result := app_private.institution_management_payload(institution_id);

  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, before_json, after_json
  ) values (
    actor_person_id, 'aal2', 'institution.create', 'institution', institution_id,
    institution_id, 'success', null,
    jsonb_build_object(
      'status', result ->> 'status',
      'plan_id', result -> 'subscription' -> 'plan_id',
      'plan_code', result -> 'subscription' -> 'plan_code',
      'changed_fields', changed_fields
    )
  );
  insert into app_private.institution_management_command_receipts(
    request_id, actor_person_id, command_kind, institution_id,
    request_hash, result_management_version
  ) values (
    p_request_id, actor_person_id, 'create', institution_id, request_hash,
    (result ->> 'management_version')::bigint
  );
  return result;
exception
  when invalid_text_representation or datetime_field_overflow
    or check_violation or not_null_violation or foreign_key_violation
    or unique_violation then
    raise invalid_parameter_value using message = 'invalid institution payload';
end;
$$;


ALTER FUNCTION "app_private"."create_institution_for_superadmin"("p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_superadmin_person_draft"("p_person_type" "public"."person_type", "p_first_name" "text", "p_last_name" "text", "p_display_name" "text" DEFAULT NULL::"text", "p_legal_name" "text" DEFAULT NULL::"text", "p_contexts" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_variable
declare
  created_person public.people;
  context jsonb;
  context_kind text;
  institution_id uuid;
  unit_id uuid;
  group_id uuid;
  membership_id uuid;
  role_id uuid;
  role_scope_kind text;
  assignment_id uuid;
  child_context_id uuid;
  child_unit_link_id uuid;
  child_group_link_id uuid;
  actor_person_id uuid;
  actor_platform_membership_id uuid;
begin
  perform child_group_link_id; -- Captured for future response enrichment.
  perform app_private.assert_people_permission('people.create');

  if p_person_type = 'service' then
    raise invalid_parameter_value using message = 'service people are read-only';
  end if;
  if nullif(btrim(p_first_name), '') is null
     or nullif(btrim(p_last_name), '') is null then
    raise invalid_parameter_value using message = 'first and last name are required';
  end if;
  if jsonb_typeof(coalesce(p_contexts, '[]'::jsonb)) <> 'array' then
    raise invalid_parameter_value using message = 'contexts must be an array';
  end if;

  if jsonb_array_length(coalesce(p_contexts, '[]'::jsonb)) > 0 then
    if p_person_type = 'adult' then
      perform app_private.assert_people_permission('people.memberships.manage');
    else
      perform app_private.assert_people_permission('people.child_contexts.manage');
    end if;
  end if;

  insert into public.people(
    person_type,
    first_name,
    last_name,
    display_name,
    legal_name,
    status
  )
  values (
    p_person_type,
    btrim(p_first_name),
    btrim(p_last_name),
    coalesce(
      nullif(btrim(p_display_name), ''),
      btrim(p_first_name) || ' ' || btrim(p_last_name)
    ),
    nullif(btrim(p_legal_name), ''),
    'draft'
  )
  returning * into created_person;

  actor_person_id := app_private.current_person_id();

  for context in
    select value from jsonb_array_elements(coalesce(p_contexts, '[]'::jsonb))
  loop
    context_kind := context ->> 'kind';
    institution_id := nullif(context ->> 'institution_id', '')::uuid;
    unit_id := nullif(context ->> 'scope_unit_id', '')::uuid;
    group_id := nullif(context ->> 'scope_group_id', '')::uuid;

    if p_person_type = 'adult'
       and context_kind = 'institution_membership' then
      if institution_id is null
         or nullif(btrim(context ->> 'role_code'), '') is null then
        raise invalid_parameter_value using
          message = 'adult membership requires institution and role';
      end if;
      if not exists (
        select 1 from public.institutions institution
        where institution.id = institution_id
      ) then
        raise foreign_key_violation using message = 'institution not found';
      end if;
      if unit_id is not null and not exists (
        select 1 from public.units unit
        where unit.id = unit_id and unit.institution_id = institution_id
      ) then
        raise check_violation using message = 'unit belongs to another institution';
      end if;
      if group_id is not null and not exists (
        select 1 from public.groups group_row
        where group_row.id = group_id
          and group_row.institution_id = institution_id
          and (unit_id is null or group_row.unit_id = unit_id)
      ) then
        raise check_violation using message = 'group belongs to another context';
      end if;
      select role.id
      into role_id
      from public.institution_roles role
      where role.institution_id = institution_id
        and role.code = btrim(context ->> 'role_code')
        and role.status = 'active'
      limit 1;
      if role_id is null then
        raise foreign_key_violation using
          message = 'contextual role does not belong to institution';
      end if;
      role_scope_kind := case
        when group_id is not null then 'group'
        when unit_id is not null then 'unit'
        else 'institution'
      end;

      membership_id := null;
      select existing_membership.id
      into membership_id
      from public.institution_memberships existing_membership
      where existing_membership.person_id = created_person.id
        and existing_membership.institution_id = institution_id
        and existing_membership.status = 'active'
        and existing_membership.revoked_at is null
      limit 1;
      if membership_id is null then
        insert into public.institution_memberships(
          person_id,
          institution_id,
          role_code,
          status,
          scope_kind,
          scope_unit_id,
          scope_group_id
        )
        values (
          created_person.id,
          institution_id,
          btrim(context ->> 'role_code'),
          'active',
          role_scope_kind,
          unit_id,
          group_id
        )
        returning id into membership_id;
      end if;

      insert into public.institution_role_assignments(
        membership_id,
        role_id,
        scope_kind,
        scope_unit_id,
        scope_group_id
      )
      values (
        membership_id,
        role_id,
        role_scope_kind,
        unit_id,
        group_id
      )
      returning id into assignment_id;

      insert into audit.audit_logs(
        actor_person_id,
        actor_membership_id,
        mfa_aal,
        action_code,
        object_type,
        object_id,
        institution_id,
        outcome,
        after_json
      )
      values (
        actor_person_id,
        app_private.platform_permission_membership_id(
          'people.memberships.manage'
        ),
        auth.jwt() ->> 'aal',
        'people.membership.context.add',
        'institution_role_assignments',
        assignment_id,
        institution_id,
        'success',
        jsonb_build_object(
          'operation', 'add',
          'changed_fields', jsonb_build_array('role', 'scope')
        )
      );
    elsif p_person_type = 'child' and context_kind = 'child_context' then
      unit_id := nullif(
        coalesce(context ->> 'unit_id', context ->> 'scope_unit_id'), ''
      )::uuid;
      group_id := nullif(
        coalesce(context ->> 'group_id', context ->> 'scope_group_id'), ''
      )::uuid;
      if institution_id is null then
        raise invalid_parameter_value using
          message = 'child context requires institution';
      end if;
      if unit_id is not null and not exists (
        select 1 from public.units unit
        where unit.id = unit_id and unit.institution_id = institution_id
      ) then
        raise check_violation using message = 'unit belongs to another institution';
      end if;
      if group_id is not null and (
        unit_id is null or not exists (
          select 1 from public.groups group_row
          where group_row.id = group_id
            and group_row.institution_id = institution_id
            and group_row.unit_id = unit_id
        )
      ) then
        raise check_violation using message = 'group belongs to another context';
      end if;

      insert into public.child_contexts(child_person_id, institution_id)
      values (created_person.id, institution_id)
      returning id into child_context_id;
      if unit_id is not null then
        insert into public.child_unit_links(
          child_context_id, unit_id, status
        )
        values (child_context_id, unit_id, 'pending')
        returning id into child_unit_link_id;
      end if;
      if group_id is not null then
        insert into public.child_group_links(child_unit_link_id, group_id)
        values (child_unit_link_id, group_id)
        returning id into child_group_link_id;
      end if;

      insert into audit.audit_logs(
        actor_person_id,
        actor_membership_id,
        mfa_aal,
        action_code,
        object_type,
        object_id,
        institution_id,
        outcome,
        after_json
      )
      values (
        actor_person_id,
        app_private.platform_permission_membership_id(
          'people.child_contexts.manage'
        ),
        auth.jwt() ->> 'aal',
        'people.child_context.context.add',
        'child_contexts',
        child_context_id,
        institution_id,
        'success',
        jsonb_build_object(
          'operation', 'add',
          'changed_fields',
            jsonb_build_array('institution', 'unit', 'group')
        )
      );
    else
      raise invalid_parameter_value using
        message = 'context kind does not match person type';
    end if;
  end loop;

  actor_platform_membership_id :=
    app_private.platform_permission_membership_id('people.create');

  insert into audit.audit_logs(
    actor_person_id,
    actor_membership_id,
    mfa_aal,
    action_code,
    object_type,
    object_id,
    outcome,
    after_json
  )
  values (
    actor_person_id,
    actor_platform_membership_id,
    auth.jwt() ->> 'aal',
    'people.create_draft',
    'people',
    created_person.id,
    'success',
    jsonb_build_object(
      'changed_fields', jsonb_build_array('person_type', 'identity', 'contexts'),
      'context_count', jsonb_array_length(coalesce(p_contexts, '[]'::jsonb))
    )
  );

  return jsonb_build_object(
    'id', created_person.id,
    'person_type', created_person.person_type,
    'display_name', created_person.display_name,
    'status', created_person.status,
    'updated_at', created_person.updated_at
  );
end
$$;


ALTER FUNCTION "app_private"."create_superadmin_person_draft"("p_person_type" "public"."person_type", "p_first_name" "text", "p_last_name" "text", "p_display_name" "text", "p_legal_name" "text", "p_contexts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_unit_for_superadmin"("p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();tenant uuid;target uuid:=gen_random_uuid();type_id uuid;plan_id uuid;
h bytea;prior app_private.unit_management_command_receipts%rowtype;handle_value text;result jsonb;begin
tenant:=nullif(p_payload->>'institution_id','')::uuid;type_id:=nullif(p_payload->>'unit_type_id','')::uuid;plan_id:=nullif(p_payload->>'plan_override_id','')::uuid;
if p_request_id is null or actor is null or(select auth.uid())is null or not app_private.has_scoped_platform_permission('units.create',tenant)
or not app_private.has_mfa_aal2()then raise insufficient_privilege using message='units.create and AAL2 required';end if;
if nullif(btrim(p_payload->>'name'),'')is null or nullif(btrim(p_payload->>'slug'),'')is null or type_id is null
then raise invalid_parameter_value using message='institution, name, slug and unit type required';end if;
if plan_id is not null and(not app_private.has_platform_permission('units.plan.manage')or not app_private.unit_plan_is_available(plan_id,tenant))
then raise insufficient_privilege using message='units.plan.manage and available plan required';end if;
perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));h:=app_private.unit_management_hash(p_payload);
select*into prior from app_private.unit_management_command_receipts where request_id=p_request_id;
if prior.request_id is not null then if prior.actor_person_id<>actor or prior.command_kind<>'create'or prior.request_hash<>h
then raise invalid_parameter_value using message='request replay mismatch';end if;return app_private.unit_form_payload(prior.unit_id);end if;
if nullif(btrim(p_payload->>'handle'),'') is not null then
  handle_value:=app_private.structure_handle_normalize(p_payload->>'handle');
  if app_private.structure_handle_in_use(handle_value,'unit',null) then
    raise unique_violation using message='handle already in use',detail='SAI_HANDLE_TAKEN';
  end if;
else
  -- units_handle_normalized_check: so [a-z0-9._], ate 30 caracteres, comeca e termina
  -- em [a-z0-9]. O sufixo (@instituicao) vem do slug sem hifen/underscore e fica
  -- inteiro; o segmento da unidade e truncado ANTES do ponto para caber.
  declare
    inst_segment text := coalesce(nullif(regexp_replace(
      (select lower(i.slug) from public.institutions i where i.id=tenant),'[^a-z0-9]','','g'),''),'instituicao');
    unit_segment text := coalesce(nullif(app_private.structure_handle_segment(p_payload->>'name'),''),'unidade');
    room integer;
  begin
    inst_segment:=left(inst_segment,24);
    room:=30-1-length(inst_segment);
    handle_value:=left(unit_segment,greatest(room,1))||'.'||inst_segment;
    if app_private.structure_handle_in_use(handle_value,'unit',null) then
      handle_value:=left(unit_segment,greatest(room-5,1))||'.'||inst_segment||'_'||left(replace(target::text,'-',''),4);
    end if;
  end;
end if;
insert into public.units(id,institution_id,name,slug,status,unit_type_id,unit_type_other_description,plan_override_id,
management_version,timezone,handle,public_discovery_enabled,public_address_visible,public_contact_visible,
inherit_address,inherit_contact,inherit_branding,inherit_representatives,inherit_administrators,inherit_plan)
values(target,tenant,btrim(p_payload->>'name'),lower(btrim(p_payload->>'slug')),
coalesce(nullif(p_payload->>'unit_status','')::public.record_status,'active'),type_id,
nullif(btrim(p_payload->>'unit_type_other_description'),''),plan_id,1,
coalesce(nullif(p_payload->>'timezone',''),'America/Sao_Paulo'),handle_value,
coalesce((p_payload#>>'{public_profile,discovery_enabled}')::boolean,false),
coalesce((p_payload#>>'{public_profile,address_visible}')::boolean,false),
coalesce((p_payload#>>'{public_profile,contact_visible}')::boolean,false),
coalesce((p_payload#>>'{inheritance,address}')::boolean,true),
coalesce((p_payload#>>'{inheritance,contact}')::boolean,true),
coalesce((p_payload#>>'{inheritance,branding}')::boolean,true),
coalesce((p_payload#>>'{inheritance,representatives}')::boolean,true),
coalesce((p_payload#>>'{inheritance,administrators}')::boolean,true),plan_id is null);
perform app_private.persist_unit_children(target,actor,p_payload);result:=app_private.unit_form_payload(target);
insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,after_json)
values(actor,'aal2','unit.create','unit',target,tenant,'success',jsonb_build_object('unit_type_id',type_id,'plan_override_id',plan_id));
insert into app_private.unit_management_command_receipts values(p_request_id,h,actor,'create',target,1,now());return result;end$$;


ALTER FUNCTION "app_private"."create_unit_for_superadmin"("p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."csv_safe"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$select case when value ~ '^[[:space:]]*[=+@-]' then ''''||value else value end$$;


ALTER FUNCTION "app_private"."csv_safe"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."current_person_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (
      select auth_link.person_id
      from public.person_auth_links auth_link
      where auth_link.auth_user_id = (select auth.uid())
        and auth_link.status = 'active'
        and auth_link.revoked_at is null
      order by auth_link.linked_at desc, auth_link.id
      limit 1
    ),
    (
      select actor.person_id
      from app_private.superadmin_internal_auth_links internal_link
      join app_private.superadmin_internal_actor_people actor
        on actor.internal_identity_id = internal_link.internal_identity_id
      where internal_link.auth_user_id = (select auth.uid())
        and internal_link.status = 'active'
      order by internal_link.created_at desc
      limit 1
    )
  )
$$;


ALTER FUNCTION "app_private"."current_person_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."d04_child_safety_directory_data_v2"("p_search" "text", "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_segment" "text", "p_limit" integer, "p_cursor" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare result jsonb; cursor_name text; cursor_context uuid; cursor_unit uuid; begin
  if coalesce(array_ndims(p_institution_ids),1)>1 or coalesce(array_ndims(p_unit_ids),1)>1 then
    raise invalid_parameter_value using message='invalid child safety filter dimensions';
  end if;
  if cardinality(coalesce(p_institution_ids,'{}'::uuid[]))>100
     or cardinality(coalesce(p_unit_ids,'{}'::uuid[]))>100
     or array_position(p_institution_ids,null) is not null
     or array_position(p_unit_ids,null) is not null then
    raise invalid_parameter_value using message='invalid child safety filter size';
  end if;
  if p_cursor is not null and p_cursor<>'{}'::jsonb and (
    jsonb_typeof(p_cursor) is distinct from 'object'
    or p_cursor-array['name','child_context_id','unit_id']<>'{}'::jsonb
    or jsonb_typeof(p_cursor->'name') is distinct from 'string'
    or jsonb_typeof(p_cursor->'child_context_id') is distinct from 'string'
    or jsonb_typeof(p_cursor->'unit_id') is distinct from 'string'
    or p_cursor->>'name'='' or p_cursor->>'child_context_id'='' or p_cursor->>'unit_id'=''
  ) then raise invalid_parameter_value using message='invalid child safety cursor shape'; end if;
  if char_length(coalesce(p_search,''))>120
     or p_segment is null
     or p_segment not in ('all','awaiting_approval','attention','authorized','without_authorization')
     or p_limit is null or p_limit not in (8,11,20,50,100)
     or (p_cursor is not null and jsonb_typeof(p_cursor)<>'object') then
    raise invalid_parameter_value using message='invalid child safety directory filters';
  end if;
  begin
    cursor_name:=nullif(p_cursor->>'name','');
    cursor_context:=nullif(p_cursor->>'child_context_id','')::uuid;
    cursor_unit:=nullif(p_cursor->>'unit_id','')::uuid;
  exception when others then
    raise invalid_parameter_value using message='invalid child safety cursor';
  end;
  if (cursor_name is null)<>(cursor_context is null)
     or (cursor_name is null)<>(cursor_unit is null) then
    raise invalid_parameter_value using message='invalid child safety cursor';
  end if;
  if exists (
    select 1 from public.units u where u.id=any(coalesce(p_unit_ids,'{}'::uuid[]))
      and cardinality(coalesce(p_institution_ids,'{}'::uuid[]))>0
      and not u.institution_id=any(p_institution_ids)
  ) then raise invalid_parameter_value using message='invalid child safety hierarchy'; end if;

  with selected_units as (
    select distinct on (l.child_context_id) l.child_context_id,l.unit_id
    from public.child_unit_links l join public.units u on u.id=l.unit_id
    where l.status in ('active','awaiting_allocation')
      and (cardinality(coalesce(p_unit_ids,'{}'::uuid[]))=0 or l.unit_id=any(p_unit_ids))
      and (cardinality(coalesce(p_institution_ids,'{}'::uuid[]))=0
        or u.institution_id=any(p_institution_ids))
    order by l.child_context_id,case when l.status='active' then 0 else 1 end,l.unit_id
  ), scoped as (
    select c.id child_context_id,p.id child_id,p.display_name child_name,
      lower(p.display_name) sort_name,coalesce(c.local_identifier,'') internal_id,
      i.id institution_id,i.public_name institution_name,u.id unit_id,u.name unit_name,
      count(a.id) authorization_count,
      coalesce(bool_or(a.decision_status='pending') filter(where a.id is not null),false) has_pending,
      coalesce(bool_or(a.decision_status='approved' and a.status='active'
        and a.revoked_at is null and a.valid_from<=current_date
        and (a.valid_until is null or a.valid_until>=current_date))
        filter(where a.id is not null),false) has_authorized,
      exists(select 1 from public.child_safety_restrictions r
        where r.child_context_id=c.id and r.unit_id=u.id and r.status='active'
          and r.revoked_at is null and r.valid_from<=now()
          and (r.valid_until is null or r.valid_until>now()))
      or exists(select 1 from public.child_safety_alerts al
        where al.child_context_id=c.id and al.unit_id=u.id
          and al.status in ('open','acknowledged')) has_attention,
      max(a.updated_at) last_safety_change
    from public.child_contexts c
    join public.people p on p.id=c.child_person_id and p.person_type='child'
    join public.institutions i on i.id=c.institution_id
    join selected_units su on su.child_context_id=c.id
    join public.units u on u.id=su.unit_id and u.institution_id=c.institution_id
    left join public.authorized_person_authorizations a
      on a.child_context_id=c.id and a.unit_id=u.id
    where c.status='active' and p.status='active'
      and (nullif(btrim(p_search),'') is null
        or lower(p.display_name) like '%'||lower(btrim(p_search))||'%'
        or lower(coalesce(c.local_identifier,'')) like '%'||lower(btrim(p_search))||'%')
    group by c.id,p.id,p.display_name,c.local_identifier,i.id,i.public_name,u.id,u.name
  ), segmented as (
    select *,case when has_pending then 'awaiting_approval'
      when has_attention then 'attention' when has_authorized then 'authorized'
      else 'without_authorization' end segment from scoped
  ), filtered as (
    select * from segmented where p_segment='all' or segment=p_segment
  ), page_plus_one as (
    select * from filtered where cursor_name is null
      or (sort_name,child_context_id,unit_id)>(cursor_name,cursor_context,cursor_unit)
    order by sort_name,child_context_id,unit_id limit p_limit+1
  ), page_rows as (
    select * from page_plus_one order by sort_name,child_context_id,unit_id limit p_limit
  ), last_row as (
    select * from page_rows order by sort_name desc,child_context_id desc,unit_id desc limit 1
  )
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'child_id',child_id,'child_context_id',child_context_id,'child_name',child_name,
      'internal_id',internal_id,'institution_id',institution_id,'institution_name',institution_name,
      'unit_id',unit_id,'unit_name',unit_name,'authorization_count',authorization_count,
      'segment',segment,'last_safety_change',last_safety_change
    ) order by sort_name,child_context_id,unit_id) from page_rows),'[]'::jsonb),
    'total_count',(select count(*) from filtered),
    'segment_counts',jsonb_build_object(
      'all',(select count(*) from segmented),
      'awaiting_approval',(select count(*) from segmented where segment='awaiting_approval'),
      'attention',(select count(*) from segmented where segment='attention'),
      'authorized',(select count(*) from segmented where segment='authorized'),
      'without_authorization',(select count(*) from segmented where segment='without_authorization')),
    'next_cursor',case when (select count(*) from page_plus_one)>p_limit then
      (select jsonb_build_object('name',sort_name,'child_context_id',child_context_id,'unit_id',unit_id)
       from last_row) else null end,
    'can_create',false
  ) into result;
  return result;
end $$;


ALTER FUNCTION "app_private"."d04_child_safety_directory_data_v2"("p_search" "text", "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_segment" "text", "p_limit" integer, "p_cursor" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."d04_child_safety_get_data_v2"("p_child_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare result jsonb; begin
  select jsonb_build_object('child_id',p.id,'child_name',p.display_name,
    'contexts',coalesce((select jsonb_agg(jsonb_build_object(
      'child_context_id',c.id,'internal_id',coalesce(c.local_identifier,''),
      'institution_id',i.id,'institution_name',i.public_name,'unit_id',u.id,'unit_name',u.name)
      order by i.public_name,u.name)
      from public.child_contexts c join public.institutions i on i.id=c.institution_id
      join public.child_unit_links l on l.child_context_id=c.id
        and l.status in ('active','awaiting_allocation')
      join public.units u on u.id=l.unit_id and u.institution_id=c.institution_id
      where c.child_person_id=p.id and c.status='active'),'[]'::jsonb),
    'authorizations',coalesce((select jsonb_agg(jsonb_build_object(
      'id',a.id,'child_context_id',a.child_context_id,'unit_id',a.unit_id,
      'person_id',ap.person_id,'name',ap.display_name,'relationship_code',rt.code,
      'relationship_detail',a.relationship_detail,
      'capability_codes',(select coalesce(jsonb_agg(cap.capability_code order by cap.capability_code),'[]')
        from public.authorized_person_authorization_capabilities cap where cap.authorization_id=a.id),
      'decision_status',a.decision_status,'lifecycle_status',a.status,
      'valid_from',a.valid_from,'valid_until',a.valid_until,'version',a.version,
      'request_reason',a.request_reason,'decision_reason',a.decision_reason)
      order by a.created_at desc)
      from public.authorized_person_authorizations a
      join public.authorized_people ap on ap.id=a.authorized_person_id
      join public.family_relationship_types rt on rt.id=a.relationship_type_id
      join public.child_contexts c on c.id=a.child_context_id
      where c.child_person_id=p.id),'[]'::jsonb),
    'restrictions',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'institution_id',r.institution_id,'unit_id',r.unit_id,'child_context_id',r.child_context_id,'restriction_code',r.restriction_code,'title',r.title,'description',r.description,'severity',r.severity,'reason',r.reason,'valid_from',r.valid_from,'valid_until',r.valid_until,'status',r.status,'version',r.version,'created_at',r.created_at,'updated_at',r.updated_at,'revoked_at',r.revoked_at))
      from public.child_safety_restrictions r join public.child_contexts c on c.id=r.child_context_id
      where c.child_person_id=p.id),'[]'::jsonb),
    'alerts',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'institution_id',a.institution_id,'unit_id',a.unit_id,'child_context_id',a.child_context_id,'authorization_id',a.authorization_id,'restriction_id',a.restriction_id,'event_code',a.event_code,'severity',a.severity,'status',a.status,'reason',a.reason,'acknowledged_at',a.acknowledged_at,'resolution_reason',a.resolution_reason,'version',a.version,'created_at',a.created_at,'updated_at',a.updated_at))
      from public.child_safety_alerts a join public.child_contexts c on c.id=a.child_context_id
      where c.child_person_id=p.id),'[]'::jsonb),
    'evidence',coalesce((select jsonb_agg(jsonb_build_object(
      'id',e.id,'child_context_id',e.child_context_id,'authorization_id',e.authorization_id,
      'restriction_id',e.restriction_id,'alert_id',e.alert_id,'file_name',e.file_name,
      'mime_type',e.mime_type,'size_bytes',e.size_bytes,'status',e.status,'created_at',e.created_at)
      order by e.created_at desc)
      from public.child_safety_evidence e join public.child_contexts c on c.id=e.child_context_id
      where c.child_person_id=p.id and e.status='active'),'[]'::jsonb)
  ) into result from public.people p
  where p.id=p_child_id and p.person_type='child' and p.status='active';
  if result is null then raise no_data_found using message='child safety record unavailable'; end if;
  return result;
end $$;


ALTER FUNCTION "app_private"."d04_child_safety_get_data_v2"("p_child_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."d04_child_safety_internal_read_v2"("p_operation" "text", "p_search" "text", "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_segment" "text", "p_limit" integer, "p_cursor" "jsonb", "p_child_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  final_ctx app_private.superadmin_internal_context;
  capability constant text := 'child_safety.read';
  action_code text;
  correlation uuid := gen_random_uuid();
  error_code text;
  result jsonb;
begin
  -- Operation codes are selected by fixed public wrappers, never supplied by UI.
  action_code := case p_operation
    when 'directory' then 'superadmin.child-safety.list'
    when 'search_children' then 'superadmin.child-safety.search-children'
    when 'get' then 'superadmin.child-safety.child' end;
  begin
    select * into strict ctx
      from app_private.require_superadmin_internal_context(capability);
    if ctx.scope_kind is distinct from 'platform'
      or ctx.scope_institution_id is not null
      or ctx.aal is null or ctx.aal not in ('aal1','aal2') then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    if action_code is null then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    -- No domain table is read until identity, session, capability and scope pass.
    case p_operation
      when 'directory' then
        result := app_private.d04_child_safety_directory_data_v2(
          p_search,p_institution_ids,p_unit_ids,p_segment,p_limit,p_cursor);
      when 'search_children' then
        result := app_private.d04_child_safety_search_children_data_v2(p_search,p_limit);
      when 'get' then
        if p_child_id is null then
          raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
        end if;
        result := app_private.d04_child_safety_get_data_v2(p_child_id);
    end case;
    select * into strict final_ctx
      from app_private.require_superadmin_internal_context(capability);
    if (ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
        ctx.session_id,ctx.platform_role_id,ctx.scope_kind,ctx.scope_institution_id)
      is distinct from
       (final_ctx.internal_identity_id,final_ctx.internal_auth_link_id,final_ctx.internal_membership_id,
        final_ctx.session_id,final_ctx.platform_role_id,final_ctx.scope_kind,final_ctx.scope_institution_id)
      or not exists(select 1 from auth.sessions s
        where s.id=final_ctx.session_id and s.user_id=final_ctx.auth_user_id
          and (s.not_after is null or s.not_after>clock_timestamp())) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
  exception
    when no_data_found then error_code := 'SAI_PERMISSION_DENIED';
    when invalid_parameter_value or invalid_text_representation
      or numeric_value_out_of_range then error_code := 'SAI_INVALID_ARGUMENT';
    when others then
      get stacked diagnostics error_code=pg_exception_detail;
      error_code := app_private.superadmin_internal_error_envelope(error_code,correlation)#>>'{error,code}';
  end;
  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      capability,coalesce(action_code,'superadmin.child-safety.read'),error_code,correlation);
    return app_private.superadmin_internal_error_envelope(error_code,correlation);
  end if;
  -- Audit contains opaque actor/resource IDs only; never search or child payload.
  -- Audit failure aborts the RPC instead of returning unaudited data.
  perform app_private.audit_append_superadmin_internal(
    ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
    ctx.session_id,capability,ctx.aal,action_code,'success',null,correlation,null,
    case when p_operation='get' then 'child' else 'child_safety_directory' end,
    case when p_operation='get' then p_child_id else null end);
  return jsonb_build_object('ok',true,'data',result,'error',null);
end;
$$;


ALTER FUNCTION "app_private"."d04_child_safety_internal_read_v2"("p_operation" "text", "p_search" "text", "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_segment" "text", "p_limit" integer, "p_cursor" "jsonb", "p_child_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."d04_child_safety_search_children_data_v2"("p_search" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ begin
  if char_length(btrim(coalesce(p_search,'')))<2 or char_length(p_search)>120
     or p_limit is null or p_limit not between 1 and 20 then
    raise invalid_parameter_value using message='invalid child search';
  end if;
  return coalesce((select jsonb_agg(item order by item->>'display_name') from (
    select jsonb_build_object('id',p.id,'display_name',p.display_name,
      'internal_id',coalesce(c.local_identifier,''),
      'contexts',jsonb_agg(jsonb_build_object('child_context_id',c.id,
        'institution_id',i.id,'institution_name',i.public_name,
        'unit_id',u.id,'unit_name',u.name) order by i.public_name,u.name)) item
    from public.people p
    join public.child_contexts c on c.child_person_id=p.id and c.status='active'
    join public.institutions i on i.id=c.institution_id
    join public.child_unit_links l on l.child_context_id=c.id
      and l.status in ('active','awaiting_allocation')
    join public.units u on u.id=l.unit_id and u.institution_id=c.institution_id
    where p.person_type='child' and p.status='active'
      and (lower(p.display_name) like '%'||lower(btrim(p_search))||'%'
        or lower(coalesce(c.local_identifier,'')) like '%'||lower(btrim(p_search))||'%')
    group by p.id,p.display_name,c.local_identifier
    order by p.display_name,p.id limit p_limit
  ) rows),'[]'::jsonb);
end $$;


ALTER FUNCTION "app_private"."d04_child_safety_search_children_data_v2"("p_search" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."decide_child_unit_transfer"("target_request_id" "uuid", "target_decision" "text", "target_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid := app_private.current_person_id();
  request_record public.child_unit_transfer_requests%rowtype;
  item_record record;
  destination_link_id uuid;
begin
  if target_decision not in ('accepted','rejected','changes_requested') then
    raise exception 'invalid transfer decision';
  end if;
  select * into request_record from public.child_unit_transfer_requests
  where id = target_request_id and status = 'pending' for update;
  if request_record.id is null then raise exception 'pending transfer not found'; end if;
  if not app_private.has_context_permission(
    request_record.institution_id, 'transfers.manage',
    request_record.destination_unit_id, null, null, null, false
  ) then raise exception 'destination authorization required'; end if;

  update public.child_unit_transfer_requests
  set status = target_decision, decision_reason = nullif(btrim(target_reason), ''),
      decided_by_person_id = actor_person_id, decided_at = now(), updated_at = now()
  where id = target_request_id;

  if target_decision = 'accepted' then
    for item_record in
      select item.*, source_link.child_context_id
      from public.child_unit_transfer_items item
      join public.child_unit_links source_link on source_link.id = item.child_unit_link_id
      where item.transfer_request_id = target_request_id and item.status = 'pending'
      for update of item
    loop
      update public.child_group_links
      set status = 'inactive', ends_at = coalesce(ends_at, now()), updated_at = now()
      where child_unit_link_id = item_record.child_unit_link_id and status = 'active';
      update public.child_unit_links
      set status = 'inactive', revoked_at = now(), updated_at = now()
      where id = item_record.child_unit_link_id;

      insert into public.child_unit_links(
        child_context_id, unit_id, status, accepted_by, accepted_at
      ) values (
        item_record.child_context_id, request_record.destination_unit_id,
        case when item_record.suggested_group_id is null
          then 'awaiting_allocation'::public.child_unit_link_status
          else 'active'::public.child_unit_link_status end,
        actor_person_id, now()
      )
      on conflict (child_context_id, unit_id) do update set
        status = excluded.status, accepted_by = excluded.accepted_by,
        accepted_at = excluded.accepted_at, revoked_at = null, updated_at = now()
      returning id into destination_link_id;

      if item_record.suggested_group_id is not null then
        insert into public.child_group_links(child_unit_link_id, group_id, starts_at)
        values (destination_link_id, item_record.suggested_group_id, now())
        on conflict (child_unit_link_id, group_id) do update set
          status = 'active', starts_at = excluded.starts_at, ends_at = null,
          updated_at = now();
      end if;
      update public.child_unit_transfer_items
      set status = 'accepted', destination_child_unit_link_id = destination_link_id,
          updated_at = now()
      where id = item_record.id;
    end loop;
  else
    update public.child_unit_transfer_items set status = 'rejected', updated_at = now()
    where transfer_request_id = target_request_id and status = 'pending';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."decide_child_unit_transfer"("target_request_id" "uuid", "target_decision" "text", "target_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."decide_unit_type_request_for_superadmin"("p_type_request_id" "uuid", "p_decision" "text", "p_approved_unit_type_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();r public.unit_type_requests%rowtype;begin
select*into r from public.unit_type_requests where id=p_type_request_id for update;if r.id is null then raise no_data_found using message='type request not found';end if;
if actor is null or not app_private.has_platform_permission('unit_types.request')or not app_private.has_mfa_aal2()
then raise insufficient_privilege using message='Superadmin AAL2 required';end if;
if r.status<>'pending'or p_decision not in('approved','rejected')
or(p_decision='approved'and not exists(select 1 from public.unit_types where id=p_approved_unit_type_id and status='active'))
or(p_decision='rejected'and nullif(btrim(p_reason),'')is null)then raise invalid_parameter_value using message='invalid type request decision';end if;
update public.unit_type_requests set status=p_decision::public.unit_type_request_status,
approved_unit_type_id=case when p_decision='approved'then p_approved_unit_type_id end,
reviewed_by_person_id=actor,reviewed_at=now(),review_reason=nullif(btrim(p_reason),''),updated_at=now()
where id=p_type_request_id returning*into r;
insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome)
values(actor,'aal2','unit_type_request.'||p_decision,'unit_type_request',r.id,r.institution_id,'success');return to_jsonb(r);end$$;


ALTER FUNCTION "app_private"."decide_unit_type_request_for_superadmin"("p_type_request_id" "uuid", "p_decision" "text", "p_approved_unit_type_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_activity_active_group_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  row_data jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  target_activity_id uuid := coalesce((row_data ->> 'activity_id')::uuid, (row_data ->> 'id')::uuid);
begin
  if not exists (
    select 1 from public.activity_definitions activity
    where activity.id = target_activity_id and activity.status = 'active'
  ) then
    return coalesce(new, old);
  end if;
  if not exists (
    select 1 from public.activity_group_links group_link
    where group_link.activity_id = target_activity_id
      and group_link.status = 'active'
      and (group_link.ends_at is null or group_link.ends_at > pg_catalog.now())
  ) then
    raise check_violation using
      message = 'activity must retain at least one active group link',
      detail = 'P36_ACTIVITY_REQUIRES_GROUP';
  end if;
  return coalesce(new, old);
end
$$;


ALTER FUNCTION "app_private"."enforce_activity_active_group_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."enforce_activity_active_group_v1"() IS 'P36 (ADR 0034 Decisao 15): atividade ativa mantem ao menos um vinculo de turma ativo; rascunho pode existir so com unidade.';



CREATE OR REPLACE FUNCTION "app_private"."enforce_activity_active_unit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target_activity_id uuid;
  row_data jsonb;
begin
  row_data := case
    when tg_op = 'DELETE' then to_jsonb(old)
    else to_jsonb(new)
  end;
  target_activity_id := coalesce(
    (row_data ->> 'activity_id')::uuid,
    (row_data ->> 'id')::uuid
  );

  if not exists (
    select 1
    from public.activity_definitions activity
    where activity.id = target_activity_id
  ) then
    return coalesce(new, old);
  end if;

  if not exists (
    select 1
    from public.activity_unit_links unit_link
    where unit_link.activity_id = target_activity_id
      and unit_link.status = 'active'
      and (unit_link.ends_at is null or unit_link.ends_at > pg_catalog.now())
  ) then
    raise check_violation using
      message = 'activity must retain at least one active unit link';
  end if;

  return coalesce(new, old);
end
$$;


ALTER FUNCTION "app_private"."enforce_activity_active_unit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_institution_handle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid;
begin
  new.slug:=app_private.normalize_institution_handle(new.slug);
  if new.slug !~ '^[a-z0-9][a-z0-9._-]{2,29}$' then
    raise check_violation using message='institution handle must have 3 to 30 allowed characters';
  end if;
  if tg_op='INSERT' then
    new.handle_last_changed_at:=coalesce(new.handle_last_changed_at,now());
    return new;
  end if;
  if new.slug is distinct from old.slug then
    if old.handle_last_changed_at is not null
       and old.handle_last_changed_at > now()-interval '15 days' then
      raise check_violation using message='institution handle can only change every 15 days';
    end if;
    actor:=app_private.current_person_id();
    new.handle_last_changed_at:=now();
    insert into public.institution_handle_history(
      institution_id,previous_handle,new_handle,changed_by
    ) values(old.id,old.slug,new.slug,actor);
  end if;
  return new;
end
$_$;


