CREATE OR REPLACE FUNCTION "app_private"."form_actor_has_export_permission"("p_actor" "uuid", "p_export_kind" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with target_permission as (
    select permission_row.id
      from public.platform_permissions permission_row
     where permission_row.code = case
       when p_export_kind = 'anonymous_participation'
         then 'forms.anonymous_participation.export'
       else 'forms.responses.export'
     end
       and permission_row.status = 'active'
  ), memberships as (
    select membership.id, membership.role_id, role_row.code as role_code
      from public.platform_memberships membership
      join public.platform_roles role_row on role_row.id = membership.role_id
     where membership.person_id = p_actor
       and membership.status = 'active'
       and membership.revoked_at is null
       and membership.scope_kind = 'platform'
       and membership.scope_institution_id is null
       and role_row.status = 'active'
  ), effects as (
    select grant_row.effect
      from memberships
      join public.platform_role_permissions grant_row
        on grant_row.role_id = memberships.role_id
       and grant_row.status = 'active'
       and grant_row.revoked_at is null
      join target_permission on target_permission.id = grant_row.permission_id
    union all
    select override_row.effect
      from memberships
      join public.platform_member_permission_overrides override_row
        on override_row.membership_id = memberships.id
       and override_row.status = 'active'
       and (override_row.starts_at is null or override_row.starts_at <= now())
       and (override_row.expires_at is null or override_row.expires_at > now())
      join target_permission on target_permission.id = override_row.permission_id
  )
  select exists(select 1 from effects where effect = 'allow')
     and not exists(select 1 from effects where effect = 'deny')
     and (
       p_export_kind <> 'anonymous_participation'
       or exists(select 1 from memberships where role_code = 'owner')
     );
$$;


ALTER FUNCTION "app_private"."form_actor_has_export_permission"("p_actor" "uuid", "p_export_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_anonymous_participation_lookup"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.anonymous_participation.read');
declare result jsonb;
begin
  perform app_private.form_assert_payload_keys(
    p_query, array['form_id','occurrence_id','justification','cursor_name','cursor_id','limit'],
    'anonymous participation query'
  );
  perform app_private.form_require_owner(actor, 'forms.anonymous_participation.read');
  if char_length(btrim(coalesce(p_query ->> 'justification', ''))) < 10 then
    raise invalid_parameter_value using message = 'auditable justification required';
  end if;
  perform app_private.superadmin_form_assert_legacy_resource_v2((p_query ->> 'form_id')::uuid);
  if not exists(
    select 1 from public.forms where id = (p_query ->> 'form_id')::uuid and identity_mode = 'anonymous'
  ) then
    raise no_data_found using message = 'anonymous form unavailable';
  end if;
  result := app_private.form_list_monitor_people(p_query);
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id, institution_id,
    outcome, reason, after_json
  )
  select actor, auth.jwt() ->> 'aal', 'forms.anonymous_participation.read', 'form', form_row.id,
         form_row.institution_id, 'success', btrim(p_query ->> 'justification'),
         jsonb_build_object('occurrence_id', p_query ->> 'occurrence_id')
    from public.forms form_row where form_row.id = (p_query ->> 'form_id')::uuid;
  return result;
end;
$$;


ALTER FUNCTION "app_private"."form_anonymous_participation_lookup"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_application_projection"("p_application_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', application.id,
    'form_id', application.form_id,
    'institution_id', application.institution_id,
    'name', application.name,
    'status', application.status,
    'opens_for_days', application.opens_for_days,
    'management_version', application.management_version,
    'audience_rules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rule.id, 'kind', rule.rule_kind, 'mode', rule.rule_mode, 'target_id', rule.target_id
      ) order by rule.position, rule.id)
        from (
          select source_rule.* from public.form_audience_rules source_rule
           where source_rule.application_id = application.id
           order by source_rule.position, source_rule.id
           limit 50
        ) rule
    ), '[]'::jsonb),
    'schedules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', schedule.id,
        'status', schedule.status,
        'management_version', schedule.management_version,
        'starts_at_local', schedule.starts_at_local,
        'time_zone', schedule.time_zone,
        'recurrence', jsonb_build_object(
          'kind', schedule.recurrence_kind,
          'interval', schedule.interval_value,
          'weekdays', to_jsonb(schedule.weekdays),
          'day', schedule.monthly_day,
          'use_last_day', schedule.monthly_last_day
        ),
        'end', jsonb_build_object(
          'kind', schedule.end_kind,
          'date', schedule.ends_on,
          'count', schedule.occurrence_count
        ),
        'reminders', coalesce((
          select jsonb_agg(jsonb_build_object('kind', reminder.reminder_kind, 'amount', reminder.amount)
                           order by reminder.position, reminder.id)
            from (
              select source_reminder.* from public.form_schedule_reminders source_reminder
               where source_reminder.schedule_id = schedule.id
               order by source_reminder.position, source_reminder.id
               limit 3
            ) reminder
        ), '[]'::jsonb)
      ) order by schedule.starts_at_local, schedule.id)
        from (
          select source_schedule.* from public.form_schedules source_schedule
           where source_schedule.application_id = application.id
             and source_schedule.status = 'active'
           order by source_schedule.starts_at_local, source_schedule.id
           limit 20
        ) schedule
    ), '[]'::jsonb)
  )
    from public.form_applications application
   where application.id = p_application_id;
$$;


ALTER FUNCTION "app_private"."form_application_projection"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_apply_location_options_v1"("p_version_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_institution uuid;
  item_row public.form_items;
  option_count integer;
begin
  select f.institution_id into target_institution
    from public.form_versions v join public.forms f on f.id = v.form_id
   where v.id = p_version_id;
  if target_institution is null then
    raise invalid_parameter_value using message = 'form version unavailable';
  end if;
  for item_row in select * from public.form_items where form_version_id = p_version_id and kind = 'location' loop
    if exists (select 1 from public.form_answer_options ao join public.form_question_options o on o.id = ao.option_id
               where o.item_id = item_row.id) then
      raise check_violation using message = 'location options with answers cannot be replaced';
    end if;
    delete from public.form_question_options where item_id = item_row.id;
    insert into public.form_question_options(form_version_id, item_id, label, position, location_id, location_status)
    select p_version_id, item_row.id, btrim(s.name), row_number() over (order by lower(s.name), s.name, s.location_id) - 1,
           s.location_id, s.status
      from app_private.form_location_options_snapshot_v1(target_institution) s;
    select count(*) into option_count from public.form_question_options where item_id = item_row.id;
    if option_count > 200 then
      raise check_violation using message = 'location item cannot snapshot more than 200 locations';
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "app_private"."form_apply_location_options_v1"("p_version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."form_apply_location_options_v1"("p_version_id" "uuid") IS 'P16: congela em form_question_options os Locais ativos da instituicao do formulario para cada item kind=location da versao (snapshot: location_id, nome, status). Chamada no salvamento do rascunho v2 e na publicacao.';



CREATE OR REPLACE FUNCTION "app_private"."form_archive_or_delete"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.manage');
declare form_row public.forms;
declare replay jsonb;
declare deleted boolean := false;
begin
  perform app_private.form_assert_payload_keys(p_payload, array['form_id','action'], 'form archive or delete');
  perform app_private.superadmin_form_lock_legacy_resource_v2((p_payload ->> 'form_id')::uuid);
  replay := app_private.form_begin_command(p_request_id, actor, 'form_archive_or_delete', p_expected_version, p_payload);
  if replay is not null then return replay; end if;
  select * into form_row from public.forms where id = (p_payload ->> 'form_id')::uuid for update;
  perform app_private.superadmin_form_assert_legacy_resource_v2(form_row.id);
  if form_row.id is null then raise no_data_found using message = 'form unavailable'; end if;
  if form_row.management_version <> p_expected_version then
    raise serialization_failure using message = 'expected_version mismatch';
  end if;
  if p_payload ->> 'action' = 'delete'
     and form_row.first_published_at is null
     and not exists(select 1 from public.form_applications where form_id = form_row.id)
     and not exists(select 1 from public.form_responses where form_id = form_row.id) then
    delete from public.forms where id = form_row.id;
    deleted := true;
  elsif p_payload ->> 'action' in ('delete', 'archive') then
    update public.forms set status = 'archived', archived_at = now(),
      management_version = management_version + 1, updated_by_person_id = actor, updated_at = now()
    where id = form_row.id;
  else
    raise invalid_parameter_value using message = 'invalid archive action';
  end if;
  return app_private.form_complete_command(
    p_request_id, jsonb_build_object('form_id', form_row.id, 'deleted', deleted)
  );
end;
$$;


ALTER FUNCTION "app_private"."form_archive_or_delete"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assert_application_payload_limits"("p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if jsonb_typeof(p_payload -> 'rules') <> 'array' then
    raise invalid_parameter_value using message = 'application rules must be an array';
  end if;
  if jsonb_array_length(p_payload -> 'rules') > 50 then
    raise check_violation using message = 'maximum 50 form audience rules';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_assert_application_payload_limits"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assert_distribution_target"("p_actor" "uuid", "p_form_id" "uuid", "p_institution_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.forms form_record
    where form_record.id = p_form_id
      and form_record.institution_id = p_institution_id
  ) then
    raise invalid_parameter_value using message = 'form and institution must match';
  end if;

  if not app_private.audit_actor_has_permission(p_actor, 'forms.manage', p_institution_id, false) then
    raise insufficient_privilege using message = 'form distribution institution unavailable';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_assert_distribution_target"("p_actor" "uuid", "p_form_id" "uuid", "p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assert_payload_keys"("p_payload" "jsonb", "p_allowed" "text"[], "p_context" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare unknown_keys text[];
begin
  if jsonb_typeof(p_payload) <> 'object' then
    raise invalid_parameter_value using message = p_context || ' must be an object';
  end if;
  select array_agg(key order by key) into unknown_keys
    from jsonb_object_keys(p_payload) key
   where not key = any(p_allowed);
  if unknown_keys is not null then
    raise invalid_parameter_value using message = p_context || ' contains unknown keys';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_assert_payload_keys"("p_payload" "jsonb", "p_allowed" "text"[], "p_context" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."form_responses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "occurrence_id" "uuid" NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "form_id" "uuid" NOT NULL,
    "form_version_id" "uuid" NOT NULL,
    "identity_mode" "text" NOT NULL,
    "respondent_person_id" "uuid",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "management_version" bigint DEFAULT 1 NOT NULL,
    "anonymous_edit_secret_hash" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "submitted_at" timestamp with time zone,
    CONSTRAINT "form_responses_anonymity_ck" CHECK (((("identity_mode" = 'anonymous'::"text") AND ("respondent_person_id" IS NULL) AND ("anonymous_edit_secret_hash" IS NOT NULL)) OR (("identity_mode" = 'identified'::"text") AND ("respondent_person_id" IS NOT NULL) AND ("anonymous_edit_secret_hash" IS NULL)))),
    CONSTRAINT "form_responses_identity_ck" CHECK (("identity_mode" = ANY (ARRAY['identified'::"text", 'anonymous'::"text"]))),
    CONSTRAINT "form_responses_status_ck" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text"]))),
    CONSTRAINT "form_responses_submission_ck" CHECK (((("status" = 'draft'::"text") AND ("submitted_at" IS NULL)) OR (("status" = 'submitted'::"text") AND ("submitted_at" IS NOT NULL)))),
    CONSTRAINT "form_responses_version_ck" CHECK (("management_version" > 0))
);

ALTER TABLE ONLY "public"."form_responses" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."form_responses" OWNER TO "postgres";


COMMENT ON TABLE "public"."form_responses" IS 'Anonymous responses intentionally have no participation_id, person_id, response unit key, or shared correlation key.';



CREATE OR REPLACE FUNCTION "app_private"."form_assert_required_response_answers"("p_response" "public"."form_responses") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  missing_item_id uuid;
  missing_kind text;
begin
  select item.id, item.kind
    into missing_item_id, missing_kind
    from public.form_items item
   where item.form_version_id = p_response.form_version_id
     and item.is_required
     and (
       not exists (
         select 1 from public.form_question_conditions condition_row
          where condition_row.target_item_id = item.id
       )
       or exists (
         select 1
           from public.form_question_conditions condition_row
           join public.form_answers source_answer
             on source_answer.response_id = p_response.id
            and source_answer.item_id = condition_row.source_item_id
          where condition_row.target_item_id = item.id
            and (
              (condition_row.condition_kind = 'yes_no'
               and source_answer.yes_no_value = condition_row.expected_yes_no)
              or (condition_row.condition_kind = 'choice' and exists (
                select 1 from public.form_answer_options selected
                 where selected.answer_id = source_answer.id
                   and selected.option_id = condition_row.source_option_id
              ))
            )
       )
     )
     and not exists (
       select 1
         from public.form_answers answer
        where answer.response_id = p_response.id
          and answer.item_id = item.id
          and case
            when item.kind = 'short_text' then nullif(btrim(answer.text_value), '') is not null
            when item.kind in ('single_choice', 'multiple_choice') then exists (
              select 1 from public.form_answer_options selected where selected.answer_id = answer.id
            )
            when item.kind = 'location' then exists (
              select 1 from public.form_answer_options selected
               where selected.answer_id = answer.id
                 and app_private.form_location_option_available_v1(selected.option_id)
            )
            when item.kind in ('photo', 'gallery') then exists (
              select 1 from public.form_answer_assets attached where attached.answer_id = answer.id
            )
            else true
          end
     )
   order by (item.kind = 'location' and not exists (
       select 1 from public.form_question_options candidate
        where candidate.item_id = item.id
          and app_private.form_location_option_available_v1(candidate.id))) desc,
     item.position, item.id
   limit 1;
  if missing_item_id is null then
    return;
  end if;
  if missing_kind = 'location' and not exists (
    select 1 from public.form_question_options candidate
     where candidate.item_id = missing_item_id
       and app_private.form_location_option_available_v1(candidate.id)
  ) then
    raise check_violation using message = 'required location question has no available location',
      detail = 'FORMS_LOCATION_NO_AVAILABLE_OPTION';
  end if;
  raise check_violation using message = 'required visible form answers are missing';
end;
$$;


ALTER FUNCTION "app_private"."form_assert_required_response_answers"("p_response" "public"."form_responses") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assert_response_actor"("p_response" "public"."form_responses", "p_actor" "uuid", "p_edit_secret" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_response.identity_mode = 'identified' then
    if p_response.respondent_person_id <> p_actor then
      raise no_data_found using message = 'form response unavailable';
    end if;
  elsif nullif(p_edit_secret, '') is null
     or not app_private.form_verify_anonymous_edit_secret(
       p_edit_secret, p_response.anonymous_edit_secret_hash
     ) then
    raise no_data_found using message = 'form response unavailable';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_assert_response_actor"("p_response" "public"."form_responses", "p_actor" "uuid", "p_edit_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assert_schedule_capacity"("p_application_id" "uuid", "p_schedule_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (
    select count(*)
      from public.form_schedules schedule
     where schedule.application_id = p_application_id
       and schedule.status = 'active'
       and schedule.id <> p_schedule_id
  ) >= 20 then
    raise check_violation using message = 'maximum 20 active form schedules per application';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_assert_schedule_capacity"("p_application_id" "uuid", "p_schedule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assert_schedule_payload_limits"("p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare reminders jsonb := coalesce(p_payload -> 'reminders', '[]'::jsonb);
begin
  if jsonb_typeof(reminders) <> 'array' then
    raise invalid_parameter_value using message = 'schedule reminders must be an array';
  end if;
  if jsonb_array_length(reminders) > 3 then
    raise check_violation using message = 'maximum 3 form schedule reminders';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_assert_schedule_payload_limits"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assets_answer_media_discard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare asset public.media_assets%rowtype;
begin
  if new.state not in ('discarded','expired') or old.state = new.state then return new; end if;
  select * into asset from public.media_assets where source_form_asset_id = new.id and status <> 'deleted' for update;
  if asset.id is null then return new; end if;
  update public.media_assets set status = 'deleted' where id = asset.id;
  insert into app_private.form_media_r2_cleanup(asset_id, bucket_id, object_key, reason)
  select asset.id, v.bucket_id, v.object_key, case when new.state = 'expired' then 'expired' else 'deleted' end
  from public.media_variants v where v.media_asset_id = asset.id
  union select asset.id, asset.bucket_id, asset.object_key, case when new.state = 'expired' then 'expired' else 'deleted' end
  on conflict do nothing;
  return new;
end $$;


ALTER FUNCTION "app_private"."form_assets_answer_media_discard_v1"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."media_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "post_id" "uuid",
    "owner_person_id" "uuid",
    "upload_request_id" "text" NOT NULL,
    "storage_provider" "text" DEFAULT 'r2'::"text" NOT NULL,
    "bucket_id" "text" NOT NULL,
    "object_key" "text" NOT NULL,
    "original_name" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "byte_size" bigint,
    "checksum_sha256" "text",
    "status" "public"."happens_media_status" DEFAULT 'pending'::"public"."happens_media_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finalized_at" timestamp with time zone,
    "catalog_kind" "text" DEFAULT 'legacy-happens'::"text" NOT NULL,
    "form_id" "uuid",
    "source_form_asset_id" "uuid",
    "owner_internal_identity_id" "uuid",
    "media_purpose" "text",
    "pixel_width" integer,
    "pixel_height" integer,
    "export_file_job_id" "uuid",
    "expires_at" timestamp with time zone,
    CONSTRAINT "media_assets_byte_size_check" CHECK (("byte_size" > 0)),
    CONSTRAINT "media_assets_catalog_shape_ck" CHECK ((((("catalog_kind" = 'legacy-happens'::"text") AND ("post_id" IS NOT NULL) AND ("owner_person_id" IS NOT NULL) AND ("byte_size" IS NOT NULL) AND ("form_id" IS NULL) AND ("source_form_asset_id" IS NULL) AND ("owner_internal_identity_id" IS NULL) AND ("media_purpose" IS NULL) AND ("pixel_width" IS NULL) AND ("pixel_height" IS NULL)) OR (("catalog_kind" = 'form-image'::"text") AND ("post_id" IS NULL) AND ("form_id" IS NOT NULL) AND ("storage_provider" = 'r2'::"text") AND ("bucket_id" = 'coelo-media-prod'::"text") AND ("original_name" = ''::"text") AND ("media_purpose" IS NOT NULL) AND ("mime_type" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"])) AND (("byte_size" IS NULL) OR (("byte_size" >= 1) AND ("byte_size" <= 4194304))) AND ((("media_purpose" = 'question-image'::"text") AND ("source_form_asset_id" IS NULL) AND ("num_nonnulls"("owner_person_id", "owner_internal_identity_id") = 1)) OR (("media_purpose" = 'answer-image'::"text") AND ("source_form_asset_id" IS NOT NULL) AND ("owner_internal_identity_id" IS NULL))) AND (("checksum_sha256" IS NULL) OR ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text")) AND ("num_nonnulls"("pixel_width", "pixel_height") = ANY (ARRAY[0, 2])) AND ((("pixel_width" IS NULL) AND ("pixel_height" IS NULL)) OR ((("pixel_width" >= 1) AND ("pixel_width" <= 2560)) AND (("pixel_height" >= 1) AND ("pixel_height" <= 2560)))) AND (("status" <> 'ready'::"public"."happens_media_status") OR (("checksum_sha256" IS NOT NULL) AND ("pixel_width" IS NOT NULL) AND ("pixel_height" IS NOT NULL) AND ("byte_size" IS NOT NULL))) AND (("status" <> 'pending'::"public"."happens_media_status") OR (("byte_size" IS NULL) AND ("checksum_sha256" IS NULL) AND ("pixel_width" IS NULL) AND ("pixel_height" IS NULL)))) OR (("catalog_kind" = 'form-xlsx'::"text") AND ("post_id" IS NULL) AND ("form_id" IS NOT NULL) AND ("source_form_asset_id" IS NULL) AND ("owner_person_id" IS NULL) AND ("owner_internal_identity_id" IS NOT NULL) AND ("storage_provider" = 'r2'::"text") AND ("bucket_id" = 'coelo-transient-prod'::"text") AND ("original_name" = ''::"text") AND ("media_purpose" = 'forms-responses-export'::"text") AND ("mime_type" = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'::"text") AND ("pixel_width" IS NULL) AND ("pixel_height" IS NULL) AND (("checksum_sha256" IS NULL) OR ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text")) AND (("status" <> 'pending'::"public"."happens_media_status") OR (("byte_size" IS NULL) AND ("checksum_sha256" IS NULL))) AND (("status" <> 'ready'::"public"."happens_media_status") OR (("byte_size" IS NOT NULL) AND ("checksum_sha256" IS NOT NULL))))) IS TRUE)),
    CONSTRAINT "media_assets_export_binding_shape_ck" CHECK ((((("catalog_kind" = 'form-xlsx'::"text") AND ("export_file_job_id" IS NOT NULL) AND ("expires_at" IS NOT NULL)) OR (("catalog_kind" <> 'form-xlsx'::"text") AND ("export_file_job_id" IS NULL) AND ("expires_at" IS NULL))) IS TRUE)),
    CONSTRAINT "media_assets_mime_type_check" CHECK ((((("catalog_kind" = 'form-xlsx'::"text") AND ("mime_type" = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'::"text")) OR (("catalog_kind" <> 'form-xlsx'::"text") AND ("mime_type" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text", 'video/mp4'::"text"])))) IS TRUE)),
    CONSTRAINT "media_assets_storage_provider_check" CHECK (("storage_provider" = ANY (ARRAY['supabase_mvp'::"text", 'r2'::"text"]))),
    CONSTRAINT "media_assets_upload_request_id_check" CHECK ((("char_length"("upload_request_id") >= 1) AND ("char_length"("upload_request_id") <= 240)))
);

