ALTER TABLE "public"."media_assets" OWNER TO "postgres";


COMMENT ON COLUMN "public"."media_assets"."source_form_asset_id" IS 'Existing response upload ownership, including anonymous secret verification, stays in form_assets; never duplicate identity/correlation in the physical catalog.';



CREATE OR REPLACE FUNCTION "app_private"."form_assets_answer_media_mirror_v1"("p_form_asset_id" "uuid") RETURNS "public"."media_assets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare source public.form_assets%rowtype; occ public.form_occurrences%rowtype;
  asset public.media_assets%rowtype; new_asset_id uuid := gen_random_uuid(); next_position integer;
begin
  select * into source from public.form_assets where id = p_form_asset_id;
  if source.id is null then raise no_data_found using detail='FORM_MEDIA_NOT_FOUND'; end if;
  select * into asset from public.media_assets where source_form_asset_id = source.id and status <> 'deleted';
  if asset.id is not null then return asset; end if;
  select * into occ from public.form_occurrences where id = source.occurrence_id;
  insert into public.media_assets(id, institution_id, form_id, source_form_asset_id, owner_person_id, catalog_kind,
    media_purpose, storage_provider, bucket_id, object_key, original_name, upload_request_id, mime_type, status)
  values (new_asset_id, source.institution_id, occ.form_id, source.id, source.prepared_by_person_id, 'form-image',
    'answer-image', 'r2', 'coelo-media-prod',
    'tenants/' || source.institution_id::text || '/forms/form/' || occ.form_id::text || '/answer-image/'
      || new_asset_id::text || '/original/' || gen_random_uuid()::text
      || case source.mime_type when 'image/jpeg' then '.jpg' when 'image/png' then '.png' else '.webp' end,
    '', 'form-asset:' || source.id::text, source.mime_type, 'pending')
  returning * into asset;
  select coalesce(max(b.position), -1) + 1 into next_position from public.media_bindings b
  join public.media_assets a on a.id = b.media_asset_id
  where b.item_id = source.item_id and b.form_version_id = occ.form_version_id and b.purpose = 'answer-image'
    and a.status <> 'deleted' and a.owner_person_id is not distinct from source.prepared_by_person_id;
  insert into public.media_bindings(media_asset_id, form_version_id, item_id, purpose, position)
  values (asset.id, occ.form_version_id, source.item_id, 'answer-image', least(next_position, 4));
  return asset;
end $$;


ALTER FUNCTION "app_private"."form_assets_answer_media_mirror_v1"("p_form_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_audience_filter_valid"("p_filter" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_typeof(p_filter) = 'object'
    and not exists (
      select 1 from jsonb_object_keys(p_filter) key
      where key not in ('status', 'profile_codes', 'membership_status')
    )
    and case when p_filter ? 'status'
      then jsonb_typeof(p_filter -> 'status') = 'string'
        and char_length(p_filter ->> 'status') between 1 and 40
      else true end
    and case when p_filter ? 'membership_status'
      then jsonb_typeof(p_filter -> 'membership_status') = 'string'
        and char_length(p_filter ->> 'membership_status') between 1 and 40
      else true end
    and case when p_filter ? 'profile_codes'
      then jsonb_typeof(p_filter -> 'profile_codes') = 'array'
        and jsonb_array_length(p_filter -> 'profile_codes') between 1 and 50
        and not exists (
          select 1 from jsonb_array_elements(p_filter -> 'profile_codes') value
           where jsonb_typeof(value) <> 'string' or char_length(value #>> '{}') not between 1 and 100
        )
      else true end;
$$;


ALTER FUNCTION "app_private"."form_audience_filter_valid"("p_filter" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_authorize_file_job_download"("p_file_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.current_person_id();
declare job_row public.form_file_jobs;
declare raw_token uuid := gen_random_uuid();
declare token_expires_at timestamptz;
begin
  if actor is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  select job.* into job_row
    from public.form_file_jobs job
    join public.forms form_row
      on form_row.id = job.form_id
     and form_row.institution_id = job.institution_id
    join public.institutions institution_row on institution_row.id = job.institution_id
   where job.id = p_file_job_id
     and job.requested_by_person_id = actor
     and job.state in ('succeeded','partial')
     and job.expires_at > now()
     and job.artifact_path is not null
   for update of job;
  if job_row.id is null then return null; end if;
  if not app_private.form_actor_has_export_permission(actor, job_row.export_kind) then
    if job_row.export_kind = 'anonymous_participation' then
      raise insufficient_privilege using
        message = 'Owner role and forms.anonymous_participation.export required';
    end if;
    raise insufficient_privilege using message = 'forms.responses.export required';
  end if;

  token_expires_at := least(job_row.expires_at, now() + interval '2 minutes');
  delete from app_private.form_file_download_tokens token_row
   where token_row.file_job_id = job_row.id
     and token_row.actor_person_id = actor
     and token_row.consumed_at is null;
  insert into app_private.form_file_download_tokens(
    file_job_id, actor_person_id, token_hash, expires_at
  ) values (
    job_row.id,
    actor,
    encode(extensions.digest(raw_token::text, 'sha256'), 'hex'),
    token_expires_at
  );
  return jsonb_build_object('download_token', raw_token, 'expires_at', token_expires_at);
end;
$$;


ALTER FUNCTION "app_private"."form_authorize_file_job_download"("p_file_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_begin_command"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  receipt app_private.form_command_receipts;
  request_hash bytea := extensions.digest(
    pg_catalog.convert_to(p_command || ':' || p_expected_version::text || ':' || p_payload::text, 'UTF8'),
    'sha256'
  );
begin
  if p_request_id is null or p_expected_version < 0 then
    raise invalid_parameter_value using message = 'request_id and non-negative expected_version required';
  end if;
  select * into receipt
    from app_private.form_command_receipts
   where request_id = p_request_id
   for update;
  if receipt.request_id is not null then
    if receipt.actor_person_id <> p_actor
       or receipt.command_name <> p_command
       or receipt.request_hash <> request_hash
       or receipt.expected_version <> p_expected_version then
      raise unique_violation using message = 'form command replay mismatch';
    end if;
    if receipt.completed_at is null then
      raise serialization_failure using message = 'form command is already in progress';
    end if;
    return receipt.result_jsonb;
  end if;
  insert into app_private.form_command_receipts(
    request_id, actor_person_id, command_name, request_hash, expected_version
  ) values (p_request_id, p_actor, p_command, request_hash, p_expected_version);
  return null;
end;
$$;


ALTER FUNCTION "app_private"."form_begin_command"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_claim_notification_delivery"("p_worker_id" "text", "p_lease_seconds" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare recipient_row public.context_notification_recipients;
declare event_row public.context_notification_events;
begin
  if nullif(btrim(p_worker_id), '') is null or p_lease_seconds not between 10 and 600 then
    raise invalid_parameter_value using message = 'valid notification worker lease required';
  end if;
  update public.context_notification_recipients recipient
     set delivery_state = 'failed',
         last_delivery_error_code = 'delivery_attempts_exhausted',
         delivery_lease_owner = null,
         delivery_lease_expires_at = null
    from public.context_notification_events event
   where event.id = recipient.event_id
     and event.event_code like 'forms.reminder.%'
     and recipient.delivery_state = 'processing'
     and recipient.delivery_attempts >= 20
     and recipient.delivery_lease_expires_at < now();
  update public.context_notification_recipients recipient
     set delivery_state = 'processing',
         delivery_attempts = delivery_attempts + 1,
         delivery_lease_owner = p_worker_id,
         delivery_lease_expires_at = now() + make_interval(secs => p_lease_seconds)
   where (recipient.event_id, recipient.person_id) = (
     select candidate.event_id, candidate.person_id
       from public.context_notification_recipients candidate
       join public.context_notification_events event on event.id = candidate.event_id
      where event.event_code like 'forms.reminder.%'
        and event.deliver_at <= now()
        and candidate.delivery_attempts < 20
        and (
          (candidate.delivery_state in ('pending', 'failed')
            and candidate.next_delivery_attempt_at <= now())
          or (candidate.delivery_state = 'processing'
            and candidate.delivery_lease_expires_at < now())
        )
      order by candidate.next_delivery_attempt_at, candidate.created_at,
               candidate.event_id, candidate.person_id
      limit 1 for update of candidate skip locked
   )
  returning * into recipient_row;
  if recipient_row.event_id is null then return null; end if;
  select * into event_row from public.context_notification_events
   where id = recipient_row.event_id;
  return jsonb_build_object(
    'event_id', event_row.id,
    'person_id', recipient_row.person_id,
    'event_code', event_row.event_code,
    'payload', event_row.payload_json,
    'attempt', recipient_row.delivery_attempts
  );
end;
$$;


ALTER FUNCTION "app_private"."form_claim_notification_delivery"("p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_claim_worker_job"("p_worker_id" "text", "p_lease_seconds" integer DEFAULT 60, "p_job_kinds" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job_row app_private.form_worker_jobs;
begin
  if nullif(btrim(p_worker_id), '') is null or p_lease_seconds not between 10 and 600 then
    raise invalid_parameter_value using message = 'valid worker id and lease required';
  end if;
  update app_private.form_worker_jobs job
     set state = 'processing',
         attempts = attempts + 1,
         lease_owner = p_worker_id,
         lease_expires_at = now() + make_interval(secs => p_lease_seconds)
   where job.id = (
     select candidate.id
       from app_private.form_worker_jobs candidate
      where (
        (candidate.state in ('pending', 'failed') and candidate.available_at <= now())
        or (candidate.state = 'processing' and candidate.lease_expires_at < now())
      )
        and candidate.attempts < 20
        and (p_job_kinds is null or candidate.job_kind = any(p_job_kinds))
      order by candidate.available_at, candidate.created_at, candidate.id
      limit 1
      for update skip locked
   )
  returning * into job_row;
  if job_row.id is null then return null; end if;
  return jsonb_build_object(
    'id', job_row.id,
    'job_kind', job_row.job_kind,
    'aggregate_id', job_row.aggregate_id,
    'payload', job_row.payload_jsonb,
    'progress', job_row.progress_jsonb,
    'attempts', job_row.attempts,
    'created_at', job_row.created_at,
    'lease_expires_at', job_row.lease_expires_at
  );
end;
$$;


ALTER FUNCTION "app_private"."form_claim_worker_job"("p_worker_id" "text", "p_lease_seconds" integer, "p_job_kinds" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_clone"("p_actor" "uuid", "p_source_form_id" "uuid", "p_target_institution_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare source_row public.forms;
declare source_projection jsonb;
declare target_form_id uuid := gen_random_uuid();
declare target_version_id uuid;
begin
  perform app_private.superadmin_form_lock_legacy_resource_v2(p_source_form_id);
  select * into source_row from public.forms where id = p_source_form_id;
  if source_row.id is null then raise no_data_found using message = 'form unavailable'; end if;
  if p_target_institution_id <> source_row.institution_id
     and not app_private.has_platform_permission('forms.transfer_cross_institution') then
    raise insufficient_privilege using message = 'forms.transfer_cross_institution required';
  end if;
  source_projection := app_private.form_definition_projection(source_row.id);
  insert into public.forms(
    id, institution_id, kind, status, identity_mode, response_unit, title, description,
    created_by_person_id, updated_by_person_id
  ) values (
    target_form_id, p_target_institution_id, source_row.kind, 'draft', source_row.identity_mode,
    source_row.response_unit, source_row.title || ' (cópia)', source_row.description, p_actor, p_actor
  );
  insert into public.form_versions(form_id, version_number, created_by_person_id)
  values (target_form_id, 1, p_actor) returning id into target_version_id;
  update public.forms set working_version_id = target_version_id where id = target_form_id;
  perform app_private.form_replace_working_definition(target_version_id, source_projection -> 'sections');
  return target_form_id;
end;
$$;


