CREATE OR REPLACE FUNCTION "app_private"."form_finalize_asset_for_worker"("p_asset_id" "uuid", "p_actual_byte_length" bigint, "p_actual_mime_type" "text", "p_actual_checksum_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare asset_row public.form_assets;
begin
  select * into asset_row from public.form_assets where id = p_asset_id for update;
  if asset_row.id is null or asset_row.state <> 'uploaded' or asset_row.expires_at <= now() then
    raise no_data_found using message = 'form asset unavailable';
  end if;
  if p_actual_byte_length <> asset_row.expected_byte_length
     or p_actual_mime_type <> asset_row.mime_type
     or lower(p_actual_checksum_sha256) <> asset_row.expected_checksum_sha256 then
    update public.form_assets
       set state = 'discarded', discarded_at = now()
     where id = asset_row.id returning * into asset_row;
    return jsonb_build_object(
      'id', asset_row.id, 'item_id', asset_row.item_id,
      'mime_type', asset_row.mime_type, 'byte_length', null,
      'state', asset_row.state, 'error_code', 'form_asset_verification_mismatch'
    );
  end if;
  update public.form_assets
     set state = 'finalized', actual_byte_length = p_actual_byte_length,
         actual_checksum_sha256 = lower(p_actual_checksum_sha256), finalized_at = now()
   where id = asset_row.id returning * into asset_row;
  return jsonb_build_object(
    'id', asset_row.id, 'item_id', asset_row.item_id, 'mime_type', asset_row.mime_type,
    'byte_length', asset_row.actual_byte_length, 'state', asset_row.state
  );
end;
$$;


ALTER FUNCTION "app_private"."form_finalize_asset_for_worker"("p_asset_id" "uuid", "p_actual_byte_length" bigint, "p_actual_mime_type" "text", "p_actual_checksum_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_finalize_asset_upload"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.respond');
declare asset_row public.form_assets;
declare replay jsonb;
declare result jsonb;
begin
  perform app_private.form_assert_payload_keys(
    p_payload, array['asset_id','edit_secret'], 'finalize form asset'
  );
  select * into asset_row from public.form_assets
   where id = (p_payload ->> 'asset_id')::uuid for update;
  if asset_row.id is null or not (
       asset_row.prepared_by_person_id = actor
       or (asset_row.prepared_by_person_id is null and app_private.form_verify_anonymous_edit_secret(
         p_payload ->> 'edit_secret', asset_row.anonymous_upload_secret_hash
       ))
     ) or asset_row.state not in ('prepared','uploaded','finalized')
     or asset_row.expires_at <= now() then
    raise no_data_found using message = 'form asset unavailable';
  end if;
  if asset_row.prepared_by_person_id is not null then
    replay := app_private.form_begin_command(
      p_request_id, actor, 'form_finalize_asset_upload', p_expected_version, p_payload
    );
    if replay is not null then return replay; end if;
  end if;
  if p_expected_version <> 0 then raise serialization_failure using message = 'expected_version mismatch'; end if;
  if asset_row.state = 'prepared' then
    update public.form_assets set state = 'uploaded' where id = asset_row.id returning * into asset_row;
  end if;
  result := jsonb_build_object(
    'asset_id', asset_row.id, 'state', asset_row.state
  );
  if asset_row.prepared_by_person_id is null then return result; end if;
  return app_private.form_complete_command(p_request_id, result);
end;
$$;


ALTER FUNCTION "app_private"."form_finalize_asset_upload"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


