CREATE OR REPLACE FUNCTION "app_private"."form_generate_due_occurrences"("p_horizon_days" integer DEFAULT 90) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare schedule_id uuid;
declare generated integer := 0;
begin
  for schedule_id in
    select schedule.id
      from public.form_schedules schedule
      join public.form_applications application on application.id = schedule.application_id
     where application.status = 'active'
     order by schedule.id
  loop
    generated := generated + app_private.form_generate_occurrences(schedule_id, p_horizon_days);
  end loop;
  return generated;
end;
$$;


ALTER FUNCTION "app_private"."form_generate_due_occurrences"("p_horizon_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_generate_occurrences"("p_schedule_id" "uuid", "p_horizon_days" integer DEFAULT 90) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare inserted_count integer;
begin
  if p_horizon_days not between 1 and 366 then
    raise invalid_parameter_value using message = 'occurrence horizon must be between 1 and 366 days';
  end if;
  with schedule_context as (
    select schedule.*,
           application.form_id,
           application.institution_id,
           application.opens_for_days,
           form_row.published_version_id
      from public.form_schedules schedule
     join public.form_applications application on application.id = schedule.application_id
      join public.forms form_row on form_row.id = application.form_id
     where schedule.id = p_schedule_id
       and schedule.status = 'active'
       and application.status = 'active'
       and form_row.status = 'published'
       and form_row.published_version_id is not null
  ), calendar_days as (
    select context.*,
           day_value::date as local_date,
           day_value::date + context.starts_at_local::time as scheduled_local
      from schedule_context context
      cross join lateral generate_series(
        context.starts_at_local::date,
        least(
          context.starts_at_local::date + p_horizon_days,
          coalesce(context.ends_on, context.starts_at_local::date + p_horizon_days)
        ),
        interval '1 day'
      ) day_value
  ), recurring as (
    select calendar.*
      from calendar_days calendar
     where case calendar.recurrence_kind
       when 'once' then calendar.local_date = calendar.starts_at_local::date
       when 'daily' then (calendar.local_date - calendar.starts_at_local::date)
                         % calendar.interval_value = 0
       when 'weekly' then (
         ((calendar.local_date - calendar.starts_at_local::date) / 7)
           % calendar.interval_value = 0
         and extract(isodow from calendar.local_date)::smallint = any(calendar.weekdays)
       )
       when 'monthly' then (
         ((extract(year from calendar.local_date)::integer
             - extract(year from calendar.starts_at_local)::integer) * 12
           + extract(month from calendar.local_date)::integer
             - extract(month from calendar.starts_at_local)::integer) % calendar.interval_value = 0
         and calendar.local_date = case when calendar.monthly_last_day
           then (date_trunc('month', calendar.local_date) + interval '1 month - 1 day')::date
           else make_date(
             extract(year from calendar.local_date)::integer,
             extract(month from calendar.local_date)::integer,
             least(
               calendar.monthly_day,
               extract(day from date_trunc('month', calendar.local_date)
                 + interval '1 month - 1 day')::integer
             )
           ) end
       )
       else false end
  ), numbered as (
    select recurring.*,
           row_number() over(order by recurring.scheduled_local) as occurrence_ordinal
      from recurring
  )
  insert into public.form_occurrences(
    application_id, schedule_id, institution_id, form_id, form_version_id,
    scheduled_local, time_zone, opens_at, closes_at, status
  )
  select numbered.application_id,
         numbered.id,
         numbered.institution_id,
         numbered.form_id,
         numbered.published_version_id,
         numbered.scheduled_local,
         numbered.time_zone,
         numbered.scheduled_local at time zone numbered.time_zone,
         (numbered.scheduled_local + make_interval(days => numbered.opens_for_days))
           at time zone numbered.time_zone,
         case
           when now() >= (numbered.scheduled_local + make_interval(days => numbered.opens_for_days))
                          at time zone numbered.time_zone then 'closed'
           when now() >= numbered.scheduled_local at time zone numbered.time_zone then 'open'
           else 'scheduled'
         end
    from numbered
   where numbered.end_kind <> 'count'
      or numbered.occurrence_ordinal <= numbered.occurrence_count
  on conflict(schedule_id, scheduled_local, time_zone) do nothing;
  get diagnostics inserted_count = row_count;

  update public.form_occurrences occurrence_row
     set status = case when now() >= occurrence_row.closes_at then 'closed' else 'open' end,
         opened_at = case when occurrence_row.opened_at is null and now() >= occurrence_row.opens_at
                          then now() else occurrence_row.opened_at end,
         closed_at = case when occurrence_row.closed_at is null and now() >= occurrence_row.closes_at
                          then now() else occurrence_row.closed_at end
   where occurrence_row.schedule_id = p_schedule_id
     and occurrence_row.status in ('scheduled', 'open')
     and now() >= occurrence_row.opens_at;
  return inserted_count;
end;
$$;


ALTER FUNCTION "app_private"."form_generate_occurrences"("p_schedule_id" "uuid", "p_horizon_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_get_editor"("p_form_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  definition_projection jsonb;
  application_projection jsonb;
  form_institution_id uuid;
  working_version_id uuid;
  question_images jsonb;
begin
  select form_row.institution_id, form_row.working_version_id
    into form_institution_id, working_version_id
    from public.forms form_row
   where form_row.id = p_form_id
     and not app_private.superadmin_form_is_internal_draft_v2(form_row.id);
  if not found then
    raise no_data_found using message = 'form unavailable';
  end if;

  actor := app_private.current_person_id();
  if actor is null or (
    not app_private.has_platform_permission('forms.manage', form_institution_id)
    and not app_private.has_platform_permission('forms.read', form_institution_id)
  ) then
    raise no_data_found using message = 'form unavailable';
  end if;

  select app_private.form_definition_projection(form_row.id)
    into definition_projection
    from public.forms form_row
   where form_row.id = p_form_id;
  if definition_projection is null then
    raise no_data_found using message = 'form unavailable';
  end if;

  if app_private.has_platform_permission('forms.manage_applications', form_institution_id) then
    select app_private.form_application_projection(application.id)
      into application_projection
      from public.form_applications application
     where application.form_id = p_form_id
       and application.institution_id = form_institution_id
     order by (application.status = 'archived'), application.updated_at desc, application.id desc
     limit 1;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'item_id', binding.item_id,
    'asset_id', asset.id,
    'status', asset.status::text,
    'mime_type', asset.mime_type,
    'position', binding.position
  ) order by binding.position, asset.id), '[]'::jsonb)
  into question_images
  from public.media_bindings binding
  join public.media_assets asset on asset.id = binding.media_asset_id
  where binding.form_version_id = working_version_id
    and binding.purpose = 'question-image'
    and asset.form_id = p_form_id
    and asset.media_purpose = 'question-image'
    and asset.status <> 'deleted';

  return jsonb_build_object(
    'definition', definition_projection,
    'application', application_projection,
    'media_context', case when working_version_id is null then 'null'::jsonb
      else jsonb_build_object(
        'form_version_id', working_version_id,
        'question_images', question_images
      ) end
  );
end;
$$;


ALTER FUNCTION "app_private"."form_get_editor"("p_form_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_get_monitor"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.monitor');
declare form_row public.forms;
begin
  perform app_private.form_assert_payload_keys(
    p_query, array['form_id','application_id','occurrence_id','starts_on_or_after','ends_on_or_before','scope_id'],
    'form monitor query'
  );
  perform app_private.superadmin_form_assert_legacy_resource_v2((p_query ->> 'form_id')::uuid);
  select * into form_row from public.forms where id = (p_query ->> 'form_id')::uuid;
  if form_row.id is null then raise no_data_found using message = 'form unavailable'; end if;
  if p_query ->> 'scope_id' is not null and not exists(
    select 1 from public.form_scope_metrics metric
    join public.form_occurrences occurrence on occurrence.id = metric.occurrence_id
     where occurrence.form_id = form_row.id
       and metric.institution_id = form_row.institution_id
       and metric.scope_id = (p_query ->> 'scope_id')::uuid
  ) then
    raise no_data_found using message = 'monitor scope unavailable';
  end if;
  return (
    select jsonb_build_object(
      'eligible_count', coalesce(sum(case when p_query ->> 'scope_id' is null
        then occurrence_metric.eligible_count else scope_metric.eligible_count end), 0),
      'responded_count', coalesce(sum(case when p_query ->> 'scope_id' is null
        then occurrence_metric.responded_count else scope_metric.responded_count end), 0),
      'pending_count', coalesce(sum(case when p_query ->> 'scope_id' is null
        then occurrence_metric.pending_count else scope_metric.pending_count end), 0),
      'is_anonymous', form_row.identity_mode = 'anonymous'
    )
      from public.form_occurrences occurrence
      left join public.form_occurrence_metrics occurrence_metric on occurrence_metric.occurrence_id = occurrence.id
      left join public.form_scope_metrics scope_metric on scope_metric.occurrence_id = occurrence.id
       and scope_metric.scope_id = (p_query ->> 'scope_id')::uuid
     where occurrence.form_id = form_row.id
       and ((p_query ->> 'application_id') is null or occurrence.application_id = (p_query ->> 'application_id')::uuid)
       and ((p_query ->> 'occurrence_id') is null or occurrence.id = (p_query ->> 'occurrence_id')::uuid)
       and ((p_query ->> 'starts_on_or_after') is null or occurrence.opens_at::date >= (p_query ->> 'starts_on_or_after')::date)
       and ((p_query ->> 'ends_on_or_before') is null or occurrence.closes_at::date <= (p_query ->> 'ends_on_or_before')::date)
  );
end;
$$;


ALTER FUNCTION "app_private"."form_get_monitor"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_get_occurrence_for_response"("p_occurrence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.respond');
declare occurrence_row public.form_occurrences;
declare participation_row public.form_participations;
begin
  select * into occurrence_row from public.form_occurrences where id = p_occurrence_id;
  select participation.* into participation_row
    from public.form_participations participation
   where participation.occurrence_id = p_occurrence_id
     and participation.eligibility_state = 'eligible'
     and (
       participation.person_id = actor
       or exists(select 1 from public.form_participation_responders responder
                 where responder.participation_id = participation.id and responder.person_id = actor)
     ) limit 1;
  if occurrence_row.id is null or participation_row.id is null then
    raise no_data_found using message = 'form occurrence unavailable';
  end if;
  return jsonb_build_object(
    'occurrence', jsonb_build_object(
      'id', occurrence_row.id, 'application_id', occurrence_row.application_id,
      'form_id', occurrence_row.form_id, 'form_version_id', occurrence_row.form_version_id,
      'form_version_number', (select version_number from public.form_versions
                               where id = occurrence_row.form_version_id),
      'opens_at', occurrence_row.opens_at, 'closes_at', occurrence_row.closes_at,
      'status', occurrence_row.status, 'management_version', occurrence_row.management_version
    ),
    'participation_id', participation_row.id,
    'definition', app_private.form_definition_projection(
      occurrence_row.form_id, occurrence_row.form_version_id
    ),
    'can_edit', occurrence_row.status = 'open' and now() between occurrence_row.opens_at and occurrence_row.closes_at
  );
end;
$$;


ALTER FUNCTION "app_private"."form_get_occurrence_for_response"("p_occurrence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_get_overview"("p_form_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.require_forms_actor('forms.read');
  perform app_private.superadmin_form_assert_legacy_resource_v2(p_form_id);
  select app_private.form_definition_projection(p_form_id) || jsonb_build_object(
    'application_count', (select count(*) from public.form_applications where form_id = p_form_id),
    'occurrence_count', (select count(*) from public.form_occurrences where form_id = p_form_id),
    'response_count', (select count(*) from public.form_responses where form_id = p_form_id)
  ) into result;
  if result is null then raise no_data_found using message = 'form unavailable'; end if;
  return result;
end;
$$;


ALTER FUNCTION "app_private"."form_get_overview"("p_form_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_get_response_detail"("p_response_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.responses.read');
declare response_row public.form_responses;
begin
  select * into response_row from public.form_responses where id = p_response_id and status = 'submitted';
  if response_row.id is null then raise no_data_found using message = 'form response unavailable'; end if;
  return jsonb_build_object(
    'id', response_row.id, 'occurrence_id', response_row.occurrence_id,
    'form_version_id', response_row.form_version_id,
    'submitted_at', case when response_row.identity_mode = 'identified' then response_row.submitted_at else null end,
    'respondent_label', case when response_row.identity_mode = 'identified'
      then (select display_name from public.people where id = response_row.respondent_person_id) else null end,
    'answers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_id', answer.item_id, 'kind', answer.answer_kind,
        'text_value', answer.text_value, 'integer_value', answer.integer_value,
        'decimal_value', answer.decimal_value, 'money_minor_units', answer.money_minor_units,
        'date_value', answer.date_value, 'yes_no_value', answer.yes_no_value,
        'scale_value', answer.scale_value,
        'option_ids', coalesce((select jsonb_agg(selected.option_id order by selected.position)
                                from public.form_answer_options selected where selected.answer_id = answer.id), '[]'::jsonb),
        'asset_ids', coalesce((select jsonb_agg(asset.asset_id order by asset.position)
                               from public.form_answer_assets asset where asset.answer_id = answer.id), '[]'::jsonb)
      ) order by item.position)
      from public.form_answers answer join public.form_items item on item.id = answer.item_id
      where answer.response_id = response_row.id
    ), '[]'::jsonb)
  );
end;
$$;


