CREATE OR REPLACE FUNCTION "app_private"."form_item_config_valid"("p_kind" "text", "p_config" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  value_min numeric;
  value_max numeric;
  date_min date;
  date_max date;
  selection_min integer;
  selection_max integer;
  image_min integer;
  image_max integer;
  scale_min integer;
  scale_max integer;
  max_length integer;
begin
  if jsonb_typeof(p_config) <> 'object' or exists (
    select 1 from jsonb_object_keys(p_config) as key
     where key not in (
       'max_length', 'min_value', 'max_value', 'decimal_places', 'currency',
       'min_selections', 'max_selections', 'scale_min', 'scale_max',
       'scale_min_label', 'scale_max_label', 'allow_camera', 'allow_existing',
       'min_images', 'max_images'
     )
  ) then return false; end if;

  if p_kind = 'short_text' then
    if p_config - 'max_length' <> '{}'::jsonb
       or (p_config ? 'max_length' and (jsonb_typeof(p_config -> 'max_length') <> 'number'
           or (p_config ->> 'max_length')::numeric <> trunc((p_config ->> 'max_length')::numeric))) then return false; end if;
    max_length := coalesce((p_config ->> 'max_length')::integer, 1000);
    return max_length between 1 and 10000;
  elsif p_kind in ('integer', 'decimal', 'money') then
    if p_config - (case when p_kind = 'decimal' then array['min_value','max_value','decimal_places']
                       when p_kind = 'money' then array['min_value','max_value','currency']
                       else array['min_value','max_value'] end) <> '{}'::jsonb
       or (p_config ? 'min_value' and jsonb_typeof(p_config -> 'min_value') <> 'number')
       or (p_config ? 'max_value' and jsonb_typeof(p_config -> 'max_value') <> 'number') then return false; end if;
    value_min := (p_config ->> 'min_value')::numeric; value_max := (p_config ->> 'max_value')::numeric;
    if (p_kind in ('integer','money') and ((value_min is not null and value_min <> trunc(value_min)) or (value_max is not null and value_max <> trunc(value_max))))
       or (value_min is not null and value_max is not null and value_min > value_max) then return false; end if;
    return p_kind <> 'decimal' or not (p_config ? 'decimal_places')
      or (jsonb_typeof(p_config -> 'decimal_places') = 'number'
          and (p_config ->> 'decimal_places')::numeric = trunc((p_config ->> 'decimal_places')::numeric)
          and (p_config ->> 'decimal_places')::integer between 0 and 6);
  elsif p_kind = 'date' then
    if p_config - array['min_value','max_value'] <> '{}'::jsonb
       or (p_config ? 'min_value' and (jsonb_typeof(p_config -> 'min_value') <> 'string' or p_config ->> 'min_value' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
       or (p_config ? 'max_value' and (jsonb_typeof(p_config -> 'max_value') <> 'string' or p_config ->> 'max_value' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) then return false; end if;
    date_min := (p_config ->> 'min_value')::date; date_max := (p_config ->> 'max_value')::date;
    return date_min is null or date_max is null or date_min <= date_max;
  elsif p_kind = 'multiple_choice' then
    if p_config - array['min_selections','max_selections'] <> '{}'::jsonb
       or (p_config ? 'min_selections' and jsonb_typeof(p_config -> 'min_selections') <> 'number')
       or (p_config ? 'max_selections' and jsonb_typeof(p_config -> 'max_selections') <> 'number')
       or (p_config ? 'min_selections' and (p_config ->> 'min_selections')::numeric <> trunc((p_config ->> 'min_selections')::numeric))
       or (p_config ? 'max_selections' and (p_config ->> 'max_selections')::numeric <> trunc((p_config ->> 'max_selections')::numeric)) then return false; end if;
    selection_min := coalesce((p_config ->> 'min_selections')::integer, 1);
    selection_max := coalesce((p_config ->> 'max_selections')::integer, 50);
    return selection_min between 1 and 50 and selection_max between selection_min and 50;
  elsif p_kind = 'scale' then
    if p_config - array['scale_min','scale_max','scale_min_label','scale_max_label'] <> '{}'::jsonb
       or (p_config ? 'scale_min' and jsonb_typeof(p_config -> 'scale_min') <> 'number')
       or (p_config ? 'scale_max' and jsonb_typeof(p_config -> 'scale_max') <> 'number')
       or (p_config ? 'scale_min' and (p_config ->> 'scale_min')::numeric <> trunc((p_config ->> 'scale_min')::numeric))
       or (p_config ? 'scale_max' and (p_config ->> 'scale_max')::numeric <> trunc((p_config ->> 'scale_max')::numeric)) then return false; end if;
    scale_min := coalesce((p_config ->> 'scale_min')::integer, 1);
    scale_max := coalesce((p_config ->> 'scale_max')::integer, 10);
    if scale_min <> 1 or scale_max not in (5, 10) then
      raise check_violation using message = 'scale configuration must be 1-5 or 1-10';
    end if;
    return true;
  elsif p_kind in ('photo','gallery') then
    if p_config - (case when p_kind = 'photo' then array['allow_camera','min_images','max_images']
                       else array['allow_existing','min_images','max_images'] end) <> '{}'::jsonb
       or (p_kind = 'photo' and p_config ? 'allow_camera' and jsonb_typeof(p_config -> 'allow_camera') <> 'boolean')
       or (p_kind = 'gallery' and p_config ? 'allow_existing' and jsonb_typeof(p_config -> 'allow_existing') <> 'boolean')
       or (p_config ? 'min_images' and jsonb_typeof(p_config -> 'min_images') <> 'number')
       or (p_config ? 'max_images' and jsonb_typeof(p_config -> 'max_images') <> 'number')
       or (p_config ? 'min_images' and (p_config ->> 'min_images')::numeric <> trunc((p_config ->> 'min_images')::numeric))
       or (p_config ? 'max_images' and (p_config ->> 'max_images')::numeric <> trunc((p_config ->> 'max_images')::numeric)) then return false; end if;
    image_min := coalesce((p_config ->> 'min_images')::integer, 1);
    image_max := coalesce((p_config ->> 'max_images')::integer, case when p_kind = 'photo' then 1 else 5 end);
    return image_min between 1 and 5 and image_max between image_min and 5
      and (p_kind <> 'photo' or (image_min = 1 and image_max = 1));
  end if;
  return p_config = '{}'::jsonb;
exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
  return false;
end;
$_$;


ALTER FUNCTION "app_private"."form_item_config_valid"("p_kind" "text", "p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_list"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.read');
declare page_limit integer := least(greatest(coalesce((p_query ->> 'limit')::integer, 25), 1), 100);
declare cursor_updated timestamptz;
declare cursor_id uuid;
begin
  perform app_private.form_assert_payload_keys(
    p_query,
    array['institution_id','search','statuses','operational_statuses','kinds','starts_on_or_after','ends_on_or_before','cursor_updated_at','cursor_id','limit'],
    'form directory query'
  );
  cursor_updated := (p_query ->> 'cursor_updated_at')::timestamptz;
  cursor_id := (p_query ->> 'cursor_id')::uuid;
  return (
    with operational as (
      select form_row.*,
             case
               when form_row.status = 'archived' then 'archived'
               when form_row.status = 'draft' then 'draft'
               when coalesce(occurrence_window.is_active, false) then 'active'
               when coalesce(occurrence_window.is_scheduled, false) then 'scheduled'
               else 'closed'
             end as operational_status
        from public.forms form_row
        left join lateral (
          select bool_or(
                   occurrence_row.status in ('scheduled', 'open')
                   and occurrence_row.opens_at <= now()
                   and occurrence_row.closes_at > now()
                 ) as is_active,
                 bool_or(
                   occurrence_row.status in ('scheduled', 'open')
                   and occurrence_row.opens_at > now()
                 ) as is_scheduled
            from public.form_occurrences occurrence_row
           where occurrence_row.form_id = form_row.id
        ) occurrence_window on true
       where not app_private.superadmin_form_is_internal_draft_v2(form_row.id)
         and ((p_query ->> 'institution_id') is null
              or form_row.institution_id = (p_query ->> 'institution_id')::uuid)
         and (nullif(p_query ->> 'search', '') is null
              or form_row.title ilike '%' || app_private.form_escape_like(p_query ->> 'search') || '%' escape '\')
         and (coalesce(jsonb_array_length(p_query -> 'statuses'), 0) = 0 or form_row.status in (
           select jsonb_array_elements_text(p_query -> 'statuses')
         ))
         and (coalesce(jsonb_array_length(p_query -> 'kinds'), 0) = 0 or form_row.kind in (
           select jsonb_array_elements_text(p_query -> 'kinds')
         ))
         and ((p_query ->> 'starts_on_or_after') is null or exists (
           select 1 from public.form_occurrences occurrence_row
            where occurrence_row.form_id = form_row.id
              and occurrence_row.opens_at::date >= (p_query ->> 'starts_on_or_after')::date
         ))
         and ((p_query ->> 'ends_on_or_before') is null or exists (
           select 1 from public.form_occurrences occurrence_row
            where occurrence_row.form_id = form_row.id
              and occurrence_row.closes_at::date <= (p_query ->> 'ends_on_or_before')::date
         ))
    ), page as (
      select operational.*
        from operational
       where (coalesce(jsonb_array_length(p_query -> 'operational_statuses'), 0) = 0
              or operational_status in (
                select jsonb_array_elements_text(p_query -> 'operational_statuses')
              ))
         and (cursor_updated is null or (updated_at, id) < (cursor_updated, cursor_id))
       order by updated_at desc, id desc
       limit page_limit + 1
    ), visible as (select * from page limit page_limit)
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'title', title, 'kind', kind, 'status', status,
        'operational_status', operational_status,
        'identity_mode', identity_mode, 'updated_at', updated_at,
        'management_version', management_version
      ) order by updated_at desc, id desc), '[]'::jsonb),
      'has_more', (select count(*) > page_limit from page),
      'next_cursor', (select jsonb_build_object('updated_at', updated_at, 'id', id)
                        from visible order by updated_at, id limit 1)
    ) from visible
  );
end;
$$;


ALTER FUNCTION "app_private"."form_list"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_list_audience_candidates"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.manage_applications');
declare page_limit integer := least(greatest(coalesce((p_query ->> 'limit')::integer, 25), 1), 100);
declare candidate_kind text := p_query ->> 'kind';
begin
  perform app_private.form_assert_payload_keys(
    p_query, array['institution_id','kind','search','cursor_label','cursor_id','limit'],
    'form audience candidates query'
  );
  return (
    with candidates as (
      select person.id, person.display_name as label, candidate_kind::text as kind
        from public.people person
        join public.institution_memberships membership on membership.person_id = person.id
       where candidate_kind in ('person','guardian','teacher','employee','profile')
         and membership.institution_id = (p_query ->> 'institution_id')::uuid
         and membership.status = 'active'
         and membership.revoked_at is null
      union all
      select unit_row.id, unit_row.name, 'unit'
        from public.units unit_row
       where candidate_kind = 'unit'
         and unit_row.institution_id = (p_query ->> 'institution_id')::uuid
      union all
      select group_row.id, group_row.name, 'group'
        from public.groups group_row
       where candidate_kind = 'group'
         and group_row.institution_id = (p_query ->> 'institution_id')::uuid
      union all
      select activity_row.id, activity_row.name, 'activity'
        from public.activity_definitions activity_row
       where candidate_kind = 'activity'
         and activity_row.institution_id = (p_query ->> 'institution_id')::uuid
      union all
      select institution_row.id, institution_row.public_name, 'institution'
        from public.institutions institution_row
       where candidate_kind = 'institution'
         and institution_row.id = (p_query ->> 'institution_id')::uuid
    ), filtered as (
      select * from candidates
       where (nullif(p_query ->> 'search', '') is null
              or label ilike '%' || app_private.form_escape_like(p_query ->> 'search') || '%' escape '\')
         and ((p_query ->> 'cursor_label') is null
              or (lower(label), id) > (lower(p_query ->> 'cursor_label'), (p_query ->> 'cursor_id')::uuid))
       order by lower(label), id limit page_limit + 1
    ), visible as (select * from filtered limit page_limit)
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object('id', id, 'label', label, 'kind', kind)
                                  order by lower(label), id), '[]'::jsonb),
      'has_more', (select count(*) > page_limit from filtered),
      'next_cursor', (select jsonb_build_object('label', label, 'id', id)
                        from visible order by lower(label) desc, id desc limit 1)
    ) from visible
  );
end;
$$;


ALTER FUNCTION "app_private"."form_list_audience_candidates"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_list_file_jobs"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.current_person_id();
declare page_limit integer := least(greatest(coalesce((p_query ->> 'limit')::integer, 25), 1), 100);
declare cursor_created timestamptz := (p_query ->> 'cursor_created_at')::timestamptz;
declare cursor_id uuid := (p_query ->> 'cursor_id')::uuid;
begin
  if actor is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  perform app_private.form_assert_payload_keys(
    p_query, array['form_id','cursor_created_at','cursor_id','limit'], 'form file jobs query'
  );
  return (
    with page as (
      select job.*
        from public.form_file_jobs job
       where job.form_id = (p_query ->> 'form_id')::uuid
         and job.requested_by_person_id = actor
         and app_private.form_actor_has_export_permission(actor, job.export_kind)
         and (cursor_created is null or (job.created_at, job.id) < (cursor_created, cursor_id))
       order by job.created_at desc, job.id desc
       limit page_limit + 1
    ), visible as (
      select * from page limit page_limit
    )
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'status', state, 'progress', progress,
        'download_available', state in ('succeeded','partial')
          and expires_at > now() and artifact_path is not null,
        'error_code', error_code, 'expires_at', expires_at
      ) order by created_at desc, id desc), '[]'::jsonb),
      'has_more', (select count(*) > page_limit from page),
      'next_cursor', (
        select jsonb_build_object('created_at', created_at, 'id', id)
          from visible order by created_at, id limit 1
      )
    ) from visible
  );
end;
$$;


ALTER FUNCTION "app_private"."form_list_file_jobs"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_list_monitor_hierarchy"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.monitor');
declare form_row public.forms;
declare requested_scope_kind text;
declare wanted_scope_kind text;
declare page_limit integer := least(greatest(coalesce((p_query ->> 'limit')::integer, 25), 1), 100);
declare cursor_label text := p_query ->> 'cursor_label';
declare cursor_id uuid := (p_query ->> 'cursor_id')::uuid;
begin
  perform app_private.form_assert_payload_keys(
    p_query, array['form_id','application_id','occurrence_id','starts_on_or_after','ends_on_or_before',
                    'scope_id','cursor_label','cursor_id','limit'],
    'form monitor hierarchy query'
  );
  perform app_private.superadmin_form_assert_legacy_resource_v2((p_query ->> 'form_id')::uuid);
  select * into form_row from public.forms where id = (p_query ->> 'form_id')::uuid;
  if form_row.id is null then raise no_data_found using message = 'form unavailable'; end if;

  if p_query ->> 'scope_id' is not null then
    select metric.scope_kind into requested_scope_kind
      from public.form_scope_metrics metric
      join public.form_occurrences occurrence on occurrence.id = metric.occurrence_id
     where occurrence.form_id = form_row.id and metric.scope_id = (p_query ->> 'scope_id')::uuid
     limit 1;
    if requested_scope_kind is null then
      raise no_data_found using message = 'monitor scope unavailable';
    end if;
  end if;
  wanted_scope_kind := case
    when requested_scope_kind is null then 'institution'
    when requested_scope_kind = 'institution' then 'unit'
    when requested_scope_kind = 'unit' then 'group'
    when requested_scope_kind = 'group' then 'activity'
    when requested_scope_kind = 'activity' then 'profile'
    else null
  end;
  if wanted_scope_kind is null then
    return jsonb_build_object('items', '[]'::jsonb, 'has_more', false, 'next_cursor', null);
  end if;

  return (
    with scopes as (
      select metric.scope_id, metric.scope_kind,
             case metric.scope_kind
               when 'institution' then (select coalesce(institution.trade_name, institution.legal_name, '') from public.institutions institution where institution.id = metric.scope_id)
               when 'unit' then (select unit.name from public.units unit where unit.id = metric.scope_id and unit.institution_id = form_row.institution_id)
               when 'group' then (select group_row.name from public.groups group_row where group_row.id = metric.scope_id and group_row.institution_id = form_row.institution_id)
               when 'activity' then (select activity.name from public.activity_definitions activity where activity.id = metric.scope_id and activity.institution_id = form_row.institution_id)
               when 'profile' then (select role_row.name from public.institution_roles role_row where role_row.id = metric.scope_id and role_row.institution_id = form_row.institution_id)
             end as label,
             sum(metric.eligible_count)::bigint as eligible_count,
             sum(metric.responded_count)::bigint as responded_count,
             sum(metric.pending_count)::bigint as pending_count
        from public.form_scope_metrics metric
        join public.form_occurrences occurrence on occurrence.id = metric.occurrence_id
       where occurrence.form_id = form_row.id and metric.institution_id = form_row.institution_id
         and metric.scope_kind = wanted_scope_kind
         and (
           requested_scope_kind is null
           or requested_scope_kind = 'institution'
           or (requested_scope_kind = 'unit' and exists(
             select 1 from public.groups group_row
              where group_row.id = metric.scope_id
                and group_row.unit_id = (p_query ->> 'scope_id')::uuid
                and group_row.institution_id = form_row.institution_id
           ))
           or (requested_scope_kind = 'group' and exists(
             select 1 from public.activity_group_links activity_link
              where activity_link.activity_id = metric.scope_id
                and activity_link.group_id = (p_query ->> 'scope_id')::uuid
                and activity_link.institution_id = form_row.institution_id
                and activity_link.status = 'active'
           ))
           or requested_scope_kind = 'activity'
         )
         and ((p_query ->> 'application_id') is null or occurrence.application_id = (p_query ->> 'application_id')::uuid)
         and ((p_query ->> 'occurrence_id') is null or occurrence.id = (p_query ->> 'occurrence_id')::uuid)
         and ((p_query ->> 'starts_on_or_after') is null or occurrence.opens_at::date >= (p_query ->> 'starts_on_or_after')::date)
         and ((p_query ->> 'ends_on_or_before') is null or occurrence.closes_at::date <= (p_query ->> 'ends_on_or_before')::date)
       group by metric.scope_id, metric.scope_kind
    ), page as (
      select * from scopes
       where label is not null
         and (cursor_label is null or (lower(label), scope_id) > (lower(cursor_label), cursor_id))
       order by lower(label), scope_id limit page_limit + 1
    ), visible as (select * from page limit page_limit)
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'scope_id', scope_id, 'scope_kind', scope_kind, 'label', label,
        'eligible_count', eligible_count, 'responded_count', responded_count, 'pending_count', pending_count
      ) order by lower(label), scope_id), '[]'::jsonb),
      'has_more', (select count(*) > page_limit from page),
      'next_cursor', (select jsonb_build_object('label', label, 'id', scope_id)
                        from visible order by lower(label) desc, scope_id desc limit 1)
    ) from visible
  );
end;
$$;


ALTER FUNCTION "app_private"."form_list_monitor_hierarchy"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_list_monitor_people"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.monitor');
declare form_row public.forms;
declare page_limit integer := least(greatest(coalesce((p_query ->> 'limit')::integer, 25), 1), 100);
begin
  perform app_private.form_assert_payload_keys(
    p_query, array[
      'form_id','application_id','occurrence_id','starts_on_or_after','ends_on_or_before','scope_id',
      'justification','cursor_name','cursor_id','limit'
    ],
    'form monitor people query'
  );
  perform app_private.superadmin_form_assert_legacy_resource_v2((p_query ->> 'form_id')::uuid);
  select * into form_row from public.forms where id = (p_query ->> 'form_id')::uuid;
  if form_row.id is null then raise no_data_found using message = 'form unavailable'; end if;
  if form_row.identity_mode = 'anonymous' then
    perform app_private.form_require_owner(actor, 'forms.anonymous_participation.read');
    if char_length(btrim(coalesce(p_query ->> 'justification', ''))) < 10 then
      raise invalid_parameter_value using message = 'auditable justification required';
    end if;
  end if;
  return (
    with page as (
      select participation.id, coalesce(person.id, responder_person.id) as person_id,
             coalesce(person.display_name, responder_person.display_name) as display_name,
             membership.role_code as profile_label,
             participation.response_unit_key as context_label,
             participation.response_state = 'responded' as responded
        from public.form_participations participation
        join public.form_occurrences occurrence_row on occurrence_row.id = participation.occurrence_id
        left join public.people person on person.id = participation.person_id
        left join public.form_participation_responders responder on responder.participation_id = participation.id
        left join public.people responder_person on responder_person.id = responder.person_id
        left join public.institution_memberships membership
          on membership.person_id = coalesce(person.id, responder_person.id)
         and membership.institution_id = participation.institution_id and membership.status = 'active'
       where occurrence_row.form_id = form_row.id
         and ((p_query ->> 'application_id') is null
              or occurrence_row.application_id = (p_query ->> 'application_id')::uuid)
         and ((p_query ->> 'occurrence_id') is null or occurrence_row.id = (p_query ->> 'occurrence_id')::uuid)
         and ((p_query ->> 'starts_on_or_after') is null
              or occurrence_row.opens_at::date >= (p_query ->> 'starts_on_or_after')::date)
         and ((p_query ->> 'ends_on_or_before') is null
              or occurrence_row.closes_at::date <= (p_query ->> 'ends_on_or_before')::date)
         and participation.eligibility_state = 'eligible'
         and ((p_query ->> 'cursor_name') is null
              or (lower(coalesce(person.display_name, responder_person.display_name)), participation.id)
                 > (lower(p_query ->> 'cursor_name'), (p_query ->> 'cursor_id')::uuid))
       order by lower(coalesce(person.display_name, responder_person.display_name)), participation.id
       limit page_limit + 1
    ), visible as (select * from page limit page_limit)
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'person_id', person_id, 'display_name', display_name, 'profile_label', profile_label,
        'context_label', context_label, 'responded', responded
      )), '[]'::jsonb),
      'has_more', (select count(*) > page_limit from page),
      'next_cursor', (select jsonb_build_object('name', display_name, 'id', id)
                        from visible order by lower(display_name) desc, id desc limit 1)
    ) from visible
  );
end;
$$;


ALTER FUNCTION "app_private"."form_list_monitor_people"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_list_responses"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.responses.read');
declare page_limit integer := least(greatest(coalesce((p_query ->> 'limit')::integer, 25), 1), 100);
declare cursor_submitted timestamptz := (p_query ->> 'cursor_submitted_at')::timestamptz;
declare cursor_id uuid := (p_query ->> 'cursor_id')::uuid;
begin
  perform app_private.form_assert_payload_keys(
    p_query, array['form_id','occurrence_id','cursor_submitted_at','cursor_id','limit'],
    'form responses query'
  );
  return (
    with page as (
      select response.*, person.display_name
        from public.form_responses response
        left join public.people person on person.id = response.respondent_person_id
       where response.form_id = (p_query ->> 'form_id')::uuid and response.status = 'submitted'
         and ((p_query ->> 'occurrence_id') is null or response.occurrence_id = (p_query ->> 'occurrence_id')::uuid)
         and (cursor_submitted is null or (response.submitted_at, response.id) < (cursor_submitted, cursor_id))
       order by response.submitted_at desc, response.id desc limit page_limit + 1
    ), visible as (select * from page limit page_limit)
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'occurrence_id', occurrence_id, 'form_version_id', form_version_id,
        'submitted_at', case when identity_mode = 'identified' then submitted_at else null end,
        'respondent_label', case when identity_mode = 'identified' then display_name else null end
      ) order by submitted_at desc, id desc), '[]'::jsonb),
      'has_more', (select count(*) > page_limit from page),
      'next_cursor', (select jsonb_build_object('submitted_at', submitted_at, 'id', id)
                        from visible order by submitted_at, id limit 1)
    ) from visible
  );
end;
$$;


