CREATE OR REPLACE FUNCTION "app_private"."form_location_option_available_v1"("p_option_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.form_question_options o
    join public.activity_locations l on l.id = o.location_id
