CREATE OR REPLACE FUNCTION "app_private"."form_media_assert_worker_v1"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(nullif(current_setting('request.jwt.claim.role', true), ''),
      nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') <> 'service_role' then
    raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
  end if;
end $$;


ALTER FUNCTION "app_private"."form_media_assert_worker_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_media_dispatch_cleanup_worker"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_url text;
declare bearer_token text;
declare request_id bigint;
begin
  select decrypted_secret into worker_url
    from vault.decrypted_secrets where name = 'form_media_worker_url' limit 1;
  select decrypted_secret into bearer_token
    from vault.decrypted_secrets where name = 'forms_worker_bearer_token' limit 1;
  if nullif(worker_url, '') is null or nullif(bearer_token, '') is null then
    return null;
  end if;
  select net.http_post(
    url := worker_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || bearer_token
    ),
    body := '{"action":"cleanup"}'::jsonb,
    timeout_milliseconds := 5000
  ) into request_id;
  return request_id;
end;
$$;


ALTER FUNCTION "app_private"."form_media_dispatch_cleanup_worker"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_media_envelope_error_v1"("p_code" "text", "p_correlation" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case when p_code in ('FORM_MEDIA_INVALID','FORM_MEDIA_NOT_FOUND','FORM_MEDIA_NOT_READY',
      'FORM_MEDIA_TICKET_INVALID','FORM_MEDIA_MISMATCH','FORM_MEDIA_REPLAY_MISMATCH')
    then pg_catalog.jsonb_build_object('ok', false, 'data', null, 'error', pg_catalog.jsonb_build_object(
      'code', p_code,
      'message', case p_code
        when 'FORM_MEDIA_INVALID' then 'Imagem não permitida: confira o tipo e o tamanho.'
        when 'FORM_MEDIA_NOT_FOUND' then 'Arquivo não encontrado.'
        when 'FORM_MEDIA_NOT_READY' then 'O arquivo ainda não terminou de ser enviado.'
        when 'FORM_MEDIA_TICKET_INVALID' then 'O envio expirou. Envie o arquivo novamente.'
        when 'FORM_MEDIA_MISMATCH' then 'O arquivo recebido não confere com o anunciado.'
        else 'A solicitação já foi usada com outros dados.' end,
      'http_status', case p_code
        when 'FORM_MEDIA_NOT_FOUND' then 404
        when 'FORM_MEDIA_INVALID' then 422 when 'FORM_MEDIA_MISMATCH' then 422
        else 409 end,
      'correlation_id', p_correlation))
    else app_private.superadmin_internal_error_envelope(p_code, p_correlation) end
$$;


ALTER FUNCTION "app_private"."form_media_envelope_error_v1"("p_code" "text", "p_correlation" "uuid") OWNER TO "postgres";


