CREATE OR REPLACE FUNCTION "app_private"."form_media_unbind_deleted_question_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  delete from public.media_bindings binding
  where binding.media_asset_id = new.id
    and binding.purpose = 'question-image';
  return new;
end;
$$;


ALTER FUNCTION "app_private"."form_media_unbind_deleted_question_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_mutate_response"("p_command" "text", "p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb", "p_submit" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.respond');
declare response_row public.form_responses;
declare occurrence_row public.form_occurrences;
declare participation_row public.form_participations;
declare replay jsonb;
declare revision_number integer;
declare result jsonb;
declare expected_action text;
begin
  perform app_private.form_assert_payload_keys(
    p_payload, array['response_id','participation_id','edit_secret','answers'], 'form response mutation'
  );
  select * into response_row from public.form_responses
   where id = (p_payload ->> 'response_id')::uuid for update;
  if response_row.id is null then raise no_data_found using message = 'form response unavailable'; end if;
  perform app_private.form_assert_response_actor(response_row, actor, p_payload ->> 'edit_secret');
  if response_row.identity_mode = 'identified' then
    replay := app_private.form_begin_command(
      p_request_id, actor, p_command, p_expected_version, p_payload
    );
    if replay is not null then return replay; end if;
  else
    expected_action := case when p_submit then 'submitted'
      when p_command = 'form_edit_response' then 'edited' else 'draft_saved' end;
    if response_row.management_version = p_expected_version + 1
       and exists (
         select 1 from public.form_response_revisions revision
          where revision.response_id = response_row.id
            and revision.action = expected_action
            and revision.answers_snapshot = p_payload -> 'answers'
       ) then
      return app_private.form_response_draft_projection(response_row.id);
    end if;
  end if;
  if response_row.management_version <> p_expected_version then
    raise serialization_failure using message = 'expected_version mismatch';
  end if;
  select * into occurrence_row from public.form_occurrences
   where id = response_row.occurrence_id for update;
  if occurrence_row.status <> 'open' or now() not between occurrence_row.opens_at and occurrence_row.closes_at then
    raise no_data_found using message = 'form occurrence unavailable';
  end if;
  select participation.* into participation_row
    from public.form_participations participation
   where participation.id = (p_payload ->> 'participation_id')::uuid
     and participation.occurrence_id = response_row.occurrence_id
     and participation.eligibility_state = 'eligible'
     and (
       participation.person_id = actor
       or exists(select 1 from public.form_participation_responders responder
                 where responder.participation_id = participation.id and responder.person_id = actor)
     )
   for update;
  if participation_row.id is null then
    raise no_data_found using message = 'form participation unavailable';
  end if;
  if p_submit and response_row.status <> 'draft' then
    raise check_violation using message = 'only a draft response can be submitted';
  end if;
  if p_command = 'form_edit_response' and response_row.status <> 'submitted' then
    raise check_violation using message = 'only a submitted response can be edited';
  end if;
  if p_command = 'form_save_response_draft' and response_row.status <> 'draft' then
    raise check_violation using message = 'only a draft response can be saved';
  end if;
  perform app_private.form_replace_response_answers(
    response_row, p_payload -> 'answers', p_payload ->> 'edit_secret'
  );
  if p_submit or p_command = 'form_edit_response' then
    perform app_private.form_assert_required_response_answers(response_row);
  end if;
  if p_submit then
    if participation_row.response_state = 'responded' then
      raise no_data_found using message = 'form participation unavailable';
    end if;
    update public.form_responses
       set status = 'submitted', submitted_at = now(), updated_at = now(),
           management_version = management_version + 1
     where id = response_row.id returning * into response_row;
    update public.form_participations
       set response_state = 'responded', responded_at = now()
     where id = participation_row.id;
    perform app_private.form_rebuild_occurrence_metrics(response_row.occurrence_id);
  else
    update public.form_responses
       set updated_at = now(), management_version = management_version + 1
     where id = response_row.id returning * into response_row;
  end if;
  select coalesce(max(revision_row.revision_number), 0) + 1 into revision_number
    from public.form_response_revisions revision_row where revision_row.response_id = response_row.id;
  insert into public.form_response_revisions(
    response_id, revision_number, action, answers_snapshot, changed_by_person_id
  ) values (
    response_row.id, revision_number,
    case when p_submit then 'submitted'
         when p_command = 'form_edit_response' then 'edited'
         else 'draft_saved' end,
    p_payload -> 'answers', case when response_row.identity_mode = 'identified' then actor else null end
  );
  result := app_private.form_response_draft_projection(response_row.id);
  if response_row.identity_mode = 'anonymous' then return result; end if;
  return app_private.form_complete_command(p_request_id, result);
end;
$$;


ALTER FUNCTION "app_private"."form_mutate_response"("p_command" "text", "p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb", "p_submit" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_open_response_draft"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.respond');
declare participation_row public.form_participations;
declare occurrence_row public.form_occurrences;
declare response_row public.form_responses;
declare replay jsonb;
declare result jsonb;
declare requested_identity_mode text;
begin
  perform app_private.form_assert_payload_keys(
    p_payload, array['occurrence_id','participation_id','identity_mode','edit_secret'],
    'open form response draft'
  );
  if p_expected_version <> 0 then
    raise serialization_failure using message = 'expected_version mismatch';
  end if;
  select * into participation_row
    from public.form_participations
   where id = (p_payload ->> 'participation_id')::uuid
     and occurrence_id = (p_payload ->> 'occurrence_id')::uuid
   for update;
  if participation_row.id is null or participation_row.eligibility_state <> 'eligible'
     or not (
       participation_row.person_id = actor
       or exists(
         select 1 from public.form_participation_responders responder
         where responder.participation_id = participation_row.id and responder.person_id = actor
       )
     ) then
    raise no_data_found using message = 'form occurrence unavailable';
  end if;
  select * into occurrence_row from public.form_occurrences
   where id = participation_row.occurrence_id for update;
  if occurrence_row.status <> 'open' or now() not between occurrence_row.opens_at and occurrence_row.closes_at then
    raise no_data_found using message = 'form occurrence unavailable';
  end if;
  select identity_mode into requested_identity_mode
    from public.forms where id = occurrence_row.form_id;
  if p_payload ->> 'identity_mode' <> requested_identity_mode then
    raise check_violation using message = 'form identity mode mismatch';
  end if;
  if requested_identity_mode = 'identified' then
    replay := app_private.form_begin_command(
      p_request_id, actor, 'form_open_response_draft', p_expected_version, p_payload
    );
    if replay is not null then return replay; end if;
  end if;
  if requested_identity_mode = 'anonymous' then
    if char_length(coalesce(p_payload ->> 'edit_secret', '')) < 43 then
      raise invalid_parameter_value using message = 'anonymous edit secret required';
    end if;
    select * into response_row
      from public.form_responses candidate
     where candidate.occurrence_id = occurrence_row.id
       and candidate.identity_mode = 'anonymous'
       and candidate.status in ('draft', 'submitted')
       and app_private.form_verify_anonymous_edit_secret(
         p_payload ->> 'edit_secret', candidate.anonymous_edit_secret_hash
       )
     limit 1;
    if participation_row.response_state = 'responded' and response_row.id is null then
      raise no_data_found using message = 'form response unavailable';
    end if;
    if response_row.id is null then
      insert into public.form_responses(
        occurrence_id, institution_id, form_id, form_version_id, identity_mode,
        anonymous_edit_secret_hash
      ) values (
        occurrence_row.id, occurrence_row.institution_id, occurrence_row.form_id,
        occurrence_row.form_version_id, 'anonymous',
        app_private.form_hash_anonymous_edit_secret(p_payload ->> 'edit_secret')
      ) returning * into response_row;
    end if;
  else
    select * into response_row from public.form_responses
     where occurrence_id = occurrence_row.id and respondent_person_id = actor
       and status in ('draft', 'submitted')
     for update;
    if participation_row.response_state = 'responded' and response_row.id is null then
      raise no_data_found using message = 'form response unavailable';
    end if;
    if response_row.id is null then
      insert into public.form_responses(
        occurrence_id, institution_id, form_id, form_version_id, identity_mode, respondent_person_id
      ) values (
        occurrence_row.id, occurrence_row.institution_id, occurrence_row.form_id,
        occurrence_row.form_version_id, 'identified', actor
      ) returning * into response_row;
    end if;
  end if;
  update public.form_participations
     set response_state = case when response_row.status = 'submitted' then 'responded' else 'draft' end,
         responded_at = case when response_row.status = 'submitted'
           then coalesce(responded_at, response_row.submitted_at) else responded_at end
   where id = participation_row.id;
  result := app_private.form_response_draft_projection(response_row.id);
  if requested_identity_mode = 'anonymous' then return result; end if;
  return app_private.form_complete_command(p_request_id, result);
end;
$$;


ALTER FUNCTION "app_private"."form_open_response_draft"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_prepare_asset_upload"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.respond');
declare occurrence_row public.form_occurrences;
declare item_row public.form_items;
declare asset_row public.form_assets;
declare replay jsonb;
declare opaque_id uuid := gen_random_uuid();
declare identity_mode text;
declare result jsonb;
begin
  perform app_private.form_assert_payload_keys(
    p_payload, array['occurrence_id','item_id','mime_type','byte_length','checksum','edit_secret'],
    'prepare form asset'
  );
  if p_expected_version <> 0 then raise serialization_failure using message = 'expected_version mismatch'; end if;
  select * into occurrence_row from public.form_occurrences
   where id = (p_payload ->> 'occurrence_id')::uuid;
  select * into item_row from public.form_items
   where id = (p_payload ->> 'item_id')::uuid
     and form_version_id = occurrence_row.form_version_id and kind in ('photo', 'gallery');
  if occurrence_row.id is null or item_row.id is null or occurrence_row.status <> 'open'
     or now() not between occurrence_row.opens_at and occurrence_row.closes_at
     or not exists(
       select 1 from public.form_participations participation
       where participation.occurrence_id = occurrence_row.id
         and participation.eligibility_state = 'eligible'
         and (participation.person_id = actor or exists(
           select 1 from public.form_participation_responders responder
           where responder.participation_id = participation.id and responder.person_id = actor
         ))
     ) then
    raise no_data_found using message = 'form asset target unavailable';
  end if;
  select form_row.identity_mode into identity_mode
    from public.forms form_row where form_row.id = occurrence_row.form_id;
  -- Serialize the per-respondent/question quota without holding a row lock
  -- across the later Storage request (the Edge function signs only after this
  -- transaction returns).
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      occurrence_row.id::text || ':' || item_row.id::text || ':' ||
      case when identity_mode = 'anonymous'
        then encode(extensions.digest(p_payload ->> 'edit_secret', 'sha256'), 'hex')
        else actor::text end,
      0
    )
  );
  if identity_mode = 'anonymous' then
    if not exists (
      select 1 from public.form_responses response
       where response.occurrence_id = occurrence_row.id
         and response.identity_mode = 'anonymous'
         and response.status = 'draft'
         and app_private.form_verify_anonymous_edit_secret(
           p_payload ->> 'edit_secret', response.anonymous_edit_secret_hash
         )
    ) then
      raise no_data_found using message = 'form asset target unavailable';
    end if;
    select * into asset_row from public.form_assets candidate
     where candidate.occurrence_id = occurrence_row.id
       and candidate.item_id = item_row.id
       and candidate.mime_type = p_payload ->> 'mime_type'
       and candidate.expected_byte_length = (p_payload ->> 'byte_length')::bigint
        and candidate.expected_checksum_sha256 = lower(p_payload ->> 'checksum')
        and candidate.state = 'prepared'
        and candidate.expires_at > now()
       and app_private.form_verify_anonymous_edit_secret(
         p_payload ->> 'edit_secret', candidate.anonymous_upload_secret_hash
       )
     limit 1;
    if asset_row.id is not null then
      return jsonb_build_object(
        'asset_id', asset_row.id, 'storage_path', asset_row.storage_path,
        'expires_at', asset_row.expires_at
      );
    end if;
  else
    replay := app_private.form_begin_command(
      p_request_id, actor, 'form_prepare_asset_upload', p_expected_version, p_payload
    );
    if replay is not null then return replay; end if;
  end if;
  if (select count(*) from public.form_assets candidate
      where candidate.occurrence_id = occurrence_row.id and candidate.item_id = item_row.id
        and candidate.state not in ('discarded','expired')
        and (
          candidate.prepared_by_person_id = actor
          or (identity_mode = 'anonymous' and app_private.form_verify_anonymous_edit_secret(
            p_payload ->> 'edit_secret', candidate.anonymous_upload_secret_hash
          ))
        )) >= 5 then
    raise check_violation using message = 'maximum five images per question';
  end if;
  insert into public.form_assets(
    id, institution_id, occurrence_id, item_id, prepared_by_person_id,
    anonymous_upload_secret_hash, storage_path,
    mime_type, expected_byte_length, expected_checksum_sha256
  ) values (
    opaque_id, occurrence_row.institution_id, occurrence_row.id, item_row.id,
    case when identity_mode = 'identified' then actor else null end,
    case when identity_mode = 'anonymous' then
      app_private.form_hash_anonymous_edit_secret(p_payload ->> 'edit_secret') else null end,
    substr(replace(opaque_id::text, '-', ''), 1, 2) || '/' || opaque_id::text,
    p_payload ->> 'mime_type', (p_payload ->> 'byte_length')::bigint,
    lower(p_payload ->> 'checksum')
  ) returning * into asset_row;
  result := jsonb_build_object(
    'asset_id', asset_row.id, 'storage_path', asset_row.storage_path,
    'expires_at', asset_row.expires_at
  );
  if identity_mode = 'anonymous' then return result; end if;
  return app_private.form_complete_command(p_request_id, result);
end;
$$;


ALTER FUNCTION "app_private"."form_prepare_asset_upload"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_publish"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.require_forms_actor('forms.publish');
  target_form_id uuid;
  form_row public.forms;
  replay jsonb;
  result jsonb;
begin
  perform app_private.form_assert_payload_keys(p_payload, array['form_id'], 'form publish');
  target_form_id := (p_payload ->> 'form_id')::uuid;
  perform app_private.superadmin_form_lock_legacy_resource_v2(target_form_id);
  replay := app_private.form_begin_command(
    p_request_id, actor, 'form_publish', p_expected_version, p_payload
  );
  if replay is not null then return replay; end if;
  perform pg_advisory_xact_lock(hashtextextended(target_form_id::text, 0));
  select * into form_row from public.forms where id = target_form_id for update;
  perform app_private.superadmin_form_assert_legacy_resource_v2(form_row.id);
  if form_row.id is null then raise no_data_found using message = 'form unavailable'; end if;
  if form_row.management_version <> p_expected_version then
    raise serialization_failure using message = 'expected_version mismatch';
  end if;
  if form_row.working_version_id is null then
    raise check_violation using message = 'working version required';
  end if;
  perform app_private.form_apply_location_options_v1(form_row.working_version_id);
  perform app_private.validate_form_definition(form_row.working_version_id);
  update public.form_versions
     set state = 'superseded'
   where id = form_row.published_version_id and state = 'published';
  update public.form_versions
     set state = 'published', published_at = now()
   where id = form_row.working_version_id and state = 'working';
  update public.forms
     set status = 'published',
         published_version_id = working_version_id,
         working_version_id = null,
         first_published_at = coalesce(first_published_at, now()),
         management_version = management_version + 1,
         updated_by_person_id = actor,
         updated_at = now()
   where id = target_form_id;
  update public.form_occurrences
     set form_version_id = form_row.working_version_id,
         management_version = management_version + 1
   where form_occurrences.form_id = target_form_id
     and status = 'scheduled'
     and opens_at > now();
  result := app_private.form_definition_projection(target_form_id);
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id, institution_id, outcome,
    after_json
  ) values (
    actor, auth.jwt() ->> 'aal', 'forms.publish', 'form', target_form_id,
    form_row.institution_id, 'success', jsonb_build_object('published_version_id', form_row.working_version_id)
  );
  return app_private.form_complete_command(p_request_id, result);
end;
$$;


ALTER FUNCTION "app_private"."form_publish"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_rebuild_occurrence_metrics"("p_occurrence_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.form_occurrence_metrics(
    occurrence_id, institution_id, eligible_count, responded_count, pending_count, updated_at
  )
  select occurrence.id, occurrence.institution_id,
         count(*) filter (where participation.eligibility_state = 'eligible'),
         count(*) filter (where participation.eligibility_state = 'eligible' and participation.response_state = 'responded'),
         count(*) filter (where participation.eligibility_state = 'eligible' and participation.response_state <> 'responded'), now()
    from public.form_occurrences occurrence
    left join public.form_participations participation on participation.occurrence_id = occurrence.id
   where occurrence.id = p_occurrence_id
   group by occurrence.id, occurrence.institution_id
  on conflict(occurrence_id) do update set
    eligible_count = excluded.eligible_count, responded_count = excluded.responded_count,
    pending_count = excluded.pending_count, updated_at = excluded.updated_at;
  perform app_private.form_rebuild_occurrence_scope_metrics(p_occurrence_id);
end;
$$;


ALTER FUNCTION "app_private"."form_rebuild_occurrence_metrics"("p_occurrence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_rebuild_occurrence_scope_metrics"("p_occurrence_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  delete from public.form_scope_metrics where occurrence_id = p_occurrence_id;

  insert into public.form_scope_metrics(
    occurrence_id, institution_id, scope_kind, scope_id,
    eligible_count, responded_count, pending_count, updated_at
  )
  with occurrence_row as (
    select occurrence.id, occurrence.institution_id, occurrence.application_id
      from public.form_occurrences occurrence
     where occurrence.id = p_occurrence_id
  ), scopes as (
    select occurrence.id as occurrence_id, occurrence.institution_id,
           'institution'::text as scope_kind, occurrence.institution_id as scope_id
      from occurrence_row occurrence
    union
    select occurrence.id, occurrence.institution_id, rule.rule_kind, rule.target_id
      from occurrence_row occurrence
      join public.form_audience_rules rule on rule.application_id = occurrence.application_id
     where rule.rule_mode = 'include'
       and rule.rule_kind in ('unit', 'group', 'activity', 'profile')
  ), counted as (
    select scope.occurrence_id, scope.institution_id, scope.scope_kind, scope.scope_id,
           count(*) filter (where participation.eligibility_state = 'eligible') as eligible_count,
           count(*) filter (
             where participation.eligibility_state = 'eligible'
               and participation.response_state = 'responded'
           ) as responded_count,
           count(*) filter (
             where participation.eligibility_state = 'eligible'
               and participation.response_state <> 'responded'
           ) as pending_count
      from scopes scope
      left join public.form_participations participation
        on participation.occurrence_id = scope.occurrence_id
       and (
         scope.scope_kind = 'institution'
         or (scope.scope_kind = 'unit' and (
           exists(
             select 1 from public.institution_memberships membership
              where membership.person_id = participation.person_id
                and membership.institution_id = scope.institution_id
                and membership.status = 'active'
                and membership.scope_unit_id = scope.scope_id
           ) or exists(
             select 1 from public.child_unit_links child_unit
              where child_unit.child_context_id = participation.child_context_id
                and child_unit.unit_id = scope.scope_id and child_unit.status = 'active'
           )
         ))
         or (scope.scope_kind = 'group' and (
           exists(
             select 1 from public.institution_memberships membership
              where membership.person_id = participation.person_id
                and membership.institution_id = scope.institution_id
                and membership.status = 'active'
                and membership.scope_group_id = scope.scope_id
           ) or exists(
             select 1 from public.child_group_links child_group
              join public.child_unit_links child_unit on child_unit.id = child_group.child_unit_link_id
              where child_unit.child_context_id = participation.child_context_id
                and child_group.group_id = scope.scope_id and child_group.status = 'active'
           )
         ))
         or (scope.scope_kind = 'activity' and (
           exists(
             select 1 from public.activity_group_assignments assignment
              join public.activity_group_links activity_link on activity_link.id = assignment.activity_group_link_id
              where assignment.person_id = participation.person_id
                and assignment.status = 'active' and activity_link.status = 'active'
                and activity_link.activity_id = scope.scope_id
           ) or exists(
             select 1 from public.child_group_links child_group
              join public.child_unit_links child_unit on child_unit.id = child_group.child_unit_link_id
              join public.activity_group_links activity_link on activity_link.group_id = child_group.group_id
              left join public.activity_group_participants selected
                on selected.activity_group_link_id = activity_link.id
               and selected.child_group_link_id = child_group.id
               and selected.status = 'active' and selected.removed_at is null
              where child_unit.child_context_id = participation.child_context_id
                and child_group.status = 'active' and activity_link.status = 'active'
                and activity_link.activity_id = scope.scope_id
                and (activity_link.participation_mode = 'all' or selected.id is not null)
           )
         ))
         or (scope.scope_kind = 'profile' and exists(
           select 1 from public.institution_role_assignments assignment
            where assignment.membership_id in (
              select membership.id from public.institution_memberships membership
               where membership.person_id = participation.person_id
                 and membership.institution_id = scope.institution_id and membership.status = 'active'
            ) and assignment.role_id = scope.scope_id and assignment.status = 'active'
         ))
       )
     group by scope.occurrence_id, scope.institution_id, scope.scope_kind, scope.scope_id
  )
  select occurrence_id, institution_id, scope_kind, scope_id,
         eligible_count, responded_count, pending_count, now()
    from counted;
$$;


ALTER FUNCTION "app_private"."form_rebuild_occurrence_scope_metrics"("p_occurrence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_reconcile_due_audiences"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare occurrence_id uuid;
declare changed integer := 0;
begin
  for occurrence_id in
    select occurrence.id from public.form_occurrences occurrence
     where occurrence.status in ('scheduled', 'open') order by occurrence.id
  loop
    changed := changed + app_private.form_reconcile_occurrence_audience(occurrence_id);
  end loop;
  return changed;
end;
$$;


ALTER FUNCTION "app_private"."form_reconcile_due_audiences"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_reconcile_occurrence_audience"("p_occurrence_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare occurrence_row public.form_occurrences;
declare response_unit text;
declare changed_count integer := 0;
declare affected integer := 0;
begin
  select occurrence.* into occurrence_row
    from public.form_occurrences occurrence
   where occurrence.id = p_occurrence_id for update;
  if occurrence_row.id is null then
    raise no_data_found using message = 'form occurrence unavailable';
  end if;
  if occurrence_row.status in ('closed', 'cancelled') then return 0; end if;
  select form_row.response_unit into response_unit
    from public.forms form_row where form_row.id = occurrence_row.form_id;

  if response_unit = 'person' then
    update public.form_participations participation
       set eligibility_state = 'ineligible', lost_eligibility_at = coalesce(lost_eligibility_at, now())
     where participation.occurrence_id = occurrence_row.id
       and participation.eligibility_state = 'eligible'
       and not exists (
         select 1 from app_private.form_resolve_person_audience(occurrence_row.application_id) resolved
          where resolved.person_id = participation.person_id
       );
    get diagnostics affected = row_count;
    changed_count := changed_count + affected;

    insert into public.form_participations as current_participation(
      occurrence_id, institution_id, person_id, response_unit_key,
      eligibility_state, lost_eligibility_at
    )
    select occurrence_row.id, occurrence_row.institution_id, resolved.person_id,
           'person:' || resolved.person_id::text, 'eligible', null
      from app_private.form_resolve_person_audience(occurrence_row.application_id) resolved
    on conflict(occurrence_id, response_unit_key) do update set
      person_id = excluded.person_id,
      eligibility_state = 'eligible',
      lost_eligibility_at = null
    where current_participation.eligibility_state <> 'eligible'
       or current_participation.person_id is distinct from excluded.person_id;
    get diagnostics affected = row_count;
    changed_count := changed_count + affected;
  elsif response_unit = 'child_family_context' then
    update public.form_participations participation
       set eligibility_state = 'ineligible', lost_eligibility_at = coalesce(lost_eligibility_at, now())
     where participation.occurrence_id = occurrence_row.id
       and participation.eligibility_state = 'eligible'
       and not exists (
         select 1 from app_private.form_resolve_child_audience(occurrence_row.application_id) resolved
          where resolved.child_context_id = participation.child_context_id
       );
    get diagnostics affected = row_count;
    changed_count := changed_count + affected;

    insert into public.form_participations as current_participation(
      occurrence_id, institution_id, child_context_id, response_unit_key,
      eligibility_state, lost_eligibility_at
    )
    select occurrence_row.id, occurrence_row.institution_id, resolved.child_context_id,
           'child:' || resolved.child_context_id::text, 'eligible', null
      from app_private.form_resolve_child_audience(occurrence_row.application_id) resolved
    on conflict(occurrence_id, response_unit_key) do update set
      child_context_id = excluded.child_context_id,
      eligibility_state = 'eligible',
      lost_eligibility_at = null
    where current_participation.eligibility_state <> 'eligible'
       or current_participation.child_context_id is distinct from excluded.child_context_id;
    get diagnostics affected = row_count;
    changed_count := changed_count + affected;
  else
    raise check_violation using message = 'unsupported form response unit';
  end if;

  delete from public.form_participation_responders responder
   using public.form_participations participation
   where responder.participation_id = participation.id
     and participation.occurrence_id = occurrence_row.id;

  insert into public.form_participation_responders(participation_id, person_id, institution_id)
  select distinct participation.id, guardian.guardian_person_id, occurrence_row.institution_id
    from public.form_participations participation
    join public.child_contexts child_context on child_context.id = participation.child_context_id
    join public.guardian_links guardian
      on guardian.child_person_id = child_context.child_person_id
     and guardian.status = 'active' and guardian.revoked_at is null
    join public.guardian_context_permissions permission
      on permission.guardian_link_id = guardian.id
     and permission.child_context_id = child_context.id
     and permission.status = 'active' and permission.can_view
     and (permission.starts_at is null or permission.starts_at <= now())
     and (permission.expires_at is null or permission.expires_at > now())
   where participation.occurrence_id = occurrence_row.id
     and participation.eligibility_state = 'eligible'
  on conflict(participation_id, person_id) do nothing;

  perform app_private.form_rebuild_occurrence_metrics(occurrence_row.id);
  return changed_count;
end;
$$;


ALTER FUNCTION "app_private"."form_reconcile_occurrence_audience"("p_occurrence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_redeem_file_job_download"("p_download_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  with consumed as (
    update app_private.form_file_download_tokens token_row
       set consumed_at = now()
     where token_row.token_hash = encode(
       extensions.digest(p_download_token::text, 'sha256'),
       'hex'
     )
       and token_row.consumed_at is null
       and token_row.expires_at > now()
     returning token_row.file_job_id, token_row.actor_person_id
  )
  select jsonb_build_object(
    'job_id', job.id,
    'storage_path', job.artifact_path,
    'export_kind', job.export_kind,
    'expires_at', job.expires_at
  )
    into result
    from consumed
    join public.form_file_jobs job
      on job.id = consumed.file_job_id
     and job.requested_by_person_id = consumed.actor_person_id
    join public.forms form_row
      on form_row.id = job.form_id
     and form_row.institution_id = job.institution_id
   where job.state in ('succeeded','partial')
     and job.expires_at > now()
     and job.artifact_path is not null
     and app_private.form_actor_has_export_permission(
       consumed.actor_person_id, job.export_kind
     );
  return result;
end;
$$;


ALTER FUNCTION "app_private"."form_redeem_file_job_download"("p_download_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_redeem_media_read_r2_v1"("p_read_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare token_row app_private.form_media_read_tokens; descriptor jsonb;
  ctx app_private.superadmin_internal_context; token_digest text; error_code text;
  correlation uuid:=gen_random_uuid();
begin
  if current_setting('transaction_isolation')<>'read committed' then
    raise invalid_parameter_value using message='forms_media_read_isolation_invalid';
  end if;
  if p_read_token is null or p_read_token !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then return null; end if;
  token_digest:=encode(extensions.digest(convert_to(lower(p_read_token),'UTF8'),'sha256'),'hex');
  -- Consume before the recoverable authorization block. Denial never revives
  -- the capability; concurrent replay waits and then sees no unconsumed row.
  update app_private.form_media_read_tokens set consumed_at=clock_timestamp()
    where token_hash=token_digest and consumed_at is null returning * into token_row;
  if token_row.id is null then return null; end if;
  begin
    if token_row.expires_at<=clock_timestamp() then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
    ctx:=app_private.forms_media_read_context_v1(token_row.actor_internal_identity_id,token_row.actor_auth_link_id,
      token_row.actor_membership_id,token_row.actor_auth_session_id,token_row.actor_scope_kind,token_row.actor_scope_institution_id);
    descriptor:=app_private.forms_answer_media_descriptor_v1(token_row.asset_id,token_row.rendition,
      ctx.scope_kind,ctx.scope_institution_id,token_row.response_id);
    if row((descriptor->>'asset_id')::uuid,(descriptor->>'media_asset_id')::uuid,(descriptor->>'response_id')::uuid,
      (descriptor->>'institution_id')::uuid,(descriptor->>'form_id')::uuid,(descriptor->>'form_version_id')::uuid,(descriptor->>'item_id')::uuid)
      is distinct from row(token_row.asset_id,token_row.media_asset_id,token_row.response_id,token_row.institution_id,
        token_row.form_id,token_row.form_version_id,token_row.item_id) then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    ctx:=app_private.forms_media_read_context_v1(token_row.actor_internal_identity_id,token_row.actor_auth_link_id,
      token_row.actor_membership_id,token_row.actor_auth_session_id,token_row.actor_scope_kind,token_row.actor_scope_institution_id);
    if token_row.expires_at<=clock_timestamp() then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
  exception when others then
    get stacked diagnostics error_code=pg_exception_detail;
    error_code:=app_private.superadmin_internal_error_envelope(error_code,correlation)#>>'{error,code}';
  end;
  -- Outside the catch: denial consumption and its audit commit together.
  perform app_private.audit_append_superadmin_internal(token_row.actor_internal_identity_id,token_row.actor_auth_link_id,
    token_row.actor_membership_id,token_row.actor_auth_session_id,'forms.responses.read',token_row.actor_aal,
    'superadmin.forms.media.read.redeem',case when error_code is null then 'success'::public.audit_outcome else 'denied'::public.audit_outcome end,
    error_code,correlation,token_row.institution_id,'form_asset',token_row.asset_id);
  if error_code is not null then return null; end if;
  return (descriptor-array['response_id','form_version_id','item_id'])||jsonb_build_object('expires_at',token_row.expires_at);
end;
$_$;


ALTER FUNCTION "app_private"."form_redeem_media_read_r2_v1"("p_read_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_redeem_xlsx_download_r2_v1"("p_download_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare token_row app_private.form_file_download_tokens; job public.form_file_jobs; asset public.media_assets;
  ctx app_private.superadmin_internal_context; target_job uuid; token_digest text;
  error_code text; correlation uuid:=gen_random_uuid();
begin
  if current_setting('transaction_isolation')<>'read committed' then
    raise invalid_parameter_value using message='forms_xlsx_isolation_invalid';
  end if;
  token_digest:=encode(extensions.digest(convert_to(p_download_token::text,'UTF8'),'sha256'),'hex');
  select file_job_id into target_job from app_private.form_file_download_tokens
    where token_hash=token_digest and actor_internal_identity_id is not null and consumed_at is null;
  if target_job is null then return null; end if;
  -- Same lock order as issue: job before token. A consumed/denied ticket is
  -- committed as consumed even if the actor lost permission after issue.
  select * into job from public.form_file_jobs where id=target_job for update;
  update app_private.form_file_download_tokens set consumed_at=clock_timestamp()
    where token_hash=token_digest and file_job_id=job.id and consumed_at is null
      and actor_internal_identity_id is not null and expires_at>clock_timestamp()
    returning * into token_row;
  if token_row.id is null then return null; end if;
  begin
    ctx:=app_private.forms_xlsx_context_from_session_v1(token_row.actor_internal_identity_id,token_row.actor_auth_link_id,
      token_row.actor_membership_id,token_row.actor_auth_session_id,token_row.actor_scope_kind,token_row.actor_scope_institution_id);
    select * into asset from public.media_assets where id=token_row.media_asset_id for share;
    if job.artifact_provider<>'r2' or job.export_kind<>'xlsx' or job.state<>'succeeded'
      or job.expires_at<=clock_timestamp() or token_row.expires_at<=clock_timestamp()
      or job.requested_by_internal_identity_id is distinct from ctx.internal_identity_id
      or (ctx.scope_kind='institution' and job.institution_id is distinct from ctx.scope_institution_id)
      or job.artifact_media_asset_id is distinct from asset.id or asset.status is distinct from 'ready'
      or asset.catalog_kind is distinct from 'form-xlsx'
      or row(asset.export_file_job_id,asset.form_id,asset.institution_id,asset.expires_at)
        is distinct from row(job.id,job.form_id,job.institution_id,job.expires_at)
      or not exists(select 1 from public.forms f join public.institutions i on i.id=f.institution_id
        where f.id=job.form_id and f.institution_id=job.institution_id and i.deleted_at is null)
    then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
    -- Locks above may wait; refresh the actor again before emitting metadata.
    ctx:=app_private.forms_xlsx_context_from_session_v1(token_row.actor_internal_identity_id,token_row.actor_auth_link_id,
      token_row.actor_membership_id,token_row.actor_auth_session_id,token_row.actor_scope_kind,token_row.actor_scope_institution_id);
    if job.expires_at<=clock_timestamp() or token_row.expires_at<=clock_timestamp() then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
  exception when insufficient_privilege then
    get stacked diagnostics error_code=pg_exception_detail;
    error_code:=app_private.superadmin_internal_error_envelope(error_code,correlation)#>>'{error,code}';
  end;
  perform app_private.audit_append_superadmin_internal(token_row.actor_internal_identity_id,token_row.actor_auth_link_id,
    token_row.actor_membership_id,token_row.actor_auth_session_id,'forms.responses.export',token_row.actor_aal,
    'superadmin.forms.export.download.redeem',case when error_code is null then 'success'::public.audit_outcome else 'denied'::public.audit_outcome end,
    error_code,correlation,job.institution_id,'form_file_job',job.id);
  if error_code is not null then return null; end if;
  return jsonb_build_object('job_id',job.id,'institution_id',job.institution_id,'asset_id',asset.id,
    'provider','r2','bucket',asset.bucket_id,'export_kind','xlsx','purpose',asset.media_purpose,
    'state',asset.status,'object_key',asset.object_key,'expires_at',least(job.expires_at,token_row.expires_at));
end;
$$;


ALTER FUNCTION "app_private"."form_redeem_xlsx_download_r2_v1"("p_download_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_remove_schedule"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.manage_applications');
declare schedule_row public.form_schedules;
declare replay jsonb;
begin
  perform app_private.form_assert_payload_keys(p_payload, array['schedule_id'], 'remove form schedule');
  perform app_private.superadmin_form_lock_legacy_resource_v2((select a.form_id from public.form_schedules s join public.form_applications a on a.id=s.application_id where s.id=(p_payload ->> 'schedule_id')::uuid));
  replay := app_private.form_begin_command(p_request_id, actor, 'form_remove_schedule', p_expected_version, p_payload);
  if replay is not null then return replay; end if;
  select * into schedule_row from public.form_schedules
   where id = (p_payload ->> 'schedule_id')::uuid for update;
  if schedule_row.id is null then raise no_data_found using message = 'form schedule unavailable'; end if;
  if schedule_row.status <> 'active' then raise no_data_found using message = 'form schedule unavailable'; end if;
  if schedule_row.management_version <> p_expected_version then
    raise serialization_failure using message = 'expected_version mismatch';
  end if;
  update public.form_schedules
     set status = 'archived', management_version = management_version + 1, updated_at = now()
   where id = schedule_row.id;
  update public.form_occurrences set status = 'cancelled'
   where schedule_id = schedule_row.id and status = 'scheduled';
  return app_private.form_complete_command(
    p_request_id, app_private.form_application_projection(schedule_row.application_id)
  );
end;
$$;


ALTER FUNCTION "app_private"."form_remove_schedule"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_replace_response_answers"("p_response" "public"."form_responses", "p_answers" "jsonb", "p_edit_secret" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare answer_json jsonb;
declare option_id_text text;
declare asset_id_text text;
declare inserted_answer_id uuid;
declare item_row public.form_items;
declare answer_kind text;
declare answer_count integer;
declare configured_min numeric;
declare configured_max numeric;
declare configured_date_min date;
declare configured_date_max date;
begin
  if jsonb_typeof(p_answers) <> 'array' or jsonb_array_length(p_answers) > 200 then
    raise invalid_parameter_value using message = 'answers must be an array with at most 200 items';
  end if;
  delete from public.form_answers where response_id = p_response.id;
  for answer_json in select value from jsonb_array_elements(p_answers) loop
    perform app_private.form_assert_payload_keys(
      answer_json,
      array[
        'item_id','kind','text_value','integer_value','decimal_value','money_minor_units',
        'date_value','yes_no_value','scale_value','option_ids','asset_ids'
      ],
      'form answer'
    );
    select * into item_row
      from public.form_items
     where id = (answer_json ->> 'item_id')::uuid
       and form_version_id = p_response.form_version_id;
    if item_row.id is null or item_row.kind = 'information' then
      raise invalid_parameter_value using message = 'answer item unavailable';
    end if;
    answer_kind := answer_json ->> 'kind';
    if answer_kind <> item_row.kind then
      raise invalid_parameter_value using message = 'answer kind mismatch';
    end if;
    if answer_kind = 'short_text'
       and char_length(coalesce(answer_json ->> 'text_value', ''))
           > coalesce((item_row.config_jsonb ->> 'max_length')::integer, 1000) then
      raise check_violation using message = 'short text answer exceeds maximum length';
    elsif answer_kind in ('integer', 'decimal', 'money') then
      configured_min := (item_row.config_jsonb ->> 'min_value')::numeric;
      configured_max := (item_row.config_jsonb ->> 'max_value')::numeric;
      if (answer_kind = 'integer' and (
            (answer_json ->> 'integer_value')::numeric < coalesce(configured_min, '-Infinity'::numeric)
            or (answer_json ->> 'integer_value')::numeric > coalesce(configured_max, 'Infinity'::numeric)
          )) or (answer_kind = 'decimal' and (
            (answer_json ->> 'decimal_value')::numeric < coalesce(configured_min, '-Infinity'::numeric)
            or (answer_json ->> 'decimal_value')::numeric > coalesce(configured_max, 'Infinity'::numeric)
          )) or (answer_kind = 'money' and (
            (answer_json ->> 'money_minor_units')::numeric < coalesce(configured_min, '-Infinity'::numeric)
            or (answer_json ->> 'money_minor_units')::numeric > coalesce(configured_max, 'Infinity'::numeric)
          )) then
        raise check_violation using message = 'numeric form answer is out of range';
      end if;
    elsif answer_kind = 'date' then
      configured_date_min := (item_row.config_jsonb ->> 'min_value')::date;
      configured_date_max := (item_row.config_jsonb ->> 'max_value')::date;
      if (answer_json ->> 'date_value')::date < coalesce(configured_date_min, '-infinity'::date)
         or (answer_json ->> 'date_value')::date > coalesce(configured_date_max, 'infinity'::date) then
        raise check_violation using message = 'date form answer is out of range';
      end if;
    elsif answer_kind = 'scale' and (
      (answer_json ->> 'scale_value')::integer < coalesce((item_row.config_jsonb ->> 'scale_min')::integer, 1)
      or (answer_json ->> 'scale_value')::integer > coalesce((item_row.config_jsonb ->> 'scale_max')::integer, 10)
    ) then
      raise check_violation using message = 'scale form answer is out of range';
    end if;
    insert into public.form_answers(
      response_id, form_version_id, item_id, answer_kind, text_value, integer_value,
      decimal_value, money_minor_units, date_value, yes_no_value, scale_value
    ) values (
      p_response.id, p_response.form_version_id, item_row.id, answer_kind,
      answer_json ->> 'text_value', (answer_json ->> 'integer_value')::bigint,
      (answer_json ->> 'decimal_value')::numeric, (answer_json ->> 'money_minor_units')::bigint,
      (answer_json ->> 'date_value')::date, (answer_json ->> 'yes_no_value')::boolean,
      (answer_json ->> 'scale_value')::integer
    ) returning id into inserted_answer_id;

    if answer_kind in ('single_choice', 'multiple_choice', 'location') then
      if jsonb_typeof(coalesce(answer_json -> 'option_ids', '[]'::jsonb)) <> 'array'
         or exists(
           select 1 from jsonb_array_elements(answer_json -> 'option_ids') option_id
            where jsonb_typeof(option_id) <> 'string'
         ) then
        raise invalid_parameter_value using message = 'invalid answer options';
      end if;
      answer_count := jsonb_array_length(coalesce(answer_json -> 'option_ids', '[]'::jsonb));
      if answer_count <> (select count(distinct option_id)
                            from jsonb_array_elements_text(answer_json -> 'option_ids') option_id) then
        raise invalid_parameter_value using message = 'form answer option ids must be unique';
      end if;
      if (answer_kind in ('single_choice', 'location') and answer_count <> 1)
         or (answer_kind = 'multiple_choice' and answer_count not between
           coalesce((item_row.config_jsonb ->> 'min_selections')::integer, 1)
           and coalesce((item_row.config_jsonb ->> 'max_selections')::integer, 50)) then
        raise check_violation using message = 'multiple choice selection count is out of range';
      end if;
      for option_id_text in select value #>> '{}' from jsonb_array_elements(answer_json -> 'option_ids') loop
        if not exists(
          select 1 from public.form_question_options
          where id = option_id_text::uuid and item_id = item_row.id
        ) then
          raise invalid_parameter_value using message = 'answer option unavailable';
        end if;
        -- P16, opcao 2: o Local do snapshot precisa continuar ativo no catalogo
        -- da instituicao. Sem alternativa valida numa pergunta obrigatoria, o
        -- bloqueio e explicito em vez de forcar uma escolha invalida.
        if answer_kind = 'location'
           and not app_private.form_location_option_available_v1(option_id_text::uuid) then
          if item_row.is_required and not exists (
            select 1 from public.form_question_options candidate
             where candidate.item_id = item_row.id
               and app_private.form_location_option_available_v1(candidate.id)
          ) then
            raise check_violation using message = 'required location question has no available location',
              detail = 'FORMS_LOCATION_NO_AVAILABLE_OPTION';
          end if;
          raise check_violation using message = 'form location answer requires a current location',
            detail = 'FORMS_LOCATION_REVOKED';
        end if;
        insert into public.form_answer_options(answer_id, option_id, position)
        values (
          inserted_answer_id,
          option_id_text::uuid,
          (select count(*) from public.form_answer_options where form_answer_options.answer_id = inserted_answer_id)
        );
      end loop;
    elsif answer_kind in ('photo', 'gallery') then
      if jsonb_typeof(coalesce(answer_json -> 'asset_ids', '[]'::jsonb)) <> 'array'
         or exists(
           select 1 from jsonb_array_elements(answer_json -> 'asset_ids') asset_id
            where jsonb_typeof(asset_id) <> 'string'
         ) then
        raise invalid_parameter_value using message = 'invalid answer assets';
      end if;
      answer_count := jsonb_array_length(coalesce(answer_json -> 'asset_ids', '[]'::jsonb));
      if (answer_kind = 'photo' and answer_count <> 1)
         or (answer_kind = 'gallery' and answer_count not between
           coalesce((item_row.config_jsonb ->> 'min_images')::integer, 1)
           and coalesce((item_row.config_jsonb ->> 'max_images')::integer, 5)) then
        raise check_violation using message = 'form answer asset count is out of range';
      end if;
      for asset_id_text in select value #>> '{}' from jsonb_array_elements(answer_json -> 'asset_ids') loop
        if not exists(
          select 1 from public.form_assets asset
          where asset.id = asset_id_text::uuid and asset.item_id = item_row.id
            and asset.occurrence_id = p_response.occurrence_id and asset.state = 'finalized'
            and (
              (p_response.identity_mode = 'identified'
                and asset.prepared_by_person_id = p_response.respondent_person_id)
              or (p_response.identity_mode = 'anonymous'
                and asset.prepared_by_person_id is null
                and app_private.form_verify_anonymous_edit_secret(
                  p_edit_secret, asset.anonymous_upload_secret_hash
                ))
            )
        ) then
          raise invalid_parameter_value using message = 'answer asset unavailable';
        end if;
        insert into public.form_answer_assets(answer_id, asset_id, position)
        values (
          inserted_answer_id,
          asset_id_text::uuid,
          (select count(*) from public.form_answer_assets where form_answer_assets.answer_id = inserted_answer_id)
        );
      end loop;
    end if;
  end loop;

  if exists (
    select 1
      from public.form_answers target_answer
     where target_answer.response_id = p_response.id
       and exists (
         select 1 from public.form_question_conditions condition_row
         where condition_row.target_item_id = target_answer.item_id
       )
       and not exists (
         select 1
           from public.form_question_conditions condition_row
           join public.form_answers source_answer
             on source_answer.response_id = p_response.id
            and source_answer.item_id = condition_row.source_item_id
          where condition_row.target_item_id = target_answer.item_id
            and (
              (condition_row.condition_kind = 'yes_no'
               and source_answer.yes_no_value = condition_row.expected_yes_no)
              or (condition_row.condition_kind = 'choice' and exists(
                select 1 from public.form_answer_options selected_option
                where selected_option.answer_id = source_answer.id
                  and selected_option.option_id = condition_row.source_option_id
              ))
            )
       )
  ) then
    raise check_violation using message = 'hidden form answers are not accepted';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_replace_response_answers"("p_response" "public"."form_responses", "p_answers" "jsonb", "p_edit_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_replace_working_definition"("p_version_id" "uuid", "p_sections" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  section_json jsonb;
  item_json jsonb;
  option_json jsonb;
  condition_json jsonb;
  source_section_id text;
  source_item_id text;
  source_option_id text;
  stable_item_id uuid;
  section_ids jsonb := '{}'::jsonb;
  item_ids jsonb := '{}'::jsonb;
  option_ids jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(p_sections) <> 'array' then
    raise invalid_parameter_value using message = 'sections must be an array';
  end if;
  if jsonb_array_length(p_sections) > 20 then
    raise check_violation using message = 'maximum 20 form sections';
  end if;

  -- Valida e resolve IDs antes do delete. Somente um UUID que ja pertence ao
  -- mesmo working version e reutilizado; IDs novos, publicados ou estrangeiros
  -- recebem UUID novo.
  for section_json in select value from jsonb_array_elements(p_sections) loop
    perform app_private.form_assert_payload_keys(
      section_json,
      array['id','title','description','position','items'],
      'form section'
    );
    source_section_id := nullif(section_json ->> 'id', '');
    if source_section_id is null or section_ids ? source_section_id then
      raise invalid_parameter_value using message = 'unique section id required';
    end if;
    section_ids := section_ids || jsonb_build_object(source_section_id, gen_random_uuid()::text);
    if jsonb_typeof(section_json -> 'items') <> 'array' then
      raise invalid_parameter_value using message = 'section items must be an array';
    end if;
    for item_json in select value from jsonb_array_elements(section_json -> 'items') loop
      perform app_private.form_assert_payload_keys(
        item_json,
        array['id','kind','label','help_text','position','is_required','config','options','conditions'],
        'form item'
      );
      source_item_id := nullif(item_json ->> 'id', '');
      if source_item_id is null or item_ids ? source_item_id then
        raise invalid_parameter_value using message = 'unique item id required';
      end if;
      stable_item_id := null;
      if source_item_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        select item.id into stable_item_id
        from public.form_items item
        where item.id = source_item_id::uuid
          and item.form_version_id = p_version_id;
      end if;
      item_ids := item_ids || jsonb_build_object(
        source_item_id,
        coalesce(stable_item_id, gen_random_uuid())::text
      );
      if jsonb_typeof(coalesce(item_json -> 'options', '[]'::jsonb)) <> 'array'
         or jsonb_typeof(coalesce(item_json -> 'conditions', '[]'::jsonb)) <> 'array' then
        raise invalid_parameter_value using message = 'item options and conditions must be arrays';
      end if;
      if jsonb_array_length(coalesce(item_json -> 'options', '[]'::jsonb)) > 50 then
        raise check_violation using message = 'maximum 50 form options per item';
      end if;
      for option_json in select value from jsonb_array_elements(coalesce(item_json -> 'options', '[]'::jsonb)) loop
        perform app_private.form_assert_payload_keys(
          option_json, array['id','label','position'], 'form option'
        );
        source_option_id := nullif(option_json ->> 'id', '');
        if source_option_id is null or option_ids ? source_option_id then
          raise invalid_parameter_value using message = 'unique option id required';
        end if;
        option_ids := option_ids || jsonb_build_object(source_option_id, gen_random_uuid()::text);
      end loop;
    end loop;
  end loop;

  if (select count(*) from jsonb_object_keys(item_ids)) > 200 then
    raise check_violation using message = 'maximum 200 form items';
  end if;

  set constraints public.media_bindings_item_id_fkey deferred;
  delete from public.form_sections where form_version_id = p_version_id;

  for section_json in select value from jsonb_array_elements(p_sections) loop
    source_section_id := section_json ->> 'id';
    insert into public.form_sections(id, form_version_id, title, description, position)
    values (
      (section_ids ->> source_section_id)::uuid,
      p_version_id,
      btrim(section_json ->> 'title'),
      nullif(btrim(section_json ->> 'description'), ''),
      (section_json ->> 'position')::integer
    );
    for item_json in select value from jsonb_array_elements(section_json -> 'items') loop
      source_item_id := item_json ->> 'id';
      insert into public.form_items(
        id, form_version_id, section_id, kind, label, help_text, is_required, position, config_jsonb
      ) values (
        (item_ids ->> source_item_id)::uuid,
        p_version_id,
        (section_ids ->> source_section_id)::uuid,
        item_json ->> 'kind',
        btrim(item_json ->> 'label'),
        nullif(btrim(item_json ->> 'help_text'), ''),
        coalesce((item_json ->> 'is_required')::boolean, false),
        (item_json ->> 'position')::integer,
        coalesce(item_json -> 'config', '{}'::jsonb)
      );
      for option_json in select value from jsonb_array_elements(coalesce(item_json -> 'options', '[]'::jsonb)) loop
        source_option_id := option_json ->> 'id';
        insert into public.form_question_options(id, form_version_id, item_id, label, position)
        values (
          (option_ids ->> source_option_id)::uuid,
          p_version_id,
          (item_ids ->> source_item_id)::uuid,
          btrim(option_json ->> 'label'),
          (option_json ->> 'position')::integer
        );
      end loop;
    end loop;
  end loop;

  for section_json in select value from jsonb_array_elements(p_sections) loop
    for item_json in select value from jsonb_array_elements(section_json -> 'items') loop
      source_item_id := item_json ->> 'id';
      for condition_json in select value from jsonb_array_elements(coalesce(item_json -> 'conditions', '[]'::jsonb)) loop
        perform app_private.form_assert_payload_keys(
          condition_json,
          array['source_item_id','kind','expected_yes_no','option_ids'],
          'form condition'
        );
        if not item_ids ? (condition_json ->> 'source_item_id') then
          raise invalid_parameter_value using message = 'condition source item not found';
        end if;
        for source_option_id in
          select value from jsonb_array_elements_text(
            case when condition_json ->> 'kind' = 'choice'
              then condition_json -> 'option_ids' else '[null]'::jsonb end
          )
        loop
          if condition_json ->> 'kind' = 'choice' and not option_ids ? source_option_id then
            raise invalid_parameter_value using message = 'condition source option not found';
          end if;
          insert into public.form_question_conditions(
            form_version_id, target_item_id, source_item_id, condition_kind,
            expected_yes_no, source_option_id
          ) values (
            p_version_id,
            (item_ids ->> source_item_id)::uuid,
            (item_ids ->> (condition_json ->> 'source_item_id'))::uuid,
            condition_json ->> 'kind',
            (condition_json ->> 'expected_yes_no')::boolean,
            case when source_option_id is null then null
                 else (option_ids ->> source_option_id)::uuid end
          );
        end loop;
      end loop;
    end loop;
  end loop;
  perform app_private.validate_form_definition(p_version_id);
  set constraints public.media_bindings_item_id_fkey immediate;
end;
$_$;


ALTER FUNCTION "app_private"."form_replace_working_definition"("p_version_id" "uuid", "p_sections" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_request_export"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb", "p_anonymous_participation" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor(
  case when p_anonymous_participation
       then 'forms.anonymous_participation.export'
       else 'forms.responses.export' end
);
declare form_row public.forms;
declare job_row public.form_file_jobs;
declare replay jsonb;
declare command_name text := case when p_anonymous_participation
  then 'form_request_anonymous_participation_export' else 'form_request_export' end;
begin
  perform app_private.form_assert_payload_keys(
    p_payload, array['form_id','occurrence_id','kind','justification'], 'form export'
  );
  perform app_private.superadmin_form_lock_legacy_resource_v2((p_payload ->> 'form_id')::uuid);
  replay := app_private.form_begin_command(
    p_request_id, actor, command_name, p_expected_version, p_payload
  );
  if replay is not null then return replay; end if;
  select * into form_row from public.forms where id = (p_payload ->> 'form_id')::uuid;
  if form_row.id is null then raise no_data_found using message = 'form unavailable'; end if;
  if form_row.management_version <> p_expected_version then
    raise serialization_failure using message = 'expected_version mismatch';
  end if;
  if p_anonymous_participation then
    perform app_private.form_require_owner(actor, 'forms.anonymous_participation.export');
    if char_length(btrim(coalesce(p_payload ->> 'justification', ''))) < 10 then
      raise invalid_parameter_value using message = 'auditable justification required';
    end if;
  end if;
  insert into public.form_file_jobs(
    institution_id, form_id, occurrence_id, requested_by_person_id, request_id, export_kind,
    manifest_jsonb
  ) values (
    form_row.institution_id, form_row.id, (p_payload ->> 'occurrence_id')::uuid,
    actor, p_request_id,
    case when p_anonymous_participation then 'anonymous_participation' else p_payload ->> 'kind' end,
    case when p_anonymous_participation
         then jsonb_build_object('justification', btrim(p_payload ->> 'justification'))
         else '{}'::jsonb end
  ) returning * into job_row;
  insert into app_private.form_worker_jobs(job_kind, aggregate_id, payload_jsonb)
  values (
    case job_row.export_kind
      when 'csv' then 'export_csv'
      when 'xlsx' then 'export_xlsx'
      when 'zip' then 'export_zip'
      else 'export_anonymous_participation'
    end,
    job_row.id,
    jsonb_build_object('file_job_id', job_row.id)
  );
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id, institution_id,
    outcome, reason, after_json
  ) values (
    actor, auth.jwt() ->> 'aal', command_name, 'form_file_job', job_row.id,
    form_row.institution_id, 'success',
    case when p_anonymous_participation then btrim(p_payload ->> 'justification') else null end,
    jsonb_build_object('form_id', form_row.id, 'export_kind', job_row.export_kind)
  );
  return app_private.form_complete_command(p_request_id, jsonb_build_object(
    'id', job_row.id, 'status', job_row.state, 'progress', job_row.progress,
    'download_path', null, 'error_code', null
  ));
end;
$$;


ALTER FUNCTION "app_private"."form_request_export"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb", "p_anonymous_participation" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_require_owner"("p_actor" "uuid", "p_capability" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not app_private.has_platform_permission(p_capability)
     or not exists(
       select 1
         from public.platform_memberships membership
         join public.platform_roles role_row on role_row.id = membership.role_id
        where membership.person_id = p_actor
          and membership.status = 'active'
          and membership.revoked_at is null
          and role_row.code = 'owner'
     ) then
    raise insufficient_privilege using message = 'Owner role and capability required';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_require_owner"("p_actor" "uuid", "p_capability" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_resolve_child_audience"("p_application_id" "uuid") RETURNS TABLE("child_context_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with application_context as (
    select application.id, application.institution_id
      from public.form_applications application
     where application.id = p_application_id and application.status = 'active'
  ), rules as (
    select rule.*
      from public.form_audience_rules rule
      join application_context context on context.id = rule.application_id
  ), raw_matches as (
    select rule.rule_mode, child_context.id as child_context_id, rule.filter_jsonb
      from rules rule
      join application_context context on true
      join public.child_contexts child_context
        on child_context.institution_id = context.institution_id
       and child_context.status = 'active'
     where rule.rule_kind = 'institution' and rule.target_id = context.institution_id
    union all
    select rule.rule_mode, child_unit.child_context_id, rule.filter_jsonb
      from rules rule
      join public.child_unit_links child_unit
        on child_unit.unit_id = rule.target_id and child_unit.status = 'active'
      join public.child_contexts child_context
        on child_context.id = child_unit.child_context_id and child_context.status = 'active'
     where rule.rule_kind = 'unit'
    union all
    select rule.rule_mode, child_unit.child_context_id, rule.filter_jsonb
      from rules rule
      join public.child_group_links child_group
        on child_group.group_id = rule.target_id and child_group.status = 'active'
       and (child_group.starts_at is null or child_group.starts_at <= now())
       and (child_group.ends_at is null or child_group.ends_at > now())
      join public.child_unit_links child_unit
        on child_unit.id = child_group.child_unit_link_id and child_unit.status = 'active'
     where rule.rule_kind = 'group'
    union all
    select rule.rule_mode, child_unit.child_context_id, rule.filter_jsonb
      from rules rule
      join public.activity_group_links activity_link
        on activity_link.activity_id = rule.target_id and activity_link.status = 'active'
       and activity_link.starts_at <= now()
       and (activity_link.ends_at is null or activity_link.ends_at > now())
      join public.child_group_links child_group
        on child_group.group_id = activity_link.group_id and child_group.status = 'active'
      join public.child_unit_links child_unit
        on child_unit.id = child_group.child_unit_link_id and child_unit.status = 'active'
      left join public.activity_group_participants selected
        on selected.activity_group_link_id = activity_link.id
       and selected.child_group_link_id = child_group.id
       and selected.status = 'active' and selected.removed_at is null
     where rule.rule_kind = 'activity'
       and (activity_link.participation_mode = 'all' or selected.id is not null)
    union all
    select rule.rule_mode, child_context.id, rule.filter_jsonb
      from rules rule
      join application_context context on true
      join public.child_contexts child_context
        on child_context.institution_id = context.institution_id
       and child_context.status = 'active'
     where rule.rule_kind in ('person', 'guardian')
       and (
         child_context.child_person_id = rule.target_id
         or exists (
           select 1 from public.guardian_links guardian
            where guardian.child_person_id = child_context.child_person_id
              and guardian.guardian_person_id = rule.target_id
              and guardian.status = 'active' and guardian.revoked_at is null
         )
       )
  ), filtered as (
    select match.rule_mode, match.child_context_id
      from raw_matches match
      join public.child_contexts child_context on child_context.id = match.child_context_id
     where not (match.filter_jsonb ? 'status')
        or child_context.status::text = match.filter_jsonb ->> 'status'
  )
  select filtered.child_context_id
    from filtered
   group by filtered.child_context_id
  having bool_or(filtered.rule_mode = 'include')
     and not bool_or(filtered.rule_mode = 'exclude');
$$;


ALTER FUNCTION "app_private"."form_resolve_child_audience"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_resolve_person_audience"("p_application_id" "uuid") RETURNS TABLE("person_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with application_context as (
    select application.id, application.institution_id
      from public.form_applications application
     where application.id = p_application_id and application.status = 'active'
  ), rules as (
    select rule.*
      from public.form_audience_rules rule
      join application_context context on context.id = rule.application_id
  ), raw_matches as (
    select rule.rule_mode, membership.person_id, rule.filter_jsonb
      from rules rule
      join application_context context on true
      join public.institution_memberships membership
        on membership.institution_id = context.institution_id
       and membership.status = 'active' and membership.revoked_at is null
     where rule.rule_kind = 'institution' and rule.target_id = context.institution_id
    union all
    select rule.rule_mode, membership.person_id, rule.filter_jsonb
      from rules rule
      join application_context context on true
      join public.institution_memberships membership
        on membership.institution_id = context.institution_id
       and membership.status = 'active' and membership.revoked_at is null
     where rule.rule_kind = 'unit'
       and (
         membership.scope_unit_id = rule.target_id
         or exists (
           select 1 from public.institution_role_assignments assignment
            where assignment.membership_id = membership.id
              and assignment.status = 'active'
              and (assignment.starts_at is null or assignment.starts_at <= now())
              and (assignment.expires_at is null or assignment.expires_at > now())
              and assignment.scope_unit_id = rule.target_id
         )
       )
    union all
    select rule.rule_mode, membership.person_id, rule.filter_jsonb
      from rules rule
      join application_context context on true
      join public.institution_memberships membership
        on membership.institution_id = context.institution_id
       and membership.status = 'active' and membership.revoked_at is null
     where rule.rule_kind = 'group'
       and (
         membership.scope_group_id = rule.target_id
         or exists (
           select 1 from public.institution_role_assignments assignment
            where assignment.membership_id = membership.id
              and assignment.status = 'active'
              and (assignment.starts_at is null or assignment.starts_at <= now())
              and (assignment.expires_at is null or assignment.expires_at > now())
              and assignment.scope_group_id = rule.target_id
         )
       )
    union all
    select rule.rule_mode, assignment.person_id, rule.filter_jsonb
      from rules rule
      join public.activity_group_links activity_link
        on activity_link.activity_id = rule.target_id and activity_link.status = 'active'
      join public.activity_group_assignments assignment
        on assignment.activity_group_link_id = activity_link.id
       and assignment.status = 'active' and assignment.revoked_at is null
     where rule.rule_kind = 'activity'
    union all
    select rule.rule_mode, membership.person_id, rule.filter_jsonb
      from rules rule
      join application_context context on true
      join public.institution_role_assignments assignment
        on assignment.role_id = rule.target_id and assignment.status = 'active'
       and (assignment.starts_at is null or assignment.starts_at <= now())
       and (assignment.expires_at is null or assignment.expires_at > now())
      join public.institution_memberships membership
        on membership.id = assignment.membership_id
       and membership.institution_id = context.institution_id
       and membership.status = 'active' and membership.revoked_at is null
     where rule.rule_kind = 'profile'
    union all
    select rule.rule_mode, rule.target_id, rule.filter_jsonb
      from rules rule
      join application_context context on true
     where rule.rule_kind in ('person', 'guardian', 'teacher', 'employee')
       and (
         exists (
           select 1 from public.institution_memberships membership
            where membership.person_id = rule.target_id
              and membership.institution_id = context.institution_id
              and membership.status = 'active' and membership.revoked_at is null
         )
         or exists (
           select 1
             from public.guardian_links guardian
             join public.child_contexts child_context
               on child_context.child_person_id = guardian.child_person_id
              and child_context.institution_id = context.institution_id
              and child_context.status = 'active'
            where guardian.guardian_person_id = rule.target_id
              and guardian.status = 'active' and guardian.revoked_at is null
         )
       )
  ), filtered as (
    select match.rule_mode, match.person_id
      from raw_matches match
      join public.people person on person.id = match.person_id and person.deleted_at is null
     where (not (match.filter_jsonb ? 'status')
            or person.status::text = match.filter_jsonb ->> 'status')
       and (not (match.filter_jsonb ? 'membership_status') or exists (
         select 1 from public.institution_memberships membership
          join application_context context on context.institution_id = membership.institution_id
         where membership.person_id = match.person_id
           and membership.status::text = match.filter_jsonb ->> 'membership_status'
       ))
       and (not (match.filter_jsonb ? 'profile_codes') or exists (
         select 1
           from public.institution_memberships membership
           join application_context context on context.institution_id = membership.institution_id
           join public.institution_role_assignments assignment on assignment.membership_id = membership.id
           join public.institution_roles role_row on role_row.id = assignment.role_id
          where membership.person_id = match.person_id
            and assignment.status = 'active'
            and role_row.code in (
              select jsonb_array_elements_text(match.filter_jsonb -> 'profile_codes')
            )
       ))
  )
  select filtered.person_id
    from filtered
   group by filtered.person_id
  having bool_or(filtered.rule_mode = 'include')
     and not bool_or(filtered.rule_mode = 'exclude');
$$;


ALTER FUNCTION "app_private"."form_resolve_person_audience"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_response_draft_projection"("p_response_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', response.id,
    'occurrence_id', response.occurrence_id,
    'status', response.status,
    'management_version', response.management_version,
    'identity_mode', response.identity_mode,
    'answers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_id', answer.item_id,
        'kind', answer.answer_kind,
        'text_value', answer.text_value,
        'integer_value', answer.integer_value,
        'decimal_value', answer.decimal_value,
        'money_minor_units', answer.money_minor_units,
        'date_value', answer.date_value,
        'yes_no_value', answer.yes_no_value,
        'option_ids', coalesce((
          select jsonb_agg(selected.option_id order by selected.position)
            from public.form_answer_options selected where selected.answer_id = answer.id
        ), '[]'::jsonb),
        'scale_value', answer.scale_value,
        'asset_ids', coalesce((
          select jsonb_agg(asset.asset_id order by asset.position)
            from public.form_answer_assets asset where asset.answer_id = answer.id
        ), '[]'::jsonb)
      ) order by item.position)
        from public.form_answers answer
        join public.form_items item on item.id = answer.item_id
       where answer.response_id = response.id
    ), '[]'::jsonb)
  ) from public.form_responses response where response.id = p_response_id;
$$;


ALTER FUNCTION "app_private"."form_response_draft_projection"("p_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_run_periodic_maintenance"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare generated integer;
declare reconciled integer;
begin
  generated := app_private.form_generate_due_occurrences(90);
  reconciled := app_private.form_reconcile_due_audiences();
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('coelo-forms-cleanup-uploads'));
  if not exists(
    select 1 from app_private.form_worker_jobs
     where job_kind = 'cleanup_uploads' and state in ('pending', 'processing')
  ) then
    insert into app_private.form_worker_jobs(job_kind) values ('cleanup_uploads');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('coelo-forms-cleanup-artifacts'));
  if not exists(
    select 1 from app_private.form_worker_jobs
     where job_kind = 'cleanup_artifacts' and state in ('pending', 'processing')
  ) then
    insert into app_private.form_worker_jobs(job_kind) values ('cleanup_artifacts');
  end if;
  return jsonb_build_object(
    'generated_occurrences', generated,
    'reconciled_participations', reconciled
  );
end;
$$;


ALTER FUNCTION "app_private"."form_run_periodic_maintenance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_save_application"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.manage_applications');
declare application_row public.form_applications;
declare rule_json jsonb;
declare replay jsonb;
declare application_id uuid := coalesce((p_payload ->> 'id')::uuid, gen_random_uuid());
begin
  perform app_private.form_assert_payload_keys(
    p_payload, array['id','form_id','institution_id','name','status','opens_for_days','rules'],
    'form application'
  );
  perform app_private.form_assert_application_payload_limits(p_payload);
  perform app_private.superadmin_form_lock_legacy_resource_v2((p_payload ->> 'form_id')::uuid);
  perform app_private.superadmin_form_lock_legacy_resource_v2((select a.form_id from public.form_applications a where a.id=application_id));
  replay := app_private.form_begin_command(p_request_id, actor, 'form_save_application', p_expected_version, p_payload);
  if replay is not null then return replay; end if;
  perform pg_advisory_xact_lock(hashtextextended(application_id::text, 11));
  select * into application_row from public.form_applications where id = application_id for update;
  if application_row.id is null then
    if p_expected_version <> 0 then raise serialization_failure using message = 'expected_version mismatch'; end if;
    insert into public.form_applications(
      id, form_id, institution_id, name, status, opens_for_days, created_by_person_id
    ) values (
      application_id, (p_payload ->> 'form_id')::uuid, (p_payload ->> 'institution_id')::uuid,
      btrim(p_payload ->> 'name'), coalesce(p_payload ->> 'status', 'active'),
      coalesce((p_payload ->> 'opens_for_days')::integer, 7), actor
    ) returning * into application_row;
  else
    if application_row.management_version <> p_expected_version then
      raise serialization_failure using message = 'expected_version mismatch';
    end if;
    update public.form_applications set name = btrim(p_payload ->> 'name'),
      status = coalesce(p_payload ->> 'status', status),
      opens_for_days = coalesce((p_payload ->> 'opens_for_days')::integer, opens_for_days),
      management_version = management_version + 1, updated_at = now()
    where id = application_id returning * into application_row;
  end if;
  delete from public.form_audience_rules audience_rule where audience_rule.application_id = application_row.id;
  for rule_json in select value from jsonb_array_elements(p_payload -> 'rules') loop
    perform app_private.form_assert_payload_keys(
      rule_json, array['kind','mode','target_id','filter','position'], 'form audience rule'
    );
    insert into public.form_audience_rules(
      application_id, institution_id, rule_kind, rule_mode, target_id, filter_jsonb, position
    ) values (
      application_row.id, application_row.institution_id, rule_json ->> 'kind', rule_json ->> 'mode',
      (rule_json ->> 'target_id')::uuid, coalesce(rule_json -> 'filter', '{}'::jsonb),
      (rule_json ->> 'position')::integer
    );
  end loop;
  return app_private.form_complete_command(
    p_request_id, app_private.form_application_projection(application_row.id)
  );
end;
$$;


ALTER FUNCTION "app_private"."form_save_application"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_save_draft"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  target_form_id uuid;
  requested_institution_id uuid;
  authorization_institution_id uuid;
  form_row public.forms;
  version_id uuid;
  next_version_number integer;
  replay jsonb;
  result jsonb;
  before_state jsonb;
begin
  actor := app_private.current_person_id();
  if actor is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  perform app_private.form_assert_payload_keys(
    p_payload,
    array['id','institution_id','kind','identity_mode','response_unit','title','description','sections'],
    'form draft'
  );
  target_form_id := coalesce((p_payload ->> 'id')::uuid, gen_random_uuid());
  requested_institution_id := (p_payload ->> 'institution_id')::uuid;
  select existing.institution_id into authorization_institution_id
    from public.forms existing where existing.id = target_form_id;
  authorization_institution_id := coalesce(authorization_institution_id, requested_institution_id);
  if not app_private.has_platform_permission('forms.manage', authorization_institution_id) then
    raise insufficient_privilege using message = 'forms.manage required';
  end if;

  perform app_private.superadmin_form_lock_legacy_resource_v2(target_form_id);
  replay := app_private.form_begin_command(
    p_request_id, actor, 'form_save_draft', p_expected_version, p_payload
  );
  if replay is not null then return replay; end if;

  perform pg_advisory_xact_lock(hashtextextended(target_form_id::text, 0));
  select * into form_row from public.forms where id = target_form_id for update;
  perform app_private.superadmin_form_assert_legacy_resource_v2(form_row.id);
  before_state := case when form_row.id is null then null else app_private.form_definition_projection(target_form_id) end;
  if form_row.id is null then
    if p_expected_version <> 0 then
      raise serialization_failure using message = 'expected_version mismatch';
    end if;
    insert into public.forms(
      id, institution_id, kind, identity_mode, response_unit, title, description,
      created_by_person_id, updated_by_person_id
    ) values (
      target_form_id, requested_institution_id, p_payload ->> 'kind',
      p_payload ->> 'identity_mode', p_payload ->> 'response_unit',
      btrim(p_payload ->> 'title'), nullif(btrim(p_payload ->> 'description'), ''),
      actor, actor
    ) returning * into form_row;
    next_version_number := 1;
    insert into public.form_versions(form_id, version_number, created_by_person_id)
    values (target_form_id, next_version_number, actor)
    returning id into version_id;
    update public.forms set working_version_id = version_id where id = target_form_id;
  else
    if form_row.management_version <> p_expected_version then
      raise serialization_failure using message = 'expected_version mismatch';
    end if;
    if form_row.institution_id <> requested_institution_id then
      raise check_violation using message = 'use form_copy_or_move for institution changes';
    end if;
    if form_row.first_published_at is not null
       and form_row.identity_mode <> p_payload ->> 'identity_mode' then
      raise check_violation using message = 'identity mode is immutable after first publication';
    end if;
    version_id := form_row.working_version_id;
    if version_id is null then
      select coalesce(max(fv.version_number), 0) + 1 into next_version_number
        from public.form_versions fv where fv.form_id = form_row.id;
      insert into public.form_versions(form_id, version_number, created_by_person_id)
      values (target_form_id, next_version_number, actor)
      returning id into version_id;
    end if;
    update public.forms
       set institution_id = requested_institution_id,
           kind = p_payload ->> 'kind',
           identity_mode = p_payload ->> 'identity_mode',
           response_unit = p_payload ->> 'response_unit',
           title = btrim(p_payload ->> 'title'),
           description = nullif(btrim(p_payload ->> 'description'), ''),
           working_version_id = version_id,
           management_version = management_version + 1,
           updated_by_person_id = actor,
           updated_at = now()
     where id = target_form_id;
  end if;

  perform app_private.form_replace_working_definition(version_id, p_payload -> 'sections');
  result := app_private.form_definition_projection(target_form_id);
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id, institution_id,
    outcome, before_json, after_json
  ) values (
    actor, auth.jwt() ->> 'aal', 'forms.draft.save', 'form', target_form_id,
    requested_institution_id, 'success', before_state,
    jsonb_build_object('management_version', result -> 'management_version')
  );
  return app_private.form_complete_command(p_request_id, result);
end;
$$;


ALTER FUNCTION "app_private"."form_save_draft"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_save_schedule"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.manage_applications');
declare schedule_row public.form_schedules;
declare replay jsonb;
declare reminder_json jsonb;
declare target_schedule_id uuid := coalesce((p_payload ->> 'schedule_id')::uuid, gen_random_uuid());
declare target_application_id uuid := (p_payload ->> 'application_id')::uuid;
begin
  perform app_private.form_assert_payload_keys(
    p_payload,
    array['schedule_id','application_id','time_zone','starts_at_local','recurrence_kind','interval','weekdays',
          'monthly_day','monthly_last_day','end_kind','ends_on','occurrence_count','reminders'],
    'form schedule'
  );
  perform app_private.form_assert_schedule_payload_limits(p_payload);
  if not exists(select 1 from pg_timezone_names where name = p_payload ->> 'time_zone') then
    raise invalid_parameter_value using message = 'unknown IANA timezone';
  end if;
  perform app_private.superadmin_form_lock_legacy_resource_v2((select a.form_id from public.form_applications a where a.id=target_application_id));
  perform app_private.superadmin_form_lock_legacy_resource_v2((select a.form_id from public.form_schedules s join public.form_applications a on a.id=s.application_id where s.id=target_schedule_id));
  replay := app_private.form_begin_command(p_request_id, actor, 'form_save_schedule', p_expected_version, p_payload);
  if replay is not null then return replay; end if;
  perform pg_advisory_xact_lock(hashtextextended(target_application_id::text, 12));
  select * into schedule_row from public.form_schedules
   where id = target_schedule_id for update;
  if schedule_row.id is not null and schedule_row.application_id <> target_application_id then
    raise no_data_found using message = 'form schedule unavailable';
  end if;
  if schedule_row.id is not null and schedule_row.status <> 'active' then
    raise no_data_found using message = 'form schedule unavailable';
  end if;
  if schedule_row.id is null and p_expected_version <> 0 then
    raise serialization_failure using message = 'expected_version mismatch';
  elsif schedule_row.id is not null and schedule_row.management_version <> p_expected_version then
    raise serialization_failure using message = 'expected_version mismatch';
  end if;
  perform app_private.form_assert_schedule_capacity(target_application_id, target_schedule_id);
  insert into public.form_schedules(
    id, application_id, time_zone, starts_at_local, recurrence_kind, interval_value, weekdays,
    monthly_day, monthly_last_day, end_kind, ends_on, occurrence_count
  ) values (
    target_schedule_id, target_application_id, p_payload ->> 'time_zone',
    (p_payload ->> 'starts_at_local')::timestamp, p_payload ->> 'recurrence_kind',
    coalesce((p_payload ->> 'interval')::integer, 1),
    coalesce(array(select jsonb_array_elements_text(p_payload -> 'weekdays')::smallint), '{}'),
    (p_payload ->> 'monthly_day')::smallint,
    coalesce((p_payload ->> 'monthly_last_day')::boolean, false),
    coalesce(p_payload ->> 'end_kind', 'never'), (p_payload ->> 'ends_on')::date,
    (p_payload ->> 'occurrence_count')::integer
  ) on conflict(id) do update set
    time_zone = excluded.time_zone, starts_at_local = excluded.starts_at_local,
    recurrence_kind = excluded.recurrence_kind, interval_value = excluded.interval_value,
    weekdays = excluded.weekdays, monthly_day = excluded.monthly_day,
    monthly_last_day = excluded.monthly_last_day, end_kind = excluded.end_kind,
    ends_on = excluded.ends_on, occurrence_count = excluded.occurrence_count,
    management_version = public.form_schedules.management_version + 1, updated_at = now()
  returning * into schedule_row;
  delete from public.form_schedule_reminders where schedule_id = schedule_row.id;
  for reminder_json in select value from jsonb_array_elements(coalesce(p_payload -> 'reminders', '[]'::jsonb)) loop
    perform app_private.form_assert_payload_keys(reminder_json, array['kind','amount','position'], 'form reminder');
    insert into public.form_schedule_reminders(schedule_id, reminder_kind, amount, position)
    values (schedule_row.id, reminder_json ->> 'kind', (reminder_json ->> 'amount')::integer,
            (reminder_json ->> 'position')::integer);
  end loop;
  insert into app_private.form_worker_jobs(job_kind, aggregate_id, payload_jsonb)
  values ('generate_occurrences', schedule_row.id, jsonb_build_object('schedule_id', schedule_row.id))
  on conflict do nothing;
  return app_private.form_complete_command(
    p_request_id, app_private.form_application_projection(schedule_row.application_id)
  );
end;
$$;


ALTER FUNCTION "app_private"."form_save_schedule"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_verify_anonymous_edit_secret"("p_secret" "text", "p_hash" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_hash is not null and extensions.crypt(p_secret, p_hash) = p_hash;
$$;


ALTER FUNCTION "app_private"."form_verify_anonymous_edit_secret"("p_secret" "text", "p_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_abort_multipart"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_upload_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_job app_private.form_worker_jobs;
declare upload_row app_private.form_multipart_uploads;
begin
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and aggregate_id = p_file_job_id and job_kind = 'export_zip'
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  select * into upload_row from app_private.form_multipart_uploads
   where file_job_id = p_file_job_id and worker_job_id = p_job_id and upload_id = p_upload_id
   for update;
  if upload_row.id is null or upload_row.state = 'completed' then
    raise no_data_found using message = 'multipart upload unavailable';
  end if;
  if upload_row.state <> 'aborted' then
    update app_private.form_multipart_uploads
       set state = 'aborted', aborted_at = now(), updated_at = now()
     where id = upload_row.id
     returning * into upload_row;
  end if;
  update app_private.form_worker_jobs
     set progress_jsonb = progress_jsonb || jsonb_build_object(
       'multipart_upload_id', upload_row.id,
       'multipart_aborted', true,
       'uploaded_bytes', upload_row.uploaded_bytes
     )
   where id = worker_job.id;
  return jsonb_build_object(
    'multipart_upload_id', upload_row.id,
    'state', upload_row.state,
    'uploaded_bytes', upload_row.uploaded_bytes
  );
end;
$$;


ALTER FUNCTION "app_private"."form_worker_abort_multipart"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_upload_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_begin_export"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_job app_private.form_worker_jobs;
begin
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and aggregate_id = p_file_job_id
     and job_kind in ('export_csv', 'export_xlsx', 'export_zip', 'export_anonymous_participation')
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  update public.form_file_jobs
     set state = 'processing', started_at = coalesce(started_at, now()), progress = greatest(progress, 0.05),
         error_code = null
   where id = p_file_job_id and state in ('pending', 'processing', 'failed') and expires_at > now();
  if not found then
    raise no_data_found using message = 'form export job unavailable';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_worker_begin_export"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_begin_multipart"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_bucket_id" "text", "p_object_path" "text", "p_upload_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare worker_job app_private.form_worker_jobs;
declare file_job public.form_file_jobs;
declare upload_row app_private.form_multipart_uploads;
begin
  if p_bucket_id <> 'coelo-forms-private'
     or p_object_path is null or p_object_path !~ '^[0-9a-f]{2}/[0-9a-f-]{36}$'
     or nullif(btrim(p_upload_id), '') is null or length(p_upload_id) > 1024
     or p_upload_id ~ '[[:cntrl:]]' then
    raise invalid_parameter_value using message = 'invalid multipart upload';
  end if;
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and aggregate_id = p_file_job_id and job_kind = 'export_zip'
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  select * into file_job from public.form_file_jobs
   where id = p_file_job_id and export_kind = 'zip' and state = 'processing' and expires_at > now()
   for update;
  if file_job.id is null then
    raise no_data_found using message = 'form export job unavailable';
  end if;
  select * into upload_row from app_private.form_multipart_uploads
   where file_job_id = p_file_job_id for update;
  if upload_row.id is null then
    insert into app_private.form_multipart_uploads(
      file_job_id, worker_job_id, bucket_id, object_path, upload_id
    ) values (
      p_file_job_id, p_job_id, p_bucket_id, p_object_path, p_upload_id
    ) returning * into upload_row;
  elsif upload_row.worker_job_id <> p_job_id
     or upload_row.bucket_id <> p_bucket_id
     or upload_row.object_path <> p_object_path
     or upload_row.upload_id <> p_upload_id then
    raise serialization_failure using message = 'multipart upload already initialized';
  end if;
  update app_private.form_worker_jobs
     set progress_jsonb = progress_jsonb || jsonb_build_object(
       'multipart_upload_id', upload_row.id,
       'next_part_number', upload_row.next_part_number,
       'uploaded_bytes', upload_row.uploaded_bytes
     )
   where id = worker_job.id;
  return jsonb_build_object(
    'multipart_upload_id', upload_row.id,
    'state', upload_row.state,
    'next_part_number', upload_row.next_part_number,
    'uploaded_bytes', upload_row.uploaded_bytes
  );
end;
$_$;


ALTER FUNCTION "app_private"."form_worker_begin_multipart"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_bucket_id" "text", "p_object_path" "text", "p_upload_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_begin_xlsx_r2_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_job public.form_file_jobs; v_worker app_private.form_worker_jobs; v_asset public.media_assets;
  v_attempt_key text; v_new_asset uuid:=gen_random_uuid(); v_ctx app_private.superadmin_internal_context;
begin
  v_job:=app_private.forms_xlsx_worker_job_v1(p_job_id,p_worker_id,p_file_job_id);
  select * into strict v_worker from app_private.form_worker_jobs where id=p_job_id;
  v_attempt_key:='xlsx:'||v_worker.id::text||':'||v_worker.attempts::text;
  select * into v_asset from public.media_assets where id=v_job.artifact_media_asset_id for update;
  if v_asset.id is null or v_asset.status<>'pending' or v_asset.upload_request_id<>v_attempt_key then
    -- A stale worker may still finish network I/O. Preserve its unique locator
    -- for reconciliation/cleanup, and never reuse that key for the next lease.
    if v_asset.id is not null and v_asset.status='pending' then
      update public.media_assets set status='quarantined' where id=v_asset.id;
    end if;
    insert into public.media_assets(id,institution_id,form_id,owner_internal_identity_id,upload_request_id,
      catalog_kind,media_purpose,export_file_job_id,storage_provider,bucket_id,original_name,mime_type,expires_at,object_key)
    values(v_new_asset,v_job.institution_id,v_job.form_id,v_job.requested_by_internal_identity_id,v_attempt_key,
      'form-xlsx','forms-responses-export',v_job.id,'r2','coelo-transient-prod','',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',v_job.expires_at,
      'tenants/'||v_job.institution_id::text||'/exports/forms/'||v_job.id::text||'/'||v_new_asset::text||'/responses.xlsx')
    returning * into v_asset;
    update public.form_file_jobs set artifact_media_asset_id=v_asset.id,state='processing',
      started_at=coalesce(started_at,clock_timestamp()),progress=greatest(progress,0.05),error_code=null
      where id=v_job.id;
  end if;
  v_job:=app_private.forms_xlsx_worker_job_v1(p_job_id,p_worker_id,p_file_job_id,v_asset.id);
  v_ctx:=app_private.forms_xlsx_context_from_session_v1(v_job.requested_by_internal_identity_id,v_job.requested_auth_link_id,
    v_job.requested_membership_id,v_job.requested_auth_session_id,v_job.requested_scope_kind,v_job.requested_scope_institution_id);
  perform app_private.audit_append_superadmin_internal(v_ctx.internal_identity_id,v_ctx.internal_auth_link_id,
    v_ctx.internal_membership_id,v_ctx.session_id,'forms.responses.export',v_ctx.aal,
    'superadmin.forms.export.begin','success',null,gen_random_uuid(),v_job.institution_id,'form_file_job',v_job.id);
  perform app_private.forms_xlsx_worker_job_v1(p_job_id,p_worker_id,p_file_job_id,v_asset.id);
  return jsonb_build_object('job_id',v_job.id,'worker_job_id',v_worker.id,'attempt',v_worker.attempts,
    'form_id',v_job.form_id,
    'asset_id',v_asset.id,'institution_id',v_job.institution_id,'provider','r2','bucket',v_asset.bucket_id,
    'object_key',v_asset.object_key,'mime_type',v_asset.mime_type,'expires_at',v_job.expires_at,
    'snapshot_format_version',v_job.snapshot_format_version,'snapshot_row_count',v_job.snapshot_row_count,
    'snapshot_schema',v_job.snapshot_schema,'snapshot_schema_sha256',v_job.snapshot_schema_sha256);
end;
$$;


ALTER FUNCTION "app_private"."form_worker_begin_xlsx_r2_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_cleanup_snapshot"("p_job_id" "uuid", "p_worker_id" "text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_job app_private.form_worker_jobs;
declare page_limit integer := least(greatest(coalesce(p_limit, 100), 1), 200);
declare result jsonb;
begin
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and job_kind in ('cleanup_uploads', 'cleanup_artifacts')
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  if worker_job.job_kind = 'cleanup_uploads' then
    select jsonb_build_object(
      'kind', worker_job.job_kind,
      'items', coalesce(jsonb_agg(jsonb_build_object('id', id, 'storage_path', storage_path)), '[]'::jsonb)
    ) into result
      from (
        select id, storage_path from public.form_assets
         where (state in ('prepared', 'uploaded') and expires_at <= now())
            or (state = 'discarded' and discarded_at is not null)
         order by expires_at, id limit page_limit
      ) candidate;
  else
    select jsonb_build_object(
      'kind', worker_job.job_kind,
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'id', id,
        'storage_path', storage_path,
        'multipart_bucket', multipart_bucket,
        'multipart_path', multipart_path,
        'multipart_upload_id', multipart_upload_id
      )), '[]'::jsonb)
    ) into result
      from (
        select file_job.id, file_job.artifact_path as storage_path,
               multipart.bucket_id as multipart_bucket,
               multipart.object_path as multipart_path,
               multipart.upload_id as multipart_upload_id
          from public.form_file_jobs file_job
          left join app_private.form_multipart_uploads multipart
            on multipart.file_job_id = file_job.id
           and multipart.state in ('initiated', 'uploading')
         where file_job.artifact_provider = 'supabase_mvp'
           and file_job.state in ('pending', 'succeeded', 'partial', 'failed')
           and file_job.expires_at <= now()
         order by file_job.expires_at, file_job.id limit page_limit
      ) candidate;
  end if;
  return result;
end;
$$;


ALTER FUNCTION "app_private"."form_worker_cleanup_snapshot"("p_job_id" "uuid", "p_worker_id" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_complete_cleanup"("p_job_id" "uuid", "p_worker_id" "text", "p_item_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_job app_private.form_worker_jobs;
declare completed_count integer;
declare requested_count integer := coalesce(cardinality(p_item_ids), 0);
begin
  if p_item_ids is null or requested_count > 200
     or requested_count <> (
       select count(distinct item_id) from unnest(p_item_ids) as items(item_id)
     ) then
    raise invalid_parameter_value using message = 'invalid cleanup items';
  end if;
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and job_kind in ('cleanup_uploads', 'cleanup_artifacts')
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  if worker_job.job_kind = 'cleanup_uploads' then
    update public.form_assets
       set state = 'expired'
     where id = any(p_item_ids) and (
       (state in ('prepared', 'uploaded') and expires_at <= now())
       or (state = 'discarded' and discarded_at is not null)
     );
  else
    update app_private.form_multipart_uploads multipart
       set state = 'aborted', aborted_at = now(), updated_at = now()
      where multipart.file_job_id = any(p_item_ids)
        and multipart.state in ('initiated', 'uploading')
        and exists (
          select 1 from public.form_file_jobs file_job
           where file_job.id = multipart.file_job_id
             and file_job.artifact_provider = 'supabase_mvp'
             and file_job.expires_at <= now()
        );
    update public.form_file_jobs
       set state = 'expired', artifact_path = null, artifact_byte_length = null
     where id = any(p_item_ids) and artifact_provider = 'supabase_mvp'
       and state in ('pending', 'succeeded', 'partial', 'failed') and expires_at <= now();
  end if;
  get diagnostics completed_count = row_count;
  if completed_count <> requested_count then
    raise serialization_failure using message = 'cleanup items unavailable';
  end if;
  update app_private.form_worker_jobs
     set state = 'succeeded', progress_jsonb = jsonb_build_object('completed', true, 'items', completed_count),
         completed_at = now(), lease_owner = null, lease_expires_at = null
   where id = worker_job.id;
end;
$$;


ALTER FUNCTION "app_private"."form_worker_complete_cleanup"("p_job_id" "uuid", "p_worker_id" "text", "p_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_complete_export"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_artifact_path" "text", "p_artifact_byte_length" bigint, "p_manifest" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare worker_job app_private.form_worker_jobs;
begin
  if p_artifact_path is null or p_artifact_path !~ '^[0-9a-f]{2}/[0-9a-f-]{36}$'
     or p_artifact_byte_length is null or p_artifact_byte_length < 1
     or p_manifest is null or jsonb_typeof(p_manifest) <> 'object' then
    raise invalid_parameter_value using message = 'invalid export artifact';
  end if;
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and aggregate_id = p_file_job_id
     and job_kind in ('export_csv', 'export_xlsx', 'export_zip', 'export_anonymous_participation')
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  update public.form_file_jobs
     set state = 'succeeded', progress = 1, artifact_path = p_artifact_path,
         artifact_byte_length = p_artifact_byte_length, manifest_jsonb = p_manifest,
         completed_at = now(), error_code = null
   where id = p_file_job_id and state = 'processing' and expires_at > now();
  if not found then
    raise no_data_found using message = 'form export job unavailable';
  end if;
  update app_private.form_worker_jobs
     set state = 'succeeded', progress_jsonb = jsonb_build_object('completed', true),
         completed_at = now(), lease_owner = null, lease_expires_at = null
   where id = worker_job.id;
end;
$_$;


ALTER FUNCTION "app_private"."form_worker_complete_export"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_artifact_path" "text", "p_artifact_byte_length" bigint, "p_manifest" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_complete_multipart"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_upload_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_job app_private.form_worker_jobs;
declare upload_row app_private.form_multipart_uploads;
begin
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and aggregate_id = p_file_job_id and job_kind = 'export_zip'
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  select * into upload_row from app_private.form_multipart_uploads
   where file_job_id = p_file_job_id and worker_job_id = p_job_id and upload_id = p_upload_id
   for update;
  if upload_row.id is null or upload_row.state = 'aborted' then
    raise no_data_found using message = 'multipart upload unavailable';
  end if;
  if upload_row.state <> 'completed' then
    if not exists(
      select 1 from app_private.form_multipart_parts
       where multipart_upload_id = upload_row.id
    ) then
      raise check_violation using message = 'multipart upload has no parts';
    end if;
    update app_private.form_multipart_uploads
       set state = 'completed', completed_at = now(), updated_at = now()
     where id = upload_row.id
     returning * into upload_row;
  end if;
  update app_private.form_worker_jobs
     set progress_jsonb = progress_jsonb || jsonb_build_object(
       'multipart_upload_id', upload_row.id,
       'multipart_completed', true,
       'uploaded_bytes', upload_row.uploaded_bytes
     )
   where id = worker_job.id;
  update public.form_file_jobs set progress = greatest(progress, 0.95)
   where id = p_file_job_id;
  return jsonb_build_object(
    'multipart_upload_id', upload_row.id,
    'state', upload_row.state,
    'part_count', upload_row.next_part_number - 1,
    'uploaded_bytes', upload_row.uploaded_bytes
  );
end;
$$;


ALTER FUNCTION "app_private"."form_worker_complete_multipart"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_upload_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_complete_xlsx_r2_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_asset_id" "uuid", "p_actual_byte_length" bigint, "p_actual_checksum_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_job public.form_file_jobs; v_worker app_private.form_worker_jobs;
  v_ctx app_private.superadmin_internal_context;
begin
  if p_asset_id is null or p_actual_byte_length is null or p_actual_byte_length<1
    or p_actual_checksum_sha256 is null or p_actual_checksum_sha256!~'^[0-9a-f]{64}$' then
    raise invalid_parameter_value using message='forms_xlsx_measurement_invalid';
  end if;
  v_job:=app_private.forms_xlsx_worker_job_v1(p_job_id,p_worker_id,p_file_job_id,p_asset_id);
  select * into strict v_worker from app_private.form_worker_jobs where id=p_job_id;
  perform 1 from public.media_assets where id=p_asset_id for update;
  perform app_private.forms_xlsx_worker_job_v1(p_job_id,p_worker_id,p_file_job_id,p_asset_id);
  if exists(select 1 from app_private.form_multipart_uploads m where m.media_asset_id=p_asset_id
    and m.artifact_provider='r2' and (m.state is distinct from 'completed'
      or m.uploaded_bytes is distinct from p_actual_byte_length
      or m.checksum_sha256 is distinct from p_actual_checksum_sha256)) then
    raise check_violation using message='forms_xlsx_multipart_finalization_mismatch';
  end if;
  -- Measurements come only from the service generating and writing the XLSX.
  -- No client grant and no caller-supplied path, MIME, tenant or manifest.
  update public.media_assets set status='ready',byte_size=p_actual_byte_length,
    checksum_sha256=p_actual_checksum_sha256,finalized_at=clock_timestamp() where id=p_asset_id;
  update public.form_file_jobs set state='succeeded',progress=1,artifact_byte_length=p_actual_byte_length,
    completed_at=clock_timestamp(),error_code=null,
    manifest_jsonb=jsonb_build_object('format_version',snapshot_format_version,'response_count',snapshot_row_count,
      'schema_sha256',snapshot_schema_sha256)
    where id=v_job.id;
  update app_private.form_worker_jobs set state='succeeded',completed_at=clock_timestamp(),
    lease_owner=null,lease_expires_at=null,progress_jsonb=jsonb_build_object('completed',true)
    where id=p_job_id;
  v_ctx:=app_private.forms_xlsx_context_from_session_v1(v_job.requested_by_internal_identity_id,v_job.requested_auth_link_id,
    v_job.requested_membership_id,v_job.requested_auth_session_id,v_job.requested_scope_kind,v_job.requested_scope_institution_id);
  perform app_private.audit_append_superadmin_internal(v_ctx.internal_identity_id,v_ctx.internal_auth_link_id,
    v_ctx.internal_membership_id,v_ctx.session_id,'forms.responses.export',v_ctx.aal,
    'superadmin.forms.export.complete','success',null,gen_random_uuid(),v_job.institution_id,'form_file_job',v_job.id);
  if v_worker.lease_expires_at<=clock_timestamp() or v_job.expires_at<=clock_timestamp() then
    raise serialization_failure using message='forms_xlsx_lease_unavailable';
  end if;
  return jsonb_build_object('job_id',v_job.id,'asset_id',p_asset_id,'state','succeeded',
    'byte_length',p_actual_byte_length,'checksum_sha256',p_actual_checksum_sha256,'expires_at',v_job.expires_at);
end;
$_$;


ALTER FUNCTION "app_private"."form_worker_complete_xlsx_r2_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_asset_id" "uuid", "p_actual_byte_length" bigint, "p_actual_checksum_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_export_snapshot"("p_file_job_id" "uuid", "p_after_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare file_job public.form_file_jobs;
declare page_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
begin
  select * into file_job
    from public.form_file_jobs
   where id = p_file_job_id
     and state in ('pending', 'processing')
     and expires_at > now();
  if file_job.id is null then
    raise no_data_found using message = 'form export job unavailable';
  end if;

  if file_job.export_kind = 'anonymous_participation' then
    return (
      with page as (
        select participation.id,
               coalesce(person_row.display_name, responder_row.display_name, '') as display_name,
               coalesce(membership_row.role_code, '') as profile_code,
               participation.response_unit_key as context_label,
               participation.response_state
          from public.form_participations participation
          join public.form_occurrences occurrence on occurrence.id = participation.occurrence_id
          left join public.people person_row on person_row.id = participation.person_id
          left join lateral (
            select responder_person.display_name, responder.person_id
              from public.form_participation_responders responder
              join public.people responder_person on responder_person.id = responder.person_id
             where responder.participation_id = participation.id
             order by responder.person_id
             limit 1
          ) responder_row on true
          left join lateral (
            select membership.role_code
              from public.institution_memberships membership
             where membership.person_id = coalesce(participation.person_id, responder_row.person_id)
               and membership.institution_id = participation.institution_id
               and membership.status = 'active'
             order by membership.id
             limit 1
          ) membership_row on true
         where occurrence.form_id = file_job.form_id
           and (file_job.occurrence_id is null or participation.occurrence_id = file_job.occurrence_id)
           and (p_after_id is null or participation.id > p_after_id)
         order by participation.id
         limit page_limit + 1
      ), visible as (select * from page limit page_limit)
      select jsonb_build_object(
        'kind', 'anonymous_participation',
        'rows', coalesce(jsonb_agg(jsonb_build_object(
          'Pessoa', display_name,
          'Perfil', coalesce(profile_code, ''),
          'Contexto', context_label,
          'Respondeu', case when response_state = 'responded' then 'Sim' else 'Não' end
        ) order by id), '[]'::jsonb),
        'has_more', (select count(*) > page_limit from page),
        'next_cursor', (select id from visible order by id desc limit 1)
      ) from visible
    );
  end if;

  return (
    with page as (
      select response.*
        from public.form_responses response
       where response.form_id = file_job.form_id
         and response.status = 'submitted'
         and (file_job.occurrence_id is null or response.occurrence_id = file_job.occurrence_id)
         and (p_after_id is null or response.id > p_after_id)
       order by response.id
       limit page_limit + 1
    ), visible as (
      select * from page limit page_limit
    ), submissions as (
      select response.id,
             jsonb_build_object(
               'responseId', response.id,
               'occurrenceId', response.occurrence_id,
               'versionId', response.form_version_id,
               'metadata', jsonb_build_object(
                 'form_id', response.form_id,
                 'identity_mode', response.identity_mode,
                 'respondent', case when response.identity_mode = 'identified'
                   then person_row.display_name else '' end,
                 'submitted_at', case when response.identity_mode = 'identified'
                   then response.submitted_at::text else '' end
               ),
               'answers', coalesce((
                 select jsonb_agg(jsonb_build_object(
                   'itemId', item.id,
                   'question', item.label,
                   'multiValued', item.kind in ('multiple_choice', 'photo', 'gallery'),
                   'values', case
                     when item.kind in ('single_choice', 'multiple_choice') then coalesce((
                       select jsonb_agg(option_row.label order by answer_option.position, option_row.position)
                         from public.form_answer_options answer_option
                         join public.form_question_options option_row on option_row.id = answer_option.option_id
                        where answer_option.answer_id = answer.id
                     ), '[]'::jsonb)
                     when item.kind in ('photo', 'gallery') then coalesce((
                       select jsonb_agg('/forms/media/' || asset.id::text order by answer_asset.position)
                         from public.form_answer_assets answer_asset
                         join public.form_assets asset on asset.id = answer_asset.asset_id
                        where answer_asset.answer_id = answer.id and asset.state = 'finalized'
                     ), '[]'::jsonb)
                     else jsonb_build_array(case answer.answer_kind
                       when 'short_text' then answer.text_value
                       when 'integer' then answer.integer_value::text
                       when 'decimal' then answer.decimal_value::text
                       when 'money' then answer.money_minor_units::text
                       when 'date' then answer.date_value::text
                       when 'yes_no' then case when answer.yes_no_value then 'Sim' else 'Não' end
                       when 'scale' then answer.scale_value::text
                       else '' end)
                   end
                 ) order by section.position, item.position, item.id)
                   from public.form_answers answer
                   join public.form_items item on item.id = answer.item_id
                   join public.form_sections section on section.id = item.section_id
                  where answer.response_id = response.id
               ), '[]'::jsonb)
             ) as payload
        from visible response
        left join public.people person_row on person_row.id = response.respondent_person_id
    )
    select jsonb_build_object(
      'kind', file_job.export_kind,
      'submissions', coalesce(jsonb_agg(payload order by id), '[]'::jsonb),
      'media', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'asset_id', media.asset_id,
          'storage_path', media.storage_path,
          'mime_type', media.mime_type
        ) order by media.asset_id), '[]'::jsonb)
          from (
            select distinct asset.id as asset_id, asset.storage_path, asset.mime_type
              from visible response_row
              join public.form_answers answer on answer.response_id = response_row.id
              join public.form_answer_assets answer_asset on answer_asset.answer_id = answer.id
              join public.form_assets asset on asset.id = answer_asset.asset_id
             where asset.state = 'finalized'
          ) media
      ),
      'has_more', (select count(*) > page_limit from page),
      'next_cursor', (select id from visible order by id desc limit 1)
    ) from submissions
  );
end;
$$;


ALTER FUNCTION "app_private"."form_worker_export_snapshot"("p_file_job_id" "uuid", "p_after_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_fail_export"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_error_code" "text", "p_retry_after_seconds" integer DEFAULT 60) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_job app_private.form_worker_jobs;
declare file_state text;
begin
  if nullif(btrim(p_error_code), '') is null then
    raise invalid_parameter_value using message = 'export error code required';
  end if;
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and aggregate_id = p_file_job_id
     and job_kind in ('export_csv', 'export_xlsx', 'export_zip', 'export_anonymous_participation')
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  update public.form_file_jobs
     set state = case when expires_at <= now() then 'expired' else 'failed' end,
         error_code = left(p_error_code, 100)
   where id = p_file_job_id and state in ('pending', 'processing')
   returning state into file_state;
  if file_state is null then
    raise no_data_found using message = 'form export job unavailable';
  end if;
  update app_private.form_worker_jobs
     set state = case when file_state = 'expired' then 'succeeded' else 'failed' end,
         last_error_code = left(p_error_code, 100),
         progress_jsonb = jsonb_build_object('completed', false),
         available_at = now() + make_interval(secs => least(greatest(p_retry_after_seconds, 1), 86400)),
         completed_at = case when file_state = 'expired' then now() else null end,
         lease_owner = null, lease_expires_at = null
   where id = worker_job.id;
end;
$$;


ALTER FUNCTION "app_private"."form_worker_fail_export"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_error_code" "text", "p_retry_after_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_multipart_snapshot"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_job app_private.form_worker_jobs;
declare upload_row app_private.form_multipart_uploads;
begin
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and aggregate_id = p_file_job_id and job_kind = 'export_zip'
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now();
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  select * into upload_row from app_private.form_multipart_uploads
   where file_job_id = p_file_job_id and worker_job_id = p_job_id and state <> 'aborted';
  if upload_row.id is null then return null; end if;
  return jsonb_build_object(
    'bucket_id', upload_row.bucket_id,
    'object_path', upload_row.object_path,
    'upload_id', upload_row.upload_id,
    'state', upload_row.state,
    'next_part_number', upload_row.next_part_number,
    'uploaded_bytes', upload_row.uploaded_bytes,
    'parts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'part_number', part.part_number,
        'etag', part.etag,
        'byte_length', part.byte_length,
        'checksum_sha256', part.checksum_sha256
      ) order by part.part_number)
      from app_private.form_multipart_parts part
      where part.multipart_upload_id = upload_row.id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "app_private"."form_worker_multipart_snapshot"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_multipart_xlsx_r2_v1"("p_scope" "jsonb", "p_operation" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_job public.form_file_jobs; v_asset public.media_assets; v_worker app_private.form_worker_jobs;
  v_upload app_private.form_multipart_uploads; v_part app_private.form_multipart_parts;
  v_job_id uuid; v_file_job_id uuid; v_asset_id uuid; v_owner text; v_expected jsonb;
  v_upload_id text; v_number integer; v_bytes bigint; v_etag text; v_checksum text; v_allowed text[];
begin
  if current_setting('transaction_isolation')<>'read committed' or p_scope is null or jsonb_typeof(p_scope)<>'object'
    or pg_column_size(p_scope)>4096 or p_payload is null or jsonb_typeof(p_payload)<>'object'
    or pg_column_size(p_payload)>4096 or p_operation is null
    or p_operation not in ('authorize','snapshot','begin','record_part','complete','reconcile') then
    raise invalid_parameter_value using message='forms_xlsx_multipart_input_invalid';
  end if;
  v_job_id:=(p_scope->>'worker_job_id')::uuid; v_file_job_id:=(p_scope->>'file_job_id')::uuid;
  v_asset_id:=(p_scope->>'asset_id')::uuid; v_owner:=p_scope->>'worker_id';
  if v_job_id is null or v_file_job_id is null or v_asset_id is null or v_owner is null then
    raise invalid_parameter_value using message='forms_xlsx_multipart_input_invalid';
  end if;
  if p_operation='reconcile' then
    select * into v_worker from app_private.form_worker_jobs where id=v_job_id
      and aggregate_id=v_file_job_id and job_kind='export_xlsx_r2_v1' for share;
    if v_worker.id is null then return null; end if;
    select * into v_upload from app_private.form_multipart_uploads where worker_job_id=v_job_id
      and file_job_id=v_file_job_id and media_asset_id=v_asset_id and artifact_provider='r2' for share;
    if v_upload.id is null then return null; end if;
    v_expected:=app_private.forms_xlsx_multipart_projection_v1(v_upload.id)->'scope';
    if p_scope is distinct from v_expected then raise serialization_failure using message='forms_xlsx_multipart_scope_mismatch'; end if;
  else
    v_job:=app_private.forms_xlsx_worker_job_v1(v_job_id,v_owner,v_file_job_id,v_asset_id);
    select * into strict v_worker from app_private.form_worker_jobs where id=v_job_id;
    select * into strict v_asset from public.media_assets where id=v_asset_id for update;
    v_expected:=jsonb_build_object('worker_job_id',v_job_id,'worker_id',v_owner,'file_job_id',v_file_job_id,
      'attempt',v_worker.attempts,'asset_id',v_asset_id,'bucket',v_asset.bucket_id,'object_key',v_asset.object_key,
      'snapshot_format_version',v_job.snapshot_format_version,'snapshot_row_count',v_job.snapshot_row_count);
    if p_scope is distinct from v_expected then raise serialization_failure using message='forms_xlsx_multipart_scope_mismatch'; end if;
    select * into v_upload from app_private.form_multipart_uploads
      where media_asset_id=v_asset_id and artifact_provider='r2' for update;
  end if;
  v_allowed:=case p_operation
    when 'begin' then array['upload_id']
    when 'record_part' then array['upload_id','part_number','etag','byte_length','checksum_sha256']
    when 'complete' then array['upload_id','byte_length','checksum_sha256']
    when 'reconcile' then array['upload_id','byte_length','checksum_sha256']
    else array[]::text[] end;
  if exists(select 1 from jsonb_object_keys(p_payload) k where not(k=any(v_allowed)))
    or exists(select 1 from unnest(v_allowed) k where not(p_payload?k)) then
    raise invalid_parameter_value using message='forms_xlsx_multipart_payload_invalid';
  end if;
  if p_operation in ('authorize','snapshot') then
    perform app_private.forms_xlsx_worker_job_v1(v_job_id,v_owner,v_file_job_id,v_asset_id);
    if p_operation='authorize' then return jsonb_build_object('authorized',true,'scope',v_expected); end if;
    return app_private.forms_xlsx_multipart_projection_v1(v_upload.id);
  end if;
  v_upload_id:=p_payload->>'upload_id';
  if jsonb_typeof(p_payload->'upload_id')<>'string' or v_upload_id is null
    or length(v_upload_id) not between 1 and 1024 or v_upload_id ~ '[[:space:][:cntrl:]]' then
    raise invalid_parameter_value using message='forms_xlsx_multipart_upload_id_invalid';
  end if;
  if p_operation='begin' then
    if v_upload.id is null then
      insert into app_private.form_multipart_uploads(file_job_id,worker_job_id,bucket_id,object_path,upload_id,
        artifact_provider,media_asset_id,worker_attempt,attempt_owner,snapshot_format_version,snapshot_row_count)
      values(v_file_job_id,v_job_id,v_asset.bucket_id,v_asset.object_key,v_upload_id,'r2',v_asset_id,
        v_worker.attempts,v_owner,v_job.snapshot_format_version,v_job.snapshot_row_count) returning * into v_upload;
    elsif v_upload.upload_id<>v_upload_id or v_upload.state='aborted' then
      raise serialization_failure using message='forms_xlsx_multipart_begin_mismatch';
    end if;
  else
    if v_upload.id is null or v_upload.upload_id<>v_upload_id or v_upload.state='aborted' then
      raise serialization_failure using message='forms_xlsx_multipart_upload_unavailable';
    end if;
    v_bytes:=(p_payload->>'byte_length')::bigint; v_checksum:=p_payload->>'checksum_sha256';
    if jsonb_typeof(p_payload->'byte_length')<>'number' or v_bytes is null or v_bytes<1
      or p_payload->'byte_length'<>to_jsonb(v_bytes) or jsonb_typeof(p_payload->'checksum_sha256')<>'string'
      or v_checksum is null or v_checksum!~'^[0-9a-f]{64}$' then
      raise invalid_parameter_value using message='forms_xlsx_measurement_invalid';
    end if;
    if p_operation='record_part' then
      v_number:=(p_payload->>'part_number')::integer; v_etag:=p_payload->>'etag';
      if jsonb_typeof(p_payload->'part_number')<>'number' or v_number is null or v_number not between 1 and 10000
        or p_payload->'part_number'<>to_jsonb(v_number) or jsonb_typeof(p_payload->'etag')<>'string'
        or v_etag is null or length(v_etag) not between 3 and 1024 or v_etag!~'^"[^"[:cntrl:]]+"$'
        or v_bytes>67108864 then raise invalid_parameter_value using message='forms_xlsx_multipart_part_invalid'; end if;
      select * into v_part from app_private.form_multipart_parts where multipart_upload_id=v_upload.id and part_number=v_number;
      if v_part.multipart_upload_id is not null then
        if (v_part.etag,v_part.byte_length,v_part.checksum_sha256) is distinct from (v_etag,v_bytes,v_checksum) then
          raise serialization_failure using message='forms_xlsx_multipart_part_replay_mismatch';
        end if;
      else
        if v_upload.state='completed' or v_number<>v_upload.next_part_number then
          raise serialization_failure using message='forms_xlsx_multipart_part_out_of_sequence';
        end if;
        -- Before another part, the preceding part must satisfy the provider's
        -- minimum and uniform non-final size. The final part may be smaller.
        if v_number>1 and (v_bytes>(select first.byte_length from app_private.form_multipart_parts first
          where first.multipart_upload_id=v_upload.id and first.part_number=1)
          or exists(select 1 from app_private.form_multipart_parts p
          where p.multipart_upload_id=v_upload.id and (p.byte_length<5242880 or p.byte_length<>
            (select first.byte_length from app_private.form_multipart_parts first
             where first.multipart_upload_id=v_upload.id and first.part_number=1)))) then
          raise check_violation using message='forms_xlsx_multipart_nonfinal_size_invalid';
        end if;
        insert into app_private.form_multipart_parts(multipart_upload_id,part_number,etag,byte_length,checksum_sha256)
          values(v_upload.id,v_number,v_etag,v_bytes,v_checksum);
        update app_private.form_multipart_uploads set state='uploading',next_part_number=next_part_number+1,
          uploaded_bytes=uploaded_bytes+v_bytes,updated_at=clock_timestamp() where id=v_upload.id returning * into v_upload;
      end if;
    elsif p_operation='complete' then
      if v_upload.uploaded_bytes<>v_bytes or v_upload.next_part_number<=1 then
        raise check_violation using message='forms_xlsx_multipart_measurement_mismatch';
      end if;
      if v_upload.state='completed' then
        if v_upload.checksum_sha256<>v_checksum then raise serialization_failure using message='forms_xlsx_multipart_complete_mismatch'; end if;
      else
        update app_private.form_multipart_uploads set state='completed',checksum_sha256=v_checksum,
          completed_at=clock_timestamp(),updated_at=clock_timestamp() where id=v_upload.id returning * into v_upload;
      end if;
    elsif p_operation='reconcile' then
      if v_upload.state<>'completed' then return null; end if;
      if v_upload.uploaded_bytes<>v_bytes or v_upload.checksum_sha256<>v_checksum then
        raise serialization_failure using message='forms_xlsx_multipart_complete_mismatch';
      end if;
      return app_private.forms_xlsx_multipart_projection_v1(v_upload.id);
    end if;
  end if;
  perform app_private.forms_xlsx_worker_job_v1(v_job_id,v_owner,v_file_job_id,v_asset_id);
  return app_private.forms_xlsx_multipart_projection_v1(v_upload.id);
end;
$_$;


ALTER FUNCTION "app_private"."form_worker_multipart_xlsx_r2_v1"("p_scope" "jsonb", "p_operation" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_reconcile_xlsx_r2_v1"("p_job_id" "uuid", "p_file_job_id" "uuid", "p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_job public.form_file_jobs; v_asset public.media_assets; v_state text:='unavailable';
begin
  if current_setting('transaction_isolation')<>'read committed' or p_job_id is null or p_file_job_id is null or p_asset_id is null then
    raise invalid_parameter_value using message='forms_xlsx_worker_input_invalid';
  end if;
  if not exists(select 1 from app_private.form_worker_jobs where id=p_job_id
    and aggregate_id=p_file_job_id and job_kind='export_xlsx_r2_v1') then
    return jsonb_build_object('state','unavailable');
  end if;
  select * into v_job from public.form_file_jobs where id=p_file_job_id and artifact_provider='r2' for update;
  select * into v_asset from public.media_assets where id=p_asset_id and export_file_job_id=p_file_job_id
    and catalog_kind='form-xlsx' for share;
  if v_job.id is not null and v_asset.id is not null then
    if v_job.state='succeeded' and v_job.artifact_media_asset_id=v_asset.id and v_asset.status='ready' then
      v_state:='committed';
    elsif v_asset.status in ('quarantined','deleted') or v_job.state='expired' then
      v_state:='abandoned';
    elsif v_job.artifact_media_asset_id=v_asset.id and v_asset.status='pending' then
      v_state:='pending';
    end if;
  end if;
  return jsonb_build_object('state',v_state,'job_id',p_file_job_id,'asset_id',p_asset_id,
    'byte_length',case when v_state='committed' then v_asset.byte_size else null end,
    'checksum_sha256',case when v_state='committed' then v_asset.checksum_sha256 else null end);
end;
$$;


ALTER FUNCTION "app_private"."form_worker_reconcile_xlsx_r2_v1"("p_job_id" "uuid", "p_file_job_id" "uuid", "p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_record_multipart_part"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_upload_id" "text", "p_part_number" integer, "p_etag" "text", "p_byte_length" bigint, "p_checksum_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare worker_job app_private.form_worker_jobs;
declare upload_row app_private.form_multipart_uploads;
declare part_row app_private.form_multipart_parts;
begin
  if p_part_number not between 1 and 10000
     or nullif(btrim(p_etag), '') is null or length(p_etag) > 1024 or p_etag ~ '[[:cntrl:]]'
     or p_byte_length is null or p_byte_length < 1
     or p_checksum_sha256 is null or p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise invalid_parameter_value using message = 'invalid multipart part';
  end if;
  select * into worker_job from app_private.form_worker_jobs
   where id = p_job_id and aggregate_id = p_file_job_id and job_kind = 'export_zip'
     and state = 'processing' and lease_owner = p_worker_id and lease_expires_at >= now()
   for update;
  if worker_job.id is null then
    raise serialization_failure using message = 'worker lease unavailable';
  end if;
  select * into upload_row from app_private.form_multipart_uploads
   where file_job_id = p_file_job_id and worker_job_id = p_job_id and upload_id = p_upload_id
   for update;
  if upload_row.id is null or upload_row.state not in ('initiated', 'uploading') then
    raise no_data_found using message = 'multipart upload unavailable';
  end if;
  select * into part_row from app_private.form_multipart_parts
   where multipart_upload_id = upload_row.id and part_number = p_part_number;
  if part_row.multipart_upload_id is not null then
    if part_row.etag <> p_etag or part_row.byte_length <> p_byte_length
       or part_row.checksum_sha256 <> p_checksum_sha256 then
      raise serialization_failure using message = 'multipart part replay mismatch';
    end if;
  else
    if p_part_number <> upload_row.next_part_number then
      raise serialization_failure using message = 'multipart part out of sequence';
    end if;
    insert into app_private.form_multipart_parts(
      multipart_upload_id, part_number, etag, byte_length, checksum_sha256
    ) values (
      upload_row.id, p_part_number, p_etag, p_byte_length, p_checksum_sha256
    );
    update app_private.form_multipart_uploads
       set state = 'uploading', next_part_number = next_part_number + 1,
           uploaded_bytes = uploaded_bytes + p_byte_length, updated_at = now()
     where id = upload_row.id
     returning * into upload_row;
  end if;
  update app_private.form_worker_jobs
     set progress_jsonb = progress_jsonb || jsonb_build_object(
       'multipart_upload_id', upload_row.id,
       'next_part_number', upload_row.next_part_number,
       'uploaded_bytes', upload_row.uploaded_bytes
     )
   where id = worker_job.id;
  update public.form_file_jobs set progress = greatest(progress, 0.1)
   where id = p_file_job_id;
  return jsonb_build_object(
    'multipart_upload_id', upload_row.id,
    'state', upload_row.state,
    'next_part_number', upload_row.next_part_number,
    'uploaded_bytes', upload_row.uploaded_bytes
  );
end;
$_$;


ALTER FUNCTION "app_private"."form_worker_record_multipart_part"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_upload_id" "text", "p_part_number" integer, "p_etag" "text", "p_byte_length" bigint, "p_checksum_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_worker_xlsx_snapshot_r2_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_asset_id" "uuid", "p_after_sequence" bigint DEFAULT 0, "p_limit" integer DEFAULT 250) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_job public.form_file_jobs; v_result jsonb;
begin
  if p_asset_id is null or p_after_sequence is null or p_after_sequence<0 or p_limit is null or p_limit not between 1 and 500 then
    raise invalid_parameter_value using message='forms_xlsx_page_invalid';
  end if;
  v_job:=app_private.forms_xlsx_worker_job_v1(p_job_id,p_worker_id,p_file_job_id,p_asset_id);
  if p_after_sequence>v_job.snapshot_row_count then raise invalid_parameter_value using message='forms_xlsx_cursor_invalid'; end if;
  select jsonb_build_object('kind','xlsx','snapshot_format_version',v_job.snapshot_format_version,
    'snapshot_schema_sha256',v_job.snapshot_schema_sha256,
    'submissions',coalesce(jsonb_agg(s.submission_jsonb order by s.sequence_number),'[]'::jsonb),
    'has_more',coalesce(max(s.sequence_number),p_after_sequence)<v_job.snapshot_row_count,
    'next_cursor',case when max(s.sequence_number) is not null then max(s.sequence_number)::text else null end)
    into v_result from (select sequence_number,submission_jsonb from app_private.form_xlsx_snapshot_rows
      where file_job_id=v_job.id and sequence_number>p_after_sequence order by sequence_number limit p_limit) s;
  perform app_private.forms_xlsx_worker_job_v1(p_job_id,p_worker_id,p_file_job_id,p_asset_id);
  return v_result;
end;
$$;


ALTER FUNCTION "app_private"."form_worker_xlsx_snapshot_r2_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_asset_id" "uuid", "p_after_sequence" bigint, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_answer_media_descriptor_v1"("p_asset" "uuid", "p_rendition" "text", "p_scope" "text", "p_institution" "uuid", "p_response" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_response_id uuid; result jsonb;
begin
  if p_asset is null or p_rendition not in ('original','preview') or p_rendition is null
    or p_scope is null or p_scope not in ('platform','institution')
    or (p_scope='institution' and p_institution is null) then
    raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
  end if;
  select r.id into v_response_id
    from public.form_assets source
    join public.form_answer_assets attachment on attachment.asset_id=source.id
    join public.form_answers answer on answer.id=attachment.answer_id
    join public.form_responses r on r.id=answer.response_id
    where source.id=p_asset and r.status='submitted'
      and (p_response is null or r.id=p_response)
      and r.institution_id=source.institution_id and r.occurrence_id=source.occurrence_id
      and (p_scope='platform' or r.institution_id=p_institution)
    order by r.id limit 1 for share of r;
  if v_response_id is null then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
  -- This final join, after the response lock, rechecks all relationships and
  -- locks attachment/definition/catalog rows against concurrent revocation.
  select jsonb_build_object('asset_id',source.id,'media_asset_id',asset.id,'response_id',r.id,
      'institution_id',f.institution_id,'form_id',f.id,'form_version_id',v.id,'item_id',item.id,
      'rendition',variant.rendition,'bucket',variant.bucket_id,'object_key',variant.object_key,'mime_type',variant.mime_type)
    into result
    from public.form_assets source
    join public.form_answer_assets attachment on attachment.asset_id=source.id
    join public.form_answers answer on answer.id=attachment.answer_id and answer.item_id=source.item_id
    join public.form_responses r on r.id=answer.response_id and r.id=v_response_id
    join public.form_occurrences occurrence on occurrence.id=r.occurrence_id and occurrence.id=source.occurrence_id
      and occurrence.institution_id=r.institution_id and occurrence.form_id=r.form_id
      and occurrence.form_version_id=r.form_version_id
    join public.forms f on f.id=r.form_id and f.institution_id=r.institution_id
    join public.institutions institution on institution.id=f.institution_id and institution.deleted_at is null
    join public.form_versions v on v.id=r.form_version_id and v.form_id=f.id
    join public.form_items item on item.id=source.item_id and item.form_version_id=v.id
    join public.form_sections section on section.id=item.section_id and section.form_version_id=v.id
    join public.media_assets asset on asset.source_form_asset_id=source.id and asset.form_id=f.id
      and asset.institution_id=f.institution_id and asset.catalog_kind='form-image'
      and asset.media_purpose='answer-image' and asset.status='ready'
    join public.media_bindings binding on binding.media_asset_id=asset.id and binding.item_id=item.id
      and binding.form_version_id=v.id and binding.purpose='answer-image'
    join public.media_variants variant on variant.media_asset_id=asset.id and variant.rendition=p_rendition
    where source.id=p_asset and source.state='finalized' and source.institution_id=f.institution_id
      and r.status='submitted' and r.identity_mode=f.identity_mode
      and answer.form_version_id=v.id and answer.answer_kind=item.kind and item.kind in ('photo','gallery')
      and asset.owner_person_id is not distinct from source.prepared_by_person_id
      and ((source.prepared_by_person_id is null)=(f.identity_mode='anonymous'))
      and (r.identity_mode='anonymous' or source.prepared_by_person_id=r.respondent_person_id)
      and (p_scope='platform' or f.institution_id=p_institution)
      and variant.bucket_id='coelo-media-prod'
      and app_private.private_media_catalog_key_v1(asset,p_rendition,variant.object_key,variant.mime_type) is true
    order by answer.id limit 1
    for share of source,attachment,answer,r,occurrence,f,institution,v,item,section,asset,binding,variant;
  if result is null then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
  return result;
end;
$$;


ALTER FUNCTION "app_private"."forms_answer_media_descriptor_v1"("p_asset" "uuid", "p_rendition" "text", "p_scope" "text", "p_institution" "uuid", "p_response" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_media_dispatch_cleanup_worker"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_url text;
declare bearer_token text;
declare request_id bigint;
begin
  select decrypted_secret into worker_url
    from vault.decrypted_secrets where name = 'forms_media_worker_url' limit 1;
  select decrypted_secret into bearer_token
    from vault.decrypted_secrets where name = 'forms_worker_bearer_token' limit 1;
  if nullif(worker_url, '') is null or nullif(bearer_token, '') is null then
    return null;
  end if;
  select net.http_post(
    url := worker_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || bearer_token
    ),
    body := '{"action":"cleanup"}'::jsonb,
    timeout_milliseconds := 5000
  ) into request_id;
  return request_id;
end;
$$;


ALTER FUNCTION "app_private"."forms_media_dispatch_cleanup_worker"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_media_read_context_v1"("p_identity" "uuid", "p_link" "uuid", "p_membership" "uuid", "p_session" "uuid", "p_scope" "text", "p_institution" "uuid") RETURNS "app_private"."superadmin_internal_context"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; v_auth_user_id uuid; session_aal text;
  original_claims text:=current_setting('request.jwt.claims',true);
  original_sub text:=current_setting('request.jwt.claim.sub',true);
begin
  select s.user_id,s.aal::text into v_auth_user_id,session_aal from auth.sessions s
    where s.id=p_session and (s.not_after is null or s.not_after>clock_timestamp());
  if v_auth_user_id is null or session_aal is null or session_aal not in ('aal1','aal2') then
    raise insufficient_privilege using detail='SAI_SESSION_INVALID';
  end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',v_auth_user_id,'session_id',p_session,
    'aal',session_aal,'role','authenticated')::text,true);
  perform set_config('request.jwt.claim.sub',v_auth_user_id::text,true);
  select * into strict ctx from app_private.require_superadmin_internal_context('forms.responses.read');
  if row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,
    ctx.scope_kind,ctx.scope_institution_id) is distinct from row(p_identity,p_link,p_membership,p_session,p_scope,p_institution)
    or ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
    or (ctx.scope_kind='institution' and ctx.scope_institution_id is null)
    or not exists(select 1 from auth.sessions s where s.id=p_session and s.user_id=v_auth_user_id
      and (s.not_after is null or s.not_after>clock_timestamp())) then
    raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
  end if;
  perform set_config('request.jwt.claims',coalesce(original_claims,''),true);
  perform set_config('request.jwt.claim.sub',coalesce(original_sub,''),true);
  return ctx;
exception when others then
  perform set_config('request.jwt.claims',coalesce(original_claims,''),true);
  perform set_config('request.jwt.claim.sub',coalesce(original_sub,''),true);
  raise;
end;
$$;


ALTER FUNCTION "app_private"."forms_media_read_context_v1"("p_identity" "uuid", "p_link" "uuid", "p_membership" "uuid", "p_session" "uuid", "p_scope" "text", "p_institution" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_media_read_token_immutable_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (to_jsonb(new)-'consumed_at') is distinct from (to_jsonb(old)-'consumed_at')
    or old.consumed_at is not null or new.consumed_at is null then
    raise check_violation using message='forms_media_read_token_immutable';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."forms_media_read_token_immutable_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_asset_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job public.form_file_jobs;
begin
  if new.catalog_kind<>'form-xlsx' then return new; end if;
  if tg_op='UPDATE' and old.status in ('quarantined','deleted') and new.status<>old.status
    and not (old.status='quarantined' and new.status='deleted') then
    raise check_violation using message='forms_xlsx_asset_revocation_final';
  end if;
  if tg_op='UPDATE' and row(new.export_file_job_id,new.expires_at,new.upload_request_id)
    is distinct from row(old.export_file_job_id,old.expires_at,old.upload_request_id) then
    raise check_violation using message='forms_xlsx_asset_binding_immutable';
  end if;
  select * into job from public.form_file_jobs where id=new.export_file_job_id for share;
  if job.id is null or job.artifact_provider<>'r2' or job.export_kind<>'xlsx'
    or row(job.form_id,job.institution_id,job.requested_by_internal_identity_id,job.expires_at)
      is distinct from row(new.form_id,new.institution_id,new.owner_internal_identity_id,new.expires_at)
  then raise check_violation using message='forms_xlsx_asset_scope_invalid'; end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."forms_xlsx_asset_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_complete_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job public.form_file_jobs; asset public.media_assets;
begin
  if tg_table_name='media_assets' then
    if new.catalog_kind<>'form-xlsx' then return null; end if;
    select * into asset from public.media_assets where id=new.id;
    select * into job from public.form_file_jobs where id=asset.export_file_job_id;
    if asset.status in ('pending','ready') and job.artifact_media_asset_id is distinct from asset.id then
      raise check_violation using message='forms_xlsx_attempt_not_current';
    end if;
  else select * into job from public.form_file_jobs where id=new.id; end if;
  if job.id is null or job.artifact_provider<>'r2' then return null; end if;
  if job.snapshot_ready and job.state<>'expired' and job.snapshot_row_count<>(
    select count(*) from app_private.form_xlsx_snapshot_rows where file_job_id=job.id
  ) then raise check_violation using message='forms_xlsx_snapshot_count_invalid'; end if;
  if job.artifact_media_asset_id is not null then
    select * into asset from public.media_assets where id=job.artifact_media_asset_id;
    if asset.id is null or asset.catalog_kind<>'form-xlsx'
      or row(asset.export_file_job_id,asset.form_id,asset.institution_id,asset.owner_internal_identity_id,asset.expires_at)
        is distinct from row(job.id,job.form_id,job.institution_id,job.requested_by_internal_identity_id,job.expires_at)
    then raise check_violation using message='forms_xlsx_job_asset_mismatch'; end if;
  end if;
  if job.state='succeeded' and (asset.id is null or asset.status<>'ready'
    or asset.byte_size is distinct from job.artifact_byte_length) then
    raise check_violation using message='forms_xlsx_original_required';
  end if;
  if asset.status='ready' and job.state<>'succeeded' then
    raise check_violation using message='forms_xlsx_job_completion_required';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "app_private"."forms_xlsx_complete_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_context_from_session_v1"("p_identity" "uuid", "p_link" "uuid", "p_membership" "uuid", "p_session" "uuid", "p_scope" "text", "p_institution" "uuid") RETURNS "app_private"."superadmin_internal_context"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; v_auth_user_id uuid; session_aal text;
  original_claims text:=current_setting('request.jwt.claims',true);
  original_sub text:=current_setting('request.jwt.claim.sub',true);
begin
  select session_record.user_id,session_record.aal::text into v_auth_user_id,session_aal
  from auth.sessions session_record
  join app_private.superadmin_internal_auth_links link on link.id=p_link
    and link.auth_user_id=session_record.user_id and link.internal_identity_id=p_identity
  where session_record.id=p_session and (session_record.not_after is null or session_record.not_after>clock_timestamp());
  if v_auth_user_id is null or session_aal is null or session_aal not in ('aal1','aal2') then
    raise insufficient_privilege using detail='SAI_SESSION_INVALID';
  end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',v_auth_user_id,'session_id',p_session,
    'aal',session_aal,'role','authenticated')::text,true);
  perform set_config('request.jwt.claim.sub',v_auth_user_id::text,true);
  select * into strict ctx from app_private.require_superadmin_internal_context('forms.responses.export');
  if row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,
    ctx.scope_kind,ctx.scope_institution_id) is distinct from row(p_identity,p_link,p_membership,p_session,p_scope,p_institution)
    or ctx.scope_kind not in ('platform','institution')
    or (ctx.scope_kind='institution' and ctx.scope_institution_id is null)
    or not exists(select 1 from auth.sessions s where s.id=p_session and s.user_id=v_auth_user_id
      and (s.not_after is null or s.not_after>clock_timestamp())) then
    raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
  end if;
  perform set_config('request.jwt.claims',coalesce(original_claims,''),true);
  perform set_config('request.jwt.claim.sub',coalesce(original_sub,''),true);
  return ctx;
exception when others then
  perform set_config('request.jwt.claims',coalesce(original_claims,''),true);
  perform set_config('request.jwt.claim.sub',coalesce(original_sub,''),true);
  raise;
end;
$$;


ALTER FUNCTION "app_private"."forms_xlsx_context_from_session_v1"("p_identity" "uuid", "p_link" "uuid", "p_membership" "uuid", "p_session" "uuid", "p_scope" "text", "p_institution" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_job_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op='UPDATE' and new.artifact_provider is distinct from old.artifact_provider then
    raise check_violation using message='forms_xlsx_job_origin_immutable';
  end if;
  if new.artifact_provider<>'r2' then return new; end if;
  if tg_op='UPDATE' and (
    row(new.id,new.form_id,new.institution_id,new.occurrence_id,new.export_kind,new.request_id,
      new.requested_by_internal_identity_id,new.requested_auth_link_id,new.requested_membership_id,
      new.requested_auth_session_id,new.requested_scope_kind,new.requested_scope_institution_id,
      new.requested_management_version,new.request_payload_sha256,new.snapshot_format_version,new.expires_at)
    is distinct from row(old.id,old.form_id,old.institution_id,old.occurrence_id,old.export_kind,old.request_id,
      old.requested_by_internal_identity_id,old.requested_auth_link_id,old.requested_membership_id,
      old.requested_auth_session_id,old.requested_scope_kind,old.requested_scope_institution_id,
      old.requested_management_version,old.request_payload_sha256,old.snapshot_format_version,old.expires_at)
    or (old.snapshot_ready and (not new.snapshot_ready or new.snapshot_row_count is distinct from old.snapshot_row_count
      or (new.snapshot_schema is distinct from old.snapshot_schema and not (
        old.snapshot_format_version=2 and old.state='expired' and new.state='expired'
        and old.snapshot_schema is not null and new.snapshot_schema is null
        and not exists(select 1 from app_private.form_xlsx_snapshot_rows s where s.file_job_id=old.id)))
      or new.snapshot_schema_sha256 is distinct from old.snapshot_schema_sha256))
    or (old.state='expired' and new.state<>'expired')
    or (old.state='succeeded' and (new.state not in ('succeeded','expired')
      or (new.state='succeeded' and row(new.artifact_media_asset_id,new.artifact_byte_length,new.manifest_jsonb)
        is distinct from row(old.artifact_media_asset_id,old.artifact_byte_length,old.manifest_jsonb))))
  ) then raise check_violation using message='forms_xlsx_job_identity_immutable'; end if;
  if not exists(select 1 from app_private.superadmin_internal_auth_links link
      where link.id=new.requested_auth_link_id and link.internal_identity_id=new.requested_by_internal_identity_id)
    or not exists(select 1 from app_private.superadmin_internal_memberships membership
      where membership.id=new.requested_membership_id and membership.internal_identity_id=new.requested_by_internal_identity_id)
  then raise check_violation using message='forms_xlsx_job_actor_mismatch'; end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."forms_xlsx_job_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_multipart_binding_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_job public.form_file_jobs; v_asset public.media_assets; v_worker app_private.form_worker_jobs;
begin
  if tg_op='UPDATE' and (new.artifact_provider,new.file_job_id,new.worker_job_id,new.bucket_id,new.object_path,
    new.upload_id,new.media_asset_id,new.worker_attempt,new.attempt_owner,new.snapshot_format_version,new.snapshot_row_count)
    is distinct from (old.artifact_provider,old.file_job_id,old.worker_job_id,old.bucket_id,old.object_path,
    old.upload_id,old.media_asset_id,old.worker_attempt,old.attempt_owner,old.snapshot_format_version,old.snapshot_row_count) then
    raise check_violation using message='forms_xlsx_multipart_origin_immutable';
  end if;
  select * into v_job from public.form_file_jobs where id=new.file_job_id;
  if v_job.artifact_provider is distinct from new.artifact_provider then
    raise check_violation using message='forms_xlsx_multipart_provider_mismatch';
  end if;
  if new.artifact_provider='r2' then
    select * into v_asset from public.media_assets where id=new.media_asset_id;
    select * into v_worker from app_private.form_worker_jobs where id=new.worker_job_id;
    if v_asset.id is null or v_asset.catalog_kind<>'form-xlsx' or v_asset.export_file_job_id<>v_job.id
      or v_asset.form_id<>v_job.form_id or v_asset.institution_id<>v_job.institution_id
      or v_asset.owner_internal_identity_id<>v_job.requested_by_internal_identity_id
      or v_asset.bucket_id<>new.bucket_id or v_asset.object_key<>new.object_path
      or v_asset.upload_request_id<>'xlsx:'||new.worker_job_id::text||':'||new.worker_attempt::text
      or v_worker.id is null or v_worker.job_kind<>'export_xlsx_r2_v1' or v_worker.aggregate_id<>v_job.id
      or new.snapshot_format_version<>v_job.snapshot_format_version or new.snapshot_row_count<>v_job.snapshot_row_count then
      raise check_violation using message='forms_xlsx_multipart_binding_mismatch';
    end if;
    if tg_op='INSERT' and (v_asset.status is distinct from 'pending' or v_job.artifact_media_asset_id is distinct from v_asset.id
      or v_worker.attempts is distinct from new.worker_attempt or v_worker.lease_owner is distinct from new.attempt_owner
      or v_worker.state is distinct from 'processing' or v_worker.lease_expires_at is null
      or v_worker.lease_expires_at<=clock_timestamp()) then
      raise check_violation using message='forms_xlsx_multipart_attempt_unavailable';
    end if;
    if tg_op='UPDATE' and old.state in ('completed','aborted') and
      (new.state,new.uploaded_bytes,new.next_part_number,new.checksum_sha256,new.completed_at,new.aborted_at)
      is distinct from (old.state,old.uploaded_bytes,old.next_part_number,old.checksum_sha256,old.completed_at,old.aborted_at) then
      raise check_violation using message='forms_xlsx_multipart_terminal_immutable';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."forms_xlsx_multipart_binding_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_multipart_projection_v1"("p_upload_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('bucket_id',m.bucket_id,'object_path',m.object_path,'upload_id',m.upload_id,
    'state',m.state,'next_part_number',m.next_part_number,'uploaded_bytes',m.uploaded_bytes,
    'checksum_sha256',m.checksum_sha256,
    'scope',jsonb_build_object('worker_job_id',m.worker_job_id,'worker_id',m.attempt_owner,
      'file_job_id',m.file_job_id,'attempt',m.worker_attempt,'asset_id',m.media_asset_id,
      'bucket',m.bucket_id,'object_key',m.object_path,'snapshot_format_version',m.snapshot_format_version,
      'snapshot_row_count',m.snapshot_row_count),
    'parts',coalesce((select jsonb_agg(jsonb_build_object('part_number',p.part_number,'etag',p.etag,
      'byte_length',p.byte_length,'checksum_sha256',p.checksum_sha256) order by p.part_number)
      from app_private.form_multipart_parts p where p.multipart_upload_id=m.id),'[]'::jsonb))
  from app_private.form_multipart_uploads m where m.id=p_upload_id and m.artifact_provider='r2';
$$;


ALTER FUNCTION "app_private"."forms_xlsx_multipart_projection_v1"("p_upload_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_snapshot_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare job public.form_file_jobs;
begin
  if tg_op='UPDATE' then raise check_violation using message='forms_xlsx_snapshot_immutable'; end if;
  if tg_op='DELETE' then
    select * into job from public.form_file_jobs where id=old.file_job_id for share;
    if job.id is not null and job.state<>'expired' then
      raise check_violation using message='forms_xlsx_snapshot_immutable';
    end if;
    return old;
  end if;
  select * into job from public.form_file_jobs where id=new.file_job_id for share;
  if job.id is null or job.artifact_provider<>'r2' or job.snapshot_ready or job.state<>'pending'
    or (job.snapshot_format_version=1 and new.submission_jsonb->>'responseId' is distinct from new.response_id::text)
    or (job.snapshot_format_version=2 and (
      new.submission_jsonb->>'responseId' is null
      or new.submission_jsonb->>'responseId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or not exists(select 1 from public.form_responses r where r.id=new.response_id
        and r.form_id=job.form_id and r.institution_id=job.institution_id
        and r.occurrence_id::text=new.submission_jsonb->>'occurrenceId'
        and r.form_version_id::text=new.submission_jsonb->>'versionId'
        and r.identity_mode=new.submission_jsonb#>>'{metadata,identity_mode}'
        and case when r.identity_mode='identified' then new.submission_jsonb->>'responseId'=r.id::text
          else new.submission_jsonb->>'responseId'<>r.id::text
            and ((new.submission_jsonb->'metadata') - array['form_id','identity_mode'])='{}'::jsonb end)))
    or new.submission_jsonb#>>'{metadata,form_id}' is distinct from job.form_id::text
  then raise check_violation using message='forms_xlsx_snapshot_scope_invalid'; end if;
  return new;
end;
$_$;


ALTER FUNCTION "app_private"."forms_xlsx_snapshot_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_token_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job public.form_file_jobs;
begin
  if tg_op='UPDATE' and (old.actor_internal_identity_id is not null or new.actor_internal_identity_id is not null) then
    if row(new.id,new.file_job_id,new.actor_person_id,new.actor_internal_identity_id,new.actor_auth_link_id,
      new.actor_membership_id,new.actor_auth_session_id,new.actor_scope_kind,new.actor_scope_institution_id,
      new.actor_aal,new.media_asset_id,new.token_hash,new.expires_at,new.created_at)
      is distinct from row(old.id,old.file_job_id,old.actor_person_id,old.actor_internal_identity_id,old.actor_auth_link_id,
      old.actor_membership_id,old.actor_auth_session_id,old.actor_scope_kind,old.actor_scope_institution_id,
      old.actor_aal,old.media_asset_id,old.token_hash,old.expires_at,old.created_at)
      or (old.consumed_at is not null and new.consumed_at is distinct from old.consumed_at) then
      raise check_violation using message='forms_xlsx_token_immutable';
    end if;
    return new;
  end if;
  if new.actor_internal_identity_id is null then return new; end if;
  select * into job from public.form_file_jobs where id=new.file_job_id for share;
  if job.id is null or job.artifact_provider<>'r2' or job.state<>'succeeded'
    or job.artifact_media_asset_id is distinct from new.media_asset_id
    or job.requested_by_internal_identity_id is distinct from new.actor_internal_identity_id
    or new.expires_at>job.expires_at
    or (new.actor_scope_kind='institution' and new.actor_scope_institution_id is distinct from job.institution_id)
    or not exists(select 1 from app_private.superadmin_internal_auth_links link
      where link.id=new.actor_auth_link_id and link.internal_identity_id=new.actor_internal_identity_id)
    or not exists(select 1 from app_private.superadmin_internal_memberships membership
      where membership.id=new.actor_membership_id and membership.internal_identity_id=new.actor_internal_identity_id)
  then raise check_violation using message='forms_xlsx_token_scope_invalid'; end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."forms_xlsx_token_guard_v1"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."form_file_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "form_id" "uuid" NOT NULL,
    "occurrence_id" "uuid",
    "requested_by_person_id" "uuid",
    "request_id" "uuid" NOT NULL,
    "export_kind" "text" NOT NULL,
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "progress" numeric(5,4) DEFAULT 0 NOT NULL,
    "artifact_path" "text",
    "artifact_byte_length" bigint,
    "manifest_jsonb" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "error_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '24:00:00'::interval) NOT NULL,
    "artifact_provider" "text" DEFAULT 'supabase_mvp'::"text" NOT NULL,
    "artifact_media_asset_id" "uuid",
    "requested_by_internal_identity_id" "uuid",
    "requested_auth_link_id" "uuid",
    "requested_membership_id" "uuid",
    "requested_auth_session_id" "uuid",
    "requested_scope_kind" "text",
    "requested_scope_institution_id" "uuid",
    "requested_management_version" bigint,
    "request_payload_sha256" "text",
    "snapshot_format_version" integer,
    "snapshot_row_count" bigint,
    "snapshot_schema" "jsonb",
    "snapshot_schema_sha256" "text",
    "snapshot_ready" boolean DEFAULT false NOT NULL,
    CONSTRAINT "form_file_jobs_artifact_ck" CHECK ((("artifact_path" IS NULL) OR ("artifact_path" ~ '^[0-9a-f]{2}/[0-9a-f-]{36}$'::"text"))),
    CONSTRAINT "form_file_jobs_kind_ck" CHECK (("export_kind" = ANY (ARRAY['csv'::"text", 'xlsx'::"text", 'zip'::"text", 'anonymous_participation'::"text"]))),
    CONSTRAINT "form_file_jobs_progress_ck" CHECK ((("progress" >= (0)::numeric) AND ("progress" <= (1)::numeric))),
    CONSTRAINT "form_file_jobs_provider_shape_ck" CHECK ((((("artifact_provider" = 'supabase_mvp'::"text") AND ("requested_by_person_id" IS NOT NULL) AND ("artifact_media_asset_id" IS NULL) AND ("requested_by_internal_identity_id" IS NULL) AND ("requested_auth_link_id" IS NULL) AND ("requested_membership_id" IS NULL) AND ("requested_auth_session_id" IS NULL) AND ("requested_scope_kind" IS NULL) AND ("requested_scope_institution_id" IS NULL) AND ("requested_management_version" IS NULL) AND ("request_payload_sha256" IS NULL) AND ("snapshot_format_version" IS NULL) AND ("snapshot_row_count" IS NULL) AND ("snapshot_schema" IS NULL) AND ("snapshot_schema_sha256" IS NULL) AND (NOT "snapshot_ready")) OR (("artifact_provider" = 'r2'::"text") AND ("requested_by_person_id" IS NULL) AND ("requested_by_internal_identity_id" IS NOT NULL) AND ("requested_auth_link_id" IS NOT NULL) AND ("requested_membership_id" IS NOT NULL) AND ("requested_auth_session_id" IS NOT NULL) AND ("requested_scope_kind" = ANY (ARRAY['platform'::"text", 'institution'::"text"])) AND ((("requested_scope_kind" = 'platform'::"text") AND ("requested_scope_institution_id" IS NULL)) OR (("requested_scope_kind" = 'institution'::"text") AND ("requested_scope_institution_id" = "institution_id"))) AND ("export_kind" = 'xlsx'::"text") AND ("occurrence_id" IS NULL) AND ("artifact_path" IS NULL) AND ("requested_management_version" IS NOT NULL) AND ("requested_management_version" >= 0) AND ("request_payload_sha256" IS NOT NULL) AND ("request_payload_sha256" ~ '^[0-9a-f]{64}$'::"text") AND ("snapshot_format_version" = ANY (ARRAY[1, 2])) AND ("snapshot_row_count" IS NOT NULL) AND ("snapshot_row_count" >= 0) AND (("snapshot_format_version" = 1) OR (NOT "snapshot_ready") OR (("jsonb_typeof"("snapshot_schema") = 'object'::"text") AND (("snapshot_schema" ->> 'formId'::"text") = ("form_id")::"text") AND ("jsonb_typeof"(("snapshot_schema" -> 'versions'::"text")) = 'array'::"text") AND ("snapshot_schema_sha256" = "encode"("extensions"."digest"("convert_to"(("snapshot_schema")::"text", 'UTF8'::"name"), 'sha256'::"text"), 'hex'::"text"))) OR (("state" = 'expired'::"text") AND ("snapshot_schema" IS NULL) AND ("snapshot_schema_sha256" ~ '^[0-9a-f]{64}$'::"text"))) AND (("state" <> 'succeeded'::"text") OR ("snapshot_ready" AND ("artifact_media_asset_id" IS NOT NULL) AND ("artifact_byte_length" IS NOT NULL) AND ("artifact_byte_length" > 0) AND ("completed_at" IS NOT NULL))))) IS TRUE)),
    CONSTRAINT "form_file_jobs_state_ck" CHECK (("state" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'succeeded'::"text", 'partial'::"text", 'failed'::"text", 'expired'::"text"])))
);

