CREATE OR REPLACE FUNCTION "app_private"."forms_xlsx_worker_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_asset_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."form_file_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_worker app_private.form_worker_jobs; v_job public.form_file_jobs;
  v_ctx app_private.superadmin_internal_context;
begin
  if current_setting('transaction_isolation')<>'read committed' or p_job_id is null or p_file_job_id is null
    or p_worker_id is null or length(p_worker_id) not between 1 and 240 then
    raise invalid_parameter_value using message='forms_xlsx_worker_input_invalid';
  end if;
  select * into v_worker from app_private.form_worker_jobs where id=p_job_id
    and aggregate_id=p_file_job_id and job_kind='export_xlsx_r2_v1'
    and state='processing' and lease_owner=p_worker_id and lease_expires_at>clock_timestamp() for update;
  if v_worker.id is null then raise serialization_failure using message='forms_xlsx_lease_unavailable'; end if;
  select j.* into v_job from public.form_file_jobs j join public.forms f on f.id=j.form_id and f.institution_id=j.institution_id
    join public.institutions i on i.id=j.institution_id and i.deleted_at is null
    where j.id=p_file_job_id and j.artifact_provider='r2' and j.export_kind='xlsx' and j.snapshot_ready
      and j.state in ('pending','processing','failed') and j.expires_at>clock_timestamp() for update of j;
  if v_job.id is null then raise no_data_found using message='forms_xlsx_job_unavailable'; end if;
  v_ctx:=app_private.forms_xlsx_context_from_session_v1(v_job.requested_by_internal_identity_id,v_job.requested_auth_link_id,
    v_job.requested_membership_id,v_job.requested_auth_session_id,v_job.requested_scope_kind,v_job.requested_scope_institution_id);
  if v_ctx.scope_kind='institution' and v_ctx.scope_institution_id is distinct from v_job.institution_id then
    raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
  end if;
  if p_asset_id is not null and (v_job.artifact_media_asset_id is distinct from p_asset_id
    or not exists(select 1 from public.media_assets a where a.id=p_asset_id and a.export_file_job_id=v_job.id
      and a.status='pending' and a.catalog_kind='form-xlsx'
      and a.upload_request_id='xlsx:'||v_worker.id::text||':'||v_worker.attempts::text)) then
    raise serialization_failure using message='forms_xlsx_attempt_unavailable';
  end if;
  if v_worker.lease_expires_at<=clock_timestamp() or v_job.expires_at<=clock_timestamp() then
    raise serialization_failure using message='forms_xlsx_lease_unavailable';
  end if;
  return v_job;
end;
$$;


ALTER FUNCTION "app_private"."forms_xlsx_worker_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_file_job_id" "uuid", "p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."generate_person_handle"("p_first_name" "text", "p_last_name" "text", "p_display_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  first_part text := app_private.person_handle_slug(coalesce(nullif(p_first_name,''), split_part(coalesce(p_display_name,''), ' ', 1)));
  last_part text := app_private.person_handle_slug(coalesce(nullif(p_last_name,''),
    nullif(regexp_replace(coalesce(p_display_name,''), '^\S+\s*', ''), '')));
  base text;
  candidate text;
  suffix integer := 0;
begin
  base := case
    when first_part <> '' and last_part <> '' then left(first_part, 14) || '.' || left(last_part, 15)
    when first_part <> '' then left(first_part, 30)
    when last_part <> '' then left(last_part, 30)
    else 'pessoa' end;
  if length(base) < 3 then base := rpad(base, 3, '0'); end if;
  candidate := base;
  while app_private.person_handle_is_reserved(candidate)
     or exists (select 1 from public.person_handles h
                where h.normalized_handle = candidate and h.status = 'active' and h.revoked_at is null) loop
    suffix := suffix + 1;
    candidate := left(base, 30 - length(suffix::text)) || suffix::text;
    if suffix > 9999 then
      candidate := left('pessoa' || replace(gen_random_uuid()::text, '-', ''), 30);
    end if;
  end loop;
  return candidate;
end
$$;


ALTER FUNCTION "app_private"."generate_person_handle"("p_first_name" "text", "p_last_name" "text", "p_display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."get_institution_for_superadmin"("p_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid;
  result jsonb;
begin
  if (select auth.uid()) is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  actor_person_id := app_private.current_person_id();
  if actor_person_id is null then
    raise insufficient_privilege using message = 'active person identity required';
  end if;
  if not app_private.has_scoped_platform_permission('platform.read', p_institution_id) then
    raise insufficient_privilege using message = 'platform.read required';
  end if;
  result := app_private.institution_management_payload(p_institution_id);
  if result is null then
    raise no_data_found using message = 'institution not found';
  end if;
  return result;
end;
$$;


ALTER FUNCTION "app_private"."get_institution_for_superadmin"("p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."get_superadmin_person"("p_person_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  perform app_private.assert_people_permission('people.read');

  select jsonb_build_object(
    'id', person.id,
    'person_type', person.person_type,
    'first_name', person.first_name,
    'last_name', person.last_name,
    'display_name', person.display_name,
    'legal_name', person.legal_name,
    'status', person.status,
    'updated_at', person.updated_at,
    'auth_summary', jsonb_build_object(
      'has_active_login', exists (
        select 1 from public.person_auth_links auth_link
        where auth_link.person_id = person.id
          and auth_link.status = 'active'
          and auth_link.revoked_at is null
      ),
      'active_link_count', (
        select count(*) from public.person_auth_links auth_link
        where auth_link.person_id = person.id
          and auth_link.status = 'active'
          and auth_link.revoked_at is null
      )
    ),
    'platform_memberships', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', membership.id,
        'role_code', role.code,
        'status', membership.status,
        'scope_kind', membership.scope_kind,
        'scope_institution_id', membership.scope_institution_id
      ) order by role.code, membership.id)
      from public.platform_memberships membership
      join public.platform_roles role on role.id = membership.role_id
      where membership.person_id = person.id
    ), '[]'::jsonb),
    'institution_memberships', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', membership.id,
        'institution_id', membership.institution_id,
        'role_code', membership.role_code,
        'status', membership.status,
        'scope_kind', membership.scope_kind,
        'scope_unit_id', membership.scope_unit_id,
        'scope_group_id', membership.scope_group_id
      ) order by membership.created_at, membership.id)
      from public.institution_memberships membership
      where membership.person_id = person.id
    ), '[]'::jsonb),
    'child_contexts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', child_context.id,
        'institution_id', child_context.institution_id,
        'status', child_context.status,
        'units', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', unit_link.id,
            'unit_id', unit_link.unit_id,
            'status', unit_link.status,
            'groups', coalesce((
              select jsonb_agg(jsonb_build_object(
                'id', group_link.id,
                'group_id', group_link.group_id,
                'status', group_link.status
              ) order by group_link.created_at, group_link.id)
              from public.child_group_links group_link
              where group_link.child_unit_link_id = unit_link.id
            ), '[]'::jsonb)
          ) order by unit_link.created_at, unit_link.id)
          from public.child_unit_links unit_link
          where unit_link.child_context_id = child_context.id
        ), '[]'::jsonb)
      ) order by child_context.created_at, child_context.id)
      from public.child_contexts child_context
      where child_context.child_person_id = person.id
    ), '[]'::jsonb),
    'guardian_summary', jsonb_build_object(
      'as_guardian_count', (
        select count(*) from public.guardian_links guardian_link
        where guardian_link.guardian_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ),
      'guardian_count', (
        select count(*) from public.guardian_links guardian_link
        where guardian_link.child_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      )
    )
  )
  into result
  from public.people person
  where person.id = p_person_id
    and person.deleted_at is null;

  if result is null then
    raise no_data_found using message = 'person not found';
  end if;
  return result;
end
$$;


ALTER FUNCTION "app_private"."get_superadmin_person"("p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."get_unit_form_for_superadmin"("p_unit_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$declare t uuid;begin
if(select auth.uid())is null or app_private.current_person_id()is null then raise insufficient_privilege using message='authentication required';end if;
if p_unit_id is not null then select institution_id into t from public.units where id=p_unit_id;
if t is null then return jsonb_build_object('unit',null,'not_found',true,'institutions','[]'::jsonb,'unit_types','[]'::jsonb,'plans','[]'::jsonb);end if;
if not app_private.has_scoped_platform_permission('units.read',t)then raise insufficient_privilege using message='units.read required';end if;end if;
return jsonb_build_object('unit',case when p_unit_id is null then null else app_private.unit_form_payload(p_unit_id)end,'not_found',false,
'institutions',coalesce((select jsonb_agg(jsonb_build_object('institution_id',i.id,'institution_name',i.public_name,
'institution_type',jsonb_build_object('id',i.institution_type_id,'label',it.name),'effective_plan',jsonb_build_object('id',sub.plan_id,'code',p.code,'label',p.name))order by i.public_name)
from public.institutions i left join public.institution_types it on it.id=i.institution_type_id
left join lateral(select s.plan_id from public.institution_subscriptions s where s.institution_id=i.id and s.status not in('cancelled','suspended')order by s.created_at desc,s.id desc limit 1)sub on true
left join public.plans p on p.id=sub.plan_id where i.deleted_at is null and app_private.has_scoped_platform_permission('units.read',i.id)),'[]'::jsonb),
'unit_types',coalesce((select jsonb_agg(jsonb_build_object('id',id,'label',name,'code',code)order by name)from public.unit_types where status='active'),'[]'::jsonb),
'plans',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'label',p.name,'code',p.code)order by p.name)from public.plans p where p.status='active'),'[]'::jsonb));end$$;


ALTER FUNCTION "app_private"."get_unit_form_for_superadmin"("p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."group_location_authorize_v2"("p_permissions" "text"[], "p_expected" "app_private"."superadmin_internal_context" DEFAULT NULL::"app_private"."superadmin_internal_context") RETURNS "app_private"."superadmin_internal_context"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; fresh app_private.superadmin_internal_context; permission text;
begin
 if coalesce(cardinality(p_permissions),0)=0 then raise invalid_parameter_value; end if;
 select * into strict ctx from app_private.require_superadmin_internal_context(p_permissions[1]);
 foreach permission in array p_permissions loop
   select * into strict fresh from app_private.require_superadmin_internal_context(permission);
   if row(fresh.internal_identity_id,fresh.internal_auth_link_id,fresh.internal_membership_id,
     fresh.auth_user_id,fresh.session_id,fresh.platform_role_id,fresh.scope_kind,fresh.scope_institution_id,fresh.aal)
     is distinct from row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
     ctx.auth_user_id,ctx.session_id,ctx.platform_role_id,ctx.scope_kind,ctx.scope_institution_id,ctx.aal) then
     raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
   end if;
 end loop;
 if p_expected.internal_identity_id is not null and ctx is distinct from p_expected then
   raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
 end if;
 if not exists(select 1 from auth.sessions s where s.id=ctx.session_id and s.user_id=ctx.auth_user_id
   and (s.not_after is null or s.not_after>clock_timestamp())) then
   raise insufficient_privilege using detail='SAI_SESSION_INVALID';
 end if;
 return ctx;
end $$;


ALTER FUNCTION "app_private"."group_location_authorize_v2"("p_permissions" "text"[], "p_expected" "app_private"."superadmin_internal_context") OWNER TO "postgres";


