    select id into permission_id from public.institution_permissions where code=new.permission_code and status='active';
    if permission_id is null or not app_private.access_profile_can_delegate_institution(permission_id) then
      raise insufficient_privilege using message='cannot delegate institution capability';
    end if;
  end if;
