CREATE OR REPLACE FUNCTION "app_private"."has_institution_permission"("target_institution_id" "uuid", "target_permission_code" "text", "target_unit_id" "uuid" DEFAULT NULL::"uuid", "target_group_id" "uuid" DEFAULT NULL::"uuid", "require_institution_scope" boolean DEFAULT false) RETURNS boolean
