COMMENT ON FUNCTION "app_private"."has_mfa_aal2"() IS 'MVP (ADR 0034, Decisao 12): sessao autenticada aal1 ou aal2 satisfaz o portao. Reverter para = ''aal2'' ao reativar a ADR 0019.';



CREATE OR REPLACE FUNCTION "app_private"."has_platform_permission"("permission_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select app_private.has_platform_permission(permission_code, null::uuid)
$$;


ALTER FUNCTION "app_private"."has_platform_permission"("permission_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."has_platform_permission"("permission_code" "text") IS 'Delegado de has_platform_permission(text, null): qualquer membership ativa (plataforma ou instituicao) conta.';



CREATE OR REPLACE FUNCTION "app_private"."has_platform_permission"("permission_code" "text", "institution_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with internal_actor as (
    select exists (
      select 1 from app_private.superadmin_internal_auth_links auth_link
      where auth_link.auth_user_id = (select auth.uid())
        and auth_link.status = 'active'
    ) as is_internal
  ), memberships as (
    select membership.id, membership.role_id
    from public.platform_memberships membership
    join public.platform_roles role_record on role_record.id = membership.role_id
    cross join internal_actor
    where membership.person_id = app_private.current_person_id()
      and membership.status = 'active' and membership.revoked_at is null
      and role_record.status = 'active'
      and (
        (membership.scope_kind = 'platform' and membership.scope_institution_id is null)
        or (
          membership.scope_kind = 'institution'
          and membership.scope_institution_id is not null
          and (
            membership.scope_institution_id = institution_id
            -- P7: pessoa do realm people-based conta a membership de instituicao
            -- mesmo sem instituicao informada; espelho de identidade interna
            -- escopada, nunca (a instituicao precisa ser informada e coincidir).
            or (institution_id is null and not internal_actor.is_internal)
          )
        )
      )
  ), target as (
    select id from public.platform_permissions
    where code = permission_code and status = 'active'
  ), effects as (
    select grant_record.effect from memberships
    join public.platform_role_permissions grant_record
      on grant_record.role_id = memberships.role_id
     and grant_record.status = 'active' and grant_record.revoked_at is null
    join target on target.id = grant_record.permission_id
    union all
    select override_record.effect from memberships
    join public.platform_member_permission_overrides override_record
      on override_record.membership_id = memberships.id
     and override_record.status = 'active'
     and (override_record.starts_at is null or override_record.starts_at <= now())
     and (override_record.expires_at is null or override_record.expires_at > now())
    join target on target.id = override_record.permission_id
  )
  select exists(select 1 from effects where effect = 'allow')
     and not exists(select 1 from effects where effect = 'deny')
$$;


ALTER FUNCTION "app_private"."has_platform_permission"("permission_code" "text", "institution_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."has_platform_permission"("permission_code" "text", "institution_id" "uuid") IS 'P7 (ADR 0034, Decisao 12) + raiz da ponte de ator (R06): memberships de plataforma e de instituicao contam; com institution_id, a de instituicao so vale para aquela instituicao; para identidade interna (superadmin_internal_auth_links) a membership espelhada com escopo de instituicao nunca conta sem institution_id. Deny vence allow; sem membership ativa, false.';



CREATE OR REPLACE FUNCTION "app_private"."has_scoped_platform_permission"("p_permission_code" "text", "p_institution_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with active_memberships as (
    select
      membership.id as membership_id,
      membership.role_id,
      role_record.code as role_code
    from public.platform_memberships membership
    join public.platform_roles role_record
      on role_record.id = membership.role_id
     and role_record.status = 'active'
    where membership.person_id = app_private.current_person_id()
      and membership.status = 'active'
      and membership.revoked_at is null
      and (
        not membership.mfa_required
        or app_private.has_mfa_aal2()
      )
      and (
        (
          p_institution_id is null
          and membership.scope_kind = 'platform'
          and membership.scope_institution_id is null
        )
        or (
          p_institution_id is not null
          and (
            (
              membership.scope_kind = 'platform'
              and membership.scope_institution_id is null
            )
            or (
              membership.scope_kind = 'institution'
              and membership.scope_institution_id = p_institution_id
            )
          )
        )
      )
  ),
  target_permission as (
    select permission_record.id
    from public.platform_permissions permission_record
    where permission_record.code = p_permission_code
      and permission_record.status = 'active'
  )
  select coalesce(exists (
    select 1
    from active_memberships membership
    cross join target_permission permission_record
    where not exists (
      select 1
      from public.platform_member_permission_overrides permission_override
      where permission_override.membership_id = membership.membership_id
        and permission_override.permission_id = permission_record.id
        and permission_override.status = 'active'
        and permission_override.effect = 'deny'
        and (
          permission_override.starts_at is null
          or permission_override.starts_at <= pg_catalog.now()
        )
        and (
          permission_override.expires_at is null
          or permission_override.expires_at > pg_catalog.now()
        )
    )
      and (
        membership.role_code = 'owner'
        or exists (
         select 1
         from public.platform_member_permission_overrides permission_override
         where permission_override.membership_id = membership.membership_id
           and permission_override.permission_id = permission_record.id
           and permission_override.status = 'active'
           and permission_override.effect = 'allow'
           and (
             permission_override.starts_at is null
             or permission_override.starts_at <= pg_catalog.now()
           )
           and (
             permission_override.expires_at is null
             or permission_override.expires_at > pg_catalog.now()
           )
       )
        or exists (
          select 1
          from public.platform_role_permissions role_permission
          where role_permission.role_id = membership.role_id
            and role_permission.permission_id = permission_record.id
            and role_permission.status = 'active'
            and role_permission.revoked_at is null
            and role_permission.effect = 'allow'
        )
      )
  ), false)
$$;


ALTER FUNCTION "app_private"."has_scoped_platform_permission"("p_permission_code" "text", "p_institution_id" "uuid") OWNER TO "postgres";


