CREATE OR REPLACE FUNCTION "app_private"."health_care_profile_for_guardian"("p_child_context_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  profile_row public.health_care_profiles;
begin
  if actor is null then
    raise insufficient_privilege using message='authentication required';
  end if;
  if p_child_context_id is null
    or not app_private.guardian_has_capability(p_child_context_id, 'view_health_care') then
    -- Negativa opaca: a mesma resposta para uma crianca que nao existe e para
    -- uma que existe e nao e sua.
    raise no_data_found using message='health care profile unavailable';
  end if;
  select * into profile_row
  from public.health_care_profiles
  where child_context_id = p_child_context_id;
  if profile_row.id is null then
    raise no_data_found using message='health care profile unavailable';
  end if;

  return jsonb_build_object(
    'id', profile_row.id,
    'child_context_id', profile_row.child_context_id,
    'operational_status', profile_row.operational_status,
    'important_signs', profile_row.important_signs,
    'adaptations', profile_row.adaptations,
    -- A projecao para a familia nao carrega a versao esperada do agregado nem
    -- a marca de quem pode gerir: o responsavel nao edita, entao entregar isso
    -- seria entregar municao para uma escrita que o servidor recusaria.
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'catalog_item_id', item_row.catalog_item_id,
        'other_text', item_row.other_text) order by item_row.catalog_item_id)
      from public.health_care_profile_items item_row
      where item_row.profile_id = profile_row.id), '[]'::jsonb),
    'allergies', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', allergy_row.id,
        'label', allergy_row.label,
        'allergy_type', allergy_row.allergy_type,
        'status', allergy_row.status,
        'active', allergy_row.active,
        'last_episode_at', allergy_row.last_episode_at,
        'episode_severity', allergy_row.episode_severity,
        'observed_reaction', allergy_row.observed_reaction,
        'guidance', allergy_row.guidance,
        'notes', allergy_row.notes) order by allergy_row.created_at)
      from public.health_care_allergies allergy_row
      where allergy_row.profile_id = profile_row.id), '[]'::jsonb)
    -- A trilha com justificativa fica de fora: ela e da instituicao e mostra
    -- quem mudou o que. Nao e projecao minima para a familia.
  );
end
$$;


ALTER FUNCTION "app_private"."health_care_profile_for_guardian"("p_child_context_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."health_care_receipt"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  receipt app_private.health_care_command_receipts%rowtype;
begin
  if p_request_id is null then
    raise invalid_parameter_value using message='request id required';
  end if;
  select * into receipt
  from app_private.health_care_command_receipts
  where request_id = p_request_id;
  if receipt.request_id is null then
    return null;
  end if;
  if receipt.actor_person_id is distinct from p_actor
    or receipt.command is distinct from p_command then
    raise invalid_parameter_value using message='request id reused for another command';
  end if;
  return receipt.response;
end
$$;


ALTER FUNCTION "app_private"."health_care_receipt"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."health_care_resolve_child_context"("p_child_context_id" "uuid", "p_child_person_id" "uuid", "p_institution_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  resolved uuid;
  candidates integer;
begin
  if p_child_context_id is not null then
    select child_row.id into resolved
    from public.child_contexts child_row
    where child_row.id = p_child_context_id
      and child_row.status = 'active'
      and (p_child_person_id is null
        or child_row.child_person_id = p_child_person_id)
      and (p_institution_id is null
        or child_row.institution_id = p_institution_id);
    return resolved;
  end if;
  if p_child_person_id is null then
    return null;
  end if;
  -- Postgres nao agrega uuid, entao a contagem e a escolha saem da mesma
  -- varredura por array em vez de min().
  select array_length(found.ids, 1), found.ids[1] into candidates, resolved
  from (
    select array_agg(child_row.id order by child_row.id) as ids
    from public.child_contexts child_row
    where child_row.child_person_id = p_child_person_id
      and child_row.status = 'active'
      and (p_institution_id is null or child_row.institution_id = p_institution_id)
  ) found;
  if coalesce(candidates, 0) <> 1 then
    -- Zero: nao existe. Mais de um: a instituicao precisa ser dita. Nos dois
    -- casos, adivinhar seria escrever dado de saude no lugar errado.
    return null;
  end if;
  return resolved;
end
$$;


ALTER FUNCTION "app_private"."health_care_resolve_child_context"("p_child_context_id" "uuid", "p_child_person_id" "uuid", "p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."health_care_scope_allowed"("p_permission" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_child_context_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_institution_id is not null
    and (
      app_private.has_platform_permission(p_permission)
      or app_private.has_context_permission(
        p_institution_id, p_permission, p_unit_id, p_group_id, null,
        p_child_context_id, false
      )
      or (
        p_permission in ('health_care.read', 'medication.read')
        and p_child_context_id is not null
        and app_private.guardian_has_capability(p_child_context_id, 'view_health_care')
      )
    )
$$;


ALTER FUNCTION "app_private"."health_care_scope_allowed"("p_permission" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_child_context_id" "uuid") OWNER TO "postgres";


