    AS $$
  update public.circular_media_assets set status=case
    when coalesce(upload_authorized_until,created_at)+interval '5 minutes'<now() then 'deleted'::public.circular_media_status
    else 'orphaned'::public.circular_media_status
  end where id=p_asset_id and status='orphaned'
$$;


