CREATE OR REPLACE FUNCTION "app_private"."mask_cpf_v1"("p_digits" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select '***.***.***-' || pg_catalog.right(p_digits, 2)
$$;


ALTER FUNCTION "app_private"."mask_cpf_v1"("p_digits" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."mask_email_v1"("p_email" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_email is null then null
    else pg_catalog.left(pg_catalog.split_part(p_email, '@', 1), 1) || '***@'
      || pg_catalog.split_part(p_email, '@', 2)
  end
$$;


ALTER FUNCTION "app_private"."mask_email_v1"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."mask_phone_v1"("p_digits" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_digits is null then null
    else pg_catalog.repeat('*', greatest(pg_catalog.char_length(p_digits) - 4, 0))
      || pg_catalog.right(p_digits, 4)
  end
$$;


ALTER FUNCTION "app_private"."mask_phone_v1"("p_digits" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."materialize_notice_publication_job"("p_job_id" "uuid", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job app_private.notice_publication_jobs;
  rule jsonb; dimension text; role_codes jsonb; plan_ids jsonb; excluded jsonb;
  search_term text; search_pattern text;
  page_count integer; last_key text;
begin
  if auth.role() is distinct from 'service_role' or p_limit not between 1 and 5000 then
    raise exception using errcode = '42501', message = 'not_authorized';
  end if;
  select * into job from app_private.notice_publication_jobs
  where id = p_job_id and state = 'processing' for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'publication_job_not_found';
  end if;

  rule := coalesce(job.audience_snapshot -> 'rules' -> 0, '{}'::jsonb);
  dimension := coalesce(rule ->> 'dimension', 'platform');
  role_codes := coalesce(job.audience_snapshot -> 'role_codes', '[]'::jsonb);
  plan_ids := coalesce(job.audience_snapshot -> 'plan_ids', '[]'::jsonb);
  excluded := coalesce(rule -> 'excluded_ids', '[]'::jsonb);
  search_term := nullif(trim(coalesce(rule -> 'filters' -> 'search' ->> 0, '')), '');
  search_pattern := case when search_term is null then null
    else '%' || replace(replace(replace(search_term, '\', '\\'), '%', '\%'), '_', '\_') || '%' end;

  with institutional_candidates as (
    select distinct membership.person_id, membership.institution_id,
      membership.person_id::text || ':' || membership.institution_id::text as recipient_key
    from public.institution_memberships membership
    where membership.status = 'active'::public.record_status
      and membership.revoked_at is null
      and (jsonb_array_length(coalesce(rule -> 'filters' -> 'institution_ids', '[]'::jsonb)) = 0
        or rule -> 'filters' -> 'institution_ids' ? membership.institution_id::text)
      and (jsonb_array_length(coalesce(rule -> 'filters' -> 'unit_ids', '[]'::jsonb)) = 0
        or rule -> 'filters' -> 'unit_ids' ? membership.scope_unit_id::text
        or exists (select 1 from public.groups filter_group
          where filter_group.id = membership.scope_group_id
            and rule -> 'filters' -> 'unit_ids' ? filter_group.unit_id::text))
      and (jsonb_array_length(role_codes) = 0 or role_codes ? membership.role_code)
      and (jsonb_array_length(plan_ids) = 0 or exists (
        select 1 from public.institution_subscriptions subscription
        where subscription.institution_id = membership.institution_id
          and subscription.status::text in ('active', 'trial')
          and plan_ids ? subscription.plan_id::text))
      and (search_pattern is null or case dimension
        when 'institution' then exists (select 1 from public.institutions institution
          where institution.id = membership.institution_id
            and institution.public_name ilike search_pattern escape '\')
        when 'unit' then exists (select 1 from public.units unit
          where (unit.id = membership.scope_unit_id or unit.id = (select scoped_group.unit_id
              from public.groups scoped_group where scoped_group.id = membership.scope_group_id))
            and unit.name ilike search_pattern escape '\')
        when 'group' then exists (select 1 from public.groups scoped_group
          where scoped_group.id = membership.scope_group_id
            and scoped_group.name ilike search_pattern escape '\')
        else true end)
      and case dimension
        when 'platform' then true
        when 'institution' then (
          (coalesce((rule ->> 'select_all')::boolean, false)
            or rule -> 'target_ids' ? membership.institution_id::text)
          and not (excluded ? membership.institution_id::text))
        when 'unit' then (
          (coalesce((rule ->> 'select_all')::boolean, false)
            or rule -> 'target_ids' ? membership.scope_unit_id::text
            or exists (select 1 from public.groups scoped_group
              where scoped_group.id = membership.scope_group_id
                and rule -> 'target_ids' ? scoped_group.unit_id::text))
          and not (excluded ? membership.scope_unit_id::text
            or exists (select 1 from public.groups scoped_group
              where scoped_group.id = membership.scope_group_id
                and excluded ? scoped_group.unit_id::text)))
        when 'group' then (
          (coalesce((rule ->> 'select_all')::boolean, false)
            or rule -> 'target_ids' ? membership.scope_group_id::text)
          and not (excluded ? membership.scope_group_id::text))
        else false end
  ), platform_candidates as (
    select distinct membership.person_id, null::uuid as institution_id,
      membership.person_id::text || ':platform' as recipient_key
    from public.platform_memberships membership
    where dimension = 'platform'
      and membership.status::text = 'active'
      and membership.revoked_at is null
      and jsonb_array_length(role_codes) = 0
  ), person_candidates as (
    select person.id as person_id, null::uuid as institution_id,
      person.id::text || ':person' as recipient_key
    from public.people person
    where dimension = 'person'
      and person.deleted_at is null
      and (coalesce((rule ->> 'select_all')::boolean, false) or rule -> 'target_ids' ? person.id::text)
      and not (excluded ? person.id::text)
      and (search_pattern is null or person.display_name ilike search_pattern escape '\')
  ), candidates as (
    select * from institutional_candidates
    union select * from platform_candidates
    union select * from person_candidates
  ), selected as (
    select * from candidates
    where job.cursor_key is null or recipient_key > job.cursor_key
    order by recipient_key limit p_limit
  ), inserted as (
    insert into public.notice_receipts(notice_id, person_id, institution_id)
    select job.notice_id, person_id, institution_id from selected
    on conflict do nothing returning 1
  )
  select count(*), max(recipient_key) into page_count, last_key from selected;

  update app_private.notice_publication_jobs
  set cursor_key = coalesce(last_key, cursor_key),
      resolved_count = resolved_count + page_count,
      state = case when page_count < p_limit then 'completed' else 'processing' end,
      completed_at = case when page_count < p_limit then now() else null end
  where id = job.id returning * into job;

  if page_count < p_limit then
    if job.resolved_count = 0 then
      update app_private.notice_publication_jobs
      set state = 'failed', last_error_code = 'empty_audience', completed_at = null,
          attempts = 20, locked_at = null, locked_by = null
      where id = job.id;
      insert into analytics.notice_events(notice_id, event_name, properties_json)
      values (job.notice_id, 'audience_empty', jsonb_build_object(
        'publication_job_id', job.id, 'notice_version', job.notice_version));
      return jsonb_build_object('state', 'failed', 'error_code', 'empty_audience');
    end if;
    update app_private.notice_publication_jobs
    set locked_at = null, locked_by = null where id = job.id;
    insert into analytics.notice_events(notice_id, event_name, properties_json)
    values (job.notice_id, 'audience_materialized', jsonb_build_object(
      'publication_job_id', job.id, 'notice_version', job.notice_version,
      'recipient_count', job.resolved_count));
  end if;
  return jsonb_build_object('state', job.state, 'resolved_count', job.resolved_count,
    'cursor_key', job.cursor_key);
end
$$;


ALTER FUNCTION "app_private"."materialize_notice_publication_job"("p_job_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_finalize_image_upload"("p_request_id" "uuid", "p_checksum_sha256" "text", "p_alt_text" "text" DEFAULT NULL::"text", "p_replace_asset_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := app_private.current_person_id();
  intent app_private.meal_plan_image_upload_intents%rowtype;
  asset public.meal_plan_image_assets%rowtype;
  previous public.meal_plan_image_assets%rowtype;
  request_hash text;
  raw_result jsonb;
  result_payload jsonb;
begin
  if auth.uid() is null or actor_id is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  select candidate.* into intent
  from app_private.meal_plan_image_upload_intents candidate
  where candidate.request_id = p_request_id;
  if not found then
    raise no_data_found using message = 'meal plan image upload intent not found';
  end if;
  select candidate.* into asset
  from public.meal_plan_image_assets candidate
  where candidate.id = intent.asset_id;
  if not found then raise no_data_found using message = 'meal plan image not found'; end if;
  perform pg_advisory_xact_lock(hashtextextended(asset.id::text, 0));
  select candidate.* into intent
  from app_private.meal_plan_image_upload_intents candidate
  where candidate.request_id = p_request_id
  for update;
  select candidate.* into asset
  from public.meal_plan_image_assets candidate
  where candidate.id = intent.asset_id
  for update;

  if intent.actor_person_id <> actor_id or asset.created_by <> actor_id
      or not app_private.has_platform_permission('meal_plans.manage')
      or not app_private.meal_plan_scope_allowed(asset.tenant_id, asset.institution_id) then
    raise insufficient_privilege using message = 'meal plan image finalization denied';
  end if;
  request_hash := app_private.meal_plan_request_hash(jsonb_build_object(
    'checksum_sha256', p_checksum_sha256,
    'alt_text', nullif(btrim(p_alt_text), ''),
    'replace_asset_id', p_replace_asset_id
  ));
  if intent.consumed_at is not null then
    if intent.finalize_payload_hash is distinct from request_hash then
      raise invalid_parameter_value using message = 'finalization payload changed';
    end if;
    return intent.finalize_result_json;
  end if;

  if app_private.meal_plan_image_parent_status(asset)
      not in ('draft', 'inReview', 'updated', 'archived') then
    raise invalid_parameter_value using message = 'meal plan image parent is immutable';
  end if;
  if p_replace_asset_id is not null then
    select candidate.* into previous
    from public.meal_plan_image_assets candidate
    where candidate.id = p_replace_asset_id
    for update;
    if previous.id is null or previous.created_by <> actor_id then
      raise insufficient_privilege using message = 'replacement image ownership denied';
    end if;
  end if;

  raw_result := app_private.meal_plan_finalize_image_upload_unreceipted(
    p_request_id, p_checksum_sha256, p_alt_text, p_replace_asset_id
  );
  update public.meal_plan_image_assets
  set revision = revision + 1
  where id = asset.id
  returning * into asset;
  if p_replace_asset_id is not null then
    update public.meal_plan_image_assets
    set revision = revision + 1
    where id = p_replace_asset_id;
  end if;
  result_payload := to_jsonb(asset) || jsonb_build_object(
    'cleanup_request_id', raw_result -> 'cleanup_request_id',
    'cleanup_asset_id', raw_result -> 'cleanup_asset_id',
    'cleanup_path', raw_result -> 'cleanup_path'
  );
  update app_private.meal_plan_image_upload_intents
  set finalize_payload_hash = request_hash,
      finalize_result_json = result_payload
  where request_id = p_request_id;
  return result_payload;
end;
$$;


ALTER FUNCTION "app_private"."meal_plan_finalize_image_upload"("p_request_id" "uuid", "p_checksum_sha256" "text", "p_alt_text" "text", "p_replace_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_finalize_image_upload_unreceipted"("p_request_id" "uuid", "p_checksum_sha256" "text", "p_alt_text" "text" DEFAULT NULL::"text", "p_replace_asset_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_id uuid := app_private.current_person_id();
  intent app_private.meal_plan_image_upload_intents%rowtype;
  asset public.meal_plan_image_assets%rowtype;
  previous public.meal_plan_image_assets%rowtype;
  object_metadata jsonb;
  cleanup_request_id uuid;
begin
  if auth.uid() is null or actor_id is null or p_request_id is null
      or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
      or (p_alt_text is not null and length(p_alt_text) > 500) then
    raise invalid_parameter_value using message = 'invalid meal plan image finalization';
  end if;

  select * into intent
  from app_private.meal_plan_image_upload_intents candidate
  where candidate.request_id = p_request_id
  for update;
  if intent.request_id is null then
    raise no_data_found using message = 'meal plan image upload intent not found';
  end if;
  select * into asset
  from public.meal_plan_image_assets candidate
  where candidate.id = intent.asset_id
  for update;
  if intent.actor_person_id <> actor_id
      or not app_private.has_platform_permission('meal_plans.manage')
      or not app_private.meal_plan_scope_allowed(asset.tenant_id, asset.institution_id) then
    raise insufficient_privilege using message = 'meal plan image finalization denied';
  end if;
  if intent.consumed_at is not null then
    if intent.checksum_sha256 is distinct from p_checksum_sha256 then
      raise invalid_parameter_value using message = 'finalization payload changed';
    end if;
    return to_jsonb(asset);
  end if;
  if intent.expires_at <= now() or asset.status <> 'pending' then
    raise invalid_parameter_value using message = 'meal plan image upload intent expired';
  end if;

  select object_record.metadata into object_metadata
  from storage.objects object_record
  where object_record.bucket_id = 'coelo-meal-plans-private'
    and object_record.name = intent.storage_path;
  if object_metadata is null
      or coalesce((object_metadata->>'size')::bigint, -1) <> intent.size_bytes
      or coalesce(object_metadata->>'mimetype', '') <> intent.mime_type then
    raise invalid_parameter_value using message = 'uploaded object metadata mismatch';
  end if;

  if p_replace_asset_id is not null then
    select * into previous
    from public.meal_plan_image_assets candidate
    where candidate.id = p_replace_asset_id
      and candidate.tenant_id = asset.tenant_id
      and candidate.resource_kind = asset.resource_kind
      and coalesce(candidate.meal_plan_id, candidate.template_id,
        candidate.meal_id, candidate.meal_item_id)
        = coalesce(asset.meal_plan_id, asset.template_id, asset.meal_id, asset.meal_item_id)
      and candidate.status = 'active'
    for update;
    if previous.id is null then
      raise invalid_parameter_value using message = 'replacement image is invalid';
    end if;
  end if;

  update public.meal_plan_image_assets
  set status = 'active',
      checksum_sha256 = p_checksum_sha256,
      alt_text = coalesce(nullif(btrim(p_alt_text), ''), alt_text),
      replaced_asset_id = previous.id,
      activated_at = now()
  where id = asset.id
  returning * into asset;
  update app_private.meal_plan_image_upload_intents
  set consumed_at = now(), checksum_sha256 = p_checksum_sha256
  where request_id = intent.request_id;

  if previous.id is not null then
    cleanup_request_id := gen_random_uuid();
    update public.meal_plan_image_assets
    set status = 'pending_delete', pending_delete_at = now()
    where id = previous.id;
    insert into app_private.meal_plan_image_delete_requests (
      request_id, asset_id, actor_person_id, storage_path
    ) values (
      cleanup_request_id, previous.id, actor_id, previous.storage_path
    );
  end if;

  insert into audit.audit_logs (
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, after_json
  ) values (
    actor_id, auth.jwt()->>'aal', 'meal_plan.image.upload.finalize',
    'meal_plan_image_asset', asset.id, asset.institution_id, 'success',
    to_jsonb(asset) || jsonb_build_object('cleanup_request_id', cleanup_request_id,
      'cleanup_asset_id', previous.id, 'cleanup_path', previous.storage_path)
  );

  return to_jsonb(asset) || jsonb_build_object(
    'cleanup_request_id', cleanup_request_id,
    'cleanup_asset_id', previous.id,
    'cleanup_path', previous.storage_path
  );
end;
$_$;


ALTER FUNCTION "app_private"."meal_plan_finalize_image_upload_unreceipted"("p_request_id" "uuid", "p_checksum_sha256" "text", "p_alt_text" "text", "p_replace_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_image_asset_parent_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  parent_tenant uuid;
  parent_institution uuid;
  parent_plan uuid;
  expected_path text;
  extension text;
begin
  extension := case new.mime_type
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'image/webp' then 'webp'
    else null
  end;

  if new.resource_kind = 'meal_plan' then
    select plan.tenant_id, plan.institution_id, plan.id
      into parent_tenant, parent_institution, parent_plan
    from public.meal_plans plan
    where plan.id = new.meal_plan_id;
    expected_path := 'meal-plans/' || new.meal_plan_id::text || '/' ||
      new.id::text || '.' || extension;
  elsif new.resource_kind = 'template' then
    select template.tenant_id, template.institution_id
      into parent_tenant, parent_institution
    from public.meal_plan_templates template
    where template.id = new.template_id;
    expected_path := 'meal-plan-templates/' || new.template_id::text || '/' ||
      new.id::text || '.' || extension;
  elsif new.resource_kind = 'meal' then
    select plan.tenant_id, plan.institution_id, plan.id
      into parent_tenant, parent_institution, parent_plan
    from public.meal_plan_meals meal
    join public.meal_plans plan
      on plan.id = meal.meal_plan_id and plan.tenant_id = meal.tenant_id
    where meal.id = new.meal_id;
    expected_path := 'meal-plans/' || parent_plan::text || '/meals/' ||
      new.meal_id::text || '/' || new.id::text || '.' || extension;
  elsif new.resource_kind = 'meal_item' then
    select plan.tenant_id, plan.institution_id, plan.id
      into parent_tenant, parent_institution, parent_plan
    from public.meal_plan_meal_items item
    join public.meal_plan_meals meal
      on meal.id = item.meal_id and meal.tenant_id = item.tenant_id
    join public.meal_plans plan
      on plan.id = meal.meal_plan_id and plan.tenant_id = meal.tenant_id
    where item.id = new.meal_item_id;
    expected_path := 'meal-plans/' || parent_plan::text || '/meal-items/' ||
      new.meal_item_id::text || '/' || new.id::text || '.' || extension;
  end if;

  if parent_tenant is null or extension is null then
    raise foreign_key_violation using message = 'meal plan image parent not found';
  end if;
  if new.tenant_id is distinct from parent_tenant
      or new.institution_id is distinct from parent_institution then
    raise check_violation using message = 'meal plan image parent scope mismatch';
  end if;
  if new.storage_bucket <> 'coelo-meal-plans-private'
      or new.storage_path is distinct from expected_path then
    raise check_violation using message = 'meal plan image storage path mismatch';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."meal_plan_image_asset_parent_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_image_delete_request_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  asset public.meal_plan_image_assets%rowtype;
begin
  select candidate.* into asset
  from public.meal_plan_image_assets candidate
  where candidate.id = new.asset_id;
  if asset.id is null or new.storage_path is distinct from asset.storage_path then
    raise foreign_key_violation using message = 'meal plan cleanup asset mismatch';
  end if;
  new.expected_revision := coalesce(new.expected_revision, asset.revision);
  new.payload_hash := coalesce(
    new.payload_hash,
    app_private.meal_plan_request_hash(jsonb_build_object(
      'asset_id', new.asset_id,
      'expected_revision', new.expected_revision
    ))
  );
  new.result_json := coalesce(new.result_json, jsonb_build_object(
    'asset_id', asset.id,
    'bucket', asset.storage_bucket,
    'delete_path', asset.storage_path,
    'confirmed', new.confirmed_at is not null,
    'revision', asset.revision
  ));
  new.state := case when new.confirmed_at is null then new.state else 'completed' end;
  new.completed_at := coalesce(new.completed_at, new.confirmed_at);
  return new;
end;
$$;


ALTER FUNCTION "app_private"."meal_plan_image_delete_request_defaults"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_image_download_descriptor"("p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  asset public.meal_plan_image_assets%rowtype;
begin
  select * into asset
  from public.meal_plan_image_assets candidate
  where candidate.id = p_asset_id and candidate.status = 'active';
  if asset.id is null then
    raise no_data_found using message = 'meal plan image not found';
  end if;
  if auth.uid() is null
      or not app_private.has_platform_permission('meal_plans.read')
      or not app_private.meal_plan_scope_allowed(asset.tenant_id, asset.institution_id) then
    raise insufficient_privilege using message = 'meal_plans.read required';
  end if;
  return jsonb_build_object(
    'asset_id', asset.id,
    'bucket', asset.storage_bucket,
    'path', asset.storage_path,
    'mime_type', asset.mime_type,
    'alt_text', asset.alt_text,
    'signed_url_ttl_seconds', 300
  );
end;
$$;


ALTER FUNCTION "app_private"."meal_plan_image_download_descriptor"("p_asset_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."meal_plan_image_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "institution_id" "uuid",
    "resource_kind" "text" NOT NULL,
    "meal_plan_id" "uuid",
    "template_id" "uuid",
    "meal_id" "uuid",
    "meal_item_id" "uuid",
    "storage_bucket" "text" DEFAULT 'coelo-meal-plans-private'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "size_bytes" bigint NOT NULL,
    "checksum_sha256" "text",
    "alt_text" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "replaced_asset_id" "uuid",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "activated_at" timestamp with time zone,
    "pending_delete_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "revision" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "meal_plan_image_assets_alt_text_check" CHECK ((("alt_text" IS NULL) OR ("length"("alt_text") <= 500))),
    CONSTRAINT "meal_plan_image_assets_checksum_sha256_check" CHECK ((("checksum_sha256" IS NULL) OR ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "meal_plan_image_assets_mime_type_check" CHECK (("mime_type" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"]))),
    CONSTRAINT "meal_plan_image_assets_parent_shape_check" CHECK (((("resource_kind" = 'meal_plan'::"text") AND ("meal_plan_id" IS NOT NULL) AND ("template_id" IS NULL) AND ("meal_id" IS NULL) AND ("meal_item_id" IS NULL)) OR (("resource_kind" = 'template'::"text") AND ("template_id" IS NOT NULL) AND ("meal_plan_id" IS NULL) AND ("meal_id" IS NULL) AND ("meal_item_id" IS NULL)) OR (("resource_kind" = 'meal'::"text") AND ("meal_id" IS NOT NULL) AND ("meal_plan_id" IS NULL) AND ("template_id" IS NULL) AND ("meal_item_id" IS NULL)) OR (("resource_kind" = 'meal_item'::"text") AND ("meal_item_id" IS NOT NULL) AND ("meal_plan_id" IS NULL) AND ("template_id" IS NULL) AND ("meal_id" IS NULL)))),
    CONSTRAINT "meal_plan_image_assets_resource_kind_check" CHECK (("resource_kind" = ANY (ARRAY['meal_plan'::"text", 'template'::"text", 'meal'::"text", 'meal_item'::"text"]))),
    CONSTRAINT "meal_plan_image_assets_revision_positive" CHECK (("revision" > 0)),
    CONSTRAINT "meal_plan_image_assets_size_bytes_check" CHECK ((("size_bytes" >= 1) AND ("size_bytes" <= 2097152))),
    CONSTRAINT "meal_plan_image_assets_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'pending_delete'::"text", 'deleted'::"text"]))),
    CONSTRAINT "meal_plan_image_assets_status_shape_check" CHECK (((("status" = 'pending'::"text") AND ("checksum_sha256" IS NULL) AND ("activated_at" IS NULL) AND ("pending_delete_at" IS NULL) AND ("deleted_at" IS NULL)) OR (("status" = 'active'::"text") AND ("checksum_sha256" IS NOT NULL) AND ("activated_at" IS NOT NULL) AND ("pending_delete_at" IS NULL) AND ("deleted_at" IS NULL)) OR (("status" = 'pending_delete'::"text") AND ("checksum_sha256" IS NOT NULL) AND ("activated_at" IS NOT NULL) AND ("pending_delete_at" IS NOT NULL) AND ("deleted_at" IS NULL)) OR (("status" = 'deleted'::"text") AND ("deleted_at" IS NOT NULL)))),
    CONSTRAINT "meal_plan_image_assets_storage_bucket_check" CHECK (("storage_bucket" = 'coelo-meal-plans-private'::"text"))
);

ALTER TABLE ONLY "public"."meal_plan_image_assets" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."meal_plan_image_assets" OWNER TO "postgres";


COMMENT ON TABLE "public"."meal_plan_image_assets" IS 'Private meal-plan image metadata. Render only through short signed URLs.';



CREATE OR REPLACE FUNCTION "app_private"."meal_plan_image_parent_status"("p_asset" "public"."meal_plan_image_assets") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case p_asset.resource_kind
    when 'template' then (
      select template.status from public.meal_plan_templates template
      where template.id = p_asset.template_id
        and template.tenant_id = p_asset.tenant_id
    )
    when 'meal' then (
      select plan.status
      from public.meal_plan_meals meal
      join public.meal_plans plan
        on plan.id = meal.meal_plan_id and plan.tenant_id = meal.tenant_id
      where meal.id = p_asset.meal_id and meal.tenant_id = p_asset.tenant_id
    )
    when 'meal_item' then (
      select plan.status
      from public.meal_plan_meal_items item
      join public.meal_plan_meals meal
        on meal.id = item.meal_id and meal.tenant_id = item.tenant_id
      join public.meal_plans plan
        on plan.id = meal.meal_plan_id and plan.tenant_id = meal.tenant_id
      where item.id = p_asset.meal_item_id and item.tenant_id = p_asset.tenant_id
    )
    else (
      select plan.status from public.meal_plans plan
      where plan.id = p_asset.meal_plan_id and plan.tenant_id = p_asset.tenant_id
    )
  end;
$$;


ALTER FUNCTION "app_private"."meal_plan_image_parent_status"("p_asset" "public"."meal_plan_image_assets") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_prepare_image_upload"("p_resource_kind" "text", "p_resource_id" "uuid", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_alt_text" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := app_private.current_person_id();
  asset_id uuid;
  parent_tenant uuid;
  parent_institution uuid;
  parent_plan uuid;
  extension text;
  storage_path text;
  expires_at timestamptz := now() + interval '10 minutes';
  prior app_private.meal_plan_image_upload_intents%rowtype;
  prior_asset public.meal_plan_image_assets%rowtype;
begin
  if auth.uid() is null or actor_id is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  if not app_private.has_platform_permission('meal_plans.manage') then
    raise insufficient_privilege using message = 'meal_plans.manage required';
  end if;
  if p_resource_kind not in ('meal_plan', 'template', 'meal', 'meal_item')
      or p_resource_id is null or p_idempotency_key is null
      or nullif(btrim(p_file_name), '') is null or length(p_file_name) > 180
      or p_mime_type not in ('image/jpeg', 'image/png', 'image/webp')
      or p_size_bytes not between 1 and 2097152
      or (p_alt_text is not null and length(p_alt_text) > 500) then
    raise invalid_parameter_value using message = 'invalid meal plan image upload';
  end if;

  if p_resource_kind = 'meal_plan' then
    select plan.tenant_id, plan.institution_id, plan.id
      into parent_tenant, parent_institution, parent_plan
    from public.meal_plans plan where plan.id = p_resource_id;
  elsif p_resource_kind = 'template' then
    select template.tenant_id, template.institution_id
      into parent_tenant, parent_institution
    from public.meal_plan_templates template where template.id = p_resource_id;
  elsif p_resource_kind = 'meal' then
    select plan.tenant_id, plan.institution_id, plan.id
      into parent_tenant, parent_institution, parent_plan
    from public.meal_plan_meals meal
    join public.meal_plans plan
      on plan.id = meal.meal_plan_id and plan.tenant_id = meal.tenant_id
    where meal.id = p_resource_id;
  else
    select plan.tenant_id, plan.institution_id, plan.id
      into parent_tenant, parent_institution, parent_plan
    from public.meal_plan_meal_items item
    join public.meal_plan_meals meal
      on meal.id = item.meal_id and meal.tenant_id = item.tenant_id
    join public.meal_plans plan
      on plan.id = meal.meal_plan_id and plan.tenant_id = meal.tenant_id
    where item.id = p_resource_id;
  end if;

  if parent_tenant is null then
    raise no_data_found using message = 'meal plan image parent not found';
  end if;
  if not app_private.meal_plan_scope_allowed(parent_tenant, parent_institution) then
    raise insufficient_privilege using message = 'meal plan image scope denied';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text, 0));
  select * into prior
  from app_private.meal_plan_image_upload_intents intent
  where intent.request_id = p_idempotency_key;
  if prior.request_id is not null then
    select * into prior_asset
    from public.meal_plan_image_assets asset where asset.id = prior.asset_id;
    if prior.actor_person_id <> actor_id
        or prior.mime_type <> p_mime_type
        or prior.size_bytes <> p_size_bytes
        or prior_asset.resource_kind <> p_resource_kind
        or coalesce(prior_asset.meal_plan_id, prior_asset.template_id,
          prior_asset.meal_id, prior_asset.meal_item_id) <> p_resource_id
        or prior_asset.alt_text is distinct from nullif(btrim(p_alt_text), '') then
      raise invalid_parameter_value using message = 'idempotency key reused';
    end if;
    return jsonb_build_object(
      'asset_id', prior.asset_id,
      'bucket', 'coelo-meal-plans-private',
      'path', prior.storage_path,
      'mime_type', prior.mime_type,
      'max_bytes', 2097152,
      'expires_at', prior.expires_at
    );
  end if;

  asset_id := gen_random_uuid();
  extension := case p_mime_type
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    else 'webp'
  end;
  storage_path := case p_resource_kind
    when 'meal_plan' then 'meal-plans/' || p_resource_id::text || '/' || asset_id::text || '.' || extension
    when 'template' then 'meal-plan-templates/' || p_resource_id::text || '/' || asset_id::text || '.' || extension
    when 'meal' then 'meal-plans/' || parent_plan::text || '/meals/' || p_resource_id::text || '/' || asset_id::text || '.' || extension
    else 'meal-plans/' || parent_plan::text || '/meal-items/' || p_resource_id::text || '/' || asset_id::text || '.' || extension
  end;

  insert into public.meal_plan_image_assets (
    id, tenant_id, institution_id, resource_kind, meal_plan_id, template_id,
    meal_id, meal_item_id, storage_path, mime_type, size_bytes, alt_text, created_by
  ) values (
    asset_id, parent_tenant, parent_institution, p_resource_kind,
    case when p_resource_kind = 'meal_plan' then p_resource_id end,
    case when p_resource_kind = 'template' then p_resource_id end,
    case when p_resource_kind = 'meal' then p_resource_id end,
    case when p_resource_kind = 'meal_item' then p_resource_id end,
    storage_path, p_mime_type, p_size_bytes, nullif(btrim(p_alt_text), ''), actor_id
  );

  insert into app_private.meal_plan_image_upload_intents (
    request_id, asset_id, actor_person_id, storage_path, mime_type,
    size_bytes, expires_at
  ) values (
    p_idempotency_key, asset_id, actor_id, storage_path, p_mime_type,
    p_size_bytes, expires_at
  );

  insert into audit.audit_logs (
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, after_json
  ) values (
    actor_id, auth.jwt()->>'aal', 'meal_plan.image.upload.prepare',
    'meal_plan_image_asset', asset_id, parent_institution, 'success',
    jsonb_build_object('resource_kind', p_resource_kind,
      'resource_id', p_resource_id, 'bucket', 'coelo-meal-plans-private',
      'path', storage_path, 'mime_type', p_mime_type, 'size_bytes', p_size_bytes)
  );

  return jsonb_build_object(
    'asset_id', asset_id,
    'bucket', 'coelo-meal-plans-private',
    'path', storage_path,
    'mime_type', p_mime_type,
    'max_bytes', 2097152,
    'expires_at', expires_at
  );
end;
$$;


ALTER FUNCTION "app_private"."meal_plan_prepare_image_upload"("p_resource_kind" "text", "p_resource_id" "uuid", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_alt_text" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_request_hash"("p_payload" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select encode(
    extensions.digest(convert_to(coalesce(p_payload, '{}'::jsonb)::text, 'UTF8'), 'sha256'),
    'hex'
  );
$$;


ALTER FUNCTION "app_private"."meal_plan_request_hash"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_request_image_delete"("p_asset_id" "uuid", "p_idempotency_key" "uuid", "p_expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := app_private.current_person_id();
  asset public.meal_plan_image_assets%rowtype;
  prior app_private.meal_plan_image_delete_requests%rowtype;
  request_hash text;
  raw_result jsonb;
  result_payload jsonb;
begin
  if auth.uid() is null or actor_id is null or p_idempotency_key is null
      or p_expected_revision is null or p_expected_revision < 1 then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  select candidate.* into asset
  from public.meal_plan_image_assets candidate
  where candidate.id = p_asset_id;
  if not found then raise no_data_found using message = 'meal plan image not found'; end if;
  perform pg_advisory_xact_lock(hashtextextended(asset.id::text, 0));
  select candidate.* into asset
  from public.meal_plan_image_assets candidate
  where candidate.id = p_asset_id
  for update;
  if not app_private.has_platform_permission('meal_plans.manage')
      or asset.created_by <> actor_id
      or not app_private.meal_plan_scope_allowed(asset.tenant_id, asset.institution_id) then
    raise insufficient_privilege using message = 'meal plan image delete denied';
  end if;
  request_hash := app_private.meal_plan_request_hash(jsonb_build_object(
    'asset_id', p_asset_id,
    'expected_revision', p_expected_revision
  ));
  select candidate.* into prior
  from app_private.meal_plan_image_delete_requests candidate
  where candidate.request_id = p_idempotency_key;
  if found then
    if prior.actor_person_id <> actor_id or prior.asset_id <> p_asset_id
        or prior.payload_hash <> request_hash then
      raise invalid_parameter_value using message = 'idempotency key reused';
    end if;
    return prior.result_json;
  end if;
  if asset.revision <> p_expected_revision then
    raise exception 'meal plan image revision conflict' using errcode = 'P0003';
  end if;
  if app_private.meal_plan_image_parent_status(asset)
      not in ('draft', 'inReview', 'updated', 'archived') then
    raise invalid_parameter_value using message = 'meal plan image parent is immutable';
  end if;

  raw_result := app_private.meal_plan_request_image_delete_unreceipted(
    p_asset_id, p_idempotency_key
  );
  update public.meal_plan_image_assets
  set revision = revision + 1
  where id = p_asset_id
  returning * into asset;
  result_payload := raw_result || jsonb_build_object('revision', asset.revision);
  update app_private.meal_plan_image_delete_requests
  set expected_revision = p_expected_revision,
      payload_hash = request_hash,
      result_json = result_payload,
      state = case when confirmed_at is null then 'pending' else 'completed' end,
      completed_at = confirmed_at
  where request_id = p_idempotency_key;
  return result_payload;
end;
$$;


ALTER FUNCTION "app_private"."meal_plan_request_image_delete"("p_asset_id" "uuid", "p_idempotency_key" "uuid", "p_expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_request_image_delete_unreceipted"("p_asset_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := app_private.current_person_id();
  asset public.meal_plan_image_assets%rowtype;
  prior app_private.meal_plan_image_delete_requests%rowtype;
  object_exists boolean;
begin
  if auth.uid() is null or actor_id is null or p_idempotency_key is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text, 0));
  select * into prior
  from app_private.meal_plan_image_delete_requests request
  where request.request_id = p_idempotency_key;
  if prior.request_id is not null then
    if prior.actor_person_id <> actor_id or prior.asset_id <> p_asset_id then
      raise invalid_parameter_value using message = 'idempotency key reused';
    end if;
    return jsonb_build_object(
      'asset_id', prior.asset_id,
      'bucket', 'coelo-meal-plans-private',
      'delete_path', prior.storage_path,
      'confirmed', prior.confirmed_at is not null
    );
  end if;

  select * into asset
  from public.meal_plan_image_assets candidate
  where candidate.id = p_asset_id
  for update;
  if asset.id is null then
    raise no_data_found using message = 'meal plan image not found';
  end if;
  if not app_private.has_platform_permission('meal_plans.manage')
      or not app_private.meal_plan_scope_allowed(asset.tenant_id, asset.institution_id) then
    raise insufficient_privilege using message = 'meal_plans.manage required';
  end if;
  if asset.status not in ('active', 'pending_delete') then
    raise invalid_parameter_value using message = 'meal plan image cannot be deleted';
  end if;

  select exists (
    select 1 from storage.objects object_record
    where object_record.bucket_id = asset.storage_bucket
      and object_record.name = asset.storage_path
  ) into object_exists;
  update public.meal_plan_image_assets
  set status = case when object_exists then 'pending_delete' else 'deleted' end,
      pending_delete_at = coalesce(pending_delete_at, now()),
      deleted_at = case when object_exists then null else now() end
  where id = asset.id
  returning * into asset;
  insert into app_private.meal_plan_image_delete_requests (
    request_id, asset_id, actor_person_id, storage_path, confirmed_at
  ) values (
    p_idempotency_key, asset.id, actor_id, asset.storage_path,
    case when object_exists then null else now() end
  );

  insert into audit.audit_logs (
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, before_json, after_json
  ) values (
    actor_id, auth.jwt()->>'aal', 'meal_plan.image.delete.request',
    'meal_plan_image_asset', asset.id, asset.institution_id, 'success',
    to_jsonb(asset), jsonb_build_object('status', asset.status,
      'bucket', asset.storage_bucket, 'path', asset.storage_path)
  );

  return jsonb_build_object(
    'asset_id', asset.id,
    'bucket', asset.storage_bucket,
    'delete_path', asset.storage_path,
    'confirmed', not object_exists
  );
end;
$$;


ALTER FUNCTION "app_private"."meal_plan_request_image_delete_unreceipted"("p_asset_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_scope_allowed"("p_tenant_id" "uuid", "p_institution_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'app_private'
    AS $$ select exists (select 1 from public.platform_memberships m join public.platform_roles r on r.id=m.role_id where m.person_id=app_private.current_person_id() and m.status='active' and m.revoked_at is null and r.status='active' and (m.scope_kind='platform' or (m.scope_kind='institution' and m.scope_institution_id=p_institution_id)) and (p_tenant_id is null or p_institution_id is null or p_tenant_id=p_institution_id)); $$;


ALTER FUNCTION "app_private"."meal_plan_scope_allowed"("p_tenant_id" "uuid", "p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_scope_rules_array"("p_value" "jsonb", "p_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_value is null or jsonb_typeof(p_value) = 'null' then '[]'::jsonb
    when jsonb_typeof(p_value) = 'array' then p_value
    when jsonb_typeof(p_value) = 'object' then coalesce((
      select jsonb_agg(rule) from (
        select jsonb_build_object('scopeLevel', 'institution', 'scopeId', id, 'institutionId', id) as rule
          from jsonb_array_elements_text(coalesce(p_value -> 'institutionIds', '[]'::jsonb)) id
        union all
        select jsonb_build_object('scopeLevel', 'unit', 'scopeId', id, 'institutionId', p_institution_id, 'unitId', id)
          from jsonb_array_elements_text(coalesce(p_value -> 'unitIds', '[]'::jsonb)) id
        union all
        select jsonb_build_object('scopeLevel', 'classLevel', 'scopeId', id, 'institutionId', p_institution_id, 'classId', id)
          from jsonb_array_elements_text(coalesce(p_value -> 'groupIds', '[]'::jsonb)) id
        union all
        select jsonb_build_object('scopeLevel', 'activity', 'scopeId', id, 'institutionId', p_institution_id, 'activityId', id)
          from jsonb_array_elements_text(coalesce(p_value -> 'activityIds', '[]'::jsonb)) id
        union all
        select jsonb_build_object('scopeLevel', 'person', 'scopeId', id, 'institutionId', p_institution_id, 'personId', id)
          from jsonb_array_elements_text(coalesce(p_value -> 'includedPersonIds', '[]'::jsonb)) id
      ) rules where rules.rule ->> 'scopeId' <> ''), '[]'::jsonb)
    else '[]'::jsonb end;
$$;


ALTER FUNCTION "app_private"."meal_plan_scope_rules_array"("p_value" "jsonb", "p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_scope_rules_object"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_value is null or jsonb_typeof(p_value) = 'null' then '{}'::jsonb
    when jsonb_typeof(p_value) = 'object' then p_value
    when jsonb_typeof(p_value) = 'array' then jsonb_build_object(
      'institutionIds', coalesce((select jsonb_agg(r ->> 'scopeId') from jsonb_array_elements(p_value) r where r ->> 'scopeLevel' = 'institution'), '[]'::jsonb),
      'unitIds', coalesce((select jsonb_agg(r ->> 'scopeId') from jsonb_array_elements(p_value) r where r ->> 'scopeLevel' = 'unit'), '[]'::jsonb),
      'groupIds', coalesce((select jsonb_agg(r ->> 'scopeId') from jsonb_array_elements(p_value) r where r ->> 'scopeLevel' = 'classLevel'), '[]'::jsonb),
      'activityIds', coalesce((select jsonb_agg(r ->> 'scopeId') from jsonb_array_elements(p_value) r where r ->> 'scopeLevel' = 'activity'), '[]'::jsonb),
      'includedPersonIds', coalesce((select jsonb_agg(r ->> 'scopeId') from jsonb_array_elements(p_value) r where r ->> 'scopeLevel' = 'person'), '[]'::jsonb),
      'excludedPersonIds', '[]'::jsonb)
    else '{}'::jsonb end;
$$;


ALTER FUNCTION "app_private"."meal_plan_scope_rules_object"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."meal_plan_validate_target"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  plan_record public.meal_plans;
  valid_target boolean := false;
begin
  select * into plan_record
  from public.meal_plans plan
  where plan.id = new.meal_plan_id and plan.tenant_id = new.tenant_id;

  if not found then
    raise foreign_key_violation using message = 'meal plan tenant mismatch';
  end if;

  if new.institution_id is distinct from plan_record.institution_id then
    raise check_violation using message = 'target institution does not match meal plan';
  end if;

  if tg_table_name = 'meal_plan_scopes' then
    if new.scope_level = 'global' then
      valid_target := true;
    elsif new.scope_level = 'institution' then
      valid_target := new.institution_id = plan_record.institution_id;
    elsif new.scope_level = 'unit' then
      select exists (
        select 1 from public.units unit_record
        where unit_record.id = new.unit_id
          and unit_record.institution_id = plan_record.institution_id
      ) into valid_target;
    elsif new.scope_level = 'classLevel' then
      select exists (
        select 1 from public.groups group_record
        where group_record.id = new.class_id
          and group_record.institution_id = plan_record.institution_id
          and (new.unit_id is null or group_record.unit_id = new.unit_id)
      ) into valid_target;
    elsif new.scope_level = 'activity' then
      select exists (
        select 1 from public.activity_definitions activity
        where activity.id = new.activity_id
          and activity.institution_id = plan_record.institution_id
      ) into valid_target;
    elsif new.scope_level = 'person' then
      select exists (
        select 1 from public.child_contexts child_context
        where child_context.child_person_id = new.person_id
          and child_context.institution_id = plan_record.institution_id
          and child_context.status = 'active'
        union all
        select 1 from public.institution_memberships membership
        where membership.person_id = new.person_id
          and membership.institution_id = plan_record.institution_id
          and membership.status = 'active'
          and membership.revoked_at is null
      ) into valid_target;
    end if;
  else
    if new.target_kind = 'institution' then
      valid_target := new.target_id = plan_record.institution_id;
    elsif new.target_kind = 'unit' then
      select exists (
        select 1 from public.units unit_record
        where unit_record.id = new.target_id
          and unit_record.institution_id = plan_record.institution_id
      ) into valid_target;
    elsif new.target_kind = 'classLevel' then
      select exists (
        select 1 from public.groups group_record
        where group_record.id = new.target_id
          and group_record.institution_id = plan_record.institution_id
      ) into valid_target;
    elsif new.target_kind = 'activity' then
      select exists (
        select 1 from public.activity_definitions activity
        where activity.id = new.target_id
          and activity.institution_id = plan_record.institution_id
      ) into valid_target;
    elsif new.target_kind = 'person' then
      if new.audience_segment = 'students' then
        select exists (
          select 1 from public.child_contexts child_context
          where child_context.child_person_id = new.target_id
            and child_context.institution_id = plan_record.institution_id
            and child_context.status = 'active'
        ) into valid_target;
      elsif new.audience_segment = 'staff' then
        select exists (
          select 1
          from public.institution_memberships membership
          join public.people person_record on person_record.id = membership.person_id
          where membership.person_id = new.target_id
            and membership.institution_id = plan_record.institution_id
            and membership.status = 'active'
            and membership.revoked_at is null
            and person_record.person_type = 'adult'
            and lower(membership.role_code) not in ('guardian', 'responsible', 'parent', 'family')
        ) into valid_target;
      else
        select exists (
          select 1 from public.child_contexts child_context
          where child_context.child_person_id = new.target_id
            and child_context.institution_id = plan_record.institution_id
            and child_context.status = 'active'
          union all
          select 1
          from public.institution_memberships membership
          join public.people person_record on person_record.id = membership.person_id
          where membership.person_id = new.target_id
            and membership.institution_id = plan_record.institution_id
            and membership.status = 'active'
            and membership.revoked_at is null
            and person_record.person_type = 'adult'
            and lower(membership.role_code) not in ('guardian', 'responsible', 'parent', 'family')
        ) into valid_target;
      end if;
    end if;
  end if;

  if not valid_target then
    raise check_violation using message = 'meal plan target is outside the authorized hierarchy or is not eligible';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."meal_plan_validate_target"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."medication_plan_care_notify_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target_unit uuid; mode text;
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then return new; end if;
  -- unidade do plano ou, no escopo de instituicao, a unidade ativa da crianca
  target_unit := new.unit_id;
  if target_unit is null then
    select cul.unit_id into target_unit from public.child_unit_links cul
    where cul.child_context_id = new.child_context_id and cul.status = 'active' and cul.revoked_at is null
    order by cul.created_at desc limit 1;
  end if;
  select coalesce(p.medication_mode, 'accept_to_release') into mode
  from (select 1) one left join public.unit_care_policies p on p.unit_id = target_unit;
  if mode = 'not_tracked' then return new; end if;
  perform app_private.notify_child_care_event_v1(new.institution_id, target_unit, new.child_context_id,
    case when tg_op = 'INSERT' then 'medication.plan.created' else 'medication.plan.' || new.status end,
    'medication_plan', new.id, jsonb_build_object('status', new.status, 'medication_mode', mode), new.created_by_person_id);
  return new;
end $$;


ALTER FUNCTION "app_private"."medication_plan_care_notify_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."medication_plans_for_guardian"("p_child_context_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
begin
  if actor is null then
    raise insufficient_privilege using message='authentication required';
  end if;
  if p_child_context_id is null
    or not app_private.guardian_has_capability(p_child_context_id, 'view_health_care') then
    raise no_data_found using message='medication plan unavailable';
  end if;

  return jsonb_build_object('items', coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', plan_row.id,
      'status', plan_row.status,
      'medication_name', version_row.medication_name,
      'dose_amount', version_row.dose_amount,
      'dose_unit', version_row.dose_unit,
      'administration_route', version_row.administration_route,
      'instructions', version_row.instructions,
      'valid_from', version_row.valid_from,
      'valid_until', version_row.valid_until,
      'timezone', version_row.timezone,
      'schedules', coalesce((
        select jsonb_agg(jsonb_build_object(
          'time_of_day', schedule_row.time_of_day,
          'weekdays', schedule_row.weekdays,
          'timezone', schedule_row.timezone) order by schedule_row.time_of_day)
        from public.medication_plan_schedules schedule_row
        where schedule_row.plan_version_id = version_row.id), '[]'::jsonb)
      -- Sem evidencia de administracao: quem administrou e quando e registro
      -- operacional da instituicao. Se a familia precisar disso, e outra
      -- decisao, com outra capacidade.
    ) order by plan_row.updated_at desc)
    from public.medication_plans plan_row
    left join public.medication_plan_versions version_row
      on version_row.id = plan_row.current_version_id
    where plan_row.child_context_id = p_child_context_id
      and plan_row.status <> 'draft'
  ), '[]'::jsonb));
end
$$;


ALTER FUNCTION "app_private"."medication_plans_for_guardian"("p_child_context_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."moments_actor"("p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") RETURNS TABLE("person_id" "uuid", "membership_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select * from app_private.moments_actor_for_auth_user(
    (select auth.uid()), p_institution_id, p_permission, p_unit_id, p_group_id
  )
$$;


ALTER FUNCTION "app_private"."moments_actor"("p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."moments_actor_for_auth_user"("p_auth_user_id" "uuid", "p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") RETURNS TABLE("person_id" "uuid", "membership_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_auth_user_id is null then
    raise insufficient_privilege using message = 'authentication_required';
  end if;
  if not app_private.has_institution_permission(
    p_institution_id, p_permission, p_unit_id, p_group_id, false
  ) then
    raise insufficient_privilege using message = 'moments_permission_denied';
  end if;
  return query
  select membership.person_id, membership.id
  from public.institution_memberships membership
  where membership.person_id = app_private.person_id_for_auth_user(p_auth_user_id)
    and membership.institution_id = p_institution_id
    and membership.status = 'active'
    and membership.revoked_at is null
  order by membership.created_at
  limit 1;
  if not found then
    raise insufficient_privilege using message = 'active_membership_required';
  end if;
end
$$;


ALTER FUNCTION "app_private"."moments_actor_for_auth_user"("p_auth_user_id" "uuid", "p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."moments_audience_matches_role"("p_role_code" "text", "p_audience" "public"."moments_audience_kind") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when lower(coalesce(p_role_code, '')) in
      ('guardian', 'responsible', 'responsavel', 'parent', 'family')
      then p_audience in ('families', 'guardians_only')
    when lower(coalesce(p_role_code, '')) in ('student', 'aluno')
      then p_audience = 'students'
    else p_audience = 'school_staff'
  end
$$;


ALTER FUNCTION "app_private"."moments_audience_matches_role"("p_role_code" "text", "p_audience" "public"."moments_audience_kind") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."moments_request_fingerprint"("p_payload" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select encode(
    extensions.digest(pg_catalog.convert_to(p_payload::text, 'UTF8'), 'sha256'),
    'hex'
  )
$$;


ALTER FUNCTION "app_private"."moments_request_fingerprint"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."normalize_access_profile_catalog_contract"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_set(p_payload,'{items}',coalesce((
    select jsonb_agg(
      case when item.value->>'inherited_effect'='none'
        then (item.value-'inherited_effect')||jsonb_build_object('inherited_effect',null)
        else item.value end order by item.ordinality
    ) from jsonb_array_elements(coalesce(p_payload->'items','[]'::jsonb)) with ordinality item(value,ordinality)
  ),'[]'::jsonb),true)
$$;


ALTER FUNCTION "app_private"."normalize_access_profile_catalog_contract"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."normalize_guardian_relationship"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare normalized_code text;
begin
  if new.relationship_type_id is null then
    normalized_code := case lower(btrim(new.relation_type))
      when 'pai' then 'father'
      when 'father' then 'father'
      when 'mae' then 'mother'
      when 'mÃ£e' then 'mother'
      when 'mother' then 'mother'
      when 'avo' then 'grandparent'
      when 'responsible' then 'other'
      when 'responsavel' then 'other'
      when 'responsÃ¡vel' then 'other'
      else 'other'
    end;

    if normalized_code = 'grandparent' then
      normalized_code := 'other';
    end if;

    select relationship.id into new.relationship_type_id
    from public.family_relationship_types relationship
    where relationship.code=normalized_code and relationship.status='active';

    if new.relationship_type_id is null then
      raise exception 'active family relationship type is missing';
    end if;
  end if;

  if new.relationship_detail is null then
    new.relationship_detail := nullif(btrim(new.relation_type),'');
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."normalize_guardian_relationship"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."normalize_institution_handle"("p_handle" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select lower(regexp_replace(regexp_replace(btrim(coalesce(p_handle,'')),'^@','','g'),'[^a-zA-Z0-9._-]','','g'))
$$;


ALTER FUNCTION "app_private"."normalize_institution_handle"("p_handle" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."normalize_institution_permission_override_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare membership_institution uuid; unit_institution uuid; group_institution uuid; group_unit uuid;
begin
  select membership.institution_id into membership_institution
  from public.institution_memberships membership where membership.id=new.membership_id;
  if membership_institution is null then raise check_violation using message='membership not found'; end if;
  if new.institution_id is null then new.institution_id:=membership_institution; end if;
  if new.institution_id<>membership_institution then raise check_violation using message='override tenant mismatch'; end if;
  if new.scope_kind='institution' then
    new.scope_unit_id:=null;new.scope_group_id:=null;new.scope_id:=null;
  elsif new.scope_kind='unit' then
    select unit_record.institution_id into unit_institution from public.units unit_record where unit_record.id=new.scope_unit_id;
    if unit_institution is distinct from new.institution_id then raise check_violation using message='override unit tenant mismatch'; end if;
    new.scope_group_id:=null;new.scope_id:=new.scope_unit_id;
  elsif new.scope_kind='group' then
    select group_record.institution_id,group_record.unit_id into group_institution,group_unit
    from public.groups group_record where group_record.id=new.scope_group_id;
    if group_institution is distinct from new.institution_id or group_unit is distinct from new.scope_unit_id then
      raise check_violation using message='override group hierarchy mismatch';
    end if;
    new.scope_id:=new.scope_group_id;
  else raise invalid_parameter_value using message='unsupported override scope'; end if;
  if tg_op='UPDATE' then new.version:=old.version+1; end if;
  return new;
end $$;


ALTER FUNCTION "app_private"."normalize_institution_permission_override_scope"() OWNER TO "postgres";


