CREATE OR REPLACE FUNCTION "app_private"."normalize_unit_sort"("value" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  normalized text := coalesce(value, 'name');
begin
  if normalized not in (
    'name', 'institution_name', 'institution_type_name', 'unit_type_name',
    'unit_status', 'plan_name', 'groups_count', 'activities_count', 'updated_at',
    'contact_email', 'contact_phone', 'contact_mobile_phone', 'street',
    'address_number', 'complement', 'district', 'postal_code', 'city', 'state'
  ) then
    raise invalid_parameter_value using message = 'invalid unit sort';
  end if;
  return normalized;
end;
$$;


