CREATE OR REPLACE FUNCTION "app_private"."notice_dispatch_publication_worker"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare worker_url text;
declare worker_secret text;
declare request_id bigint;
begin
  select decrypted_secret into worker_url
    from vault.decrypted_secrets where name = 'notices_worker_url' limit 1;
  select decrypted_secret into worker_secret
    from vault.decrypted_secrets where name = 'notices_worker_secret' limit 1;
  if nullif(worker_url, '') is null or nullif(worker_secret, '') is null then
    return null;
  end if;
  select net.http_post(
    url := worker_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-coelo-worker-secret', worker_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 5000
  ) into request_id;
  return request_id;
end;
$$;


ALTER FUNCTION "app_private"."notice_dispatch_publication_worker"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."notify_child_care_event_v1"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_child_context_id" "uuid", "p_event_code" "text", "p_object_type" "text", "p_object_id" "uuid", "p_payload" "jsonb", "p_actor_person_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare event_id uuid;
begin
  insert into public.context_notification_events(institution_id, unit_id, child_context_id, event_code,
    object_type, object_id, payload_json, created_by_person_id)
  values (p_institution_id, p_unit_id, p_child_context_id, p_event_code, p_object_type, p_object_id,
    coalesce(p_payload, '{}'::jsonb), p_actor_person_id)
  returning id into event_id;
  insert into public.context_notification_recipients(event_id, person_id)
  select event_id, r from app_private.child_care_notification_recipients_v1(p_institution_id, p_unit_id, p_child_context_id, p_actor_person_id) r
  on conflict do nothing;
  return event_id;
end $$;


ALTER FUNCTION "app_private"."notify_child_care_event_v1"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_child_context_id" "uuid", "p_event_code" "text", "p_object_type" "text", "p_object_id" "uuid", "p_payload" "jsonb", "p_actor_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."now_actor"("p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") RETURNS TABLE("person_id" "uuid", "membership_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null then raise insufficient_privilege using message='authentication_required'; end if;
  if p_unit_id is not null and not exists(
    select 1 from public.units where id=p_unit_id and institution_id=p_institution_id
  ) then raise insufficient_privilege using message='context_not_authorized'; end if;
  if p_group_id is not null and (
    p_unit_id is null or not exists(
      select 1 from public.groups
      where id=p_group_id and institution_id=p_institution_id and unit_id=p_unit_id
    )
  ) then raise insufficient_privilege using message='context_not_authorized'; end if;
  if not app_private.has_institution_permission(p_institution_id,p_permission,p_unit_id,p_group_id,false)
  then raise insufficient_privilege using message='now_permission_denied'; end if;
  return query select membership.person_id,membership.id
  from public.institution_memberships membership
  where membership.person_id=app_private.person_id_for_auth_user((select auth.uid()))
    and membership.institution_id=p_institution_id
    and membership.status='active' and membership.revoked_at is null order by membership.created_at limit 1;
  if not found then raise insufficient_privilege using message='active_membership_required'; end if;
end $$;


ALTER FUNCTION "app_private"."now_actor"("p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."now_audience_matches_role"("p_role_code" "text", "p_audience" "public"."now_audience_kind") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case lower(coalesce(p_role_code,''))
    when 'guardian' then p_audience in ('families','guardians_only')
    when 'student' then p_audience='students'
    when 'school_staff' then p_audience='school_staff'
    else false
  end
$$;


ALTER FUNCTION "app_private"."now_audience_matches_role"("p_role_code" "text", "p_audience" "public"."now_audience_kind") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."now_max_video_seconds"("p_institution_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select greatest(30,coalesce((
    select case jsonb_typeof(entitlement.value_json)
      when 'number' then entitlement.value_json#>>'{}'
      else entitlement.value_json->>'value'
    end::integer
    from public.institution_subscriptions subscription
    join public.plan_entitlements entitlement on entitlement.plan_id=subscription.plan_id
    where subscription.institution_id=p_institution_id
      and subscription.status::text in('active','trial')
      and entitlement.entitlement_key='now.max_video_seconds'
      and entitlement.status::text='active'
    order by subscription.created_at desc limit 1
  ),30));
$$;


ALTER FUNCTION "app_private"."now_max_video_seconds"("p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."now_viewer_has_context"("p_person_id" "uuid", "p_role_code" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when lower(coalesce(p_role_code,'')) in ('student','aluno') then exists(
      select 1
      from public.child_contexts child_context
      left join public.child_unit_links unit_link
        on unit_link.child_context_id=child_context.id
       and unit_link.status='active'
       and unit_link.revoked_at is null
      left join public.child_group_links group_link
        on group_link.child_unit_link_id=unit_link.id
       and group_link.status='active'
       and (group_link.starts_at is null or group_link.starts_at<=now())
       and (group_link.ends_at is null or group_link.ends_at>now())
      where child_context.child_person_id=p_person_id
        and child_context.institution_id=p_institution_id
        and child_context.status='active'
        and child_context.archived_at is null
        and (p_unit_id is null or unit_link.unit_id=p_unit_id)
        and (p_group_id is null or group_link.group_id=p_group_id)
    )
    when lower(coalesce(p_role_code,'')) in ('guardian','responsible','responsavel','parent','family') then exists(
      select 1
      from public.guardian_links guardian
      join public.child_contexts child_context
        on child_context.child_person_id=guardian.child_person_id
       and child_context.institution_id=p_institution_id
       and child_context.status='active'
       and child_context.archived_at is null
      join public.guardian_context_permissions guardian_permission
        on guardian_permission.guardian_link_id=guardian.id
       and guardian_permission.child_context_id=child_context.id
       and guardian_permission.can_view
       and guardian_permission.status='active'
       and (guardian_permission.starts_at is null or guardian_permission.starts_at<=now())
       and (guardian_permission.expires_at is null or guardian_permission.expires_at>now())
      left join public.child_unit_links unit_link
        on unit_link.child_context_id=child_context.id
       and unit_link.status='active'
       and unit_link.revoked_at is null
      left join public.child_group_links group_link
        on group_link.child_unit_link_id=unit_link.id
       and group_link.status='active'
       and (group_link.starts_at is null or group_link.starts_at<=now())
       and (group_link.ends_at is null or group_link.ends_at>now())
      where guardian.guardian_person_id=p_person_id
        and guardian.status='active'
        and guardian.revoked_at is null
        and (p_unit_id is null or unit_link.unit_id=p_unit_id)
        and (p_group_id is null or group_link.group_id=p_group_id)
    )
    when lower(coalesce(p_role_code,'')) in (
      'professional','institution_admin','unit_admin','teacher','coordinator'
    ) then true
    else false
  end
$$;


ALTER FUNCTION "app_private"."now_viewer_has_context"("p_person_id" "uuid", "p_role_code" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."now_viewer_role_class"("p_person_id" "uuid", "p_membership_id" "uuid", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with student_context as (
    select 1
    from public.child_contexts child_context
    left join public.child_unit_links unit_link
      on unit_link.child_context_id=child_context.id
     and unit_link.status='active'
     and unit_link.revoked_at is null
    left join public.child_group_links group_link
      on group_link.child_unit_link_id=unit_link.id
     and group_link.status='active'
     and (group_link.starts_at is null or group_link.starts_at<=now())
     and (group_link.ends_at is null or group_link.ends_at>now())
    where child_context.child_person_id=p_person_id
      and child_context.institution_id=p_institution_id
      and child_context.status='active'
      and child_context.archived_at is null
      and (p_unit_id is null or unit_link.unit_id=p_unit_id)
      and (p_group_id is null or group_link.group_id=p_group_id)
    limit 1
  ),
  guardian_context as (
    select 1
    from public.guardian_links guardian
    join public.child_contexts child_context
      on child_context.child_person_id=guardian.child_person_id
     and child_context.institution_id=p_institution_id
     and child_context.status='active'
     and child_context.archived_at is null
    join public.guardian_context_permissions guardian_permission
      on guardian_permission.guardian_link_id=guardian.id
     and guardian_permission.child_context_id=child_context.id
     and guardian_permission.can_view
     and guardian_permission.status='active'
     and (guardian_permission.starts_at is null or guardian_permission.starts_at<=now())
     and (guardian_permission.expires_at is null or guardian_permission.expires_at>now())
    left join public.child_unit_links unit_link
      on unit_link.child_context_id=child_context.id
     and unit_link.status='active'
     and unit_link.revoked_at is null
    left join public.child_group_links group_link
      on group_link.child_unit_link_id=unit_link.id
     and group_link.status='active'
     and (group_link.starts_at is null or group_link.starts_at<=now())
     and (group_link.ends_at is null or group_link.ends_at>now())
    where guardian.guardian_person_id=p_person_id
      and guardian.status='active'
      and guardian.revoked_at is null
      and (p_unit_id is null or unit_link.unit_id=p_unit_id)
      and (p_group_id is null or group_link.group_id=p_group_id)
    limit 1
  ),
  active_membership as (
    select membership.id
    from public.institution_memberships membership
    where membership.id=p_membership_id
      and membership.person_id=p_person_id
      and membership.institution_id=p_institution_id
      and membership.status='active'
      and membership.revoked_at is null
  ),
  staff_effects as (
    select role_permission.effect
    from active_membership membership
    join public.institution_role_assignments assignment
      on assignment.membership_id=membership.id
     and assignment.status='active'
     and (assignment.starts_at is null or assignment.starts_at<=now())
     and (assignment.expires_at is null or assignment.expires_at>now())
    join public.institution_roles role_record
      on role_record.id=assignment.role_id
     and role_record.status='active'
     and (role_record.institution_id is null or role_record.institution_id=p_institution_id)
    join public.institution_role_permissions role_permission
      on role_permission.role_id=role_record.id
     and role_permission.status='active'
     and role_permission.revoked_at is null
    join public.institution_permissions permission_record
      on permission_record.id=role_permission.permission_id
     and permission_record.code='now.publications.read'
     and permission_record.status='active'
    where assignment.scope_kind='institution'
       or (assignment.scope_kind='unit' and assignment.scope_unit_id=p_unit_id)
       or (
         assignment.scope_kind='group'
         and assignment.scope_group_id=p_group_id
         and (p_unit_id is null or assignment.scope_unit_id=p_unit_id)
       )
  )
  select case
    when exists(select 1 from student_context) then 'student'
    when exists(select 1 from guardian_context) then 'guardian'
    when exists(select 1 from active_membership)
      and exists(select 1 from staff_effects where effect='allow')
      and not exists(select 1 from staff_effects where effect='deny')
      then 'school_staff'
    else null
  end
$$;


ALTER FUNCTION "app_private"."now_viewer_role_class"("p_person_id" "uuid", "p_membership_id" "uuid", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."people_assign_initial_handle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.person_type = 'service' then
    return new;
  end if;
  begin
    perform app_private.ensure_person_handle(new.id);
  exception when others then
    -- O @ nunca impede o cadastro da pessoa; fica para o backfill/set.
    raise warning 'person handle not assigned for %: %', new.id, sqlerrm;
  end;
  return new;
end
$$;


ALTER FUNCTION "app_private"."people_assign_initial_handle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."persist_unit_children"("target" "uuid", "actor" "uuid", "payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v jsonb;sid uuid;t uuid;begin
if payload?'address'then v:=payload->'address';if v='null'::jsonb then delete from public.unit_addresses where unit_id=target;else
insert into public.unit_addresses(unit_id,country,state,city,district,street,number,complement,postal_code,status,updated_at)
values(target,coalesce(nullif(v->>'country',''),'BR'),nullif(v->>'state',''),nullif(v->>'city',''),nullif(v->>'district',''),nullif(v->>'street',''),nullif(v->>'number',''),nullif(v->>'complement',''),nullif(v->>'postal_code',''),'active',now())
on conflict(unit_id)do update set country=excluded.country,state=excluded.state,city=excluded.city,district=excluded.district,street=excluded.street,number=excluded.number,complement=excluded.complement,postal_code=excluded.postal_code,status='active',updated_at=now();end if;end if;
if payload?'contact'then v:=payload->'contact';if v='null'::jsonb or num_nonnulls(nullif(v->>'email',''),nullif(v->>'phone',''),nullif(v->>'mobile_phone',''))=0 then delete from public.unit_contacts where unit_id=target;else
insert into public.unit_contacts(unit_id,email,phone,mobile_phone,status,updated_at)values(target,nullif(lower(v->>'email'),''),nullif(v->>'phone',''),nullif(v->>'mobile_phone',''),'active',now())
on conflict(unit_id)do update set email=excluded.email,phone=excluded.phone,mobile_phone=excluded.mobile_phone,status='active',updated_at=now();end if;end if;
if payload?'branding'then v:=payload->'branding';if v='null'::jsonb then delete from public.unit_branding where unit_id=target;else
insert into public.unit_branding(unit_id,display_name,logo_media_asset_id,cover_media_asset_id,accent_color,secondary_color,text_color,surface_color,inherit_institution_branding,approval_status,updated_by,updated_at)
values(target,nullif(v->>'display_name',''),nullif(v->>'logo_media_asset_id','')::uuid,nullif(v->>'cover_media_asset_id','')::uuid,nullif(v->>'accent_color',''),nullif(v->>'secondary_color',''),nullif(v->>'text_color',''),nullif(v->>'surface_color',''),coalesce((v->>'inherit_institution_branding')::boolean,true),coalesce(nullif(v->>'approval_status',''),'draft'),actor,now())
on conflict(unit_id)do update set display_name=excluded.display_name,logo_media_asset_id=excluded.logo_media_asset_id,cover_media_asset_id=excluded.cover_media_asset_id,accent_color=excluded.accent_color,secondary_color=excluded.secondary_color,text_color=excluded.text_color,surface_color=excluded.surface_color,inherit_institution_branding=excluded.inherit_institution_branding,approval_status=excluded.approval_status,updated_by=actor,updated_at=now();end if;end if;
if payload?'subtypes'or payload?'subtype_ids'then select unit_type_id into t from public.units where id=target;delete from public.unit_subtype_links where unit_id=target;
for sid in select distinct coalesce(value->>'id',value#>>'{}')::uuid from jsonb_array_elements(coalesce(payload->'subtypes',payload->'subtype_ids'))value loop
if not exists(select 1 from public.unit_subtypes where id=sid and unit_type_id=t and status='active')then raise invalid_parameter_value using message='invalid subtype';end if;
insert into public.unit_subtype_links(unit_id,unit_subtype_id,created_by_person_id)values(target,sid,actor);end loop;end if;end$$;


