CREATE OR REPLACE FUNCTION "app_private"."person_handle_is_reserved"("p_normalized" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_normalized = any (array[
    'coelo','coelo.me','coelome','coelo_me','admin','superadmin','suporte','support',
    'sistema','system','root','owner','api','app','www'
  ]) or p_normalized like 'coelo.%' or p_normalized like 'coelo\_%';
$$;


ALTER FUNCTION "app_private"."person_handle_is_reserved"("p_normalized" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."person_handle_is_valid"("p_normalized" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select p_normalized is not null
    and p_normalized = lower(p_normalized)
    and p_normalized ~ '^[a-z0-9._]{3,30}$'
    and p_normalized !~ '\..*\.'  -- no maximo um ponto (constraint da tabela)
    and p_normalized !~ '\.$'
    and p_normalized !~ '^\.';
$_$;


ALTER FUNCTION "app_private"."person_handle_is_valid"("p_normalized" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."person_handle_slug"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- minusculas, sem acentos comuns, so [a-z0-9]
  select regexp_replace(
    translate(lower(coalesce(p_text,'')),
      'áàãâäéèêëíìîïóòõôöúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'),
    '[^a-z0-9]', '', 'g');
$$;


ALTER FUNCTION "app_private"."person_handle_slug"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."person_id_for_auth_user"("p_auth_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (
      select auth_link.person_id
      from public.person_auth_links auth_link
      where auth_link.auth_user_id = p_auth_user_id
        and auth_link.status = 'active'
        and auth_link.revoked_at is null
      order by auth_link.linked_at desc, auth_link.id
      limit 1
    ),
    (
      select actor.person_id
      from app_private.superadmin_internal_auth_links internal_link
      join app_private.superadmin_internal_actor_people actor
        on actor.internal_identity_id = internal_link.internal_identity_id
      where internal_link.auth_user_id = p_auth_user_id
        and internal_link.status = 'active'
      order by internal_link.created_at desc
      limit 1
    )
  )
$$;


ALTER FUNCTION "app_private"."person_id_for_auth_user"("p_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."person_identity_hmac_v1"("p_digits" "text") RETURNS "bytea"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  key_value text;
begin
  select decrypted_secret into key_value
  from vault.decrypted_secrets
  where name = 'coelo_person_identity_hmac_v1'
  limit 1;
  if key_value is null then
    raise object_not_in_prerequisite_state using
      message = 'person identity hmac key is missing';
  end if;
  return extensions.hmac(pg_catalog.convert_to(p_digits, 'UTF8'),
    pg_catalog.convert_to(key_value, 'UTF8'), 'sha256');
end
$$;


ALTER FUNCTION "app_private"."person_identity_hmac_v1"("p_digits" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."platform_permission_membership_id"("permission_code" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select membership.id
  from public.platform_memberships membership
  join public.platform_roles role on role.id = membership.role_id
  where membership.person_id = app_private.current_person_id()
    and membership.status = 'active'
    and membership.revoked_at is null
    and role.status = 'active'
    and (
      role.code = 'owner'
      or exists (
        select 1
        from public.platform_member_permission_overrides override_row
        join public.platform_permissions permission
          on permission.id = override_row.permission_id
        where override_row.membership_id = membership.id
          and permission.code = permission_code
          and permission.status = 'active'
          and override_row.status = 'active'
          and override_row.effect = 'allow'
          and (
            override_row.starts_at is null
            or override_row.starts_at <= pg_catalog.now()
          )
          and (
            override_row.expires_at is null
            or override_row.expires_at > pg_catalog.now()
          )
      )
      or exists (
        select 1
        from public.platform_role_permissions role_permission
        join public.platform_permissions permission
          on permission.id = role_permission.permission_id
        where role_permission.role_id = membership.role_id
          and permission.code = permission_code
          and permission.status = 'active'
          and role_permission.status = 'active'
          and role_permission.effect = 'allow'
      )
    )
  order by (role.code = 'owner') desc, membership.created_at, membership.id
  limit 1
$$;


ALTER FUNCTION "app_private"."platform_permission_membership_id"("permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."prevent_activity_v2_group_activity_admin"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.assignment_role<>'activity_admin' then return new; end if;
  if tg_op='INSERT' or old.assignment_role is distinct from 'activity_admin'
     or new.id is distinct from old.id or new.activity_group_link_id is distinct from old.activity_group_link_id
     or new.institution_id is distinct from old.institution_id or new.person_id is distinct from old.person_id
     or new.membership_id is distinct from old.membership_id or new.assigned_by_person_id is distinct from old.assigned_by_person_id
     or new.assigned_at is distinct from old.assigned_at or new.created_at is distinct from old.created_at
     or new.status not in('inactive','suspended','archived') or new.revoked_at is null then
    raise check_violation using message='activity_admin assignments are activity-scoped only';
  end if;
  return new;
end $$;


ALTER FUNCTION "app_private"."prevent_activity_v2_group_activity_admin"() OWNER TO "postgres";


