CREATE OR REPLACE FUNCTION "app_private"."profile_about_page_for"("p_subject_type" "text", "p_subject_id" "uuid") RETURNS "public"."profile_about_pages"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select p.* from public.profile_about_pages p where p.subject_type=p_subject_type and
  case p_subject_type when 'institution' then p.institution_subject_id=p_subject_id
   when 'unit' then p.unit_subject_id=p_subject_id when 'group' then p.group_subject_id=p_subject_id
   when 'activity' then p.activity_subject_id=p_subject_id when 'person' then p.person_subject_id=p_subject_id else false end
$$;


