CREATE OR REPLACE FUNCTION "app_private"."profile_about_publication_max_video_seconds"("p_institution_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  result integer := 30;
begin
  if pg_catalog.to_regprocedure('app_private.now_max_video_seconds(uuid)') is not null then
    execute 'select app_private.now_max_video_seconds($1)'
      into result
      using p_institution_id;
  end if;
  return greatest(coalesce(result, 30), 1);
end
$_$;


