CREATE OR REPLACE FUNCTION "app_private"."require_superadmin_internal_context"("p_permission_code" "text") RETURNS SETOF "app_private"."superadmin_internal_context"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_auth_user_id uuid;
  current_session_id uuid;
  jwt_session_id text;
  jwt_aal text;
  link_record record;
  membership_record record;
  role_record record;
  permission_record record;
  grant_effect public.permission_effect;
begin
  current_auth_user_id := auth.uid();
  if current_auth_user_id is null then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_AUTH_REQUIRED';
  end if;

  jwt_session_id := auth.jwt() ->> 'session_id';
  begin
    current_session_id := jwt_session_id::uuid;
  exception when others then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_SESSION_INVALID';
  end;

  if not exists (
    select 1 from auth.sessions session_record
    where session_record.id = current_session_id
      and session_record.user_id = current_auth_user_id
      and (session_record.not_after is null
        or session_record.not_after > pg_catalog.now())
  ) then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_SESSION_INVALID';
  end if;

  if not exists (
    select 1 from auth.users auth_user
    where auth_user.id = current_auth_user_id
      and auth_user.email_confirmed_at is not null
  ) then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_INTERNAL_CONTEXT_DENIED';
  end if;

  jwt_aal := auth.jwt() ->> 'aal';
  if jwt_aal not in ('aal1', 'aal2') then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_SESSION_INVALID';
  end if;

  select auth_link.* into link_record
  from app_private.superadmin_internal_auth_links auth_link
  where auth_link.auth_user_id = current_auth_user_id
  order by auth_link.created_at desc
  limit 1;

  if link_record.id is null then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_INTERNAL_CONTEXT_DENIED';
  elsif link_record.status <> 'active' then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_INTERNAL_CONTEXT_DENIED';
  end if;

  select membership.* into membership_record
  from app_private.superadmin_internal_memberships membership
  where membership.internal_identity_id = link_record.internal_identity_id
  order by (membership.status = 'active') desc, membership.created_at desc
  limit 1;

  if membership_record.id is null then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_INTERNAL_CONTEXT_DENIED';
  elsif membership_record.status = 'suspended' then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_MEMBERSHIP_SUSPENDED';
  elsif membership_record.status = 'revoked' then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_MEMBERSHIP_REVOKED';
  end if;

  select role_item.* into role_record
  from public.platform_roles role_item
  where role_item.id = membership_record.platform_role_id
    and role_item.status = 'active';

  if role_record.id is null
     or app_private.access_scope_rank(membership_record.scope_kind::text)
       > app_private.access_scope_rank(role_record.max_scope_kind) then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_PERMISSION_DENIED';
  end if;

  select permission_item.* into permission_record
  from public.platform_permissions permission_item
  where permission_item.code = p_permission_code
    and permission_item.status = 'active';

  if permission_record.id is null then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_PERMISSION_DENIED';
  end if;

  select role_permission.effect into grant_effect
  from public.platform_role_permissions role_permission
  where role_permission.role_id = role_record.id
    and role_permission.permission_id = permission_record.id
    and role_permission.status = 'active'
    and role_permission.revoked_at is null;

  if grant_effect is distinct from 'allow'::public.permission_effect then
    raise insufficient_privilege using message = 'internal authorization denied',
      detail = 'SAI_PERMISSION_DENIED';
  end if;

  return query select
    link_record.internal_identity_id,
    link_record.id,
    membership_record.id,
    current_auth_user_id,
    current_session_id,
    role_record.id,
    role_record.code,
    membership_record.scope_kind::text,
    membership_record.scope_institution_id,
    null::uuid,
    jwt_aal,
    p_permission_code,
    permission_record.requires_mfa;
end
$$;


ALTER FUNCTION "app_private"."require_superadmin_internal_context"("p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."revert_attendance_record"("target_record_id" "uuid", "target_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid:=app_private.current_person_id();
  record_row public.attendance_records%rowtype;
  session_row public.attendance_sessions%rowtype;
begin
  select * into record_row from public.attendance_records
  where id=target_record_id and status='active' for update;
  if record_row.id is null then raise exception 'active attendance record not found'; end if;
  select * into session_row from public.attendance_sessions
  where id=record_row.attendance_session_id;
  if not app_private.can_access_attendance_child(
    session_row.institution_id,session_row.unit_id,session_row.group_id,
    session_row.activity_id,record_row.child_context_id,true
  ) then raise exception 'attendance management required'; end if;
  if nullif(btrim(target_reason),'') is null then raise exception 'revert reason required'; end if;
  update public.attendance_records set status='inactive',
    reverted_by_person_id=actor_person_id,reverted_at=now(),
    revert_reason=btrim(target_reason),updated_at=now()
  where id=target_record_id;
  insert into public.attendance_record_revisions(
    attendance_record_id,action_code,before_json,after_json,reason,
    changed_by_person_id
  ) select target_record_id,'reverted',to_jsonb(record_row),to_jsonb(current_row),
    btrim(target_reason),actor_person_id
  from public.attendance_records current_row where id=target_record_id;
end;
$$;


ALTER FUNCTION "app_private"."revert_attendance_record"("target_record_id" "uuid", "target_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."routine_definition_json"("p_model_version_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    jsonb_build_object(
      'model_version_id', version_row.id,
      'model_id', version_row.model_id,
      'version', version_row.version,
      'sections', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', section_row.id,
            'name', section_row.name,
            'sort_order', section_row.sort_order,
            'fields', coalesce((
              select jsonb_agg(
                jsonb_build_object(
                  'id', field_row.id,
                  'label', field_row.label,
                  'kind', field_row.kind,
                  'sort_order', field_row.sort_order,
                  'is_required', field_row.is_required,
                  'initial_value', field_row.initial_value,
                  'minimum_value', field_row.minimum_value,
                  'maximum_value', field_row.maximum_value,
                  'options', coalesce((
                    select jsonb_agg(
                      jsonb_build_object(
                        'id', option_row.id,
                        'label', option_row.label,
                        'sort_order', option_row.sort_order
                      ) order by option_row.sort_order
                    )
                    from public.routine_field_options option_row
                    where option_row.field_id = field_row.id
                  ), '[]'::jsonb),
                  'conditions', coalesce((
                    select jsonb_agg(
                      jsonb_build_object(
                        'id', condition_row.id,
                        'parent_field_id', condition_row.parent_field_id,
                        'target_field_id', condition_row.target_field_id,
                        'option_id', condition_row.option_id,
                        'boolean_value', condition_row.boolean_value,
                        'depth', condition_row.depth
                      ) order by condition_row.id
                    )
                    from public.routine_field_conditions condition_row
                    where condition_row.target_field_id = field_row.id
                  ), '[]'::jsonb)
                ) order by field_row.sort_order
              )
              from public.routine_fields field_row
              where field_row.section_id = section_row.id
            ), '[]'::jsonb)
          ) order by section_row.sort_order
        )
        from public.routine_sections section_row
        where section_row.model_version_id = version_row.id
      ), '[]'::jsonb)
    ),
    '{}'::jsonb
  )
  from public.routine_model_versions version_row
  where version_row.id = p_model_version_id
$$;


