CREATE OR REPLACE FUNCTION "app_private"."run_notice_publication_job"("p_job_id" "uuid", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job app_private.notice_publication_jobs;
  notice public.platform_notices;
  failure_code text;
begin
  if auth.role() is distinct from 'service_role' or p_limit not between 1 and 5000 then
    raise exception using errcode = '42501', message = 'not_authorized';
  end if;
  select * into job from app_private.notice_publication_jobs
  where id = p_job_id and state = 'processing' for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'publication_job_not_found';
  end if;
  select * into notice from public.platform_notices where id = job.notice_id for share;

  failure_code := case
    when notice.id is null then 'notice_missing'
    when exists (select 1 from app_private.notice_publication_jobs newer
      where newer.notice_id = job.notice_id and newer.notice_version > job.notice_version)
      then 'notice_superseded'
    when notice.ends_at is not null and notice.ends_at <= now() then 'notice_expired'
    when notice.status::text not in ('scheduled', 'active') then 'notice_not_publishable'
    else null end;
  if failure_code is not null then
    update app_private.notice_publication_jobs
    set state = 'failed', attempts = 20, completed_at = null, locked_at = null,
        locked_by = null, last_error_code = failure_code
    where id = job.id;
    return jsonb_build_object('state', 'failed', 'error_code', failure_code);
  end if;

  -- Primeira pagina: materializa a audiencia vigente do aviso e registra no job.
  if job.cursor_key is null and job.resolved_count = 0
    and notice.audience_json is distinct from job.audience_snapshot then
    update app_private.notice_publication_jobs
    set audience_snapshot = notice.audience_json where id = job.id;
  end if;
  return app_private.materialize_notice_publication_job(p_job_id, p_limit);
end
$$;


ALTER FUNCTION "app_private"."run_notice_publication_job"("p_job_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."seed_institution_role_system_templates"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  role_spec record;
  target_role_id uuid;
  granted integer := 0;
  inserted integer;
begin
  for role_spec in
    select * from (values
      ('institution_admin', 'Administrador da instituicao', 'Acesso completo a instituicao, unidades e turmas.', 'institution', null::text[]),
      ('coordinator', 'Coordenacao', 'Leitura geral e gestao pedagogica, de rotina e de atividades.', 'institution',
        array['activities.assign_people','activities.create','activities.link_groups','activities.link_units','activities.manage','activities.read',
              'attendance.manage','attendance.read','circulars.circulars.create','circulars.circulars.manage','circulars.circulars.publish','circulars.circulars.read',
              'family.read','groups.manage','groups.read','happens.posts.create','happens.posts.publish','happens.posts.read','happens.posts.remove',
              'health_care.read','medication.read','moments.publications.create','moments.publications.publish','moments.publications.read',
              'now.publications.create','now.publications.publish','now.publications.read','people.read','profiles.about.read',
              'routine.correct','routine.manage_applications','routine.manage_models','routine.publish','routine.read','routine.record']),
      ('teacher', 'Professor(a)', 'Leitura da turma e registro de rotina, assiduidade e momentos.', 'unit',
        array['activities.read','attendance.manage','attendance.read','circulars.circulars.read','circulars.circulars.respond','family.read','groups.read',
              'happens.posts.create','happens.posts.read','health_care.read','medication.read','medication.record_evidence',
              'moments.publications.create','moments.publications.read','now.publications.create','now.publications.read','people.read',
              'routine.read','routine.record']),
      ('secretary', 'Secretaria', 'Pessoas, familias, transferencias e circulares.', 'institution',
        array['activities.read','circulars.circulars.create','circulars.circulars.manage','circulars.circulars.read','family.manage','family.read',
              'groups.read','people.assign_children','people.manage','people.read','transfers.manage','authorized_people.manage'])
    ) as spec(code, name, description, max_scope_kind, permission_codes)
  loop
    -- Sem unique em institution_roles: idempotencia por existencia explicita.
    insert into public.institution_roles (institution_id, code, name, description, is_system, status, max_scope_kind)
    select null, role_spec.code, role_spec.name, role_spec.description, true, 'active', role_spec.max_scope_kind
    where not exists (
      select 1 from public.institution_roles existing
      where existing.institution_id is null and existing.code = role_spec.code and existing.is_system
    );
    select existing.id into target_role_id from public.institution_roles existing
    where existing.institution_id is null and existing.code = role_spec.code and existing.is_system
    order by existing.created_at limit 1;
    if target_role_id is null then continue; end if;

    insert into public.institution_role_permissions (role_id, permission_id, effect, status)
    select target_role_id, permission_record.id, 'allow', 'active'
    from public.institution_permissions permission_record
    where permission_record.status = 'active'
      and (role_spec.permission_codes is null or permission_record.code = any(role_spec.permission_codes))
      and not exists (
        select 1 from public.institution_role_permissions existing
        where existing.role_id = target_role_id and existing.permission_id = permission_record.id
          and existing.status = 'active' and existing.revoked_at is null
      );
    get diagnostics inserted = row_count;
    granted := granted + inserted;
  end loop;
  return granted;
end
$$;


ALTER FUNCTION "app_private"."seed_institution_role_system_templates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."seed_qa_r03_internal_profile"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  inserted integer := 0;
begin
  insert into app_private.superadmin_internal_profiles (
    internal_identity_id, first_name, last_name, display_name, cpf,
    professional_email, job_title, department, internal_function
  )
  select identity.id, 'QA', 'R04 Sintetico', 'QA R04 Sintetico', '00000000000',
         'qa-r03@coelo.me', 'Usuario sintetico de teste', 'QA', 'Rodada 4'
  from app_private.superadmin_internal_identities identity
  join app_private.superadmin_internal_auth_links auth_link
    on auth_link.internal_identity_id = identity.id
  join auth.users auth_user on auth_user.id = auth_link.auth_user_id
  where auth_user.email = 'qa-r03@coelo.me'
    and not exists (
      select 1 from app_private.superadmin_internal_profiles existing
      where existing.internal_identity_id = identity.id
    );
  get diagnostics inserted = row_count;
  return inserted;
end
$$;


ALTER FUNCTION "app_private"."seed_qa_r03_internal_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."seed_qa_r06_group_user"("p_email" "text", "p_group" "text", "p_cpf" "text" DEFAULT '00000000000'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_auth_user_id uuid;
  v_identity_id uuid;
  v_role_id uuid;
  v_person_id uuid;
  v_inst_memberships integer := 0;
  v_created boolean := false;
begin
  select id into v_auth_user_id from auth.users where email = p_email;
  if v_auth_user_id is null then
    return jsonb_build_object('email', p_email, 'skipped', 'auth user ausente');
  end if;

  -- papel Owner de plataforma: o mesmo do qa-r03 (fonte de verdade em producao)
  select m.platform_role_id into v_role_id
  from app_private.superadmin_internal_memberships m
  join app_private.superadmin_internal_auth_links l on l.internal_identity_id = m.internal_identity_id
  join auth.users u on u.id = l.auth_user_id
  where u.email = 'qa-r03@coelo.me' and m.status = 'active' and m.scope_kind = 'platform'
  order by m.created_at limit 1;
  if v_role_id is null then
    select id into v_role_id from public.platform_roles where code = 'owner' limit 1;
  end if;
  if v_role_id is null then
    raise exception 'papel owner de plataforma nao encontrado' using errcode = '55000';
  end if;

  select l.internal_identity_id into v_identity_id
  from app_private.superadmin_internal_auth_links l
  where l.auth_user_id = v_auth_user_id
  order by (l.status = 'active') desc, l.created_at limit 1;

  if v_identity_id is null then
    insert into app_private.superadmin_internal_identities default values
      returning id into v_identity_id;
    insert into app_private.superadmin_internal_auth_links (internal_identity_id, auth_user_id, status)
      values (v_identity_id, v_auth_user_id, 'active');
    v_created := true;
  else
    update app_private.superadmin_internal_auth_links
      set status = 'active', suspended_at = null, revoked_at = null
      where internal_identity_id = v_identity_id and auth_user_id = v_auth_user_id
        and status <> 'active';
  end if;

  if not exists (
    select 1 from app_private.superadmin_internal_memberships m
    where m.internal_identity_id = v_identity_id and m.status = 'active' and m.scope_kind = 'platform'
  ) then
    insert into app_private.superadmin_internal_memberships (internal_identity_id, platform_role_id, scope_kind, status)
      values (v_identity_id, v_role_id, 'platform', 'active');
  end if;

  insert into app_private.superadmin_internal_profiles (
    internal_identity_id, first_name, last_name, display_name, cpf,
    professional_email, job_title, department, internal_function
  )
  select v_identity_id, 'QA', 'R06 ' || initcap(p_group), 'QA R06 ' || initcap(p_group), p_cpf,
         p_email, 'Usuario sintetico de teste', 'QA', 'Rodada 6 - ' || p_group
  where not exists (
    select 1 from app_private.superadmin_internal_profiles existing
    where existing.internal_identity_id = v_identity_id
  );

  -- ponte de ator: garante a pessoa de servico mesmo se o trigger nao disparou
  v_person_id := app_private.superadmin_internal_actor_sync(v_identity_id);

  insert into public.institution_memberships (person_id, institution_id, role_code, status, scope_kind)
  select v_person_id, inst.id, 'owner', 'active', 'institution'
  from public.institutions inst
  where inst.deleted_at is null
    and inst.slug in ('qa-r04-chat', 'qa-r04-cuidado-sintetico', 'qa-r04-escola')
    and not exists (
      select 1 from public.institution_memberships m
      where m.person_id = v_person_id and m.institution_id = inst.id
        and m.status = 'active' and m.revoked_at is null
    );
  get diagnostics v_inst_memberships = row_count;

  return jsonb_build_object(
    'email', p_email, 'identity_id', v_identity_id, 'person_id', v_person_id,
    'identity_created', v_created, 'institution_memberships_added', v_inst_memberships);
end
$$;


ALTER FUNCTION "app_private"."seed_qa_r06_group_user"("p_email" "text", "p_group" "text", "p_cpf" "text") OWNER TO "postgres";


