    "body_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "message_type" "text" DEFAULT 'text'::"text" NOT NULL,
    "status" "public"."record_status" DEFAULT 'active'::"public"."record_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "author_membership_id" "uuid",
    "author_experience_kind" "text",
    "author_role_snapshot" "text",
    "author_kind" "text" DEFAULT 'person'::"text" NOT NULL,
    "author_internal_identity_id" "uuid",
    "author_internal_membership_id" "uuid",
    CONSTRAINT "messages_author_experience_kind_check" CHECK (("author_experience_kind" = ANY (ARRAY['family'::"text", 'professional'::"text"]))),
    CONSTRAINT "messages_author_realm_check" CHECK (((("author_kind" = 'person'::"text") AND ("author_person_id" IS NOT NULL) AND ("author_internal_identity_id" IS NULL) AND ("author_internal_membership_id" IS NULL)) OR (("author_kind" = 'superadmin_internal'::"text") AND ("author_person_id" IS NULL) AND ("author_internal_identity_id" IS NOT NULL) AND ("author_internal_membership_id" IS NOT NULL))))
);


