    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "circular_id" "uuid" NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "revision_number" integer NOT NULL,
    "status" "public"."circular_revision_status" DEFAULT 'working'::"public"."circular_revision_status" NOT NULL,
    "title" "text" NOT NULL,
    "body_text" "text" DEFAULT ''::"text" NOT NULL,
    "created_by_person_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "published_at" timestamp with time zone,
    "created_by_internal_identity_id" "uuid",
    CONSTRAINT "circular_revisions_actor_realm_ck" CHECK ((("created_by_person_id" IS NOT NULL) <> ("created_by_internal_identity_id" IS NOT NULL))),
    CONSTRAINT "circular_revisions_body_length_check" CHECK (("char_length"("body_text") <= 4000)),
    CONSTRAINT "circular_revisions_revision_number_check" CHECK (("revision_number" > 0)),
    CONSTRAINT "circular_revisions_title_length_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 120)))
);

ALTER TABLE ONLY "public"."circular_revisions" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."circular_revisions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_circular_draft_json"("p_target" "public"."circulars", "p_revision" "public"."circular_revisions") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
select jsonb_build_object(
 'id',p_target.id,'version',p_target.management_version,'revision_id',p_revision.id,
 'title',p_revision.title,'status',p_target.status::text,
 'response_policy',p_target.response_policy::text,
 'responses_close_at',p_target.responses_close_at,
 'blocks',(select coalesce(jsonb_agg(case block_record.block_kind
   when 'text' then jsonb_build_object('id',block_record.id,'kind','text','text',block_record.text_content)
   when 'media' then jsonb_build_object('id',block_record.id,'kind','media','asset_ids',
     (select coalesce(jsonb_agg(link.media_asset_id order by link.display_order),'[]'::jsonb)
      from public.circular_media_links link where link.revision_id=p_revision.id and link.block_id=block_record.id))
   else jsonb_build_object('id',block_record.id,'kind','question','question',(
     select jsonb_build_object('id',question_record.id,'prompt',question_record.prompt,
       'kind',question_record.question_kind::text,'required',question_record.required,
       'options',(select coalesce(jsonb_agg(jsonb_build_object('id',option_record.id,
         'label',option_record.label) order by option_record.display_order),'[]'::jsonb)
        from public.circular_question_options option_record
        where option_record.question_id=question_record.id))
     from public.circular_questions question_record where question_record.block_id=block_record.id))
   end order by block_record.display_order),'[]'::jsonb)
   from public.circular_blocks block_record where block_record.revision_id=p_revision.id),
 'audiences',(select coalesce(jsonb_agg(distinct audience_record.audience_kind::text),'[]'::jsonb)
   from public.circular_audience_rules audience_record where audience_record.circular_id=p_target.id))
$$;


ALTER FUNCTION "app_private"."superadmin_circular_draft_json"("p_target" "public"."circulars", "p_revision" "public"."circular_revisions") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_circular_error"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_code like 'SAI_%' then
    app_private.superadmin_internal_error_envelope(p_code,p_correlation_id)
  else jsonb_build_object('ok',false,'data',null,'error',jsonb_build_object(
    'code',case when p_code in ('CIRCULAR_INVALID_INPUT','CIRCULAR_NOT_FOUND',
      'CIRCULAR_CONFLICT','CIRCULAR_INVALID_STATE','CIRCULAR_MEDIA_BLOCKED')
      then p_code else 'CIRCULAR_INTERNAL_ERROR' end,
    'message',case
      when p_code='CIRCULAR_NOT_FOUND' then 'Circular não encontrada.'
      when p_code='CIRCULAR_CONFLICT' then 'A Circular foi alterada. Recarregue e tente novamente.'
      when p_code='CIRCULAR_MEDIA_BLOCKED' then 'A mídia ainda não está disponível.'
      when p_code in ('CIRCULAR_INVALID_INPUT','CIRCULAR_INVALID_STATE') then 'Revise os dados da Circular.'
      else 'Não foi possível concluir a operação.' end,
    'correlation_id',p_correlation_id,
    'http_status',case when p_code='CIRCULAR_NOT_FOUND' then 404
      when p_code='CIRCULAR_CONFLICT' then 409
      when p_code like 'CIRCULAR_%' then 422 else 500 end)) end
$$;


ALTER FUNCTION "app_private"."superadmin_circular_error"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_circular_validate_scope"("p_institution" "uuid", "p_unit" "uuid", "p_group" "uuid", "p_activity" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_institution is null
    or (p_unit is not null and not exists(select 1 from public.units u
      where u.id=p_unit and u.institution_id=p_institution))
    or (p_group is not null and not exists(select 1 from public.groups g
      where g.id=p_group and g.institution_id=p_institution and g.unit_id=p_unit))
    or (p_activity is not null and not exists(select 1 from public.activity_definitions a
      where a.id=p_activity and a.institution_id=p_institution)) then
    raise invalid_parameter_value using message='invalid circular scope',detail='CIRCULAR_INVALID_INPUT';
  end if;
end
$$;


ALTER FUNCTION "app_private"."superadmin_circular_validate_scope"("p_institution" "uuid", "p_unit" "uuid", "p_group" "uuid", "p_activity" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_complete_institution_export"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare job public.import_jobs%rowtype;
begin
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null or job.target_domain<>'institutions_export' then
  raise no_data_found using message='institution export not found';
 end if;
 if p_storage_path!~('^exports/institutions/'||job.id||'/[0-9a-f-]+\.(csv|xlsx)$')
    or p_mime_type not in('text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    or p_size_bytes not between 1 and 5242880
    or p_row_count not between 1 and 5000
    or p_checksum_sha256!~'^[0-9a-f]{64}$' then
  raise invalid_parameter_value using message='invalid institution export artifact';
 end if;
 insert into public.import_files(import_job_id,storage_path,file_name,mime_type,size_bytes)
 values(job.id,p_storage_path,left(p_file_name,180),p_mime_type,p_size_bytes);
 update public.import_results set created_count=p_row_count,completed_at=now()
 where import_job_id=job.id;
 update public.import_jobs set processing_state='SUCESSO',status='active',finished_at=now(),
  summary=summary||jsonb_build_object(
    'phase','complete','storage_path',p_storage_path,
    'checksum_sha256',p_checksum_sha256,'row_count',p_row_count
  ),updated_at=now() where id=job.id;
 return app_private.institution_file_job_payload(job.id);
end
$_$;


ALTER FUNCTION "app_private"."superadmin_complete_institution_export"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_complete_unit_file_job"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  job public.import_jobs%rowtype;
  object_metadata jsonb;
begin
  select *
  into job
  from public.import_jobs
  where id = p_import_job_id
  for update;

  if job.id is null or job.target_domain <> 'units_export' then
    raise no_data_found using message = 'unit export not found';
  end if;

  if p_storage_path !~ (
      '^exports/units/' || job.id || '/[0-9a-f-]+\.(csv|xlsx)$'
    )
    or p_mime_type not in (
      'text/csv',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    )
    or p_size_bytes not between 1 and 5242880
    or p_row_count < 0
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
    or length(coalesce(p_file_name, '')) not between 1 and 180
  then
    raise invalid_parameter_value using message = 'invalid unit export artifact';
  end if;

  select object_record.metadata
  into object_metadata
  from storage.objects object_record
  where object_record.bucket_id = 'coelo-operations'
    and object_record.name = p_storage_path;

  if not found
    or coalesce((object_metadata ->> 'size')::bigint, -1) <> p_size_bytes
    or coalesce(object_metadata ->> 'mimetype', '') <> p_mime_type
  then
    raise check_violation using message = 'unit export object attestation mismatch';
  end if;

  if job.processing_state = 'SUCESSO' then
    return app_private.unit_file_job_payload(job.id);
  end if;

  insert into public.import_files(
    import_job_id,
    storage_path,
    file_name,
    mime_type,
    size_bytes
  ) values (
    job.id,
    p_storage_path,
    left(p_file_name, 180),
    p_mime_type,
    p_size_bytes
  );

  update public.import_results
  set created_count = p_row_count,
      completed_at = now()
  where import_job_id = job.id;

  update public.import_jobs
  set processing_state = 'SUCESSO',
      status = 'active',
      finished_at = now(),
      summary = summary || jsonb_build_object(
        'phase', 'complete',
        'storage_path', p_storage_path,
        'checksum_sha256', p_checksum_sha256,
        'row_count', p_row_count
      ),
      updated_at = now()
  where id = job.id;

  insert into audit.audit_logs(
    actor_person_id,
    mfa_aal,
    action_code,
    object_type,
    object_id,
    outcome,
    after_json
  ) values (
    job.created_by,
    'aal2',
    'unit.export.complete',
    'import_job',
    job.id,
    'success',
    jsonb_build_object('row_count', p_row_count)
  );

  return app_private.unit_file_job_payload(job.id);
end;
$_$;


ALTER FUNCTION "app_private"."superadmin_complete_unit_file_job"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_confirm_import_export_job"("p_import_job_id" "uuid", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
begin
  actor := app_private.assert_import_export_hub_actor();
  select * into job from public.import_jobs
  where id = p_import_job_id and created_by = actor;
  if job.id is null or job.target_domain <> 'units' then
    raise insufficient_privilege using message = 'import confirmation unavailable';
