    AS $$
declare actor uuid; job public.import_jobs%rowtype; request_hash bytea;
begin
 actor:=app_private.assert_institution_file_access('institutions.import');
 if p_idempotency_key is null or p_source_format not in('csv','xlsx')
    or length(coalesce(p_file_name,'')) not between 1 and 180
    or p_mime_type<>(case p_source_format when 'csv' then 'text/csv'
      else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' end) then
  raise invalid_parameter_value using message='invalid institution import file contract';
 end if;
 request_hash:=extensions.digest(pg_catalog.convert_to(jsonb_build_object(
  'file_name',p_file_name,'mime_type',p_mime_type,'format',p_source_format
 )::text,'UTF8'),'sha256');
