  'draft','PENDENTE',jsonb_build_object('phase','upload','original_name',left(p_file_name,180)),actor
 ) returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 return app_private.institution_file_job_payload(job.id);
end
$$;


ALTER FUNCTION "app_private"."superadmin_create_institution_import_job"("p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_create_scoped_activity_template"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_name" "text", "p_description" "text", "p_taxonomy_id" "uuid", "p_governance_kind" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  normalized_name text:=btrim(coalesce(p_name,''));
  normalized_description text:=btrim(coalesce(p_description,''));
  subtype public.activity_taxonomies%rowtype;
  receipt app_private.superadmin_internal_activity_template_create_receipts%rowtype;
  request_hash bytea;
  template_id uuid;
  template_code text;
  result jsonb;
  target_scope text:=case when p_unit_id is null then 'institution' else 'unit' end;
  correlation_id uuid:=gen_random_uuid();
begin
  select * into strict ctx
  from app_private.require_superadmin_internal_context('activities.templates.manage');
  if p_institution_id is null or p_taxonomy_id is null or p_idempotency_key is null
     or normalized_name='' or length(normalized_name)>120
     or length(normalized_description)>1000
     or p_governance_kind is null
     or p_governance_kind not in ('optional','mandatory')
     or not exists(select 1 from public.institutions institution
       where institution.id=p_institution_id and institution.status='active')
     or (p_unit_id is not null and not exists(select 1 from public.units unit
       where unit.id=p_unit_id and unit.institution_id=p_institution_id
        and unit.status<>'archived')) then
    raise invalid_parameter_value using message='invalid activity template request';
  end if;
  if ctx.scope_kind='institution'
     and ctx.scope_institution_id is distinct from p_institution_id then
    raise insufficient_privilege using message='institution scope denied',detail='SAI_PERMISSION_DENIED';
  end if;
  select taxonomy.* into subtype from public.activity_taxonomies taxonomy
  where taxonomy.id=p_taxonomy_id and taxonomy.taxonomy_kind='subtype'
   and taxonomy.status='active'
   and exists(select 1 from public.activity_taxonomies category
     where category.id=taxonomy.parent_id and category.taxonomy_kind='category'
      and category.status='active');
  if subtype.id is null then
    raise invalid_parameter_value using message='invalid activity template request';
  end if;
  request_hash:=extensions.digest(convert_to(jsonb_build_object(
    'institution_id',p_institution_id,'unit_id',p_unit_id,'name',normalized_name,
    'description',normalized_description,'taxonomy_id',p_taxonomy_id,
    'governance_kind',p_governance_kind)::text,'UTF8'),'sha256');
  perform pg_advisory_xact_lock(hashtextextended(
    'activity-template-create:'||p_idempotency_key::text,0));
  select create_receipt.* into receipt
  from app_private.superadmin_internal_activity_template_create_receipts create_receipt
  where create_receipt.request_id=p_idempotency_key;
  if receipt.request_id is not null then
    if receipt.internal_identity_id<>ctx.internal_identity_id then
      raise insufficient_privilege using message='template receipt actor mismatch';
    end if;
    if receipt.request_hash<>request_hash then
      raise invalid_parameter_value using message='idempotency key reused';
    end if;
    return receipt.result_json;
  end if;
  template_id:=app_private.activity_request_uuid('activity-template-create',p_idempotency_key);
  template_code:=coalesce(nullif(left(app_private.activity_slugify(normalized_name),48),''),'modelo')
    ||'-'||replace(p_idempotency_key::text,'-','');
  insert into public.activity_templates(
    id,scope_kind,institution_id,unit_id,code,name,description,taxonomy_id,
    governance_kind,template_payload,status,created_by_person_id
  ) values(
    template_id,target_scope,p_institution_id,p_unit_id,template_code,normalized_name,
    nullif(normalized_description,''),subtype.id,p_governance_kind,
    jsonb_build_object('taxonomy_code',subtype.code,'governance_kind',p_governance_kind),
    'active',null
  );
  result:=jsonb_build_object(
    'id',template_id,'code',template_code,'name',normalized_name,
    'description',nullif(normalized_description,''),'scope_kind',target_scope,
    'institution_id',p_institution_id,'unit_id',p_unit_id,
    'governance_kind',p_governance_kind,'taxonomy_id',subtype.parent_id,
    'subtype_id',subtype.id,'status','active');
  perform app_private.audit_append_superadmin_internal(
    ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
    ctx.session_id,'activities.templates.manage',ctx.aal,
    'activity.template.create','success',null,correlation_id,p_institution_id,
    'activity_template',template_id,jsonb_build_object(
      'id',template_id,'institution_id',p_institution_id,'unit_id',p_unit_id,
      'scope_kind',target_scope,'status','active'
    )
  );
  insert into app_private.superadmin_internal_activity_template_create_receipts(
    request_id,internal_identity_id,institution_id,unit_id,request_hash,
    result_template_id,result_json,correlation_id
  ) values(
    p_idempotency_key,ctx.internal_identity_id,p_institution_id,p_unit_id,
    request_hash,template_id,result,correlation_id
  );
  return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_create_scoped_activity_template"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_name" "text", "p_description" "text", "p_taxonomy_id" "uuid", "p_governance_kind" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_create_unit_import_job"("p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; job public.import_jobs%rowtype; request_hash bytea; extension text;
begin
 actor:=app_private.assert_unit_file_access('units.import',null);
 if p_idempotency_key is null or p_source_format not in('csv','xlsx')
    or length(coalesce(p_file_name,'')) not between 1 and 180
    or p_mime_type <> (case p_source_format when 'csv' then 'text/csv' else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' end) then
  raise invalid_parameter_value using message='invalid unit import file contract';
 end if;
 extension:=p_source_format;
 request_hash:=extensions.digest(pg_catalog.convert_to(jsonb_build_object(
  'file_name',p_file_name,'mime_type',p_mime_type,'format',p_source_format)::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into job from public.import_jobs where request_id=p_idempotency_key;
 if job.id is not null then
  if job.created_by<>actor or job.request_hash<>request_hash or job.target_domain<>'units' then
   raise invalid_parameter_value using message='idempotency key replay mismatch';
  end if;
  return app_private.unit_file_job_payload(job.id)||jsonb_build_object(
   'bucket','coelo-operations','upload_path','imports/units/'||job.id||'/source.'||extension);
 end if;
 insert into public.import_jobs(request_id,request_hash,target_domain,target_table,source_format,
  source_locale,target_locale,status,processing_state,summary,created_by)
 values(p_idempotency_key,request_hash,'units','units',p_source_format,'pt-BR','pt-BR',
  'draft','PENDENTE',jsonb_build_object('phase','upload','original_name',left(p_file_name,180)),actor)
 returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json)
 values(actor,'aal2','unit.import.create','import_job',job.id,'success',jsonb_build_object('format',p_source_format));
 return app_private.unit_file_job_payload(job.id)||jsonb_build_object(
  'bucket','coelo-operations','upload_path','imports/units/'||job.id||'/source.'||extension);
end $$;


ALTER FUNCTION "app_private"."superadmin_create_unit_import_job"("p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_duplicate_activity_template"("p_template_id" "uuid", "p_institution_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 actor uuid:=app_private.current_person_id();
 template public.activity_templates%rowtype;
 receipt app_private.activity_template_command_receipts%rowtype;
 request_hash bytea; payload jsonb; result jsonb;
 activity_id uuid; upsert_request_id uuid; template_defaults jsonb;
begin
 if (select auth.uid()) is null or actor is null then
  raise insufficient_privilege using message='authentication required';
 end if;
 if not app_private.has_platform_permission('activities.create') then
  raise insufficient_privilege using message='activities.create required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if p_template_id is null or p_institution_id is null or p_idempotency_key is null
    or not exists(select 1 from public.institutions institution
      where institution.id=p_institution_id) then
  raise invalid_parameter_value using message='invalid template activity request';
 end if;
 select * into template from public.activity_templates template_record
 where template_record.id=p_template_id and template_record.status='active'
  and (template_record.scope_kind='platform'
   or template_record.institution_id=p_institution_id);
 if template.id is null then
  raise no_data_found using message='template not found';
 end if;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'template_id',p_template_id,'institution_id',p_institution_id)::text,
  'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into receipt from app_private.activity_template_command_receipts
  where request_id=p_idempotency_key;
 if receipt.request_id is not null then
  if receipt.actor_person_id<>actor then
   raise insufficient_privilege using message='template receipt actor mismatch';
  end if;
  if receipt.command_kind<>'create_activity'
     or receipt.request_hash<>request_hash
     or receipt.source_template_id<>p_template_id then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return receipt.result_json;
 end if;
 activity_id:=app_private.activity_request_uuid(
  'activity-from-template',p_idempotency_key);
 upsert_request_id:=app_private.activity_request_uuid(
  'activity-from-template-upsert',p_idempotency_key);
 select coalesce(jsonb_object_agg(entry.key,entry.value),'{}'::jsonb)
 into template_defaults
 from jsonb_each(template.template_payload) entry
 where entry.key in (
  'description','governance_kind','identity_mode',
  'identity_initials','identity_color','identity_icon'
 );
 payload:=template_defaults||jsonb_build_object(
  'id',activity_id,'expected_version',0,
  'institution_id',p_institution_id,
  'name',template.name,
  'description',coalesce(template_defaults->>'description',template.description,''),
  'origin_scope_kind','institution',
  'governance_kind',coalesce(
   template_defaults->>'governance_kind',template.governance_kind),
  'status','draft','taxonomy_id',template.taxonomy_id,
  'identity_mode',coalesce(template_defaults->>'identity_mode','initials'),
  'identity_initials',coalesce(template_defaults->>'identity_initials',
   upper(left(regexp_replace(template.name,'[^[:alnum:]]','','g'),2))),
  'identity_color',coalesce(template_defaults->>'identity_color','#D63C00')
 );
 result:=app_private.superadmin_upsert_activity(payload,upsert_request_id);
 update public.activity_definitions
 set template_id=template.id,updated_at=now()
 where id=activity_id;
 result:=app_private.activity_management_payload(activity_id);
 insert into app_private.activity_template_command_receipts(
  request_id,command_kind,request_hash,actor_person_id,source_template_id,
  result_activity_id,result_json
 ) values(p_idempotency_key,'create_activity',request_hash,actor,template.id,
  activity_id,result);
 insert into audit.audit_logs(
  actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,
  outcome,after_json
 ) values(actor,auth.jwt()->>'aal','activity.template.instantiate',
  'activity_definition',activity_id,p_institution_id,'success',
  jsonb_build_object('template_id',template.id,'status','draft'));
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_duplicate_activity_template"("p_template_id" "uuid", "p_institution_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_fail_institution_file_job"("p_import_job_id" "uuid", "p_error_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job public.import_jobs%rowtype;
begin
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null or job.target_domain not in('institutions','institutions_export') then
  raise no_data_found using message='institution file job not found';
 end if;
 update public.import_jobs set processing_state='ERRO',status='draft',finished_at=now(),
  summary=summary||jsonb_build_object('phase','error','error_code',left(coalesce(p_error_code,'worker_error'),80)),
  updated_at=now() where id=job.id;
 return app_private.institution_file_job_payload(job.id);
end
$$;


ALTER FUNCTION "app_private"."superadmin_fail_institution_file_job"("p_import_job_id" "uuid", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_fail_unit_file_job"("p_import_job_id" "uuid", "p_error_code" "text", "p_expected_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job public.import_jobs%rowtype;
begin
  select * into job from public.import_jobs where id = p_import_job_id for update;
  if job.id is null
     or job.target_domain not in ('units','units_export')
     or job.request_id <> p_expected_request_id then
    raise insufficient_privilege using message = 'unit file job outside edge execution scope';
  end if;
  update public.import_jobs
  set processing_state = 'ERRO',
      status = 'draft',
      finished_at = now(),
      summary = summary || jsonb_build_object(
        'phase','error',
        'error_code',left(coalesce(p_error_code,'worker_error'),80)
      ),
      updated_at = now()
  where id = job.id;
  insert into audit.audit_logs(
    actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json
  ) values (
    job.created_by,'aal2','unit.file.fail','import_job',job.id,'failure',
    jsonb_build_object('error_code',left(coalesce(p_error_code,'worker_error'),80))
  );
  return app_private.unit_file_job_payload(job.id);
end
$$;


ALTER FUNCTION "app_private"."superadmin_fail_unit_file_job"("p_import_job_id" "uuid", "p_error_code" "text", "p_expected_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_file_job_fail"("p_import_job_id" "uuid", "p_error_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job public.import_jobs%rowtype;
begin
  select * into job from public.import_jobs where id = p_import_job_id for update;
  if job.id is null then return; end if;
  update public.import_jobs set
    processing_state = 'ERRO', finished_at = now(),
    summary = summary || jsonb_build_object('progress', 100, 'error_code', left(p_error_code, 80)),
    updated_at = now()
  where id = job.id and processing_state not in ('SUCESSO','REJEICAO');
  update app_private.import_processing_queue set
    state = 'ERRO', last_error_code = left(p_error_code, 80),
    locked_at = null, locked_by = null, updated_at = now()
  where import_job_id = job.id and state not in ('SUCESSO','REJEICAO');
  insert into audit.audit_logs(
    actor_person_id, action_code, object_type, object_id, outcome, after_json
  ) values (job.created_by, 'file.job.fail', 'import_job', job.id, 'failed', jsonb_build_object('error_code', left(p_error_code, 80)));
end $$;


ALTER FUNCTION "app_private"."superadmin_file_job_fail"("p_import_job_id" "uuid", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_finalize_activity_identity_upload"("p_activity_id" "uuid", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid:=app_private.current_person_id(); request_hash bytea;
 receipt app_private.activity_management_command_receipts%rowtype;
 before_record public.activity_definitions%rowtype; result jsonb;
 intent app_private.activity_identity_upload_intents%rowtype; object_metadata jsonb;
begin
 if (select auth.uid()) is null or actor is null
    or not app_private.has_platform_permission('activities.manage') then
  raise insufficient_privilege using message='activities.manage required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if p_idempotency_key is null or p_mime_type not in ('image/jpeg','image/png','image/webp')
    or p_size_bytes not between 1 and 2097152
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
  raise invalid_parameter_value using message='invalid identity result';
 end if;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'activity_id',p_activity_id,'path',p_storage_path,'mime_type',p_mime_type,
  'size_bytes',p_size_bytes,'checksum',p_checksum_sha256)::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into receipt from app_private.activity_management_command_receipts
  where request_id=p_idempotency_key;
 if receipt.request_id is not null then
  if receipt.actor_person_id<>actor then
   raise insufficient_privilege using message='idempotency receipt actor mismatch';
  end if;
  if receipt.command_kind<>'identity_finalize' or receipt.request_hash<>request_hash then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return receipt.result_json;
 end if;
 select * into intent from app_private.activity_identity_upload_intents intent_record
  where intent_record.activity_id=p_activity_id and intent_record.storage_path=p_storage_path
   and intent_record.actor_person_id=actor and intent_record.expires_at>now()
   and intent_record.consumed_at is null for update;
 if intent.request_id is null or intent.mime_type<>p_mime_type
    or intent.size_bytes<>p_size_bytes then
  raise insufficient_privilege using message='identity upload intent invalid';
 end if;
 select object_record.metadata into object_metadata from storage.objects object_record
  where object_record.bucket_id='coelo-identities' and object_record.name=p_storage_path;
 if object_metadata is null
    or coalesce((object_metadata->>'size')::bigint,-1)<>p_size_bytes
    or coalesce(object_metadata->>'mimetype','')<>p_mime_type then
  raise invalid_parameter_value using message='uploaded object metadata mismatch';
 end if;
 select * into before_record from public.activity_definitions activity
  where activity.id=p_activity_id for update;
 if before_record.id is null then raise no_data_found using message='activity not found'; end if;
 update public.activity_definitions set identity_mode='photo',
  identity_storage_bucket='coelo-identities',identity_storage_path=p_storage_path,
  identity_checksum_sha256=p_checksum_sha256,management_version=management_version+1,
  updated_at=now() where id=p_activity_id;
 update app_private.activity_identity_upload_intents set
  consumed_at=now(),checksum_sha256=p_checksum_sha256 where request_id=intent.request_id;
 result:=app_private.activity_management_payload(p_activity_id);
 insert into app_private.activity_management_command_receipts(
  request_id,command_kind,request_hash,actor_person_id,activity_id,result_json
 ) values(p_idempotency_key,'identity_finalize',request_hash,actor,p_activity_id,result);
 insert into audit.audit_logs(
  actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,
  outcome,before_json,after_json
 ) values(actor,auth.jwt()->>'aal','activity.identity.update','activity_definition',
  p_activity_id,before_record.institution_id,'success',to_jsonb(before_record),
  jsonb_build_object('bucket','coelo-identities','path',p_storage_path,
   'checksum_sha256',p_checksum_sha256));
 return result;
end $_$;


ALTER FUNCTION "app_private"."superadmin_finalize_activity_identity_upload"("p_activity_id" "uuid", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_finalize_institution_identity_upload"("p_media_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  media public.institution_identity_media%rowtype;
  old_media_id uuid;
begin
  select * into media from public.institution_identity_media where id=p_media_id for update;
  if media.id is null then raise no_data_found using message='media intent not found'; end if;
  perform app_private.assert_institution_identity_access(media.institution_id);
  if media.state<>'pending' then
    if media.state='active' then
      return jsonb_build_object('media_id',media.id,'state',media.state);
    end if;
    raise object_not_in_prerequisite_state using message='media intent is not pending';
  end if;
  if not exists(
    select 1 from storage.objects o
    where o.bucket_id=media.bucket_id and o.name=media.storage_path
  ) then
    raise object_not_in_prerequisite_state using message='uploaded object not found';
  end if;
  select case media.kind
    when 'profile' then b.logo_media_asset_id
    else b.cover_media_asset_id
  end into old_media_id
  from public.institution_branding b where b.institution_id=media.institution_id for update;
  if not found then raise no_data_found using message='institution branding not found'; end if;
  update public.institution_identity_media
  set state='archived',archived_at=now()
  where id=old_media_id and id<>media.id and state='active';
  update public.institution_identity_media
  set state='active',finalized_at=now()
  where id=media.id;
  update public.institution_branding
  set logo_media_asset_id=case when media.kind='profile' then media.id else logo_media_asset_id end,
      cover_media_asset_id=case when media.kind='cover' then media.id else cover_media_asset_id end,
      updated_at=now()
  where institution_id=media.institution_id;
  return jsonb_build_object('media_id',media.id,'state','active','replaced_media_id',old_media_id);
end
$$;


ALTER FUNCTION "app_private"."superadmin_finalize_institution_identity_upload"("p_media_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_finalize_unit_identity_upload"("request_id" "uuid", "checksum" "text", "replace_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid:=app_private.current_person_id();intent app_private.unit_identity_upload_intents%rowtype;
 metadata jsonb;previous public.unit_identity_media%rowtype;active public.unit_identity_media%rowtype;begin
 if(select auth.uid())is null or actor is null or checksum!~'^[0-9a-f]{64}$'then raise invalid_parameter_value using message='invalid identity finalization';end if;
 select*into intent from app_private.unit_identity_upload_intents i where i.request_id=$1 for update;
 if intent.request_id is null then raise no_data_found using message='identity upload intent not found';end if;
 if intent.actor_person_id<>actor or not app_private.has_scoped_platform_permission('units.update',intent.institution_id)or not app_private.has_mfa_aal2()
 then raise insufficient_privilege using message='units.update and AAL2 required';end if;
 if intent.consumed_at is not null then select*into active from public.unit_identity_media where id=intent.media_id;return to_jsonb(active);end if;
 if intent.expires_at<=now()then raise invalid_parameter_value using message='identity upload intent expired';end if;
 select o.metadata into metadata from storage.objects o where o.bucket_id='coelo-unit-identities'and o.name=intent.storage_path;
 if metadata is null or coalesce((metadata->>'size')::bigint,-1)<>intent.size_bytes or coalesce(metadata->>'mimetype','')<>intent.mime_type
 then raise invalid_parameter_value using message='uploaded object metadata mismatch';end if;
 if replace_id is not null then select*into previous from public.unit_identity_media m where m.id=replace_id and m.unit_id=intent.unit_id
  and m.media_kind=intent.media_kind and m.status='active'for update;
  if previous.id is null then raise invalid_parameter_value using message='replacement media is invalid';end if;
 elsif intent.media_kind in('profile','cover')then select*into previous from public.unit_identity_media m where m.unit_id=intent.unit_id
  and m.media_kind=intent.media_kind and m.status='active'order by activated_at desc nulls last limit 1 for update;end if;
 if previous.id is not null then update public.unit_identity_media set status='pending_delete',pending_delete_at=now()where id=previous.id;end if;
 update public.unit_identity_media set status='active',checksum_sha256=checksum,replaced_media_id=previous.id,activated_at=now()
 where id=intent.media_id returning*into active;
 if intent.media_kind='profile'then insert into public.unit_branding(unit_id,logo_media_asset_id,inherit_institution_branding,updated_by)
  values(intent.unit_id,intent.media_id,false,actor)on conflict(unit_id)do update set logo_media_asset_id=excluded.logo_media_asset_id,
  inherit_institution_branding=false,updated_by=actor,updated_at=now();
 elsif intent.media_kind='cover'then insert into public.unit_branding(unit_id,cover_media_asset_id,inherit_institution_branding,updated_by)
  values(intent.unit_id,intent.media_id,false,actor)on conflict(unit_id)do update set cover_media_asset_id=excluded.cover_media_asset_id,
  inherit_institution_branding=false,updated_by=actor,updated_at=now();end if;
 update app_private.unit_identity_upload_intents as upload_intent set consumed_at=now() where upload_intent.request_id=intent.request_id;
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,before_json,after_json)
 values(actor,auth.jwt()->>'aal','unit.identity.upload.finalize','unit_identity_media',active.id,active.institution_id,'success',
 case when previous.id is null then null else to_jsonb(previous)end,to_jsonb(active));
 return to_jsonb(active)||jsonb_build_object('cleanup_media_id',previous.id,'cleanup_path',previous.storage_path);end$_$;


ALTER FUNCTION "app_private"."superadmin_finalize_unit_identity_upload"("request_id" "uuid", "checksum" "text", "replace_id" "uuid") OWNER TO "postgres";


