COMMENT ON FUNCTION "app_private"."superadmin_form_is_internal_draft_v2"("p_form_id" "uuid") IS 'Temporary nominal coexistence for internally-created never-published drafts, not a permanent audience or author authorization policy.';



CREATE OR REPLACE FUNCTION "app_private"."superadmin_form_lock_legacy_resource_v2"("p_form_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.superadmin_form_assert_legacy_resource_v2(p_form_id);
  perform 1 from public.forms f where f.id=p_form_id for update;
  perform app_private.superadmin_form_assert_legacy_resource_v2(p_form_id);
end
$$;


