CREATE OR REPLACE FUNCTION "app_private"."superadmin_form_replace_draft_definition_v2"("p_version_id" "uuid", "p_sections" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  section_json jsonb;
  item_json jsonb;
  option_json jsonb;
  condition_json jsonb;
  source_section_id text;
  source_item_id text;
  source_option_id text;
  section_ids jsonb := '{}'::jsonb;
  item_ids jsonb := '{}'::jsonb;
  option_ids jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(p_sections) <> 'array' then
    raise invalid_parameter_value using message = 'sections must be an array';
  end if;
  if jsonb_array_length(p_sections) > 20 then
    raise check_violation using message = 'maximum 20 form sections';
  end if;

  delete from public.form_sections where form_version_id = p_version_id;

  for section_json in select value from jsonb_array_elements(p_sections) loop
    perform app_private.form_assert_payload_keys(
      section_json,
      array['id','title','description','position','items'],
      'form section'
    );
    source_section_id := nullif(section_json ->> 'id', '');
    if source_section_id is null or section_ids ? source_section_id then
      raise invalid_parameter_value using message = 'unique section id required';
    end if;
    section_ids := section_ids || jsonb_build_object(source_section_id, gen_random_uuid()::text);
    if jsonb_typeof(section_json -> 'items') <> 'array' then
      raise invalid_parameter_value using message = 'section items must be an array';
    end if;
    for item_json in select value from jsonb_array_elements(section_json -> 'items') loop
      perform app_private.form_assert_payload_keys(
        item_json,
        array['id','kind','label','help_text','position','is_required','config','options','conditions'],
        'form item'
      );
      source_item_id := nullif(item_json ->> 'id', '');
      if source_item_id is null or item_ids ? source_item_id then
        raise invalid_parameter_value using message = 'unique item id required';
      end if;
      item_ids := item_ids || jsonb_build_object(source_item_id, gen_random_uuid()::text);
      if jsonb_typeof(coalesce(item_json -> 'options', '[]'::jsonb)) <> 'array'
         or jsonb_typeof(coalesce(item_json -> 'conditions', '[]'::jsonb)) <> 'array' then
        raise invalid_parameter_value using message = 'item options and conditions must be arrays';
      end if;
      if jsonb_array_length(coalesce(item_json -> 'options', '[]'::jsonb)) > 50 then
        raise check_violation using message = 'maximum 50 form options per item';
      end if;
      -- P16: opcoes de Local sao do servidor (snapshot do catalogo), nunca do cliente.
      if item_json ->> 'kind' = 'location' then continue; end if;
      for option_json in select value from jsonb_array_elements(coalesce(item_json -> 'options', '[]'::jsonb)) loop
        perform app_private.form_assert_payload_keys(
          option_json, array['id','label','position'], 'form option'
        );
        source_option_id := nullif(option_json ->> 'id', '');
        if source_option_id is null or option_ids ? source_option_id then
          raise invalid_parameter_value using message = 'unique option id required';
        end if;
        option_ids := option_ids || jsonb_build_object(source_option_id, gen_random_uuid()::text);
      end loop;
    end loop;
  end loop;

  if (select count(*) from jsonb_object_keys(item_ids)) > 200 then
    raise check_violation using message = 'maximum 200 form items';
  end if;

  for section_json in select value from jsonb_array_elements(p_sections) loop
    source_section_id := section_json ->> 'id';
    insert into public.form_sections(id, form_version_id, title, description, position)
    values (
      (section_ids ->> source_section_id)::uuid,
      p_version_id,
      btrim(section_json ->> 'title'),
      nullif(btrim(section_json ->> 'description'), ''),
      (section_json ->> 'position')::integer
    );
    for item_json in select value from jsonb_array_elements(section_json -> 'items') loop
      source_item_id := item_json ->> 'id';
      insert into public.form_items(
        id, form_version_id, section_id, kind, label, help_text, is_required, position, config_jsonb
      ) values (
        (item_ids ->> source_item_id)::uuid,
        p_version_id,
        (section_ids ->> source_section_id)::uuid,
        item_json ->> 'kind',
        btrim(item_json ->> 'label'),
        nullif(btrim(item_json ->> 'help_text'), ''),
        coalesce((item_json ->> 'is_required')::boolean, false),
        (item_json ->> 'position')::integer,
        coalesce(item_json -> 'config', '{}'::jsonb)
      );
      if item_json ->> 'kind' = 'location' then continue; end if;
      for option_json in select value from jsonb_array_elements(coalesce(item_json -> 'options', '[]'::jsonb)) loop
        source_option_id := option_json ->> 'id';
        insert into public.form_question_options(id, form_version_id, item_id, label, position)
        values (
          (option_ids ->> source_option_id)::uuid,
          p_version_id,
          (item_ids ->> source_item_id)::uuid,
          btrim(option_json ->> 'label'),
          (option_json ->> 'position')::integer
        );
      end loop;
    end loop;
  end loop;

  for section_json in select value from jsonb_array_elements(p_sections) loop
    for item_json in select value from jsonb_array_elements(section_json -> 'items') loop
      source_item_id := item_json ->> 'id';
      for condition_json in select value from jsonb_array_elements(coalesce(item_json -> 'conditions', '[]'::jsonb)) loop
        perform app_private.form_assert_payload_keys(
          condition_json,
          array['source_item_id','kind','expected_yes_no','option_ids'],
          'form condition'
        );
        if not item_ids ? (condition_json ->> 'source_item_id') then
          raise invalid_parameter_value using message = 'condition source item not found';
        end if;
        for source_option_id in
          select value
            from jsonb_array_elements_text(
              case when condition_json ->> 'kind' = 'choice'
                then condition_json -> 'option_ids' else '[null]'::jsonb end
            )
        loop
          if condition_json ->> 'kind' = 'choice' and not option_ids ? source_option_id then
            raise invalid_parameter_value using message = 'condition source option not found';
          end if;
          insert into public.form_question_conditions(
            form_version_id, target_item_id, source_item_id, condition_kind,
            expected_yes_no, source_option_id
          ) values (
            p_version_id,
            (item_ids ->> source_item_id)::uuid,
            (item_ids ->> (condition_json ->> 'source_item_id'))::uuid,
            condition_json ->> 'kind',
            (condition_json ->> 'expected_yes_no')::boolean,
            case when source_option_id is null then null
                 else (option_ids ->> source_option_id)::uuid end
          );
        end loop;
      end loop;
    end loop;
  end loop;
  perform app_private.form_apply_location_options_v1(p_version_id);
  perform app_private.superadmin_form_validate_draft_definition_v2(p_version_id);
end;
$$;


ALTER FUNCTION "app_private"."superadmin_form_replace_draft_definition_v2"("p_version_id" "uuid", "p_sections" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_form_request_xlsx_v2"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare ctx app_private.superadmin_internal_context; initial_ctx app_private.superadmin_internal_context;
  form_row public.forms; job public.form_file_jobs; target_form uuid; payload_hash text;
  captured_count bigint; captured_schema jsonb; invalid_capture boolean;
  error_code text; correlation uuid:=gen_random_uuid();
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context('forms.responses.export');
    initial_ctx:=ctx;
    if current_setting('transaction_isolation')<>'read committed' or p_request_id is null
      or p_expected_version is null or p_expected_version<0
      or jsonb_typeof(p_payload) is distinct from 'object' then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    if jsonb_typeof(p_payload->'form_id') is distinct from 'string'
      or not (p_payload->>'form_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
      or exists(select 1 from jsonb_object_keys(p_payload) k where k<>'form_id') then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    if ctx.aal is null or ctx.aal not in ('aal1','aal2') or ctx.scope_kind is null
      or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and ctx.scope_institution_id is null) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    target_form:=(p_payload->>'form_id')::uuid;
    payload_hash:=encode(extensions.digest(convert_to(jsonb_build_object('form_id',target_form,
      'expected_version',p_expected_version)::text,'UTF8'),'sha256'),'hex');
    perform pg_advisory_xact_lock(hashtextextended(ctx.internal_identity_id::text||':'||p_request_id::text,0));
    select f.* into form_row from public.forms f join public.institutions i on i.id=f.institution_id
      where f.id=target_form and i.deleted_at is null
        and (ctx.scope_kind='platform' or f.institution_id=ctx.scope_institution_id) for share of f,i;
    if form_row.id is null then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
    select * into job from public.form_file_jobs where requested_by_internal_identity_id=ctx.internal_identity_id
      and request_id=p_request_id for update;
    if job.id is not null then
      if job.request_payload_sha256 is distinct from payload_hash or job.form_id is distinct from form_row.id
        or job.institution_id is distinct from form_row.institution_id then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
    else
      if form_row.management_version<>p_expected_version then
        raise serialization_failure using detail='SAI_CONCURRENT_CHANGE';
      end if;
      insert into public.form_file_jobs(form_id,institution_id,request_id,export_kind,artifact_provider,
        requested_by_internal_identity_id,requested_auth_link_id,requested_membership_id,requested_auth_session_id,
        requested_scope_kind,requested_scope_institution_id,requested_management_version,request_payload_sha256,
        snapshot_format_version,snapshot_row_count,snapshot_ready)
      values(form_row.id,form_row.institution_id,p_request_id,'xlsx','r2',ctx.internal_identity_id,
        ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,ctx.scope_kind,ctx.scope_institution_id,
        p_expected_version,payload_hash,2,0,false) returning * into job;
      -- All source rows, the complete version graph and typed values share one
      -- MVCC statement snapshot. Invalid incoming/outgoing links reject the
      -- entire request; inner joins must never silently omit damaged history.
      with captured as materialized (
        select r.*,case when r.identity_mode='anonymous' then gen_random_uuid() else r.id end export_id
        from public.form_responses r where r.form_id=form_row.id and r.status='submitted'
      ), versions as materialized (
        select v.* from public.form_versions v where v.id in(select form_version_id from captured)
      ), sections as materialized (
        select s.* from public.form_sections s where s.form_version_id in(select id from versions)
      ), items as materialized (
        select i.* from public.form_items i where i.form_version_id in(select id from versions)
      ), options as materialized (
        select o.* from public.form_question_options o where o.form_version_id in(select id from versions)
      ), conditions as materialized (
        select c.* from public.form_question_conditions c where c.form_version_id in(select id from versions)
      ), graph as (
        select jsonb_build_object('formId',form_row.id,'formTitle',form_row.title,'versions',
          coalesce((select jsonb_agg(jsonb_build_object(
            'versionId',v.id,'versionNumber',v.version_number,'state',v.state,
            'sections',coalesce((select jsonb_agg(jsonb_build_object(
              'sectionId',s.id,'title',s.title,'description',s.description,'position',s.position,
              'items',coalesce((select jsonb_agg(jsonb_build_object(
                'itemId',i.id,'kind',i.kind,'label',i.label,'helpText',i.help_text,
                'position',i.position,'required',i.is_required,'config',i.config_jsonb,
                'options',coalesce((select jsonb_agg(jsonb_build_object(
                  'optionId',o.id,'label',o.label,'position',o.position) order by o.position,o.id)
                  from options o where o.item_id=i.id),'[]'::jsonb)) order by i.position,i.id)
                from items i where i.section_id=s.id),'[]'::jsonb)) order by s.position,s.id)
              from sections s where s.form_version_id=v.id),'[]'::jsonb),
            'conditions',coalesce((select jsonb_agg(jsonb_build_object(
              'sourceItemId',c.source_item_id,'targetItemId',c.target_item_id,'kind',c.condition_kind,
              'expectedYesNo',c.expected_yes_no,'sourceOptionId',c.source_option_id)
              order by c.target_item_id,c.source_item_id,c.id)
              from conditions c where c.form_version_id=v.id),'[]'::jsonb))
            order by v.version_number,v.id) from versions v),'[]'::jsonb)) body
      ), invalid as (
        select exists(select 1 from captured r
          left join public.form_occurrences o on o.id=r.occurrence_id and o.form_id=r.form_id
            and o.institution_id=r.institution_id and o.form_version_id=r.form_version_id
          left join public.form_applications app on app.id=o.application_id
            and app.form_id=r.form_id and app.institution_id=r.institution_id
          left join versions v on v.id=r.form_version_id and v.form_id=r.form_id
          where r.institution_id<>form_row.institution_id or r.identity_mode<>form_row.identity_mode
            or o.id is null or app.id is null or v.id is null)
        or exists(select 1 from public.form_items i join public.form_sections s on s.id=i.section_id
          where (i.form_version_id in(select id from versions) or s.form_version_id in(select id from versions))
            and i.form_version_id<>s.form_version_id)
        or exists(select 1 from public.form_question_options o join public.form_items i on i.id=o.item_id
          where (o.form_version_id in(select id from versions) or i.form_version_id in(select id from versions))
            and (o.form_version_id<>i.form_version_id or i.kind not in ('single_choice','multiple_choice','location')))
        or exists(select 1 from public.form_question_conditions c
          join public.form_items target on target.id=c.target_item_id
          join public.form_items source on source.id=c.source_item_id
          left join public.form_question_options o on o.id=c.source_option_id
          where (c.form_version_id in(select id from versions) or target.form_version_id in(select id from versions)
            or source.form_version_id in(select id from versions))
            and (c.form_version_id<>target.form_version_id or c.form_version_id<>source.form_version_id
              or (c.condition_kind='yes_no' and source.kind<>'yes_no')
              or (c.condition_kind='choice' and (source.kind not in ('single_choice','multiple_choice')
                or o.id is null or o.form_version_id<>c.form_version_id or o.item_id<>source.id))))
        or exists(select 1 from public.form_answers a join captured r on r.id=a.response_id
          left join items i on i.id=a.item_id and i.form_version_id=r.form_version_id
          left join sections s on s.id=i.section_id and s.form_version_id=r.form_version_id
          where a.form_version_id<>r.form_version_id or i.id is null or s.id is null or a.answer_kind<>i.kind
            or case a.answer_kind
              when 'short_text' then a.text_value is null
              when 'integer' then a.integer_value is null
              when 'decimal' then a.decimal_value is null
              when 'money' then a.money_minor_units is null or jsonb_typeof(i.config_jsonb->'currency') is distinct from 'string'
              when 'date' then a.date_value is null
              when 'yes_no' then a.yes_no_value is null
              when 'scale' then a.scale_value is null else false end)
        or exists(select 1 from public.form_answer_options ao
          join public.form_answers a on a.id=ao.answer_id join captured r on r.id=a.response_id
          left join options o on o.id=ao.option_id and o.item_id=a.item_id and o.form_version_id=r.form_version_id
          where o.id is null or a.answer_kind not in ('single_choice','multiple_choice','location'))
        or exists(select 1 from public.form_answer_assets aa
          join public.form_answers a on a.id=aa.answer_id join captured r on r.id=a.response_id
          left join public.form_assets asset on asset.id=aa.asset_id and asset.item_id=a.item_id
            and asset.occurrence_id=r.occurrence_id and asset.institution_id=r.institution_id
          where asset.id is null or asset.state<>'finalized' or a.answer_kind not in ('photo','gallery')
            or (r.identity_mode='identified' and asset.prepared_by_person_id is distinct from r.respondent_person_id)
            or (r.identity_mode='anonymous' and asset.prepared_by_person_id is not null)) bad
      ), inserted as (
        insert into app_private.form_xlsx_snapshot_rows(file_job_id,sequence_number,response_id,submission_jsonb)
        select job.id,row_number() over(order by r.export_id),r.id,jsonb_build_object(
          'responseId',r.export_id,'occurrenceId',r.occurrence_id,'versionId',r.form_version_id,
          'metadata',jsonb_build_object('form_id',r.form_id,'identity_mode',r.identity_mode)
            ||case when r.identity_mode='identified' then jsonb_build_object(
              'respondent',(select display_name from public.people where id=r.respondent_person_id),
              'submitted_at',r.submitted_at) else '{}'::jsonb end,
          'answers',coalesce((select jsonb_agg(jsonb_build_object('itemId',i.id,'values',case
            when a.answer_kind in ('single_choice','multiple_choice','location') then coalesce((
              select jsonb_agg(jsonb_build_object('kind','choice','optionId',ao.option_id) order by ao.position,ao.option_id)
              from public.form_answer_options ao where ao.answer_id=a.id),'[]'::jsonb)
            when a.answer_kind in ('photo','gallery') then coalesce((
              select jsonb_agg(jsonb_build_object('kind','media','assetId',aa.asset_id) order by aa.position,aa.asset_id)
              from public.form_answer_assets aa where aa.answer_id=a.id),'[]'::jsonb)
            else jsonb_build_array(case a.answer_kind
              when 'short_text' then jsonb_build_object('kind','text','value',a.text_value)
              when 'integer' then jsonb_build_object('kind','integer','value',a.integer_value::text)
              when 'decimal' then jsonb_build_object('kind','decimal','value',a.decimal_value::text)
              when 'money' then jsonb_build_object('kind','money','minorUnits',a.money_minor_units::text,'currency',i.config_jsonb->>'currency')
              when 'date' then jsonb_build_object('kind','date','value',a.date_value::text)
              when 'yes_no' then jsonb_build_object('kind','boolean','value',a.yes_no_value)
              when 'scale' then jsonb_build_object('kind','integer','value',a.scale_value::text) end) end)
            order by s.position,i.position,i.id)
            from public.form_answers a join items i on i.id=a.item_id
            join sections s on s.id=i.section_id where a.response_id=r.id),'[]'::jsonb))
          from captured r where not (select bad from invalid)
          returning 1
      ) select graph.body,invalid.bad,(select count(*) from inserted)
        into captured_schema,invalid_capture,captured_count from graph cross join invalid;
      if invalid_capture then raise check_violation using detail='SAI_UNAVAILABLE'; end if;
      update public.form_file_jobs set snapshot_ready=true,snapshot_row_count=captured_count,
        snapshot_schema=captured_schema,
        snapshot_schema_sha256=encode(extensions.digest(convert_to(captured_schema::text,'UTF8'),'sha256'),'hex')
        where id=job.id returning * into job;

      insert into app_private.form_worker_jobs(job_kind,aggregate_id,payload_jsonb)
        values('export_xlsx_r2_v1',job.id,jsonb_build_object('file_job_id',job.id));
    end if;
    -- Any wait or capture may span a revocation. Refresh before committing work.
    select * into strict ctx from app_private.require_superadmin_internal_context('forms.responses.export');
    if row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,ctx.scope_kind,ctx.scope_institution_id)
      is distinct from row(initial_ctx.internal_identity_id,initial_ctx.internal_auth_link_id,initial_ctx.internal_membership_id,
        initial_ctx.session_id,initial_ctx.scope_kind,initial_ctx.scope_institution_id)
      or not exists(select 1 from auth.sessions s where s.id=ctx.session_id and s.user_id=ctx.auth_user_id
        and (s.not_after is null or s.not_after>clock_timestamp())) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
      ctx.session_id,'forms.responses.export',ctx.aal,'superadmin.forms.export.request','success',null,
      correlation,job.institution_id,'form_file_job',job.id);
  exception when others then
    get stacked diagnostics error_code=pg_exception_detail;
    error_code:=app_private.superadmin_internal_error_envelope(error_code,correlation)#>>'{error,code}';
  end;
  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified('forms.responses.export',
      'superadmin.forms.export.request',error_code,correlation);
    return app_private.superadmin_internal_error_envelope(error_code,correlation);
  end if;
  return jsonb_build_object('ok',true,'error',null,'data',jsonb_build_object('id',job.id,'status',job.state,
    'progress',job.progress,'download_path',null,'error_code',job.error_code,'expires_at',job.expires_at,
    'download_available',job.state='succeeded' and job.expires_at>clock_timestamp()));
end;
$_$;


ALTER FUNCTION "app_private"."superadmin_form_request_xlsx_v2"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_form_validate_draft_definition_v2"("p_version_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_has_cycle boolean;
  v_max_depth integer;
begin
  if (select count(*) from public.form_sections where form_version_id = p_version_id) > 20 then
    raise check_violation using message = 'maximum 20 form sections';
  end if;
  if (select count(*) from public.form_items where form_version_id = p_version_id) > 200 then
    raise check_violation using message = 'maximum 200 form items';
  end if;
  if exists (
    select 1
      from public.form_items item
     where item.form_version_id = p_version_id
       and item.kind in ('single_choice', 'multiple_choice')
       and (select count(*) from public.form_question_options option_row where option_row.item_id = item.id) not between 2 and 50
  ) then
    raise check_violation using message = 'choice item requires between 2 and 50 options';
  end if;
  if exists (
    select 1
      from public.form_question_options option_row
      join public.form_items item on item.id = option_row.item_id
     where option_row.form_version_id = p_version_id
       and (item.form_version_id <> p_version_id or item.kind not in ('single_choice', 'multiple_choice', 'location'))
  ) then
    raise check_violation using message = 'form options require a choice item in the same version';
  end if;
  if exists (
    select 1
      from public.form_question_options option_row
      join public.form_items item on item.id = option_row.item_id
     where option_row.form_version_id = p_version_id
       and ((item.kind = 'location') <> (option_row.location_id is not null))
  ) then
    raise check_violation using message = 'location options must come from the catalog snapshot';
  end if;
  if exists (
    select 1
      from public.form_question_conditions condition_row
      join public.form_items source_item on source_item.id = condition_row.source_item_id
     where condition_row.form_version_id = p_version_id
       and (
         (condition_row.condition_kind = 'yes_no' and source_item.kind <> 'yes_no')
         or (condition_row.condition_kind = 'choice' and source_item.kind not in ('single_choice', 'multiple_choice'))
       )
  ) then
    raise check_violation using message = 'condition source kind is not allowed';
  end if;
  if exists (
    select 1
      from public.form_items item
      join public.form_sections section_row on section_row.id = item.section_id
     where item.form_version_id = p_version_id
       and section_row.form_version_id <> p_version_id
  ) or exists (
    select 1
      from public.form_question_conditions condition_row
      join public.form_items source_item on source_item.id = condition_row.source_item_id
      join public.form_items target_item on target_item.id = condition_row.target_item_id
     where condition_row.form_version_id = p_version_id
       and (source_item.form_version_id <> p_version_id or target_item.form_version_id <> p_version_id)
  ) then
    raise check_violation using message = 'form definition version mismatch';
  end if;

  if exists (
    select 1 from public.form_question_conditions c
    join public.form_question_options o on o.id=c.source_option_id
    where c.form_version_id=p_version_id and (o.item_id<>c.source_item_id or o.form_version_id<>p_version_id)
  ) then raise check_violation using message='condition option does not belong to its source'; end if;

  -- One logical edge can have 50 option rows. Never enumerate option paths.
  -- UNION deduplicates (origin,target,depth), bounded by 200*200*5 states.
  with recursive edges(source_id,target_id) as (
    select distinct source_item_id,target_item_id from public.form_question_conditions
    where form_version_id=p_version_id
  ), walk(origin_id,current_item_id,depth) as (
    select source_id,target_id,1 from edges
    union
    select walk.origin_id,edges.target_id,walk.depth+1
    from walk join edges on edges.source_id=walk.current_item_id
    where walk.depth<5
  )
  select coalesce(bool_or(origin_id=current_item_id), false), coalesce(max(depth), 0)
    into v_has_cycle, v_max_depth
    from walk;

  if v_has_cycle then
    raise check_violation using message = 'form condition cycle';
  end if;
  if v_max_depth > 4 then
    raise check_violation using message = 'maximum form condition depth is 4';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."superadmin_form_validate_draft_definition_v2"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_form_validate_draft_payload_v2"("p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  s jsonb; i jsonb; o jsonb; c jsonb;
  field_name text;
  section_position integer:=0;
  item_position integer;
  option_position integer;
  item_count integer:=0;
begin
  -- Technical request ceiling; relational limits below remain authoritative.
  if p_payload is null or pg_catalog.jsonb_typeof(p_payload) is distinct from 'object'
    or pg_catalog.octet_length(p_payload::text)>33554432
    or p_payload-array['id','institution_id','kind','identity_mode','response_unit','title','description','sections']<>'{}'::jsonb
    or not (p_payload ?& array['institution_id','kind','identity_mode','response_unit','title','sections']) then
    raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
  end if;
  foreach field_name in array array['institution_id','kind','identity_mode','response_unit','title'] loop
    if pg_catalog.jsonb_typeof(p_payload->field_name) is distinct from 'string' then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
  end loop;
  foreach field_name in array array['id','description'] loop
    if p_payload ? field_name and p_payload->field_name<>'null'::jsonb
      and pg_catalog.jsonb_typeof(p_payload->field_name)<>'string' then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
  end loop;
  if p_payload->>'institution_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or (p_payload->>'id' is not null and p_payload->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    or p_payload->>'kind' not in ('form','quick_poll')
    or p_payload->>'identity_mode' not in ('identified','anonymous')
    or p_payload->>'response_unit' not in ('person','child_family_context')
    or pg_catalog.char_length(btrim(p_payload->>'title')) not between 1 and 200
    or pg_catalog.char_length(p_payload->>'description')>4000
    or pg_catalog.jsonb_typeof(p_payload->'sections') is distinct from 'array' then
    raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
  end if;
  if pg_catalog.jsonb_array_length(p_payload->'sections')>20 then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
  for s in select value from pg_catalog.jsonb_array_elements(p_payload->'sections') loop
    if pg_catalog.jsonb_typeof(s) is distinct from 'object'
      or s-array['id','title','description','position','items']<>'{}'::jsonb
      or not (s ?& array['id','title','position','items']) then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
    if pg_catalog.jsonb_typeof(s->'id') is distinct from 'string' or pg_catalog.char_length(s->>'id') not between 1 and 128
      or pg_catalog.jsonb_typeof(s->'title') is distinct from 'string'
      or pg_catalog.jsonb_typeof(s->'position') is distinct from 'number' or s->>'position' !~ '^[0-9]+$'
      or (s->>'position')::integer<>section_position
      or pg_catalog.jsonb_typeof(s->'items') is distinct from 'array'
      or (s ? 'description' and s->'description'<>'null'::jsonb and pg_catalog.jsonb_typeof(s->'description')<>'string') then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    section_position:=section_position+1; item_position:=0;
    for i in select value from pg_catalog.jsonb_array_elements(s->'items') loop
      item_count:=item_count+1;
      if item_count>200 or pg_catalog.jsonb_typeof(i) is distinct from 'object'
        or i-array['id','kind','label','help_text','position','is_required','config','options','conditions']<>'{}'::jsonb
        or not (i ?& array['id','kind','label','position']) then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
      foreach field_name in array array['id','kind','label'] loop
        if pg_catalog.jsonb_typeof(i->field_name) is distinct from 'string' then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
      end loop;
      if pg_catalog.char_length(i->>'id') not between 1 and 128
        or pg_catalog.jsonb_typeof(i->'position') is distinct from 'number' or i->>'position' !~ '^[0-9]+$'
        or (i->>'position')::integer<>item_position
        or (i ? 'help_text' and i->'help_text'<>'null'::jsonb and pg_catalog.jsonb_typeof(i->'help_text')<>'string')
        or (i ? 'is_required' and pg_catalog.jsonb_typeof(i->'is_required') is distinct from 'boolean')
        or (i ? 'config' and pg_catalog.jsonb_typeof(i->'config') is distinct from 'object') then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      item_position:=item_position+1; option_position:=0;
      foreach field_name in array array['options','conditions'] loop
        if i ? field_name and pg_catalog.jsonb_typeof(i->field_name) is distinct from 'array' then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
      end loop;
      if pg_catalog.jsonb_array_length(coalesce(i->'options','[]'))>50
        or pg_catalog.jsonb_array_length(coalesce(i->'conditions','[]'))>200 then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
      for o in select value from pg_catalog.jsonb_array_elements(coalesce(i->'options','[]')) loop
        -- P16: a projecao devolve location_id/location_status/location_available nas
        -- opcoes de item `location`; o cliente pode devolve-las e o servidor as ignora.
        if pg_catalog.jsonb_typeof(o) is distinct from 'object'
          or o-array['id','label','position','location_id','location_status','location_available']<>'{}'::jsonb
          or (i->>'kind'<>'location' and o-array['id','label','position']<>'{}'::jsonb)
          or not (o ?& array['id','label','position'])
          or pg_catalog.jsonb_typeof(o->'id') is distinct from 'string' or pg_catalog.char_length(o->>'id') not between 1 and 128
          or pg_catalog.jsonb_typeof(o->'label') is distinct from 'string'
          or pg_catalog.jsonb_typeof(o->'position') is distinct from 'number' or o->>'position' !~ '^[0-9]+$'
          or (o->>'position')::integer<>option_position then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
        option_position:=option_position+1;
      end loop;
      for c in select value from pg_catalog.jsonb_array_elements(coalesce(i->'conditions','[]')) loop
        if pg_catalog.jsonb_typeof(c) is distinct from 'object'
          or c-array['source_item_id','kind','expected_yes_no','option_ids']<>'{}'::jsonb
          or pg_catalog.jsonb_typeof(c->'source_item_id') is distinct from 'string'
          or pg_catalog.char_length(c->>'source_item_id') not between 1 and 128
          or pg_catalog.jsonb_typeof(c->'kind') is distinct from 'string'
          or c->>'kind' not in ('yes_no','choice') then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
        if c->>'kind'='yes_no' then
          if pg_catalog.jsonb_typeof(c->'expected_yes_no') is distinct from 'boolean'
            or (c ? 'option_ids' and c->'option_ids' not in ('[]'::jsonb,'null'::jsonb)) then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
        else
          if (c ? 'expected_yes_no' and c->'expected_yes_no'<>'null'::jsonb)
            or pg_catalog.jsonb_typeof(c->'option_ids') is distinct from 'array' then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
          if pg_catalog.jsonb_array_length(c->'option_ids') not between 1 and 50
            or exists(select 1 from pg_catalog.jsonb_array_elements(c->'option_ids') v where pg_catalog.jsonb_typeof(v)<>'string' or pg_catalog.char_length(v#>>'{}') not between 1 and 128) then
            raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
          end if;
        end if;
      end loop;
    end loop;
  end loop;
end
$_$;


ALTER FUNCTION "app_private"."superadmin_form_validate_draft_payload_v2"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_forms_authoring_institutions_v2"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  ctx app_private.superadmin_internal_context;
  initial_ctx app_private.superadmin_internal_context;
  correlation uuid:=pg_catalog.gen_random_uuid();
  error_code text;
  search_text text:='';
  search_pattern text;
  page_limit integer:=20;
  cursor_name text;
  cursor_id uuid;
  result jsonb;
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context('forms.manage');
    if ctx.aal is null or ctx.aal not in ('aal1','aal2')
      or ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and ctx.scope_institution_id is null) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    initial_ctx:=ctx;
    if pg_catalog.current_setting('transaction_isolation')<>'read committed' then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    if p_query is null or pg_catalog.jsonb_typeof(p_query)<>'object'
      or pg_catalog.octet_length(pg_catalog.convert_to(p_query::text,'UTF8'))>8192 then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    if exists(select 1 from pg_catalog.jsonb_object_keys(p_query) k where k not in ('search','limit','cursor')) then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    if p_query ? 'search' then
      if pg_catalog.jsonb_typeof(p_query->'search') is distinct from 'string'
        or pg_catalog.char_length(p_query->>'search')>160 then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      search_text:=p_query->>'search';
    end if;
    if p_query ? 'limit' then
      if pg_catalog.jsonb_typeof(p_query->'limit') is distinct from 'number' then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      if (p_query->>'limit')::numeric<>pg_catalog.trunc((p_query->>'limit')::numeric)
        or (p_query->>'limit')::numeric<1 or (p_query->>'limit')::numeric>50 then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      page_limit:=(p_query->>'limit')::numeric::integer;
    end if;
    if p_query ? 'cursor' and p_query->'cursor'<>'null'::jsonb then
      if pg_catalog.jsonb_typeof(p_query->'cursor') is distinct from 'object' then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      if not ((p_query->'cursor') ?& array['name_key','id'])
        or exists(select 1 from pg_catalog.jsonb_object_keys(p_query->'cursor') k where k not in ('name_key','id'))
        or pg_catalog.jsonb_typeof(p_query#>'{cursor,name_key}') is distinct from 'string'
        or pg_catalog.jsonb_typeof(p_query#>'{cursor,id}') is distinct from 'string'
        or pg_catalog.char_length(p_query#>>'{cursor,name_key}')>1024
        or (p_query#>>'{cursor,id}') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      cursor_name:=p_query#>>'{cursor,name_key}';
      cursor_id:=(p_query#>>'{cursor,id}')::uuid;
    end if;
    -- Literal search. The same lower(public_name), id pair orders and seeks.
    search_pattern:='%'||pg_catalog.replace(pg_catalog.replace(pg_catalog.replace(
      search_text,E'\\',E'\\\\'),'%',E'\\%'),'_',E'\\_')||'%';
    with candidates as materialized (
      select i.id,i.public_name,pg_catalog.lower(i.public_name) as name_key
      from public.institutions i
      where i.status='active' and i.deleted_at is null
        and (ctx.scope_kind='platform' or i.id=ctx.scope_institution_id)
        and (search_text='' or i.public_name ilike search_pattern escape E'\\')
        and (cursor_id is null or (pg_catalog.lower(i.public_name),i.id)>(cursor_name,cursor_id))
      order by pg_catalog.lower(i.public_name),i.id limit page_limit+1
    ), visible as (
      select * from candidates order by name_key,id limit page_limit
    )
    select pg_catalog.jsonb_build_object(
      'items',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'id',id,'public_name',public_name) order by name_key,id) from visible),'[]'::jsonb),
      'has_more',(select count(*)>page_limit from candidates),
      'next_cursor',case when (select count(*)>page_limit from candidates)
        then (select pg_catalog.jsonb_build_object('name_key',name_key,'id',id)
              from visible order by name_key desc,id desc limit 1) else null end
    ) into result;
    -- Candidate rows are a snapshot, not an authorization grant. Save performs
    -- its own real-institution check. Reauthorize the actor before returning it.
    select * into strict ctx from app_private.require_superadmin_internal_context('forms.manage');
    if row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
           ctx.auth_user_id,ctx.session_id,ctx.scope_kind,ctx.scope_institution_id)
       is distinct from row(initial_ctx.internal_identity_id,initial_ctx.internal_auth_link_id,
           initial_ctx.internal_membership_id,initial_ctx.auth_user_id,initial_ctx.session_id,
           initial_ctx.scope_kind,initial_ctx.scope_institution_id)
      or ctx.aal is null or ctx.aal not in ('aal1','aal2')
      or ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and ctx.scope_institution_id is null) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    if not exists(select 1 from auth.sessions s where s.id=initial_ctx.session_id
      and s.user_id=initial_ctx.auth_user_id
      and (s.not_after is null or s.not_after>pg_catalog.clock_timestamp())) then
      raise insufficient_privilege using detail='SAI_SESSION_INVALID';
    end if;
  exception
    when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then
      error_code:='SAI_INVALID_ARGUMENT';
    when others then
      get stacked diagnostics error_code=pg_exception_detail;
      error_code:=app_private.superadmin_internal_error_envelope(error_code,correlation)#>>'{error,code}';
  end;
  -- Audit is intentionally outside the error conversion block: audit failure
  -- cannot produce a successful response or a silently unaudited denial.
  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'forms.manage','superadmin.forms.authoring.institutions',error_code,correlation);
    return app_private.superadmin_internal_error_envelope(error_code,correlation);
  end if;
  perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,ctx.internal_auth_link_id,
    ctx.internal_membership_id,ctx.session_id,'forms.manage',ctx.aal,
    'superadmin.forms.authoring.institutions','success',null,correlation,ctx.scope_institution_id);
  return pg_catalog.jsonb_build_object('ok',true,'data',result,'error',null);
end
$_$;


ALTER FUNCTION "app_private"."superadmin_forms_authoring_institutions_v2"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_forms_directory_v2"("p_query" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  ctx app_private.superadmin_internal_context;
  correlation uuid := pg_catalog.gen_random_uuid();
  error_code text;
  result jsonb;
  page_limit integer := 25;
  institution_filter uuid;
  search_text text;
  statuses text[] := '{}';
  operational_statuses text[] := '{}';
  kinds text[] := '{}';
  starts_on date;
  ends_on date;
  cursor_updated timestamptz;
  cursor_id uuid;
  field_name text;
  allowed_values text[];
  values_array text[];
begin
  -- Only authorization and projection are caught. Audit failures must escape.
  begin
  -- The guard must run before any cast or query derived from client input.
  select * into strict ctx from app_private.require_superadmin_internal_context('forms.read');
  if ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
    or (ctx.scope_kind='institution' and ctx.scope_institution_id is null)
    or ctx.aal is null or ctx.aal not in ('aal1','aal2') then
    raise insufficient_privilege using detail = 'SAI_INTERNAL_CONTEXT_DENIED';
  end if;

  if p_query is null or pg_catalog.jsonb_typeof(p_query) <> 'object'
    or pg_catalog.octet_length(p_query::text) > 16384
    or p_query - array['institution_id','search','statuses','operational_statuses','kinds',
      'starts_on_or_after','ends_on_or_before','cursor_updated_at','cursor_id','limit'] <> '{}'::jsonb then
    raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
  end if;
  if p_query ? 'limit' then
    if pg_catalog.jsonb_typeof(p_query->'limit') is distinct from 'number'
      or p_query->>'limit' !~ '^[0-9]{1,3}$' then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
    page_limit := (p_query->>'limit')::integer;
    if page_limit not between 1 and 100 then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
  end if;

  foreach field_name in array array['institution_id','search','starts_on_or_after','ends_on_or_before','cursor_updated_at','cursor_id'] loop
    if p_query ? field_name and p_query->field_name <> 'null'::jsonb
      and pg_catalog.jsonb_typeof(p_query->field_name) <> 'string' then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
  end loop;
  if p_query->>'institution_id' is not null then
    if p_query->>'institution_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
    institution_filter := (p_query->>'institution_id')::uuid;
  end if;
  search_text := p_query->>'search';
  if pg_catalog.char_length(search_text) > 500 then
    raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
  end if;
  search_text := nullif(search_text,'');
  -- Search is literal, not a client-authored LIKE pattern.
  search_text := pg_catalog.replace(pg_catalog.replace(pg_catalog.replace(search_text,'\','\\'),'%','\%'),'_','\_');

  foreach field_name in array array['statuses','operational_statuses','kinds'] loop
    if not (p_query ? field_name) then continue; end if;
    if pg_catalog.jsonb_typeof(p_query->field_name) is distinct from 'array' then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
    allowed_values := case field_name
      when 'statuses' then array['draft','published','archived']
      when 'operational_statuses' then array['draft','scheduled','active','closed','archived']
      else array['form','quick_poll'] end;
    if pg_catalog.jsonb_array_length(p_query->field_name) > pg_catalog.cardinality(allowed_values)
      or exists(select 1 from pg_catalog.jsonb_array_elements(p_query->field_name) entry
        where pg_catalog.jsonb_typeof(entry) <> 'string' or not ((entry #>> '{}')=any(allowed_values))) then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
    select coalesce(pg_catalog.array_agg(entry),'{}'::text[]) into values_array
      from pg_catalog.jsonb_array_elements_text(p_query->field_name) entry;
    case field_name
      when 'statuses' then statuses := values_array;
      when 'operational_statuses' then operational_statuses := values_array;
      else kinds := values_array;
    end case;
  end loop;

  foreach field_name in array array['starts_on_or_after','ends_on_or_before'] loop
    if p_query->>field_name is not null and p_query->>field_name !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
  end loop;
  starts_on := (p_query->>'starts_on_or_after')::date;
  ends_on := (p_query->>'ends_on_or_before')::date;
  if starts_on > ends_on then
    raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
  end if;
  if ((p_query->>'cursor_updated_at') is null) <> ((p_query->>'cursor_id') is null) then
    raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
  end if;
  if p_query->>'cursor_id' is not null then
    if p_query->>'cursor_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or p_query->>'cursor_updated_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ](0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{1,6})?(Z|[+-](0[0-9]|1[0-5]):[0-5][0-9])$' then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
    cursor_id := (p_query->>'cursor_id')::uuid;
    cursor_updated := (p_query->>'cursor_updated_at')::timestamptz;
    if not pg_catalog.isfinite(cursor_updated) then
      raise invalid_parameter_value using detail = 'SAI_INVALID_ARGUMENT';
    end if;
  end if;

  with scoped as materialized (
    select f.id,f.institution_id,f.title,f.kind,f.status,f.identity_mode,f.updated_at,f.management_version
    from public.forms f
    where (ctx.scope_kind='platform' or (ctx.scope_kind='institution' and f.institution_id=ctx.scope_institution_id))
      and (institution_filter is null or f.institution_id=institution_filter)
      and (search_text is null or f.title ilike '%'||search_text||'%' escape '\')
      and (pg_catalog.cardinality(statuses)=0 or f.status=any(statuses))
      and (pg_catalog.cardinality(kinds)=0 or f.kind=any(kinds))
  ), operational as (
    select scoped.*,
      case when scoped.status='archived' then 'archived'
        when scoped.status='draft' then 'draft'
        when coalesce(windows.is_active,false) then 'active'
        when coalesce(windows.is_scheduled,false) then 'scheduled'
        else 'closed' end as operational_status
    from scoped
    left join lateral (
      select pg_catalog.bool_or(o.status in ('scheduled','open') and o.opens_at<=pg_catalog.now() and o.closes_at>pg_catalog.now()) as is_active,
        pg_catalog.bool_or(o.status in ('scheduled','open') and o.opens_at>pg_catalog.now()) as is_scheduled
      from public.form_occurrences o where o.form_id=scoped.id and o.institution_id=scoped.institution_id
    ) windows on true
    where (starts_on is null or exists(select 1 from public.form_occurrences o
      where o.form_id=scoped.id and o.institution_id=scoped.institution_id and o.opens_at::date>=starts_on))
      and (ends_on is null or exists(select 1 from public.form_occurrences o
      where o.form_id=scoped.id and o.institution_id=scoped.institution_id and o.closes_at::date<=ends_on))
  ), page as materialized (
    select operational.* from operational
    where (pg_catalog.cardinality(operational_statuses)=0 or operational_status=any(operational_statuses))
      and (cursor_updated is null or (updated_at,id)<(cursor_updated,cursor_id))
    order by updated_at desc,id desc limit page_limit+1
  ), visible as materialized (
    select * from page order by updated_at desc,id desc limit page_limit
  )
  select pg_catalog.jsonb_build_object(
    'items',coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id',id,'title',title,'kind',kind,'status',status,'operational_status',operational_status,
      'identity_mode',identity_mode,'updated_at',updated_at,'management_version',management_version
    ) order by updated_at desc,id desc),'[]'::jsonb),
    'has_more',(select count(*)>page_limit from page),
    'next_cursor',case when (select count(*)>page_limit from page) then
      (select pg_catalog.jsonb_build_object('updated_at',updated_at,'id',id) from visible order by updated_at,id limit 1)
      else null end
  ) into result from visible;
exception
  when invalid_parameter_value or invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then
    error_code := 'SAI_INVALID_ARGUMENT';
  when others then
    get stacked diagnostics error_code = pg_exception_detail;
    -- Normalize technical/unknown details before they can enter the audit log.
    error_code := app_private.superadmin_internal_error_envelope(error_code,correlation) #>> '{error,code}';
  end;
  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'forms.read','superadmin.forms.directory',error_code,correlation);
    return app_private.superadmin_internal_error_envelope(error_code,correlation);
  end if;
  perform app_private.audit_append_superadmin_internal(
    ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
    ctx.session_id,'forms.read',ctx.aal,'superadmin.forms.directory','success',null,
    correlation,case when ctx.scope_kind='institution' then ctx.scope_institution_id else null end);
  return pg_catalog.jsonb_build_object('ok',true,'data',result,'error',null);
end
$_$;


ALTER FUNCTION "app_private"."superadmin_forms_directory_v2"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_forms_editor_v2"("p_form_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  initial_ctx app_private.superadmin_internal_context;
  f public.forms;
  institution_name text;
  correlation uuid:=pg_catalog.gen_random_uuid();
  permission text:='forms.manage';
  error_code text;
  result jsonb;
begin
  begin
    begin
      select * into strict ctx from app_private.require_superadmin_internal_context(permission);
    exception when insufficient_privilege then
      get stacked diagnostics error_code=pg_exception_detail;
      if error_code is distinct from 'SAI_PERMISSION_DENIED' then raise; end if;
      permission:='forms.read';
      select * into strict ctx from app_private.require_superadmin_internal_context(permission);
      error_code:=null;
    end;
    if ctx.aal is null or ctx.aal not in ('aal1','aal2') or ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and ctx.scope_institution_id is null) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    initial_ctx:=ctx;
    if pg_catalog.current_setting('transaction_isolation')<>'read committed' then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    if p_form_id is null then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
    select * into f from public.forms where id=p_form_id
      and (ctx.scope_kind='platform' or institution_id=ctx.scope_institution_id) for share;
    select i.public_name into institution_name from public.institutions i where i.id=f.institution_id and i.deleted_at is null for share;
    if not found then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
    -- A new SPI statement in this VOLATILE function gets a fresh READ COMMITTED
    -- snapshot after all explicit waits. Keep the originally selected capability.
    select * into strict ctx from app_private.require_superadmin_internal_context(permission);
    if row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.auth_user_id,ctx.session_id,
           ctx.scope_kind,ctx.scope_institution_id)
       is distinct from row(initial_ctx.internal_identity_id,initial_ctx.internal_auth_link_id,initial_ctx.internal_membership_id,
           initial_ctx.auth_user_id,initial_ctx.session_id,initial_ctx.scope_kind,initial_ctx.scope_institution_id)
      or ctx.aal is null or ctx.aal not in ('aal1','aal2') or ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and (ctx.scope_institution_id is null or f.institution_id is distinct from ctx.scope_institution_id)) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    if not exists(select 1 from auth.sessions s where s.id=initial_ctx.session_id and s.user_id=initial_ctx.auth_user_id
      and (s.not_after is null or s.not_after>pg_catalog.clock_timestamp())) then
      raise insufficient_privilege using detail='SAI_SESSION_INVALID';
    end if;
    if f.id is null or f.created_by_internal_identity_id is null or f.status<>'draft'
      or f.first_published_at is not null or f.published_version_id is not null
      or exists(select 1 from public.form_versions v where v.form_id=f.id and (v.state<>'working' or v.published_at is not null))
      or exists(select 1 from public.form_applications a where a.form_id=f.id)
      or exists(select 1 from public.form_occurrences o where o.form_id=f.id)
      or exists(select 1 from public.form_file_jobs j where j.form_id=f.id) then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    result:=pg_catalog.jsonb_build_object('definition',app_private.form_definition_projection(f.id),'application',null,
      'institution',pg_catalog.jsonb_build_object('id',f.institution_id,'public_name',institution_name),
      'capabilities',pg_catalog.jsonb_build_object('manage',permission='forms.manage'));
  exception
    when invalid_parameter_value then error_code:='SAI_INVALID_ARGUMENT';
    when others then
      get stacked diagnostics error_code=pg_exception_detail;
      error_code:=app_private.superadmin_internal_error_envelope(error_code,correlation)#>>'{error,code}';
  end;
  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(permission,'superadmin.forms.editor',error_code,correlation);
    return app_private.superadmin_internal_error_envelope(error_code,correlation);
  end if;
  perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
    ctx.session_id,permission,ctx.aal,'superadmin.forms.editor','success',null,correlation,f.institution_id);
  return pg_catalog.jsonb_build_object('ok',true,'data',result,'error',null);
end
$$;


ALTER FUNCTION "app_private"."superadmin_forms_editor_v2"("p_form_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_forms_operations_read_v2"("p_operation" "text", "p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  ctx app_private.superadmin_internal_context; final_ctx app_private.superadmin_internal_context;
  capability text:=case p_operation when 'monitor' then 'forms.monitor'
    when 'file_jobs' then 'forms.responses.export' else 'forms.responses.read' end;
  action_code text:='superadmin.forms.'||p_operation;
  correlation uuid:=gen_random_uuid(); error_code text; result jsonb;
  allowed text[]; field_name text; page_limit integer:=25;
  form_row public.forms; response_row public.form_responses; version_row public.form_versions;
  definition_result jsonb; invalid_definition boolean;
  v_form_id uuid; v_response_id uuid; v_application_id uuid; v_occurrence_id uuid; v_scope_id uuid;
  v_cursor_id uuid; cursor_time timestamptz; cursor_field text;
  starts_on date; ends_on date; v_scope_kind text;
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context(capability);
    if ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and ctx.scope_institution_id is null)
      or ctx.aal is null or ctx.aal not in ('aal1','aal2') then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    allowed:=case p_operation
      when 'monitor' then array['form_id','application_id','occurrence_id','starts_on_or_after','ends_on_or_before','scope_id']
      when 'responses' then array['form_id','occurrence_id','cursor_submitted_at','cursor_id','limit']
      when 'response_detail' then array['response_id','form_id']
      when 'file_jobs' then array['form_id','cursor_created_at','cursor_id','limit'] end;
    if allowed is null or p_query is null or jsonb_typeof(p_query)<>'object'
      or octet_length(p_query::text)>16384 or p_query-allowed<>'{}'::jsonb then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    foreach field_name in array allowed loop
      if field_name='limit' then continue; end if;
      if p_query?field_name and p_query->field_name<>'null'::jsonb
        and jsonb_typeof(p_query->field_name)<>'string' then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
    end loop;
    foreach field_name in array array['form_id','response_id','application_id','occurrence_id','scope_id','cursor_id'] loop
      if p_query->>field_name is not null and p_query->>field_name!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
    end loop;
    if p_query?'limit' then
      if jsonb_typeof(p_query->'limit') is distinct from 'number' or p_query->>'limit'!~'^[0-9]{1,3}$' then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      page_limit:=(p_query->>'limit')::integer;
      if page_limit not between 1 and 100 then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
    end if;
    v_form_id:=(p_query->>'form_id')::uuid; v_response_id:=(p_query->>'response_id')::uuid;
    v_application_id:=(p_query->>'application_id')::uuid; v_occurrence_id:=(p_query->>'occurrence_id')::uuid;
    v_scope_id:=(p_query->>'scope_id')::uuid; v_cursor_id:=(p_query->>'cursor_id')::uuid;
    if p_operation='response_detail' then
      if v_response_id is null then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
      select r.* into response_row from public.form_responses r
        join public.forms f on f.id=r.form_id and f.institution_id=r.institution_id
        join public.institutions i on i.id=f.institution_id and i.deleted_at is null
        join public.form_versions v on v.id=r.form_version_id and v.form_id=f.id
        join public.form_occurrences o on o.id=r.occurrence_id and o.form_id=f.id and o.institution_id=f.institution_id
          and o.form_version_id=r.form_version_id
        where r.id=v_response_id and r.status='submitted' and (v_form_id is null or r.form_id=v_form_id)
          and (ctx.scope_kind='platform' or f.institution_id=ctx.scope_institution_id) for share of r;
      if response_row.id is null then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
      v_form_id:=response_row.form_id;
    elsif v_form_id is null then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    select f.* into form_row from public.forms f join public.institutions i on i.id=f.institution_id and i.deleted_at is null
      where f.id=v_form_id and (ctx.scope_kind='platform' or f.institution_id=ctx.scope_institution_id) for share of f;
    if form_row.id is null then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
    if v_application_id is not null and not exists(select 1 from public.form_applications a
      where a.id=v_application_id and a.form_id=form_row.id and a.institution_id=form_row.institution_id) then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    if v_occurrence_id is not null and not exists(select 1 from public.form_occurrences o
      where o.id=v_occurrence_id and o.form_id=form_row.id and o.institution_id=form_row.institution_id
        and (v_application_id is null or o.application_id=v_application_id)) then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    foreach field_name in array array['starts_on_or_after','ends_on_or_before'] loop
      if p_query->>field_name is not null and p_query->>field_name!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
    end loop;
    starts_on:=(p_query->>'starts_on_or_after')::date; ends_on:=(p_query->>'ends_on_or_before')::date;
    if starts_on>ends_on then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
    cursor_field:=case p_operation when 'responses' then 'cursor_submitted_at' when 'file_jobs' then 'cursor_created_at' end;
    if p_operation='responses' and form_row.identity_mode='anonymous' then
      if p_query->>'cursor_submitted_at' is not null then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
    elsif cursor_field is not null then
      if (v_cursor_id is null)<>((p_query->>cursor_field) is null) then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      if p_query->>cursor_field is not null then
        if p_query->>cursor_field!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ](0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{1,6})?(Z|[+-](0[0-9]|1[0-5]):[0-5][0-9])$' then
          raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
        end if;
        cursor_time:=(p_query->>cursor_field)::timestamptz;
        if not isfinite(cursor_time) then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
      end if;
    end if;

    if p_operation='monitor' then
      if v_scope_id is not null then
        select min(m.scope_kind) into v_scope_kind from public.form_scope_metrics m
          join public.form_occurrences o on o.id=m.occurrence_id and o.institution_id=m.institution_id
          where o.form_id=form_row.id and m.institution_id=form_row.institution_id and m.scope_id=v_scope_id
            and (v_application_id is null or o.application_id=v_application_id)
            and (v_occurrence_id is null or o.id=v_occurrence_id)
          having count(distinct m.scope_kind)=1;
        if v_scope_kind is null then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
      end if;
      select jsonb_build_object(
        'eligible_count',coalesce(sum(case when v_scope_id is null then om.eligible_count else sm.eligible_count end),0),
        'responded_count',coalesce(sum(case when v_scope_id is null then om.responded_count else sm.responded_count end),0),
        'pending_count',coalesce(sum(case when v_scope_id is null then om.pending_count else sm.pending_count end),0),
        'is_anonymous',form_row.identity_mode='anonymous') into result
      from public.form_occurrences o
      left join public.form_occurrence_metrics om on om.occurrence_id=o.id and om.institution_id=form_row.institution_id
      left join public.form_scope_metrics sm on sm.occurrence_id=o.id and sm.institution_id=form_row.institution_id
        and sm.scope_id=v_scope_id and sm.scope_kind=v_scope_kind
      where o.form_id=form_row.id and o.institution_id=form_row.institution_id
        and (v_application_id is null or o.application_id=v_application_id) and (v_occurrence_id is null or o.id=v_occurrence_id)
        and (starts_on is null or o.opens_at::date>=starts_on) and (ends_on is null or o.closes_at::date<=ends_on);
    elsif p_operation='responses' then
      if exists(select 1 from public.form_responses r where r.form_id=form_row.id
        and r.status='submitted' and (r.institution_id is distinct from form_row.institution_id
          or r.identity_mode is distinct from form_row.identity_mode)) then
        raise check_violation using detail='SAI_UNAVAILABLE';
      end if;
      with page as materialized (
        select r.id,r.occurrence_id,r.form_version_id,r.identity_mode,r.submitted_at,p.display_name
        from public.form_responses r
        join public.form_occurrences o on o.id=r.occurrence_id and o.form_id=form_row.id and o.institution_id=form_row.institution_id
          and o.form_version_id=r.form_version_id
        join public.form_versions v on v.id=r.form_version_id and v.form_id=form_row.id
        left join public.people p on p.id=r.respondent_person_id and r.identity_mode='identified'
        where r.form_id=form_row.id and r.institution_id=form_row.institution_id and r.status='submitted'
          and (v_occurrence_id is null or r.occurrence_id=v_occurrence_id)
          and (v_cursor_id is null or case when form_row.identity_mode='anonymous' then r.id<v_cursor_id
            else (r.submitted_at,r.id)<(cursor_time,v_cursor_id) end)
        order by case when form_row.identity_mode='identified' then r.submitted_at end desc,r.id desc limit page_limit+1
      ), visible as materialized (
        select * from page order by case when form_row.identity_mode='identified' then submitted_at end desc,id desc limit page_limit
      ) select jsonb_build_object('identity_mode',form_row.identity_mode,
        'items',coalesce(jsonb_agg(jsonb_build_object('id',id,'occurrence_id',vis.occurrence_id,'form_version_id',form_version_id,
          'identity_mode',identity_mode,'submitted_at',case when identity_mode='identified' then submitted_at else null end,
          'respondent_label',case when identity_mode='identified' then display_name else null end)
          order by case when form_row.identity_mode='identified' then submitted_at end desc,id desc),'[]'::jsonb),
        'has_more',(select count(*)>page_limit from page),
        'next_cursor',case when (select count(*)>page_limit from page) then
          (select case when form_row.identity_mode='anonymous' then jsonb_build_object('id',id)
            else jsonb_build_object('submitted_at',submitted_at,'id',id) end from visible
            order by case when form_row.identity_mode='identified' then submitted_at end,id limit 1) else null end)
        into result from visible vis;
    elsif p_operation='response_detail' then
      select v.* into strict version_row from public.form_versions v
        where v.id=response_row.form_version_id and v.form_id=form_row.id;
      -- The legacy projector follows section/item IDs, not composite version
      -- keys. Validate the whole graph, including unanswered/incoming rows,
      -- before allowing it to project any definition content.
      -- Both values use one statement snapshot; the later response envelope
      -- reuses this captured definition instead of re-reading mutable links.
      select app_private.form_definition_projection(form_row.id,version_row.id),
        exists(select 1 from public.form_items i
        join public.form_sections s on s.id=i.section_id
        where (i.form_version_id=version_row.id or s.form_version_id=version_row.id)
          and (i.form_version_id<>version_row.id or s.form_version_id<>version_row.id))
        or exists(select 1 from public.form_question_options o
          join public.form_items i on i.id=o.item_id
          where (o.form_version_id=version_row.id or i.form_version_id=version_row.id)
            and (o.form_version_id<>version_row.id or i.form_version_id<>version_row.id))
        or exists(select 1 from public.form_question_conditions c
          join public.form_items target on target.id=c.target_item_id
          join public.form_items source on source.id=c.source_item_id
          left join public.form_question_options o on o.id=c.source_option_id
          where (c.form_version_id=version_row.id or target.form_version_id=version_row.id)
            and (c.form_version_id<>version_row.id or target.form_version_id<>version_row.id
              or source.form_version_id<>version_row.id
              or (c.condition_kind='yes_no' and source.kind<>'yes_no')
              or (c.condition_kind='choice' and (source.kind not in ('single_choice','multiple_choice')
                or o.id is null or o.form_version_id<>version_row.id or o.item_id<>source.id))))
        into definition_result,invalid_definition;
      if invalid_definition then
        raise check_violation using detail='SAI_UNAVAILABLE';
      end if;
      if response_row.identity_mode is distinct from form_row.identity_mode
        or exists(select 1 from public.form_answers a
        left join public.form_items i on i.id=a.item_id and i.form_version_id=response_row.form_version_id
        left join public.form_sections s on s.id=i.section_id and s.form_version_id=response_row.form_version_id
        where a.response_id=response_row.id and (a.form_version_id is distinct from response_row.form_version_id
          or i.id is null or s.id is null)) then
        raise check_violation using detail='SAI_UNAVAILABLE';
      end if;
      if exists(select 1 from public.form_answer_options ao
        join public.form_answers a on a.id=ao.answer_id
        left join public.form_question_options qo on qo.id=ao.option_id and qo.item_id=a.item_id
          and qo.form_version_id=response_row.form_version_id
        where a.response_id=response_row.id and qo.id is null)
        or exists(select 1 from public.form_answer_assets aa
          join public.form_answers a on a.id=aa.answer_id
          left join public.form_assets fa on fa.id=aa.asset_id and fa.item_id=a.item_id
            and fa.occurrence_id=response_row.occurrence_id and fa.institution_id=form_row.institution_id
          where a.response_id=response_row.id and fa.id is null) then
        raise check_violation using detail='SAI_UNAVAILABLE';
      end if;
      result:=jsonb_build_object('id',response_row.id,'occurrence_id',response_row.occurrence_id,
        'form_id',form_row.id,'form_version_id',version_row.id,
        'form_version_number',version_row.version_number,'form_version_state',version_row.state,
        'identity_mode',response_row.identity_mode,
        'submitted_at',case when response_row.identity_mode='identified' then response_row.submitted_at else null end,
        'respondent_label',case when response_row.identity_mode='identified' then
          (select display_name from public.people where id=response_row.respondent_person_id) else null end,
        'definition',definition_result,
        'answers',coalesce((select jsonb_agg(jsonb_build_object(
          'item_id',a.item_id,'kind',a.answer_kind,'text_value',a.text_value,'integer_value',a.integer_value,
          'decimal_value',a.decimal_value,'money_minor_units',a.money_minor_units,'date_value',a.date_value,
          'yes_no_value',a.yes_no_value,'scale_value',a.scale_value,
          'option_ids',coalesce((select jsonb_agg(ao.option_id order by ao.position)
            from public.form_answer_options ao join public.form_question_options qo on qo.id=ao.option_id and qo.item_id=i.id
            where ao.answer_id=a.id),'[]'::jsonb),
          'asset_ids',coalesce((select jsonb_agg(aa.asset_id order by aa.position)
            from public.form_answer_assets aa where aa.answer_id=a.id),'[]'::jsonb))
          order by s.position,i.position,i.id)
          from public.form_answers a join public.form_items i on i.id=a.item_id
          join public.form_sections s on s.id=i.section_id where a.response_id=response_row.id),'[]'::jsonb));
    else
      with page as materialized (
        select j.* from public.form_file_jobs j where j.form_id=form_row.id and j.institution_id=form_row.institution_id
          and j.artifact_provider='r2' and j.export_kind='xlsx' and j.requested_by_internal_identity_id=ctx.internal_identity_id
          and (v_cursor_id is null or (j.created_at,j.id)<(cursor_time,v_cursor_id))
          order by j.created_at desc,j.id desc limit page_limit+1
      ), visible as materialized (
        select * from page order by created_at desc,id desc limit page_limit
      ) select jsonb_build_object('form_id',form_row.id,'management_version',form_row.management_version,
        'items',coalesce(jsonb_agg(jsonb_build_object('id',j.id,
          'status',case when j.expires_at<=clock_timestamp() then 'expired' else j.state end,'progress',j.progress,
          'error_code',case when j.error_code in ('export_failed','export_timeout','empty_export','retry_exhausted') then j.error_code else null end,
          'expires_at',j.expires_at,'download_available',j.state='succeeded' and j.expires_at>clock_timestamp()
            and exists(select 1 from public.media_assets a where a.id=j.artifact_media_asset_id
              and a.export_file_job_id=j.id and a.form_id=j.form_id and a.institution_id=j.institution_id
              and a.owner_internal_identity_id=ctx.internal_identity_id and a.catalog_kind='form-xlsx'
              and a.storage_provider='r2' and a.status='ready' and a.expires_at>clock_timestamp()))
          order by j.created_at desc,j.id desc),'[]'::jsonb),
        'has_more',(select count(*)>page_limit from page),
        'next_cursor',case when (select count(*)>page_limit from page) then
          (select jsonb_build_object('created_at',created_at,'id',id) from visible order by created_at,id limit 1) else null end)
        into result from visible j;
    end if;
    select * into strict final_ctx from app_private.require_superadmin_internal_context(capability);
    if (ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,ctx.scope_kind,ctx.scope_institution_id)
      is distinct from (final_ctx.internal_identity_id,final_ctx.internal_auth_link_id,final_ctx.internal_membership_id,
        final_ctx.session_id,final_ctx.scope_kind,final_ctx.scope_institution_id)
      or not exists(select 1 from auth.sessions where id=final_ctx.session_id and user_id=final_ctx.auth_user_id
        and (not_after is null or not_after>clock_timestamp()))
      or not exists(select 1 from public.institutions where id=form_row.institution_id and deleted_at is null) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
  exception
    when invalid_parameter_value or invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then
      error_code:='SAI_INVALID_ARGUMENT';
    when others then
      get stacked diagnostics error_code=pg_exception_detail;
      error_code:=app_private.superadmin_internal_error_envelope(error_code,correlation)#>>'{error,code}';
  end;
  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(capability,action_code,error_code,correlation);
    return app_private.superadmin_internal_error_envelope(error_code,correlation);
  end if;
  perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
    ctx.session_id,capability,ctx.aal,action_code,'success',null,correlation,form_row.institution_id,
    case when p_operation='response_detail' then 'form_response' else 'form' end,
    case when p_operation='response_detail' then response_row.id else form_row.id end);
  return jsonb_build_object('ok',true,'data',result,'error',null);
end;
$_$;


ALTER FUNCTION "app_private"."superadmin_forms_operations_read_v2"("p_operation" "text", "p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_forms_save_draft_v2"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  initial_ctx app_private.superadmin_internal_context;
  f public.forms;
  receipt app_private.superadmin_internal_form_draft_receipts;
  correlation uuid:=pg_catalog.gen_random_uuid();
  error_code text;
  target_id uuid;
  target_institution uuid;
  working_id uuid;
  request_hash bytea;
  result jsonb;
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context('forms.manage');
    if ctx.aal is null or ctx.aal not in ('aal1','aal2') or ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and ctx.scope_institution_id is null) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    initial_ctx:=ctx;
    if pg_catalog.current_setting('transaction_isolation')<>'read committed' then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    if p_request_id is null or p_expected_version is null or p_expected_version<0 then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    perform app_private.superadmin_form_validate_draft_payload_v2(p_payload);
    target_institution:=(p_payload->>'institution_id')::uuid;
    if (ctx.scope_kind='institution' and target_institution is distinct from ctx.scope_institution_id)
      or not exists(select 1 from public.institutions i where i.id=target_institution and i.deleted_at is null) then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    request_hash:=extensions.digest(pg_catalog.convert_to(p_expected_version::text||':'||p_payload::text,'UTF8'),'sha256');
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_id::text,6404));
    -- The request lock can wait before even the private receipt lookup.
    select * into strict ctx from app_private.require_superadmin_internal_context('forms.manage');
    if row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.auth_user_id,ctx.session_id,
           ctx.scope_kind,ctx.scope_institution_id)
       is distinct from row(initial_ctx.internal_identity_id,initial_ctx.internal_auth_link_id,initial_ctx.internal_membership_id,
           initial_ctx.auth_user_id,initial_ctx.session_id,initial_ctx.scope_kind,initial_ctx.scope_institution_id)
      or ctx.aal is null or ctx.aal not in ('aal1','aal2') or ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and (ctx.scope_institution_id is null or target_institution is distinct from ctx.scope_institution_id)) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    if not exists(select 1 from auth.sessions s where s.id=initial_ctx.session_id and s.user_id=initial_ctx.auth_user_id
      and (s.not_after is null or s.not_after>pg_catalog.clock_timestamp())) then
      raise insufficient_privilege using detail='SAI_SESSION_INVALID';
    end if;
    select * into receipt from app_private.superadmin_internal_form_draft_receipts where request_id=p_request_id;
    if receipt.request_id is not null then
      if receipt.actor_internal_identity_id is distinct from ctx.internal_identity_id
        or receipt.institution_id is distinct from target_institution
        or receipt.expected_version is distinct from p_expected_version
        or receipt.request_hash is distinct from request_hash then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      target_id:=receipt.form_id;
    else
      target_id:=coalesce((p_payload->>'id')::uuid,pg_catalog.gen_random_uuid());
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(target_id::text,0));
    select * into f from public.forms where id=target_id for update;
    perform 1 from public.institutions i where i.id=target_institution and i.deleted_at is null for share;
    if not found then raise insufficient_privilege using detail='SAI_PERMISSION_DENIED'; end if;
    -- Reauthorize after request, form-row and institution waits, before exposing
    -- a receipt snapshot or writing. Never migrate the in-flight actor/context.
    select * into strict ctx from app_private.require_superadmin_internal_context('forms.manage');
    if row(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.auth_user_id,ctx.session_id,
           ctx.scope_kind,ctx.scope_institution_id)
       is distinct from row(initial_ctx.internal_identity_id,initial_ctx.internal_auth_link_id,initial_ctx.internal_membership_id,
           initial_ctx.auth_user_id,initial_ctx.session_id,initial_ctx.scope_kind,initial_ctx.scope_institution_id)
      or ctx.aal is null or ctx.aal not in ('aal1','aal2') or ctx.scope_kind is null or ctx.scope_kind not in ('platform','institution')
      or (ctx.scope_kind='institution' and (ctx.scope_institution_id is null or target_institution is distinct from ctx.scope_institution_id)) then
      raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED';
    end if;
    if not exists(select 1 from auth.sessions s where s.id=initial_ctx.session_id and s.user_id=initial_ctx.auth_user_id
      and (s.not_after is null or s.not_after>pg_catalog.clock_timestamp())) then
      raise insufficient_privilege using detail='SAI_SESSION_INVALID';
    end if;
    if f.id is not null then
      if f.institution_id is distinct from target_institution or f.created_by_internal_identity_id is null or f.status<>'draft'
        or f.first_published_at is not null or f.published_version_id is not null
        or exists(select 1 from public.form_versions v where v.form_id=f.id and (v.state<>'working' or v.published_at is not null))
        or exists(select 1 from public.form_applications a where a.form_id=f.id)
        or exists(select 1 from public.form_occurrences o where o.form_id=f.id)
        or exists(select 1 from public.form_file_jobs j where j.form_id=f.id) then
        raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
      end if;
    elsif receipt.request_id is not null then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    if receipt.request_id is not null then
      result:=receipt.result_jsonb;
    else
      if f.id is null then
        if p_expected_version<>0 then raise serialization_failure using detail='SAI_CONCURRENT_CHANGE'; end if;
        insert into public.forms(id,institution_id,kind,identity_mode,response_unit,title,description,
          created_by_internal_identity_id,updated_by_internal_identity_id)
        values(target_id,target_institution,p_payload->>'kind',p_payload->>'identity_mode',p_payload->>'response_unit',
          btrim(p_payload->>'title'),nullif(btrim(p_payload->>'description'),''),ctx.internal_identity_id,ctx.internal_identity_id)
        returning * into f;
        insert into public.form_versions(form_id,version_number,created_by_internal_identity_id)
        values(f.id,1,ctx.internal_identity_id) returning id into working_id;
        update public.forms set working_version_id=working_id where id=f.id;
      else
        if f.management_version is distinct from p_expected_version then raise serialization_failure using detail='SAI_CONCURRENT_CHANGE'; end if;
        working_id:=f.working_version_id;
        if working_id is null or not exists(select 1 from public.form_versions v where v.id=working_id and v.form_id=f.id and v.state='working') then
          raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
        end if;
        update public.forms set kind=p_payload->>'kind',identity_mode=p_payload->>'identity_mode',response_unit=p_payload->>'response_unit',
          title=btrim(p_payload->>'title'),description=nullif(btrim(p_payload->>'description'),''),management_version=management_version+1,
          updated_by_person_id=null,updated_by_internal_identity_id=ctx.internal_identity_id,updated_at=pg_catalog.now()
        where id=f.id;
      end if;
      perform app_private.superadmin_form_replace_draft_definition_v2(working_id,p_payload->'sections');
      result:=app_private.form_definition_projection(f.id);
      insert into app_private.superadmin_internal_form_draft_receipts(request_id,actor_internal_identity_id,form_id,institution_id,expected_version,request_hash,result_jsonb)
      values(p_request_id,ctx.internal_identity_id,f.id,target_institution,p_expected_version,request_hash,result);
    end if;
  exception
    when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range or check_violation or not_null_violation or foreign_key_violation or unique_violation then
      error_code:='SAI_INVALID_ARGUMENT';
    when serialization_failure then error_code:='SAI_CONCURRENT_CHANGE';
    when others then
      get stacked diagnostics error_code=pg_exception_detail;
      error_code:=app_private.superadmin_internal_error_envelope(error_code,correlation)#>>'{error,code}';
  end;
  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified('forms.manage','superadmin.forms.draft.save',error_code,correlation);
    return app_private.superadmin_internal_error_envelope(error_code,correlation);
  end if;
  -- Intentionally outside the inner exception block: audit failure rolls back
  -- business changes AND receipt rather than returning an unaudited denial.
  perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,
    ctx.session_id,'forms.manage',ctx.aal,'superadmin.forms.draft.save','success',null,correlation,target_institution);
  return pg_catalog.jsonb_build_object('ok',true,'data',result,'error',null);
end
$$;


ALTER FUNCTION "app_private"."superadmin_forms_save_draft_v2"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_get_activity_form_options"("p_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
 if (select auth.uid()) is null or
    not app_private.has_platform_permission('activities.read') then
  raise insufficient_privilege using message='activities.read required';
 end if;
 if p_institution_id is not null and not exists(select 1 from public.institutions institution
   where institution.id=p_institution_id) then
  raise no_data_found using message='institution not found';
 end if;
 select jsonb_build_object(
  'institutions',coalesce((select jsonb_agg(jsonb_build_object(
    'id',institution.id,'name',institution.public_name) order by institution.public_name)
    from public.institutions institution
    where p_institution_id is null or institution.id=p_institution_id),'[]'::jsonb),
  'units',coalesce((select jsonb_agg(jsonb_build_object(
    'id',unit.id,'institution_id',unit.institution_id,'name',unit.name) order by unit.name)
    from public.units unit where (p_institution_id is null
      or unit.institution_id=p_institution_id) and unit.status<>'archived'),'[]'::jsonb),
  'locations','[]'::jsonb,
  'groups',coalesce((select jsonb_agg(jsonb_build_object(
    'id',group_record.id,'unit_id',group_record.unit_id,'name',group_record.name,
    'participant_count',(select count(*) from public.child_group_links child_link
      where child_link.group_id=group_record.id and child_link.status='active'))
    order by group_record.name) from public.groups group_record
    where (p_institution_id is null or group_record.institution_id=p_institution_id)
     and group_record.status<>'archived'),'[]'::jsonb),
  'professionals',coalesce((select jsonb_agg(jsonb_build_object(
    'membership_id',membership.id,'person_id',person.id,'name',person.display_name,
    'role',membership.role_code) order by person.display_name)
    from public.institution_memberships membership
    join public.people person on person.id=membership.person_id
    where (p_institution_id is null or membership.institution_id=p_institution_id)
     and membership.status='active' and membership.revoked_at is null
     and person.person_type<>'child' and person.status='active'),'[]'::jsonb),
  'taxonomy',coalesce((select jsonb_agg(jsonb_build_object(
    'id',category.id,'label',category.name,'is_other',category.code='outros',
    'subtypes',coalesce((select jsonb_agg(jsonb_build_object(
      'id',subtype.id,'label',subtype.name) order by subtype.sort_order,subtype.name)
      from public.activity_taxonomies subtype where subtype.parent_id=category.id
       and subtype.status='active'),'[]'::jsonb))
    order by category.sort_order,category.name)
    from public.activity_taxonomies category
    where category.taxonomy_kind='category' and category.status='active'),'[]'::jsonb),
  'templates',coalesce((select jsonb_agg(jsonb_build_object(
    'id',template.id,'name',template.name,
    'description',template.description,
    'scope_kind',template.scope_kind,
    'institution_id',template.institution_id,
    'governance_kind',template.governance_kind,
    'taxonomy_id',coalesce(taxonomy.parent_id,taxonomy.id),
    'subtype_id',case when taxonomy.taxonomy_kind='subtype' then taxonomy.id end)
    order by template.name)
    from public.activity_templates template
    join public.activity_taxonomies taxonomy on taxonomy.id=template.taxonomy_id
    where template.status='active' and (template.scope_kind='platform'
      or template.institution_id=p_institution_id)),'[]'::jsonb)
 ) into result;
 return result;
end $$;


