CREATE OR REPLACE FUNCTION "app_private"."superadmin_get_unit_file_job"("p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  permission_code text;
begin
  select *
  into job
  from public.import_jobs
  where id = p_import_job_id;

  if job.id is null or job.target_domain not in ('units', 'units_export') then
    raise no_data_found using message = 'unit file job not found';
  end if;

  permission_code := case
    when job.target_domain = 'units' then 'units.import'
    else 'units.export'
  end;
  actor := app_private.assert_unit_file_access(permission_code, null);
  if job.created_by <> actor then
    raise insufficient_privilege using message = 'unit file job outside actor scope';
  end if;

  return app_private.unit_file_job_payload(job.id);
end
$$;


