CREATE OR REPLACE FUNCTION "app_private"."superadmin_import_export_upload_contract"("p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  mime_type text;
begin
  if p_import_job_id is null then
    raise invalid_parameter_value using message = 'import job required';
  end if;

  actor := app_private.assert_unit_file_access('units.import', null);
  select * into job
  from public.import_jobs
  where id = p_import_job_id and created_by = actor;

  if job.id is null or job.target_domain <> 'units'
    or job.processing_state <> 'PENDENTE' then
    raise insufficient_privilege using message = 'import upload unavailable';
  end if;

  mime_type := case job.source_format
    when 'csv' then 'text/csv'
    when 'xlsx' then 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    else null
  end;
  if mime_type is null then
    raise invalid_parameter_value using message = 'invalid import format';
  end if;

  return jsonb_build_object(
    'job_id', job.id,
    'bucket', 'coelo-operations',
    'path', 'imports/units/' || job.id || '/source.' || job.source_format,
    'mime_type', mime_type,
    'max_bytes', 5242880,
    'expires_in', 60
  );
end;
$$;


ALTER FUNCTION "app_private"."superadmin_import_export_upload_contract"("p_import_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_import_payload"("p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', job.id, 'institution_id', job.institution_id,
    'target_domain', job.target_domain, 'target_table', job.target_table,
    'source_format', job.source_format, 'processing_state', job.processing_state,
    'summary', job.summary, 'created_at', job.created_at,
    'started_at', job.started_at, 'finished_at', job.finished_at,
    'result', coalesce(to_jsonb(result_record), '{}'::jsonb),
    'errors', coalesce((select jsonb_agg(jsonb_build_object(
      'row', error_record.row_number, 'field', error_record.column_name,
      'code', error_record.error_code, 'message', error_record.message
    ) order by error_record.row_number, error_record.column_name)
      from public.import_errors error_record where error_record.import_job_id = job.id), '[]'::jsonb)
  )
  from public.import_jobs job
  left join public.import_results result_record on result_record.import_job_id = job.id
  where job.id = p_import_job_id
$$;


ALTER FUNCTION "app_private"."superadmin_import_payload"("p_import_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_import_start"("p_request_id" "uuid", "p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_person_id uuid; job public.import_jobs%rowtype;
begin
  if p_request_id is null or p_import_job_id is null then raise invalid_parameter_value using message = 'request required'; end if;
  if (select auth.uid()) is null then raise insufficient_privilege using message = 'authentication required'; end if;
  actor_person_id := app_private.current_person_id();
  if actor_person_id is null or not app_private.has_platform_permission('imports.manage') then
    raise insufficient_privilege using message = 'imports.manage required';
  end if;
  if not app_private.has_mfa_aal2() then raise insufficient_privilege using message = 'MFA AAL2 required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_import_job_id::text, 0));
  select job_source.* into job from public.import_jobs job_source where job_source.start_request_id = p_request_id;
  if found then
    if job.id <> p_import_job_id then
      raise invalid_parameter_value using message = 'request_id already used by another import';
    end if;
    return app_private.superadmin_import_payload(job.id);
  end if;
  select * into job from public.import_jobs where id = p_import_job_id for update;
  if job.id is null then raise no_data_found using message = 'import job not found'; end if;
  if job.created_by <> actor_person_id and not app_private.has_platform_permission('imports.manage') then
    raise insufficient_privilege using message = 'import job outside actor scope';
  end if;
  if job.processing_state in ('SUCESSO','REJEICAO','ERRO') then
    return app_private.superadmin_import_payload(job.id);
  end if;
  update public.import_jobs set processing_state = 'PROCESSANDO', status = 'active',
    start_request_id = p_request_id, started_at = coalesce(started_at, now()),
    updated_at = now() where id = job.id;
  insert into app_private.import_processing_queue(import_job_id, state, available_at)
  values (job.id, 'PENDENTE', now())
  on conflict (import_job_id) do update set state = 'PENDENTE', available_at = now(), updated_at = now();
  insert into audit.audit_logs(actor_person_id, action_code, object_type, object_id,
    institution_id, outcome, after_json)
  values (actor_person_id, 'import.start', 'import_job', job.id, job.institution_id,
    'success', jsonb_build_object('state', 'PROCESSANDO'));
  return app_private.superadmin_import_payload(job.id);
end $$;


ALTER FUNCTION "app_private"."superadmin_import_start"("p_request_id" "uuid", "p_import_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_contacts_apply_v1"("p_request_id" "uuid", "p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb", "p_request_hash" "bytea", "p_context" "app_private"."superadmin_internal_context", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  prior_receipt app_private.superadmin_internal_institution_edit_receipts%rowtype;
  institution_record public.institutions%rowtype;
  v_contact_child jsonb;
  v_entry jsonb;
  v_person_id uuid;
  v_membership_id uuid;
  v_role_code_value text;
  v_rep_status public.record_status;
  v_dob date;
  kept_representative_ids uuid[] := '{}';
  kept_administrator_ids uuid[] := '{}';
  result_version bigint;
  admin_role_codes constant text[] := array['owner','institution_admin','coordinator'];
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_id::text, 0));

  select receipt.* into prior_receipt
  from app_private.superadmin_internal_institution_edit_receipts receipt
  where receipt.request_id = p_request_id;
  if prior_receipt.request_id is not null then
    if prior_receipt.actor_internal_identity_id is distinct from p_context.internal_identity_id
      or prior_receipt.institution_id is distinct from p_institution_id
      or prior_receipt.expected_version is distinct from p_expected_version
      or prior_receipt.request_hash is distinct from p_request_hash then
      raise invalid_parameter_value using
        message = 'request id already used', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    return pg_catalog.jsonb_build_object(
      'institution_id', prior_receipt.institution_id,
      'management_version', prior_receipt.result_management_version,
      'correlation_id', p_correlation_id,
      'replayed', true);
  end if;

  select institution.* into institution_record
  from public.institutions institution
  where institution.id = p_institution_id and institution.deleted_at is null
  for update;
  if institution_record.id is null then
    raise insufficient_privilege using
      message = 'internal institution access denied', detail = 'SAI_PERMISSION_DENIED';
  end if;
  if institution_record.management_version is distinct from p_expected_version then
    raise serialization_failure using
      message = 'stale institution version', detail = 'SAI_CONCURRENT_CHANGE';
  end if;

  -- documento
  if p_payload ? 'document' then
    update public.institutions set
      document_type = p_payload -> 'document' ->> 'document_type',
      document_ref = p_payload -> 'document' ->> 'document_ref'
    where id = p_institution_id;
  end if;

  -- contato
  if p_payload ? 'contact' then
    v_contact_child := p_payload -> 'contact';
    if pg_catalog.num_nonnulls(v_contact_child ->> 'email', v_contact_child ->> 'phone',
        v_contact_child ->> 'mobile_phone', v_contact_child ->> 'website_url',
        v_contact_child ->> 'whatsapp_number') = 0 then
      delete from public.institution_contacts where institution_id = p_institution_id;
    else
      insert into public.institution_contacts(
        institution_id, email, phone, mobile_phone, website_url, whatsapp_number, status)
      values (p_institution_id, v_contact_child ->> 'email', v_contact_child ->> 'phone',
        v_contact_child ->> 'mobile_phone', v_contact_child ->> 'website_url',
        v_contact_child ->> 'whatsapp_number', 'active')
      on conflict (institution_id) do update set
        email = excluded.email, phone = excluded.phone, mobile_phone = excluded.mobile_phone,
        website_url = excluded.website_url, whatsapp_number = excluded.whatsapp_number,
        status = 'active', updated_at = pg_catalog.now();
    end if;
  end if;

  -- administradores primeiro (definem a role da membership)
  if p_payload ? 'administrators' then
    for v_entry in select value from pg_catalog.jsonb_array_elements(p_payload -> 'administrators') loop
      v_person_id := app_private.superadmin_institution_contacts_upsert_person_v1(v_entry);
      if v_person_id = any(kept_administrator_ids) then
        raise invalid_parameter_value using
          message = 'duplicate administrator', detail = 'SAI_INVALID_ARGUMENT';
      end if;
      v_role_code_value := case v_entry ->> 'level'
        when 'admin_master' then 'owner'
        when 'authorized_administrator' then 'institution_admin'
        else 'coordinator' end;
      select m.id into v_membership_id from public.institution_memberships m
      where m.person_id = v_person_id and m.institution_id = p_institution_id
        and m.status = 'active' and m.revoked_at is null
      for update;
      if v_membership_id is null then
        insert into public.institution_memberships(
          person_id, institution_id, role_code, status, scope_kind, invited_by)
        values (v_person_id, p_institution_id, v_role_code_value, 'active', 'institution', null)
        returning id into v_membership_id;
      else
        update public.institution_memberships set role_code = v_role_code_value
        where id = v_membership_id and role_code is distinct from v_role_code_value;
      end if;
      kept_administrator_ids := kept_administrator_ids || v_person_id;
    end loop;
  end if;

  -- representantes legais
  if p_payload ? 'representatives' then
    for v_entry in select value from pg_catalog.jsonb_array_elements(p_payload -> 'representatives') loop
      v_person_id := app_private.superadmin_institution_contacts_upsert_person_v1(v_entry);
      if v_person_id = any(kept_representative_ids) then
        raise invalid_parameter_value using
          message = 'duplicate representative', detail = 'SAI_INVALID_ARGUMENT';
      end if;
      select m.id into v_membership_id from public.institution_memberships m
      where m.person_id = v_person_id and m.institution_id = p_institution_id
        and m.status = 'active' and m.revoked_at is null
      for update;
      if v_membership_id is null then
        insert into public.institution_memberships(
          person_id, institution_id, role_code, status, scope_kind)
        values (v_person_id, p_institution_id, 'legal_representative', 'active', 'institution')
        returning id into v_membership_id;
      end if;
      select date_of_birth into v_dob from public.people where id = v_person_id;
      v_rep_status := case
        when v_dob is not null and v_dob <= (current_date - interval '18 years')::date then 'active'
        else 'draft' end;
      -- fecha vinculos do mesmo par em estado diferente e reaproveita o igual
      update public.institution_legal_representatives r set
        status = 'inactive', ends_on = coalesce(r.ends_on, greatest(current_date, r.starts_on))
      where r.institution_id = p_institution_id and r.person_id = v_person_id
        and r.status in ('active','draft') and r.status <> v_rep_status;
      if exists (
        select 1 from public.institution_legal_representatives r
        where r.institution_id = p_institution_id and r.person_id = v_person_id and r.status = v_rep_status
      ) then
        update public.institution_legal_representatives r set
          is_primary = coalesce((v_entry ->> 'is_primary')::boolean, false),
          membership_id = v_membership_id
        where r.institution_id = p_institution_id and r.person_id = v_person_id and r.status = v_rep_status;
      else
        insert into public.institution_legal_representatives(
          institution_id, person_id, membership_id, is_primary, starts_on, status)
        values (p_institution_id, v_person_id, v_membership_id,
          coalesce((v_entry ->> 'is_primary')::boolean, false), current_date, v_rep_status);
      end if;
      kept_representative_ids := kept_representative_ids || v_person_id;
    end loop;
    -- quem saiu da lista e encerrado
    update public.institution_legal_representatives r set
      status = 'inactive', ends_on = coalesce(r.ends_on, greatest(current_date, r.starts_on))
    where r.institution_id = p_institution_id and r.status in ('active','draft')
      and not (r.person_id = any(kept_representative_ids));
  end if;

  -- administradores que sairam da lista: rebaixa ou encerra a membership
  if p_payload ? 'administrators' then
    for v_membership_id, v_person_id in
      select m.id, m.person_id from public.institution_memberships m
      where m.institution_id = p_institution_id and m.status = 'active' and m.revoked_at is null
        and m.role_code = any(admin_role_codes)
        and not (m.person_id = any(kept_administrator_ids))
    loop
      if exists (
        select 1 from public.institution_legal_representatives r
        where r.membership_id = v_membership_id and r.status in ('active','draft')
      ) then
        update public.institution_memberships set role_code = 'legal_representative'
        where id = v_membership_id;
      else
        update public.institution_memberships set status = 'inactive', revoked_at = pg_catalog.now()
        where id = v_membership_id;
      end if;
    end loop;
  end if;

  -- representantes sem papel administrativo que sairam: encerra a membership orfa
  if p_payload ? 'representatives' then
    update public.institution_memberships m set status = 'inactive', revoked_at = pg_catalog.now()
    where m.institution_id = p_institution_id and m.status = 'active' and m.revoked_at is null
      and m.role_code = 'legal_representative'
      and not exists (
        select 1 from public.institution_legal_representatives r
        where r.membership_id = m.id and r.status in ('active','draft'));
  end if;

  update public.institutions institution set
    management_version = institution.management_version + 1,
    updated_at = greatest(pg_catalog.clock_timestamp(),
      institution.updated_at + interval '1 microsecond')
  where institution.id = p_institution_id
  returning institution.management_version into result_version;

  insert into app_private.superadmin_internal_institution_edit_receipts(
    request_id, actor_internal_identity_id, institution_id, expected_version,
    request_hash, result_management_version, original_correlation_id)
  values (p_request_id, p_context.internal_identity_id, p_institution_id,
    p_expected_version, p_request_hash, result_version, p_correlation_id);

  return pg_catalog.jsonb_build_object(
    'institution_id', p_institution_id,
    'management_version', result_version,
    'correlation_id', p_correlation_id,
    'replayed', false);
end
$$;


ALTER FUNCTION "app_private"."superadmin_institution_contacts_apply_v1"("p_request_id" "uuid", "p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb", "p_request_hash" "bytea", "p_context" "app_private"."superadmin_internal_context", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_contacts_request_hash_v1"("p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "bytea"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select extensions.digest(
    pg_catalog.convert_to(pg_catalog.jsonb_build_object(
      'command_kind', 'institution.edit_contacts',
      'institution_id', p_institution_id,
      'expected_version', p_expected_version,
      'payload', p_payload
    )::text, 'UTF8'),
    'sha256'
  )
$$;


ALTER FUNCTION "app_private"."superadmin_institution_contacts_request_hash_v1"("p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_contacts_upsert_person_v1"("p_person" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_person_id uuid;
  v_person_record public.people%rowtype;
  v_first_name text := p_person ->> 'first_name';
  v_last_name text := p_person ->> 'last_name';
  v_display_name text := p_person ->> 'display_name';
  v_email_value text := p_person ->> 'email';
  v_phone_digits text := p_person ->> 'mobile_phone';
  v_cpf_digits text := p_person ->> 'cpf';
  v_dob date := (p_person ->> 'date_of_birth')::date;
  v_new_hash text;
begin
  if p_person ? 'person_id' then
    v_person_id := (p_person ->> 'person_id')::uuid;
    select * into v_person_record from public.people where id = v_person_id for update;
    if v_person_record.id is null or v_person_record.deleted_at is not null
      or v_person_record.person_type <> 'adult' then
      raise invalid_parameter_value using
        message = 'person not found or not an adult', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    update public.people set
      first_name = coalesce(v_first_name, people.first_name),
      last_name = coalesce(v_last_name, people.last_name),
      display_name = coalesce(v_display_name,
        case when v_first_name is not null or v_last_name is not null
          then coalesce(v_first_name, people.first_name) || ' ' || coalesce(v_last_name, people.last_name)
          else people.display_name end),
      date_of_birth = coalesce(v_dob, people.date_of_birth),
      updated_at = pg_catalog.now()
    where id = v_person_id;
  else
    insert into public.people(person_type, first_name, last_name, display_name, date_of_birth, status)
    values ('adult', v_first_name, v_last_name,
      coalesce(v_display_name, v_first_name || ' ' || v_last_name), v_dob, 'active')
    returning id into v_person_id;
  end if;

  if v_email_value is not null then
    v_new_hash := encode(extensions.digest(pg_catalog.convert_to(v_email_value, 'UTF8'), 'sha256'), 'hex');
    if not exists (
      select 1 from public.person_contacts c
      where c.person_id = v_person_id and c.contact_type = 'email'
        and c.status = 'active' and c.normalized_value_hash = v_new_hash
    ) then
      update public.person_contacts set status = 'inactive'
      where person_contacts.person_id = v_person_id and contact_type = 'email' and status = 'active';
      insert into public.person_contacts(person_id, contact_type, normalized_value_hash, masked_value, status)
      values (v_person_id, 'email', v_new_hash, app_private.mask_email_v1(v_email_value), 'active');
    end if;
  end if;

  if v_phone_digits is not null then
    v_new_hash := encode(extensions.digest(pg_catalog.convert_to(v_phone_digits, 'UTF8'), 'sha256'), 'hex');
    if not exists (
      select 1 from public.person_contacts c
      where c.person_id = v_person_id and c.contact_type = 'mobile_phone'
        and c.status = 'active' and c.normalized_value_hash = v_new_hash
    ) then
      update public.person_contacts set status = 'inactive'
      where person_contacts.person_id = v_person_id and contact_type = 'mobile_phone' and status = 'active';
      insert into public.person_contacts(person_id, contact_type, normalized_value_hash, masked_value, status)
      values (v_person_id, 'mobile_phone', v_new_hash, app_private.mask_phone_v1(v_phone_digits), 'active');
    end if;
  end if;

  if v_cpf_digits is not null then
    if not exists (
      select 1 from app_private.person_identity_identifiers i
      where i.person_id = v_person_id and i.identifier_kind = 'cpf' and i.status = 'active'
        and i.normalized_value_hmac = app_private.person_identity_hmac_v1(v_cpf_digits)
    ) then
      update app_private.person_identity_identifiers
      set status = 'inactive', revoked_at = pg_catalog.now(), updated_at = pg_catalog.now()
      where person_identity_identifiers.person_id = v_person_id
        and identifier_kind = 'cpf' and status = 'active';
      insert into app_private.person_identity_identifiers(
        person_id, identifier_kind, normalized_value_hmac, hmac_key_version, masked_value, status)
      values (v_person_id, 'cpf', app_private.person_identity_hmac_v1(v_cpf_digits), 1,
        app_private.mask_cpf_v1(v_cpf_digits), 'active');
    end if;
  end if;

  return v_person_id;
end
$$;


ALTER FUNCTION "app_private"."superadmin_institution_contacts_upsert_person_v1"("p_person" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_contacts_validate_person_v1"("p_person" "jsonb", "p_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  unknown_key text;
  key_name text;
  out_person jsonb := '{}'::jsonb;
  email_value text;
  phone_digits text;
  cpf_digits text;
  level_value text;
  dob date;
begin
  if p_person is null or pg_catalog.jsonb_typeof(p_person) <> 'object' then
    raise invalid_parameter_value using
      message = 'invalid person entry', detail = 'SAI_INVALID_ARGUMENT';
  end if;
  select k into unknown_key
  from pg_catalog.jsonb_object_keys(p_person) k
  where not (k = any(array[
    'person_id','first_name','last_name','display_name','email','mobile_phone',
    'cpf','date_of_birth','is_primary','level'
  ]::text[]))
  limit 1;
  if unknown_key is not null then
    raise invalid_parameter_value using
      message = 'unknown person payload key', detail = 'SAI_INVALID_ARGUMENT';
  end if;

  if p_person ? 'person_id' and pg_catalog.jsonb_typeof(p_person -> 'person_id') <> 'null' then
    if pg_catalog.jsonb_typeof(p_person -> 'person_id') <> 'string'
      or (p_person ->> 'person_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise invalid_parameter_value using
        message = 'invalid person_id', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    out_person := out_person || pg_catalog.jsonb_build_object('person_id', p_person ->> 'person_id');
  end if;

  foreach key_name in array array['first_name','last_name','display_name']::text[] loop
    if p_person ? key_name and pg_catalog.jsonb_typeof(p_person -> key_name) <> 'null' then
      if pg_catalog.jsonb_typeof(p_person -> key_name) <> 'string'
        or pg_catalog.char_length(pg_catalog.btrim(p_person ->> key_name)) > 120
        or (p_person ->> key_name) ~ U&'[\0001-\001f\007f]' then
        raise invalid_parameter_value using
          message = 'invalid person name', detail = 'SAI_INVALID_ARGUMENT';
      end if;
      if pg_catalog.btrim(p_person ->> key_name) <> '' then
        out_person := out_person
          || pg_catalog.jsonb_build_object(key_name, pg_catalog.btrim(p_person ->> key_name));
      end if;
    end if;
  end loop;
  if not (out_person ? 'person_id')
    and (not (out_person ? 'first_name') or not (out_person ? 'last_name')) then
    raise invalid_parameter_value using
      message = 'first_name and last_name are required for a new person',
      detail = 'SAI_INVALID_ARGUMENT';
  end if;

  if p_person ? 'email' and pg_catalog.jsonb_typeof(p_person -> 'email') <> 'null' then
    email_value := pg_catalog.lower(pg_catalog.btrim(p_person ->> 'email'));
    if email_value <> '' then
      if pg_catalog.char_length(email_value) > 254
        or email_value !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
        raise invalid_parameter_value using
          message = 'invalid person email', detail = 'SAI_INVALID_ARGUMENT';
      end if;
      out_person := out_person || pg_catalog.jsonb_build_object('email', email_value);
    end if;
  end if;

  if p_person ? 'mobile_phone' and pg_catalog.jsonb_typeof(p_person -> 'mobile_phone') <> 'null' then
    phone_digits := pg_catalog.regexp_replace(coalesce(p_person ->> 'mobile_phone', ''), '[^0-9]', '', 'g');
    if phone_digits <> '' then
      if phone_digits !~ '^[0-9]{10,13}$' then
        raise invalid_parameter_value using
          message = 'invalid person mobile_phone', detail = 'SAI_INVALID_ARGUMENT';
      end if;
      out_person := out_person || pg_catalog.jsonb_build_object('mobile_phone', phone_digits);
    end if;
  end if;

  if p_person ? 'cpf' and pg_catalog.jsonb_typeof(p_person -> 'cpf') <> 'null' then
    cpf_digits := pg_catalog.regexp_replace(coalesce(p_person ->> 'cpf', ''), '[^0-9]', '', 'g');
    if cpf_digits <> '' then
      if not app_private.cpf_digits_valid_v1(cpf_digits) then
        raise invalid_parameter_value using
          message = 'invalid person cpf', detail = 'SAI_INVALID_ARGUMENT';
      end if;
      out_person := out_person || pg_catalog.jsonb_build_object('cpf', cpf_digits);
    end if;
  end if;

  if p_person ? 'date_of_birth' and pg_catalog.jsonb_typeof(p_person -> 'date_of_birth') <> 'null' then
    begin
      dob := (p_person ->> 'date_of_birth')::date;
    exception when others then
      raise invalid_parameter_value using
        message = 'invalid date_of_birth', detail = 'SAI_INVALID_ARGUMENT';
    end;
    if dob > current_date or dob < date '1900-01-01' then
      raise invalid_parameter_value using
        message = 'invalid date_of_birth', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    out_person := out_person || pg_catalog.jsonb_build_object('date_of_birth', dob);
  end if;

  if p_kind = 'representative' then
    if p_person ? 'level' then
      raise invalid_parameter_value using
        message = 'level is only for administrators', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    out_person := out_person || pg_catalog.jsonb_build_object(
      'is_primary', coalesce((p_person ->> 'is_primary')::boolean, false));
  else
    if p_person ? 'is_primary' then
      raise invalid_parameter_value using
        message = 'is_primary is only for representatives', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    level_value := coalesce(p_person ->> 'level', '');
    if level_value not in ('admin_master','authorized_administrator','coordinator') then
      raise invalid_parameter_value using
        message = 'invalid administrator level', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    out_person := out_person || pg_catalog.jsonb_build_object('level', level_value);
  end if;

  return out_person;
end
$_$;


ALTER FUNCTION "app_private"."superadmin_institution_contacts_validate_person_v1"("p_person" "jsonb", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_contacts_validate_v1"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  unknown_key text;
  key_name text;
  out_payload jsonb := '{}'::jsonb;
  child jsonb;
  out_child jsonb;
  entry jsonb;
  items jsonb;
  text_value text;
  digits text;
  primary_count integer;
begin
  if p_payload is null
    or pg_catalog.jsonb_typeof(p_payload) <> 'object'
    or p_payload = '{}'::jsonb
    or pg_catalog.octet_length(p_payload::text) > 65536 then
    raise invalid_parameter_value using
      message = 'invalid institution contacts payload', detail = 'SAI_INVALID_ARGUMENT';
  end if;
  select k into unknown_key
  from pg_catalog.jsonb_object_keys(p_payload) k
  where not (k = any(array['document','contact','representatives','administrators']::text[]))
  limit 1;
  if unknown_key is not null then
    raise invalid_parameter_value using
      message = 'unknown institution contacts payload key', detail = 'SAI_INVALID_ARGUMENT';
  end if;

  -- documento
  if p_payload ? 'document' then
    child := p_payload -> 'document';
    if pg_catalog.jsonb_typeof(child) <> 'object' then
      raise invalid_parameter_value using
        message = 'document must be an object', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    select k into unknown_key from pg_catalog.jsonb_object_keys(child) k
    where not (k = any(array['document_type','document_ref']::text[])) limit 1;
    if unknown_key is not null then
      raise invalid_parameter_value using
        message = 'unknown document payload key', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    text_value := pg_catalog.lower(pg_catalog.btrim(coalesce(child ->> 'document_type', 'cnpj')));
    if text_value <> 'cnpj' then
      raise invalid_parameter_value using
        message = 'only cnpj documents are supported', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    digits := pg_catalog.regexp_replace(coalesce(child ->> 'document_ref', ''), '[^0-9]', '', 'g');
    if digits = '' then
      out_child := pg_catalog.jsonb_build_object('document_type', 'cnpj', 'document_ref', null);
    else
      if not app_private.cnpj_digits_valid_v1(digits) then
        raise invalid_parameter_value using
          message = 'invalid cnpj', detail = 'SAI_INVALID_ARGUMENT';
      end if;
      out_child := pg_catalog.jsonb_build_object('document_type', 'cnpj', 'document_ref', digits);
    end if;
    out_payload := out_payload || pg_catalog.jsonb_build_object('document', out_child);
  end if;

  -- contato da instituicao
  if p_payload ? 'contact' then
    child := p_payload -> 'contact';
    if pg_catalog.jsonb_typeof(child) <> 'object' then
      raise invalid_parameter_value using
        message = 'contact must be an object', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    select k into unknown_key from pg_catalog.jsonb_object_keys(child) k
    where not (k = any(array['email','phone','mobile_phone','website_url','whatsapp_number']::text[])) limit 1;
    if unknown_key is not null then
      raise invalid_parameter_value using
        message = 'unknown contact payload key', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    out_child := '{}'::jsonb;
    foreach key_name in array array['email','phone','mobile_phone','website_url','whatsapp_number']::text[] loop
      if pg_catalog.jsonb_typeof(child -> key_name) = 'string' then
        text_value := pg_catalog.btrim(child ->> key_name);
        if text_value ~ U&'[\0001-\001f\007f]' or pg_catalog.char_length(text_value) > 2048 then
          raise invalid_parameter_value using
            message = 'invalid contact value', detail = 'SAI_INVALID_ARGUMENT';
        end if;
        if key_name = 'email' then text_value := pg_catalog.lower(text_value); end if;
        if key_name = 'email' and text_value <> ''
          and text_value !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
          raise invalid_parameter_value using
            message = 'invalid contact email', detail = 'SAI_INVALID_ARGUMENT';
        end if;
        if key_name in ('phone','mobile_phone') and text_value <> '' then
          text_value := pg_catalog.regexp_replace(text_value, '[^0-9+]', '', 'g');
          if text_value !~ '^\+?[0-9]{8,15}$' then
            raise invalid_parameter_value using
              message = 'invalid contact phone', detail = 'SAI_INVALID_ARGUMENT';
          end if;
        end if;
        if key_name = 'whatsapp_number' and text_value <> '' then
          text_value := pg_catalog.regexp_replace(text_value, '[^0-9+]', '', 'g');
          if text_value !~ '^\+' then text_value := '+' || text_value; end if;
          if text_value !~ '^\+[1-9][0-9]{7,14}$' then
            raise invalid_parameter_value using
              message = 'invalid whatsapp number', detail = 'SAI_INVALID_ARGUMENT';
          end if;
        end if;
        if key_name = 'website_url' and text_value <> ''
          and text_value !~* '^https?://[[:alnum:]]([[:alnum:].-]*[[:alnum:]])?(:[0-9]{1,5})?([/?#][^[:space:]]*)?$' then
          raise invalid_parameter_value using
            message = 'invalid website url', detail = 'SAI_INVALID_ARGUMENT';
        end if;
        out_child := out_child || pg_catalog.jsonb_build_object(key_name,
          case when text_value = '' then null else text_value end);
      elsif child ? key_name and pg_catalog.jsonb_typeof(child -> key_name) <> 'null' then
        raise invalid_parameter_value using
          message = 'invalid contact value', detail = 'SAI_INVALID_ARGUMENT';
      else
        out_child := out_child || pg_catalog.jsonb_build_object(key_name, null);
      end if;
    end loop;
    out_payload := out_payload || pg_catalog.jsonb_build_object('contact', out_child);
  end if;

  -- representantes legais
  if p_payload ? 'representatives' then
    if pg_catalog.jsonb_typeof(p_payload -> 'representatives') <> 'array'
      or pg_catalog.jsonb_array_length(p_payload -> 'representatives') > 20 then
      raise invalid_parameter_value using
        message = 'representatives must be an array of up to 20 entries',
        detail = 'SAI_INVALID_ARGUMENT';
    end if;
    items := '[]'::jsonb;
    for entry in select value from pg_catalog.jsonb_array_elements(p_payload -> 'representatives') loop
      items := items || app_private.superadmin_institution_contacts_validate_person_v1(entry, 'representative');
    end loop;
    select count(*) into primary_count
    from pg_catalog.jsonb_array_elements(items) e where (e ->> 'is_primary')::boolean;
    if primary_count > 1 then
      raise invalid_parameter_value using
        message = 'only one primary representative is allowed', detail = 'SAI_INVALID_ARGUMENT';
    end if;
    out_payload := out_payload || pg_catalog.jsonb_build_object('representatives', items);
  end if;

  -- administradores
  if p_payload ? 'administrators' then
    if pg_catalog.jsonb_typeof(p_payload -> 'administrators') <> 'array'
      or pg_catalog.jsonb_array_length(p_payload -> 'administrators') > 20 then
      raise invalid_parameter_value using
        message = 'administrators must be an array of up to 20 entries',
        detail = 'SAI_INVALID_ARGUMENT';
    end if;
    items := '[]'::jsonb;
    for entry in select value from pg_catalog.jsonb_array_elements(p_payload -> 'administrators') loop
      items := items || app_private.superadmin_institution_contacts_validate_person_v1(entry, 'administrator');
    end loop;
    out_payload := out_payload || pg_catalog.jsonb_build_object('administrators', items);
  end if;

  return out_payload;
end
$_$;


ALTER FUNCTION "app_private"."superadmin_institution_contacts_validate_v1"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_create_apply_v2"("p_request_id" "uuid", "p_payload" "jsonb", "p_request_hash" "bytea", "p_context" "app_private"."superadmin_internal_context", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  prior_receipt app_private.superadmin_internal_institution_create_receipts%rowtype;
  requested_type_id uuid;
  named_type_id uuid;
  new_institution_id uuid;
  result_version bigint;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_request_id::text,0)
  );

  select receipt.* into prior_receipt
  from app_private.superadmin_internal_institution_create_receipts receipt
  where receipt.request_id=p_request_id;

  if prior_receipt.request_id is not null then
    if prior_receipt.actor_internal_identity_id
         is distinct from p_context.internal_identity_id
      or prior_receipt.request_hash is distinct from p_request_hash then
      raise invalid_parameter_value using
        message='request id already used',detail='SAI_INVALID_ARGUMENT';
    end if;
    select institution.management_version into result_version
    from public.institutions institution
    where institution.id=prior_receipt.institution_id;
    return pg_catalog.jsonb_build_object(
      'institution_id',prior_receipt.institution_id,
      'management_version',result_version,
      'correlation_id',p_correlation_id,
      'replayed',true
    );
  end if;

  if p_payload?'institution_type_id' then
    select institution_type.id into requested_type_id
    from public.institution_types institution_type
    where institution_type.id=(p_payload->>'institution_type_id')::uuid
      and institution_type.status='active'
    for share;
    if not found then
      raise invalid_parameter_value using
        message='invalid institution type',detail='SAI_INVALID_ARGUMENT';
    end if;
  end if;

  if p_payload?'institution_type_name' then
    select institution_type.id into named_type_id
    from public.institution_types institution_type
    where pg_catalog.lower(institution_type.name)
        =pg_catalog.lower(p_payload->>'institution_type_name')
      and institution_type.status='active'
    order by institution_type.created_at,institution_type.id
    limit 1
    for share;
    if named_type_id is null then
      raise invalid_parameter_value using
        message='unknown or inactive institution type',detail='SAI_INVALID_ARGUMENT';
    end if;
    if requested_type_id is not null and requested_type_id<>named_type_id then
      raise invalid_parameter_value using
        message='institution type id and name disagree',detail='SAI_INVALID_ARGUMENT';
    end if;
    requested_type_id:=named_type_id;
  end if;

  if exists(
    select 1 from public.institutions institution
    where institution.slug=p_payload->>'slug'
  ) then
    raise unique_violation using
      message='institution handle already in use',detail='SAI_INVALID_ARGUMENT';
  end if;

  insert into public.institutions(
    public_name,trade_name,legal_name,slug,status,timezone,locale,
    institution_type_id
  ) values(
    p_payload->>'public_name',
    p_payload->>'trade_name',
    p_payload->>'legal_name',
    p_payload->>'slug',
    'draft',
    coalesce(p_payload->>'timezone','America/Sao_Paulo'),
    coalesce(p_payload->>'locale','pt-BR'),
    requested_type_id
  )
  returning id,management_version into new_institution_id,result_version;

  if p_payload?'address' then
    insert into public.institution_addresses(
      institution_id,country,state,city,district,street,number,complement,
      postal_code,status,created_at,updated_at
    ) values(
      new_institution_id,
      p_payload->'address'->>'country',
      p_payload->'address'->>'state',
      p_payload->'address'->>'city',
      p_payload->'address'->>'district',
      p_payload->'address'->>'street',
      p_payload->'address'->>'number',
      p_payload->'address'->>'complement',
      p_payload->'address'->>'postal_code',
      'active',pg_catalog.now(),pg_catalog.now()
    );
  end if;

  insert into app_private.superadmin_internal_institution_create_receipts(
    request_id,actor_internal_identity_id,institution_id,request_hash,
    original_correlation_id
  ) values(
    p_request_id,p_context.internal_identity_id,new_institution_id,
    p_request_hash,p_correlation_id
  );

  return pg_catalog.jsonb_build_object(
    'institution_id',new_institution_id,
    'management_version',result_version,
    'correlation_id',p_correlation_id,
    'replayed',false
  );
end
$$;


ALTER FUNCTION "app_private"."superadmin_institution_create_apply_v2"("p_request_id" "uuid", "p_payload" "jsonb", "p_request_hash" "bytea", "p_context" "app_private"."superadmin_internal_context", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_create_request_hash_v2"("p_payload" "jsonb") RETURNS "bytea"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select extensions.digest(
    pg_catalog.convert_to(
      pg_catalog.jsonb_build_object(
        'command_kind','institution.create',
        'payload',p_payload
      )::text,
      'UTF8'
    ),
    'sha256'
  )
$$;


ALTER FUNCTION "app_private"."superadmin_institution_create_request_hash_v2"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_create_validate_v2"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  normalized_payload jsonb;
  normalized_slug text;
  type_name text;
begin
  if p_payload is null
    or pg_catalog.jsonb_typeof(p_payload)<>'object'
    or pg_catalog.octet_length(p_payload::text)>65536 then
    raise invalid_parameter_value using
      message='invalid institution create payload',detail='SAI_INVALID_ARGUMENT';
  end if;
  if not(p_payload?'slug') or pg_catalog.jsonb_typeof(p_payload->'slug')<>'string'
    or not(p_payload?'public_name') then
    raise invalid_parameter_value using
      message='slug and public_name are required',detail='SAI_INVALID_ARGUMENT';
  end if;

  if p_payload?'institution_type_name' then
    if pg_catalog.jsonb_typeof(p_payload->'institution_type_name')<>'string' then
      raise invalid_parameter_value using
        message='invalid institution type name',detail='SAI_INVALID_ARGUMENT';
    end if;
    type_name:=pg_catalog.btrim(p_payload->>'institution_type_name');
    if type_name='' or pg_catalog.octet_length(type_name)>120
      or type_name ~ '[[:cntrl:]]' then
      raise invalid_parameter_value using
        message='invalid institution type name',detail='SAI_INVALID_ARGUMENT';
    end if;
  end if;

  normalized_payload:=
    app_private.superadmin_institution_edit_core_validate_v2(
      p_payload-'slug'-'institution_type_name'
    );

  if pg_catalog.jsonb_typeof(normalized_payload->'public_name') is distinct from 'string' then
    raise invalid_parameter_value using
      message='public_name is required',detail='SAI_INVALID_ARGUMENT';
  end if;
  if normalized_payload?'address'
    and (
      not((normalized_payload->'address')?'country')
      or normalized_payload->'address'->>'country' is distinct from 'Brasil'
    ) then
    raise invalid_parameter_value using
      message='country Brasil is required for a new institution address',
      detail='SAI_INVALID_ARGUMENT';
  end if;

  normalized_slug:=app_private.normalize_institution_handle(p_payload->>'slug');
  if normalized_slug !~ '^[a-z0-9][a-z0-9._-]{2,29}$' then
    raise invalid_parameter_value using
      message='institution handle must have 3 to 30 allowed characters',
      detail='SAI_INVALID_ARGUMENT';
  end if;

  return normalized_payload
    ||pg_catalog.jsonb_build_object('slug',normalized_slug)
    ||case when type_name is null then '{}'::jsonb
      else pg_catalog.jsonb_build_object('institution_type_name',type_name) end;
end
$_$;


ALTER FUNCTION "app_private"."superadmin_institution_create_validate_v2"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_detail_payload_v2"("p_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.institution_management_payload(p_institution_id)
    || pg_catalog.jsonb_build_object(
      'representatives', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'id', r.id,
          'person_id', p.id,
          'membership_id', r.membership_id,
          'is_primary', r.is_primary,
          'status', r.status::text,
          'starts_on', r.starts_on,
          'first_name', p.first_name,
          'last_name', p.last_name,
          'display_name', p.display_name,
          'handle', (select h.normalized_handle from public.person_handles h
            where h.person_id = p.id and h.status = 'active' and h.revoked_at is null
            order by h.created_at desc limit 1),
          'date_of_birth', p.date_of_birth,
          'email_masked', (select c.masked_value from public.person_contacts c
            where c.person_id = p.id and c.contact_type = 'email' and c.status = 'active'
            order by c.created_at desc limit 1),
          'mobile_phone_masked', (select c.masked_value from public.person_contacts c
            where c.person_id = p.id and c.contact_type = 'mobile_phone' and c.status = 'active'
            order by c.created_at desc limit 1),
          'cpf_masked', (select i.masked_value from app_private.person_identity_identifiers i
            where i.person_id = p.id and i.identifier_kind = 'cpf' and i.status = 'active'
            order by i.created_at desc limit 1)
        ) order by r.is_primary desc, r.starts_on, r.id)
        from public.institution_legal_representatives r
        join public.people p on p.id = r.person_id and p.deleted_at is null
        where r.institution_id = p_institution_id and r.status in ('active','draft')
      ), '[]'::jsonb),
      'administrators', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'membership_id', m.id,
          'person_id', p.id,
          'role_code', m.role_code,
          'level', case m.role_code
            when 'owner' then 'admin_master'
            when 'institution_admin' then 'authorized_administrator'
            else 'coordinator' end,
          'status', m.status::text,
          'first_name', p.first_name,
          'last_name', p.last_name,
          'display_name', p.display_name,
          'handle', (select h.normalized_handle from public.person_handles h
            where h.person_id = p.id and h.status = 'active' and h.revoked_at is null
            order by h.created_at desc limit 1),
          'has_active_login', exists (select 1 from public.person_auth_links l
            where l.person_id = p.id and l.status = 'active' and l.revoked_at is null),
          'invitation_status', case when exists (select 1 from public.person_auth_links l
            where l.person_id = p.id and l.status = 'active' and l.revoked_at is null)
            then 'accepted' else 'not_sent' end,
          'email_masked', (select c.masked_value from public.person_contacts c
            where c.person_id = p.id and c.contact_type = 'email' and c.status = 'active'
            order by c.created_at desc limit 1),
          'mobile_phone_masked', (select c.masked_value from public.person_contacts c
            where c.person_id = p.id and c.contact_type = 'mobile_phone' and c.status = 'active'
            order by c.created_at desc limit 1),
          'cpf_masked', (select i.masked_value from app_private.person_identity_identifiers i
            where i.person_id = p.id and i.identifier_kind = 'cpf' and i.status = 'active'
            order by i.created_at desc limit 1),
          'source_representative_id', (select r.id from public.institution_legal_representatives r
            where r.membership_id = m.id and r.status in ('active','draft')
            order by r.starts_on limit 1)
        ) order by m.created_at, m.id)
        from public.institution_memberships m
        join public.people p on p.id = m.person_id and p.deleted_at is null
        where m.institution_id = p_institution_id and m.status = 'active' and m.revoked_at is null
          and m.role_code in ('owner','institution_admin','coordinator')
          and p.person_type = 'adult'
      ), '[]'::jsonb)
    )
  from public.institutions i
  where i.id = p_institution_id and i.deleted_at is null
$$;


ALTER FUNCTION "app_private"."superadmin_institution_detail_payload_v2"("p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_directory_payload_v2"("p_filters" "jsonb", "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_sort_ascending" boolean, "p_scope_kind" "text", "p_scope_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  search_value text;
  status_values text[];
  state_values text[];
  city_values text[];
  district_values text[];
  type_values text[];
  plan_value uuid;
  result_payload jsonb;
begin
  if p_filters is null or p_limit is null or p_offset is null
    or p_sort is null or p_sort_ascending is null
    or pg_catalog.jsonb_typeof(p_filters)<>'object'
    or p_filters-array[
      'search','statuses','plan_id','states','cities','districts','type_ids'
    ]::text[]<>'{}'::jsonb
    or pg_catalog.octet_length(p_filters::text)>8192
    or p_limit not between 1 and 100
    or p_offset not between 0 and 10000
    or p_sort not in(
      'public_name','type_name','units_count','groups_count','plan_name','status',
      'contact_email','contact_phone','contact_mobile_phone','primary_domain',
      'street','postal_code','number','complement','district','city','state')
    or p_scope_kind not in('platform','institution')
    or (p_scope_kind='institution' and p_scope_institution_id is null) then
    raise invalid_parameter_value using
      message='invalid institution list argument',detail='SAI_INVALID_ARGUMENT';
  end if;

  if p_filters ? 'search' then
    if pg_catalog.jsonb_typeof(p_filters->'search')<>'string' then
      raise invalid_parameter_value using
        message='invalid institution search',detail='SAI_INVALID_ARGUMENT';
    end if;
    search_value:=pg_catalog.btrim(p_filters->>'search');
    if search_value='' or pg_catalog.char_length(search_value)>200 then
      raise invalid_parameter_value using
        message='invalid institution search',detail='SAI_INVALID_ARGUMENT';
    end if;
  end if;

  status_values:=app_private.superadmin_institution_filter_array_v2(
    p_filters,'statuses',6,
    array['draft','onboarding','active','inactive','suspended','archived'],false);
  state_values:=app_private.superadmin_institution_filter_array_v2(
    p_filters,'states',20,null,false);
  city_values:=app_private.superadmin_institution_filter_array_v2(
    p_filters,'cities',20,null,false);
  district_values:=app_private.superadmin_institution_filter_array_v2(
    p_filters,'districts',20,null,false);
  type_values:=app_private.superadmin_institution_filter_array_v2(
    p_filters,'type_ids',20,null,true);

  if p_filters ? 'plan_id' then
    if pg_catalog.jsonb_typeof(p_filters->'plan_id')<>'string'
      or pg_catalog.btrim(p_filters->>'plan_id')='' then
      raise invalid_parameter_value using
        message='invalid institution plan filter',detail='SAI_INVALID_ARGUMENT';
    end if;
    begin
      plan_value:=pg_catalog.btrim(p_filters->>'plan_id')::uuid;
    exception when invalid_text_representation then
      raise invalid_parameter_value using
        message='invalid institution plan filter',detail='SAI_INVALID_ARGUMENT';
    end;
  end if;

  with filtered as materialized(
    select directory.*
    from public.institution_directory directory
    where (p_scope_kind='platform'
      or directory.id=p_scope_institution_id)
      and (search_value is null or pg_catalog.strpos(
        pg_catalog.lower(directory.search_name),
        pg_catalog.lower(search_value))>0)
      and (pg_catalog.cardinality(status_values)=0
        or directory.status=any(status_values))
      and (plan_value is null or directory.plan_id=plan_value)
      and (pg_catalog.cardinality(state_values)=0
        or pg_catalog.btrim(directory.state)=any(state_values))
      and (pg_catalog.cardinality(city_values)=0
        or pg_catalog.btrim(directory.city)=any(city_values))
      and (pg_catalog.cardinality(district_values)=0
        or pg_catalog.btrim(directory.district)=any(district_values))
      and (pg_catalog.cardinality(type_values)=0
        or directory.institution_type_id=any(type_values::uuid[]))
  ),
  ordered as(
    select filtered.*,
      row_number() over(order by
        case when p_sort='public_name' and p_sort_ascending then public_name end asc nulls last,
        case when p_sort='public_name' and not p_sort_ascending then public_name end desc nulls last,
        case when p_sort='type_name' and p_sort_ascending then type_name end asc nulls last,
        case when p_sort='type_name' and not p_sort_ascending then type_name end desc nulls last,
        case when p_sort='units_count' and p_sort_ascending then units_count end asc nulls last,
        case when p_sort='units_count' and not p_sort_ascending then units_count end desc nulls last,
        case when p_sort='groups_count' and p_sort_ascending then groups_count end asc nulls last,
        case when p_sort='groups_count' and not p_sort_ascending then groups_count end desc nulls last,
        case when p_sort='plan_name' and p_sort_ascending then plan_name end asc nulls last,
        case when p_sort='plan_name' and not p_sort_ascending then plan_name end desc nulls last,
        case when p_sort='status' and p_sort_ascending then status end asc nulls last,
        case when p_sort='status' and not p_sort_ascending then status end desc nulls last,
        case when p_sort='contact_email' and p_sort_ascending then contact_email end asc nulls last,
        case when p_sort='contact_email' and not p_sort_ascending then contact_email end desc nulls last,
        case when p_sort='contact_phone' and p_sort_ascending then contact_phone end asc nulls last,
        case when p_sort='contact_phone' and not p_sort_ascending then contact_phone end desc nulls last,
        case when p_sort='contact_mobile_phone' and p_sort_ascending then contact_mobile_phone end asc nulls last,
        case when p_sort='contact_mobile_phone' and not p_sort_ascending then contact_mobile_phone end desc nulls last,
        case when p_sort='primary_domain' and p_sort_ascending then primary_domain end asc nulls last,
        case when p_sort='primary_domain' and not p_sort_ascending then primary_domain end desc nulls last,
        case when p_sort='street' and p_sort_ascending then street end asc nulls last,
        case when p_sort='street' and not p_sort_ascending then street end desc nulls last,
        case when p_sort='postal_code' and p_sort_ascending then postal_code end asc nulls last,
        case when p_sort='postal_code' and not p_sort_ascending then postal_code end desc nulls last,
        case when p_sort='number' and p_sort_ascending then number end asc nulls last,
        case when p_sort='number' and not p_sort_ascending then number end desc nulls last,
        case when p_sort='complement' and p_sort_ascending then complement end asc nulls last,
        case when p_sort='complement' and not p_sort_ascending then complement end desc nulls last,
        case when p_sort='district' and p_sort_ascending then district end asc nulls last,
        case when p_sort='district' and not p_sort_ascending then district end desc nulls last,
        case when p_sort='city' and p_sort_ascending then city end asc nulls last,
        case when p_sort='city' and not p_sort_ascending then city end desc nulls last,
        case when p_sort='state' and p_sort_ascending then state end asc nulls last,
        case when p_sort='state' and not p_sort_ascending then state end desc nulls last,
        id asc) as row_order
    from filtered
  ),
  page_rows as(
    select * from ordered order by row_order limit p_limit offset p_offset
  )
  select pg_catalog.jsonb_build_object(
    'items',coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id',id,'public_name',public_name,'trade_name',trade_name,
        'legal_name',legal_name,'primary_domain',primary_domain,'status',status,
        'institution_type_id',institution_type_id,'type_name',type_name,
        'district',district,'street',street,'number',number,
        'complement',complement,'postal_code',postal_code,'city',city,'state',state,
        'contact_email',contact_email,'contact_phone',contact_phone,
        'contact_mobile_phone',contact_mobile_phone,'plan_id',plan_id,
        'plan_name',plan_name,'units_count',units_count,'groups_count',groups_count)
      order by row_order) from page_rows),'[]'::jsonb),
    'total_count',(select count(*) from filtered),
    'limit',p_limit,'offset',p_offset)
  into result_payload;
  return result_payload;
end
$$;


ALTER FUNCTION "app_private"."superadmin_institution_directory_payload_v2"("p_filters" "jsonb", "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_sort_ascending" boolean, "p_scope_kind" "text", "p_scope_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_edit_core_apply_v2"("p_request_id" "uuid", "p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb", "p_request_hash" "bytea", "p_context" "app_private"."superadmin_internal_context", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  prior_receipt app_private.superadmin_internal_institution_edit_receipts%rowtype;
  institution_record public.institutions%rowtype;
  address_record public.institution_addresses%rowtype;
  requested_type_id uuid;
  requested_public_name text;
  requested_trade_name text;
  requested_legal_name text;
  requested_timezone text;
  requested_locale text;
  requested_country text;
  requested_state text;
  requested_city text;
  requested_district text;
  requested_street text;
  requested_number text;
  requested_complement text;
  requested_postal_code text;
  address_changed boolean:=false;
  root_changed boolean:=false;
  result_version bigint;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_request_id::text,0)
  );

  select receipt.* into prior_receipt
  from app_private.superadmin_internal_institution_edit_receipts receipt
  where receipt.request_id=p_request_id;

  if prior_receipt.request_id is not null then
    if prior_receipt.actor_internal_identity_id
         is distinct from p_context.internal_identity_id
      or prior_receipt.institution_id is distinct from p_institution_id
      or prior_receipt.expected_version is distinct from p_expected_version
      or prior_receipt.request_hash is distinct from p_request_hash then
      raise invalid_parameter_value using
        message='request id already used',detail='SAI_INVALID_ARGUMENT';
    end if;

    return pg_catalog.jsonb_build_object(
      'institution_id',prior_receipt.institution_id,
      'management_version',prior_receipt.result_management_version,
      'correlation_id',p_correlation_id,
      'replayed',true
    );
  end if;

  select institution.* into institution_record
  from public.institutions institution
  where institution.id=p_institution_id and institution.deleted_at is null
  for update;
  if institution_record.id is null then
    raise insufficient_privilege using
      message='internal institution access denied',detail='SAI_PERMISSION_DENIED';
  end if;
  if institution_record.management_version is distinct from p_expected_version then
    raise serialization_failure using
      message='stale institution version',detail='SAI_CONCURRENT_CHANGE';
  end if;

  requested_type_id:=institution_record.institution_type_id;
  if p_payload?'institution_type_id' then
    select institution_type.id into requested_type_id
    from public.institution_types institution_type
    where institution_type.id=(p_payload->>'institution_type_id')::uuid
      and institution_type.status='active'
    for share;
    if not found then
      raise invalid_parameter_value using
        message='invalid institution type',detail='SAI_INVALID_ARGUMENT';
    end if;
  end if;

  requested_public_name:=case when p_payload?'public_name'
    then p_payload->>'public_name' else institution_record.public_name end;
  requested_trade_name:=case when p_payload?'trade_name'
    then p_payload->>'trade_name' else institution_record.trade_name end;
  requested_legal_name:=case when p_payload?'legal_name'
    then p_payload->>'legal_name' else institution_record.legal_name end;
  requested_timezone:=case when p_payload?'timezone'
    then p_payload->>'timezone' else institution_record.timezone end;
  requested_locale:=case when p_payload?'locale'
    then p_payload->>'locale' else institution_record.locale end;

  root_changed:=requested_public_name is distinct from institution_record.public_name
    or requested_trade_name is distinct from institution_record.trade_name
    or requested_legal_name is distinct from institution_record.legal_name
    or requested_timezone is distinct from institution_record.timezone
    or requested_locale is distinct from institution_record.locale
    or requested_type_id is distinct from institution_record.institution_type_id;

  if p_payload?'address' then
    select address_item.* into address_record
    from public.institution_addresses address_item
    where address_item.institution_id=p_institution_id;
    if address_record.institution_id is null
      and (
        not((p_payload->'address')?'country')
        or p_payload->'address'->>'country'<>'Brasil'
      ) then
      raise invalid_parameter_value using
        message='country Brasil is required for a new institution address',
        detail='SAI_INVALID_ARGUMENT';
    end if;
    requested_country:=case when (p_payload->'address')?'country'
      then p_payload->'address'->>'country'
      else address_record.country end;
    requested_state:=case when (p_payload->'address')?'state'
      then p_payload->'address'->>'state' else address_record.state end;
    requested_city:=case when (p_payload->'address')?'city'
      then p_payload->'address'->>'city' else address_record.city end;
    requested_district:=case when (p_payload->'address')?'district'
      then p_payload->'address'->>'district' else address_record.district end;
    requested_street:=case when (p_payload->'address')?'street'
      then p_payload->'address'->>'street' else address_record.street end;
    requested_number:=case when (p_payload->'address')?'number'
      then p_payload->'address'->>'number' else address_record.number end;
    requested_complement:=case when (p_payload->'address')?'complement'
      then p_payload->'address'->>'complement' else address_record.complement end;
    requested_postal_code:=case when (p_payload->'address')?'postal_code'
      then p_payload->'address'->>'postal_code' else address_record.postal_code end;
    address_changed:=address_record.institution_id is null
      or requested_country is distinct from address_record.country
      or requested_state is distinct from address_record.state
      or requested_city is distinct from address_record.city
      or requested_district is distinct from address_record.district
      or requested_street is distinct from address_record.street
      or requested_number is distinct from address_record.number
      or requested_complement is distinct from address_record.complement
      or requested_postal_code is distinct from address_record.postal_code;
  end if;

  if not(root_changed or address_changed) then
    raise invalid_parameter_value using
      message='institution edit is a no-op',detail='SAI_INVALID_ARGUMENT';
  end if;

  update public.institutions institution set
    public_name=requested_public_name,
    trade_name=requested_trade_name,
    legal_name=requested_legal_name,
    timezone=requested_timezone,
    locale=requested_locale,
    institution_type_id=requested_type_id,
    management_version=institution.management_version+1,
    updated_at=greatest(
      pg_catalog.clock_timestamp(),institution.updated_at+interval '1 microsecond'
    )
  where institution.id=p_institution_id
  returning institution.management_version into result_version;

  if address_changed then
    insert into public.institution_addresses(
      institution_id,country,state,city,district,street,number,complement,
      postal_code,status,created_at,updated_at
    ) values(
      p_institution_id,requested_country,requested_state,requested_city,
      requested_district,requested_street,requested_number,requested_complement,
      requested_postal_code,'active',pg_catalog.now(),pg_catalog.now()
    )
    on conflict(institution_id) do update set
      country=excluded.country,state=excluded.state,city=excluded.city,
      district=excluded.district,street=excluded.street,number=excluded.number,
      complement=excluded.complement,postal_code=excluded.postal_code,
      updated_at=greatest(
        pg_catalog.clock_timestamp(),
        public.institution_addresses.updated_at+interval '1 microsecond'
      );
  end if;

  insert into app_private.superadmin_internal_institution_edit_receipts(
    request_id,actor_internal_identity_id,institution_id,expected_version,
    request_hash,result_management_version,original_correlation_id
  ) values(
    p_request_id,p_context.internal_identity_id,p_institution_id,
    p_expected_version,p_request_hash,result_version,p_correlation_id
  );

  return pg_catalog.jsonb_build_object(
    'institution_id',p_institution_id,
    'management_version',result_version,
    'correlation_id',p_correlation_id,
    'replayed',false
  );
end
$$;


ALTER FUNCTION "app_private"."superadmin_institution_edit_core_apply_v2"("p_request_id" "uuid", "p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb", "p_request_hash" "bytea", "p_context" "app_private"."superadmin_internal_context", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_edit_core_request_hash_v2"("p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "bytea"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select extensions.digest(
    pg_catalog.convert_to(pg_catalog.jsonb_build_object(
      'command_kind','institution.edit_core',
      'institution_id',p_institution_id,
      'expected_version',p_expected_version,
      'payload',p_payload
    )::text,'UTF8'),
    'sha256'
  )
$$;


ALTER FUNCTION "app_private"."superadmin_institution_edit_core_request_hash_v2"("p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_edit_core_validate_v2"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  unknown_key text;
  key_name text;
  normalized_payload jsonb:='{}'::jsonb;
  normalized_child jsonb;
  normalized_type_id uuid;
begin
  if p_payload is null
    or pg_catalog.jsonb_typeof(p_payload)<>'object'
    or p_payload='{}'::jsonb
    or pg_catalog.octet_length(p_payload::text)>65536 then
    raise invalid_parameter_value using
      message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
  end if;

  select payload_key into unknown_key
  from pg_catalog.jsonb_object_keys(p_payload) payload_key
  where not(payload_key=any(array[
    'public_name','trade_name','legal_name','timezone','locale',
    'institution_type_id','address'
  ]::text[]))
  limit 1;
  if unknown_key is not null then
    raise invalid_parameter_value using
      message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
  end if;

  foreach key_name in array array[
    'public_name','trade_name','legal_name','timezone','locale'
  ]::text[] loop
    if p_payload?key_name then
      if pg_catalog.jsonb_typeof(p_payload->key_name) not in('string','null') then
        raise invalid_parameter_value using
          message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
      end if;
      if key_name=any(array[
        'public_name','timezone','locale'
      ]::text[]) and (
        pg_catalog.jsonb_typeof(p_payload->key_name)='null'
        or pg_catalog.btrim(p_payload->>key_name)=''
      ) then
        raise invalid_parameter_value using
          message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
      end if;
      normalized_payload:=normalized_payload||pg_catalog.jsonb_build_object(
        key_name,
        case
          when key_name=any(array[
            'public_name','timezone','locale'
          ]::text[]) then pg_catalog.to_jsonb(pg_catalog.btrim(p_payload->>key_name))
          when pg_catalog.jsonb_typeof(p_payload->key_name)='null'
            or pg_catalog.btrim(p_payload->>key_name)='' then 'null'::jsonb
          else pg_catalog.to_jsonb(pg_catalog.btrim(p_payload->>key_name))
        end
      );

      if pg_catalog.jsonb_typeof(normalized_payload->key_name)='string'
        and (
          normalized_payload->>key_name ~ U&'[\0001-\001f\007f]'
          or pg_catalog.octet_length(normalized_payload->>key_name)>
            case
              when key_name in('public_name','trade_name','legal_name') then 240
              when key_name='timezone' then 64
              when key_name='locale' then 35
            end
        ) then
        raise invalid_parameter_value using
          message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
      end if;
    end if;
  end loop;

  if normalized_payload?'timezone' and not exists(
    select 1 from pg_catalog.pg_timezone_names timezone_item
    where timezone_item.name=normalized_payload->>'timezone'
  ) then
    raise invalid_parameter_value using
      message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
  end if;
  if normalized_payload?'locale'
    and normalized_payload->>'locale'
      !~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$' then
    raise invalid_parameter_value using
      message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
  end if;

  if p_payload?'institution_type_id' then
    if pg_catalog.jsonb_typeof(p_payload->'institution_type_id')<>'string'
      or pg_catalog.btrim(p_payload->>'institution_type_id')='' then
      raise invalid_parameter_value using
        message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
    end if;
    begin
      normalized_type_id:=
        pg_catalog.btrim(p_payload->>'institution_type_id')::uuid;
    exception when invalid_text_representation then
      raise invalid_parameter_value using
        message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
    end;
    normalized_payload:=normalized_payload||pg_catalog.jsonb_build_object(
      'institution_type_id',
      normalized_type_id::text
    );
  end if;

  if p_payload?'address' then
    if pg_catalog.jsonb_typeof(p_payload->'address')<>'object'
      or p_payload->'address'='{}'::jsonb then
      raise invalid_parameter_value using
        message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
    end if;
    select payload_key into unknown_key
    from pg_catalog.jsonb_object_keys(p_payload->'address') payload_key
    where not(payload_key=any(array[
      'country','state','city','district','street','number','complement','postal_code'
    ]::text[]))
    limit 1;
    if unknown_key is not null then
      raise invalid_parameter_value using
        message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
    end if;
    normalized_child:='{}'::jsonb;
    foreach key_name in array array[
      'country','state','city','district','street','number','complement','postal_code'
    ]::text[] loop
      if (p_payload->'address')?key_name then
        if pg_catalog.jsonb_typeof(p_payload->'address'->key_name)
          not in('string','null')
          or (key_name='country' and (
            pg_catalog.jsonb_typeof(p_payload->'address'->key_name)='null'
            or pg_catalog.btrim(p_payload->'address'->>key_name)=''
          )) then
          raise invalid_parameter_value using
            message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
        end if;
        normalized_child:=normalized_child||pg_catalog.jsonb_build_object(
          key_name,
          case
            when pg_catalog.jsonb_typeof(p_payload->'address'->key_name)='null'
              or pg_catalog.btrim(p_payload->'address'->>key_name)=''
              then 'null'::jsonb
            else pg_catalog.to_jsonb(
              pg_catalog.btrim(p_payload->'address'->>key_name))
          end
        );
        if pg_catalog.jsonb_typeof(normalized_child->key_name)='string'
          and (
            normalized_child->>key_name ~ U&'[\0001-\001f\007f]'
            or pg_catalog.octet_length(normalized_child->>key_name)>
              case
                when key_name='country' then 80
                when key_name in(
                  'state','city','district','street','complement'
                ) then 240
                when key_name in('number','postal_code') then 64
              end
          ) then
          raise invalid_parameter_value using
            message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
        end if;
        if key_name='country'
          and normalized_child->>key_name<>'Brasil' then
          raise invalid_parameter_value using
            message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
        end if;
        if key_name='postal_code'
          and pg_catalog.jsonb_typeof(normalized_child->key_name)='string'
          and normalized_child->>key_name !~ '^[0-9]{8}$' then
          raise invalid_parameter_value using
            message='invalid institution edit payload',detail='SAI_INVALID_ARGUMENT';
        end if;
      end if;
    end loop;
    normalized_payload:=normalized_payload||
      pg_catalog.jsonb_build_object('address',normalized_child);
  end if;

  return normalized_payload;
end
$_$;


ALTER FUNCTION "app_private"."superadmin_institution_edit_core_validate_v2"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_filter_array_v2"("p_filters" "jsonb", "p_key" "text", "p_max_items" integer, "p_allowed" "text"[], "p_require_uuid" boolean) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result_values text[];
begin
  if not p_filters ? p_key then
    return '{}'::text[];
  end if;
  if pg_catalog.jsonb_typeof(p_filters->p_key)<>'array'
    or pg_catalog.jsonb_array_length(p_filters->p_key)>p_max_items then
    raise invalid_parameter_value using
      message='invalid institution filter',detail='SAI_INVALID_ARGUMENT';
  end if;
  if exists(
    select 1
    from pg_catalog.jsonb_array_elements(p_filters->p_key) element(value)
    where pg_catalog.jsonb_typeof(value)<>'string'
      or pg_catalog.btrim(value#>>'{}')=''
      or pg_catalog.octet_length(value#>>'{}')>240
  ) then
    raise invalid_parameter_value using
      message='invalid institution filter',detail='SAI_INVALID_ARGUMENT';
  end if;

  select coalesce(
    pg_catalog.array_agg(pg_catalog.btrim(value#>>'{}') order by ordinal),
    '{}'::text[])
  into result_values
  from pg_catalog.jsonb_array_elements(p_filters->p_key)
    with ordinality element(value,ordinal);

  if exists(
    select 1 from pg_catalog.unnest(result_values) value
    group by pg_catalog.lower(value) having count(*)>1
  ) or (p_allowed is not null and exists(
    select 1 from pg_catalog.unnest(result_values) value
    where not(value=any(p_allowed))
  )) then
    raise invalid_parameter_value using
      message='invalid institution filter',detail='SAI_INVALID_ARGUMENT';
  end if;

  if p_require_uuid then
    begin
      select coalesce(pg_catalog.array_agg(value::uuid::text order by ordinal),
        '{}'::text[])
      into result_values
      from pg_catalog.unnest(result_values) with ordinality element(value,ordinal);
    exception when invalid_text_representation then
      raise invalid_parameter_value using
        message='invalid institution filter',detail='SAI_INVALID_ARGUMENT';
    end;
    if exists(
      select 1 from pg_catalog.unnest(result_values) value
      group by value having count(*)>1
    ) then
      raise invalid_parameter_value using
        message='invalid institution filter',detail='SAI_INVALID_ARGUMENT';
    end if;
  end if;
  return result_values;
end
$$;


ALTER FUNCTION "app_private"."superadmin_institution_filter_array_v2"("p_filters" "jsonb", "p_key" "text", "p_max_items" integer, "p_allowed" "text"[], "p_require_uuid" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_filter_options_payload_v2"("p_states" "text"[], "p_cities" "text"[], "p_scope_kind" "text", "p_scope_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_states text[];
  normalized_cities text[];
  result_payload jsonb;
begin
  if p_states is null or p_cities is null
    or pg_catalog.cardinality(p_states)>20
    or pg_catalog.cardinality(p_cities)>20
    or p_scope_kind not in('platform','institution')
    or (p_scope_kind='institution' and p_scope_institution_id is null)
    or exists(select 1 from pg_catalog.unnest(p_states) value
      where value is null or pg_catalog.btrim(value)=''
        or pg_catalog.octet_length(value)>240)
    or exists(select 1 from pg_catalog.unnest(p_cities) value
      where value is null or pg_catalog.btrim(value)=''
        or pg_catalog.octet_length(value)>240) then
    raise invalid_parameter_value using
      message='invalid institution options argument',detail='SAI_INVALID_ARGUMENT';
  end if;
  select coalesce(pg_catalog.array_agg(pg_catalog.btrim(value)),'{}'::text[])
    into normalized_states from pg_catalog.unnest(p_states) value;
  select coalesce(pg_catalog.array_agg(pg_catalog.btrim(value)),'{}'::text[])
    into normalized_cities from pg_catalog.unnest(p_cities) value;
  if exists(select 1 from pg_catalog.unnest(normalized_states) value
      group by pg_catalog.lower(value) having count(*)>1)
    or exists(select 1 from pg_catalog.unnest(normalized_cities) value
      group by pg_catalog.lower(value) having count(*)>1) then
    raise invalid_parameter_value using
      message='invalid institution options argument',detail='SAI_INVALID_ARGUMENT';
  end if;

  with visible as materialized(
    select directory.* from public.institution_directory directory
    where p_scope_kind='platform' or directory.id=p_scope_institution_id
  ),
  plan_options as(
    select distinct plan_id::text id,plan_name label from visible
    where plan_id is not null and plan_name is not null
  ),type_options as(
    select distinct institution_type_id::text id,type_name label from visible
    where institution_type_id is not null and type_name is not null
  ),state_options as(
    select distinct pg_catalog.btrim(state) id,pg_catalog.btrim(state) label
    from visible where state is not null and pg_catalog.btrim(state)<>''
  ),city_options as(
    select distinct pg_catalog.btrim(city) id,pg_catalog.btrim(city) label
    from visible
    where pg_catalog.cardinality(normalized_states)>0
      and pg_catalog.btrim(state)=any(normalized_states)
      and city is not null and pg_catalog.btrim(city)<>''
  ),district_options as(
    select distinct pg_catalog.btrim(district) id,pg_catalog.btrim(district) label
    from visible
    where pg_catalog.cardinality(normalized_cities)>0
      and pg_catalog.btrim(city)=any(normalized_cities)
      and (pg_catalog.cardinality(normalized_states)=0
        or pg_catalog.btrim(state)=any(normalized_states))
      and district is not null and pg_catalog.btrim(district)<>''
  )
  select pg_catalog.jsonb_build_object(
    'plans',coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('id',id,'label',label) order by label,id)
      from plan_options),'[]'::jsonb),
    'types',coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('id',id,'label',label) order by label,id)
      from type_options),'[]'::jsonb),
    'states',coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('id',id,'label',label) order by label,id)
      from state_options),'[]'::jsonb),
    'cities',coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('id',id,'label',label) order by label,id)
      from city_options),'[]'::jsonb),
    'districts',coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('id',id,'label',label) order by label,id)
      from district_options),'[]'::jsonb))
  into result_payload;
  return result_payload;
end
$$;


ALTER FUNCTION "app_private"."superadmin_institution_filter_options_payload_v2"("p_states" "text"[], "p_cities" "text"[], "p_scope_kind" "text", "p_scope_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_institution_identity_download_descriptor"("p_media_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare media public.institution_identity_media%rowtype;
begin
  select * into media from public.institution_identity_media where id=p_media_id;
  if media.id is null or media.state<>'active' then
    raise no_data_found using message='institution identity media not found';
  end if;
  perform app_private.assert_institution_identity_access(media.institution_id);
  return jsonb_build_object(
    'media_id',media.id,'bucket',media.bucket_id,'storage_path',media.storage_path,
    'mime_type',media.mime_type,'size_bytes',media.size_bytes
  );
end
$$;


