CREATE OR REPLACE FUNCTION "app_private"."superadmin_internal_error_envelope"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select pg_catalog.jsonb_build_object('ok',false,'data',null,'error',
    pg_catalog.jsonb_build_object('code',case when p_code in(
      'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
      'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED',
      'SAI_MFA_REQUIRED','SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE',
      'SAI_INVALID_ARGUMENT') then p_code else 'SAI_INTERNAL_ERROR' end,
      'message',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID')
          then 'Autenticação necessária.'
        when p_code='SAI_MFA_REQUIRED' then 'Confirme o segundo fator.'
        when p_code='SAI_INVALID_ARGUMENT' then 'Revise os dados enviados.'
        when p_code in('SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE')
          then 'O estado mudou. Recarregue e tente novamente.'
        when p_code like 'SAI_%DENIED' or p_code like 'SAI_MEMBERSHIP_%'
          then 'Acesso não autorizado.'
        else 'Não foi possível concluir a operação.' end,
      'correlation_id',p_correlation_id,
      'http_status',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 401
        when p_code='SAI_INVALID_ARGUMENT' then 400
        when p_code in('SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE') then 409
        when p_code in('SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
          'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED') then 403
        else 500 end))
$$;


ALTER FUNCTION "app_private"."superadmin_internal_error_envelope"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_internal_user_create_check"("p_draft" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare target_role public.platform_roles%rowtype; scope_id uuid;
  draft_email text := lower(btrim(p_draft#>>'{identity,professional_email}'));
  draft_cpf text := regexp_replace(coalesce(p_draft#>>'{identity,cpf}',''),'\D','','g');
begin
  if not app_private.superadmin_internal_user_draft_valid(p_draft) then
    raise invalid_parameter_value using message='invalid internal user command';
  end if;
  select * into target_role from public.platform_roles
    where id=(p_draft->>'profile_id')::uuid and status='active';
  if target_role.id is null then
    raise invalid_parameter_value using message='unknown or inactive profile';
  end if;
  if target_role.code='owner' and p_draft->>'scope'<>'platform' then
    raise check_violation using message='owner requires platform scope';
  end if;
  if draft_cpf !~ '^[0-9]{11}$' or draft_email not like '%@%' then
    raise invalid_parameter_value using message='invalid internal user command';
  end if;
  if exists(select 1 from app_private.superadmin_internal_profiles p where p.cpf=draft_cpf) then
    raise unique_violation using message='internal user cpf already registered', detail='SAI_CONFLICT';
  end if;
  if exists(select 1 from app_private.superadmin_internal_profiles p where p.professional_email=draft_email) then
    raise unique_violation using message='internal user email already registered', detail='SAI_CONFLICT';
  end if;
  if p_draft->>'scope'='limited' then
    for scope_id in select value::uuid from jsonb_array_elements_text(p_draft->'scope_ids') loop
      if not exists(select 1 from public.institutions i where i.id=scope_id) then
        raise foreign_key_violation using message='unknown institution scope';
      end if;
    end loop;
  end if;
end $_$;


ALTER FUNCTION "app_private"."superadmin_internal_user_create_check"("p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_internal_user_denial_code"("p_sqlstate" "text", "p_detail" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_detail in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
      'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED',
      'SAI_MFA_REQUIRED','SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE') then p_detail
    when p_sqlstate='40001' then 'SAI_CONCURRENT_CHANGE'
    when p_sqlstate in('22023','23503','23514','22P02','22001') then 'SAI_INVALID_INPUT'
    when p_sqlstate in('P0002','42501') then 'SAI_PERMISSION_DENIED'
    else 'SAI_INTERNAL_ERROR' end
$$;


ALTER FUNCTION "app_private"."superadmin_internal_user_denial_code"("p_sqlstate" "text", "p_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_internal_user_draft_valid"("p_draft" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_draft is not null and pg_column_size(p_draft)<=32768
    and jsonb_typeof(p_draft)='object' and jsonb_typeof(p_draft->'identity')='object'
    and (select array_agg(key order by key) from jsonb_object_keys(p_draft) key)
      = array['identity','profile_id','scope','scope_ids']::text[]
    and (select array_agg(key order by key) from jsonb_object_keys(p_draft->'identity') key)
      = array['additional_phone','birth_date','city','complement','country','cpf','department',
        'display_name','first_name','internal_function','job_title','last_name','mobile',
        'neighborhood','number','postal_code','professional_email','professional_notes','state',
        'street']::text[]
    and jsonb_typeof(p_draft->'profile_id')='string'
    and p_draft->>'scope' in('platform','limited')
    and jsonb_typeof(p_draft->'scope_ids')='array'
    and jsonb_array_length(p_draft->'scope_ids')<=100
    and (select count(*)=count(distinct value) from jsonb_array_elements_text(p_draft->'scope_ids'))
    and (p_draft->>'scope'='platform' or jsonb_array_length(p_draft->'scope_ids')>=1)
$$;


ALTER FUNCTION "app_private"."superadmin_internal_user_draft_valid"("p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_internal_user_error_envelope"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select pg_catalog.jsonb_build_object('ok',false,'data',null,'error',
    pg_catalog.jsonb_build_object(
      'code',case when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID',
        'SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED',
        'SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED','SAI_LAST_OWNER_PROTECTED',
        'SAI_CONCURRENT_CHANGE','SAI_INVALID_INPUT') then p_code else 'SAI_INTERNAL_ERROR' end,
      'message',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 'Autenticação necessária.'
        when p_code='SAI_MFA_REQUIRED' then 'Confirme o segundo fator.'
        when p_code='SAI_INVALID_INPUT' then 'Revise os dados enviados.'
        when p_code in('SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE')
          then 'O estado mudou. Recarregue e tente novamente.'
        when p_code like 'SAI_%DENIED' or p_code like 'SAI_MEMBERSHIP_%'
          then 'Acesso não autorizado.'
        else 'Não foi possível concluir a operação.' end,
      'correlation_id',p_correlation_id,
      'http_status',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 401
        when p_code in('SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE') then 409
        when p_code='SAI_INVALID_INPUT' then 422
        when p_code in('SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
          'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED') then 403
        else 500 end))
$$;


ALTER FUNCTION "app_private"."superadmin_internal_user_error_envelope"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_internal_user_projection"("p_identity_id" "uuid", "p_include_sensitive" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'id',identity_record.id,
    'version',greatest(profile_record.version,membership_record.version,auth_link.version),
    'identity',pg_catalog.jsonb_build_object(
      'id',identity_record.id,'first_name',profile_record.first_name,
      'last_name',profile_record.last_name,'display_name',profile_record.display_name,
      'birth_date',case when p_include_sensitive then profile_record.birth_date else null end,
      'cpf',case when p_include_sensitive then profile_record.cpf
        else repeat('0',9)||right(profile_record.cpf,2) end,
      'professional_email',case when p_include_sensitive then profile_record.professional_email
        else left(profile_record.professional_email,1)||'***@'||split_part(profile_record.professional_email,'@',2) end,
      'mobile',case when p_include_sensitive then profile_record.mobile
        when profile_record.mobile='' then '' else repeat('0',7)||right(profile_record.mobile,4) end,
      'additional_phone',case when p_include_sensitive then profile_record.additional_phone else '' end,
      'job_title',profile_record.job_title,
      'department',profile_record.department,'internal_function',profile_record.internal_function,
      'professional_notes',case when p_include_sensitive then profile_record.professional_notes else '' end,
      'postal_code',case when p_include_sensitive then profile_record.postal_code else '' end,
      'street',case when p_include_sensitive then profile_record.street else '' end,
      'number',case when p_include_sensitive then profile_record.address_number else '' end,
      'complement',case when p_include_sensitive then profile_record.complement else '' end,
      'neighborhood',case when p_include_sensitive then profile_record.neighborhood else '' end,
      'city',case when p_include_sensitive then profile_record.city else '' end,
      'state',case when p_include_sensitive then profile_record.state else '' end,
      'country',case when p_include_sensitive then profile_record.country else 'Brasil' end),
    'credential',pg_catalog.jsonb_build_object('status',case auth_link.status
      when 'active' then 'active' when 'suspended' then 'blocked' else 'noAccess' end),
    'memberships',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'id',membership_record.id,'status',membership_record.status,
      'scope',case when membership_record.scope_kind='platform' then 'platform' else 'limited' end,
      'scope_ids',coalesce((select pg_catalog.jsonb_agg(scope_record.institution_id order by institution.public_name)
        from app_private.superadmin_internal_membership_scopes scope_record
        join public.institutions institution on institution.id=scope_record.institution_id
        where scope_record.membership_id=membership_record.id),
        case when membership_record.scope_institution_id is null then '[]'::jsonb
          else pg_catalog.jsonb_build_array(membership_record.scope_institution_id) end),
      'scope_names',coalesce((select pg_catalog.jsonb_agg(institution.public_name order by institution.public_name)
        from app_private.superadmin_internal_membership_scopes scope_record
        join public.institutions institution on institution.id=scope_record.institution_id
        where scope_record.membership_id=membership_record.id),
        case when membership_record.scope_institution_id is null then '[]'::jsonb
          else pg_catalog.jsonb_build_array((select institution.public_name
            from public.institutions institution
            where institution.id=membership_record.scope_institution_id)) end),
      'started_at',membership_record.created_at,'ended_at',coalesce(membership_record.revoked_at,membership_record.suspended_at),
      'profile',pg_catalog.jsonb_build_object(
        'id',role_record.id,'name',role_record.name,'code',role_record.code,
        'allows_global',role_record.max_scope_kind='platform','active',role_record.status='active',
        'permissions',coalesce((select pg_catalog.jsonb_agg(permission_record.code order by permission_record.code)
          from public.platform_role_permissions role_permission
          join public.platform_permissions permission_record on permission_record.id=role_permission.permission_id
          where role_permission.role_id=role_record.id and role_permission.status='active'
            and role_permission.revoked_at is null and role_permission.effect='allow'
            and permission_record.status='active'),'[]'::jsonb)))),
    'invitation',pg_catalog.jsonb_build_object(
      'id',auth_link.id,'email',case when p_include_sensitive then profile_record.professional_email
        else left(profile_record.professional_email,1)||'***@'||split_part(profile_record.professional_email,'@',2) end,
      'status','accepted',
      'attempts',1,'updated_at',auth_link.created_at),
    'history',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'at',audit_record.occurred_at,'title',case audit_record.action_code
          when 'superadmin.internal-users.update' then 'Cadastro atualizado'
          when 'superadmin.internal-users.suspend' then 'Acesso suspenso'
          when 'superadmin.internal-users.reactivate' then 'Acesso reativado'
          when 'superadmin.internal-users.revoke' then 'Vínculo revogado'
          else 'Alteração de acesso' end,
        'detail',coalesce(audit_record.reason_code,'Operação auditada.')) order by audit_record.occurred_at)
      from audit.audit_logs audit_record
      where audit_record.object_type='superadmin_internal_identity'
        and audit_record.object_id=identity_record.id),'[]'::jsonb))
  from app_private.superadmin_internal_identities identity_record
  join app_private.superadmin_internal_profiles profile_record
    on profile_record.internal_identity_id=identity_record.id
  join lateral(select membership_item.*
    from app_private.superadmin_internal_memberships membership_item
    where membership_item.internal_identity_id=identity_record.id
    order by (membership_item.status='active') desc,membership_item.created_at desc limit 1
  ) membership_record on true
  join public.platform_roles role_record on role_record.id=membership_record.platform_role_id
  join lateral(select auth_item.*
    from app_private.superadmin_internal_auth_links auth_item
    where auth_item.internal_identity_id=identity_record.id
    order by (auth_item.status='active') desc,auth_item.created_at desc limit 1
  ) auth_link on true
  where identity_record.id=p_identity_id
$$;


ALTER FUNCTION "app_private"."superadmin_internal_user_projection"("p_identity_id" "uuid", "p_include_sensitive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_internal_user_target_allowed"("p_ctx" "app_private"."superadmin_internal_context", "p_internal_identity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_internal_identity_id is not null and exists(
    select 1 from app_private.superadmin_internal_profiles profile_record
    join lateral(select membership_item.*
      from app_private.superadmin_internal_memberships membership_item
      where membership_item.internal_identity_id=profile_record.internal_identity_id
      order by (membership_item.status='active') desc,membership_item.created_at desc limit 1
    ) membership_record on true
    join lateral(select auth_item.*
      from app_private.superadmin_internal_auth_links auth_item
      where auth_item.internal_identity_id=profile_record.internal_identity_id
      order by (auth_item.status='active') desc,auth_item.created_at desc limit 1
    ) auth_link on true
    where profile_record.internal_identity_id=p_internal_identity_id
      and (p_ctx.scope_kind='platform' or (
        membership_record.scope_kind='institution' and (
          membership_record.scope_institution_id=p_ctx.scope_institution_id or exists(
            select 1 from app_private.superadmin_internal_membership_scopes scope_record
            where scope_record.membership_id=membership_record.id
              and scope_record.institution_id=p_ctx.scope_institution_id))))
  )
$$;


ALTER FUNCTION "app_private"."superadmin_internal_user_target_allowed"("p_ctx" "app_private"."superadmin_internal_context", "p_internal_identity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_invite_directory_payload_v2"("p_search" "text", "p_statuses" "text"[], "p_channels" "text"[], "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_group_ids" "uuid"[], "p_profile_ids" "uuid"[], "p_created_from" timestamp with time zone, "p_created_to" timestamp with time zone, "p_limit" integer, "p_offset" integer, "p_sort_ascending" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  if length(coalesce(p_search,''))>120
    or p_limit not in(8,11,20,50,100)
    or p_offset<0 or p_offset>10000
    or not(coalesce(p_statuses,'{}'::text[])
      <@ array['pending','accepted','expired','revoked']::text[])
    or not(coalesce(p_channels,'{}'::text[]) <@ array['email','link']::text[])
    or p_created_from>p_created_to then
    raise invalid_parameter_value using
      message='invalid invitation directory query',detail='SAI_INVALID_ARGUMENT';
  end if;

  with filtered as(
    select invitation.id,invitation.created_at,
      case when invitation.invitation_state='pending' and invitation.expires_at<=now()
        then 'expired' else invitation.invitation_state::text end as effective_status
    from public.invitations invitation
    join public.institutions institution on institution.id=invitation.institution_id
    left join public.units unit_record on unit_record.id=invitation.unit_id
    left join public.groups group_record on group_record.id=invitation.group_id
    left join public.institution_roles profile_record on profile_record.id=invitation.profile_id
    where(p_search is null or btrim(p_search)=''
      or institution.public_name ilike '%'||btrim(p_search)||'%'
      or coalesce(unit_record.name,'') ilike '%'||btrim(p_search)||'%'
      or coalesce(group_record.name,'') ilike '%'||btrim(p_search)||'%'
      or coalesce(profile_record.name,invitation.role_code,'') ilike '%'||btrim(p_search)||'%'
      or coalesce(invitation.masked_destination,'') ilike '%'||btrim(p_search)||'%')
      and(p_institution_ids is null or invitation.institution_id=any(p_institution_ids))
      and(p_unit_ids is null or invitation.unit_id=any(p_unit_ids))
      and(p_group_ids is null or invitation.group_id=any(p_group_ids))
      and(p_profile_ids is null or invitation.profile_id=any(p_profile_ids))
      and(p_channels is null or invitation.channels&&p_channels)
      and(p_created_from is null or invitation.created_at>=p_created_from)
      and(p_created_to is null or invitation.created_at<=p_created_to)
  ), status_filtered as(
    select * from filtered
    where p_statuses is null or effective_status=any(p_statuses)
  ), page_rows as(
    select * from status_filtered
    order by
      case when p_sort_ascending then created_at end asc,
      case when p_sort_ascending then id end asc,
      case when not p_sort_ascending then created_at end desc,
      case when not p_sort_ascending then id end desc
    limit p_limit offset p_offset
  )
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(
      app_private.superadmin_invite_payload_v2(page_rows.id)
      order by case when p_sort_ascending then page_rows.created_at end asc,
        case when not p_sort_ascending then page_rows.created_at end desc
    ) from page_rows),'[]'::jsonb),
    'total_count',(select count(*) from status_filtered)
  ) into result;
  return result;
end
$$;


ALTER FUNCTION "app_private"."superadmin_invite_directory_payload_v2"("p_search" "text", "p_statuses" "text"[], "p_channels" "text"[], "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_group_ids" "uuid"[], "p_profile_ids" "uuid"[], "p_created_from" timestamp with time zone, "p_created_to" timestamp with time zone, "p_limit" integer, "p_offset" integer, "p_sort_ascending" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_invite_error_envelope_v2"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'ok',false,
    'data',null,
    'error',jsonb_build_object(
      'code',case when p_code in(
        'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
        'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED',
        'SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED','SAI_CONCURRENT_CHANGE',
        'SAI_INVALID_ARGUMENT'
      ) then p_code else 'SAI_INTERNAL_ERROR' end,
      'message',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID')
          then 'Autenticação necessária.'
        when p_code='SAI_MFA_REQUIRED' then 'Confirme o segundo fator.'
        when p_code='SAI_CONCURRENT_CHANGE'
          then 'O estado mudou. Recarregue e tente novamente.'
        when p_code='SAI_INVALID_ARGUMENT' then 'Revise os dados informados.'
        when p_code like 'SAI_%DENIED' or p_code like 'SAI_MEMBERSHIP_%'
          then 'Acesso não autorizado.'
        else 'Não foi possível concluir a operação.' end,
      'correlation_id',p_correlation_id,
      'http_status',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 401
        when p_code='SAI_CONCURRENT_CHANGE' then 409
        when p_code='SAI_INVALID_ARGUMENT' then 422
        when p_code in(
          'SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
          'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED'
        ) then 403 else 500 end
    )
  )
$$;


ALTER FUNCTION "app_private"."superadmin_invite_error_envelope_v2"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_invite_options_payload_v2"("p_search" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  if length(coalesce(p_search,''))>120 or p_limit<1 or p_limit>100 then
    raise invalid_parameter_value using
      message='invalid invitation options query',detail='SAI_INVALID_ARGUMENT';
  end if;
  if p_unit_id is not null and not exists(
    select 1 from public.units unit_record
    where unit_record.id=p_unit_id and unit_record.institution_id=p_institution_id
  ) or p_group_id is not null and not exists(
    select 1 from public.groups group_record
    where group_record.id=p_group_id and group_record.unit_id=p_unit_id
      and group_record.institution_id=p_institution_id
  ) then
    raise insufficient_privilege using
      message='invitation options denied',detail='SAI_PERMISSION_DENIED';
  end if;

  select jsonb_build_object(
    'scopes',coalesce((
      select jsonb_agg(scope_record.payload order by scope_record.label)
      from(
        select institution.public_name label,jsonb_build_object(
          'scope_kind','institution','institution_id',institution.id,
          'unit_id',null,'group_id',null,'label',institution.public_name
        ) payload
        from public.institutions institution
        where institution.status='active'
          and(p_institution_id is null or institution.id=p_institution_id)
          and(p_search is null or institution.public_name ilike '%'||btrim(p_search)||'%')
        union all
        select unit_record.name,jsonb_build_object(
          'scope_kind','unit','institution_id',unit_record.institution_id,
          'unit_id',unit_record.id,'group_id',null,'label',unit_record.name
        )
        from public.units unit_record
        where unit_record.status='active'
          and(p_institution_id is null or unit_record.institution_id=p_institution_id)
          and(p_unit_id is null or unit_record.id=p_unit_id)
          and(p_search is null or unit_record.name ilike '%'||btrim(p_search)||'%')
        union all
        select group_record.name,jsonb_build_object(
          'scope_kind','group','institution_id',group_record.institution_id,
          'unit_id',group_record.unit_id,'group_id',group_record.id,
          'label',group_record.name
        )
        from public.groups group_record
        where group_record.status='active'
          and(p_institution_id is null or group_record.institution_id=p_institution_id)
          and(p_unit_id is null or group_record.unit_id=p_unit_id)
          and(p_group_id is null or group_record.id=p_group_id)
          and(p_search is null or group_record.name ilike '%'||btrim(p_search)||'%')
        limit p_limit
      ) scope_record
    ),'[]'::jsonb),
    'profiles',coalesce((
      select jsonb_agg(jsonb_build_object(
        'profile_id',profile_record.id,'label',profile_record.name,
        'institution_id',coalesce(profile_record.institution_id,p_institution_id),
        'unit_id',null,'group_id',null
      ) order by profile_record.name)
      from(
        select profile.*
        from public.institution_roles profile
        where profile.status='active'
          and p_institution_id is not null
          and(profile.institution_id=p_institution_id
            or profile.institution_id is null)
          and(p_search is null or profile.name ilike '%'||btrim(p_search)||'%')
        order by profile.name,profile.id
        limit p_limit
      ) profile_record
    ),'[]'::jsonb),
    'recipients',coalesce((
      select jsonb_agg(jsonb_build_object(
        'person_id',person_record.id,'label',person_record.display_name,
        'masked_email',contact_record.masked_value
      ) order by person_record.display_name)
      from(
        select person.*
        from public.people person
        where person.status='active' and person.person_type='adult'
          and(p_search is null or person.display_name ilike '%'||btrim(p_search)||'%')
        order by person.display_name,person.id
        limit p_limit
      ) person_record
      left join lateral(
        select contact.masked_value
        from public.person_contacts contact
        where contact.person_id=person_record.id
          and contact.contact_type='email' and contact.status='active'
        order by contact.verified_at desc nulls last,contact.created_at desc limit 1
      ) contact_record on true
    ),'[]'::jsonb)
  ) into result;
  return result;
end
$$;


ALTER FUNCTION "app_private"."superadmin_invite_options_payload_v2"("p_search" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_invite_payload_v2"("p_invite_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id',invitation.id,
    'scope_kind',invitation.scope_kind,
    'institution_id',invitation.institution_id,
    'unit_id',invitation.unit_id,
    'group_id',invitation.group_id,
    'scope_label',concat_ws(' · ',institution.public_name,unit_record.name,group_record.name),
    'profile_id',coalesce(invitation.profile_id::text,'legacy'),
    'profile_label',coalesce(profile_record.name,invitation.role_code,'Perfil legado'),
    'recipient_label',case when invitation.target_person_id is not null
      then 'Pessoa vinculada' end,
    'recipient_masked',invitation.masked_destination,
    'channels',to_jsonb(coalesce(invitation.channels,'{}'::text[])),
    'status',case
      when invitation.invitation_state='pending' and invitation.expires_at<=now()
        then 'expired'
      else invitation.invitation_state::text end,
    'issuer',case
      when invitation.invited_by_internal_identity_id is not null then
        jsonb_build_object('kind','superadmin_internal','display','Usuário interno')
      when invitation.invited_by is not null then
        jsonb_build_object('kind','legacy_person','display','Emissor institucional')
      else jsonb_build_object('kind','unknown','display','Emissor não informado') end,
    'created_at',invitation.created_at,
    'expires_at',invitation.expires_at,
    'accepted_at',invitation.accepted_at,
    'revoked_at',invitation.revoked_at,
    'email_delivery_status','not_requested',
    'management_version',coalesce(invitation.version,0),
    'timeline',jsonb_build_array(jsonb_build_object(
      'label','Convite criado','occurred_at',invitation.created_at
    ))
      || case when invitation.last_sent_at is not null then jsonb_build_array(
        jsonb_build_object('label','Convite reenviado','occurred_at',invitation.last_sent_at)
      ) else '[]'::jsonb end
      || case when invitation.accepted_at is not null then jsonb_build_array(
        jsonb_build_object('label','Convite aceito','occurred_at',invitation.accepted_at)
      ) else '[]'::jsonb end
      || case when invitation.revoked_at is not null then jsonb_build_array(
        jsonb_build_object('label','Convite revogado','occurred_at',invitation.revoked_at)
      ) else '[]'::jsonb end
  )
  from public.invitations invitation
  join public.institutions institution on institution.id=invitation.institution_id
  left join public.units unit_record on unit_record.id=invitation.unit_id
  left join public.groups group_record on group_record.id=invitation.group_id
  left join public.institution_roles profile_record on profile_record.id=invitation.profile_id
  where invitation.id=p_invite_id
$$;


ALTER FUNCTION "app_private"."superadmin_invite_payload_v2"("p_invite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_list_import_export_jobs"("p_domains" "text"[], "p_states" "text"[], "p_formats" "text"[], "p_search" "text", "p_created_from" timestamp with time zone, "p_created_to" timestamp with time zone, "p_before_created_at" timestamp with time zone, "p_before_job_id" "uuid", "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  normalized_search text := nullif(btrim(p_search), '');
  escaped_search text;
begin
  actor := app_private.assert_import_export_hub_actor();
  if p_page_size not between 1 and 100
    or (p_domains is not null and exists (
      select 1 from unnest(p_domains) domain_name where domain_name <> 'units'
    ))
    or (p_states is not null and exists (
      select 1 from unnest(p_states) state_name
      where state_name not in ('PENDENTE','PROCESSANDO','SUCESSO','REJEICAO','ERRO')
    ))
    or (p_formats is not null and exists (
      select 1 from unnest(p_formats) format_name where format_name not in ('csv','xlsx')
    ))
    or (normalized_search is not null and (
      char_length(normalized_search) > 120 or normalized_search ~ '[[:cntrl:]]'
    ))
    or (p_created_from is not null and p_created_to is not null
      and p_created_from > p_created_to)
  then
    raise invalid_parameter_value using message = 'invalid import/export list filters';
  end if;

  escaped_search := case when normalized_search is null then null else
    replace(replace(replace(normalized_search, chr(92), chr(92) || chr(92)),
      '%', chr(92) || '%'), '_', chr(92) || '_')
  end;

  return (
    with authorized as materialized (
      select job.id, job.target_domain, job.source_format, job.processing_state,
        job.summary, job.created_at, job.started_at, job.finished_at,
        source_file.file_name,
        result_record.created_count, result_record.updated_count,
        result_record.linked_count, result_record.ignored_count,
        result_record.rejected_count
      from public.import_jobs job
      left join public.import_results result_record on result_record.import_job_id = job.id
      left join lateral (
        select file_record.file_name
        from public.import_files file_record
        where file_record.import_job_id = job.id
        order by file_record.uploaded_at desc, file_record.id desc
        limit 1
      ) source_file on true
      where job.created_by = actor
        and job.target_domain in ('units', 'units_export')
        and app_private.can_access_import_export_job(job.target_domain)
        and (p_domains is null or cardinality(p_domains) = 0
          or app_private.import_export_job_domain(job.target_domain) = any(p_domains))
        and (p_states is null or cardinality(p_states) = 0
          or job.processing_state::text = any(p_states))
        and (p_formats is null or cardinality(p_formats) = 0
          or job.source_format = any(p_formats))
        and (p_created_from is null or job.created_at >= p_created_from)
        and (p_created_to is null or job.created_at <= p_created_to)
        and (escaped_search is null
          or job.target_domain ilike '%' || escaped_search || '%' escape chr(92)
          or job.source_format ilike '%' || escaped_search || '%' escape chr(92)
          or source_file.file_name ilike '%' || escaped_search || '%' escape chr(92))
    ), windowed as materialized (
      select * from authorized
      where p_before_created_at is null or (created_at, id) < (
        p_before_created_at,
        coalesce(p_before_job_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)
      )
      order by created_at desc, id desc
      limit p_page_size + 1
    ), visible as materialized (
      select * from windowed order by created_at desc, id desc limit p_page_size
    ), last_visible as (
      select created_at, id from visible order by created_at asc, id asc limit 1
    )
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'job_id', visible.id,
        'domain', app_private.import_export_job_domain(visible.target_domain),
        'direction', app_private.import_export_job_direction(visible.target_domain),
        'format', visible.source_format,
        'file_name', visible.file_name,
        'state', visible.processing_state,
        'progress', case visible.processing_state
          when 'PENDENTE' then coalesce((visible.summary ->> 'progress')::integer, 0)
          when 'PROCESSANDO' then coalesce((visible.summary ->> 'progress')::integer, 50)
          else 100
        end,
        'created_at', visible.created_at,
        'started_at', visible.started_at,
        'finished_at', visible.finished_at,
        'summary', jsonb_strip_nulls(jsonb_build_object(
          'phase', visible.summary ->> 'phase',
          'valid_count', visible.summary -> 'valid_count',
          'rejected_count', visible.summary -> 'rejected_count',
          'row_count', visible.summary -> 'row_count'
        )),
        'result', jsonb_strip_nulls(jsonb_build_object(
          'created_count', visible.created_count,
          'updated_count', visible.updated_count,
          'linked_count', visible.linked_count,
          'ignored_count', visible.ignored_count,
          'rejected_count', visible.rejected_count
        ))
      ) order by visible.created_at desc, visible.id desc), '[]'::jsonb),
      'total_count', (select count(*) from authorized),
      'has_more', (select count(*) from windowed) > p_page_size,
      'next_cursor', case when (select count(*) from windowed) > p_page_size
        then (select jsonb_build_object('created_at', created_at, 'job_id', id)
          from last_visible)
        else null
      end
    ) from visible
  );
end;
$$;


ALTER FUNCTION "app_private"."superadmin_list_import_export_jobs"("p_domains" "text"[], "p_states" "text"[], "p_formats" "text"[], "p_search" "text", "p_created_from" timestamp with time zone, "p_created_to" timestamp with time zone, "p_before_created_at" timestamp with time zone, "p_before_job_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_location_locked_v2"("p_context" "app_private"."superadmin_internal_context", "p_location_id" "uuid") RETURNS "public"."activity_locations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target public.activity_locations%rowtype;
begin
  if p_location_id is null then
    raise invalid_parameter_value using message='location id required',detail='SAI_INVALID_ARGUMENT';
  end if;
  select l.* into target from public.activity_locations l
    where l.id=p_location_id
      and p_context.platform_role_code='owner'
      and (p_context.scope_kind='platform'
        or (p_context.scope_kind='institution' and p_context.scope_institution_id=l.institution_id))
    for update;
  if not found then
    raise insufficient_privilege using message='location access denied',detail='SAI_PERMISSION_DENIED';
  end if;
  perform app_private.superadmin_location_owner_v2(p_context,target.scope_kind,target.institution_id,target.unit_id);
  return target;
end
$$;


ALTER FUNCTION "app_private"."superadmin_location_locked_v2"("p_context" "app_private"."superadmin_internal_context", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_location_name_available_v2"("p_location_id" "uuid", "p_scope_kind" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select not exists(
    select 1 from public.activity_locations l
    where l.id is distinct from p_location_id
      and l.status<>'archived'
      and l.institution_id=p_institution_id
      and lower(l.name)=lower(p_name)
      and ((p_scope_kind='unit' and l.unit_id=p_unit_id)
        or (p_scope_kind='institution' and l.unit_id is null)))
$$;


ALTER FUNCTION "app_private"."superadmin_location_name_available_v2"("p_location_id" "uuid", "p_scope_kind" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_location_owner_v2"("p_context" "app_private"."superadmin_internal_context", "p_scope_kind" "text", "p_institution_id" "uuid", "p_unit_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_context.internal_identity_id is null or p_context.platform_role_code is distinct from 'owner'
    or p_context.scope_kind is null or p_context.scope_kind not in('platform','institution')
    or p_scope_kind is null or p_scope_kind not in('institution','unit')
    or p_institution_id is null
    or (p_scope_kind='institution' and p_unit_id is not null)
    or (p_scope_kind='unit' and p_unit_id is null)
    or (p_context.scope_kind='institution' and p_context.scope_institution_id is distinct from p_institution_id) then
    raise insufficient_privilege using message='location access denied',detail='SAI_PERMISSION_DENIED';
  end if;
  perform 1 from public.institutions institution
    where institution.id=p_institution_id and institution.deleted_at is null for share;
  if not found then
    raise insufficient_privilege using message='location access denied',detail='SAI_PERMISSION_DENIED';
  end if;
  if p_scope_kind='unit' then
    perform 1 from public.units unit_record where unit_record.id=p_unit_id
      and unit_record.institution_id=p_institution_id and unit_record.status<>'archived' for share;
    if not found then
      raise insufficient_privilege using message='location access denied',detail='SAI_PERMISSION_DENIED';
    end if;
  end if;
end
$$;


ALTER FUNCTION "app_private"."superadmin_location_owner_v2"("p_context" "app_private"."superadmin_internal_context", "p_scope_kind" "text", "p_institution_id" "uuid", "p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_location_payload_v2"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('id',l.id,'scope_kind',l.scope_kind,
    'institution_id',l.institution_id,'unit_id',l.unit_id,'name',l.name,
    'description',l.description,'kind',l.kind,'floor',l.floor,'address',l.address,
    'visibility',l.visibility,'status',l.status,'management_version',l.management_version,
    'created_at',l.created_at,'updated_at',l.updated_at)
  from public.activity_locations l where l.id=p_location_id
$$;


ALTER FUNCTION "app_private"."superadmin_location_payload_v2"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_location_schedule_normalize_v2"("p_windows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare item jsonb; field text; numeric_value numeric; result jsonb;
begin
  if p_windows is null or jsonb_typeof(p_windows)<>'array' then
    raise invalid_parameter_value using message='invalid location schedule',detail='SAI_INVALID_ARGUMENT';
  end if;
  -- Ten windows a day is already more than a place is ever opened and closed.
  if jsonb_array_length(p_windows)>70 then
    raise invalid_parameter_value using message='location schedule too long',detail='SAI_INVALID_ARGUMENT';
  end if;
  for item in select value from jsonb_array_elements(p_windows) loop
    if jsonb_typeof(item)<>'object'
      or not(item ?& array['weekday','starts_minute','ends_minute'])
      or (select count(*) from jsonb_object_keys(item))<>3 then
      raise invalid_parameter_value using message='invalid location schedule window',detail='SAI_INVALID_ARGUMENT';
    end if;
    foreach field in array array['weekday','starts_minute','ends_minute'] loop
      if jsonb_typeof(item->field)<>'number' then
        raise invalid_parameter_value using message='invalid location schedule window',detail='SAI_INVALID_ARGUMENT';
      end if;
      numeric_value:=(item->>field)::numeric;
      if numeric_value<>trunc(numeric_value) then
        raise invalid_parameter_value using message='invalid location schedule window',detail='SAI_INVALID_ARGUMENT';
      end if;
    end loop;
    if (item->>'weekday')::integer<0 or (item->>'weekday')::integer>6
      or (item->>'starts_minute')::integer<0 or (item->>'ends_minute')::integer>1440
      or (item->>'starts_minute')::integer>=(item->>'ends_minute')::integer then
      raise invalid_parameter_value using message='invalid location schedule window',detail='SAI_INVALID_ARGUMENT';
    end if;
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object(
      'weekday',weekday,'starts_minute',starts_minute,'ends_minute',ends_minute)
      order by weekday,starts_minute),'[]'::jsonb)
    into result from (
      select (value->>'weekday')::integer weekday,(value->>'starts_minute')::integer starts_minute,
        (value->>'ends_minute')::integer ends_minute from jsonb_array_elements(p_windows)) parsed;
  -- Two windows that overlap on the same day mean the operator lost track of one of
  -- them; refusing is safer than merging something nobody asked to merge.
  if exists(select 1 from (
      select starts_minute,lag(ends_minute) over(partition by weekday order by starts_minute) previous_end
      from (select (value->>'weekday')::integer weekday,(value->>'starts_minute')::integer starts_minute,
              (value->>'ends_minute')::integer ends_minute from jsonb_array_elements(result)) ordered
    ) windowed where previous_end is not null and starts_minute<previous_end) then
    raise invalid_parameter_value using message='location schedule windows overlap',detail='SAI_INVALID_ARGUMENT';
  end if;
  return result;
end
$$;


ALTER FUNCTION "app_private"."superadmin_location_schedule_normalize_v2"("p_windows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_location_schedule_payload_v2"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('weekday',s.weekday,
      'starts_minute',s.starts_minute,'ends_minute',s.ends_minute)
      order by s.weekday,s.starts_minute),'[]'::jsonb)
  from public.activity_location_schedules s where s.location_id=p_location_id
$$;


ALTER FUNCTION "app_private"."superadmin_location_schedule_payload_v2"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_materialize_unit_export_from_edge"("p_export_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  job public.import_jobs%rowtype;
  actor_auth_user_id uuid;
  filters jsonb;
  view_data jsonb;
  page jsonb;
  item jsonb;
  page_items jsonb;
  page_offset integer := 0;
  item_ordinal bigint;
  sort_input text;
  sort_name text;
  uuid_regex constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  select *
  into job
  from public.import_jobs
  where id = p_export_job_id
  for update;

  if job.id is null or job.target_domain <> 'units_export' then
    raise no_data_found using message = 'unit export not found';
  end if;

  select auth_link.auth_user_id
  into actor_auth_user_id
  from public.person_auth_links auth_link
  where auth_link.person_id = job.created_by
    and auth_link.status = 'active'
    and auth_link.revoked_at is null
  order by auth_link.linked_at desc
  limit 1;

  if actor_auth_user_id is null then
    raise insufficient_privilege using message = 'unit export actor is not active';
  end if;

  perform pg_catalog.set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'sub', actor_auth_user_id::text,
      'role', 'authenticated',
      'aal', 'aal2'
    )::text,
    true
  );

  filters := coalesce(job.summary -> 'filters', '{}'::jsonb);
  view_data := coalesce(job.summary -> 'current_view', '{}'::jsonb);
  sort_input := coalesce(nullif(btrim(view_data ->> 'sort'), ''), 'name');
  sort_name := case sort_input
    when 'institution_type' then 'institution_type_name'
    when 'unit_type' then 'unit_type_name'
    when 'status' then 'unit_status'
    when 'plan' then 'plan_name'
    when 'groups' then 'groups_count'
    when 'activities' then 'activities_count'
    else sort_input
  end;
  if sort_name not in (
    'name',
    'institution_name',
    'institution_type_name',
    'unit_type_name',
    'unit_status',
    'plan_name',
    'groups_count',
    'activities_count',
    'updated_at'
  ) then
    sort_name := 'name';
  end if;

  if exists (
    select 1
    from app_private.unit_export_snapshot_rows
    where export_job_id = job.id
  ) then
    return app_private.unit_file_job_payload(job.id);
  end if;

  loop
    page := app_private.list_units_for_superadmin(
      filters ->> 'search',
      coalesce(array(
        select value::uuid
        from jsonb_array_elements_text(coalesce(filters -> 'institution_ids', '[]'::jsonb)) value
        where value ~* uuid_regex
      ), array[]::uuid[]),
      coalesce(array(
        select value::uuid
        from jsonb_array_elements_text(coalesce(filters -> 'institution_type_ids', '[]'::jsonb)) value
        where value ~* uuid_regex
      ), array[]::uuid[]),
      coalesce(array(
        select value::uuid
        from jsonb_array_elements_text(coalesce(filters -> 'unit_type_ids', '[]'::jsonb)) value
        where value ~* uuid_regex
      ), array[]::uuid[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(
          coalesce(filters -> 'unit_statuses', coalesce(filters -> 'statuses', '[]'::jsonb))
        ) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(coalesce(filters -> 'plan_ids', '[]'::jsonb)) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(coalesce(filters -> 'states', '[]'::jsonb)) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(coalesce(filters -> 'cities', '[]'::jsonb)) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(coalesce(filters -> 'districts', '[]'::jsonb)) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      sort_name,
      coalesce((view_data ->> 'sort_ascending')::boolean, true),
      page_offset,
      100
    );

    page_items := coalesce(page -> 'items', '[]'::jsonb);
    exit when jsonb_array_length(page_items) = 0;

    for item, item_ordinal in
      select value, ordinality
      from jsonb_array_elements(page_items) with ordinality
    loop
      insert into app_private.unit_export_snapshot_rows(
        export_job_id,
        ordinal,
        unit_id,
        row_payload
      ) values (
        job.id,
        page_offset + item_ordinal,
        (item ->> 'id')::uuid,
        item
      );
    end loop;

    page_offset := page_offset + jsonb_array_length(page_items);
    if page_offset > 50000 then
      raise program_limit_exceeded using message = 'unit export exceeds maximum row count';
    end if;
    exit when coalesce((page ->> 'has_more')::boolean, false) is false;
  end loop;

  update public.import_jobs
  set summary = summary || jsonb_build_object(
        'phase', 'snapshot_ready',
        'snapshot_row_count', page_offset
      ),
      updated_at = now()
  where id = job.id;

  return app_private.unit_file_job_payload(job.id);
end;
$_$;


ALTER FUNCTION "app_private"."superadmin_materialize_unit_export_from_edge"("p_export_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_medication_plan_detail"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  plan_row public.medication_plans;
  version_row public.medication_plan_versions;
begin
  actor := app_private.require_health_care_actor('medication.read');
  select * into plan_row
  from public.medication_plans
  where id = p_plan_id
    and app_private.health_care_scope_allowed(
      'medication.read', institution_id, unit_id, group_id, child_context_id);
  if plan_row.id is null then
    raise no_data_found using message='medication plan unavailable';
  end if;
  select * into version_row from public.medication_plan_versions
  where id = plan_row.current_version_id;

  return jsonb_build_object(
    'id', plan_row.id,
    'institution_id', plan_row.institution_id,
    'child_context_id', plan_row.child_context_id,
    'child_person_id', (
      select child_row.child_person_id from public.child_contexts child_row
      where child_row.id = plan_row.child_context_id),
    'scope_kind', plan_row.scope_kind,
    'unit_id', plan_row.unit_id,
    'group_id', plan_row.group_id,
    'status', plan_row.status,
    'management_version', plan_row.management_version,
    'can_manage', app_private.health_care_scope_allowed(
      'medication.manage', plan_row.institution_id, plan_row.unit_id,
      plan_row.group_id, plan_row.child_context_id),
    'current_version', to_jsonb(version_row),
    'schedules', coalesce((
      select jsonb_agg(to_jsonb(schedule_row) order by schedule_row.time_of_day)
      from public.medication_plan_schedules schedule_row
      where schedule_row.plan_version_id = version_row.id), '[]'::jsonb),
    'evidence', coalesce((
      select jsonb_agg(to_jsonb(evidence_row) order by evidence_row.occurred_at desc)
      from public.medication_plan_evidence evidence_row
      where evidence_row.plan_id = plan_row.id), '[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "app_private"."superadmin_medication_plan_detail"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_medication_plan_directory"("p_search" "text", "p_statuses" "text"[], "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer, "p_offset" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  page_limit integer := least(greatest(coalesce(p_limit, 20), 1), 100);
  page_offset integer := greatest(coalesce(p_offset, 0), 0);
  search_term text := nullif(btrim(coalesce(p_search, '')), '');
  items jsonb;
  total bigint;
begin
  actor := app_private.require_health_care_actor('medication.read');
  select coalesce(jsonb_agg(to_jsonb(page_row) order by page_row.updated_at desc), '[]'::jsonb),
         coalesce(max(page_row.total_count), 0)
    into items, total
  from (
    select plan_row.id, plan_row.institution_id, plan_row.child_context_id,
           plan_row.scope_kind, plan_row.unit_id, plan_row.group_id,
           plan_row.status, plan_row.management_version, plan_row.updated_at,
           child_row.child_person_id, child_person.display_name,
           version_row.medication_name, version_row.dose_amount,
           version_row.dose_unit, version_row.administration_route,
           version_row.valid_from, version_row.valid_until,
           version_row.review_status, version_row.version,
           count(*) over () as total_count
    from public.medication_plans plan_row
    join public.child_contexts child_row on child_row.id = plan_row.child_context_id
    join public.people child_person on child_person.id = child_row.child_person_id
    left join public.medication_plan_versions version_row
      on version_row.id = plan_row.current_version_id
    where app_private.health_care_scope_allowed(
            'medication.read', plan_row.institution_id,
            plan_row.unit_id, plan_row.group_id, plan_row.child_context_id)
      and (p_institution_id is null or plan_row.institution_id = p_institution_id)
      and (p_unit_id is null or plan_row.unit_id = p_unit_id)
      and (p_group_id is null or plan_row.group_id = p_group_id)
      and (p_statuses is null or array_length(p_statuses, 1) is null
        or plan_row.status = any(p_statuses))
      and (search_term is null
        or child_person.display_name ilike '%' || search_term || '%'
        or version_row.medication_name ilike '%' || search_term || '%')
    order by plan_row.updated_at desc
    limit page_limit offset page_offset
  ) page_row;

  return jsonb_build_object(
    'items', items, 'total', total,
    'limit', page_limit, 'offset', page_offset
  );
end
$$;


ALTER FUNCTION "app_private"."superadmin_medication_plan_directory"("p_search" "text", "p_statuses" "text"[], "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_medication_plan_record_evidence"("p_request_id" "uuid", "p_plan_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  plan_row public.medication_plans;
  evidence_id uuid;
  response jsonb;
begin
  actor := app_private.require_health_care_actor('medication.record_evidence');
  perform pg_advisory_xact_lock(hashtextextended(p_plan_id::text, 0));
  response := app_private.health_care_receipt(p_request_id, actor, 'record_evidence');
  if response is not null then return response; end if;

  select * into plan_row
  from public.medication_plans
  where id = p_plan_id
    and app_private.health_care_scope_allowed(
      'medication.record_evidence', institution_id, unit_id, group_id,
      child_context_id);
  if plan_row.id is null then
    raise no_data_found using message='medication plan unavailable';
  end if;
  if plan_row.current_version_id is null then
    raise check_violation using message='medication plan has no version';
  end if;

  insert into public.medication_plan_evidence(
    plan_id, plan_version_id, schedule_id, occurred_at, outcome,
    reason, note, media_asset_id, recorded_by_person_id
  ) values (
    p_plan_id, plan_row.current_version_id,
    (p_payload->>'schedule_id')::uuid,
    coalesce((p_payload->>'occurred_at')::timestamptz, now()),
    coalesce(p_payload->>'outcome','administered'),
    nullif(btrim(coalesce(p_payload->>'reason','')), ''),
    nullif(btrim(coalesce(p_payload->>'note','')), ''),
    (p_payload->>'media_asset_id')::uuid,
    actor
  ) returning id into evidence_id;

  response := jsonb_build_object('id', evidence_id, 'plan_id', p_plan_id);
  insert into app_private.health_care_command_receipts
    values (p_request_id, actor, 'record_evidence', p_plan_id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'medication.evidence.record',
    'medication_plan_evidence', evidence_id, plan_row.institution_id,
    'success', response
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_medication_plan_record_evidence"("p_request_id" "uuid", "p_plan_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_medication_plan_save"("p_request_id" "uuid", "p_plan_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  aggregate_id uuid := coalesce(p_plan_id, gen_random_uuid());
  plan_row public.medication_plans;
  child_context uuid;
  child_institution uuid;
  version_id uuid;
  version_no integer;
  response jsonb;
  before_json jsonb;
  schedule_entry jsonb;
begin
  actor := app_private.require_health_care_actor('medication.manage');
  perform pg_advisory_xact_lock(hashtextextended(aggregate_id::text, 0));
  response := app_private.health_care_receipt(p_request_id, actor, 'save_plan');
  if response is not null then return response; end if;
  if jsonb_typeof(p_payload->'schedules') <> 'array'
    or jsonb_array_length(p_payload->'schedules') = 0 then
    raise check_violation using message='medication plan requires schedules';
  end if;

  if p_plan_id is not null then
    select * into plan_row
    from public.medication_plans
    where id = aggregate_id
      and app_private.health_care_scope_allowed(
        'medication.manage', institution_id, unit_id, group_id, child_context_id)
    for update;
    if plan_row.id is null then
      raise no_data_found using message='medication plan unavailable';
    end if;
    if plan_row.management_version <> p_expected_version then
      raise serialization_failure using message='expected_version mismatch';
    end if;
    before_json := to_jsonb(plan_row);
  else
    if p_expected_version <> 0 then
      raise serialization_failure using message='expected_version mismatch';
    end if;
    child_context := app_private.health_care_resolve_child_context(
      (p_payload->>'child_context_id')::uuid,
      (p_payload->>'child_person_id')::uuid,
      (p_payload->>'institution_id')::uuid);
    child_institution := app_private.health_care_child_institution(child_context);
    if child_institution is null then
      raise no_data_found using message='medication plan unavailable';
    end if;
    if not app_private.health_care_scope_allowed(
      'medication.manage', child_institution,
      (p_payload->>'unit_id')::uuid, (p_payload->>'group_id')::uuid,
      child_context) then
      raise insufficient_privilege using message='medication.manage required';
    end if;
    insert into public.medication_plans(
      id, institution_id, child_context_id, scope_kind, unit_id, group_id,
      status, created_by_person_id
    ) values (
      aggregate_id, child_institution, child_context,
      coalesce(p_payload->>'scope_kind','institution'),
      (p_payload->>'unit_id')::uuid, (p_payload->>'group_id')::uuid,
      coalesce(p_payload->>'status','draft'), actor
    ) returning * into plan_row;
    before_json := null;
  end if;

  -- Mudanca relevante cria versao e invalida aprovacoes anteriores (spec 020).
  -- As versoes antigas ficam; nenhuma dose registrada perde referencia.
  update public.medication_plan_versions
    set review_status = 'invalidated',
        review_reason = 'nova versao do plano',
        approved_at = null,
        approved_by_person_id = null
  where plan_id = aggregate_id and review_status in ('pending','approved');

  select coalesce(max(existing.version), 0) + 1 into version_no
  from public.medication_plan_versions existing
  where existing.plan_id = aggregate_id;

  insert into public.medication_plan_versions(
    plan_id, version, medication_name, dose_amount, dose_unit,
    administration_route, route_details, instructions, reason,
    valid_from, valid_until, timezone, created_by_person_id
  ) values (
    aggregate_id, version_no,
    btrim(coalesce(p_payload->>'medication_name','')),
    (p_payload->>'dose_amount')::numeric,
    btrim(coalesce(p_payload->>'dose_unit','')),
    btrim(coalesce(p_payload->>'administration_route','')),
    nullif(btrim(coalesce(p_payload->>'route_details','')), ''),
    nullif(btrim(coalesce(p_payload->>'instructions','')), ''),
    btrim(coalesce(p_payload->>'reason','')),
    (p_payload->>'valid_from')::date,
    (p_payload->>'valid_until')::date,
    btrim(coalesce(p_payload->>'timezone','')),
    actor
  ) returning id into version_id;

  for schedule_entry in select value from jsonb_array_elements(p_payload->'schedules') loop
    insert into public.medication_plan_schedules(
      plan_version_id, time_of_day, weekdays, timezone, frequency_kind,
      start_date, end_date, max_occurrences_per_day, institution_id
    ) values (
      version_id,
      (schedule_entry->>'time_of_day')::time,
      (select array_agg(value::smallint)
         from jsonb_array_elements_text(schedule_entry->'weekdays')),
      btrim(coalesce(schedule_entry->>'timezone', p_payload->>'timezone')),
      coalesce(schedule_entry->>'frequency_kind','weekly'),
      (schedule_entry->>'start_date')::date,
      (schedule_entry->>'end_date')::date,
      (schedule_entry->>'max_occurrences_per_day')::smallint,
      (schedule_entry->>'institution_id')::uuid
    );
  end loop;

  update public.medication_plans set
    current_version_id = version_id,
    status = coalesce(p_payload->>'status', status),
    management_version = management_version + 1,
    updated_at = now()
  where id = aggregate_id returning * into plan_row;

  response := jsonb_build_object(
    'id', aggregate_id,
    'management_version', plan_row.management_version,
    'version', version_no,
    'version_id', version_id
  );
  insert into app_private.health_care_command_receipts
    values (p_request_id, actor, 'save_plan', aggregate_id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, reason, before_json, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'medication.plan.save', 'medication_plan',
    aggregate_id, plan_row.institution_id, 'success',
    nullif(btrim(coalesce(p_payload->>'reason','')), ''),
    before_json, to_jsonb(plan_row)
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_medication_plan_save"("p_request_id" "uuid", "p_plan_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_notice_append_audit"("p_context" "app_private"."superadmin_internal_context", "p_action_code" "text", "p_resource_id" "uuid", "p_outcome" "text", "p_reason_code" "text", "p_correlation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.audit_append_superadmin_internal(
    p_context.internal_identity_id, p_context.internal_auth_link_id,
    p_context.internal_membership_id, p_context.session_id,
    p_context.permission_code, p_context.aal, p_action_code,
    p_outcome::public.audit_outcome, left(p_reason_code, 120), p_correlation_id,
    null, 'platform_notice', p_resource_id);
end
$$;


ALTER FUNCTION "app_private"."superadmin_notice_append_audit"("p_context" "app_private"."superadmin_internal_context", "p_action_code" "text", "p_resource_id" "uuid", "p_outcome" "text", "p_reason_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_notice_context"("p_permission_code" "text") RETURNS "app_private"."superadmin_internal_context"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context_record app_private.superadmin_internal_context;
begin
  select * into strict context_record
  from app_private.require_superadmin_internal_context(p_permission_code);
  if context_record.scope_kind <> 'platform' then
    raise insufficient_privilege using
      message = 'notice authorization denied', detail = 'SAI_PERMISSION_DENIED';
  end if;
  return context_record;
end
$$;


ALTER FUNCTION "app_private"."superadmin_notice_context"("p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_notice_denied"("p_permission_code" "text", "p_action_code" "text", "p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare normalized_code text := case when p_code in (
  'NOTICE_INVALID_INPUT', 'NOTICE_NOT_FOUND', 'NOTICE_CONFLICT',
  'NOTICE_INVALID_TRANSITION', 'NOTICE_TERMINAL', 'NOTICE_MEDIA_BLOCKED',
  'SAI_AUTH_REQUIRED', 'SAI_SESSION_INVALID', 'SAI_INTERNAL_CONTEXT_DENIED',
  'SAI_MEMBERSHIP_SUSPENDED', 'SAI_MEMBERSHIP_REVOKED',
  'SAI_PERMISSION_DENIED', 'SAI_MFA_REQUIRED') then p_code
  else 'SAI_INTERNAL_ERROR' end;
begin
  perform app_private.audit_superadmin_internal_denial_if_identified(
    p_permission_code, p_action_code, normalized_code, p_correlation_id);
  return app_private.superadmin_notice_error(normalized_code, p_correlation_id);
end
$$;


ALTER FUNCTION "app_private"."superadmin_notice_denied"("p_permission_code" "text", "p_action_code" "text", "p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_notice_error"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when p_code like 'SAI_%' then
      app_private.superadmin_internal_error_envelope(p_code, p_correlation_id)
    else pg_catalog.jsonb_build_object(
      'ok', false, 'data', null,
      'error', pg_catalog.jsonb_build_object(
        'code', case when p_code in (
          'NOTICE_INVALID_INPUT', 'NOTICE_NOT_FOUND', 'NOTICE_CONFLICT',
          'NOTICE_INVALID_TRANSITION', 'NOTICE_TERMINAL', 'NOTICE_MEDIA_BLOCKED'
        ) then p_code else 'NOTICE_INTERNAL_ERROR' end,
        'message', case
          when p_code = 'NOTICE_INVALID_INPUT' then 'Revise os dados da comunicação.'
          when p_code = 'NOTICE_NOT_FOUND' then 'Comunicação não encontrada.'
          when p_code = 'NOTICE_CONFLICT' then 'A comunicação foi alterada. Recarregue e tente novamente.'
          when p_code in ('NOTICE_INVALID_TRANSITION', 'NOTICE_TERMINAL') then 'Esta transição não é permitida.'
          when p_code = 'NOTICE_MEDIA_BLOCKED' then 'A mídia ainda não está disponível.'
          else 'Não foi possível concluir a operação.' end,
        'correlation_id', p_correlation_id,
        'http_status', case
          when p_code = 'NOTICE_NOT_FOUND' then 404
          when p_code = 'NOTICE_CONFLICT' then 409
          when p_code in ('NOTICE_INVALID_INPUT', 'NOTICE_INVALID_TRANSITION',
            'NOTICE_TERMINAL', 'NOTICE_MEDIA_BLOCKED') then 422
          else 500 end)) end
$$;


ALTER FUNCTION "app_private"."superadmin_notice_error"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_notice_guard_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.status::text in ('expired', 'inactive') and new.status is distinct from old.status then
    raise object_not_in_prerequisite_state using message = 'terminal notice state',
      detail = 'NOTICE_TERMINAL';
  end if;
  if new.status::text = 'published' or new.status::text = 'archived' then
    raise invalid_parameter_value using message = 'legacy notice state denied',
      detail = 'NOTICE_INVALID_TRANSITION';
  end if;
  if old.status is distinct from new.status and not (
    (old.status::text = 'draft' and new.status::text in ('scheduled', 'active', 'inactive'))
    or (old.status::text = 'scheduled' and new.status::text in ('active', 'expired', 'inactive'))
    or (old.status::text = 'active' and new.status::text in ('paused', 'expired', 'inactive'))
    or (old.status::text = 'paused' and new.status::text in ('scheduled', 'active', 'inactive'))
  ) then
    raise object_not_in_prerequisite_state using message = 'invalid notice transition',
      detail = 'NOTICE_INVALID_TRANSITION';
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."superadmin_notice_guard_transition"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."platform_notices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "notice_type" "public"."notice_type" NOT NULL,
    "status" "public"."notice_status" DEFAULT 'draft'::"public"."notice_status" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "title" "text",
    "body_text" "text",
    "cta_label" "text",
    "cta_url" "text",
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "created_by" "uuid",
    "approved_by" "uuid",
    "published_at" timestamp with time zone,
    "silencing_policy" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "priority_code" "text" DEFAULT 'routine'::"text" NOT NULL,
    "audience_json" "jsonb" DEFAULT "jsonb_build_object"('rules', "jsonb_build_array"("jsonb_build_object"('dimension', 'platform', 'select_all', true))) NOT NULL,
    "audience_label" "text" DEFAULT 'Toda a plataforma'::"text" NOT NULL,
    "behavior" "text" DEFAULT 'dismissible'::"text" NOT NULL,
    "target_device" "text" DEFAULT 'all'::"text" NOT NULL,
    "content_format" "text" DEFAULT 'text_background'::"text" NOT NULL,
    "background_color" "text",
    "text_color" "text",
    "button_color" "text",
    "popup_size" "text" DEFAULT 'standard'::"text" NOT NULL,
    "has_outer_inset" boolean DEFAULT true NOT NULL,
    "recurrence" "text" DEFAULT 'one_time'::"text" NOT NULL,
    "recurrence_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "image_orientation" "text" DEFAULT 'vertical'::"text" NOT NULL,
    "management_version" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by_internal_identity_id" "uuid",
    "updated_by_internal_identity_id" "uuid",
    "published_by_internal_identity_id" "uuid",
    CONSTRAINT "platform_notices_internal_v2_values_ck" CHECK (((("status")::"text" = ANY (ARRAY['draft'::"text", 'scheduled'::"text", 'active'::"text", 'paused'::"text", 'expired'::"text", 'inactive'::"text"])) AND ("priority_code" = ANY (ARRAY['routine'::"text", 'important'::"text", 'urgent'::"text"])) AND ("behavior" = ANY (ARRAY['dismissible'::"text", 'confirmation'::"text", 'checkbox_confirmation'::"text"])) AND ("target_device" = ANY (ARRAY['all'::"text", 'web'::"text", 'mobile'::"text", 'tablet'::"text"])) AND ("content_format" = 'text_background'::"text") AND ("popup_size" = ANY (ARRAY['compact'::"text", 'standard'::"text", 'large'::"text", 'fullscreen'::"text"])) AND ("recurrence" = ANY (ARRAY['one_time'::"text", 'daily'::"text", 'weekly'::"text", 'monthly'::"text", 'interval'::"text"])) AND ("image_orientation" = ANY (ARRAY['vertical'::"text", 'horizontal'::"text"])) AND ("management_version" > 0) AND (("char_length"("btrim"(COALESCE("title", ''::"text"))) >= 1) AND ("char_length"("btrim"(COALESCE("title", ''::"text"))) <= 120)) AND (("char_length"("btrim"(COALESCE("body_text", ''::"text"))) >= 1) AND ("char_length"("btrim"(COALESCE("body_text", ''::"text"))) <= 4000)) AND (("char_length"("btrim"("audience_label")) >= 1) AND ("char_length"("btrim"("audience_label")) <= 200)) AND (("ends_at" IS NULL) OR ("starts_at" IS NULL) OR ("ends_at" >= "starts_at")) AND (("background_color" IS NULL) OR ("background_color" ~ '^#[0-9A-F]{6}$'::"text")) AND (("text_color" IS NULL) OR ("text_color" ~ '^#[0-9A-F]{6}$'::"text")) AND (("button_color" IS NULL) OR ("button_color" ~ '^#[0-9A-F]{6}$'::"text"))))
);

ALTER TABLE ONLY "public"."platform_notices" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."platform_notices" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_notice_json"("p_notice" "public"."platform_notices") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'id', p_notice.id,
    'type', p_notice.notice_type::text,
    'title', p_notice.title,
    'body', p_notice.body_text,
    'priority', p_notice.priority_code,
    'status', case p_notice.status::text
      when 'published' then 'active' when 'archived' then 'inactive'
      else p_notice.status::text end,
    'starts_at', p_notice.starts_at,
    'ends_at', p_notice.ends_at,
    'audience', p_notice.audience_json,
    'audience_label', p_notice.audience_label,
    'behavior', p_notice.behavior,
    'target_device', p_notice.target_device,
    'content_format', p_notice.content_format,
    'background_color', p_notice.background_color,
    'text_color', p_notice.text_color,
    'button_color', p_notice.button_color,
    'popup_size', p_notice.popup_size,
    'has_outer_inset', p_notice.has_outer_inset,
    'button_label', p_notice.cta_label,
    'link_label', p_notice.silencing_policy ->> 'link_label',
    'recurrence', p_notice.recurrence,
    'interval_days', p_notice.recurrence_config -> 'interval_days',
    'weekly_days', coalesce(p_notice.recurrence_config -> 'weekly_days', '[]'::jsonb),
    'day_of_month', p_notice.recurrence_config -> 'day_of_month',
    'recurrence_until', p_notice.recurrence_config ->> 'until',
    'image_orientation', p_notice.image_orientation,
    'management_version', p_notice.management_version,
    'updated_at', p_notice.updated_at,
    'reach', (select count(*) from public.notice_receipts receipt
      where receipt.notice_id = p_notice.id),
    'delivered_count', (select count(*) from public.notice_receipts receipt
      where receipt.notice_id = p_notice.id and receipt.delivered_at is not null),
    'viewed_count', (select count(*) from public.notice_receipts receipt
      where receipt.notice_id = p_notice.id and receipt.opened_at is not null),
    'accepted_count', (select count(*) from public.notice_receipts receipt
      where receipt.notice_id = p_notice.id and receipt.acted_at is not null))
$$;


ALTER FUNCTION "app_private"."superadmin_notice_json"("p_notice" "public"."platform_notices") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_notice_refresh_lifecycle"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.platform_notices
  set status = 'active', published_at = coalesce(published_at, clock_timestamp()),
      updated_at = clock_timestamp(), management_version = management_version + 1
  where status = 'scheduled'::public.notice_status
    and starts_at <= clock_timestamp()
    and (ends_at is null or ends_at > clock_timestamp());
  update public.platform_notices
  set status = 'expired', updated_at = clock_timestamp(),
      management_version = management_version + 1
  where status in ('scheduled'::public.notice_status, 'active'::public.notice_status)
    and ends_at is not null and ends_at <= clock_timestamp();
end
$$;


ALTER FUNCTION "app_private"."superadmin_notice_refresh_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_notice_validate_payload"("p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare rule jsonb; dimension text; target_id text;
begin
  if jsonb_typeof(p_payload) <> 'object'
    or p_payload ->> 'type' not in ('popup', 'notice', 'critical_notice',
      'content_card', 'highlight', 'for_you')
    or char_length(btrim(coalesce(p_payload ->> 'title', ''))) not between 1 and 120
    or char_length(btrim(coalesce(p_payload ->> 'body', ''))) not between 1 and 4000
    or p_payload ->> 'priority' not in ('routine', 'important', 'urgent')
    or p_payload ->> 'content_format' <> 'text_background'
    or p_payload ->> 'behavior' not in ('dismissible', 'confirmation', 'checkbox_confirmation')
    or p_payload ->> 'target_device' not in ('all', 'web', 'mobile', 'tablet')
    or p_payload ->> 'popup_size' not in ('compact', 'standard', 'large', 'fullscreen')
    or p_payload ->> 'recurrence' not in ('one_time', 'daily', 'weekly', 'monthly', 'interval')
    or nullif(p_payload ->> 'starts_at', '') is null
    or not pg_input_is_valid(p_payload ->> 'starts_at', 'timestamptz')
    or (nullif(p_payload ->> 'ends_at', '') is not null
      and not pg_input_is_valid(p_payload ->> 'ends_at', 'timestamptz'))
    or jsonb_typeof(p_payload -> 'audience') <> 'object'
    or jsonb_typeof(p_payload #> '{audience,rules}') <> 'array'
    or jsonb_array_length(p_payload #> '{audience,rules}') <> 1 then
    raise invalid_parameter_value using message = 'invalid notice payload',
      detail = case when p_payload ->> 'content_format' = 'image'
        then 'NOTICE_MEDIA_BLOCKED' else 'NOTICE_INVALID_INPUT' end;
  end if;
  if p_payload ? 'ends_at' and nullif(p_payload ->> 'ends_at', '') is not null
    and (p_payload ->> 'ends_at')::timestamptz < (p_payload ->> 'starts_at')::timestamptz then
    raise invalid_parameter_value using message = 'invalid notice dates',
      detail = 'NOTICE_INVALID_INPUT';
  end if;
  for rule in select value from jsonb_array_elements(p_payload #> '{audience,rules}') loop
    dimension := rule ->> 'dimension';
    if dimension not in ('platform', 'institution', 'unit', 'group', 'person')
      or jsonb_typeof(coalesce(rule -> 'target_ids', '[]'::jsonb)) <> 'array'
      or jsonb_array_length(coalesce(rule -> 'target_ids', '[]'::jsonb)) > 500
      or (dimension = 'platform' and not coalesce((rule ->> 'select_all')::boolean, false))
      or (dimension <> 'platform' and not coalesce((rule ->> 'select_all')::boolean, false)
        and jsonb_array_length(coalesce(rule -> 'target_ids', '[]'::jsonb)) = 0) then
      raise invalid_parameter_value using message = 'invalid notice audience',
        detail = 'NOTICE_INVALID_INPUT';
    end if;
    for target_id in select value from jsonb_array_elements_text(
      coalesce(rule -> 'target_ids', '[]'::jsonb)) loop
      begin perform target_id::uuid;
      exception when invalid_text_representation then
        raise invalid_parameter_value using message = 'invalid notice audience id',
          detail = 'NOTICE_INVALID_INPUT';
      end;
      if (dimension = 'institution' and not exists(select 1 from public.institutions where id = target_id::uuid))
        or (dimension = 'unit' and not exists(select 1 from public.units where id = target_id::uuid))
        or (dimension = 'group' and not exists(select 1 from public.groups where id = target_id::uuid))
        or (dimension = 'person' and not exists(select 1 from public.people where id = target_id::uuid)) then
        raise invalid_parameter_value using message = 'invalid notice audience target',
          detail = 'NOTICE_INVALID_INPUT';
      end if;
    end loop;
  end loop;
end
$$;


ALTER FUNCTION "app_private"."superadmin_notice_validate_payload"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_person_detail_payload_v2"("p_person_id" "uuid", "p_scope_kind" "text", "p_scope_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id',person_record.id,
    'first_name',person_record.first_name,
    'last_name',person_record.last_name,
    'display_name',person_record.display_name,
    'legal_name',person_record.legal_name,
    'type',person_record.person_type,
    'status',person_record.status,
    'auth_link',case
      when exists(
        select 1
        from public.person_auth_links auth_link
        where auth_link.person_id=person_record.id
          and auth_link.status='active'
          and auth_link.revoked_at is null
      ) then 'linked'
      when exists(
        select 1
        from public.person_auth_links auth_link
        where auth_link.person_id=person_record.id
          and auth_link.revoked_at is null
      ) then 'pending'
      else 'unlinked'
    end,
    'memberships',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',assignment.id,
          'membership_id',membership.id,
          'institution_id',membership.institution_id,
          'institution_name',institution.public_name,
          'unit_id',unit_record.id,
          'unit_name',unit_record.name,
          'group_id',group_record.id,
          'group_name',group_record.name,
          'role',role_record.code,
          'is_platform',false
        )
        order by
          lower(institution.public_name) collate "C",
          institution.id,
          lower(unit_record.name) collate "C" nulls first,
          unit_record.id nulls first,
          lower(group_record.name) collate "C" nulls first,
          group_record.id nulls first,
          assignment.id
      )
      from public.institution_memberships membership
      join public.institution_role_assignments assignment
        on assignment.membership_id=membership.id
       and assignment.status='active'
       and (assignment.starts_at is null or assignment.starts_at<=now())
       and (assignment.expires_at is null or assignment.expires_at>now())
      join public.institution_roles role_record
        on role_record.id=assignment.role_id
       and role_record.status='active'
       and (
         role_record.institution_id is null
         or role_record.institution_id=membership.institution_id
       )
      join public.institutions institution
        on institution.id=membership.institution_id
       and institution.deleted_at is null
      left join public.units unit_record
        on unit_record.id=assignment.scope_unit_id
       and unit_record.institution_id=membership.institution_id
      left join public.groups group_record
        on group_record.id=assignment.scope_group_id
       and group_record.institution_id=membership.institution_id
       and group_record.unit_id=unit_record.id
      where membership.person_id=person_record.id
        and person_record.person_type='adult'
        and membership.status='active'
        and membership.revoked_at is null
        and (
          p_scope_kind='platform'
          or membership.institution_id=p_scope_institution_id
        )
        and (
          (assignment.scope_kind='institution'
            and assignment.scope_unit_id is null
            and assignment.scope_group_id is null)
          or (assignment.scope_kind='unit'
            and unit_record.id is not null
            and assignment.scope_group_id is null)
          or (assignment.scope_kind='group'
            and unit_record.id is not null
            and group_record.id is not null)
        )
    ),'[]'::jsonb) || coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',child_context.id,
          'membership_id',null,
          'institution_id',child_context.institution_id,
          'institution_name',institution.public_name,
          'unit_id',unit_link.unit_id,
          'unit_name',unit_record.name,
          'group_id',group_link.group_id,
          'group_name',group_record.name,
          'role','student',
          'is_platform',false
        )
        order by
          lower(institution.public_name) collate "C",
          institution.id,
          lower(unit_record.name) collate "C" nulls first,
          unit_record.id nulls first,
          lower(group_record.name) collate "C" nulls first,
          group_record.id nulls first,
          child_context.id
      )
      from public.child_contexts child_context
      join public.institutions institution
        on institution.id=child_context.institution_id
       and institution.deleted_at is null
      left join lateral(
        select candidate.id,candidate.unit_id
        from public.child_unit_links candidate
        join public.units candidate_unit
          on candidate_unit.id=candidate.unit_id
         and candidate_unit.institution_id=child_context.institution_id
        where candidate.child_context_id=child_context.id
          and candidate.status in('pending','awaiting_allocation','active')
          and candidate.revoked_at is null
        order by
          lower(candidate_unit.name) collate "C",
          candidate_unit.id,
          candidate.id
        limit 1
      ) unit_link on true
      left join public.units unit_record
        on unit_record.id=unit_link.unit_id
       and unit_record.institution_id=child_context.institution_id
      left join lateral(
        select candidate.id,candidate.group_id
        from public.child_group_links candidate
        join public.groups candidate_group
          on candidate_group.id=candidate.group_id
         and candidate_group.institution_id=child_context.institution_id
         and candidate_group.unit_id=unit_link.unit_id
        where candidate.child_unit_link_id=unit_link.id
          and candidate.status='active'
          and (candidate.starts_at is null or candidate.starts_at<=now())
          and (candidate.ends_at is null or candidate.ends_at>now())
        order by lower(candidate_group.name) collate "C",candidate_group.id,candidate.id
        limit 1
      ) group_link on true
      left join public.groups group_record
        on group_record.id=group_link.group_id
       and group_record.institution_id=child_context.institution_id
       and group_record.unit_id=unit_link.unit_id
      where child_context.child_person_id=person_record.id
        and person_record.person_type='child'
        and child_context.status='active'
        and (
          p_scope_kind='platform'
          or child_context.institution_id=p_scope_institution_id
        )
    ),'[]'::jsonb),
    'child_contexts',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',child_context.id,
          'institution_id',child_context.institution_id,
          'institution_name',institution.public_name,
          'unit_id',unit_link.unit_id,
          'unit_name',unit_record.name,
          'group_id',group_link.group_id,
          'group_name',group_record.name,
          'child_unit_link_id',unit_link.id,
          'child_group_link_id',group_link.id
        )
        order by
          lower(institution.public_name) collate "C",
          institution.id,
          lower(unit_record.name) collate "C" nulls first,
          unit_record.id nulls first,
          lower(group_record.name) collate "C" nulls first,
          group_record.id nulls first,
          child_context.id
      )
      from public.child_contexts child_context
      join public.institutions institution
        on institution.id=child_context.institution_id
       and institution.deleted_at is null
      left join lateral(
        select candidate.id,candidate.unit_id
        from public.child_unit_links candidate
        join public.units candidate_unit
          on candidate_unit.id=candidate.unit_id
         and candidate_unit.institution_id=child_context.institution_id
        where candidate.child_context_id=child_context.id
          and candidate.status in('pending','awaiting_allocation','active')
          and candidate.revoked_at is null
        order by
          lower(candidate_unit.name) collate "C",
          candidate_unit.id,
          candidate.id
        limit 1
      ) unit_link on true
      left join public.units unit_record
        on unit_record.id=unit_link.unit_id
       and unit_record.institution_id=child_context.institution_id
      left join lateral(
        select candidate.id,candidate.group_id
        from public.child_group_links candidate
        join public.groups candidate_group
          on candidate_group.id=candidate.group_id
         and candidate_group.institution_id=child_context.institution_id
         and candidate_group.unit_id=unit_link.unit_id
        where candidate.child_unit_link_id=unit_link.id
          and candidate.status='active'
          and (candidate.starts_at is null or candidate.starts_at<=now())
          and (candidate.ends_at is null or candidate.ends_at>now())
        order by lower(candidate_group.name) collate "C",candidate_group.id,candidate.id
        limit 1
      ) group_link on true
      left join public.groups group_record
        on group_record.id=group_link.group_id
       and group_record.institution_id=child_context.institution_id
       and group_record.unit_id=unit_link.unit_id
      where child_context.child_person_id=person_record.id
        and person_record.person_type='child'
        and child_context.status='active'
        and (
          p_scope_kind='platform'
          or child_context.institution_id=p_scope_institution_id
        )
    ),'[]'::jsonb),
    'updated_at',person_record.updated_at
  )
  from public.people person_record
  where person_record.id=p_person_id
    and person_record.deleted_at is null
    and (
      p_scope_kind='platform'
      or (
        p_scope_kind='institution'
        and (
          exists(
            select 1
            from public.institution_memberships membership
            join public.institution_role_assignments assignment
              on assignment.membership_id=membership.id
             and assignment.status='active'
             and (assignment.starts_at is null or assignment.starts_at<=now())
             and (assignment.expires_at is null or assignment.expires_at>now())
            join public.institution_roles role_record
              on role_record.id=assignment.role_id
             and role_record.status='active'
             and (
               role_record.institution_id is null
               or role_record.institution_id=membership.institution_id
             )
            join public.institutions institution
              on institution.id=membership.institution_id
             and institution.deleted_at is null
            left join public.units unit_record
              on unit_record.id=assignment.scope_unit_id
             and unit_record.institution_id=membership.institution_id
            left join public.groups group_record
              on group_record.id=assignment.scope_group_id
             and group_record.institution_id=membership.institution_id
             and group_record.unit_id=unit_record.id
            where membership.person_id=person_record.id
              and person_record.person_type='adult'
              and membership.institution_id=p_scope_institution_id
              and membership.status='active'
              and membership.revoked_at is null
              and (
                (assignment.scope_kind='institution'
                  and assignment.scope_unit_id is null
                  and assignment.scope_group_id is null)
                or (assignment.scope_kind='unit'
                  and unit_record.id is not null
                  and assignment.scope_group_id is null)
                or (assignment.scope_kind='group'
                  and unit_record.id is not null
                  and group_record.id is not null)
              )
          )
          or exists(
            select 1
            from public.child_contexts child_context
            join public.institutions institution
              on institution.id=child_context.institution_id
             and institution.deleted_at is null
            where child_context.child_person_id=person_record.id
              and person_record.person_type='child'
              and child_context.institution_id=p_scope_institution_id
              and child_context.status='active'
          )
        )
      )
    )
  for share of person_record
$$;


ALTER FUNCTION "app_private"."superadmin_person_detail_payload_v2"("p_person_id" "uuid", "p_scope_kind" "text", "p_scope_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_person_payload"("target_person_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', person.id,
    'first_name', person.first_name,
    'last_name', person.last_name,
    'display_name', person.display_name,
    'legal_name', person.legal_name,
    'type', person.person_type,
    'status', person.status,
    'auth_link', case
      when exists (
        select 1
        from public.person_auth_links auth_link
        where auth_link.person_id = person.id
          and auth_link.status = 'active'
          and auth_link.revoked_at is null
      ) then 'linked'
      when exists (
        select 1
        from public.person_auth_links auth_link
        where auth_link.person_id = person.id
          and auth_link.revoked_at is null
      ) then 'pending'
      else 'unlinked'
    end,
    'memberships', coalesce((
      select jsonb_agg(membership_payload order by membership_payload ->> 'institution_name')
      from (
        select jsonb_build_object(
          'id', assignment.id,
          'assignment_id', assignment.id,
          'membership_id', membership.id,
          'institution_id', membership.institution_id,
          'institution_name', institution.public_name,
          'unit_id', assignment.scope_unit_id,
          'unit_name', unit.name,
          'group_id', assignment.scope_group_id,
          'group_name', group_row.name,
          'role', role.code,
          'role_name', role.name,
          'is_platform', false
        ) as membership_payload
        from public.institution_memberships membership
        join public.institution_role_assignments assignment
          on assignment.membership_id = membership.id
          and assignment.status = 'active'
        join public.institution_roles role
          on role.id = assignment.role_id
        join public.institutions institution
          on institution.id = membership.institution_id
        left join public.units unit
          on unit.id = assignment.scope_unit_id
        left join public.groups group_row
          on group_row.id = assignment.scope_group_id
        where membership.person_id = person.id
          and membership.status = 'active'
          and membership.revoked_at is null
        union all
        select jsonb_build_object(
          'id', child_context.id,
          'institution_id', child_context.institution_id,
          'institution_name', institution.public_name,
          'unit_id', unit_link.unit_id,
          'unit_name', unit.name,
          'group_id', group_link.group_id,
          'group_name', group_row.name,
          'role', 'student',
          'is_platform', false
        )
        from public.child_contexts child_context
        join public.institutions institution
          on institution.id = child_context.institution_id
        left join public.child_unit_links unit_link
          on unit_link.child_context_id = child_context.id
          and unit_link.status in ('pending', 'awaiting_allocation', 'active')
          and unit_link.revoked_at is null
        left join public.units unit on unit.id = unit_link.unit_id
        left join public.child_group_links group_link
          on group_link.child_unit_link_id = unit_link.id
          and group_link.status = 'active'
        left join public.groups group_row on group_row.id = group_link.group_id
        where child_context.child_person_id = person.id
          and child_context.status = 'active'
      ) membership_rows
    ), '[]'::jsonb),
    'child_contexts', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', child_context.id,
          'institution_id', child_context.institution_id,
          'institution_name', institution.public_name,
          'status', child_context.status,
          'child_unit_link_id', (
            select unit_link.id
            from public.child_unit_links unit_link
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
            order by unit_link.created_at, unit_link.id
            limit 1
          ),
          'child_group_link_id', (
            select group_link.id
            from public.child_unit_links unit_link
            join public.child_group_links group_link
              on group_link.child_unit_link_id = unit_link.id
              and group_link.status = 'active'
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
            order by group_link.created_at, group_link.id
            limit 1
          ),
          'unit_id', (
            select unit_link.unit_id
            from public.child_unit_links unit_link
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
            order by unit_link.created_at, unit_link.id
            limit 1
          ),
          'group_id', (
            select group_link.group_id
            from public.child_unit_links unit_link
            join public.child_group_links group_link
              on group_link.child_unit_link_id = unit_link.id
              and group_link.status = 'active'
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
            order by group_link.created_at, group_link.id
            limit 1
          ),
          'unit_links', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'id', unit_link.id,
                'unit_id', unit_link.unit_id,
                'unit_name', unit.name,
                'status', unit_link.status,
                'group_links', coalesce((
                  select jsonb_agg(
                    jsonb_build_object(
                      'id', group_link.id,
                      'group_id', group_link.group_id,
                      'group_name', group_row.name,
                      'status', group_link.status
                    )
                    order by lower(group_row.name), group_link.id
                  )
                  from public.child_group_links group_link
                  join public.groups group_row
                    on group_row.id = group_link.group_id
                  where group_link.child_unit_link_id = unit_link.id
                    and group_link.status = 'active'
                ), '[]'::jsonb)
              )
              order by lower(unit.name), unit_link.id
            )
            from public.child_unit_links unit_link
            join public.units unit on unit.id = unit_link.unit_id
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
          ), '[]'::jsonb)
        )
        order by lower(institution.public_name), child_context.id
      )
      from public.child_contexts child_context
      join public.institutions institution
        on institution.id = child_context.institution_id
      where child_context.child_person_id = person.id
        and child_context.status = 'active'
    ), '[]'::jsonb),
    'platform_membership_summary', (
      select string_agg(role.name, ', ' order by role.name)
      from public.platform_memberships membership
      join public.platform_roles role on role.id = membership.role_id
      where membership.person_id = person.id
        and membership.status in ('invited', 'active', 'suspended')
        and membership.revoked_at is null
    ),
    'guardian_links_summary', concat_ws(
      ' · ',
      case when (
        select count(*)
        from public.guardian_links guardian_link
        where guardian_link.guardian_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ) > 0 then (
        select count(*)::text || ' criança(s)'
        from public.guardian_links guardian_link
        where guardian_link.guardian_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ) end,
      case when (
        select count(*)
        from public.guardian_links guardian_link
        where guardian_link.child_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ) > 0 then (
        select count(*)::text || ' responsável(is)'
        from public.guardian_links guardian_link
        where guardian_link.child_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ) end
    ),
    'updated_at', person.updated_at
  )
  from public.people person
  where person.id = target_person_id
    and person.deleted_at is null
$$;


ALTER FUNCTION "app_private"."superadmin_person_payload"("target_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_prepare_activity_identity_upload"("p_activity_id" "uuid", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id(); extension text; request_hash bytea;
 receipt app_private.activity_management_command_receipts%rowtype; result jsonb; path text;
begin
 if (select auth.uid()) is null or actor is null
    or not app_private.has_platform_permission('activities.manage') then
  raise insufficient_privilege using message='activities.manage required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if not exists(select 1 from public.activity_definitions activity where activity.id=p_activity_id)
    or p_idempotency_key is null or nullif(btrim(p_file_name),'') is null
    or length(p_file_name)>180 or p_size_bytes not between 1 and 2097152
    or p_mime_type not in ('image/jpeg','image/png','image/webp') then
  raise invalid_parameter_value using message='invalid identity upload';
 end if;
 extension:=case p_mime_type when 'image/jpeg' then 'jpg'
  when 'image/png' then 'png' else 'webp' end;
 path:='activities/'||p_activity_id::text||'/'||p_idempotency_key::text||'.'||extension;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'activity_id',p_activity_id,'file_name',p_file_name,'mime_type',p_mime_type,
  'size_bytes',p_size_bytes)::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into receipt from app_private.activity_management_command_receipts
  where request_id=p_idempotency_key;
 if receipt.request_id is not null then
  if receipt.actor_person_id<>actor then
   raise insufficient_privilege using message='idempotency receipt actor mismatch';
  end if;
  if receipt.command_kind<>'identity_prepare' or receipt.request_hash<>request_hash then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return receipt.result_json;
 end if;
 insert into app_private.activity_identity_upload_intents(
  request_id,activity_id,actor_person_id,storage_path,mime_type,size_bytes,expires_at
 ) values(p_idempotency_key,p_activity_id,actor,path,p_mime_type,p_size_bytes,
   now()+interval '10 minutes');
 result:=jsonb_build_object('bucket','coelo-identities','path',path,
  'mime_type',p_mime_type,'size_limit',2097152,'expires_at',now()+interval '10 minutes');
 insert into app_private.activity_management_command_receipts(
  request_id,command_kind,request_hash,actor_person_id,activity_id,result_json
 ) values(p_idempotency_key,'identity_prepare',request_hash,actor,p_activity_id,result);
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_prepare_activity_identity_upload"("p_activity_id" "uuid", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_prepare_institution_identity_upload"("p_institution_id" "uuid", "p_kind" "text", "p_mime_type" "text", "p_size_bytes" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  media_id uuid := gen_random_uuid();
  extension text;
  storage_path text;
begin
  actor:=app_private.assert_institution_identity_access(p_institution_id);
  if p_kind not in('profile','cover')
     or p_mime_type not in('image/jpeg','image/png')
     or p_size_bytes not between 1 and 2097152 then
    raise invalid_parameter_value using message='invalid institution identity media';
  end if;
  extension:=case p_mime_type when 'image/png' then 'png' else 'jpg' end;
  storage_path:='institutions/'||p_institution_id||'/'||p_kind||'/'||media_id||'.'||extension;
  insert into public.institution_identity_media(
    id,institution_id,kind,storage_path,mime_type,size_bytes,created_by
  ) values(media_id,p_institution_id,p_kind,storage_path,p_mime_type,p_size_bytes,actor);
  insert into audit.audit_logs(
    actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json
  ) values(
    actor,'aal2','institution.identity.prepare','institution_identity_media',
    media_id,'success',jsonb_build_object('institution_id',p_institution_id,'kind',p_kind)
  );
  return jsonb_build_object(
    'media_id',media_id,'bucket','coelo-institution-identities','storage_path',storage_path
  );
end
$$;


