CREATE OR REPLACE FUNCTION "app_private"."superadmin_prepare_unit_identity_upload"("unit_id" "uuid", "kind" "text", "mime" "text", "bytes" bigint, "request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();institution uuid;media uuid;path text;ext text;
 prior app_private.unit_identity_upload_intents%rowtype;expiry timestamptz:=now()+interval'15 minutes';begin
 if(select auth.uid())is null or actor is null or request_id is null then raise insufficient_privilege using message='authentication required';end if;
 select u.institution_id into institution from public.units u where u.id=unit_id;
 if institution is null then raise no_data_found using message='unit not found';end if;
 if not app_private.has_scoped_platform_permission('units.update',institution)or not app_private.has_mfa_aal2()
 then raise insufficient_privilege using message='units.update and AAL2 required';end if;
 if kind not in('profile','cover','featured')or mime not in('image/jpeg','image/png')or bytes not between 1 and 5242880
 then raise invalid_parameter_value using message='invalid unit identity upload';end if;
 perform pg_advisory_xact_lock(hashtextextended(request_id::text,0));
 select*into prior from app_private.unit_identity_upload_intents i where i.request_id=superadmin_prepare_unit_identity_upload.request_id;
 if prior.request_id is not null then
  if prior.actor_person_id<>actor or prior.unit_id<>unit_id or prior.media_kind::text<>kind or prior.mime_type<>mime or prior.size_bytes<>bytes
  then raise invalid_parameter_value using message='idempotency key reused';end if;
  return jsonb_build_object('media_id',prior.media_id,'bucket','coelo-unit-identities','upload_path',prior.storage_path,'expires_at',prior.expires_at);end if;
 media:=gen_random_uuid();ext:=case mime when'image/jpeg'then'jpg'else'png'end;
 path:='institutions/'||institution||'/units/'||unit_id||'/'||kind||'/'||media||'.'||ext;
 insert into public.unit_identity_media(id,institution_id,unit_id,media_kind,storage_path,mime_type,size_bytes,created_by_person_id)
 values(media,institution,unit_id,kind::public.unit_identity_media_kind,path,mime,bytes,actor);
 insert into app_private.unit_identity_upload_intents values(request_id,media,institution,unit_id,kind::public.unit_identity_media_kind,actor,path,mime,bytes,expiry,null,now());
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,after_json)
 values(actor,auth.jwt()->>'aal','unit.identity.upload.prepare','unit_identity_media',media,institution,'success',
 jsonb_build_object('unit_id',unit_id,'kind',kind,'bucket','coelo-unit-identities','path',path,'mime_type',mime,'size_bytes',bytes));
 return jsonb_build_object('media_id',media,'bucket','coelo-unit-identities','upload_path',path,'expires_at',expiry);end$$;


ALTER FUNCTION "app_private"."superadmin_prepare_unit_identity_upload"("unit_id" "uuid", "kind" "text", "mime" "text", "bytes" bigint, "request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_preview_institution_import"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_file" "jsonb", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
 actor uuid; job public.import_jobs%rowtype; source_row jsonb; row_number integer;
 payload jsonb; error_code text; valid_count integer:=0; rejected_count integer:=0;
 expected_path text;
begin
 actor:=app_private.assert_institution_file_access('institutions.import');
 if p_request_id is null or jsonb_typeof(p_rows)<>'array'
    or jsonb_array_length(p_rows) not between 1 and 5000
    or jsonb_typeof(p_file)<>'object' then
  raise invalid_parameter_value using message='invalid institution import preview';
 end if;
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null or job.target_domain<>'institutions' or job.created_by<>actor then
  raise insufficient_privilege using message='institution import outside actor scope';
 end if;
 expected_path:='imports/institutions/'||job.id||'/source.'||job.source_format;
 if p_file->>'storage_path'<>expected_path
    or p_file->>'mime_type'<>(case job.source_format when 'csv' then 'text/csv'
       else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' end)
    or coalesce((p_file->>'size_bytes')::bigint,0) not between 1 and 5242880
    or coalesce(p_file->>'checksum_sha256','')!~'^[0-9a-f]{64}$' then
  raise invalid_parameter_value using message='invalid institution import artifact';
 end if;
 delete from public.import_errors where import_job_id=job.id;
 delete from public.import_rows where import_job_id=job.id;
 for source_row in select value from jsonb_array_elements(p_rows) loop
  row_number:=coalesce((source_row->>'row_number')::integer,0);
  payload:=jsonb_strip_nulls(jsonb_build_object(
   'public_name',nullif(btrim(source_row->>'public_name'),''),
   'slug',app_private.normalize_institution_handle(source_row->>'slug'),
   'institution_type_name',nullif(btrim(source_row->>'institution_type_name'),''),
   'legal_name',nullif(btrim(source_row->>'legal_name'),''),
   'document_type',coalesce(nullif(btrim(source_row->>'document_type'),''),'CNPJ'),
   'document_ref',nullif(btrim(source_row->>'document_ref'),''),
   'status',coalesce(nullif(btrim(source_row->>'status'),''),'draft'),
   'timezone',coalesce(nullif(btrim(source_row->>'timezone'),''),'America/Sao_Paulo'),
   'locale',coalesce(nullif(btrim(source_row->>'locale'),''),'pt-BR'),
   'contact',jsonb_build_object('email',nullif(btrim(source_row->>'contact_email'),''))
  ));
  error_code:=null;
  if row_number<2
     or coalesce(payload->>'public_name','')=''
     or coalesce(payload->>'institution_type_name','')=''
     or coalesce(payload->>'slug','')!~'^[a-z0-9][a-z0-9._-]{2,29}$' then
   error_code:='invalid_required_fields';
  elsif exists(
    select 1 from public.institutions i
    where i.slug=payload->>'slug' and i.deleted_at is null
  ) or exists(
    select 1 from public.import_rows r
    where r.import_job_id=job.id and r.payload_json->>'slug'=payload->>'slug'
  ) then
   error_code:='handle_unavailable';
  end if;
  insert into public.import_rows(import_job_id,row_number,payload_json,status,error_code)
  values(
    job.id,row_number,payload,
    case when error_code is null then 'active'::public.record_status else 'archived'::public.record_status end,
    error_code
  );
  if error_code is null then
   valid_count:=valid_count+1;
  else
   rejected_count:=rejected_count+1;
   insert into public.import_errors(import_job_id,row_number,error_code,message)
   values(job.id,row_number,error_code,
    case error_code when 'handle_unavailable' then '@ indisponÃ­vel.'
    else 'Nome, @ e tipo da instituiÃ§Ã£o sÃ£o obrigatÃ³rios e devem ser vÃ¡lidos.' end);
  end if;
 end loop;
 insert into public.import_files(import_job_id,storage_path,file_name,mime_type,size_bytes)
 values(job.id,expected_path,left(p_file->>'file_name',180),p_file->>'mime_type',(p_file->>'size_bytes')::bigint)
 on conflict do nothing;
 update public.import_jobs set
  summary=summary||jsonb_build_object(
    'phase','preview','valid_count',valid_count,'rejected_count',rejected_count,
    'preview_request_id',p_request_id
  ),updated_at=now()
 where id=job.id;
 return app_private.institution_file_job_payload(job.id);
end
$_$;


ALTER FUNCTION "app_private"."superadmin_preview_institution_import"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_file" "jsonb", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_preview_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_rows" "jsonb", "p_mapping" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid; job public.import_jobs%rowtype; source_row jsonb; row_number int:=0;
 v_valid_count int:=0; v_rejected_count int:=0; institution uuid; type_id uuid; error_code text;
 storage_path text; expected_path text; file_data jsonb;
begin
 actor:=app_private.assert_unit_file_access('units.import',null);
 if p_request_id is null or p_import_job_id is null or jsonb_typeof(p_rows)<>'array'
    or jsonb_array_length(p_rows)>5000 or jsonb_typeof(p_mapping)<>'object' then
  raise invalid_parameter_value using message='invalid unit import preview';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_import_job_id::text,0));
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null then raise no_data_found using message='unit import not found'; end if;
 if job.target_domain<>'units' or job.created_by<>actor then
  raise insufficient_privilege using message='unit import outside actor scope';
 end if;
 file_data:=p_mapping->'file'; storage_path:=file_data->>'storage_path';
 expected_path:='imports/units/'||job.id||'/source.'||job.source_format;
 if storage_path is distinct from expected_path
    or not exists(select 1 from storage.objects object_record
      where object_record.bucket_id='coelo-operations' and object_record.name=expected_path) then
  raise check_violation using message='unit import object not found';
 end if;
 delete from public.import_errors where import_job_id=job.id;
 delete from public.import_rows where import_job_id=job.id;
 delete from public.import_mappings where import_job_id=job.id;
 for source_row in select value from jsonb_array_elements(p_rows) loop
  row_number:=row_number+1; error_code:=null;
  begin institution:=nullif(source_row->>'institution_id','')::uuid;
  exception when others then error_code:='invalid_institution_id'; end;
  begin type_id:=nullif(source_row->>'unit_type_id','')::uuid;
  exception when others then error_code:=coalesce(error_code,'invalid_unit_type_id'); end;
  if error_code is null and not app_private.has_scoped_platform_permission('units.import',institution) then error_code:='institution_scope_denied'; end if;
  if error_code is null and not exists(select 1 from public.institutions i where i.id=institution and i.deleted_at is null) then error_code:='institution_not_found'; end if;
  if error_code is null and not exists(select 1 from public.unit_types t where t.id=type_id and t.status='active') then error_code:='unit_type_not_found'; end if;
  if error_code is null and (length(btrim(coalesce(source_row->>'name',''))) not between 1 and 160
    or (source_row->>'slug') !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$') then error_code:='invalid_identity'; end if;
  if error_code is null and coalesce(nullif(source_row->>'status',''),'active') not in('draft','active','inactive','suspended','archived') then error_code:='invalid_unit_status'; end if;
  if error_code is null and exists(select 1 from public.units u where u.institution_id=institution and u.slug=source_row->>'slug') then error_code:='slug_unavailable'; end if;
  if error_code is null and exists(select 1 from public.unit_types t where t.id=type_id and lower(t.code)='other')
     and nullif(btrim(source_row->>'unit_type_other_text'),'') is null then error_code:='other_description_required'; end if;
  source_row:=source_row||jsonb_build_object('request_id',coalesce(source_row->>'request_id',gen_random_uuid()::text));
  insert into public.import_rows(import_job_id,row_number,payload_json,status,error_code)
  values(job.id,row_number,source_row,case when error_code is null then'draft'::public.record_status else'archived'::public.record_status end,error_code);
  if error_code is null then v_valid_count:=v_valid_count+1; else
   v_rejected_count:=v_rejected_count+1;
   insert into public.import_errors(import_job_id,row_number,error_code,message)
   values(job.id,row_number,error_code,'Linha rejeitada pela validacao de Unidades.');
  end if;
 end loop;
 insert into public.import_files(import_job_id,storage_path,file_name,mime_type,size_bytes)
 values(job.id,expected_path,'source.'||job.source_format,file_data->>'mime_type',nullif(file_data->>'size_bytes','')::bigint)
 on conflict do nothing;
 update public.import_jobs set summary=summary||jsonb_build_object('phase','preview','mapping',coalesce(p_mapping->'columns','{}'::jsonb),
  'valid_count',v_valid_count,'rejected_count',v_rejected_count,'preview_request_id',p_request_id),updated_at=now() where id=job.id;
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json)
 values(actor,'aal2','unit.import.preview','import_job',job.id,'success',jsonb_build_object('valid',v_valid_count,'rejected',v_rejected_count));
 return app_private.unit_file_job_payload(job.id);
end $_$;


ALTER FUNCTION "app_private"."superadmin_preview_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_rows" "jsonb", "p_mapping" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_preview_unit_import_from_edge"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_rows" "jsonb", "p_mapping_columns" "jsonb", "p_checksum_sha256" "text", "p_size_bytes" bigint, "p_mime_type" "text", "p_parser_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  job public.import_jobs%rowtype;
  attestation app_private.unit_import_source_attestations%rowtype;
  actor_auth_user_id uuid;
  object_metadata jsonb;
  expected_path text;
  expected_mime text;
begin
  if p_request_id is null
    or p_import_job_id is null
    or jsonb_typeof(p_rows) <> 'array'
    or jsonb_array_length(p_rows) not between 1 and 5000
    or jsonb_typeof(p_mapping_columns) <> 'object'
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
    or p_size_bytes not between 1 and 5242880
    or p_mime_type not in (
      'text/csv',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    )
    or nullif(btrim(p_parser_version), '') is null
  then
    raise invalid_parameter_value using message = 'invalid edge import attestation';
  end if;

  select *
  into job
  from public.import_jobs
  where id = p_import_job_id
  for update;

  if job.id is null or job.target_domain <> 'units' then
    raise no_data_found using message = 'unit import not found';
  end if;

  expected_path := 'imports/units/' || job.id || '/source.' || job.source_format;
  expected_mime := case job.source_format
    when 'csv' then 'text/csv'
    when 'xlsx' then 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    else null
  end;
  if p_mime_type is distinct from expected_mime then
    raise invalid_parameter_value using message = 'edge import MIME mismatch';
  end if;

  select object_record.metadata
  into object_metadata
  from storage.objects object_record
  where object_record.bucket_id = 'coelo-operations'
    and object_record.name = expected_path;

  if not found
    or coalesce((object_metadata ->> 'size')::bigint, -1) <> p_size_bytes
    or coalesce(object_metadata ->> 'mimetype', '') <> p_mime_type
  then
    raise check_violation using message = 'attested import object mismatch';
  end if;

  select *
  into attestation
  from app_private.unit_import_source_attestations
  where import_job_id = job.id
  for update;

  if attestation.import_job_id is null then
    insert into app_private.unit_import_source_attestations (
      import_job_id,
      storage_path,
      mime_type,
      size_bytes,
      checksum_sha256,
      parser_version
    ) values (
      job.id,
      expected_path,
      p_mime_type,
      p_size_bytes,
      p_checksum_sha256,
      btrim(p_parser_version)
    );
  elsif attestation.storage_path <> expected_path
    or attestation.mime_type <> p_mime_type
    or attestation.size_bytes <> p_size_bytes
    or attestation.checksum_sha256 <> p_checksum_sha256
    or attestation.parser_version <> btrim(p_parser_version)
  then
    raise invalid_parameter_value using message = 'unit import source replay mismatch';
  end if;

  select auth_link.auth_user_id
  into actor_auth_user_id
  from public.person_auth_links auth_link
  where auth_link.person_id = job.created_by
    and auth_link.status = 'active'
    and auth_link.revoked_at is null
  order by auth_link.linked_at desc
  limit 1;

  if actor_auth_user_id is null then
    raise insufficient_privilege using message = 'unit import actor is not active';
  end if;

  perform pg_catalog.set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'sub', actor_auth_user_id::text,
      'role', 'authenticated',
      'aal', 'aal2'
    )::text,
    true
  );

  return app_private.superadmin_preview_unit_import(
    p_request_id,
    p_import_job_id,
    p_rows,
    jsonb_build_object(
      'columns', p_mapping_columns,
      'file', jsonb_build_object(
        'storage_path', expected_path,
        'mime_type', p_mime_type,
        'size_bytes', p_size_bytes
      )
    )
  );
end;
$_$;


ALTER FUNCTION "app_private"."superadmin_preview_unit_import_from_edge"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_rows" "jsonb", "p_mapping_columns" "jsonb", "p_checksum_sha256" "text", "p_size_bytes" bigint, "p_mime_type" "text", "p_parser_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_activity_export"("p_format" "text", "p_filters" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id(); request_hash bytea;
 job public.import_jobs%rowtype;
begin
 if (select auth.uid()) is null or actor is null
    or not app_private.has_platform_permission('activities.export') then
  raise insufficient_privilege using message='activities.export required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if p_format not in ('csv','xlsx') or p_idempotency_key is null
    or jsonb_typeof(coalesce(p_filters,'{}'::jsonb))<>'object'
    or coalesce(p_filters,'{}'::jsonb)-array[
      'search','institution_ids','unit_ids','group_ids','statuses','origins'
    ]<>'{}'::jsonb then
  raise invalid_parameter_value using message='invalid export request';
 end if;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'format',p_format,'filters',coalesce(p_filters,'{}'))::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into job from public.import_jobs job_record
  where job_record.request_id=p_idempotency_key;
 if job.id is not null then
  if job.created_by<>actor then
   raise insufficient_privilege using message='idempotency job actor mismatch';
  end if;
  if job.request_hash<>request_hash or job.target_domain<>'activities'
     or job.summary->>'operation'<>'export' then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return jsonb_build_object('job_id',job.id,'state',job.processing_state,'summary',job.summary);
 end if;
 insert into public.import_jobs(
  request_id,request_hash,target_domain,target_table,source_format,source_locale,
  target_locale,status,processing_state,summary,created_by
 ) values(p_idempotency_key,request_hash,'activities','activity_definitions',
  p_format,'pt-BR','pt-BR','draft','PENDENTE',
  jsonb_build_object('operation','export','filters',coalesce(p_filters,'{}'),
   'template_version','activities-v1','progress',0),actor)
 returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 insert into app_private.import_processing_queue(import_job_id) values(job.id);
 insert into audit.audit_logs(
  actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json
 ) values(actor,auth.jwt()->>'aal','activity.export.request','import_job',job.id,
  'success',jsonb_build_object('format',p_format,'state','PENDENTE'));
 return jsonb_build_object('job_id',job.id,'state',job.processing_state,'summary',job.summary);
end $$;


ALTER FUNCTION "app_private"."superadmin_request_activity_export"("p_format" "text", "p_filters" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_child_safety_export"("p_request_id" "uuid", "p_format" "text", "p_filters" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare
  actor uuid:=app_private.current_person_id(); request_hash bytea; replay jsonb;
  job_id uuid; result jsonb; filter_institutions uuid[]; filter_units uuid[];
  filter_search text; filter_segment text;
begin
  perform app_private.assert_child_safety_platform('child_safety.export');
  if p_request_id is null or p_format not in ('csv','json')
     or jsonb_typeof(coalesce(p_filters,'{}'))<>'object'
     or exists(select 1 from jsonb_object_keys(coalesce(p_filters,'{}')) key
       where key not in ('search','institution_ids','unit_ids','segment')) then
    raise invalid_parameter_value using message='invalid child safety export';
  end if;
  if (p_filters ? 'institution_ids' and jsonb_typeof(p_filters->'institution_ids')<>'array')
     or (p_filters ? 'unit_ids' and jsonb_typeof(p_filters->'unit_ids')<>'array')
     or (p_filters ? 'search' and jsonb_typeof(p_filters->'search')<>'string')
     or (p_filters ? 'segment' and jsonb_typeof(p_filters->'segment')<>'string') then
    raise invalid_parameter_value using message='invalid child safety export';
  end if;
  begin
    select coalesce(array_agg(value::uuid),'{}'::uuid[]) into filter_institutions
      from jsonb_array_elements_text(coalesce(p_filters->'institution_ids','[]'::jsonb)) value;
    select coalesce(array_agg(value::uuid),'{}'::uuid[]) into filter_units
      from jsonb_array_elements_text(coalesce(p_filters->'unit_ids','[]'::jsonb)) value;
  exception when others then
    raise invalid_parameter_value using message='invalid child safety export';
  end;
  filter_search:=btrim(coalesce(p_filters->>'search',''));
  filter_segment:=coalesce(nullif(p_filters->>'segment',''),'all');
  if char_length(filter_search)>120 or filter_segment not in (
    'all','awaiting_approval','attention','authorized','without_authorization'
  ) or exists (
    select 1 from public.units u where u.id=any(filter_units)
      and cardinality(filter_institutions)>0 and not u.institution_id=any(filter_institutions)
  ) then raise invalid_parameter_value using message='invalid child safety hierarchy'; end if;
  request_hash:=extensions.digest(convert_to(jsonb_build_object(
    'format',p_format,'filters',coalesce(p_filters,'{}'))::text,'utf8'),'sha256');
  perform pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_id::text,0));
  replay:=app_private.child_safety_receipt(p_request_id,actor,'request_export',request_hash);
  if replay is not null then return replay; end if;
  insert into public.import_jobs(
    target_domain,target_table,source_format,source_locale,target_locale,status,summary,created_by
  ) values('child_safety.export','authorized_person_authorizations',p_format,'pt-BR','pt-BR','draft',
    jsonb_build_object('direction','export','filters',coalesce(p_filters,'{}'),
      'template_version','child-safety-export-v1','csv_formula_policy','escape'),actor)
  returning id into job_id;
  result:=jsonb_build_object('job_id',job_id,'status','draft');
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,
    outcome,after_json)
  values(actor,auth.jwt()->>'aal','child_safety.export.request','import_job',job_id,'success',
    jsonb_build_object('format',p_format,'status','draft'));
  return app_private.child_safety_store_receipt(
    p_request_id,actor,'request_export',request_hash,job_id,result
  );
end $$;


ALTER FUNCTION "app_private"."superadmin_request_child_safety_export"("p_request_id" "uuid", "p_format" "text", "p_filters" "jsonb") OWNER TO "postgres";


