ALTER FUNCTION "app_private"."superadmin_request_import_export"("p_domain" "text", "p_format" "text", "p_filters" "jsonb", "p_current_view" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_institution_export"("p_format" "text", "p_filters" "jsonb", "p_sort" "text", "p_sort_ascending" boolean, "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; job public.import_jobs%rowtype; rows jsonb; request_hash bytea;
begin
 actor:=app_private.assert_institution_file_access('institutions.export');
 if p_format not in('csv','xlsx') or jsonb_typeof(p_filters)<>'object'
    or length(coalesce(p_filters->>'search',''))>200
    or p_sort not in('public_name','status','type_name','plan_name','city','state','updated_at') then
  raise invalid_parameter_value using message='invalid institution export contract';
 end if;
 select coalesce(jsonb_agg(to_jsonb(export_row)),'[]'::jsonb) into rows
 from (
  select d.id,d.public_name,d.legal_name,d.slug,d.type_name as institution_type_name,
   d.status,d.plan_name,d.contact_email,d.city,d.state,d.updated_at
  from public.institution_directory d
  where (coalesce(p_filters->>'search','')=''
    or d.search_name ilike '%'||replace(replace(replace(p_filters->>'search','\','\\'),'%','\%'),'_','\_')||'%' escape '\')
   and (jsonb_array_length(coalesce(p_filters->'statuses','[]'::jsonb))=0
    or d.status::text in(select jsonb_array_elements_text(p_filters->'statuses')))
   and (jsonb_array_length(coalesce(p_filters->'type_ids','[]'::jsonb))=0
    or d.institution_type_id::text in(select jsonb_array_elements_text(p_filters->'type_ids')))
   and (coalesce(p_filters->>'plan_id','')='' or d.plan_id::text=p_filters->>'plan_id')
   and (jsonb_array_length(coalesce(p_filters->'states','[]'::jsonb))=0
    or d.state in(select jsonb_array_elements_text(p_filters->'states')))
   and (jsonb_array_length(coalesce(p_filters->'cities','[]'::jsonb))=0
    or d.city in(select jsonb_array_elements_text(p_filters->'cities')))
   and (jsonb_array_length(coalesce(p_filters->'districts','[]'::jsonb))=0
    or d.district in(select jsonb_array_elements_text(p_filters->'districts')))
  order by
   case when p_sort='public_name' and p_sort_ascending then d.public_name end asc,
   case when p_sort='public_name' and not p_sort_ascending then d.public_name end desc,
   case when p_sort='status' and p_sort_ascending then d.status::text end asc,
   case when p_sort='status' and not p_sort_ascending then d.status::text end desc,
   case when p_sort='city' and p_sort_ascending then d.city end asc,
   case when p_sort='city' and not p_sort_ascending then d.city end desc,
   d.id asc
  limit 5001
 ) export_row;
 if jsonb_array_length(rows)=0 then return jsonb_build_object('empty',true); end if;
 if jsonb_array_length(rows)>5000 then
  raise program_limit_exceeded using message='institution export exceeds 5000 rows';
 end if;
 request_hash:=extensions.digest(pg_catalog.convert_to(jsonb_build_object(
  'format',p_format,'filters',p_filters,'sort',p_sort,'ascending',p_sort_ascending
 )::text,'UTF8'),'sha256');
 insert into public.import_jobs(
  request_id,request_hash,target_domain,target_table,source_format,source_locale,target_locale,
  status,processing_state,summary,created_by
 ) values(
  p_idempotency_key,request_hash,'institutions_export','institutions',p_format,'pt-BR','pt-BR',
  'draft','PROCESSANDO',jsonb_build_object('phase','generating','pii_included',true),actor
 ) returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 return jsonb_build_object('empty',false,'job_id',job.id,'format',p_format,'rows',rows);
end
$$;


ALTER FUNCTION "app_private"."superadmin_request_institution_export"("p_format" "text", "p_filters" "jsonb", "p_sort" "text", "p_sort_ascending" boolean, "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_institution_identity_delete"("p_institution_id" "uuid", "p_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare media public.institution_identity_media%rowtype;
begin
  perform app_private.assert_institution_identity_access(p_institution_id);
  if p_kind not in('profile','cover') then
    raise invalid_parameter_value using message='invalid identity kind';
  end if;
  select m.* into media
  from public.institution_identity_media m
  where m.institution_id=p_institution_id and m.kind=p_kind and m.state='active'
  for update;
  if media.id is null then
    return jsonb_build_object('bucket','coelo-institution-identities','storage_path',null);
  end if;
  update public.institution_branding
  set logo_media_asset_id=case when p_kind='profile' then null else logo_media_asset_id end,
      cover_media_asset_id=case when p_kind='cover' then null else cover_media_asset_id end,
      updated_at=now()
  where institution_id=p_institution_id;
  update public.institution_identity_media
  set state='archived',archived_at=now() where id=media.id;
  return jsonb_build_object('bucket',media.bucket_id,'storage_path',media.storage_path);
end
$$;


ALTER FUNCTION "app_private"."superadmin_request_institution_identity_delete"("p_institution_id" "uuid", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_unit_export"("p_format" "text", "p_filters" "jsonb", "p_current_view" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  request_hash bytea;
begin
  actor := app_private.assert_unit_file_access('units.export', null);
  if p_idempotency_key is null
    or p_format not in ('csv', 'xlsx')
    or jsonb_typeof(p_filters) <> 'object'
    or jsonb_typeof(p_current_view) <> 'object'
    or p_filters - array[
      'search',
      'institution_ids',
      'institution_type_ids',
      'unit_type_ids',
      'statuses',
      'unit_statuses',
      'plan_ids',
      'states',
      'cities',
      'districts'
    ] <> '{}'::jsonb
    or p_current_view - array[
      'sort',
      'sort_ascending',
      'group_by_institution',
      'columns'
    ] <> '{}'::jsonb
  then
    raise invalid_parameter_value using message = 'invalid unit export contract';
  end if;

  if length(coalesce(p_filters->>'search', '')) > 200
    or coalesce(p_current_view->>'sort', 'name') not in (
      'name',
      'institution_name',
      'institution_type',
      'unit_type',
      'status',
      'plan',
      'groups',
      'activities'
    )
  then
    raise invalid_parameter_value using message = 'invalid unit export filters';
  end if;

  request_hash := extensions.digest(
    pg_catalog.convert_to(
      jsonb_build_object(
        'format', p_format,
        'filters', p_filters,
        'view', p_current_view
      )::text,
      'UTF8'
    ),
    'sha256'
  );
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text, 0));

  select *
  into job
  from public.import_jobs
  where request_id = p_idempotency_key;

  if job.id is not null then
    if job.created_by <> actor
      or job.request_hash <> request_hash
      or job.target_domain <> 'units_export'
    then
      raise invalid_parameter_value using message = 'idempotency key replay mismatch';
    end if;
    return app_private.unit_file_job_payload(job.id);
  end if;

  insert into public.import_jobs(
    request_id,
    request_hash,
    target_domain,
    target_table,
    source_format,
    source_locale,
    target_locale,
    status,
    processing_state,
    summary,
    created_by
  )
  values(
    p_idempotency_key,
    request_hash,
    'units_export',
    'units',
    p_format,
    'pt-BR',
    'pt-BR',
    'draft',
    'PENDENTE',
    jsonb_build_object(
      'phase', 'queued',
      'filters', p_filters,
      'current_view', p_current_view,
      'pii_included', false
    ),
    actor
  )
  returning * into job;

  insert into public.import_results(import_job_id) values(job.id);
  insert into audit.audit_logs(
    actor_person_id,
    mfa_aal,
    action_code,
    object_type,
    object_id,
    outcome,
    after_json
  )
  values(
    actor,
    'aal2',
    'unit.export.request',
    'import_job',
    job.id,
    'success',
    jsonb_build_object('format', p_format, 'pii_included', false)
  );

  return app_private.unit_file_job_payload(job.id);
end
$$;


ALTER FUNCTION "app_private"."superadmin_request_unit_export"("p_format" "text", "p_filters" "jsonb", "p_current_view" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_unit_identity_delete"("media_id" "uuid", "request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$declare actor uuid:=app_private.current_person_id();
 media public.unit_identity_media%rowtype;prior app_private.unit_identity_delete_requests%rowtype;begin
 if(select auth.uid())is null or actor is null or request_id is null then raise insufficient_privilege using message='authentication required';end if;
 perform pg_advisory_xact_lock(hashtextextended(request_id::text,0));select*into prior from app_private.unit_identity_delete_requests r
 where r.request_id=superadmin_request_unit_identity_delete.request_id;
 if prior.request_id is not null then if prior.actor_person_id<>actor or prior.media_id<>media_id then raise invalid_parameter_value using message='idempotency key reused';end if;
  return jsonb_build_object('media_id',prior.media_id,'bucket','coelo-unit-identities','delete_path',prior.storage_path);end if;
 select*into media from public.unit_identity_media m where m.id=media_id for update;
 if media.id is null then raise no_data_found using message='unit identity media not found';end if;
 if not app_private.has_scoped_platform_permission('units.update',media.institution_id)or not app_private.has_mfa_aal2()
 then raise insufficient_privilege using message='units.update and AAL2 required';end if;
 if media.status not in('active','pending_delete')then raise invalid_parameter_value using message='unit identity media cannot be deleted';end if;
 update public.unit_identity_media set status='pending_delete',pending_delete_at=coalesce(pending_delete_at,now())where id=media.id;
 if media.media_kind='profile'then update public.unit_branding set logo_media_asset_id=null,updated_by=actor,updated_at=now()
  where unit_id=media.unit_id and logo_media_asset_id=media.id;
 elsif media.media_kind='cover'then update public.unit_branding set cover_media_asset_id=null,updated_by=actor,updated_at=now()
  where unit_id=media.unit_id and cover_media_asset_id=media.id;end if;
 insert into app_private.unit_identity_delete_requests values(request_id,media.id,actor,media.storage_path,null,now());
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,before_json,after_json)
 values(actor,auth.jwt()->>'aal','unit.identity.delete.request','unit_identity_media',media.id,media.institution_id,'success',to_jsonb(media),jsonb_build_object('status','pending_delete'));
 return jsonb_build_object('media_id',media.id,'bucket','coelo-unit-identities','delete_path',media.storage_path);end$$;


ALTER FUNCTION "app_private"."superadmin_request_unit_identity_delete"("media_id" "uuid", "request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_retry_import_export_job"("p_import_job_id" "uuid", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
begin
  if p_request_id is null or p_import_job_id is null then
    raise invalid_parameter_value using message = 'request_id and import job are required';
  end if;

  actor := app_private.assert_unit_file_access('units.import', null);
  select * into job
  from public.import_jobs
  where id = p_import_job_id and created_by = actor;
  if job.id is null or job.target_domain <> 'units' then
    raise insufficient_privilege using message = 'import retry unavailable';
  end if;
  return app_private.superadmin_retry_unit_import(p_request_id, p_import_job_id);
end;
$$;


ALTER FUNCTION "app_private"."superadmin_retry_import_export_job"("p_import_job_id" "uuid", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_retry_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  prior_job_id uuid;
begin
  if p_request_id is null or p_import_job_id is null then
    raise invalid_parameter_value using message = 'request_id and import job are required';
  end if;

  actor := app_private.assert_unit_file_access('units.import', null);
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('unit-import-retry:' || p_request_id::text, 0)
  );

  select candidate.id into prior_job_id
  from public.import_jobs candidate
  where candidate.target_domain = 'units'
    and candidate.summary ->> 'retry_request_id' = p_request_id::text
  limit 1;

  if prior_job_id is not null then
    if prior_job_id <> p_import_job_id then
      raise invalid_parameter_value using message = 'retry request_id already used';
    end if;
    select * into job
    from public.import_jobs
    where id = prior_job_id and created_by = actor;
    if job.id is null then
      raise insufficient_privilege using message = 'unit import outside actor scope';
    end if;
    return app_private.unit_file_job_payload(job.id);
  end if;

  select * into job
  from public.import_jobs
  where id = p_import_job_id
  for update;
  if job.id is null then
    raise no_data_found using message = 'unit import not found';
  end if;
  if job.created_by <> actor or job.target_domain <> 'units' then
    raise insufficient_privilege using message = 'unit import outside actor scope';
  end if;
  if job.processing_state not in ('ERRO', 'REJEICAO') then
    raise object_not_in_prerequisite_state using message = 'unit import is not retryable';
  end if;

  update public.import_jobs
  set processing_state = 'PENDENTE',
      status = 'draft',
      finished_at = null,
      summary = coalesce(summary, '{}'::jsonb) || jsonb_build_object(
        'phase', 'preview',
        'retry_request_id', p_request_id
      ),
      updated_at = now()
  where id = job.id;

  return app_private.unit_file_job_payload(job.id);
end;
$$;


ALTER FUNCTION "app_private"."superadmin_retry_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_application_detail"("p_application_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  application_row public.routine_applications;
  revision_row public.routine_application_revisions;
begin
  actor := app_private.require_routine_actor('routine.read', false);
  select * into application_row
  from public.routine_applications
  where id = p_application_id
    and app_private.routine_scope_allowed(
      'routine.read', institution_id, unit_id, group_id);
  if application_row.id is null then
    raise no_data_found using message='routine application unavailable';
  end if;
  select * into revision_row from public.routine_application_revisions
  where application_id = application_row.id
  order by revision_no desc limit 1;

  return jsonb_build_object(
    'id', application_row.id,
    'source_model_version_id', application_row.source_model_version_id,
    'institution_id', application_row.institution_id,
    'unit_id', application_row.unit_id,
    'group_id', application_row.group_id,
    'activity_id', application_row.activity_id,
    'parent_application_id', application_row.parent_application_id,
    'scope_kind', application_row.scope_kind,
    'status', application_row.status,
    'inheritance_mode', application_row.inheritance_mode,
    'visibility', application_row.visibility,
    'valid_from', application_row.valid_from,
    'valid_until', application_row.valid_until,
    'starts_at', application_row.starts_at,
    'ends_at', application_row.ends_at,
    'management_version', application_row.management_version,
    'effective_version', coalesce(revision_row.revision_no, 0),
    'can_manage', app_private.routine_scope_allowed(
      'routine.manage_applications', application_row.institution_id,
      application_row.unit_id, application_row.group_id),
    'assignees', coalesce((
      select jsonb_agg(jsonb_build_object(
        'membership_id', assignee_row.membership_id,
        'responsibility', assignee_row.responsibility) order by assignee_row.membership_id)
      from public.routine_application_assignees assignee_row
      where assignee_row.application_id = application_row.id), '[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "app_private"."superadmin_routine_application_detail"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_correct_launch"("uuid", "uuid", bigint, "text", "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid:=app_private.current_person_id(); launch_row public.routine_launches; before_state jsonb; after_state jsonb; response jsonb; item jsonb; next_revision integer; supplied integer;
begin
  if actor is null then raise insufficient_privilege using message='authentication required'; end if;
  perform pg_advisory_xact_lock(hashtextextended($2::text,0));
  response:=app_private.routine_receipt($1,actor,'correct_launch'); if response is not null then return response; end if;
  select l.* into launch_row from public.routine_launches l where l.id=$2
    and app_private.routine_scope_allowed('routine.correct',l.institution_id,l.unit_id,l.group_id) for update;
  if launch_row.id is null then raise insufficient_privilege using message='routine.correct required'; end if;
  if not app_private.has_mfa_aal2() then raise insufficient_privilege using message='MFA AAL2 required'; end if;
  if btrim(coalesce($4,''))='' then raise check_violation using message='correction reason required'; end if;
  if jsonb_typeof($5) <> 'array' or jsonb_array_length($5) not between 1 and 500 then raise invalid_parameter_value using message='invalid routine correction payload'; end if;
  supplied := jsonb_array_length($5);
  if supplied <> (select count(distinct payload_item.value->>'answer_id') from jsonb_array_elements($5) as payload_item(value) where payload_item.value ? 'answer_id')
    or supplied <> (select count(*) from public.routine_answers a join public.routine_child_entries e on e.id=a.child_entry_id
      where e.launch_id=$2 and a.id in (select (payload_item.value->>'answer_id')::uuid from jsonb_array_elements($5) as payload_item(value))) then
    raise check_violation using message='routine correction answer mismatch';
  end if;
  if launch_row.management_version<>$3 or launch_row.status not in ('published','corrected') then raise serialization_failure using message='expected_version mismatch'; end if;
  select coalesce(jsonb_agg(to_jsonb(a) order by a.id),'[]') into before_state from public.routine_answers a join public.routine_child_entries e on e.id=a.child_entry_id where e.launch_id=$2;
  for item in select value from jsonb_array_elements($5) loop
    update public.routine_answers a set value_json=item->'value',answered_by_person_id=actor,answered_at=now()
    from public.routine_child_entries e where a.id=(item->>'answer_id')::uuid and e.id=a.child_entry_id and e.launch_id=$2;
  end loop;
  perform app_private.validate_routine_launch_answers($2,true);
  select coalesce(jsonb_agg(to_jsonb(a) order by a.id),'[]') into after_state from public.routine_answers a join public.routine_child_entries e on e.id=a.child_entry_id where e.launch_id=$2;
  select coalesce(max(revision_row.revision_no),0)+1 into next_revision from public.routine_launch_revisions revision_row where revision_row.launch_id=$2;
  insert into public.routine_launch_revisions(launch_id,revision_no,reason,before_json,after_json,changed_by_person_id) values($2,next_revision,btrim($4),before_state,after_state,actor);
  update public.routine_launches set status='corrected',corrected_at=now(),updated_at=now(),management_version=management_version+1 where id=$2 returning * into launch_row;
  response:=jsonb_build_object('id',$2,'management_version',launch_row.management_version,'status','corrected','revision',next_revision);
  insert into app_private.routine_command_receipts values($1,actor,'correct_launch',$2,response,now());
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,reason,before_json,after_json) values(actor,auth.jwt()->>'aal','routine.launch.correct','routine_launch',$2,launch_row.institution_id,'success',btrim($4),before_state,after_state);
  return response;
end $_$;


ALTER FUNCTION "app_private"."superadmin_routine_correct_launch"("uuid", "uuid", bigint, "text", "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_directory"("p_entry_kind" "text", "p_search" "text", "p_status" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer, "p_offset" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  page_limit integer := least(greatest(coalesce(p_limit, 20), 1), 100);
  page_offset integer := greatest(coalesce(p_offset, 0), 0);
  search_term text := nullif(btrim(coalesce(p_search, '')), '');
  items jsonb;
  total bigint;
begin
  actor := app_private.require_routine_actor('routine.read', false);
  if p_entry_kind not in ('model','application','launch') then
    raise invalid_parameter_value using message='invalid routine entry kind';
  end if;

  if p_entry_kind = 'model' then
    select coalesce(jsonb_agg(to_jsonb(page_row) order by page_row.updated_at desc), '[]'::jsonb),
           coalesce(max(page_row.total_count), 0)
      into items, total
    from (
      select model_row.id, model_row.name, model_row.description, model_row.status,
             model_row.institution_id, model_row.origin_scope, model_row.origin_unit_id,
             model_row.management_version, model_row.updated_at,
             coalesce(version_row.version, 0) as version,
             model_row.current_version_id,
             count(*) over () as total_count
      from public.routine_models model_row
      left join public.routine_model_versions version_row
        on version_row.id = model_row.current_version_id
      where app_private.routine_scope_allowed(
              'routine.read', model_row.institution_id, model_row.origin_unit_id, null)
        and (p_institution_id is null or model_row.institution_id = p_institution_id)
        and (p_unit_id is null or model_row.origin_unit_id = p_unit_id)
        and (p_status is null or model_row.status = p_status)
        and (search_term is null or model_row.name ilike '%' || search_term || '%')
      order by model_row.updated_at desc
      limit page_limit offset page_offset
    ) page_row;
  elsif p_entry_kind = 'application' then
    select coalesce(jsonb_agg(to_jsonb(page_row) order by page_row.updated_at desc), '[]'::jsonb),
           coalesce(max(page_row.total_count), 0)
      into items, total
    from (
      select application_row.id, application_row.institution_id, application_row.unit_id,
             application_row.group_id, application_row.activity_id,
             application_row.scope_kind, application_row.status,
             application_row.inheritance_mode, application_row.visibility,
             application_row.valid_from, application_row.valid_until,
             application_row.starts_at, application_row.ends_at,
             application_row.parent_application_id,
             application_row.source_model_version_id,
             application_row.management_version, application_row.updated_at,
             count(*) over () as total_count
      from public.routine_applications application_row
      where app_private.routine_scope_allowed(
              'routine.read', application_row.institution_id,
              application_row.unit_id, application_row.group_id)
        and (p_institution_id is null or application_row.institution_id = p_institution_id)
        and (p_unit_id is null or application_row.unit_id = p_unit_id)
        and (p_group_id is null or application_row.group_id = p_group_id)
        and (p_status is null or application_row.status = p_status)
      order by application_row.updated_at desc
      limit page_limit offset page_offset
    ) page_row;
  else
    select coalesce(jsonb_agg(to_jsonb(page_row) order by page_row.launch_date desc), '[]'::jsonb),
           coalesce(max(page_row.total_count), 0)
      into items, total
    from (
      select launch_row.id, launch_row.institution_id, launch_row.unit_id,
             launch_row.group_id, launch_row.application_id,
             launch_row.application_revision_id, launch_row.launch_date,
             launch_row.status, launch_row.management_version,
             launch_row.published_at, launch_row.corrected_at, launch_row.updated_at,
             count(*) over () as total_count
      from public.routine_launches launch_row
      where app_private.routine_scope_allowed(
              'routine.read', launch_row.institution_id,
              launch_row.unit_id, launch_row.group_id)
        and (p_institution_id is null or launch_row.institution_id = p_institution_id)
        and (p_unit_id is null or launch_row.unit_id = p_unit_id)
        and (p_group_id is null or launch_row.group_id = p_group_id)
        and (p_status is null or launch_row.status = p_status)
      order by launch_row.launch_date desc
      limit page_limit offset page_offset
    ) page_row;
  end if;

  return jsonb_build_object(
    'items', items,
    'total', total,
    'limit', page_limit,
    'offset', page_offset,
    -- capacidade de criar/gerir no topo do envelope (F-R04-FCR-009)
    'can_manage', app_private.has_platform_permission('routine.manage_models')
      or exists (
        select 1
        from public.institution_memberships membership
        where membership.person_id = actor
          and membership.status = 'active'
          and membership.revoked_at is null
          and app_private.routine_scope_allowed(
            'routine.manage_models', membership.institution_id, null, null)
      )
  );
end
$$;


ALTER FUNCTION "app_private"."superadmin_routine_directory"("p_entry_kind" "text", "p_search" "text", "p_status" "text", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_launch_detail"("p_launch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  launch_row public.routine_launches;
begin
  actor := app_private.require_routine_actor('routine.read', false);
  select * into launch_row
  from public.routine_launches
  where id = p_launch_id
    and app_private.routine_scope_allowed(
      'routine.read', institution_id, unit_id, group_id);
  if launch_row.id is null then
    raise no_data_found using message='routine launch unavailable';
  end if;

  return jsonb_build_object(
    'id', launch_row.id,
    'application_id', launch_row.application_id,
    'application_revision_id', launch_row.application_revision_id,
    'institution_id', launch_row.institution_id,
    'unit_id', launch_row.unit_id,
    'group_id', launch_row.group_id,
    'author_membership_id', launch_row.author_membership_id,
    'launch_date', launch_row.launch_date,
    'status', launch_row.status,
    'management_version', launch_row.management_version,
    'can_manage', app_private.routine_scope_allowed(
      'routine.record', launch_row.institution_id,
      launch_row.unit_id, launch_row.group_id),
    'children', coalesce((
      select jsonb_agg(jsonb_build_object(
        'entry_id', entry_row.id,
        'child_context_id', entry_row.child_context_id,
        'child_group_link_id', entry_row.child_group_link_id,
        'status', entry_row.status,
        'answers', coalesce((
          select jsonb_agg(jsonb_build_object(
            'answer_id', answer_row.id,
            'field_id', answer_row.field_id,
            'value', answer_row.value_json) order by answer_row.field_id)
          from public.routine_answers answer_row
          where answer_row.child_entry_id = entry_row.id), '[]'::jsonb)
      ) order by entry_row.created_at)
      from public.routine_child_entries entry_row
      where entry_row.launch_id = launch_row.id), '[]'::jsonb)
  );
end
$$;


