CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_publish_launch"("p_request_id" "uuid", "p_launch_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  launch_row public.routine_launches;
  response jsonb;
begin
  if actor is null then
    raise insufficient_privilege using message='authentication required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_launch_id::text, 0));
  response := app_private.routine_receipt(p_request_id, actor, 'publish_launch');
  if response is not null then return response; end if;

  select launch.* into launch_row
  from public.routine_launches launch
  where launch.id = p_launch_id
    and app_private.routine_scope_allowed(
      'routine.publish', launch.institution_id, launch.unit_id, launch.group_id)
  for update;
  if launch_row.id is null then
    raise insufficient_privilege using message='routine.publish required';
  end if;
  if app_private.routine_mfa_phase_enforced() and not app_private.has_mfa_aal2() then
    raise insufficient_privilege using message='MFA AAL2 required';
  end if;
  if launch_row.management_version <> p_expected_version
    or launch_row.status <> 'draft' then
    raise serialization_failure using message='expected_version mismatch';
  end if;

  perform app_private.validate_routine_launch_answers(p_launch_id, true);

  update public.routine_launches set
    status = 'published',
    published_at = now(),
    published_by_person_id = actor,
    management_version = management_version + 1,
    updated_at = now()
  where id = p_launch_id returning * into launch_row;

  insert into public.context_notification_events(
    institution_id, unit_id, group_id, event_code, object_type, object_id,
    payload_json, created_by_person_id
  ) values (
    launch_row.institution_id, launch_row.unit_id, launch_row.group_id,
    'routine_launch_published', 'routine_launch', p_launch_id,
    jsonb_build_object('launch_date', launch_row.launch_date), actor
  );

  response := jsonb_build_object(
    'id', p_launch_id,
    'management_version', launch_row.management_version,
    'status', 'published'
  );
  insert into app_private.routine_command_receipts
    values (p_request_id, actor, 'publish_launch', p_launch_id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'routine.launch.publish', 'routine_launch',
    p_launch_id, launch_row.institution_id, 'success', response
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_routine_publish_launch"("p_request_id" "uuid", "p_launch_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_revert_application"("uuid", "uuid", bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor uuid;
  app_row public.routine_applications;
  parent_row public.routine_applications;
  response jsonb;
  revision_no integer;
begin
  actor:=app_private.require_routine_actor('routine.manage_applications',false);
  perform pg_advisory_xact_lock(hashtextextended($2::text,0));
  response:=app_private.routine_receipt($1,actor,'revert_application');
  if response is not null then return response; end if;
  select * into app_row
  from public.routine_applications
  where id=$2
    and app_private.routine_scope_allowed('routine.manage_applications', institution_id, unit_id, group_id)
  for update;
  if app_row.id is null then
    raise no_data_found using message='routine application unavailable';
  end if;
  if app_row.management_version<>$3 or app_row.parent_application_id is null then
    raise serialization_failure using message='expected_version mismatch';
  end if;
  select * into parent_row from public.routine_applications
  where id=app_row.parent_application_id and institution_id=app_row.institution_id;
  if parent_row.id is null then
    raise no_data_found using message='routine application unavailable';
  end if;
  update public.routine_applications set source_model_version_id=parent_row.source_model_version_id,
    inheritance_mode='inherited',management_version=management_version+1,updated_at=now()
  where id=$2 returning * into app_row;
  select coalesce(max(revision_row.revision_no),0)+1 into revision_no
  from public.routine_application_revisions revision_row where revision_row.application_id=$2;
  insert into public.routine_application_revisions(
    application_id,revision_no,source_model_version_id,origin_application_id,effective_definition,created_by_person_id
  ) values ($2,revision_no,app_row.source_model_version_id,parent_row.id,
    app_private.routine_definition_json(app_row.source_model_version_id),actor);
  response:=jsonb_build_object('id',$2,'management_version',app_row.management_version,'inherited',true);
  insert into app_private.routine_command_receipts values($1,actor,'revert_application',$2,response,now());
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,after_json)
  values(actor,auth.jwt()->>'aal','routine.application.revert','routine_application',$2,app_row.institution_id,'success',response);
  return response;
end $_$;


ALTER FUNCTION "app_private"."superadmin_routine_revert_application"("uuid", "uuid", bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_save_application"("p_request_id" "uuid", "p_application_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  aggregate_id uuid := coalesce(p_application_id, gen_random_uuid());
  app_row public.routine_applications;
  response jsonb;
  revision_id uuid;
  revision_no integer;
begin
  actor := app_private.require_routine_actor('routine.manage_applications', false);
  perform pg_advisory_xact_lock(hashtextextended(aggregate_id::text, 0));
  response := app_private.routine_receipt(p_request_id, actor, 'save_application');
  if response is not null then return response; end if;

  if p_application_id is not null then
    select * into app_row
    from public.routine_applications
    where id = aggregate_id
      and app_private.routine_scope_allowed('routine.manage_applications', institution_id, unit_id, group_id)
    for update;
    if app_row.id is null then
      raise no_data_found using message = 'routine application unavailable';
    end if;
  end if;

  if app_row.id is null then
    if p_expected_version <> 0 then
      raise serialization_failure using message = 'expected_version mismatch';
    end if;
    perform app_private.require_routine_scope(
      'routine.manage_applications',
      (p_payload->>'institution_id')::uuid,
      (p_payload->>'unit_id')::uuid,
      (p_payload->>'group_id')::uuid,
      false
    );
    insert into public.routine_applications(
      id,institution_id,unit_id,group_id,activity_id,scope_kind,source_model_version_id,
      parent_application_id,inheritance_mode,visibility,valid_from,valid_until,starts_at,
      ends_at,status,created_by_person_id
    ) values (
      aggregate_id,(p_payload->>'institution_id')::uuid,(p_payload->>'unit_id')::uuid,
      (p_payload->>'group_id')::uuid,(p_payload->>'activity_id')::uuid,p_payload->>'scope_kind',
      (p_payload->>'source_model_version_id')::uuid,(p_payload->>'parent_application_id')::uuid,
      coalesce(p_payload->>'inheritance_mode','inherited'),
      coalesce(p_payload->>'visibility','authorized_guardians'),(p_payload->>'valid_from')::date,
      (p_payload->>'valid_until')::date,(p_payload->>'starts_at')::time,
      (p_payload->>'ends_at')::time,coalesce(p_payload->>'status','draft'),actor
    ) returning * into app_row;
  else
    if app_row.management_version <> p_expected_version then
      raise serialization_failure using message = 'expected_version mismatch';
    end if;
    update public.routine_applications set
      source_model_version_id=(p_payload->>'source_model_version_id')::uuid,
      parent_application_id=(p_payload->>'parent_application_id')::uuid,
      inheritance_mode=coalesce(p_payload->>'inheritance_mode',inheritance_mode),
      visibility=coalesce(p_payload->>'visibility',visibility),
      valid_from=(p_payload->>'valid_from')::date,valid_until=(p_payload->>'valid_until')::date,
      starts_at=(p_payload->>'starts_at')::time,ends_at=(p_payload->>'ends_at')::time,
      status=coalesce(p_payload->>'status',status),management_version=management_version+1,
      updated_at=now()
    where id=aggregate_id returning * into app_row;
  end if;

  select coalesce(max(revision_row.revision_no),0)+1 into revision_no
  from public.routine_application_revisions revision_row where revision_row.application_id=aggregate_id;
  insert into public.routine_application_revisions(
    application_id,revision_no,source_model_version_id,origin_application_id,effective_definition,created_by_person_id
  ) values (
    aggregate_id,revision_no,app_row.source_model_version_id,
    coalesce(app_row.parent_application_id,aggregate_id),
    app_private.routine_definition_json(app_row.source_model_version_id),actor
  ) returning id into revision_id;
  delete from public.routine_application_assignees where application_id=aggregate_id;
  insert into public.routine_application_assignees(application_id,institution_id,membership_id,responsibility)
  select aggregate_id,app_row.institution_id,(x->>'membership_id')::uuid,coalesce(x->>'responsibility','record')
  from jsonb_array_elements(coalesce(p_payload->'assignees','[]')) x;
  response:=jsonb_build_object('id',aggregate_id,'management_version',app_row.management_version,
    'revision_id',revision_id,'revision',revision_no);
  insert into app_private.routine_command_receipts values(p_request_id,actor,'save_application',aggregate_id,response,now());
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,after_json)
  values(actor,auth.jwt()->>'aal','routine.application.save','routine_application',aggregate_id,app_row.institution_id,'success',response);
  return response;
end $$;


ALTER FUNCTION "app_private"."superadmin_routine_save_application"("p_request_id" "uuid", "p_application_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_save_launch_draft"("p_request_id" "uuid", "p_launch_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  aggregate_id uuid := coalesce(p_launch_id, gen_random_uuid());
  launch_row public.routine_launches;
  application_row public.routine_applications;
  revision_row public.routine_application_revisions;
  author_membership uuid;
  entry_item jsonb;
  answer_item jsonb;
  entry_id uuid;
  response jsonb;
begin
  actor := app_private.require_routine_actor('routine.record', false);
  perform pg_advisory_xact_lock(hashtextextended(aggregate_id::text, 0));
  response := app_private.routine_receipt(p_request_id, actor, 'save_launch_draft');
  if response is not null then return response; end if;

  if p_launch_id is not null then
    select * into launch_row
    from public.routine_launches
    where id = aggregate_id
      and app_private.routine_scope_allowed(
        'routine.record', institution_id, unit_id, group_id)
    for update;
    if launch_row.id is null then
      raise no_data_found using message='routine launch unavailable';
    end if;
    if launch_row.management_version <> p_expected_version then
      raise serialization_failure using message='expected_version mismatch';
    end if;
    if launch_row.status <> 'draft' then
      raise check_violation using message='routine launch is not a draft';
    end if;
    select * into application_row from public.routine_applications
    where id = launch_row.application_id;
  else
    if p_expected_version <> 0 then
      raise serialization_failure using message='expected_version mismatch';
    end if;
    select * into application_row from public.routine_applications
    where id = (p_payload->>'application_id')::uuid;
    if application_row.id is null then
      raise no_data_found using message='routine application unavailable';
    end if;
    perform app_private.require_routine_scope(
      'routine.record', application_row.institution_id,
      application_row.unit_id, application_row.group_id, false
    );
    select * into revision_row from public.routine_application_revisions
    where application_id = application_row.id
    order by revision_no desc limit 1;
    -- A autoria e derivada da sessao e do tenant do lancamento, nunca aceita
    -- do payload: aceitar deixaria um profissional lancar em nome de outro.
    select membership.id into author_membership
    from public.institution_memberships membership
    where membership.person_id = actor
      and membership.institution_id = application_row.institution_id
      and membership.status = 'active'
      and membership.revoked_at is null
    limit 1;
    insert into public.routine_launches(
      id, institution_id, unit_id, group_id, application_id,
      application_revision_id, author_membership_id, launch_date, status,
      created_by_person_id
    ) values (
      aggregate_id, application_row.institution_id, application_row.unit_id,
      application_row.group_id, application_row.id, revision_row.id,
      author_membership,
      coalesce((p_payload->>'launch_date')::date, current_date), 'draft', actor
    ) returning * into launch_row;
  end if;

  for entry_item in
    select value from jsonb_array_elements(coalesce(p_payload->'entries','[]'::jsonb))
  loop
    insert into public.routine_child_entries(
      launch_id, child_context_id, child_group_link_id, status
    ) values (
      aggregate_id,
      (entry_item->>'child_context_id')::uuid,
      (entry_item->>'child_group_link_id')::uuid,
      coalesce(entry_item->>'status','draft')
    )
    on conflict (launch_id, child_context_id) do update set
      child_group_link_id = excluded.child_group_link_id,
      status = excluded.status
    returning id into entry_id;

    for answer_item in
      select value from jsonb_array_elements(coalesce(entry_item->'answers','[]'::jsonb))
    loop
      insert into public.routine_answers(
        child_entry_id, field_id, value_json, answered_by_person_id, answered_at
      ) values (
        entry_id, (answer_item->>'field_id')::uuid, answer_item->'value', actor, now()
      )
      on conflict (child_entry_id, field_id) do update set
        value_json = excluded.value_json,
        answered_by_person_id = excluded.answered_by_person_id,
        answered_at = excluded.answered_at;
    end loop;
  end loop;

  perform app_private.validate_routine_launch_answers(aggregate_id, false);

  update public.routine_launches
    set management_version = management_version + 1, updated_at = now()
  where id = aggregate_id returning * into launch_row;

  response := jsonb_build_object(
    'id', aggregate_id,
    'management_version', launch_row.management_version,
    'status', launch_row.status
  );
  insert into app_private.routine_command_receipts
    values (p_request_id, actor, 'save_launch_draft', aggregate_id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'routine.launch.save_draft', 'routine_launch',
    aggregate_id, launch_row.institution_id, 'success', response
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_routine_save_launch_draft"("p_request_id" "uuid", "p_launch_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_routine_save_model"("p_request_id" "uuid", "p_model_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  aggregate_id uuid := coalesce(p_model_id, gen_random_uuid());
  model_row public.routine_models;
  before_json jsonb;
  after_json jsonb;
  response jsonb;
  version_id uuid;
  version_no integer;
  section_item jsonb;
  field_item jsonb;
  option_item jsonb;
  condition_item jsonb;
  section_id uuid;
  field_id uuid;
  option_id uuid;
  field_ids jsonb := '{}'::jsonb;
  option_ids jsonb := '{}'::jsonb;
begin
  actor := app_private.require_routine_actor('routine.manage_models', false);
  perform pg_advisory_xact_lock(hashtextextended(aggregate_id::text, 0));
  response := app_private.routine_receipt(p_request_id, actor, 'save_model');
  if response is not null then return response; end if;

  if p_model_id is not null then
    select * into model_row
    from public.routine_models
    where id = aggregate_id
      and app_private.routine_scope_allowed(
        'routine.manage_models', institution_id, origin_unit_id, null)
    for update;
    if model_row.id is null then
      raise no_data_found using message = 'routine model unavailable';
    end if;
    if model_row.management_version <> p_expected_version then
      raise serialization_failure using message='expected_version mismatch';
    end if;
    before_json := to_jsonb(model_row);
  else
    if p_expected_version <> 0 then
      raise serialization_failure using message='expected_version mismatch';
    end if;
    perform app_private.require_routine_scope(
      'routine.manage_models',
      (p_payload->>'institution_id')::uuid,
      (p_payload->>'origin_unit_id')::uuid,
      null,
      false
    );
    before_json := null;
  end if;

  if model_row.id is null then
    insert into public.routine_models(
      id, institution_id, origin_scope, origin_unit_id, name, description,
      status, created_by_person_id
    ) values (
      aggregate_id,
      (p_payload->>'institution_id')::uuid,
      coalesce(p_payload->>'origin_scope','institution'),
      (p_payload->>'origin_unit_id')::uuid,
      btrim(coalesce(p_payload->>'name','')),
      coalesce(p_payload->>'description',''),
      coalesce(p_payload->>'status','draft'),
      actor
    ) returning * into model_row;
  else
    update public.routine_models set
      name = btrim(coalesce(p_payload->>'name', name)),
      description = coalesce(p_payload->>'description', description),
      status = coalesce(p_payload->>'status', status),
      management_version = management_version + 1,
      updated_at = now()
    where id = aggregate_id returning * into model_row;
  end if;

  if p_payload ? 'sections' then
    if jsonb_typeof(p_payload->'sections') <> 'array' then
      raise invalid_parameter_value using message='invalid routine definition payload';
    end if;
    select coalesce(max(existing.version), 0) + 1 into version_no
    from public.routine_model_versions existing
    where existing.model_id = aggregate_id;

    insert into public.routine_model_versions(
      model_id, version, created_by_person_id
    ) values (aggregate_id, version_no, actor) returning id into version_id;

    for section_item in select value from jsonb_array_elements(p_payload->'sections') loop
      insert into public.routine_sections(model_version_id, name, sort_order)
      values (
        version_id,
        btrim(coalesce(section_item->>'name','')),
        coalesce((section_item->>'sort_order')::integer, 0)
      ) returning id into section_id;

      for field_item in
        select value from jsonb_array_elements(coalesce(section_item->'fields','[]'::jsonb))
      loop
        insert into public.routine_fields(
          section_id, label, kind, sort_order, is_required,
          initial_value, minimum_value, maximum_value
        ) values (
          section_id,
          btrim(coalesce(field_item->>'label','')),
          coalesce(field_item->>'kind','short_text'),
          coalesce((field_item->>'sort_order')::integer, 0),
          coalesce((field_item->>'is_required')::boolean, false),
          field_item->'initial_value',
          (field_item->>'minimum_value')::numeric,
          (field_item->>'maximum_value')::numeric
        ) returning id into field_id;
        field_ids := field_ids || jsonb_build_object(
          coalesce(field_item->>'id', field_id::text), field_id::text);

        for option_item in
          select value from jsonb_array_elements(coalesce(field_item->'options','[]'::jsonb))
        loop
          insert into public.routine_field_options(field_id, label, sort_order)
          values (
            field_id,
            btrim(coalesce(option_item->>'label','')),
            coalesce((option_item->>'sort_order')::integer, 0)
          ) returning id into option_id;
          option_ids := option_ids || jsonb_build_object(
            coalesce(option_item->>'id', option_id::text), option_id::text);
        end loop;
      end loop;
    end loop;

    for section_item in select value from jsonb_array_elements(p_payload->'sections') loop
      for field_item in
        select value from jsonb_array_elements(coalesce(section_item->'fields','[]'::jsonb))
      loop
        for condition_item in
          select value from jsonb_array_elements(coalesce(field_item->'conditions','[]'::jsonb))
        loop
          insert into public.routine_field_conditions(
            parent_field_id, target_field_id, option_id, boolean_value, depth
          ) values (
            (field_ids->>(condition_item->>'parent_field_id'))::uuid,
            (field_ids->>(condition_item->>'target_field_id'))::uuid,
            (option_ids->>(condition_item->>'option_id'))::uuid,
            (condition_item->>'boolean_value')::boolean,
            coalesce((condition_item->>'depth')::integer, 1)
          );
        end loop;
      end loop;
    end loop;

    perform app_private.validate_routine_definition(version_id);
    update public.routine_model_versions
      set definition_json = app_private.routine_definition_json(version_id),
          published_at = now()
    where id = version_id;
    update public.routine_models
      set current_version_id = version_id, updated_at = now()
    where id = aggregate_id returning * into model_row;
  end if;

  after_json := to_jsonb(model_row);
  response := jsonb_build_object(
    'id', aggregate_id,
    'management_version', model_row.management_version,
    'version', coalesce(version_no, 0),
    'version_id', version_id
  );
  insert into app_private.routine_command_receipts
    values (p_request_id, actor, 'save_model', aggregate_id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, before_json, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'routine.model.save', 'routine_model', aggregate_id,
    model_row.institution_id, 'success', before_json, after_json
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_routine_save_model"("p_request_id" "uuid", "p_model_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_student_edit"("p_request_id" "uuid", "p_child_context_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  institution uuid;
  target_unit uuid := (p_payload->>'unit_id')::uuid;
  target_group uuid := (p_payload->>'group_id')::uuid;
  unit_link public.child_unit_links;
  group_link public.child_group_links;
  before_state jsonb;
  response jsonb;
begin
  response := app_private.student_link_receipt(p_request_id, actor, 'edit');
  if response is not null then return response; end if;
  if target_unit is null or target_group is null then
    raise invalid_parameter_value using message='student edit requires unit and group';
  end if;
  institution := app_private.student_link_require_scope(
    p_child_context_id, target_unit, target_group);
  perform pg_advisory_xact_lock(hashtextextended(p_child_context_id::text, 0));

  select * into unit_link from public.child_unit_links
  where child_context_id = p_child_context_id and unit_id = target_unit;
  if unit_link.id is null then
    raise no_data_found using message='student link unavailable';
  end if;
  select * into group_link from public.child_group_links
  where child_unit_link_id = unit_link.id and group_id = target_group
  for update;
  if group_link.id is null then
    raise no_data_found using message='student link unavailable';
  end if;
  before_state := to_jsonb(group_link);

  update public.child_group_links set
    starts_at = coalesce((p_payload->>'starts_at')::timestamptz, starts_at),
    ends_at = case
      when p_payload ? 'ends_at' then (p_payload->>'ends_at')::timestamptz
      else ends_at end,
    updated_at = now()
  where id = group_link.id returning * into group_link;

  response := jsonb_build_object(
    'child_context_id', p_child_context_id,
    'unit_link_id', unit_link.id,
    'group_link_id', group_link.id,
    'starts_at', group_link.starts_at,
    'ends_at', group_link.ends_at
  );
  insert into app_private.student_link_command_receipts
    values (p_request_id, actor, 'edit', group_link.id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, before_json, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'student.edit', 'child_group_link',
    group_link.id, institution, 'success', before_state, response
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_student_edit"("p_request_id" "uuid", "p_child_context_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_student_link"("p_request_id" "uuid", "p_child_context_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  institution uuid;
  target_unit uuid := (p_payload->>'unit_id')::uuid;
  target_group uuid := (p_payload->>'group_id')::uuid;
  unit_link public.child_unit_links;
  group_link_id uuid;
  response jsonb;
begin
  response := app_private.student_link_receipt(p_request_id, actor, 'link');
  if response is not null then return response; end if;
  if target_unit is null then
    raise invalid_parameter_value using message='student link requires a unit';
  end if;
  institution := app_private.student_link_require_scope(
    p_child_context_id, target_unit, target_group);
  perform pg_advisory_xact_lock(hashtextextended(p_child_context_id::text, 0));

  -- Vincular a mesma crianca a mesma unidade de novo nao cria um segundo
  -- vinculo: reativa o que existe. A unicidade (child_context_id, unit_id) ja
  -- diz isso no schema; aqui a intencao vira reativacao explicita em vez de
  -- erro de chave.
  insert into public.child_unit_links(
    child_context_id, unit_id, status, accepted_by, accepted_at
  ) values (
    p_child_context_id, target_unit, 'active', actor, now()
  )
  on conflict (child_context_id, unit_id) do update set
    status = 'active',
    accepted_by = excluded.accepted_by,
    accepted_at = excluded.accepted_at,
    revoked_at = null,
    updated_at = now()
  returning * into unit_link;

  if target_group is not null then
    insert into public.child_group_links(
      child_unit_link_id, group_id, status, starts_at
    ) values (
      unit_link.id, target_group, 'active',
      coalesce((p_payload->>'starts_at')::timestamptz, now())
    )
    on conflict (child_unit_link_id, group_id) do update set
      status = 'active',
      starts_at = coalesce(excluded.starts_at, public.child_group_links.starts_at),
      ends_at = null,
      updated_at = now()
    returning id into group_link_id;
  end if;

  response := jsonb_build_object(
    'child_context_id', p_child_context_id,
    'unit_link_id', unit_link.id,
    'group_link_id', group_link_id,
    'status', unit_link.status
  );
  insert into app_private.student_link_command_receipts
    values (p_request_id, actor, 'link', unit_link.id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'student.link', 'child_unit_link',
    unit_link.id, institution, 'success', response
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_student_link"("p_request_id" "uuid", "p_child_context_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_student_links"("p_child_context_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  child_row public.child_contexts;
  child_name text;
begin
  if actor is null then
    raise insufficient_privilege using message='authentication required';
  end if;
  select * into child_row from public.child_contexts
  where id = p_child_context_id and status = 'active';
  if child_row.id is null then
    raise no_data_found using message='student link unavailable';
  end if;
  if not app_private.has_platform_permission('people.read')
    and not app_private.has_context_permission(
      child_row.institution_id, 'people.read', null, null, null,
      child_row.id, false
    ) then
    -- Mesma negativa da crianca ausente: distinguir confirmaria que ela existe
    -- em outra instituicao.
    raise no_data_found using message='student link unavailable';
  end if;
  select person_row.display_name into child_name
  from public.people person_row where person_row.id = child_row.child_person_id;

  return jsonb_build_object(
    'child_context_id', child_row.id,
    'child_person_id', child_row.child_person_id,
    'display_name', child_name,
    'institution_id', child_row.institution_id,
    'can_manage', app_private.has_platform_permission('people.assign_children')
      or app_private.has_context_permission(
        child_row.institution_id, 'people.assign_children', null, null, null,
        child_row.id, false),
    'unit_links', coalesce((
      select jsonb_agg(jsonb_build_object(
        'unit_link_id', unit_link.id,
        'unit_id', unit_link.unit_id,
        'unit_name', unit_row.name,
        'status', unit_link.status,
        'accepted_at', unit_link.accepted_at,
        'revoked_at', unit_link.revoked_at,
        'group_links', coalesce((
          select jsonb_agg(jsonb_build_object(
            'group_link_id', group_link.id,
            'group_id', group_link.group_id,
            'group_name', group_row.name,
            'status', group_link.status,
            'starts_at', group_link.starts_at,
            'ends_at', group_link.ends_at
          ) order by group_row.name)
          from public.child_group_links group_link
          join public.groups group_row on group_row.id = group_link.group_id
          where group_link.child_unit_link_id = unit_link.id), '[]'::jsonb)
      ) order by unit_row.name)
      from public.child_unit_links unit_link
      join public.units unit_row on unit_row.id = unit_link.unit_id
      where unit_link.child_context_id = child_row.id), '[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "app_private"."superadmin_student_links"("p_child_context_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_student_revoke"("p_request_id" "uuid", "p_child_context_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  institution uuid;
  target_unit uuid := (p_payload->>'unit_id')::uuid;
  reason text := nullif(btrim(coalesce(p_payload->>'reason','')), '');
  unit_link public.child_unit_links;
  before_state jsonb;
  response jsonb;
begin
  response := app_private.student_link_receipt(p_request_id, actor, 'revoke');
  if response is not null then return response; end if;
  if target_unit is null then
    raise invalid_parameter_value using message='student revoke requires a unit';
  end if;
  if reason is null then
    raise check_violation using message='revoke reason required';
  end if;
  institution := app_private.student_link_require_scope(
    p_child_context_id, target_unit, null);
  perform pg_advisory_xact_lock(hashtextextended(p_child_context_id::text, 0));

  select * into unit_link from public.child_unit_links
  where child_context_id = p_child_context_id and unit_id = target_unit
  for update;
  if unit_link.id is null or unit_link.status = 'revoked' then
    raise no_data_found using message='student link unavailable';
  end if;
  before_state := to_jsonb(unit_link);

  -- Revogar nao apaga: encerra as turmas e marca o vinculo, preservando o
  -- historico. Presenca, rotina e cuidado passados continuam apontando para um
  -- vinculo que existiu.
  update public.child_group_links set
    status = 'inactive', ends_at = coalesce(ends_at, now()), updated_at = now()
  where child_unit_link_id = unit_link.id and status = 'active';

  update public.child_unit_links set
    status = 'revoked', revoked_at = now(), updated_at = now()
  where id = unit_link.id returning * into unit_link;

  response := jsonb_build_object(
    'child_context_id', p_child_context_id,
    'unit_link_id', unit_link.id,
    'status', unit_link.status,
    'revoked_at', unit_link.revoked_at
  );
  insert into app_private.student_link_command_receipts
    values (p_request_id, actor, 'revoke', unit_link.id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, reason, before_json, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'student.revoke', 'child_unit_link',
    unit_link.id, institution, 'success', reason, before_state, response
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_student_revoke"("p_request_id" "uuid", "p_child_context_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_student_transfer"("p_request_id" "uuid", "p_child_context_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  institution uuid;
  origin_unit uuid := (p_payload->>'from_unit_id')::uuid;
  target_unit uuid := (p_payload->>'to_unit_id')::uuid;
  target_group uuid := (p_payload->>'to_group_id')::uuid;
  reason text := nullif(btrim(coalesce(p_payload->>'reason','')), '');
  origin_link public.child_unit_links;
  target_link public.child_unit_links;
  response jsonb;
begin
  response := app_private.student_link_receipt(p_request_id, actor, 'transfer');
  if response is not null then return response; end if;
  if origin_unit is null or target_unit is null then
    raise invalid_parameter_value using message='student transfer requires both units';
  end if;
  if origin_unit = target_unit then
    raise invalid_parameter_value using message='student transfer requires a different unit';
  end if;
  if reason is null then
    raise check_violation using message='transfer reason required';
  end if;
  -- Autoriza os DOIS lados: quem so pode gerir a unidade de destino nao pode
  -- retirar a crianca da unidade de origem.
  institution := app_private.student_link_require_scope(
    p_child_context_id, origin_unit, null);
  perform app_private.student_link_require_scope(
    p_child_context_id, target_unit, target_group);
  perform pg_advisory_xact_lock(hashtextextended(p_child_context_id::text, 0));

  select * into origin_link from public.child_unit_links
  where child_context_id = p_child_context_id and unit_id = origin_unit
  for update;
  if origin_link.id is null or origin_link.status not in ('active','awaiting_allocation') then
    raise no_data_found using message='student link unavailable';
  end if;

  -- As turmas da origem encerram junto: uma crianca transferida deixa de
  -- pertencer as turmas da unidade que deixou, senao continuaria aparecendo em
  -- chamada e rotina de uma unidade onde ja nao esta.
  update public.child_group_links set
    status = 'inactive', ends_at = coalesce(ends_at, now()), updated_at = now()
  where child_unit_link_id = origin_link.id and status = 'active';

  update public.child_unit_links set
    status = 'inactive', updated_at = now()
  where id = origin_link.id;

  insert into public.child_unit_links(
    child_context_id, unit_id, status, accepted_by, accepted_at
  ) values (
    p_child_context_id, target_unit, 'active', actor, now()
  )
  on conflict (child_context_id, unit_id) do update set
    status = 'active',
    accepted_by = excluded.accepted_by,
    accepted_at = excluded.accepted_at,
    revoked_at = null,
    updated_at = now()
  returning * into target_link;

  if target_group is not null then
    insert into public.child_group_links(
      child_unit_link_id, group_id, status, starts_at
    ) values (target_link.id, target_group, 'active', now())
    on conflict (child_unit_link_id, group_id) do update set
      status = 'active', ends_at = null, updated_at = now();
  end if;

  response := jsonb_build_object(
    'child_context_id', p_child_context_id,
    'from_unit_link_id', origin_link.id,
    'unit_link_id', target_link.id,
    'status', target_link.status
  );
  insert into app_private.student_link_command_receipts
    values (p_request_id, actor, 'transfer', target_link.id, response, now());
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, reason, before_json, after_json
  ) values (
    actor, auth.jwt()->>'aal', 'student.transfer', 'child_unit_link',
    target_link.id, institution, 'success', reason,
    to_jsonb(origin_link), response
  );
  return response;
end
$$;


ALTER FUNCTION "app_private"."superadmin_student_transfer"("p_request_id" "uuid", "p_child_context_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_unit_detail_payload_v2"("p_unit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id',unit_record.id,
    'name',unit_record.name,
    'slug',unit_record.slug,
    'handle',unit_record.handle,
    'handle_last_changed_at',unit_record.handle_last_changed_at,
    'status',unit_record.status,
    'institution',jsonb_build_object(
      'id',institution.id,
      'name',institution.public_name,
      'type',case when institution_type.id is null then null else
        jsonb_build_object(
          'id',institution_type.id,
          'name',institution_type.name
        )
      end
    ),
    'unit_type',jsonb_build_object(
      'id',unit_type.id,
      'name',unit_type.name
    ),
    'address',case when address.unit_id is null then null else
      jsonb_build_object(
        'country',address.country,
        'state',address.state,
        'city',address.city,
        'district',address.district,
        'street',address.street,
        'number',address.number,
        'complement',address.complement,
        'postal_code',address.postal_code
      )
    end,
    'contact',case when contact.unit_id is null then null else
      jsonb_build_object(
        'email',contact.email,
        'phone',contact.phone,
        'mobile_phone',contact.mobile_phone
      )
    end,
    'effective_plan',case when effective_plan.id is null then null else
      jsonb_build_object(
        'id',effective_plan.id,
        'code',effective_plan.code,
        'name',effective_plan.name,
        'inherited',unit_record.plan_override_id is null
      )
    end
  )
  from public.units unit_record
  join public.institutions institution
    on institution.id=unit_record.institution_id
   and institution.deleted_at is null
  -- Producao usa units.unit_type_id referenciando public.unit_types. A versao
  -- historica juntava institution_types por units.institution_type_id, coluna
  -- que nao existe la, e por isso o pacote nao aplicava sobre a baseline.
  join public.unit_types unit_type
    on unit_type.id=unit_record.unit_type_id
  left join public.institution_types institution_type
    on institution_type.id=institution.institution_type_id
  left join public.unit_addresses address
    on address.unit_id=unit_record.id
   and address.status<>'archived'
  left join public.unit_contacts contact
    on contact.unit_id=unit_record.id
   and contact.status<>'archived'
  left join lateral(
    select subscription.plan_id
    from public.institution_subscriptions subscription
    where subscription.institution_id=institution.id
    order by subscription.created_at desc,subscription.id desc
    limit 1
  ) latest_subscription on unit_record.plan_override_id is null
  left join public.plans effective_plan
    on effective_plan.id=coalesce(
      unit_record.plan_override_id,
      latest_subscription.plan_id
    )
  where unit_record.id=p_unit_id
$$;


ALTER FUNCTION "app_private"."superadmin_unit_detail_payload_v2"("p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_unit_export_page"("p_import_job_id" "uuid", "p_cursor_text" "text", "p_cursor_id" "uuid", "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  filters jsonb;
  view_data jsonb;
  result jsonb;
  cursor_offset bigint := 0;
  page_limit integer;
  sort_input text;
  sort_name text;
  uuid_regex constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  perform p_cursor_id; -- Compatibility parameter retained by the public RPC contract.
  actor := app_private.assert_unit_file_access('units.export', null);

  select *
  into job
  from public.import_jobs
  where id = p_import_job_id;

  if job.id is null then
    raise no_data_found using message = 'unit export not found';
  end if;
  if job.created_by <> actor or job.target_domain <> 'units_export' then
    raise insufficient_privilege using message = 'unit export outside actor scope';
  end if;
  if p_page_size not between 1 and 500 then
    raise invalid_parameter_value using message = 'invalid export page size';
  end if;

  if p_cursor_text is null or btrim(p_cursor_text) = '' then
    cursor_offset := 0;
  elsif btrim(p_cursor_text) !~ '^[0-9]+$' then
    raise invalid_parameter_value using message = 'invalid export cursor';
  else
    cursor_offset := btrim(p_cursor_text)::bigint;
  end if;
  if cursor_offset < 0 or cursor_offset > 2147483647 then
    raise invalid_parameter_value using message = 'invalid export cursor';
  end if;

  page_limit := least(p_page_size, 100);
  filters := coalesce(job.summary->'filters', '{}'::jsonb);
  view_data := coalesce(job.summary->'current_view', '{}'::jsonb);
  sort_input := coalesce(nullif(btrim(view_data->>'sort'), ''), 'name');
  sort_name := case sort_input
    when 'institution_type' then 'institution_type_name'
    when 'unit_type' then 'unit_type_name'
    when 'status' then 'unit_status'
    when 'plan' then 'plan_name'
    when 'groups' then 'groups_count'
    when 'activities' then 'activities_count'
    else sort_input
  end;
  if sort_name not in (
    'name',
    'institution_name',
    'institution_type_name',
    'unit_type_name',
    'unit_status',
    'plan_name',
    'groups_count',
    'activities_count',
    'updated_at'
  ) then
    sort_name := 'name';
  end if;

  result := app_private.list_units_for_superadmin(
    filters->>'search',
    coalesce(array(
      select value::uuid
      from jsonb_array_elements_text(coalesce(filters->'institution_ids', '[]'::jsonb)) value
      where value ~* uuid_regex
    ), array[]::uuid[]),
    coalesce(array(
      select value::uuid
      from jsonb_array_elements_text(coalesce(filters->'institution_type_ids', '[]'::jsonb)) value
      where value ~* uuid_regex
    ), array[]::uuid[]),
    coalesce(array(
      select value::uuid
      from jsonb_array_elements_text(coalesce(filters->'unit_type_ids', '[]'::jsonb)) value
      where value ~* uuid_regex
    ), array[]::uuid[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(
        coalesce(filters->'unit_statuses', coalesce(filters->'statuses', '[]'::jsonb))
      ) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(coalesce(filters->'plan_ids', '[]'::jsonb)) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(coalesce(filters->'states', '[]'::jsonb)) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(coalesce(filters->'cities', '[]'::jsonb)) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(coalesce(filters->'districts', '[]'::jsonb)) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    sort_name,
    coalesce((view_data->>'sort_ascending')::boolean, true),
    cursor_offset::integer,
    page_limit
  );

  if coalesce((result->>'has_more')::boolean, false)
    and jsonb_array_length(coalesce(result->'items', '[]'::jsonb)) > 0
  then
    result := result || jsonb_build_object(
      'next_cursor',
      jsonb_build_object(
        'text',
        (cursor_offset + jsonb_array_length(result->'items'))::text,
        'id',
        null
      )
    );
  end if;
  return result;
end
$_$;


ALTER FUNCTION "app_private"."superadmin_unit_export_page"("p_import_job_id" "uuid", "p_cursor_text" "text", "p_cursor_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_unit_export_page_v2"("p_export_job_id" "uuid", "p_after_ordinal" bigint, "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  items jsonb;
  last_ordinal bigint;
  total_count bigint;
  has_more boolean;
begin
  actor := app_private.assert_unit_file_access('units.export', null);

  if p_page_size not between 1 and 500 or coalesce(p_after_ordinal, 0) < 0 then
    raise invalid_parameter_value using message = 'invalid export keyset cursor';
  end if;

  select *
  into job
  from public.import_jobs
  where id = p_export_job_id;

  if job.id is null
    or job.target_domain <> 'units_export'
    or job.created_by <> actor
  then
    raise insufficient_privilege using message = 'unit export outside actor scope';
  end if;

  with page as (
    select ordinal, row_payload
    from app_private.unit_export_snapshot_rows
    where export_job_id = p_export_job_id
      and ordinal > coalesce(p_after_ordinal, 0)
    order by ordinal
    limit p_page_size
  )
  select coalesce(jsonb_agg(row_payload order by ordinal), '[]'::jsonb), max(ordinal)
  into items, last_ordinal
  from page;

  select count(*)
  into total_count
  from app_private.unit_export_snapshot_rows
  where export_job_id = p_export_job_id;

  has_more := last_ordinal is not null and exists (
    select 1
    from app_private.unit_export_snapshot_rows
    where export_job_id = p_export_job_id
      and ordinal > last_ordinal
  );

  return jsonb_build_object(
    'items', items,
    'total_count', total_count,
    'has_more', has_more,
    'next_cursor', case
      when has_more then jsonb_build_object('ordinal', last_ordinal)
      else null
    end
  );
end;
$$;


ALTER FUNCTION "app_private"."superadmin_unit_export_page_v2"("p_export_job_id" "uuid", "p_after_ordinal" bigint, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_unit_identity_download_descriptor"("media_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$declare media public.unit_identity_media%rowtype;begin
 select*into media from public.unit_identity_media m where m.id=media_id and m.status='active';
 if media.id is null then raise no_data_found using message='unit identity media not found';end if;
 if(select auth.uid())is null or not app_private.has_scoped_platform_permission('units.read',media.institution_id)
 then raise insufficient_privilege using message='units.read required';end if;
 return jsonb_build_object('media_id',media.id,'bucket',media.storage_bucket,'path',media.storage_path,'signed_url_ttl_seconds',300);end$$;


ALTER FUNCTION "app_private"."superadmin_unit_identity_download_descriptor"("media_id" "uuid") OWNER TO "postgres";


