CREATE OR REPLACE FUNCTION "public"."authorize_moments_media_finalize"("p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor record;
  asset public.moments_media_assets%rowtype;
  target public.moments_publications%rowtype;
  finalize_ticket uuid := gen_random_uuid();
  ticket_expires_at timestamptz := now() + interval '2 minutes';
begin
  select * into asset from public.moments_media_assets media
  where media.id = p_asset_id and media.status in ('pending', 'ready');
  if asset.id is null then
    raise insufficient_privilege using message = 'asset_not_authorized';
  end if;
  select * into target from public.moments_publications publication
  where publication.id = asset.publication_id and publication.status = 'draft';
  if target.id is null then
    raise insufficient_privilege using message = 'publication_not_authorized';
  end if;
  select * into actor from app_private.moments_actor(
    asset.institution_id, 'moments.publications.create', target.unit_id, target.group_id
  );
  if asset.owner_person_id <> actor.person_id or target.author_person_id <> actor.person_id then
    raise insufficient_privilege using message = 'asset_not_authorized';
  end if;

  delete from app_private.moments_media_finalize_tickets ticket
  where ticket.expires_at <= now();
  delete from app_private.moments_media_finalize_tickets ticket
  where ticket.asset_id = asset.id
    and ticket.actor_person_id = actor.person_id;
  insert into app_private.moments_media_finalize_tickets (
    token_hash, asset_id, actor_person_id, expires_at
  ) values (
    app_private.moments_request_fingerprint(to_jsonb(finalize_ticket::text)),
    asset.id,
    actor.person_id,
    ticket_expires_at
  );
  return jsonb_build_object(
    'finalize_ticket', finalize_ticket,
    'expires_at', ticket_expires_at
  );
end
$$;


ALTER FUNCTION "public"."authorize_moments_media_finalize"("p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."authorize_moments_media_read"("p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  asset public.moments_media_assets%rowtype;
  target public.moments_publications%rowtype;
  actor record;
  actor_role text;
  is_author boolean := false;
  is_consumer boolean := false;
begin
  if (select auth.uid()) is null then
    raise insufficient_privilege using message = 'authentication_required';
  end if;
  select * into asset from public.moments_media_assets media
  where media.id = p_asset_id and media.status = 'ready';
  if asset.id is null then
    raise insufficient_privilege using message = 'asset_not_authorized';
  end if;
  select * into target from public.moments_publications publication
  where publication.id = asset.publication_id;
  if target.id is null then
    raise insufficient_privilege using message = 'asset_not_authorized';
  end if;

  if app_private.has_institution_permission(
    asset.institution_id, 'moments.publications.create',
    target.unit_id, target.group_id, false
  ) then
    select * into actor from app_private.moments_actor(
      asset.institution_id, 'moments.publications.create',
      target.unit_id, target.group_id
    );
    is_author := target.author_person_id = actor.person_id;
  end if;

  if not is_author
    and target.status = 'published'
    and target.withdrawn_at is null
    and app_private.has_institution_permission(
      asset.institution_id, 'moments.publications.read',
      target.unit_id, target.group_id, false
    )
  then
    select * into actor from app_private.moments_actor(
      asset.institution_id, 'moments.publications.read',
      target.unit_id, target.group_id
    );
    select lower(membership.role_code) into actor_role
    from public.institution_memberships membership
    where membership.id = actor.membership_id;
    is_consumer := exists (
      select 1
      from public.moments_publication_audiences audience
      where audience.publication_id = target.id
        and audience.institution_id = target.institution_id
        and audience.unit_id is not distinct from target.unit_id
        and audience.group_id is not distinct from target.group_id
        and app_private.moments_audience_matches_role(actor_role, audience.audience_kind)
    );
  end if;

  if not (is_author or is_consumer) then
    raise insufficient_privilege using message = 'asset_not_authorized';
  end if;

  return jsonb_build_object(
    'asset_id', asset.id,
    'object_key', asset.object_key,
    'mime_type', asset.mime_type
  );
end
$$;


ALTER FUNCTION "public"."authorize_moments_media_read"("p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."authorize_now_asset_read"("p_institution_id" "uuid", "p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare asset public.now_media_assets%rowtype;target public.now_publications%rowtype;actor record;
begin
  select * into asset from public.now_media_assets where id=p_asset_id and institution_id=p_institution_id and status='ready';
  if asset.id is null then raise insufficient_privilege using message='asset_not_authorized';end if;
  select * into target from public.now_publications where id=asset.publication_id and status='draft';
  if target.id is null then raise insufficient_privilege using message='asset_not_authorized';end if;
  select * into actor from app_private.now_actor(p_institution_id,'now.publications.create',target.unit_id,target.group_id);
  if asset.owner_person_id<>actor.person_id then raise insufficient_privilege using message='asset_not_authorized';end if;
  return jsonb_build_object(
    'storage_provider',asset.storage_provider,
    'bucket_id',asset.bucket_id,
    'object_key',asset.object_key,
    'mime_type',asset.mime_type
  );
end $$;


