CREATE OR REPLACE FUNCTION "public"."check_institution_handle_availability"("p_handle" "text", "p_excluding_institution_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare normalized text;
begin
  if (select auth.uid()) is null or app_private.current_person_id() is null
     or not app_private.has_platform_permission('institution.update') then
    raise insufficient_privilege using message='institution handle permission required';
  end if;
  normalized:=app_private.normalize_institution_handle(p_handle);
  if normalized !~ '^[a-z0-9][a-z0-9._-]{2,29}$' then return false; end if;
  return not exists(
    select 1 from public.institutions i
    where i.slug=normalized
      and i.deleted_at is null
      and (p_excluding_institution_id is null or i.id<>p_excluding_institution_id)
  );
end
$_$;


