CREATE OR REPLACE FUNCTION "public"."delete_circular"("p_request_id" "uuid", "p_circular_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target public.circulars%rowtype; actor record; response jsonb; fingerprint text; prior_fingerprint text;
begin
  select * into target from public.circulars c where c.id=p_circular_id for update;
  if target.id is null then raise insufficient_privilege using message='circular_not_found'; end if;
  select * into actor from app_private.circular_actor(target.institution_id,'circulars.circulars.create',target.unit_id,target.group_id);
  if target.author_person_id<>actor.person_id and not app_private.has_institution_permission(target.institution_id,'circulars.circulars.manage',target.unit_id,target.group_id,false)
  then raise insufficient_privilege using message='circular_manage_denied'; end if;
  fingerprint:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_circular_id::text||p_expected_version::text,'UTF8'),'sha256'),'hex');
  select receipt.response,receipt.request_fingerprint into response,prior_fingerprint
  from app_private.circular_command_receipts receipt
  where receipt.actor_person_id=actor.person_id and receipt.command_name='delete' and receipt.request_id=p_request_id;
  if response is not null then
    if prior_fingerprint<>fingerprint then raise unique_violation using message='request_id_conflict'; end if;
    return response;
  end if;
  if target.deleted_at is not null or target.management_version<>p_expected_version then raise serialization_failure using message='expected_version_conflict'; end if;
  if target.current_revision_id is null and not exists(select 1 from public.circular_response_sessions session where session.circular_id=target.id) then
    update public.circular_media_assets set status='orphaned' where circular_id=target.id and status in ('pending','ready');
  end if;
  update public.circulars set status='archived',deleted_at=now(),management_version=management_version+1,updated_at=now()
  where id=target.id returning * into target;
  response:=jsonb_build_object('id',target.id,'version',target.management_version,'status',target.status,'deleted',true);
  insert into app_private.circular_command_receipts(actor_person_id,command_name,request_id,request_fingerprint,response)
  values(actor.person_id,'delete',p_request_id,fingerprint,response);
  insert into app_private.circular_audit(circular_id,revision_id,institution_id,actor_person_id,event_code,detail)
  values(target.id,target.current_revision_id,target.institution_id,actor.person_id,'circular_deleted',jsonb_build_object('logical',true));
  return response;
end $$;


ALTER FUNCTION "public"."delete_circular"("p_request_id" "uuid", "p_circular_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_due_now_publications"("p_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor record;
  transitioned integer;
begin
  if p_institution_id is null then
    raise insufficient_privilege using message='context_not_authorized';
  end if;
  select * into actor
  from app_private.now_actor(p_institution_id,'now.publications.publish',null,null);
  transitioned:=app_private.sweep_expired_now_publications(p_institution_id,500);
  insert into app_private.now_publication_audit(
    publication_id,institution_id,actor_person_id,event_code,detail
  )
  values(
    null,
    p_institution_id,
    actor.person_id,
    'expiry_sweep_requested',
    jsonb_build_object('expired_count',transitioned)
  );
  return jsonb_build_object(
    'institution_id',p_institution_id,
    'expired_count',transitioned
  );
end
$$;


ALTER FUNCTION "public"."expire_due_now_publications"("p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_circular_media_upload"("p_asset_id" "uuid", "p_finalize_ticket" "uuid", "p_expected_byte_size" bigint, "p_expected_mime_type" "text", "p_checksum_sha256" "text", "p_etag" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare asset public.circular_media_assets%rowtype;
begin
  select * into asset from public.circular_media_assets m where m.id=p_asset_id for update;
  if asset.status='ready' and asset.byte_size=p_expected_byte_size and asset.mime_type=p_expected_mime_type then
    return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'bucket_id',asset.bucket_id,'object_key',asset.object_key,'status',asset.status);
  end if;
  if asset.id is null or asset.status<>'pending' or asset.finalize_ticket<>p_finalize_ticket or asset.finalize_ticket_expires_at<=now()
    or asset.byte_size<>p_expected_byte_size or asset.mime_type<>p_expected_mime_type
  then raise insufficient_privilege using message='media_finalize_denied'; end if;
  if asset.storage_provider='r2' and (p_checksum_sha256 is null or p_checksum_sha256 !~ '^[0-9a-f]{64}$')
  then raise check_violation using message='media_checksum_required'; end if;
  update public.circular_media_assets set status='ready',checksum_sha256=p_checksum_sha256,etag=p_etag,finalized_at=now(),finalize_ticket=null,finalize_ticket_expires_at=null where id=asset.id returning * into asset;
  return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'bucket_id',asset.bucket_id,'object_key',asset.object_key,'status',asset.status);
end $_$;


ALTER FUNCTION "public"."finalize_circular_media_upload"("p_asset_id" "uuid", "p_finalize_ticket" "uuid", "p_expected_byte_size" bigint, "p_expected_mime_type" "text", "p_checksum_sha256" "text", "p_etag" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_happens_media_upload"("p_asset_id" "uuid", "p_post_id" "uuid", "p_checksum_sha256" "text", "p_display_order" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  asset public.media_assets%rowtype;
  actor record;
  target public.posts%rowtype;
begin
  select * into asset
  from public.media_assets
  where id=p_asset_id and post_id=p_post_id
  for update;
  if asset.id is null then
    raise insufficient_privilege using message='asset_not_authorized';
  end if;

  select * into target
  from public.posts
  where id=p_post_id and institution_id=asset.institution_id and status='draft'
  for update;
  if target.id is null then
    raise insufficient_privilege using message='media_not_uploaded';
  end if;

  select * into actor
  from app_private.happens_actor(
    asset.institution_id,'happens.posts.create',target.unit_id,target.group_id
  );
  if asset.owner_person_id<>actor.person_id or target.author_person_id<>actor.person_id then
    raise insufficient_privilege using message='media_not_uploaded';
  end if;

  if exists(
    select 1 from public.media_links
    where post_id=target.id
      and media_asset_id=asset.id
      and display_order=p_display_order::smallint
  ) and asset.status='ready' then
    return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'object_key',asset.object_key);
  end if;

  if asset.storage_provider='r2' and (p_checksum_sha256 is null or p_checksum_sha256 !~ '^[0-9a-f]{64}$') then
    raise check_violation using message='media_checksum_required';
  end if;

  if asset.status<>'pending' or exists(
    select 1 from public.media_links
    where post_id=target.id
      and (media_asset_id=asset.id or display_order=p_display_order::smallint)
  ) or (asset.storage_provider<>'r2' and not exists(
    select 1 from storage.objects
    where bucket_id=asset.bucket_id and name=asset.object_key
  )) then
    raise check_violation using message='media_finalize_conflict';
  end if;

  update public.media_assets
  set checksum_sha256=p_checksum_sha256,status='ready',finalized_at=now()
  where id=asset.id;
  insert into public.media_links(post_id,media_asset_id,display_order)
  values(target.id,asset.id,p_display_order::smallint);
  return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'object_key',asset.object_key);
end
$_$;


ALTER FUNCTION "public"."finalize_happens_media_upload"("p_asset_id" "uuid", "p_post_id" "uuid", "p_checksum_sha256" "text", "p_display_order" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_moments_media_upload"("p_request_id" "uuid", "p_asset_id" "uuid", "p_finalize_ticket" "uuid", "p_expected_byte_size" bigint, "p_expected_mime_type" "text", "p_checksum_sha256" "text", "p_etag" "text", "p_display_order" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  asset public.moments_media_assets%rowtype;
  target public.moments_publications%rowtype;
  consumed_ticket app_private.moments_media_finalize_tickets%rowtype;
  fingerprint text;
  prior record;
  receipt_id uuid := gen_random_uuid();
  result jsonb;
begin
  select * into asset from public.moments_media_assets media
  where media.id = p_asset_id for update;
  if asset.id is null then raise insufficient_privilege using message = 'asset_not_authorized'; end if;
  select * into target from public.moments_publications publication
  where publication.id = asset.publication_id and publication.status = 'draft';
  if target.id is null then raise insufficient_privilege using message = 'publication_not_authorized'; end if;
  if asset.owner_person_id <> target.author_person_id then
    raise insufficient_privilege using message = 'asset_not_authorized';
  end if;
  if p_expected_byte_size <> asset.byte_size or p_expected_mime_type <> asset.mime_type then
    raise check_violation using message = 'uploaded_media_mismatch';
  end if;
  if p_display_order not between 0 and 4 then
    raise check_violation using message = 'display_order_invalid';
  end if;

  fingerprint := app_private.moments_request_fingerprint(jsonb_build_object(
    'asset_id', p_asset_id,
    'expected_byte_size', p_expected_byte_size,
    'expected_mime_type', p_expected_mime_type,
    'checksum_sha256', p_checksum_sha256,
    'etag', p_etag,
    'display_order', p_display_order
  ));
  perform pg_advisory_xact_lock(
    hashtextextended(asset.owner_person_id::text || p_request_id::text, 0)
  );
  select receipt.request_fingerprint, receipt.response into prior
  from app_private.moments_command_receipts receipt
  where receipt.actor_person_id = asset.owner_person_id
    and receipt.command_name = 'finalize_media'
    and receipt.request_id = p_request_id;
  if prior.response is not null then
    if prior.request_fingerprint <> fingerprint then
      raise unique_violation using message = 'idempotency_key_reused';
    end if;
    return prior.response;
  end if;

  if asset.status <> 'pending' then
    raise object_not_in_prerequisite_state using message = 'asset_not_pending';
  end if;

  delete from app_private.moments_media_finalize_tickets ticket
  where ticket.token_hash = app_private.moments_request_fingerprint(
      to_jsonb(p_finalize_ticket::text)
    )
    and ticket.asset_id = asset.id
    and ticket.actor_person_id = asset.owner_person_id
    and ticket.expires_at > now()
  returning ticket.* into consumed_ticket;
  if consumed_ticket.asset_id is null then
    raise insufficient_privilege using message = 'finalize_ticket_invalid';
  end if;

  if asset.status = 'ready' then raise unique_violation using message = 'asset_already_finalized'; end if;
  if p_checksum_sha256 is not null and p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise check_violation using message = 'checksum_invalid';
  end if;
  update public.moments_media_assets replaced set
    status = 'orphaned',
    cleanup_attempted_at = null
  from public.moments_media_links existing_link
  where existing_link.publication_id = target.id
    and existing_link.display_order = p_display_order
    and existing_link.media_asset_id <> asset.id
    and replaced.id = existing_link.media_asset_id
    and replaced.status = 'ready';
  delete from public.moments_media_links link
  where link.publication_id = target.id and link.display_order = p_display_order;
  update public.moments_media_assets set
    checksum_sha256 = p_checksum_sha256,
    etag = nullif(p_etag, ''),
    status = 'ready',
    finalized_at = now()
  where id = asset.id;
  insert into public.moments_media_links (publication_id, media_asset_id, display_order)
  values (target.id, asset.id, p_display_order::smallint)
  on conflict (publication_id, media_asset_id) do update
    set display_order = excluded.display_order;

  result := jsonb_build_object(
    'asset_id', asset.id,
    'object_key', asset.object_key,
    'receipt_id', receipt_id
  );
  insert into app_private.moments_command_receipts (
    id, actor_person_id, institution_id, command_name,
    request_id, request_fingerprint, response
  ) values (
    receipt_id, asset.owner_person_id, asset.institution_id, 'finalize_media',
    p_request_id, fingerprint, result
  );
  insert into app_private.moments_publication_audit (
    publication_id, institution_id, actor_person_id, receipt_id, event_code, detail
  ) values (
    target.id, asset.institution_id, asset.owner_person_id, receipt_id,
    'media_upload_finalized', jsonb_build_object('asset_id', asset.id)
  );
  return result;
end
$_$;


ALTER FUNCTION "public"."finalize_moments_media_upload"("p_request_id" "uuid", "p_asset_id" "uuid", "p_finalize_ticket" "uuid", "p_expected_byte_size" bigint, "p_expected_mime_type" "text", "p_checksum_sha256" "text", "p_etag" "text", "p_display_order" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_now_asset_upload"("p_asset_id" "uuid", "p_checksum_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare asset public.now_media_assets%rowtype;target public.now_publications%rowtype;actor record;
begin
  select * into asset from public.now_media_assets where id=p_asset_id for update;
  if asset.id is null then raise insufficient_privilege using message='asset_not_authorized';end if;
  select * into target from public.now_publications where id=asset.publication_id;
  select * into actor from app_private.now_actor(asset.institution_id,'now.publications.create',target.unit_id,target.group_id);
  if asset.owner_person_id<>actor.person_id or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
    or (asset.storage_provider<>'r2' and not exists(select 1 from storage.objects where bucket_id=asset.bucket_id and name=asset.object_key))
  then raise insufficient_privilege using message='asset_not_uploaded';end if;
  update public.now_media_assets set checksum_sha256=p_checksum_sha256,status='ready',finalized_at=now() where id=p_asset_id;
  return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'object_key',asset.object_key);
end $_$;


ALTER FUNCTION "public"."finalize_now_asset_upload"("p_asset_id" "uuid", "p_checksum_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."follow_followers_list"("p_target_kind" "text", "p_target_id" "uuid", "p_limit" integer DEFAULT 50, "p_after_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  kind public.follow_target_kind := app_private.follow_target_kind_of(p_target_kind);
  safe_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
begin
  if (select auth.uid()) is null or not app_private.has_platform_permission('people.read') then
    raise insufficient_privilege using message = 'follow list permission denied';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', link.id, 'person_id', link.follower_person_id,
      'display_name', person.display_name, 'person_type', person.person_type,
      'origin', link.origin, 'since', link.created_at
    ) order by link.created_at desc, link.id)
    from (
      select * from public.follow_links link
      where link.target_kind = kind and link.target_id = p_target_id and link.status = 'active'
        and (p_after_id is null or link.id > p_after_id)
      order by link.created_at desc, link.id
      limit safe_limit
    ) link
    join public.people person on person.id = link.follower_person_id
  ), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."follow_followers_list"("p_target_kind" "text", "p_target_id" "uuid", "p_limit" integer, "p_after_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."follow_following_list"("p_person_id" "uuid", "p_limit" integer DEFAULT 50, "p_after_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := app_private.current_person_id();
  safe_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
begin
  if (select auth.uid()) is null
     or not (actor = p_person_id or app_private.has_platform_permission('people.read')) then
    raise insufficient_privilege using message = 'follow list permission denied';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', link.id, 'target_kind', link.target_kind, 'target_id', link.target_id,
      'origin', link.origin, 'since', link.created_at
    ) order by link.created_at desc, link.id)
    from (
      select * from public.follow_links link
      where link.follower_person_id = p_person_id and link.status = 'active'
        and (p_after_id is null or link.id > p_after_id)
      order by link.created_at desc, link.id
      limit safe_limit
    ) link
  ), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."follow_following_list"("p_person_id" "uuid", "p_limit" integer, "p_after_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."follow_set"("p_target_kind" "text", "p_target_id" "uuid", "p_follow" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  kind public.follow_target_kind := app_private.follow_target_kind_of(p_target_kind);
  actor uuid := app_private.current_person_id();
  target_exists boolean;
begin
  if (select auth.uid()) is null or actor is null then
    raise insufficient_privilege using message = 'follow requires an identified person';
  end if;
  if kind = 'person' and p_target_id = actor then
    raise invalid_parameter_value using message = 'a person cannot follow themselves';
  end if;
  target_exists := case kind
    when 'institution' then exists(select 1 from public.institutions x where x.id = p_target_id)
    when 'unit' then exists(select 1 from public.units x where x.id = p_target_id)
    when 'group' then exists(select 1 from public.groups x where x.id = p_target_id)
    when 'person' then exists(select 1 from public.people x where x.id = p_target_id)
  end;
  if not target_exists then
    raise no_data_found using message = 'follow target not found';
  end if;
  if p_follow then
    insert into public.follow_links (follower_person_id, target_kind, target_id, origin)
    select actor, kind, p_target_id, 'manual'
    where not exists (
      select 1 from public.follow_links link
      where link.follower_person_id = actor and link.target_kind = kind
        and link.target_id = p_target_id and link.origin = 'manual' and link.status = 'active'
    );
  else
    update public.follow_links link
    set status = 'inactive', revoked_at = now(), updated_at = now()
    where link.follower_person_id = actor and link.target_kind = kind
      and link.target_id = p_target_id and link.origin = 'manual' and link.status = 'active';
  end if;
  return public.follow_summary(p_target_kind, p_target_id)
    || jsonb_build_object('following', exists(
      select 1 from public.follow_links link
      where link.follower_person_id = actor and link.target_kind = kind
        and link.target_id = p_target_id and link.status = 'active'));
end $$;


ALTER FUNCTION "public"."follow_set"("p_target_kind" "text", "p_target_id" "uuid", "p_follow" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."follow_summary"("p_target_kind" "text", "p_target_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  kind public.follow_target_kind := app_private.follow_target_kind_of(p_target_kind);
  followers_count bigint;
  following_count bigint;
begin
  if (select auth.uid()) is null then
    raise insufficient_privilege using message = 'follow summary requires a session';
  end if;
  select count(distinct link.follower_person_id) into followers_count
  from public.follow_links link
  where link.target_kind = kind and link.target_id = p_target_id and link.status = 'active';
  if kind = 'person' then
    select count(distinct (link.target_kind, link.target_id)) into following_count
    from public.follow_links link
    where link.follower_person_id = p_target_id and link.status = 'active';
  end if;
  return jsonb_build_object(
    'target_kind', kind, 'target_id', p_target_id,
    'followers_count', followers_count,
    'following_count', following_count
  );
end $$;


