CREATE OR REPLACE FUNCTION "public"."form_media_authorize_for_worker"("p_asset_id" "uuid", "p_actor_person_id" "uuid", "p_edit_secret" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare asset_row public.form_assets;
begin
  select * into asset_row from public.form_assets
   where id = p_asset_id and state in ('uploaded', 'finalized');
  if asset_row.id is null or (
    (asset_row.prepared_by_person_id = p_actor_person_id)
    or (
      asset_row.prepared_by_person_id is null
      and app_private.form_verify_anonymous_edit_secret(
        p_edit_secret, asset_row.anonymous_upload_secret_hash
      )
    )
    or (asset_row.state = 'finalized'
      and exists (
        select 1 from public.form_answer_assets answer_asset
         where answer_asset.asset_id = asset_row.id
      )
      and app_private.audit_actor_has_permission(
        p_actor_person_id, 'forms.responses.read', asset_row.institution_id, false
      ))
  ) is not true then
    raise no_data_found using message = 'form asset unavailable';
  end if;
  return jsonb_build_object(
    'asset_id', asset_row.id, 'storage_path', asset_row.storage_path,
    'mime_type', asset_row.mime_type, 'byte_length', asset_row.actual_byte_length,
    'state', asset_row.state
  );
end;
$$;


ALTER FUNCTION "public"."form_media_authorize_for_worker"("p_asset_id" "uuid", "p_actor_person_id" "uuid", "p_edit_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."form_media_claim_cleanup_r2_v1"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare items jsonb;
begin
  perform app_private.form_media_assert_worker_v1();
  with claimed as (
    select c.id from app_private.form_media_r2_cleanup c
    where c.purged_at is null and (c.claimed_at is null or c.claimed_at < now() - interval '10 minutes')
    order by c.queued_at limit least(greatest(coalesce(p_limit, 50), 1), 200) for update skip locked
  ), updated as (
    update app_private.form_media_r2_cleanup c set claimed_at = now() from claimed where c.id = claimed.id
    returning c.id, c.bucket_id, c.object_key
  )
  select coalesce(jsonb_agg(jsonb_build_object('cleanup_id', u.id, 'bucket', u.bucket_id, 'object_key', u.object_key)), '[]'::jsonb)
  into items from updated u;
  return app_private.form_media_success_v1(jsonb_build_object('items', items));
exception when insufficient_privilege then
  return app_private.form_media_envelope_error_v1('SAI_PERMISSION_DENIED', gen_random_uuid());
end $$;


ALTER FUNCTION "public"."form_media_claim_cleanup_r2_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."form_media_expire_question_r2_v1"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare expired integer := 0; item record;
begin
  perform app_private.form_media_assert_worker_v1();
  for item in
    select t.asset_id, a.bucket_id, a.object_key from app_private.form_media_upload_tickets t
    join public.media_assets a on a.id = t.asset_id
    where t.used_at is null and t.expires_at < now() and a.status = 'pending'
    order by t.expires_at limit least(greatest(coalesce(p_limit, 100), 1), 500) for update of t skip locked
  loop
    update public.media_assets set status = 'deleted' where id = item.asset_id;
    insert into app_private.form_media_r2_cleanup(asset_id, bucket_id, object_key, reason)
    values (item.asset_id, item.bucket_id, item.object_key, 'expired') on conflict do nothing;
    update app_private.form_media_upload_tickets set used_at = now() where asset_id = item.asset_id;
    expired := expired + 1;
  end loop;
  return app_private.form_media_success_v1(jsonb_build_object('expired', expired));
exception when insufficient_privilege then
  return app_private.form_media_envelope_error_v1('SAI_PERMISSION_DENIED', gen_random_uuid());
end $$;


ALTER FUNCTION "public"."form_media_expire_question_r2_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."form_media_finalize_answer_r2_v1"("p_asset_id" "uuid", "p_byte_size" bigint, "p_checksum_sha256" "text", "p_pixel_width" integer, "p_pixel_height" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare source public.form_assets%rowtype; asset public.media_assets%rowtype; worker jsonb; sha text := lower(btrim(coalesce(p_checksum_sha256,'')));
begin
  perform app_private.form_media_assert_worker_v1();
  select * into source from public.form_assets where id = p_asset_id for update;
  if source.id is null then return app_private.form_media_envelope_error_v1('FORM_MEDIA_NOT_FOUND', gen_random_uuid()); end if;
  select * into asset from public.media_assets where source_form_asset_id = source.id and status <> 'deleted' for update;
  if asset.id is null then return app_private.form_media_envelope_error_v1('FORM_MEDIA_NOT_FOUND', gen_random_uuid()); end if;
  if source.state = 'finalized' and asset.status = 'ready' then
    return app_private.form_media_success_v1(jsonb_build_object('asset_id', source.id, 'media_asset_id', asset.id,
      'state', 'finalized', 'media_status', 'ready', 'replayed', true));
  end if;
  -- o legado decide finalized/discarded pelas medidas; dimensoes so entram no catalogo
  worker := app_private.form_finalize_asset_for_worker(source.id, p_byte_size, source.mime_type, sha);
  if worker ->> 'state' <> 'finalized'
    or p_pixel_width is null or p_pixel_height is null
    or p_pixel_width not between 1 and 2560 or p_pixel_height not between 1 and 2560 then
    if worker ->> 'state' = 'finalized' then
      -- medidas certas mas pixels invalidos: descarta o legado tambem
      update public.form_assets set state = 'discarded', discarded_at = now() where id = source.id;
    end if;
    -- o gatilho de discard ja marcou o espelho e a fila
    return app_private.form_media_envelope_error_v1('FORM_MEDIA_MISMATCH', gen_random_uuid());
  end if;
  update public.media_assets set byte_size = p_byte_size, checksum_sha256 = sha,
    pixel_width = p_pixel_width, pixel_height = p_pixel_height, status = 'ready', finalized_at = now()
  where id = asset.id returning * into asset;
  insert into public.media_variants(media_asset_id, rendition, bucket_id, object_key, mime_type,
    byte_size, checksum_sha256, pixel_width, pixel_height)
  values (asset.id, 'original', asset.bucket_id, asset.object_key, asset.mime_type,
    asset.byte_size, asset.checksum_sha256, asset.pixel_width, asset.pixel_height);
  return app_private.form_media_success_v1(jsonb_build_object('asset_id', source.id, 'media_asset_id', asset.id,
    'state', 'finalized', 'media_status', 'ready', 'replayed', false));
exception when insufficient_privilege then
  return app_private.form_media_envelope_error_v1('SAI_PERMISSION_DENIED', gen_random_uuid());
end $$;


ALTER FUNCTION "public"."form_media_finalize_answer_r2_v1"("p_asset_id" "uuid", "p_byte_size" bigint, "p_checksum_sha256" "text", "p_pixel_width" integer, "p_pixel_height" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."form_media_finalize_question_r2_v1"("p_asset_id" "uuid", "p_finalize_ticket" "uuid", "p_byte_size" bigint, "p_checksum_sha256" "text", "p_pixel_width" integer, "p_pixel_height" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare correlation uuid := gen_random_uuid(); code text; mismatch boolean := false; replayed boolean := false;
  ticket app_private.form_media_upload_tickets%rowtype; asset public.media_assets%rowtype;
  sha text := lower(btrim(coalesce(p_checksum_sha256, '')));
begin
  begin
    if coalesce(nullif(current_setting('request.jwt.claim.role', true), ''),
        nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') <> 'service_role' then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    select * into ticket from app_private.form_media_upload_tickets t
    where t.asset_id = p_asset_id and t.finalize_ticket = p_finalize_ticket for update;
    if ticket.asset_id is null then raise no_data_found using detail='FORM_MEDIA_NOT_FOUND'; end if;
    select * into asset from public.media_assets where id = p_asset_id for update;

    if ticket.used_at is not null then
      if asset.status = 'ready'
        and p_byte_size is not distinct from asset.byte_size
        and sha is not distinct from asset.checksum_sha256
        and p_pixel_width is not distinct from asset.pixel_width
        and p_pixel_height is not distinct from asset.pixel_height
        and exists (
          select 1 from public.media_variants variant
          where variant.media_asset_id = asset.id and variant.rendition = 'original'
            and variant.byte_size is not distinct from asset.byte_size
            and variant.checksum_sha256 is not distinct from asset.checksum_sha256
            and variant.pixel_width is not distinct from asset.pixel_width
            and variant.pixel_height is not distinct from asset.pixel_height
        ) then
        replayed := true;
      else
        raise object_not_in_prerequisite_state using detail='FORM_MEDIA_TICKET_INVALID';
      end if;
    elsif ticket.expires_at < now() or asset.status <> 'pending' then
      raise object_not_in_prerequisite_state using detail='FORM_MEDIA_TICKET_INVALID';
    else
      if p_byte_size is distinct from ticket.expected_byte_size or sha is distinct from ticket.expected_sha256
        or p_pixel_width is null or p_pixel_height is null
        or p_pixel_width not between 1 and 2560 or p_pixel_height not between 1 and 2560 then
        mismatch := true;
      end if;
      if not mismatch then
        update public.media_assets set byte_size = p_byte_size, checksum_sha256 = sha,
          pixel_width = p_pixel_width, pixel_height = p_pixel_height, status = 'ready', finalized_at = now()
        where id = asset.id returning * into asset;
        insert into public.media_variants(media_asset_id, rendition, bucket_id, object_key, mime_type,
          byte_size, checksum_sha256, pixel_width, pixel_height)
        values (asset.id, 'original', asset.bucket_id, asset.object_key, asset.mime_type,
          asset.byte_size, asset.checksum_sha256, asset.pixel_width, asset.pixel_height);
        update app_private.form_media_upload_tickets set used_at = now() where asset_id = asset.id;
        perform app_private.audit_append_superadmin_internal(ticket.internal_identity_id, ticket.internal_auth_link_id,
          ticket.internal_membership_id, ticket.session_id, 'forms.manage', 'aal1', 'forms.media.finalize', 'success',
          null, correlation, ticket.institution_id, 'media_asset', asset.id);
      end if;
    end if;
  exception when others then
    get stacked diagnostics code = pg_exception_detail;
    code := coalesce(nullif(code, ''), 'SAI_INTERNAL_ERROR');
  end;
  if code is null and mismatch then
    update public.media_assets set status = 'deleted' where id = asset.id;
    insert into app_private.form_media_r2_cleanup(asset_id, bucket_id, object_key, reason)
    values (asset.id, asset.bucket_id, asset.object_key, 'mismatch') on conflict do nothing;
    update app_private.form_media_upload_tickets set used_at = now() where asset_id = asset.id;
    perform app_private.audit_append_superadmin_internal(ticket.internal_identity_id, ticket.internal_auth_link_id,
      ticket.internal_membership_id, ticket.session_id, 'forms.manage', 'aal1', 'forms.media.finalize', 'failed',
      'FORM_MEDIA_MISMATCH', correlation, ticket.institution_id, 'media_asset', asset.id);
    code := 'FORM_MEDIA_MISMATCH';
  end if;
  if code is not null then return app_private.form_media_envelope_error_v1(code, correlation); end if;
  return app_private.form_media_success_v1(jsonb_build_object('asset_id', asset.id, 'status', asset.status::text,
    'finalized_at', asset.finalized_at, 'replayed', replayed));
end $$;


ALTER FUNCTION "public"."form_media_finalize_question_r2_v1"("p_asset_id" "uuid", "p_finalize_ticket" "uuid", "p_byte_size" bigint, "p_checksum_sha256" "text", "p_pixel_width" integer, "p_pixel_height" integer) OWNER TO "postgres";


