CREATE OR REPLACE FUNCTION "public"."list_visible_happens_feed"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid", "p_before_at" timestamp with time zone, "p_before_type" "text", "p_before_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("item_type" "text", "item_id" "uuid", "effective_published_at" timestamp with time zone, "payload" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record; actor_role text;
begin
  select * into actor from app_private.happens_actor(p_institution_id,'happens.posts.read',p_unit_id,p_group_id);
  select lower(m.role_code) into actor_role from public.institution_memberships m where m.id=actor.membership_id;
  delete from app_private.happens_media_read_tickets ticket where ticket.expires_at<=now();
  return query
  with authorized_items as (
    select 'post'::text as kind,post.id,coalesce(post.published_at,post.publish_at) as at,
      jsonb_build_object('author_name',person.display_name,'author_initials',upper(left(person.display_name,1)),'context_label',coalesce(g.name,u.name,i.public_name),'caption',post.caption,'management_version',post.management_version,'can_withdraw',post.author_person_id=actor.person_id and app_private.has_institution_permission(p_institution_id,'happens.posts.remove',p_unit_id,p_group_id,false),'media',app_private.circular_feed_post_media(post.id,actor.person_id)) as body
    from public.posts post join public.people person on person.id=post.author_person_id join public.institutions i on i.id=post.institution_id
    left join public.units u on u.id=post.unit_id left join public.groups g on g.id=post.group_id
    where post.institution_id=p_institution_id
      and post.withdrawn_at is null
      and app_private.circular_feed_post_visible(post,actor.person_id,actor_role,p_unit_id,p_group_id)
    union all
    select 'circular',c.id,c.publish_at,jsonb_build_object('author_name',person.display_name,'author_initials',upper(left(person.display_name,1)),'context_label',coalesce(g.name,u.name,i.public_name),
      'title',r.title,'excerpt',left(r.body_text,420),'revised_at',c.revised_at,'attachment_count',(select count(*) from public.circular_media_links ml where ml.revision_id=r.id),
      'question_count',(select count(*) from public.circular_questions q where q.revision_id=r.id),'response_state',case when exists(select 1 from public.circular_response_sessions s where s.revision_id=r.id and s.last_actor_person_id=actor.person_id and s.status='submitted') then 'answered' when exists(select 1 from public.circular_response_sessions s where s.revision_id=r.id and s.last_actor_person_id=actor.person_id) then 'partial' else 'unanswered' end)
    from public.circulars c join public.circular_revisions r on r.id=c.current_revision_id join public.people person on person.id=c.author_person_id join public.institutions i on i.id=c.institution_id
    left join public.units u on u.id=c.unit_id left join public.groups g on g.id=c.group_id
    where c.institution_id=p_institution_id
      and app_private.has_institution_permission(c.institution_id,'circulars.circulars.read',c.unit_id,c.group_id,false)
      and app_private.circular_visible(c,actor.person_id,actor_role,p_unit_id,p_group_id,p_activity_id)
  )
  select source.kind,source.id,source.at,source.body from authorized_items source
  where p_before_at is null or (source.at,source.kind,source.id)<(p_before_at,coalesce(p_before_type,'zz'),p_before_id)
  order by source.at desc,source.kind desc,source.id desc limit least(greatest(coalesce(p_limit,20),1),50);
end $$;


ALTER FUNCTION "public"."list_visible_happens_feed"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid", "p_before_at" timestamp with time zone, "p_before_type" "text", "p_before_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_visible_happens_posts"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("post_id" "uuid", "author_name" "text", "author_initials" "text", "context_label" "text", "caption" "text", "published_at" timestamp with time zone, "management_version" bigint, "can_withdraw" boolean, "media" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor record;
  actor_role text;
  visible_post record;
  visible_media record;
  media_items jsonb;
  read_ticket uuid;
begin
  select * into actor from app_private.happens_actor(p_institution_id,'happens.posts.read',p_unit_id,p_group_id);
  select lower(membership.role_code) into actor_role
  from public.institution_memberships membership
  where membership.id=actor.membership_id;

  delete from app_private.happens_media_read_tickets ticket
  where ticket.expires_at<=now();

  for visible_post in
    select
      post.id,
      post.author_person_id,
      post.management_version as resolved_version,
      person.display_name,
      coalesce(scoped_group.name,scoped_unit.name,institution.public_name) as resolved_context,
      post.caption,
      coalesce(post.published_at,post.publish_at) as resolved_published_at
    from public.posts post
    join public.people person on person.id=post.author_person_id
    join public.institutions institution on institution.id=post.institution_id
    left join public.units scoped_unit on scoped_unit.id=post.unit_id
    left join public.groups scoped_group on scoped_group.id=post.group_id
    where post.institution_id=p_institution_id
      and post.status in('scheduled','published')
      and post.withdrawn_at is null
      and post.publish_at<=now()
      and (post.unit_id is null or post.unit_id=p_unit_id)
      and (post.group_id is null or post.group_id=p_group_id)
      and exists(
        select 1
        from public.post_audiences audience
        where audience.post_id=post.id
          and audience.institution_id=p_institution_id
          and audience.unit_id is not distinct from post.unit_id
          and audience.group_id is not distinct from post.group_id
          and app_private.happens_audience_matches_role(actor_role,audience.audience_kind)
      )
    order by post.publish_at desc,post.id
    limit least(greatest(coalesce(p_limit,20),1),50)
  loop
    media_items:='[]'::jsonb;
    for visible_media in
      select asset.id,asset.mime_type,link.display_order
      from public.media_links link
      join public.media_assets asset on asset.id=link.media_asset_id
      where link.post_id=visible_post.id and asset.status='ready'
      order by link.display_order
    loop
      insert into app_private.happens_media_read_tickets(media_asset_id,viewer_person_id)
      values(visible_media.id,actor.person_id)
      returning token into read_ticket;
      media_items:=media_items||jsonb_build_array(jsonb_build_object(
        'read_ticket',read_ticket,
        'mime_type',visible_media.mime_type,
        'display_order',visible_media.display_order
      ));
    end loop;

    post_id:=visible_post.id;
    author_name:=visible_post.display_name;
    author_initials:=upper(left(visible_post.display_name,1));
    context_label:=visible_post.resolved_context;
    caption:=visible_post.caption;
    published_at:=visible_post.resolved_published_at;
    management_version:=visible_post.resolved_version;
    can_withdraw:=visible_post.author_person_id=actor.person_id
      and app_private.has_institution_permission(
        p_institution_id,'happens.posts.remove',p_unit_id,p_group_id,false);
    media:=media_items;
    return next;
  end loop;
end
$$;


ALTER FUNCTION "public"."list_visible_happens_posts"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_visible_moments"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer DEFAULT 20, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("publication_id" "uuid", "author_name" "text", "author_initials" "text", "context_label" "text", "caption" "text", "published_at" timestamp with time zone, "can_withdraw" boolean, "media" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor record;
  actor_role text;
begin
  select * into actor from app_private.moments_actor(
    p_institution_id, 'moments.publications.read', p_unit_id, p_group_id
  );
  select lower(membership.role_code) into actor_role
  from public.institution_memberships membership
  where membership.id = actor.membership_id;

  return query
  select
    publication.id,
    person.display_name,
    upper(left(person.display_name, 1)),
    coalesce(scoped_group.name, scoped_unit.name, institution.public_name),
    publication.caption,
    publication.published_at,
    publication.author_person_id = actor.person_id
      and app_private.has_institution_permission(
        publication.institution_id,
        'moments.publications.remove',
        publication.unit_id,
        publication.group_id,
        false
      ),
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'asset_id', asset.id,
            'mime_type', asset.mime_type,
            'display_order', link.display_order,
            'duration_milliseconds', asset.duration_milliseconds
          )
          order by link.display_order
        )
        from public.moments_media_links link
        join public.moments_media_assets asset on asset.id = link.media_asset_id
        where link.publication_id = publication.id and asset.status = 'ready'
      ),
      '[]'::jsonb
    )
  from public.moments_publications publication
  join public.people person on person.id = publication.author_person_id
  join public.institutions institution on institution.id = publication.institution_id
  left join public.units scoped_unit on scoped_unit.id = publication.unit_id
  left join public.groups scoped_group on scoped_group.id = publication.group_id
  where publication.institution_id = p_institution_id
    and publication.status = 'published'
    and publication.withdrawn_at is null
    and publication.published_at is not null
    and (publication.unit_id is null or publication.unit_id = p_unit_id)
    and (publication.group_id is null or publication.group_id = p_group_id)
    and (p_cursor is null or publication.published_at < p_cursor)
    and exists (
      select 1
      from public.moments_publication_audiences audience
      where audience.publication_id = publication.id
        and audience.institution_id = p_institution_id
        and audience.unit_id is not distinct from publication.unit_id
        and audience.group_id is not distinct from publication.group_id
        and app_private.moments_audience_matches_role(actor_role, audience.audience_kind)
    )
  order by publication.published_at desc, publication.id desc
  limit least(greatest(coalesce(p_limit, 20), 1), 50);
end
$$;


ALTER FUNCTION "public"."list_visible_moments"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer, "p_cursor" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_visible_now_publications"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("publication_id" "uuid", "author_name" "text", "author_initials" "text", "context_label" "text", "caption" "text", "overlay_text" "text", "crop_scale" numeric, "crop_x" numeric, "crop_y" numeric, "cover_position" numeric, "published_at" timestamp with time zone, "expires_at" timestamp with time zone, "media" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor record;
  actor_role text;
  visible_publication record;
  visible_asset record;
  media_items jsonb;
  read_ticket uuid;
begin
  select * into actor
  from app_private.now_actor(
    p_institution_id,
    'now.publications.read',
    p_unit_id,
    p_group_id
  );
  actor_role:=app_private.now_viewer_role_class(
    actor.person_id,actor.membership_id,p_institution_id,p_unit_id,p_group_id
  );
  if actor_role is null then
    raise insufficient_privilege using message='viewer_context_not_authorized';
  end if;

  delete from app_private.now_media_read_tickets ticket
  where ticket.expires_at<=now();

  for visible_publication in
    select
      publication.id,
      person.display_name,
      coalesce(scoped_group.name,scoped_unit.name,institution.public_name) as resolved_context,
      publication.caption,
      publication.overlay_text,
      publication.crop_scale,
      publication.crop_x,
      publication.crop_y,
      publication.cover_position,
      coalesce(publication.published_at,publication.publish_at) as resolved_published_at,
      publication.expires_at
    from public.now_publications publication
    join public.people person on person.id=publication.author_person_id
    join public.institutions institution on institution.id=publication.institution_id
    left join public.units scoped_unit on scoped_unit.id=publication.unit_id
    left join public.groups scoped_group on scoped_group.id=publication.group_id
    where publication.institution_id=p_institution_id
      and publication.status in('scheduled','published')
      and publication.publish_at<=now()
      and publication.expires_at>now()
      and publication.status<>'expired'
      and (publication.unit_id is null or publication.unit_id=p_unit_id)
      and (publication.group_id is null or publication.group_id=p_group_id)
      and exists(
        select 1
        from public.now_publication_audiences audience
        where audience.publication_id=publication.id
          and audience.institution_id=p_institution_id
          and audience.unit_id is not distinct from publication.unit_id
          and audience.group_id is not distinct from publication.group_id
          and app_private.now_audience_matches_role(actor_role,audience.audience_kind)
      )
    order by publication.publish_at desc,publication.id
    limit least(greatest(coalesce(p_limit,20),1),50)
  loop
    media_items:='[]'::jsonb;
    for visible_asset in
      select asset.id,asset.kind,asset.mime_type
      from public.now_media_assets asset
      where asset.publication_id=visible_publication.id
        and asset.institution_id=p_institution_id
        and asset.status='ready'
      order by asset.kind
    loop
      insert into app_private.now_media_read_tickets(media_asset_id,viewer_person_id)
      values(visible_asset.id,actor.person_id)
      returning token into read_ticket;
      media_items:=media_items||jsonb_build_array(jsonb_build_object(
        'read_ticket',read_ticket,
        'kind',visible_asset.kind,
        'mime_type',visible_asset.mime_type
      ));
    end loop;

    publication_id:=visible_publication.id;
    author_name:=visible_publication.display_name;
    author_initials:=upper(left(visible_publication.display_name,1));
    context_label:=visible_publication.resolved_context;
    caption:=visible_publication.caption;
    overlay_text:=visible_publication.overlay_text;
    crop_scale:=visible_publication.crop_scale;
    crop_x:=visible_publication.crop_x;
    crop_y:=visible_publication.crop_y;
    cover_position:=visible_publication.cover_position;
    published_at:=visible_publication.resolved_published_at;
    expires_at:=visible_publication.expires_at;
    media:=media_items;
    return next;
  end loop;
end
$$;


ALTER FUNCTION "public"."list_visible_now_publications"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_visible_profile_circulars"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid", "p_before_at" timestamp with time zone, "p_before_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("item_id" "uuid", "title" "text", "excerpt" "text", "author_name" "text", "context_label" "text", "effective_published_at" timestamp with time zone, "revised_at" timestamp with time zone, "attachment_count" bigint, "question_count" bigint, "response_state" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record;
begin
  select * into actor from app_private.circular_actor(p_institution_id,'circulars.circulars.read',p_unit_id,p_group_id);
  return query select c.id,r.title,left(r.body_text,320),p.display_name,coalesce(g.name,u.name,i.public_name),c.publish_at,c.revised_at,
    (select count(*) from public.circular_media_links ml where ml.revision_id=r.id),
    (select count(*) from public.circular_questions q where q.revision_id=r.id),
    case when exists(select 1 from public.circular_response_sessions s where s.revision_id=r.id and s.last_actor_person_id=actor.person_id and s.status='submitted') then 'answered'
      when exists(select 1 from public.circular_response_sessions s where s.revision_id=r.id and s.last_actor_person_id=actor.person_id) then 'partial' else 'unanswered' end
  from public.circulars c join public.circular_revisions r on r.id=c.current_revision_id join public.people p on p.id=c.author_person_id
  join public.institutions i on i.id=c.institution_id left join public.units u on u.id=c.unit_id left join public.groups g on g.id=c.group_id
  where c.institution_id=p_institution_id and app_private.circular_visible(c,actor.person_id,actor.role_code,p_unit_id,p_group_id,p_activity_id)
    and (p_before_at is null or (c.publish_at,c.id)<(p_before_at,p_before_id))
  order by c.publish_at desc,c.id desc limit least(greatest(coalesce(p_limit,20),1),50);
end $$;


ALTER FUNCTION "public"."list_visible_profile_circulars"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid", "p_before_at" timestamp with time zone, "p_before_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."load_circular_draft"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record; target public.circulars%rowtype; revision public.circular_revisions%rowtype;
begin
  perform app_private.circular_validate_scope(p_institution_id,p_unit_id,p_group_id,p_activity_id);
  select * into actor from app_private.circular_actor(p_institution_id,'circulars.circulars.create',p_unit_id,p_group_id);
  select * into target from public.circulars c
  where c.institution_id=p_institution_id and c.author_person_id=actor.person_id and c.deleted_at is null
    and c.working_revision_id is not null and c.unit_id is not distinct from p_unit_id
    and c.group_id is not distinct from p_group_id and c.activity_id is not distinct from p_activity_id
  order by c.updated_at desc limit 1;
  if target.id is null then return null; end if;
  select * into revision from public.circular_revisions r where r.id=target.working_revision_id;
  return jsonb_build_object(
    'id',target.id,'version',target.management_version,'revision_id',revision.id,'title',revision.title,
    'status',target.status,'response_policy',target.response_policy,'publish_at',target.publish_at,
    'responses_close_at',target.responses_close_at,
    'blocks',(select coalesce(jsonb_agg(
      case block.block_kind
        when 'text' then jsonb_build_object('id',block.id,'kind','text','text',block.text_content,'order',block.display_order)
        when 'media' then jsonb_build_object('id',block.id,'kind','media','order',block.display_order,'asset_ids',(
          select coalesce(jsonb_agg(link.media_asset_id order by link.display_order),'[]') from public.circular_media_links link where link.block_id=block.id))
        else jsonb_build_object('id',block.id,'kind','question','order',block.display_order,'question',(
          select jsonb_build_object('id',q.id,'prompt',q.prompt,'kind',q.question_kind,'required',q.required,'options',(
            select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'order',o.display_order) order by o.display_order),'[]') from public.circular_question_options o where o.question_id=q.id))
          from public.circular_questions q where q.block_id=block.id))
      end order by block.display_order),'[]') from public.circular_blocks block where block.revision_id=revision.id),
    'audiences',(select coalesce(jsonb_agg(jsonb_build_object('kind',a.audience_kind,'scope',a.scope_kind,'unit_id',a.unit_id,'group_id',a.group_id,'activity_id',a.activity_id)),'[]') from public.circular_audience_rules a where a.circular_id=target.id and a.revision_id=revision.id)
  );
end $$;


ALTER FUNCTION "public"."load_circular_draft"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."load_happens_draft"("p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record; target public.posts%rowtype;
begin
  select * into actor from app_private.happens_actor(p_institution_id,'happens.posts.create',p_unit_id,p_group_id);
  select * into target from public.posts where institution_id=p_institution_id and author_person_id=actor.person_id
    and status='draft' and unit_id is not distinct from p_unit_id and group_id is not distinct from p_group_id
    order by updated_at desc limit 1;
  if target.id is null then return null; end if;
  return jsonb_build_object('id',target.id,'caption',target.caption,'version',target.management_version,'publish_at',target.publish_at,
    'audiences',(select coalesce(jsonb_agg(audience_kind order by audience_kind),'[]') from public.post_audiences where post_id=target.id),
    'media',(select coalesce(jsonb_agg(jsonb_build_object('asset_id',asset.id,'name',asset.original_name,'mime_type',asset.mime_type,'object_key',asset.object_key) order by link.display_order),'[]') from public.media_links link join public.media_assets asset on asset.id=link.media_asset_id where link.post_id=target.id and asset.status='ready'));
end $$;


