CREATE OR REPLACE FUNCTION "public"."meal_plan_publish"("p_request_id" "text", "p_meal_plan_id" "uuid", "p_expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := app_private.current_person_id();
  stored_plan public.meal_plans%rowtype;
  request_hash text;
  receipt app_private.meal_plan_command_receipts%rowtype;
  result_payload jsonb;
begin
  if auth.uid() is null or actor_id is null
      or not app_private.has_platform_permission('meal_plans.publish') then
    raise insufficient_privilege using message = 'meal_plans.publish required';
  end if;
  if nullif(btrim(coalesce(p_request_id, '')), '') is null
      or length(p_request_id) > 200 then
    raise invalid_parameter_value using message = 'invalid meal plan request id';
  end if;
  select candidate.* into stored_plan
  from public.meal_plans candidate
  where candidate.id = p_meal_plan_id
    and app_private.meal_plan_scope_allowed(
      candidate.tenant_id, candidate.institution_id
    );
  if not found then raise no_data_found using message = 'meal plan not found'; end if;

  request_hash := app_private.meal_plan_request_hash(jsonb_build_object(
    'command', 'publish',
    'meal_plan_id', p_meal_plan_id,
    'expected_revision', p_expected_revision
  ));
  perform pg_advisory_xact_lock(
    hashtextextended(actor_id::text || ':' || p_request_id, 0)
  );
  select candidate.* into receipt
  from app_private.meal_plan_command_receipts candidate
  where candidate.actor_person_id = actor_id
    and candidate.request_id = p_request_id;
  if found then
    if receipt.command_name <> 'publish'
        or receipt.payload_hash <> request_hash then
      raise invalid_parameter_value using message = 'idempotency key reused';
    end if;
    return receipt.result_json;
  end if;

  result_payload := public.meal_plan_publish_unreceipted(
    p_request_id, p_meal_plan_id, p_expected_revision
  );
  insert into app_private.meal_plan_command_receipts (
    actor_person_id, request_id, command_name, meal_plan_id,
    payload_hash, result_json
  ) values (
    actor_id, p_request_id, 'publish', p_meal_plan_id,
    request_hash, result_payload
  );
  return result_payload;
end;
$$;


ALTER FUNCTION "public"."meal_plan_publish"("p_request_id" "text", "p_meal_plan_id" "uuid", "p_expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."meal_plan_publish_unreceipted"("p_request_id" "text", "p_meal_plan_id" "uuid", "p_expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare plan public.meal_plans; pending_conflicts integer;
begin
  if auth.uid() is null or not app_private.has_platform_permission('meal_plans.publish') then raise insufficient_privilege; end if;
  select * into plan from public.meal_plans where id = p_meal_plan_id for update;
  if not found then raise no_data_found; end if;
  select count(*) into pending_conflicts from public.meal_plans other_plan
    where other_plan.id <> plan.id and other_plan.scope_level = plan.scope_level and other_plan.scope_id = plan.scope_id and other_plan.start_date <= plan.end_date and other_plan.end_date >= plan.start_date and other_plan.priority = plan.priority and other_plan.status in ('inReview', 'scheduled', 'published', 'updated');
  if plan.conflict_state or pending_conflicts > 0 then raise exception 'meal plan has unresolved conflict' using errcode = 'P0003'; end if;
  if plan.revision <> p_expected_revision or plan.status not in ('inReview', 'updated') then raise exception 'meal plan revision or status conflict' using errcode = 'P0003'; end if;
  update public.meal_plans set status = 'published', is_draft = false, requires_review = false, revision = revision + 1, updated_by = app_private.current_person_id(), updated_at = now() where id = plan.id returning * into plan;
  return public.meal_plan_json(plan);
end;
$$;


