CREATE OR REPLACE FUNCTION "public"."meal_plan_submit_for_review_unreceipted"("p_request_id" "text", "p_meal_plan_id" "uuid", "p_expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare plan public.meal_plans;
begin
  if auth.uid() is null or not app_private.has_platform_permission('meal_plans.manage') then raise insufficient_privilege; end if;
