CREATE OR REPLACE FUNCTION "public"."prepare_circular_media_upload"("p_request_id" "uuid", "p_institution_id" "uuid", "p_circular_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record; target public.circulars%rowtype; asset public.circular_media_assets%rowtype; max_bytes bigint;
  new_asset_id uuid; new_bucket text; new_object_key text;
begin
  select * into target from public.circulars c where c.id=p_circular_id and c.institution_id=p_institution_id and c.working_revision_id is not null and c.deleted_at is null;
  if target.id is null then raise insufficient_privilege using message='circular_not_authorized'; end if;
  select * into actor from app_private.circular_actor(p_institution_id,'circulars.circulars.create',target.unit_id,target.group_id);
  if target.author_person_id<>actor.person_id then raise insufficient_privilege using message='circular_not_authorized'; end if;
  max_bytes:=case when p_mime_type in ('image/jpeg','image/png','image/webp') then 10485760 when p_mime_type='video/mp4' then 26214400 when p_mime_type='application/pdf' then 5242880 end;
  if max_bytes is null or p_byte_size not between 1 and max_bytes then raise check_violation using message='circular_media_invalid'; end if;
  select * into asset from public.circular_media_assets m where m.circular_id=target.id and m.upload_request_id=p_request_id;
  if asset.id is null then
    if (select count(*) from public.circular_media_assets m where m.circular_id=target.id and m.status<>'deleted')>=4 then raise check_violation using message='circular_media_limit'; end if;
    new_asset_id:=gen_random_uuid();
    new_bucket:=case when p_mime_type='application/pdf' then 'coelo-documents-prod' else 'coelo-media-prod' end;
    new_object_key:='tenants/'||p_institution_id::text||'/circulars/circular/'||target.id::text
      ||'/attachment/'||new_asset_id::text||'/original/'||gen_random_uuid()::text
      ||case p_mime_type when 'image/jpeg' then '.jpg' when 'image/png' then '.png'
        when 'image/webp' then '.webp' when 'video/mp4' then '.mp4' else '.pdf' end;
    insert into public.circular_media_assets(id,circular_id,institution_id,owner_person_id,upload_request_id,storage_provider,bucket_id,object_key,original_name,mime_type,byte_size)
    values(new_asset_id,target.id,p_institution_id,actor.person_id,p_request_id,'r2',new_bucket,new_object_key,p_name,p_mime_type,p_byte_size)
    returning * into asset;
  elsif asset.owner_person_id<>actor.person_id or asset.mime_type<>p_mime_type or asset.byte_size<>p_byte_size then
    raise insufficient_privilege using message='upload_request_conflict';
  end if;
  return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'bucket_id',asset.bucket_id,'object_key',asset.object_key,'expected_mime_type',asset.mime_type,'expected_byte_size',asset.byte_size,'status',asset.status);
end $$;


ALTER FUNCTION "public"."prepare_circular_media_upload"("p_request_id" "uuid", "p_institution_id" "uuid", "p_circular_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_happens_media_upload"("p_request_id" "text", "p_institution_id" "uuid", "p_post_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record;asset public.media_assets%rowtype;target public.posts%rowtype;new_asset_id uuid;new_object_key text;
begin
  select * into target from public.posts where id=p_post_id and institution_id=p_institution_id and status='draft';
  if target.id is null then raise insufficient_privilege using message='post_not_authorized';end if;
  select * into actor from app_private.happens_actor(p_institution_id,'happens.posts.create',target.unit_id,target.group_id);
  if target.author_person_id<>actor.person_id then raise insufficient_privilege using message='post_not_authorized';end if;
  if p_mime_type not in('image/jpeg','image/png','image/webp','video/mp4') then raise check_violation using message='unsupported_media_type';end if;
  select * into asset from public.media_assets where post_id=p_post_id and upload_request_id=p_request_id;
  if asset.id is not null then
    if asset.owner_person_id<>actor.person_id or asset.mime_type<>p_mime_type or asset.byte_size<>p_byte_size then raise insufficient_privilege using message='upload_request_conflict';end if;
    return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'bucket_id',asset.bucket_id,'object_key',asset.object_key,'expected_mime_type',asset.mime_type,'expected_byte_size',asset.byte_size,'status',asset.status);
  end if;
  new_asset_id:=gen_random_uuid();
  new_object_key:='tenants/'||p_institution_id::text||'/happens/post/'||p_post_id::text
    ||'/attachment/'||new_asset_id::text||'/original/'||gen_random_uuid()::text
    ||case p_mime_type when 'image/jpeg' then '.jpg' when 'image/png' then '.png'
      when 'image/webp' then '.webp' else '.mp4' end;
  insert into public.media_assets(id,institution_id,post_id,owner_person_id,upload_request_id,storage_provider,bucket_id,object_key,original_name,mime_type,byte_size)
  values(new_asset_id,p_institution_id,p_post_id,actor.person_id,p_request_id,'r2','coelo-media-prod',new_object_key,p_name,p_mime_type,p_byte_size)
  returning * into asset;
  return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'bucket_id',asset.bucket_id,'object_key',asset.object_key,'expected_mime_type',asset.mime_type,'expected_byte_size',asset.byte_size,'status',asset.status);
end $$;


ALTER FUNCTION "public"."prepare_happens_media_upload"("p_request_id" "text", "p_institution_id" "uuid", "p_post_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_moments_media_upload"("p_request_id" "uuid", "p_institution_id" "uuid", "p_publication_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_duration_milliseconds" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor record;
  target public.moments_publications%rowtype;
  asset public.moments_media_assets%rowtype;
  asset_id uuid := gen_random_uuid();
  object_key text;
  fingerprint text;
  prior record;
  receipt_id uuid := gen_random_uuid();
  result jsonb;
begin
  select * into target from public.moments_publications publication
  where publication.id = p_publication_id
    and publication.institution_id = p_institution_id
    and publication.status = 'draft';
  if target.id is null then raise insufficient_privilege using message = 'publication_not_authorized'; end if;
  select * into actor from app_private.moments_actor(
    p_institution_id, 'moments.publications.create', target.unit_id, target.group_id
  );
  if target.author_person_id <> actor.person_id then
    raise insufficient_privilege using message = 'publication_not_authorized';
  end if;
  if p_mime_type not in ('image/jpeg', 'image/png', 'image/webp', 'video/mp4') then
    raise check_violation using message = 'unsupported_media_type';
  end if;
  if p_byte_size < 1 or p_byte_size > 26214400 then
    raise check_violation using message = 'media_size_invalid';
  end if;
  if p_mime_type = 'video/mp4' and (
    p_duration_milliseconds is null or p_duration_milliseconds not between 1 and 300000
  ) then raise check_violation using message = 'video_duration_invalid'; end if;
  if p_mime_type <> 'video/mp4' and p_duration_milliseconds is not null then
    raise check_violation using message = 'image_duration_invalid';
  end if;

  fingerprint := app_private.moments_request_fingerprint(jsonb_build_object(
    'institution_id', p_institution_id,
    'publication_id', p_publication_id,
    'name', p_name,
    'mime_type', p_mime_type,
    'byte_size', p_byte_size,
    'duration_milliseconds', p_duration_milliseconds
  ));
  perform pg_advisory_xact_lock(hashtextextended(actor.person_id::text || p_request_id::text, 0));
  select receipt.request_fingerprint, receipt.response into prior
  from app_private.moments_command_receipts receipt
  where receipt.actor_person_id = actor.person_id
    and receipt.command_name = 'prepare_media'
    and receipt.request_id = p_request_id;
  if prior.response is not null then
    if prior.request_fingerprint <> fingerprint then
      raise unique_violation using message = 'idempotency_key_reused';
    end if;
    return prior.response;
  end if;

  object_key := 'institution/' || p_institution_id::text ||
    '/moments/' || to_char(now() at time zone 'utc', 'YYYY/MM') ||
    '/' || asset_id::text || '/original';
  insert into public.moments_media_assets (
    id, institution_id, publication_id, owner_person_id, upload_request_id,
    object_key, original_name, mime_type, byte_size, duration_milliseconds
  ) values (
    asset_id, p_institution_id, p_publication_id, actor.person_id, p_request_id,
    object_key, left(p_name, 240), p_mime_type, p_byte_size, p_duration_milliseconds
  ) returning * into asset;

  result := jsonb_build_object(
    'asset_id', asset.id,
    'object_key', asset.object_key,
    'expected_byte_size', asset.byte_size,
    'expected_mime_type', asset.mime_type,
    'receipt_id', receipt_id
  );
  insert into app_private.moments_command_receipts (
    id, actor_person_id, institution_id, command_name,
    request_id, request_fingerprint, response
  ) values (
    receipt_id, actor.person_id, p_institution_id, 'prepare_media',
    p_request_id, fingerprint, result
  );
  insert into app_private.moments_publication_audit (
    publication_id, institution_id, actor_person_id, receipt_id, event_code, detail
  ) values (
    p_publication_id, p_institution_id, actor.person_id, receipt_id,
    'media_upload_requested', jsonb_build_object('asset_id', asset.id)
  );
  return result;
end
$$;


ALTER FUNCTION "public"."prepare_moments_media_upload"("p_request_id" "uuid", "p_institution_id" "uuid", "p_publication_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_duration_milliseconds" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_now_asset_upload"("p_institution_id" "uuid", "p_publication_id" "uuid", "p_kind" "public"."now_asset_kind", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_duration_seconds" numeric, "p_rights_confirmed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record;asset public.now_media_assets%rowtype;target public.now_publications%rowtype;
  max_seconds integer;new_asset_id uuid;new_object_key text;
begin
  select * into target from public.now_publications
    where id=p_publication_id and institution_id=p_institution_id and status='draft';
  if target.id is null then raise insufficient_privilege using message='publication_not_authorized';end if;
  select * into actor from app_private.now_actor(p_institution_id,'now.publications.create',target.unit_id,target.group_id);
  if target.author_person_id<>actor.person_id then raise insufficient_privilege using message='publication_not_authorized';end if;
  if p_byte_size<1 or p_byte_size>26214400 or char_length(p_name)>255 then raise check_violation using message='invalid_asset_metadata';end if;
  if p_kind='media' and p_mime_type not in('image/jpeg','image/png','image/webp','video/mp4') then raise check_violation using message='unsupported_media_type';end if;
  if p_kind='audio' and (p_mime_type not in('audio/mpeg','audio/mp4','audio/wav','audio/aac') or not p_rights_confirmed) then raise check_violation using message='audio_rights_required';end if;
  if p_kind='cover' and p_mime_type not in('image/jpeg','image/png','image/webp') then raise check_violation using message='unsupported_cover_type';end if;
  max_seconds:=app_private.now_max_video_seconds(p_institution_id);
  if p_mime_type='video/mp4' and (p_duration_seconds is null or p_duration_seconds>max_seconds) then raise check_violation using message='video_duration_exceeded';end if;

  select * into asset from public.now_media_assets
    where publication_id=p_publication_id and kind=p_kind for update;
  if asset.id is not null and asset.owner_person_id=actor.person_id
    and asset.mime_type=p_mime_type and asset.byte_size=p_byte_size
    and asset.original_name=p_name and asset.status in('pending','ready') then
    return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'bucket_id',asset.bucket_id,'object_key',asset.object_key,'expected_mime_type',asset.mime_type,'expected_byte_size',asset.byte_size,'status',asset.status);
  end if;

  new_asset_id:=coalesce(asset.id,gen_random_uuid());
  new_object_key:='tenants/'||p_institution_id::text||'/now/publication/'||p_publication_id::text
    ||'/'||p_kind::text||'/'||new_asset_id::text||'/original/'||gen_random_uuid()::text
    ||case p_mime_type when 'image/jpeg' then '.jpg' when 'image/png' then '.png'
      when 'image/webp' then '.webp' when 'video/mp4' then '.mp4' when 'audio/mpeg' then '.mp3'
      when 'audio/mp4' then '.m4a' when 'audio/wav' then '.wav' else '.aac' end;
  if asset.id is null then
    insert into public.now_media_assets(id,publication_id,institution_id,owner_person_id,kind,storage_provider,bucket_id,object_key,original_name,mime_type,byte_size,duration_seconds,rights_confirmed)
    values(new_asset_id,p_publication_id,p_institution_id,actor.person_id,p_kind,'r2','coelo-media-prod',new_object_key,p_name,p_mime_type,p_byte_size,p_duration_seconds,p_rights_confirmed)
    returning * into asset;
  else
    update public.now_media_assets set storage_provider='r2',bucket_id='coelo-media-prod',object_key=new_object_key,
      original_name=p_name,mime_type=p_mime_type,byte_size=p_byte_size,duration_seconds=p_duration_seconds,
      rights_confirmed=p_rights_confirmed,status='pending',finalized_at=null,checksum_sha256=null
    where id=asset.id returning * into asset;
  end if;
  return jsonb_build_object('asset_id',asset.id,'storage_provider',asset.storage_provider,'bucket_id',asset.bucket_id,'object_key',asset.object_key,'expected_mime_type',asset.mime_type,'expected_byte_size',asset.byte_size,'status',asset.status);
end $$;


ALTER FUNCTION "public"."prepare_now_asset_upload"("p_institution_id" "uuid", "p_publication_id" "uuid", "p_kind" "public"."now_asset_kind", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_duration_seconds" numeric, "p_rights_confirmed" boolean) OWNER TO "postgres";


