CREATE OR REPLACE FUNCTION "public"."superadmin_account_profile_save"("p_request_id" "uuid", "p_first_name" "text", "p_last_name" "text", "p_mobile_phone" "text", "p_requested_email" "text" DEFAULT NULL::"text", "p_avatar_initials" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.superadmin_account_profile_save_v2(p_request_id,p_first_name,p_last_name,p_mobile_phone,p_requested_email,p_avatar_initials,null)
$$;


ALTER FUNCTION "public"."superadmin_account_profile_save"("p_request_id" "uuid", "p_first_name" "text", "p_last_name" "text", "p_mobile_phone" "text", "p_requested_email" "text", "p_avatar_initials" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_account_profile_save_v2"("p_request_id" "uuid", "p_first_name" "text", "p_last_name" "text", "p_mobile_phone" "text", "p_requested_email" "text" DEFAULT NULL::"text", "p_avatar_initials" "text" DEFAULT NULL::"text", "p_avatar_background_color" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor_id uuid; result jsonb; current_email text; normalized_email text;
begin
  actor_id := app_private.assert_account_actor();
  if p_request_id is null or char_length(trim(coalesce(p_first_name,''))) not between 1 and 80
    or char_length(trim(coalesce(p_last_name,''))) not between 1 and 120
    or char_length(trim(coalesce(p_mobile_phone,''))) not between 7 and 40
    or (p_avatar_background_color is not null and p_avatar_background_color !~ '^#[0-9A-Fa-f]{6}$')
    or (p_avatar_initials is not null and p_avatar_initials !~ '^[[:alpha:]]{1,2}$') then
    raise exception using errcode = '22023', message = 'invalid_account_profile';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));
  if exists (select 1 from public.account_profile_command_receipts where request_id=p_request_id and (person_id<>actor_id or action_code<>'save')) then
    raise exception using errcode='42501',message='account_request_not_owned';
  end if;
  select response_json into result from public.account_profile_command_receipts where request_id=p_request_id and person_id=actor_id and action_code='save';
  if result is not null then return result; end if;
  select u.email into current_email
  from auth.users u join public.person_auth_links link on link.auth_user_id = u.id
  where link.person_id = actor_id and link.status = 'active'
  order by link.linked_at desc limit 1;
  if current_email is null then select email into current_email from auth.users where id=auth.uid(); end if;
  update public.people set account_avatar_initials=coalesce(upper(p_avatar_initials),account_avatar_initials),
    account_avatar_background_color=coalesce(upper(p_avatar_background_color),account_avatar_background_color), first_name = trim(p_first_name), last_name = trim(p_last_name),
    display_name = trim(p_first_name) || ' ' || trim(p_last_name), mobile_phone = trim(p_mobile_phone), updated_at = now()
  where id = actor_id and deleted_at is null;
  if not found then raise exception using errcode = 'P0002', message = 'account_profile_not_found'; end if;
  normalized_email := lower(trim(coalesce(p_requested_email, '')));
  if normalized_email <> '' and normalized_email <> lower(coalesce(current_email, '')) then
    insert into public.account_email_change_requests(person_id, requested_email)
      values (actor_id, normalized_email)
      on conflict (person_id) where status = 'pending'
      do update set requested_email = excluded.requested_email, requested_at = now();
  end if;
  result := app_private.account_profile_projection(actor_id);
  insert into public.account_profile_command_receipts(request_id, person_id, action_code, response_json)
    values (p_request_id, actor_id, 'save', result);
  return result;
end;
$_$;


ALTER FUNCTION "public"."superadmin_account_profile_save_v2"("p_request_id" "uuid", "p_first_name" "text", "p_last_name" "text", "p_mobile_phone" "text", "p_requested_email" "text", "p_avatar_initials" "text", "p_avatar_background_color" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_account_sessions_list_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user uuid;
  v_current uuid;
  v_sessions jsonb;
begin
  perform app_private.assert_account_actor();
  v_user := auth.uid();
  v_current := nullif(coalesce(auth.jwt() ->> 'session_id', ''), '')::uuid;

  select coalesce(
           jsonb_agg(row_data order by is_current desc, refreshed_at desc nulls last, created_at desc),
           '[]'::jsonb)
    into v_sessions
  from (
    select
      s.id = v_current as is_current,
      s.created_at,
      coalesce(s.refreshed_at, s.updated_at) as refreshed_at,
      jsonb_build_object(
        'id', s.id,
        'is_current', s.id = v_current,
        'created_at', s.created_at,
        'refreshed_at', coalesce(s.refreshed_at, s.updated_at),
        'not_after', s.not_after,
        'user_agent', left(coalesce(s.user_agent, ''), 240),
        'ip', host(s.ip)
      ) as row_data
    from auth.sessions s
    where s.user_id = v_user
      and (s.not_after is null or s.not_after > now())
  ) live;

  return jsonb_build_object(
    'current_session_id', v_current,
    'sessions', v_sessions
  );
end;
$$;


ALTER FUNCTION "public"."superadmin_account_sessions_list_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_activity_create_v2"("p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid:=gen_random_uuid(); institution uuid; activity uuid:=gen_random_uuid(); taxonomy uuid; units uuid[]; h bytea; replay jsonb; a public.activity_definitions%rowtype; code text;
begin begin
 select * into strict ctx from app_private.activity_v2_require_context('activities.create',null);
 if p_payload is null or jsonb_typeof(p_payload)<>'object' or p_payload-array['institution_id','name','description','taxonomy_id','icon_key','initials','unit_ids','handle']<>'{}'::jsonb
 or jsonb_typeof(p_payload->'institution_id')<>'string' or jsonb_typeof(p_payload->'name')<>'string'
 or jsonb_typeof(p_payload->'taxonomy_id')<>'string' or jsonb_typeof(p_payload->'unit_ids')<>'array'
 or (p_payload?'description' and p_payload->'description'<>'null'::jsonb and jsonb_typeof(p_payload->'description')<>'string')
 or (p_payload?'icon_key' and p_payload->'icon_key'<>'null'::jsonb and jsonb_typeof(p_payload->'icon_key')<>'string')
 or (p_payload?'initials' and p_payload->'initials'<>'null'::jsonb and jsonb_typeof(p_payload->'initials')<>'string')
 or exists(select 1 from jsonb_array_elements(p_payload->'unit_ids') item where jsonb_typeof(item)<>'string')
 or length(btrim(coalesce(p_payload->>'name',''))) not between 1 and 120
 or length(coalesce(p_payload->>'description',''))>500 or length(coalesce(p_payload->>'icon_key',''))>64
 or length(btrim(coalesce(p_payload->>'initials',''))) not between 1 and 2
 or nullif(p_payload->>'institution_id','') is null or nullif(p_payload->>'taxonomy_id','') is null
 then raise invalid_parameter_value using detail='ACTIVITY_INVALID_INPUT'; end if;
 begin institution:=(p_payload->>'institution_id')::uuid; taxonomy:=(p_payload->>'taxonomy_id')::uuid; select array_agg(x::uuid) into units from jsonb_array_elements_text(p_payload->'unit_ids')x; exception when others then raise invalid_parameter_value using detail='ACTIVITY_INVALID_INPUT'; end;
 if p_request_id is null or nullif(btrim(p_payload->>'name'),'') is null or coalesce(array_length(units,1),0) not between 1 and 100 or cardinality(units)<>(select count(distinct unit_id) from unnest(units) unit_id) then raise invalid_parameter_value using detail='ACTIVITY_INVALID_INPUT'; end if;
 select * into strict ctx from app_private.activity_v2_require_context('activities.create',institution); perform app_private.activity_v2_require_context('activities.link_units',institution);
 h:=app_private.activity_v2_command_request_hash('activity.create',institution,null,null,p_payload); replay:=app_private.activity_v2_replay_or_error(ctx,p_request_id,institution,null,'activity.create',h,correlation); if replay is not null then return replay; end if;
 perform 1 from public.activity_taxonomies t where t.id=taxonomy order by t.id for share;
 perform 1 from public.units u where u.id=any(units) order by u.id for share;
 if not exists(select 1 from public.activity_taxonomies t where t.id=taxonomy and t.status='active' and t.code<>'outros') or (select count(*) from public.units u where u.id=any(units) and u.institution_id=institution and u.status='active')<>cardinality(units) then raise invalid_parameter_value using detail='ACTIVITY_INVALID_REFERENCE'; end if;
 perform app_private.activity_v2_set_marker(ctx,'activities.create','create',correlation);
 insert into public.activity_definitions(id,institution_id,name,description,origin_scope_kind,origin_unit_id,created_by_person_id,status,taxonomy_id,handle_stem,identity_mode,identity_initials,identity_color,identity_icon)
 values(activity,institution,btrim(p_payload->>'name'),nullif(btrim(p_payload->>'description'),''),'institution',null,null,'draft',taxonomy,coalesce(nullif(app_private.activity_slugify(split_part(app_private.structure_handle_normalize(p_payload->>'handle'),'.',1)),''),nullif(app_private.activity_slugify(p_payload->>'name'),''),'activity-'||left(activity::text,8)),'initials',nullif(p_payload->>'initials',''),'#D63C00',nullif(p_payload->>'icon_key','')) returning * into a;
 perform app_private.activity_v2_set_marker(ctx,'activities.link_units','link_units',correlation);
 insert into public.activity_unit_links(activity_id,institution_id,unit_id,linked_by_person_id) select activity,institution,x,null from unnest(units)x;
 correlation:=app_private.activity_v2_append_audit(ctx,institution,activity,'activities.create','activity.create',pg_catalog.jsonb_build_object('units',cardinality(units)));
 return app_private.activity_v2_finish_command(ctx,p_request_id,institution,activity,'activity.create',h,a.management_version,a.status::text,correlation,pg_catalog.jsonb_build_object('units',cardinality(units)));
 exception when others then get stacked diagnostics code=pg_exception_detail; code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
 return app_private.activity_v2_denied_envelope('activities.create','activity.create',code,correlation,institution); end $$;


ALTER FUNCTION "public"."superadmin_activity_create_v2"("p_request_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


