CREATE OR REPLACE FUNCTION "public"."superadmin_activity_detail_v2"("p_activity_id" "uuid", "p_sections" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; a public.activity_definitions%rowtype; correlation uuid:=gen_random_uuid();
 result jsonb; section text; code text;
begin begin
 select * into strict ctx from app_private.activity_v2_require_context('activities.read',null);
 if p_activity_id is null or p_sections is null then raise invalid_parameter_value using detail='ACTIVITY_INVALID_INPUT'; end if;
 select * into a from public.activity_definitions x where x.id=p_activity_id
   and (ctx.scope_kind<>'institution' or x.institution_id=ctx.scope_institution_id);
 if a.id is null then raise no_data_found using detail='ACTIVITY_NOT_FOUND'; end if;
 select * into strict ctx from app_private.activity_v2_require_context('activities.read',a.institution_id);
 if coalesce(array_length(p_sections,1),0)<>(select count(distinct x) from unnest(p_sections) x)
    or exists(select 1 from unnest(p_sections) x where x not in('participants','professionals','permissions')) then
  raise invalid_parameter_value using message='unknown or duplicate section',detail='ACTIVITY_INVALID_INPUT'; end if;
 foreach section in array p_sections loop
  if section in('participants','professionals') then perform app_private.activity_v2_require_context('activities.assign_people',a.institution_id);
  else perform app_private.activity_v2_require_context('activities.manage_permissions',a.institution_id); end if;
 end loop;
 result:=pg_catalog.jsonb_build_object('activity',pg_catalog.jsonb_build_object(
  'activity_id',a.id,'institution_id',a.institution_id,'name',a.name,'description',a.description,
  'handle_stem',a.handle_stem,'canonical_handle',a.canonical_handle,'handle_last_changed_at',a.handle_last_changed_at,
  'taxonomy_id',a.taxonomy_id,'taxonomy_name',(select t.name from public.activity_taxonomies t where t.id=a.taxonomy_id),
  'status',a.status,'management_version',a.management_version,'icon_key',a.identity_icon,'initials',a.identity_initials,
  'created_at',a.created_at,'updated_at',a.updated_at),
  'units',coalesce((select jsonb_agg(pg_catalog.jsonb_build_object('unit_id',u.id,'name',u.name,'status',l.status) order by u.name) from public.activity_unit_links l join public.units u on u.id=l.unit_id where l.activity_id=a.id and l.status='active'),'[]'::jsonb),
  'groups',coalesce((select jsonb_agg(pg_catalog.jsonb_build_object('group_id',g.id,'unit_id',g.unit_id,'name',g.name,'status',l.status,'participation_mode',l.participation_mode) order by g.name) from public.activity_group_links l join public.groups g on g.id=l.group_id where l.activity_id=a.id and l.status='active'),'[]'::jsonb),
  'counts',pg_catalog.jsonb_build_object('units',(select count(*) from public.activity_unit_links l where l.activity_id=a.id and l.status='active'),'groups',(select count(*) from public.activity_group_links l where l.activity_id=a.id and l.status='active'),'participants',(select count(*) from public.activity_group_participants p join public.activity_group_links l on l.id=p.activity_group_link_id where l.activity_id=a.id and p.status='active' and p.removed_at is null),'instructors',(select count(*) from public.activity_group_assignments p join public.activity_group_links l on l.id=p.activity_group_link_id where l.activity_id=a.id and p.status='active' and p.assignment_role='instructor'),'activity_admins',(select count(*) from public.activity_admin_assignments p where p.activity_id=a.id and p.status='active')));
 if 'participants'=any(p_sections) then result:=result||pg_catalog.jsonb_build_object('participants',coalesce((select jsonb_agg(pg_catalog.jsonb_build_object('child_group_link_id',p.child_group_link_id,'group_id',gl.group_id,'display_name',person.display_name,'status',p.status)) from public.activity_group_participants p join public.activity_group_links gl on gl.id=p.activity_group_link_id join public.child_group_links cgl on cgl.id=p.child_group_link_id and cgl.group_id=gl.group_id and cgl.status='active' join public.child_unit_links cul on cul.id=cgl.child_unit_link_id and cul.unit_id=gl.unit_id and cul.status='active' join public.child_contexts cc on cc.id=cul.child_context_id and cc.institution_id=a.institution_id and cc.status='active' join public.people person on person.id=cc.child_person_id and person.person_type='child' and person.status='active' where gl.activity_id=a.id and gl.status='active' and p.status='active' and p.removed_at is null),'[]'::jsonb)); end if;
 if 'professionals'=any(p_sections) then result:=result||pg_catalog.jsonb_build_object('professionals',coalesce((select jsonb_agg(item) from(
  select pg_catalog.jsonb_build_object('membership_id',x.membership_id,'role','instructor','group_id',gl.group_id,'display_name',p.display_name,'status',x.status) item from public.activity_group_assignments x join public.activity_group_links gl on gl.id=x.activity_group_link_id and gl.institution_id=a.institution_id and gl.status='active' join public.groups g on g.id=gl.group_id and g.institution_id=a.institution_id and g.unit_id=gl.unit_id and g.status='active' join public.institution_memberships m on m.id=x.membership_id and m.person_id=x.person_id and m.institution_id=a.institution_id and m.status='active' and m.revoked_at is null join public.people p on p.id=x.person_id and p.person_type='adult' and p.status='active' where gl.activity_id=a.id and x.institution_id=a.institution_id and x.status='active' and x.revoked_at is null and x.assignment_role='instructor'
  union all select pg_catalog.jsonb_build_object('membership_id',x.membership_id,'role','activity_admin','group_id',null,'display_name',p.display_name,'status',x.status) from public.activity_admin_assignments x join public.institution_memberships m on m.id=x.membership_id and m.person_id=x.person_id and m.institution_id=a.institution_id and m.status='active' and m.revoked_at is null join public.people p on p.id=x.person_id and p.person_type='adult' and p.status='active' where x.activity_id=a.id and x.institution_id=a.institution_id and x.status='active' and x.revoked_at is null) q),'[]'::jsonb)); end if;
 if 'permissions'=any(p_sections) then result:=result||pg_catalog.jsonb_build_object('permissions',pg_catalog.jsonb_build_object(
  'policies',coalesce((select jsonb_agg(pg_catalog.jsonb_build_object('code',c.code,'mode',p.policy_mode)) from public.activity_capability_policies p join public.activity_capabilities c on c.id=p.capability_id where p.activity_id=a.id),'[]'::jsonb),
  'group_settings',coalesce((select jsonb_agg(pg_catalog.jsonb_build_object('group_id',gl.group_id,'code',c.code,'enabled',s.is_enabled)) from public.activity_group_capability_settings s join public.activity_group_links gl on gl.id=s.activity_group_link_id join public.activity_capabilities c on c.id=s.capability_id where gl.activity_id=a.id),'[]'::jsonb),
  'professional_actions',coalesce((select jsonb_agg(item order by role,membership_id,group_id nulls first) from(
    select ga.membership_id,'instructor'::text role,gl.group_id,
      pg_catalog.jsonb_build_object('membership_id',ga.membership_id,'role','instructor','group_id',gl.group_id,
        'actions',coalesce((select jsonb_object_agg(c.code,case when action.can_view and action.can_edit then 'both' when action.can_edit then 'edit' when action.can_view then 'view' else 'none' end order by c.code)
          from public.activity_assignment_capability_actions action join public.activity_capabilities c on c.id=action.capability_id
          where action.assignment_id=ga.id and c.code in('chat','now','happens','moments','attendance')),'{}'::jsonb)) item
    from public.activity_group_assignments ga join public.activity_group_links gl on gl.id=ga.activity_group_link_id and gl.institution_id=a.institution_id and gl.status='active'
    join public.groups g on g.id=gl.group_id and g.institution_id=a.institution_id and g.unit_id=gl.unit_id and g.status='active'
    join public.institution_memberships m on m.id=ga.membership_id and m.person_id=ga.person_id and m.institution_id=a.institution_id and m.status='active' and m.revoked_at is null
    join public.people person on person.id=ga.person_id and person.person_type='adult' and person.status='active'
    where gl.activity_id=a.id and ga.institution_id=a.institution_id and ga.status='active' and ga.revoked_at is null and ga.assignment_role='instructor'
    union all
    select aa.membership_id,'activity_admin'::text role,null::uuid group_id,
      pg_catalog.jsonb_build_object('membership_id',aa.membership_id,'role','activity_admin','group_id',null,
        'actions',coalesce((select jsonb_object_agg(c.code,case when action.can_view and action.can_edit then 'both' when action.can_edit then 'edit' when action.can_view then 'view' else 'none' end order by c.code)
          from public.activity_admin_capability_actions action join public.activity_capabilities c on c.id=action.capability_id
          where action.activity_admin_assignment_id=aa.id and c.code in('chat','now','happens','moments','attendance')),'{}'::jsonb)) item
    from public.activity_admin_assignments aa
    join public.institution_memberships m on m.id=aa.membership_id and m.person_id=aa.person_id and m.institution_id=a.institution_id and m.status='active' and m.revoked_at is null
    join public.people person on person.id=aa.person_id and person.person_type='adult' and person.status='active'
    where aa.activity_id=a.id and aa.institution_id=a.institution_id and aa.status='active' and aa.revoked_at is null
  ) actions),'[]'::jsonb))); end if;
  return app_private.activity_v2_success_envelope(result);
 exception when others then get stacked diagnostics code=pg_exception_detail; code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
 return app_private.activity_v2_denied_envelope('activities.read','activity.detail',code,correlation,case when a.id is null then null else a.institution_id end); end $$;


ALTER FUNCTION "public"."superadmin_activity_detail_v2"("p_activity_id" "uuid", "p_sections" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_activity_directory"("p_search" "text" DEFAULT NULL::"text", "p_institution_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_unit_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_group_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_statuses" "text"[] DEFAULT '{}'::"text"[], "p_origins" "text"[] DEFAULT '{}'::"text"[], "p_limit" integer DEFAULT 24, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'name'::"text", "p_sort_ascending" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare payload jsonb; transformed jsonb;
begin
 payload:=app_private.superadmin_activity_directory(
  p_search,p_institution_ids,p_unit_ids,p_group_ids,p_statuses,p_origins,
  p_limit,p_offset,p_sort,p_sort_ascending);
 select jsonb_build_object(
  'items',coalesce(jsonb_agg(item||jsonb_build_object(
    'active_unit_count',jsonb_array_length(coalesce(item->'linked_units','[]'::jsonb)),
    'active_group_count',jsonb_array_length(coalesce(item->'linked_groups','[]'::jsonb)))
   ),'[]'::jsonb),
  'total_count',payload->'total_count') into transformed
 from jsonb_array_elements(coalesce(payload->'items','[]'::jsonb)) item;
 return transformed;
end $$;


ALTER FUNCTION "public"."superadmin_activity_directory"("p_search" "text", "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_group_ids" "uuid"[], "p_statuses" "text"[], "p_origins" "text"[], "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_sort_ascending" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_activity_directory_v2"("p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_limit" integer DEFAULT 24, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'name'::"text", "p_sort_ascending" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  correlation uuid := gen_random_uuid();
  result jsonb;
  filters jsonb := '{}'::jsonb;
  dimension text;
  scalar_key text;
  values_json jsonb;
  member jsonb;
  normalized text;
  normalized_values jsonb;
  search_text text;
  code text;
begin
  begin
    select * into strict ctx
      from app_private.activity_v2_require_context('activities.read', null);
    if p_filters is null or jsonb_typeof(p_filters) <> 'object' then
      raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
    end if;
    if p_filters - array['search','institution_id','unit_id','group_id','status',
        'institution_ids','unit_ids','group_ids','statuses','origins'] <> '{}'::jsonb
      or p_limit is null or p_limit not between 1 and 100
      or p_offset is null or p_offset < 0
      or p_sort is null or p_sort not in ('name','status','created_at','updated_at')
      or p_sort_ascending is null then
      raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
    end if;
    if p_filters ? 'search' and jsonb_typeof(p_filters->'search') not in ('string','null') then
      raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
    end if;
    search_text := nullif(btrim(p_filters->>'search'), '');
    if length(coalesce(search_text, '')) > 120 then
      raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
    end if;

    -- Validate sequentially before expansion/casts, including normalized UUID
    -- duplicates. Scalar and array forms may not coexist, even if empty.
    foreach dimension in array array['institution_ids','unit_ids','group_ids','statuses','origins'] loop
      scalar_key := case dimension when 'institution_ids' then 'institution_id'
        when 'unit_ids' then 'unit_id' when 'group_ids' then 'group_id'
        when 'statuses' then 'status' else null end;
      values_json := '[]'::jsonb;
      if p_filters ? dimension then
        if scalar_key is not null and p_filters ? scalar_key then
          raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
        end if;
        values_json := p_filters->dimension;
        if jsonb_typeof(values_json) is distinct from 'array' then
          raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
        end if;
      elsif scalar_key is not null and p_filters ? scalar_key then
        -- Historical scalar null/empty means no filter; array null is invalid.
        if jsonb_typeof(p_filters->scalar_key) not in ('string','null') then
          raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
        end if;
        if p_filters->>scalar_key <> '' then
          values_json := jsonb_build_array(p_filters->scalar_key);
        end if;
      end if;
      if jsonb_array_length(values_json) > 100 then
        raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
      end if;
      normalized_values := '[]'::jsonb;
      for member in select value from jsonb_array_elements(values_json) loop
        if jsonb_typeof(member) <> 'string' then
          raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
        end if;
        normalized := member#>>'{}';
        if dimension in ('institution_ids','unit_ids','group_ids') then
          normalized := app_private.activity_v2_safe_uuid(normalized)::text;
        elsif dimension = 'statuses' and normalized not in ('draft','active','inactive','suspended','archived') then
          raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
        elsif dimension = 'origins' and normalized not in ('institution','unit') then
          raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
        end if;
        if normalized_values ? normalized then
          raise invalid_parameter_value using detail = 'ACTIVITY_INVALID_INPUT';
        end if;
        normalized_values := normalized_values || jsonb_build_array(normalized);
      end loop;
      filters := filters || jsonb_build_object(dimension, normalized_values);
    end loop;

    with filtered as (
      select a.* from public.activity_definitions a
      where (ctx.scope_kind <> 'institution' or a.institution_id = ctx.scope_institution_id)
        and (filters->'institution_ids' = '[]'::jsonb or filters->'institution_ids' ? a.institution_id::text)
        and (filters->'statuses' = '[]'::jsonb or filters->'statuses' ? a.status::text)
        and (filters->'origins' = '[]'::jsonb or filters->'origins' ? a.origin_scope_kind::text)
        -- strpos makes %, _ and backslash literal, never SQL patterns.
        and (search_text is null or strpos(lower(a.name), lower(search_text)) > 0
          or strpos(lower(coalesce(a.description,'')), lower(search_text)) > 0)
        and (filters->'unit_ids' = '[]'::jsonb or exists (
          select 1 from public.activity_unit_links ul
          where ul.activity_id = a.id and ul.institution_id = a.institution_id
            and ul.status = 'active' and filters->'unit_ids' ? ul.unit_id::text))
        and (filters->'group_ids' = '[]'::jsonb or exists (
          select 1 from public.activity_group_links gl
          where gl.activity_id = a.id and gl.institution_id = a.institution_id
            and gl.status = 'active' and filters->'group_ids' ? gl.group_id::text))
    ), ordered as (
      select f.*, row_number() over (order by
        case when p_sort = 'name' and p_sort_ascending then f.name end asc,
        case when p_sort = 'name' and not p_sort_ascending then f.name end desc,
        case when p_sort = 'status' and p_sort_ascending then f.status::text end asc,
        case when p_sort = 'status' and not p_sort_ascending then f.status::text end desc,
        case when p_sort = 'created_at' and p_sort_ascending then f.created_at end asc,
        case when p_sort = 'created_at' and not p_sort_ascending then f.created_at end desc,
        case when p_sort = 'updated_at' and p_sort_ascending then f.updated_at end asc,
        case when p_sort = 'updated_at' and not p_sort_ascending then f.updated_at end desc,
        f.id asc) as ordinal
      from filtered f
    ), page as (
      select * from ordered order by ordinal limit p_limit offset p_offset
    ), projected as (
      select p.ordinal, jsonb_build_object(
        'id',p.id,'activity_id',p.id,'institution_id',p.institution_id,
        'institution_name',i.public_name,'name',p.name,'status',p.status,
        'description',p.description,'origin_scope_kind',p.origin_scope_kind,
        'distribution_scope',p.distribution_scope,'governance_kind',p.governance_kind,
        'handle_stem',p.handle_stem,'canonical_handle',p.canonical_handle,
        'management_version',p.management_version,'icon_key',p.identity_icon,
        'initials',p.identity_initials,'created_at',p.created_at,'updated_at',p.updated_at,
        'active_unit_count',jsonb_array_length(units.items),'unit_count',jsonb_array_length(units.items),
        'active_group_count',jsonb_array_length(groups.items),'group_count',jsonb_array_length(groups.items),
        'linked_units',units.items,'linked_groups',groups.items) as item
      from page p join public.institutions i on i.id = p.institution_id
      cross join lateral (
        select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'institution_id',u.institution_id,
          'name',u.name) order by u.name,u.id),'[]'::jsonb) as items
        from public.activity_unit_links ul join public.units u
          on u.id = ul.unit_id and u.institution_id = p.institution_id
        where ul.activity_id = p.id and ul.institution_id = p.institution_id and ul.status = 'active'
      ) units
      cross join lateral (
        select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'unit_id',g.unit_id,
          'name',g.name,'unit_name',u.name) order by g.name,g.id),'[]'::jsonb) as items
        from public.activity_group_links gl join public.groups g
          on g.id = gl.group_id and g.unit_id = gl.unit_id and g.institution_id = p.institution_id
        join public.units u on u.id = g.unit_id and u.institution_id = p.institution_id
        where gl.activity_id = p.id and gl.institution_id = p.institution_id and gl.status = 'active'
      ) groups
    )
    select jsonb_build_object('items',coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb),
      'total',(select count(*) from filtered),'limit',p_limit,'offset',p_offset)
    into result from projected;
  exception when others then
    get stacked diagnostics code = pg_exception_detail;
    code := coalesce(nullif(code,''),'SAI_INTERNAL_ERROR');
  end;
  if code is not null then
    return app_private.activity_v2_denied_envelope('activities.read','activity.directory',code,
      correlation,case when ctx.scope_kind = 'institution' then ctx.scope_institution_id else null end);
  end if;
  -- Audit failure must propagate: do not place this append inside the read
  -- exception block or return any data before the append succeeds.
  perform app_private.audit_append_superadmin_internal(
    ctx.internal_identity_id,ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,
    'activities.read',ctx.aal,'activity.directory','success'::public.audit_outcome,null::text,
    correlation,case when ctx.scope_kind = 'institution' then ctx.scope_institution_id else null::uuid end,
    null::text,null::uuid,jsonb_build_object('row_count',jsonb_array_length(result->'items')));
  return app_private.activity_v2_success_envelope(
    result || jsonb_build_object('correlation_id',correlation));
end $$;


ALTER FUNCTION "public"."superadmin_activity_directory_v2"("p_filters" "jsonb", "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_sort_ascending" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_activity_export_complete"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$select app_private.superadmin_activity_export_complete(
 p_import_job_id,p_storage_path,p_file_name,p_mime_type,
 p_size_bytes,p_checksum_sha256,p_row_count)$$;


ALTER FUNCTION "public"."superadmin_activity_export_complete"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_activity_export_prepare"("p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$select app_private.superadmin_activity_export_prepare(p_import_job_id)$$;


