CREATE OR REPLACE FUNCTION "public"."superadmin_chat_attachment_authorize_finalize_v1"("p_attachment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context; correlation uuid := gen_random_uuid(); code text;
  ticket app_private.superadmin_internal_chat_attachment_tickets%rowtype;
  attachment public.chat_attachment_metadata%rowtype;
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.send');
    if p_attachment_id is null then raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
    select * into ticket from app_private.superadmin_internal_chat_attachment_tickets t
    where t.attachment_id = p_attachment_id and t.internal_identity_id = ctx.internal_identity_id
      and (ctx.scope_kind <> 'institution' or t.institution_id = ctx.scope_institution_id);
    if ticket.attachment_id is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
    if ticket.used_at is not null or ticket.expires_at < now() then
      raise object_not_in_prerequisite_state using detail='CHAT_ATTACHMENT_TICKET_INVALID';
    end if;
    select * into attachment from public.chat_attachment_metadata where id = p_attachment_id;
    if attachment.upload_status <> 'pending' then
      raise object_not_in_prerequisite_state using detail='CHAT_ATTACHMENT_TICKET_INVALID';
    end if;
  exception when others then
    get stacked diagnostics code = pg_exception_detail;
    code := coalesce(nullif(code, ''), 'SAI_INTERNAL_ERROR');
  end;
  if code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'chat.internal.send', 'chat.attachment.authorize_finalize', code, correlation, ticket.institution_id);
    return app_private.superadmin_chat_error(code, correlation);
  end if;
  return app_private.superadmin_chat_success(jsonb_build_object(
    'attachment_id', attachment.id, 'object_key', attachment.object_key, 'bucket', 'coelo-media-prod',
    'content_type', attachment.content_type, 'byte_size', attachment.byte_size, 'sha256', attachment.sha256,
    'finalize_ticket', ticket.finalize_ticket, 'expires_at', ticket.expires_at));
end $$;


ALTER FUNCTION "public"."superadmin_chat_attachment_authorize_finalize_v1"("p_attachment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_attachment_authorize_read_v1"("p_attachment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context; correlation uuid := gen_random_uuid(); code text;
  attachment public.chat_attachment_metadata%rowtype; institution uuid; conversation uuid;
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.read');
    if p_attachment_id is null then raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
    select a.* into attachment
    from public.chat_attachment_metadata a
    join public.messages m on m.id = a.message_id
    join public.conversations c on c.id = m.conversation_id
    where a.id = p_attachment_id and m.status = 'active' and m.deleted_at is null
      and (ctx.scope_kind <> 'institution' or c.institution_id = ctx.scope_institution_id);
    if attachment.id is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
    select c.institution_id, c.id into institution, conversation
    from public.messages m join public.conversations c on c.id = m.conversation_id
    where m.id = attachment.message_id;
    if attachment.upload_status <> 'ready' then
      raise object_not_in_prerequisite_state using detail='CHAT_ATTACHMENT_NOT_READY';
    end if;
    perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,
      ctx.internal_auth_link_id, ctx.internal_membership_id, ctx.session_id,
      'chat.internal.read', ctx.aal, 'chat.attachment.read', 'success', null, correlation,
      institution, 'chat_attachment', attachment.id);
  exception when others then
    get stacked diagnostics code = pg_exception_detail;
    code := coalesce(nullif(code, ''), 'SAI_INTERNAL_ERROR');
  end;
  if code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'chat.internal.read', 'chat.attachment.read', code, correlation, institution);
    return app_private.superadmin_chat_error(code, correlation);
  end if;
  return app_private.superadmin_chat_success(jsonb_build_object(
    'attachment_id', attachment.id, 'message_id', attachment.message_id, 'conversation_id', conversation,
    'object_key', attachment.object_key, 'bucket', 'coelo-media-prod',
    'file_name', attachment.file_name, 'content_type', attachment.content_type,
    'byte_size', attachment.byte_size, 'sha256', attachment.sha256, 'ttl_seconds', 300));
end $$;


ALTER FUNCTION "public"."superadmin_chat_attachment_authorize_read_v1"("p_attachment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_attachment_expire_v1"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare expired integer := 0; item record;
begin
  if coalesce(nullif(current_setting('request.jwt.claim.role', true), ''),
        nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') <> 'service_role' then
    return app_private.superadmin_chat_error('SAI_PERMISSION_DENIED', gen_random_uuid());
  end if;
  for item in
    select t.attachment_id, a.message_id, a.object_key
    from app_private.superadmin_internal_chat_attachment_tickets t
    join public.chat_attachment_metadata a on a.id = t.attachment_id
    where t.used_at is null and t.expires_at < now() and a.upload_status = 'pending'
    order by t.expires_at limit least(greatest(coalesce(p_limit, 100), 1), 500)
    for update of t skip locked
  loop
    update public.chat_attachment_metadata set upload_status = 'failed' where id = item.attachment_id;
    update public.messages set status = 'archived', deleted_at = now() where id = item.message_id;
    update app_private.superadmin_internal_chat_attachment_tickets set used_at = now()
      where attachment_id = item.attachment_id;
    expired := expired + 1;
  end loop;
  return app_private.superadmin_chat_success(jsonb_build_object('expired', expired));
end $$;


ALTER FUNCTION "public"."superadmin_chat_attachment_expire_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_attachment_finalize_v1"("p_attachment_id" "uuid", "p_finalize_ticket" "uuid", "p_byte_size" bigint, "p_checksum_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  correlation uuid := gen_random_uuid(); code text; mismatch boolean := false;
  ticket app_private.superadmin_internal_chat_attachment_tickets%rowtype;
  attachment public.chat_attachment_metadata%rowtype;
begin
  begin
    if coalesce(nullif(current_setting('request.jwt.claim.role', true), ''),
        nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') <> 'service_role' then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    if p_attachment_id is null or p_finalize_ticket is null then
      raise invalid_parameter_value using detail='CHAT_INVALID_INPUT';
    end if;
    select * into ticket from app_private.superadmin_internal_chat_attachment_tickets t
    where t.attachment_id = p_attachment_id and t.finalize_ticket = p_finalize_ticket for update;
    if ticket.attachment_id is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
    if ticket.used_at is not null or ticket.expires_at < now() then
      raise object_not_in_prerequisite_state using detail='CHAT_ATTACHMENT_TICKET_INVALID';
    end if;
    select * into attachment from public.chat_attachment_metadata where id = p_attachment_id for update;
    if attachment.upload_status <> 'pending' then
      raise object_not_in_prerequisite_state using detail='CHAT_ATTACHMENT_TICKET_INVALID';
    end if;
    if p_byte_size is distinct from attachment.byte_size
      or lower(coalesce(p_checksum_sha256, '')) is distinct from attachment.sha256 then
      mismatch := true;
    end if;
    if not mismatch then
    update public.chat_attachment_metadata set upload_status = 'ready', uploaded_at = now()
      where id = attachment.id returning * into attachment;
    update public.messages set status = 'active', updated_at = now() where id = attachment.message_id;
    update app_private.superadmin_internal_chat_attachment_tickets set used_at = now()
      where attachment_id = attachment.id;
    perform app_private.audit_append_superadmin_internal(ticket.internal_identity_id,
      ticket.internal_auth_link_id, ticket.internal_membership_id, ticket.session_id,
      'chat.internal.send', 'aal1', 'chat.attachment.finalize', 'success', null, correlation,
      ticket.institution_id, 'chat_attachment', attachment.id);
    end if;
  exception when others then
    get stacked diagnostics code = pg_exception_detail;
    code := coalesce(nullif(code, ''), 'SAI_INTERNAL_ERROR');
  end;
  if code is null and mismatch then
    -- fora do bloco protegido: o estado falho precisa persistir
    update public.chat_attachment_metadata set upload_status = 'failed' where id = attachment.id;
    update public.messages set status = 'archived', deleted_at = now() where id = attachment.message_id;
    update app_private.superadmin_internal_chat_attachment_tickets set used_at = now()
      where attachment_id = attachment.id;
    perform app_private.audit_append_superadmin_internal(ticket.internal_identity_id,
      ticket.internal_auth_link_id, ticket.internal_membership_id, ticket.session_id,
      'chat.internal.send', 'aal1', 'chat.attachment.finalize', 'failed', 'CHAT_ATTACHMENT_MISMATCH',
      correlation, ticket.institution_id, 'chat_attachment', attachment.id);
    code := 'CHAT_ATTACHMENT_MISMATCH';
  end if;
  if code is not null then return app_private.superadmin_chat_error(code, correlation); end if;
  return app_private.superadmin_chat_success(jsonb_build_object(
    'attachment_id', attachment.id, 'message_id', attachment.message_id,
    'upload_status', attachment.upload_status, 'uploaded_at', attachment.uploaded_at));
end $$;


ALTER FUNCTION "public"."superadmin_chat_attachment_finalize_v1"("p_attachment_id" "uuid", "p_finalize_ticket" "uuid", "p_byte_size" bigint, "p_checksum_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_attachment_prepare_v1"("p_request_id" "uuid", "p_conversation_id" "uuid", "p_file_name" "text", "p_content_type" "text", "p_byte_size" bigint, "p_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  ctx app_private.superadmin_internal_context;
  correlation uuid := gen_random_uuid();
  institution uuid; read_only boolean; code text;
  actor_person uuid; limit_bytes bigint; request_hash bytea;
  prior app_private.superadmin_internal_chat_attachment_tickets%rowtype;
  attachment public.chat_attachment_metadata%rowtype;
  created_message public.messages%rowtype;
  file_name text := btrim(coalesce(p_file_name, ''));
  content_type text := lower(btrim(coalesce(p_content_type, '')));
  sha text := lower(btrim(coalesce(p_sha256, '')));
  new_attachment_id uuid := gen_random_uuid();
  object_key text; ticket_expiry timestamptz := now() + interval '30 minutes';
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.send');
    if p_request_id is null or p_conversation_id is null then
      raise invalid_parameter_value using detail='CHAT_INVALID_INPUT';
    end if;
    limit_bytes := app_private.chat_attachment_limit_v1(content_type);
    if limit_bytes is null or file_name = '' or char_length(file_name) > 255
      or file_name ~ '[[:cntrl:]/\\]' or p_byte_size is null or p_byte_size < 1
      or p_byte_size > limit_bytes or sha !~ '^[0-9a-f]{64}$' then
      raise invalid_parameter_value using detail='CHAT_ATTACHMENT_INVALID';
    end if;
    select institution_id, is_read_only into institution, read_only from public.conversations
    where id = p_conversation_id and status = 'active'
      and (ctx.scope_kind <> 'institution' or institution_id = ctx.scope_institution_id) for share;
    if institution is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
    if read_only then raise object_not_in_prerequisite_state using detail='CHAT_READ_ONLY'; end if;
    actor_person := app_private.current_person_id();
    if actor_person is null then raise insufficient_privilege using detail='SAI_INTERNAL_CONTEXT_DENIED'; end if;

    request_hash := extensions.digest(convert_to(jsonb_build_object('conversation_id', p_conversation_id,
      'file_name', file_name, 'content_type', content_type, 'byte_size', p_byte_size,
      'sha256', sha)::text, 'UTF8'), 'sha256');
    perform pg_advisory_xact_lock(hashtextextended(ctx.internal_identity_id::text || p_request_id::text, 0));
    select * into prior from app_private.superadmin_internal_chat_attachment_tickets t
    where t.internal_identity_id = ctx.internal_identity_id and t.request_id = p_request_id for update;
    if prior.attachment_id is not null then
      if prior.request_hash <> request_hash then raise unique_violation using detail='CHAT_REPLAY_MISMATCH'; end if;
      select * into attachment from public.chat_attachment_metadata where id = prior.attachment_id;
    else
      -- ADR 0038: ate 10 anexos por envio. Conta os anexos deste autor nesta conversa
      -- ainda pendentes (ticket vivo, upload nao finalizado); sem teto por conversa.
      if (select count(*) from app_private.superadmin_internal_chat_attachment_tickets t
            join public.chat_attachment_metadata a on a.id = t.attachment_id
          where t.internal_identity_id = ctx.internal_identity_id
            and t.conversation_id = p_conversation_id and t.used_at is null
            and t.expires_at >= now() and a.upload_status = 'pending') >= 10 then
        raise check_violation using detail='CHAT_ATTACHMENT_LIMIT';
      end if;
      insert into public.messages(conversation_id, author_person_id, body_text, message_type, status,
        author_membership_id, author_experience_kind, author_role_snapshot, author_kind,
        author_internal_identity_id, author_internal_membership_id)
      values (p_conversation_id, null, file_name, 'attachment', 'draft', null, null,
        ctx.platform_role_code, 'superadmin_internal', ctx.internal_identity_id, ctx.internal_membership_id)
      returning * into created_message;
      object_key := 'tenants/' || institution::text || '/chat/conversation/' || p_conversation_id::text
        || '/attachment/' || new_attachment_id::text || '/original/' || gen_random_uuid()::text
        || '.' || app_private.chat_attachment_extension_v1(content_type);
      insert into public.chat_attachment_metadata(id, message_id, provider, object_key, file_name,
        content_type, byte_size, sha256, upload_status, created_by_person_id)
      values (new_attachment_id, created_message.id, 'r2', object_key, file_name, content_type,
        p_byte_size, sha, 'pending', actor_person)
      returning * into attachment;
      insert into app_private.superadmin_internal_chat_attachment_tickets(attachment_id,
        internal_identity_id, internal_auth_link_id, internal_membership_id, session_id,
        conversation_id, institution_id, request_id, request_hash, expires_at)
      values (attachment.id, ctx.internal_identity_id, ctx.internal_auth_link_id,
        ctx.internal_membership_id, ctx.session_id, p_conversation_id, institution, p_request_id,
        request_hash, ticket_expiry)
      returning * into prior;
      perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,
        ctx.internal_auth_link_id, ctx.internal_membership_id, ctx.session_id,
        'chat.internal.send', ctx.aal, 'chat.attachment.prepare', 'success', null, correlation,
        institution, 'chat_attachment', attachment.id);
    end if;
  exception when others then
    get stacked diagnostics code = pg_exception_detail;
    code := coalesce(nullif(code, ''), 'SAI_INTERNAL_ERROR');
  end;
  if code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'chat.internal.send', 'chat.attachment.prepare', code, correlation, institution);
    return app_private.superadmin_chat_error(code, correlation);
  end if;
  return app_private.superadmin_chat_success(jsonb_build_object(
    'message_id', attachment.message_id, 'attachment_id', attachment.id,
    'object_key', attachment.object_key, 'bucket', 'coelo-media-prod',
    'file_name', attachment.file_name, 'content_type', attachment.content_type,
    'byte_size', attachment.byte_size, 'sha256', attachment.sha256,
    'upload_status', attachment.upload_status, 'finalize_ticket', prior.finalize_ticket,
    'expires_at', prior.expires_at, 'replayed', prior.used_at is not null or attachment.upload_status <> 'pending'));
end $_$;


ALTER FUNCTION "public"."superadmin_chat_attachment_prepare_v1"("p_request_id" "uuid", "p_conversation_id" "uuid", "p_file_name" "text", "p_content_type" "text", "p_byte_size" bigint, "p_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_create_group_v2"("p_request_id" "uuid", "p_institution_id" "uuid", "p_title" "text", "p_person_ids" "uuid"[], "p_unit_id" "uuid" DEFAULT NULL::"uuid", "p_group_id" "uuid" DEFAULT NULL::"uuid", "p_activity_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  correlation uuid:=gen_random_uuid();
  normalized_title text:=nullif(btrim(p_title),'');
  members uuid[]:=(select coalesce(array_agg(distinct member_id),array[]::uuid[])
    from unnest(coalesce(p_person_ids,array[]::uuid[])) member_id where member_id is not null);
  scope text;
  institution uuid;
  request_hash bytea;
  prior record;
  created public.conversations%rowtype;
  member_count integer;
  code text;
begin begin
  select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.manage');
  if p_request_id is null or p_institution_id is null or normalized_title is null
     or length(normalized_title)>120 or cardinality(members) not between 1 and 200
     or (p_activity_id is not null and (p_group_id is null or p_unit_id is null))
     or (p_group_id is not null and p_unit_id is null) then
    raise invalid_parameter_value using detail='CHAT_INVALID_INPUT';
  end if;
  -- Escopo de instituicao do ator: outro tenant nao enumera.
  select institution_row.id into institution from public.institutions institution_row
   where institution_row.id=p_institution_id and institution_row.deleted_at is null
     and (ctx.scope_kind<>'institution' or institution_row.id=ctx.scope_institution_id);
  if institution is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
  scope:=case when p_activity_id is not null then 'activity'
              when p_group_id is not null then 'group'
              when p_unit_id is not null then 'unit' else 'institution' end;
  if p_unit_id is not null and not exists(select 1 from public.units unit_row
       where unit_row.id=p_unit_id and unit_row.institution_id=institution) then
    raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
  if p_group_id is not null and not exists(select 1 from public.groups group_row
       where group_row.id=p_group_id and group_row.unit_id=p_unit_id
         and group_row.institution_id=institution) then
    raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
  if p_activity_id is not null and not exists(select 1 from public.activity_group_links link
       where link.activity_id=p_activity_id and link.group_id=p_group_id
         and link.unit_id=p_unit_id and link.institution_id=institution) then
    raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;

  request_hash:=extensions.digest(convert_to(jsonb_build_object('op','create_group',
    'institution_id',institution,'title',normalized_title,'scope',scope,
    'unit_id',p_unit_id,'group_id',p_group_id,'activity_id',p_activity_id,
    'members',(select jsonb_agg(member_id order by member_id) from unnest(members) member_id))::text,'UTF8'),'sha256');
  perform pg_advisory_xact_lock(hashtextextended(ctx.internal_identity_id::text||p_request_id::text,0));
  select * into prior from app_private.superadmin_internal_chat_group_receipts receipt
   where receipt.internal_identity_id=ctx.internal_identity_id and receipt.request_id=p_request_id for update;
  if prior.request_id is not null then
    if prior.request_hash<>request_hash then raise unique_violation using detail='CHAT_REPLAY_MISMATCH'; end if;
    select * into created from public.conversations where id=prior.conversation_id;
  else
    -- Cada membro precisa de vinculo real com a instituicao: profissional
    -- (institution_memberships ativo) ou responsavel (guardian_links ativo de
    -- crianca com child_contexts ativo na instituicao). Nada de pessoa solta.
    if exists(select 1 from unnest(members) member_id
      where not exists(select 1 from public.people person
         where person.id=member_id and person.status='active' and person.deleted_at is null)
        or not (
          exists(select 1 from public.institution_memberships membership
            where membership.person_id=member_id and membership.institution_id=institution
              and membership.status='active' and membership.revoked_at is null)
          or exists(select 1 from public.guardian_links guardian
            join public.child_contexts child_context
              on child_context.child_person_id=guardian.child_person_id
             and child_context.institution_id=institution
             and child_context.status='active' and child_context.archived_at is null
            where guardian.guardian_person_id=member_id
              and guardian.status='active' and guardian.revoked_at is null))) then
      raise check_violation using detail='CHAT_MEMBER_INVALID';
    end if;
    begin
      insert into public.conversations(institution_id,scope_kind,scope_id,conversation_type,title,
        created_by,unit_id,group_id,activity_id)
      values(institution,scope,
        case scope when 'unit' then p_unit_id when 'group' then p_group_id
          when 'activity' then p_activity_id else null end,
        'group',normalized_title,null,p_unit_id,p_group_id,p_activity_id)
      returning * into created;
    exception when raise_exception then
      raise invalid_parameter_value using detail='CHAT_INVALID_INPUT';
    end;
    insert into public.conversation_participants(conversation_id,person_id,membership_id,
      experience_kind,role_snapshot)
    select created.id,member_id,membership.id,
      case when membership.id is null then 'family' else 'professional' end,
      coalesce(nullif(membership.role_code,''),'responsavel')
    from unnest(members) member_id
    left join lateral(select membership_row.id,membership_row.role_code
      from public.institution_memberships membership_row
      where membership_row.person_id=member_id and membership_row.institution_id=institution
        and membership_row.status='active' and membership_row.revoked_at is null
      order by membership_row.created_at desc limit 1) membership on true;
    insert into app_private.superadmin_internal_chat_group_receipts(
      request_id,internal_identity_id,request_hash,conversation_id)
    values(p_request_id,ctx.internal_identity_id,request_hash,created.id);
    perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,
      ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,
      'chat.internal.manage',ctx.aal,'chat.group.create','success',null,correlation,
      institution,'conversation',created.id);
  end if;
  select count(*) into member_count from public.conversation_participants participant
   where participant.conversation_id=created.id and participant.status='active' and participant.left_at is null;
  return app_private.superadmin_chat_success(jsonb_build_object(
    'conversation_id',created.id,'title',coalesce(created.title,''),
    'conversation_type',created.conversation_type,'scope_kind',created.scope_kind,
    'institution_id',created.institution_id,'unit_id',created.unit_id,
    'group_id',created.group_id,'activity_id',created.activity_id,
    'member_count',member_count,'created_at',created.created_at,
    'replayed',prior.request_id is not null));
exception when others then get stacked diagnostics code=pg_exception_detail;
  code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
  perform app_private.audit_superadmin_internal_denial_if_identified(
    'chat.internal.manage','chat.group.create',code,correlation,institution);
  return app_private.superadmin_chat_error(code,correlation);
end $$;


ALTER FUNCTION "public"."superadmin_chat_create_group_v2"("p_request_id" "uuid", "p_institution_id" "uuid", "p_title" "text", "p_person_ids" "uuid"[], "p_unit_id" "uuid", "p_group_id" "uuid", "p_activity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_edit_message_v2"("p_conversation_id" "uuid", "p_message_id" "uuid", "p_body_text" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid:=gen_random_uuid();
 normalized_body text:=nullif(btrim(p_body_text),''); institution uuid; read_only boolean;
 request_hash bytea; prior record; target public.messages%rowtype; previous_body text; code text;
begin begin
 select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.manage');
 if p_conversation_id is null or p_message_id is null or p_request_id is null
   or normalized_body is null or length(normalized_body)>4000 then
  raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
 select institution_id,is_read_only into institution,read_only from public.conversations
  where id=p_conversation_id and status='active'
   and (ctx.scope_kind<>'institution' or institution_id=ctx.scope_institution_id) for share;
 if institution is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
 if read_only then raise object_not_in_prerequisite_state using detail='CHAT_READ_ONLY'; end if;
 perform pg_advisory_xact_lock(hashtextextended(ctx.internal_identity_id::text||p_request_id::text,0));
 request_hash:=extensions.digest(convert_to(jsonb_build_object('op','edit',
   'message_id',p_message_id,'body_text',normalized_body)::text,'UTF8'),'sha256');
 select * into prior from app_private.superadmin_internal_chat_command_receipts receipt
  where receipt.internal_identity_id=ctx.internal_identity_id and receipt.request_id=p_request_id for update;
 if prior.request_id is not null then
  if prior.request_hash<>request_hash then raise unique_violation using detail='CHAT_REPLAY_MISMATCH'; end if;
  select * into target from public.messages where id=prior.message_id;
 else
  select * into target from public.messages
   where id=p_message_id and conversation_id=p_conversation_id for update;
  if target.id is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
  if target.author_kind<>'superadmin_internal'
    or target.author_internal_identity_id is distinct from ctx.internal_identity_id then
   raise insufficient_privilege using detail='CHAT_NOT_AUTHOR'; end if;
  if target.status<>'active' or target.deleted_at is not null then
   raise object_not_in_prerequisite_state using detail='CHAT_ALREADY_REVOKED'; end if;
  if target.created_at < now()-interval '15 minutes' then
   raise object_not_in_prerequisite_state using detail='CHAT_EDIT_WINDOW_CLOSED'; end if;
  previous_body:=target.body_text;
  update public.messages set body_text=normalized_body,updated_at=now()
   where id=target.id returning * into target;
  insert into app_private.superadmin_internal_chat_message_edits(
    message_id,internal_identity_id,old_body_text,new_body_text)
  values(target.id,ctx.internal_identity_id,previous_body,normalized_body);
  insert into app_private.superadmin_internal_chat_command_receipts(
    request_id,internal_identity_id,conversation_id,request_hash,message_id)
  values(p_request_id,ctx.internal_identity_id,p_conversation_id,request_hash,target.id);
  perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,
    ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,
    'chat.internal.manage',ctx.aal,'chat.message.edit','success',null,correlation,
    institution,'message',target.id);
 end if;
 return app_private.superadmin_chat_success(jsonb_build_object(
  'message_id',target.id,'body_text',coalesce(target.body_text,''),
  'message_type',target.message_type,'created_at',target.created_at,
  'updated_at',target.updated_at,'author_name','Equipe Coelo','is_mine',true,'can_manage',true,
  'edited_at',(select max(edit.edited_at) from app_private.superadmin_internal_chat_message_edits edit
    where edit.message_id=target.id),
  'receipt',app_private.superadmin_chat_message_receipt(target.id,p_conversation_id,true,
    ctx.internal_identity_id),
  'attachments','[]'::jsonb,'replayed',prior.request_id is not null));
exception when others then get stacked diagnostics code=pg_exception_detail;
 code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
 perform app_private.audit_superadmin_internal_denial_if_identified(
  'chat.internal.manage','chat.message.edit',code,correlation,institution);
 return app_private.superadmin_chat_error(code,correlation); end $$;


ALTER FUNCTION "public"."superadmin_chat_edit_message_v2"("p_conversation_id" "uuid", "p_message_id" "uuid", "p_body_text" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_group_members_v2"("p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid:=gen_random_uuid();
  institution uuid; result jsonb; code text;
begin begin
  select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.read');
  if p_conversation_id is null then raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
  select institution_id into institution from public.conversations where id=p_conversation_id
    and (ctx.scope_kind<>'institution' or institution_id=ctx.scope_institution_id);
  if institution is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
  select jsonb_build_object('conversation_id',p_conversation_id,
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'person_id',participant.person_id,'display_name',person.display_name,
      'experience_kind',participant.experience_kind,'role_snapshot',participant.role_snapshot,
      'joined_at',participant.joined_at) order by person.display_name,participant.person_id)
      from public.conversation_participants participant
      join public.people person on person.id=participant.person_id
      where participant.conversation_id=p_conversation_id
        and participant.status='active' and participant.left_at is null),'[]'::jsonb),
    'total',(select count(*) from public.conversation_participants participant
      where participant.conversation_id=p_conversation_id
        and participant.status='active' and participant.left_at is null)) into result;
  return app_private.superadmin_chat_success(result);
exception when others then get stacked diagnostics code=pg_exception_detail;
  code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
  perform app_private.audit_superadmin_internal_denial_if_identified(
    'chat.internal.read','chat.group.members',code,correlation,institution);
  return app_private.superadmin_chat_error(code,correlation);
end $$;


ALTER FUNCTION "public"."superadmin_chat_group_members_v2"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_inbox_v2"("p_cursor_activity_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_conversation_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 30, "p_search" "text" DEFAULT NULL::"text", "p_unread_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx app_private.superadmin_internal_context;
  correlation uuid := gen_random_uuid();
  result jsonb;
  code text;
  normalized_search text := nullif(btrim(p_search), '');
begin
  begin
    select * into strict ctx
    from app_private.require_superadmin_internal_context('chat.internal.read');
    if p_limit is null or p_limit not between 1 and 100
       or (p_cursor_activity_at is null) <> (p_cursor_conversation_id is null)
       or length(coalesce(normalized_search, '')) > 100 then
      raise invalid_parameter_value using detail = 'CHAT_INVALID_INPUT';
    end if;
    with candidate as (
      select conversation_row.id, conversation_row.title, conversation_row.conversation_type,
        conversation_row.scope_kind, conversation_row.institution_id,
        conversation_row.is_read_only,
        latest.id latest_message_id, latest.body_text latest_message_text,
        latest.created_at latest_message_at,
        coalesce(latest.created_at, conversation_row.updated_at) activity_at,
        preference.pinned_at,
        coalesce(preference.flag, 'none') flag,
        (select count(*) from public.messages unread_message
         left join app_private.superadmin_internal_chat_receipts receipt
           on receipt.message_id = unread_message.id
          and receipt.internal_identity_id = ctx.internal_identity_id
         where unread_message.conversation_id = conversation_row.id
           and unread_message.status = 'active' and unread_message.deleted_at is null
           and unread_message.author_internal_identity_id is distinct from ctx.internal_identity_id
           and receipt.read_at is null) unread_count
      from public.conversations conversation_row
      left join lateral(
        select message_row.id, message_row.body_text, message_row.created_at
        from public.messages message_row
        where message_row.conversation_id = conversation_row.id
          and message_row.status = 'active' and message_row.deleted_at is null
        order by message_row.created_at desc, message_row.id desc limit 1) latest on true
      left join app_private.superadmin_internal_chat_preferences preference
        on preference.conversation_id = conversation_row.id
       and preference.internal_identity_id = ctx.internal_identity_id
      where (ctx.scope_kind <> 'institution'
          or conversation_row.institution_id = ctx.scope_institution_id)
        and (normalized_search is null
          or conversation_row.title ilike '%' || normalized_search || '%'
          or latest.body_text ilike '%' || normalized_search || '%')
    ), eligible as (
      select * from candidate where not p_unread_only or unread_count > 0
    ), filtered as (
      select * from eligible
      where p_cursor_activity_at is null
        or (activity_at, id) < (p_cursor_activity_at, p_cursor_conversation_id)
    ), page as (
      select * from filtered order by activity_at desc, id desc limit p_limit + 1
    ), stats as (
      select count(*) total, coalesce(sum(unread_count), 0) total_unread from eligible
    )
    select pg_catalog.jsonb_build_object(
      'items', coalesce((select jsonb_agg(jsonb_build_object(
        'conversation_id', item.id, 'title', coalesce(item.title, ''),
        'conversation_type', item.conversation_type, 'scope_kind', item.scope_kind,
        'institution_id', item.institution_id, 'latest_message_id', item.latest_message_id,
        'latest_message_text', coalesce(item.latest_message_text, ''),
        'latest_message_at', item.latest_message_at, 'unread_count', item.unread_count,
        'activity_at', item.activity_at, 'is_read_only', item.is_read_only,
        'pinned_at', item.pinned_at, 'flag', item.flag)
        -- Fixadas primeiro, e so entao a ordem por atividade. A paginacao
        -- continua ancorada em activity_at, entao o cursor nao muda.
        order by (item.pinned_at is null), item.pinned_at desc,
          item.activity_at desc, item.id desc)
        from (select * from page limit p_limit) item), '[]'::jsonb),
      'total', (select total from stats),
      'total_unread', (select total_unread from stats),
      'has_more', (select count(*) > p_limit from page),
      'next_cursor', case when (select count(*) from page) > p_limit then
        (select jsonb_build_object('timestamp', item.activity_at, 'id', item.id)
         from (select * from page limit p_limit) item
         order by item.activity_at, item.id limit 1) else null end
    ) into result;
    return app_private.superadmin_chat_success(result);
  exception when others then
    get stacked diagnostics code = pg_exception_detail;
    code := coalesce(nullif(code, ''), 'SAI_INTERNAL_ERROR');
  end;
  perform app_private.audit_superadmin_internal_denial_if_identified(
    'chat.internal.read', 'chat.inbox', code, correlation);
  return app_private.superadmin_chat_error(code, correlation);
end $$;


ALTER FUNCTION "public"."superadmin_chat_inbox_v2"("p_cursor_activity_at" timestamp with time zone, "p_cursor_conversation_id" "uuid", "p_limit" integer, "p_search" "text", "p_unread_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_mark_read_v2"("p_conversation_id" "uuid", "p_through_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid:=gen_random_uuid();
 cutoff timestamptz; institution uuid; marked_at timestamptz:=now(); count_written integer; code text;
begin begin
 select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.read');
 if p_conversation_id is null or p_through_message_id is null then
  raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
 select institution_id into institution from public.conversations where id=p_conversation_id
   and (ctx.scope_kind<>'institution' or institution_id=ctx.scope_institution_id);
 select created_at into cutoff from public.messages where id=p_through_message_id
   and conversation_id=p_conversation_id and status='active' and deleted_at is null;
 if institution is null or cutoff is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
 with written as(insert into app_private.superadmin_internal_chat_receipts(
   message_id,internal_identity_id,delivered_at,read_at)
  select message_row.id,ctx.internal_identity_id,marked_at,marked_at from public.messages message_row
  where message_row.conversation_id=p_conversation_id and message_row.status='active'
   and message_row.deleted_at is null and message_row.created_at<=cutoff
   and message_row.author_internal_identity_id is distinct from ctx.internal_identity_id
  on conflict(message_id,internal_identity_id) do update set
   delivered_at=coalesce(app_private.superadmin_internal_chat_receipts.delivered_at,excluded.delivered_at),
   read_at=excluded.read_at returning 1)
 select count(*) into count_written from written;
 perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,
   ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,
   'chat.internal.read',ctx.aal,'chat.conversation.read','success',null,correlation,
   institution,'conversation',p_conversation_id);
 return app_private.superadmin_chat_success(jsonb_build_object(
   'updated_count',count_written,'read_at',marked_at));
exception when others then get stacked diagnostics code=pg_exception_detail;
 code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
 perform app_private.audit_superadmin_internal_denial_if_identified(
  'chat.internal.read','chat.conversation.read',code,correlation,institution);
 return app_private.superadmin_chat_error(code,correlation); end $$;


ALTER FUNCTION "public"."superadmin_chat_mark_read_v2"("p_conversation_id" "uuid", "p_through_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_realtime_refresh_v2"("p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid:=gen_random_uuid();
 institution uuid; result jsonb; code text;
begin begin
 select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.read');
 select institution_id into institution from public.conversations where id=p_conversation_id
   and (ctx.scope_kind<>'institution' or institution_id=ctx.scope_institution_id);
 if institution is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
 select jsonb_build_object('conversation_id',conversation_row.id,
   'latest_message_id',latest.id,'latest_message_at',coalesce(latest.created_at,conversation_row.updated_at),
   'unread_count',(select count(*) from public.messages unread_message
    left join app_private.superadmin_internal_chat_receipts receipt on receipt.message_id=unread_message.id
      and receipt.internal_identity_id=ctx.internal_identity_id
    where unread_message.conversation_id=conversation_row.id and unread_message.status='active'
      and unread_message.deleted_at is null and receipt.read_at is null
      and unread_message.author_internal_identity_id is distinct from ctx.internal_identity_id)) into result
 from public.conversations conversation_row left join lateral(
   select message_row.id,message_row.created_at from public.messages message_row
   where message_row.conversation_id=conversation_row.id and message_row.status='active'
    and message_row.deleted_at is null order by message_row.created_at desc,message_row.id desc limit 1)latest on true
 where conversation_row.id=p_conversation_id;
 return app_private.superadmin_chat_success(result);
exception when others then get stacked diagnostics code=pg_exception_detail;
 code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
 perform app_private.audit_superadmin_internal_denial_if_identified(
  'chat.internal.read','chat.realtime.refresh',code,correlation,institution);
 return app_private.superadmin_chat_error(code,correlation); end $$;


ALTER FUNCTION "public"."superadmin_chat_realtime_refresh_v2"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_revoke_message_v2"("p_conversation_id" "uuid", "p_message_id" "uuid", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid:=gen_random_uuid();
 institution uuid; read_only boolean; request_hash bytea; prior record; target public.messages%rowtype; code text;
begin begin
 select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.manage');
 if p_conversation_id is null or p_message_id is null or p_request_id is null then
  raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
 select institution_id,is_read_only into institution,read_only from public.conversations where id=p_conversation_id
   and (ctx.scope_kind<>'institution' or institution_id=ctx.scope_institution_id);
 if institution is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
 if read_only then raise object_not_in_prerequisite_state using detail='CHAT_READ_ONLY'; end if;
 perform pg_advisory_xact_lock(hashtextextended(ctx.internal_identity_id::text||p_request_id::text,0));
 request_hash:=extensions.digest(convert_to(jsonb_build_object('op','revoke',
   'message_id',p_message_id)::text,'UTF8'),'sha256');
 select * into prior from app_private.superadmin_internal_chat_command_receipts receipt
  where receipt.internal_identity_id=ctx.internal_identity_id and receipt.request_id=p_request_id for update;
 if prior.request_id is not null then
  if prior.request_hash<>request_hash then raise unique_violation using detail='CHAT_REPLAY_MISMATCH'; end if;
  select * into target from public.messages where id=prior.message_id;
 else
  select * into target from public.messages
   where id=p_message_id and conversation_id=p_conversation_id for update;
  if target.id is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
  if target.author_kind<>'superadmin_internal'
    or target.author_internal_identity_id is distinct from ctx.internal_identity_id then
   raise insufficient_privilege using detail='CHAT_NOT_AUTHOR'; end if;
  if target.status<>'active' or target.deleted_at is not null then
   raise object_not_in_prerequisite_state using detail='CHAT_ALREADY_REVOKED'; end if;
  update public.messages set status='archived',deleted_at=now(),updated_at=now()
   where id=target.id returning * into target;
  insert into app_private.superadmin_internal_chat_command_receipts(
    request_id,internal_identity_id,conversation_id,request_hash,message_id)
  values(p_request_id,ctx.internal_identity_id,p_conversation_id,request_hash,target.id);
  perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,
    ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,
    'chat.internal.manage',ctx.aal,'chat.message.revoke','success',null,correlation,
    institution,'message',target.id);
 end if;
 return app_private.superadmin_chat_success(jsonb_build_object(
  'message_id',target.id,'revoked_at',target.deleted_at,
  'replayed',prior.request_id is not null));
exception when others then get stacked diagnostics code=pg_exception_detail;
 code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
 perform app_private.audit_superadmin_internal_denial_if_identified(
  'chat.internal.manage','chat.message.revoke',code,correlation,institution);
 return app_private.superadmin_chat_error(code,correlation); end $$;


ALTER FUNCTION "public"."superadmin_chat_revoke_message_v2"("p_conversation_id" "uuid", "p_message_id" "uuid", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_chat_send_message_v2"("p_conversation_id" "uuid", "p_body_text" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid:=gen_random_uuid();
 normalized_body text:=nullif(btrim(p_body_text),''); institution uuid; read_only boolean;
 request_hash bytea; prior record; created_message public.messages%rowtype; code text;
begin begin
 select * into strict ctx from app_private.require_superadmin_internal_context('chat.internal.send');
 if p_conversation_id is null or p_request_id is null or normalized_body is null
   or length(normalized_body)>4000 then raise invalid_parameter_value using detail='CHAT_INVALID_INPUT'; end if;
 select institution_id,is_read_only into institution,read_only from public.conversations
  where id=p_conversation_id and status='active'
   and (ctx.scope_kind<>'institution' or institution_id=ctx.scope_institution_id) for share;
 if institution is null then raise no_data_found using detail='CHAT_NOT_FOUND'; end if;
 if read_only then raise object_not_in_prerequisite_state using detail='CHAT_READ_ONLY'; end if;
 request_hash:=extensions.digest(convert_to(jsonb_build_object('conversation_id',p_conversation_id,
   'body_text',normalized_body)::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(ctx.internal_identity_id::text||p_request_id::text,0));
 select * into prior from app_private.superadmin_internal_chat_command_receipts receipt
  where receipt.internal_identity_id=ctx.internal_identity_id and receipt.request_id=p_request_id for update;
 if prior.request_id is not null then
  if prior.request_hash<>request_hash then raise unique_violation using detail='CHAT_REPLAY_MISMATCH'; end if;
  select * into created_message from public.messages where id=prior.message_id;
 else
  insert into public.messages(conversation_id,author_person_id,body_text,message_type,
    author_membership_id,author_experience_kind,author_role_snapshot,author_kind,
    author_internal_identity_id,author_internal_membership_id)
  values(p_conversation_id,null,normalized_body,'text',null,null,ctx.platform_role_code,
    'superadmin_internal',ctx.internal_identity_id,ctx.internal_membership_id)
  returning * into created_message;
  insert into app_private.superadmin_internal_chat_command_receipts(
   request_id,internal_identity_id,conversation_id,request_hash,message_id)
  values(p_request_id,ctx.internal_identity_id,p_conversation_id,request_hash,created_message.id);
  perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id,
    ctx.internal_auth_link_id,ctx.internal_membership_id,ctx.session_id,
    'chat.internal.send',ctx.aal,'chat.message.send','success',null,correlation,
    institution,'message',created_message.id);
 end if;
 return app_private.superadmin_chat_success(jsonb_build_object(
  'message_id',created_message.id,'body_text',created_message.body_text,
  'message_type',created_message.message_type,'created_at',created_message.created_at,
  'updated_at',created_message.updated_at,'author_name','Equipe Coelo','is_mine',true,
  'attachments','[]'::jsonb,'replayed',prior.request_id is not null));
exception when others then get stacked diagnostics code=pg_exception_detail;
 code:=coalesce(nullif(code,''),'SAI_INTERNAL_ERROR'); end;
 perform app_private.audit_superadmin_internal_denial_if_identified(
  'chat.internal.send','chat.message.send',code,correlation,institution);
 return app_private.superadmin_chat_error(code,correlation); end $$;


ALTER FUNCTION "public"."superadmin_chat_send_message_v2"("p_conversation_id" "uuid", "p_body_text" "text", "p_request_id" "uuid") OWNER TO "postgres";


