CREATE OR REPLACE FUNCTION "public"."superadmin_people_filter_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.assert_people_permission('people.read');
  return jsonb_build_object(
    'institutions',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'label',i.public_name) order by lower(i.public_name),i.id) from public.institutions i where i.deleted_at is null),'[]'::jsonb),
    'units',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'label',u.name,'institution_id',u.institution_id) order by lower(u.name),u.id) from public.units u where u.status='active'),'[]'::jsonb),
    'groups',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'label',g.name,'institution_id',g.institution_id,'unit_id',g.unit_id) order by lower(g.name),g.id) from public.groups g where g.status='active'),'[]'::jsonb),
    'roles',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'label',r.name,'code',r.code,'institution_id',r.institution_id) order by lower(r.name),r.institution_id,r.id) from public.institution_roles r where r.status='active'),'[]'::jsonb),
    'activities',coalesce((select jsonb_agg(distinct jsonb_build_object('id',a.id,'label',a.name,'institution_id',l.institution_id,'unit_id',l.unit_id,'group_id',l.group_id) order by jsonb_build_object('id',a.id,'label',a.name,'institution_id',l.institution_id,'unit_id',l.unit_id,'group_id',l.group_id)) from public.activity_definitions a join public.activity_group_links l on l.activity_id=a.id and l.institution_id=a.institution_id and l.status='active' where a.status='active'),'[]'::jsonb),
    'states',coalesce((select jsonb_agg(distinct jsonb_build_object('id',x.state_code,'label',x.state_code)) from (select coalesce(ua.state,ia.state) state_code from public.units u left join public.unit_addresses ua on ua.unit_id=u.id and ua.status='active' left join public.institution_addresses ia on ia.institution_id=u.institution_id and ia.status='active' where u.status='active') x where nullif(btrim(x.state_code),'') is not null),'[]'::jsonb),
    'municipalities',coalesce((select jsonb_agg(distinct jsonb_build_object('id',x.city,'label',x.city,'state_code',x.state_code)) from (select coalesce(ua.state,ia.state) state_code,coalesce(ua.city,ia.city) city from public.units u left join public.unit_addresses ua on ua.unit_id=u.id and ua.status='active' left join public.institution_addresses ia on ia.institution_id=u.institution_id and ia.status='active' where u.status='active') x where nullif(btrim(x.city),'') is not null),'[]'::jsonb),
    'neighborhoods',coalesce((select jsonb_agg(distinct jsonb_build_object('id',x.district,'label',x.district,'municipality_id',x.city,'state_code',x.state_code)) from (select coalesce(ua.state,ia.state) state_code,coalesce(ua.city,ia.city) city,coalesce(ua.district,ia.district) district from public.units u left join public.unit_addresses ua on ua.unit_id=u.id and ua.status='active' left join public.institution_addresses ia on ia.institution_id=u.institution_id and ia.status='active' where u.status='active') x where nullif(btrim(x.district),'') is not null),'[]'::jsonb)
  );
end; $$;


ALTER FUNCTION "public"."superadmin_people_filter_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_people_identity_lookup_v1"("p_kind" "text", "p_query" "text", "p_institution_id" "uuid" DEFAULT NULL::"uuid", "p_unit_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  kind text := lower(btrim(coalesce(p_kind, '')));
  raw text := btrim(coalesce(p_query, ''));
  normalized text;
  digest_hex text;
  access_level text;
  candidates jsonb := '[]'::jsonb;
begin
  perform app_private.assert_people_permission('people.create');
  if kind not in ('email','phone','cpf','handle','name') then
    raise invalid_parameter_value using message = 'invalid identity lookup kind';
  end if;
  if raw = '' or char_length(raw) > 200 then
    raise invalid_parameter_value using message = 'identity lookup query is required';
  end if;
  access_level := case when app_private.has_platform_permission('people.update') then 'edit_global' else 'link_only' end;

  if kind = 'email' then
    normalized := lower(raw);
    if position('@' in normalized) = 0 then
      raise invalid_parameter_value using message = 'invalid email';
    end if;
    digest_hex := encode(extensions.digest(pg_catalog.convert_to(normalized, 'UTF8'), 'sha256'), 'hex');
    select coalesce(jsonb_agg(jsonb_build_object(
        'person_id', person.id, 'display_name', person.display_name, 'person_type', person.person_type,
        'matched_by', 'email', 'masked_match', coalesce(contact.masked_value, app_private.mask_email_v1(normalized)),
        'access', access_level) order by person.display_name), '[]'::jsonb)
    into candidates
    from public.person_contacts contact
    join public.people person on person.id = contact.person_id and person.deleted_at is null
    where contact.contact_type = 'email' and contact.status = 'active'
      and contact.normalized_value_hash = digest_hex;
  elsif kind = 'phone' then
    normalized := regexp_replace(raw, '\D', '', 'g');
    if char_length(normalized) < 8 then
      raise invalid_parameter_value using message = 'invalid phone';
    end if;
    digest_hex := encode(extensions.digest(pg_catalog.convert_to(normalized, 'UTF8'), 'sha256'), 'hex');
    select coalesce(jsonb_agg(jsonb_build_object(
        'person_id', person.id, 'display_name', person.display_name, 'person_type', person.person_type,
        'matched_by', 'phone', 'masked_match', coalesce(contact.masked_value, app_private.mask_phone_v1(normalized)),
        'access', access_level) order by person.display_name), '[]'::jsonb)
    into candidates
    from public.person_contacts contact
    join public.people person on person.id = contact.person_id and person.deleted_at is null
    where contact.contact_type = 'mobile_phone' and contact.status = 'active'
      and contact.normalized_value_hash = digest_hex;
  elsif kind = 'cpf' then
    normalized := regexp_replace(raw, '\D', '', 'g');
    if char_length(normalized) <> 11 then
      raise invalid_parameter_value using message = 'invalid cpf';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
        'person_id', person.id, 'display_name', person.display_name, 'person_type', person.person_type,
        'matched_by', 'cpf', 'masked_match', identifier.masked_value,
        'access', access_level) order by person.display_name), '[]'::jsonb)
    into candidates
    from app_private.person_identity_identifiers identifier
    join public.people person on person.id = identifier.person_id and person.deleted_at is null
    where identifier.identifier_kind = 'cpf' and identifier.status = 'active'
      and identifier.normalized_value_hmac = app_private.person_identity_hmac_v1(normalized);
    digest_hex := encode(extensions.digest(pg_catalog.convert_to(normalized, 'UTF8'), 'sha256'), 'hex');
  elsif kind = 'handle' then
    normalized := app_private.normalize_person_handle(raw);
    select coalesce(jsonb_agg(jsonb_build_object(
        'person_id', person.id, 'display_name', person.display_name, 'person_type', person.person_type,
        'matched_by', 'handle', 'masked_match', '@' || handle.normalized_handle,
        'access', access_level) order by person.display_name), '[]'::jsonb)
    into candidates
    from public.person_handles handle
    join public.people person on person.id = handle.person_id and person.deleted_at is null
    where handle.normalized_handle = normalized and handle.status = 'active' and handle.revoked_at is null;
    digest_hex := encode(extensions.digest(pg_catalog.convert_to(normalized, 'UTF8'), 'sha256'), 'hex');
  else
    normalized := raw;
    if char_length(normalized) < 3 then
      raise invalid_parameter_value using message = 'name lookup needs at least 3 characters';
    end if;
    select coalesce(jsonb_agg(item order by item->>'display_name'), '[]'::jsonb)
    into candidates
    from (
      select jsonb_build_object(
        'person_id', person.id, 'display_name', person.display_name, 'person_type', person.person_type,
        'matched_by', 'name', 'masked_match', person.display_name,
        'access', access_level) as item
      from public.people person
      where person.deleted_at is null and person.person_type in ('adult','child')
        and (person.display_name ilike '%' || normalized || '%' or person.legal_name ilike '%' || normalized || '%')
      order by person.display_name
      limit 10
    ) matches;
    digest_hex := encode(extensions.digest(pg_catalog.convert_to(lower(normalized), 'UTF8'), 'sha256'), 'hex');
  end if;

  -- O mascaramento de audit_logs redige reason/after_json com valores que
  -- pareçam identificadores; a trilha guarda so quem, quando e o contexto.
  insert into audit.audit_logs(actor_person_id, mfa_aal, action_code, object_type, object_id, outcome, reason, after_json)
  values (app_private.current_person_id(), 'aal1', 'permission_changed', 'person_identity_lookup', null, 'success',
    'superadmin.people.identity-lookup',
    jsonb_build_object('institution_id', p_institution_id, 'unit_id', p_unit_id));
  return jsonb_build_object('ok', true, 'data', candidates, 'error', null);
end
$$;


ALTER FUNCTION "public"."superadmin_people_identity_lookup_v1"("p_kind" "text", "p_query" "text", "p_institution_id" "uuid", "p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_people_list"("p_search" "text" DEFAULT ''::"text", "p_types" "public"."person_type"[] DEFAULT ARRAY[]::"public"."person_type"[], "p_statuses" "public"."record_status"[] DEFAULT ARRAY[]::"public"."record_status"[], "p_institution_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_unit_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_group_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_contextual_roles" "text"[] DEFAULT ARRAY[]::"text"[], "p_auth_links" "text"[] DEFAULT ARRAY[]::"text"[], "p_sort" "text" DEFAULT 'display_name'::"text", "p_sort_ascending" boolean DEFAULT true, "p_offset" integer DEFAULT 0, "p_limit" integer DEFAULT 11, "p_segment" "text" DEFAULT 'all'::"text", "p_activity_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_state_codes" "text"[] DEFAULT ARRAY[]::"text"[], "p_municipality_ids" "text"[] DEFAULT ARRAY[]::"text"[], "p_neighborhood_ids" "text"[] DEFAULT ARRAY[]::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.assert_people_permission('people.read');
  if p_offset < 0 then raise invalid_parameter_value using message = 'offset must not be negative'; end if;
  if p_limit not in (8,11,20,50,100) then raise invalid_parameter_value using message = 'limit must be 8, 11, 20, 50 or 100'; end if;
  if coalesce(p_segment,'all') not in ('all','institutional_team','guardians','children','dual_profile') then raise invalid_parameter_value using message = 'invalid segment'; end if;
  if p_sort not in ('display_name','type','status','institution_name','unit_name','group_name','contextual_role','auth_link') then raise invalid_parameter_value using message = 'unsupported people sort'; end if;

  -- Preserva as rejeições de contexto já expostas pelo contrato existente.
  if exists (select 1 from public.units u where u.id = any(coalesce(p_unit_ids,array[]::uuid[]))
      and cardinality(coalesce(p_institution_ids,array[]::uuid[])) > 0
      and not u.institution_id = any(p_institution_ids)) then
    raise check_violation using message = 'unit filter crosses institution selection';
  end if;
  if exists (select 1 from public.groups g where g.id = any(coalesce(p_group_ids,array[]::uuid[]))
      and ((cardinality(coalesce(p_institution_ids,array[]::uuid[])) > 0 and not g.institution_id = any(p_institution_ids))
        or (cardinality(coalesce(p_unit_ids,array[]::uuid[])) > 0 and not g.unit_id = any(p_unit_ids)))) then
    raise check_violation using message = 'group filter crosses selected context';
  end if;

  with base_context_rows as (
    -- Papel institucional vigente.
    select m.person_id, a.id row_id, m.institution_id, a.scope_unit_id unit_id,
      a.scope_group_id group_id, r.code contextual_role, r.name contextual_role_name, null::uuid activity_id
    from public.institution_memberships m
    join public.institution_role_assignments a on a.membership_id=m.id and a.status='active'
    join public.institution_roles r on r.id=a.role_id
    where m.status='active' and m.revoked_at is null
    union all
    -- Criança no contexto de unidade/grupo vigente.
    select c.child_person_id, c.id, c.institution_id, ul.unit_id, gl.group_id, 'student', 'Aluno', null::uuid
    from public.child_contexts c
    join public.child_unit_links ul on ul.child_context_id=c.id
      and ul.status in ('pending','awaiting_allocation','active') and ul.revoked_at is null
    left join public.child_group_links gl on gl.child_unit_link_id=ul.id and gl.status='active'
    where c.status='active'
    union all
    -- Profissional é elegível somente pela atribuição e vínculo de atividade ativos.
    select aga.person_id, aga.id, agl.institution_id, agl.unit_id, agl.group_id,
      aga.assignment_role, aga.assignment_role, agl.activity_id
    from public.activity_group_assignments aga
    join public.activity_group_links agl on agl.id=aga.activity_group_link_id
      and agl.institution_id=aga.institution_id and agl.status='active'
    where aga.status='active' and aga.revoked_at is null
    union all
    -- Criança: grupo/unidade ativo e participante ativo quando a atividade é selected.
    select c.child_person_id, cgl.id, agl.institution_id, agl.unit_id, agl.group_id,
      'student', 'Aluno', agl.activity_id
    from public.child_contexts c
    join public.child_unit_links cul on cul.child_context_id=c.id
      and cul.status in ('pending','awaiting_allocation','active') and cul.revoked_at is null
    join public.child_group_links cgl on cgl.child_unit_link_id=cul.id and cgl.status='active'
    join public.activity_group_links agl on agl.group_id=cgl.group_id and agl.unit_id=cul.unit_id
      and agl.institution_id=c.institution_id and agl.status='active'
    left join public.activity_group_participants agp on agp.activity_group_link_id=agl.id
      and agp.child_group_link_id=cgl.id and agp.status='active' and agp.removed_at is null
    where c.status='active' and (agl.participation_mode='all' or agp.id is not null)
  ), context_rows as (
    select b.*, coalesce(ua.state,ia.state) state_code,
      coalesce(ua.city,ia.city) municipality_id, coalesce(ua.district,ia.district) neighborhood_id,
      i.public_name institution_name, u.name unit_name, g.name group_name, b.contextual_role_name role_name,
      activity.name activity_name
    from base_context_rows b
    join public.institutions i on i.id=b.institution_id
    left join public.units u on u.id=b.unit_id and u.institution_id=b.institution_id
    left join public.groups g on g.id=b.group_id and g.unit_id=b.unit_id and g.institution_id=b.institution_id
    left join public.activity_definitions activity on activity.id=b.activity_id and activity.institution_id=b.institution_id
    left join public.unit_addresses ua on ua.unit_id=b.unit_id and ua.status='active'
    left join public.institution_addresses ia on ia.institution_id=b.institution_id and ia.status='active'
  ), filtered as (
    select p.id,p.display_name,p.person_type,p.status,p.updated_at,
      coalesce((select min(lower(c.institution_name)) from context_rows c where c.person_id=p.id),'') institution_sort,
      coalesce((select min(lower(c.unit_name)) from context_rows c where c.person_id=p.id),'') unit_sort,
      coalesce((select min(lower(c.group_name)) from context_rows c where c.person_id=p.id),'') group_sort,
      coalesce((select min(lower(c.role_name)) from context_rows c where c.person_id=p.id),'') role_sort,
      case when exists(select 1 from public.person_auth_links x where x.person_id=p.id and x.status='active' and x.revoked_at is null) then 'linked'
           when exists(select 1 from public.person_auth_links x where x.person_id=p.id and x.revoked_at is null) then 'pending' else 'unlinked' end auth_link_state
    from public.people p
    where p.deleted_at is null
      and (coalesce(p_segment,'all')='all' or (p_segment='children' and p.person_type='child')
        or (p_segment='guardians' and exists(select 1 from public.guardian_links x where x.guardian_person_id=p.id and x.status='active' and x.revoked_at is null))
        or (p_segment='institutional_team' and exists(select 1 from public.institution_memberships x where x.person_id=p.id and x.status='active' and x.revoked_at is null))
        or (p_segment='dual_profile' and exists(select 1 from public.guardian_links x where x.guardian_person_id=p.id and x.status='active' and x.revoked_at is null) and exists(select 1 from public.institution_memberships x where x.person_id=p.id and x.status='active' and x.revoked_at is null)))
      and (nullif(btrim(coalesce(p_search,'')),'') is null or p.display_name ilike '%'||btrim(p_search)||'%')
      and (cardinality(coalesce(p_types,array[]::public.person_type[]))=0 or p.person_type=any(p_types))
      and (cardinality(coalesce(p_statuses,array[]::public.record_status[]))=0 or p.status=any(p_statuses))
      and (cardinality(coalesce(p_auth_links,array[]::text[]))=0 or (case when exists(select 1 from public.person_auth_links x where x.person_id=p.id and x.status='active' and x.revoked_at is null) then 'linked' when exists(select 1 from public.person_auth_links x where x.person_id=p.id and x.revoked_at is null) then 'pending' else 'unlinked' end)=any(p_auth_links))
      and (cardinality(coalesce(p_institution_ids,array[]::uuid[]))=0 and cardinality(coalesce(p_unit_ids,array[]::uuid[]))=0 and cardinality(coalesce(p_group_ids,array[]::uuid[]))=0 and cardinality(coalesce(p_contextual_roles,array[]::text[]))=0 and cardinality(coalesce(p_activity_ids,array[]::uuid[]))=0 and cardinality(coalesce(p_state_codes,array[]::text[]))=0 and cardinality(coalesce(p_municipality_ids,array[]::text[]))=0 and cardinality(coalesce(p_neighborhood_ids,array[]::text[]))=0
        or exists(select 1 from context_rows c where c.person_id=p.id
          and (cardinality(coalesce(p_institution_ids,array[]::uuid[]))=0 or c.institution_id=any(p_institution_ids))
          and (cardinality(coalesce(p_unit_ids,array[]::uuid[]))=0 or c.unit_id=any(p_unit_ids))
          and (cardinality(coalesce(p_group_ids,array[]::uuid[]))=0 or c.group_id=any(p_group_ids))
          and (cardinality(coalesce(p_contextual_roles,array[]::text[]))=0 or c.contextual_role=any(p_contextual_roles))
          and (cardinality(coalesce(p_activity_ids,array[]::uuid[]))=0 or c.activity_id=any(p_activity_ids))
          and (cardinality(coalesce(p_state_codes,array[]::text[]))=0 or c.state_code=any(p_state_codes))
          and (cardinality(coalesce(p_municipality_ids,array[]::text[]))=0 or c.municipality_id=any(p_municipality_ids))
          and (cardinality(coalesce(p_neighborhood_ids,array[]::text[]))=0 or c.neighborhood_id=any(p_neighborhood_ids))))
  ), ranked as (
    select f.*, row_number() over(order by
      case when p_sort_ascending and p_sort='display_name' then lower(f.display_name) end asc, case when not p_sort_ascending and p_sort='display_name' then lower(f.display_name) end desc,
      case when p_sort_ascending and p_sort='type' then f.person_type::text end asc, case when not p_sort_ascending and p_sort='type' then f.person_type::text end desc,
      case when p_sort_ascending and p_sort='status' then f.status::text end asc, case when not p_sort_ascending and p_sort='status' then f.status::text end desc,
      case when p_sort_ascending and p_sort='institution_name' then f.institution_sort end asc, case when not p_sort_ascending and p_sort='institution_name' then f.institution_sort end desc,
      case when p_sort_ascending and p_sort='unit_name' then f.unit_sort end asc, case when not p_sort_ascending and p_sort='unit_name' then f.unit_sort end desc,
      case when p_sort_ascending and p_sort='group_name' then f.group_sort end asc, case when not p_sort_ascending and p_sort='group_name' then f.group_sort end desc,
      case when p_sort_ascending and p_sort='contextual_role' then f.role_sort end asc, case when not p_sort_ascending and p_sort='contextual_role' then f.role_sort end desc,
      case when p_sort_ascending and p_sort='auth_link' then f.auth_link_state end asc, case when not p_sort_ascending and p_sort='auth_link' then f.auth_link_state end desc, lower(f.display_name),f.id) ordinal
    from filtered f
  ), page_rows as (select * from ranked where ordinal>p_offset and ordinal<=p_offset+p_limit)
  select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'display_name',q.display_name,'type',q.person_type,'status',q.status,'auth_link',q.auth_link_state,'memberships',coalesce((select jsonb_agg(jsonb_build_object('id',c.row_id,'institution_id',c.institution_id,'institution_name',c.institution_name,'unit_id',c.unit_id,'unit_name',c.unit_name,'group_id',c.group_id,'group_name',c.group_name,'activity_id',c.activity_id,'activity_name',c.activity_name,'role',c.contextual_role,'role_name',c.role_name) order by lower(c.institution_name),lower(c.unit_name),lower(c.group_name),c.row_id) from context_rows c where c.person_id=q.id),'[]'::jsonb),'updated_at',q.updated_at) order by q.ordinal) from page_rows q),'[]'::jsonb),'total_count',(select count(*) from filtered)) into result;
  return result;
end; $$;


ALTER FUNCTION "public"."superadmin_people_list"("p_search" "text", "p_types" "public"."person_type"[], "p_statuses" "public"."record_status"[], "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_group_ids" "uuid"[], "p_contextual_roles" "text"[], "p_auth_links" "text"[], "p_sort" "text", "p_sort_ascending" boolean, "p_offset" integer, "p_limit" integer, "p_segment" "text", "p_activity_ids" "uuid"[], "p_state_codes" "text"[], "p_municipality_ids" "text"[], "p_neighborhood_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_people_update"("p_update" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_variable
declare
  person_id uuid;
  expected_updated_at timestamptz;
  person_type public.person_type;
  normalized_changes jsonb;
begin
  perform app_private.assert_people_permission('people.update');
  if jsonb_typeof(coalesce(p_update, '{}'::jsonb)) <> 'object' then
    raise invalid_parameter_value using message = 'update must be an object';
  end if;
  if exists (
    select 1
    from jsonb_object_keys(coalesce(p_update, '{}'::jsonb)) key
    where key not in (
      'person_id',
      'expected_updated_at',
      'first_name',
      'last_name',
      'display_name',
      'legal_name',
      'context_changes',
      'membership_changes',
      'child_context_changes'
    )
  ) then
    raise invalid_parameter_value using message = 'update field is not editable';
  end if;
  person_id := nullif(p_update ->> 'person_id', '')::uuid;
  expected_updated_at :=
    nullif(p_update ->> 'expected_updated_at', '')::timestamptz;
  select person.person_type
  into person_type
  from public.people person
  where person.id = person_id
    and person.deleted_at is null;
  if not found then
    raise no_data_found using message = 'person not found';
  end if;
  if expected_updated_at is null then
    raise invalid_parameter_value using message = 'expected_updated_at is required';
  end if;

  if p_update ? 'context_changes' then
    if jsonb_typeof(p_update -> 'context_changes') <> 'array' then
      raise invalid_parameter_value using message = 'context_changes must be an array';
    end if;
    normalized_changes := p_update -> 'context_changes';
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'kind', case
        when person_type = 'adult' then 'institution_membership'
        else 'child_context'
      end,
      'operation', case
        when change ->> 'operation' = 'remove' then 'revoke'
        else change ->> 'operation'
      end,
      'membership_id', change ->> 'membership_id',
      'assignment_id', change ->> 'assignment_id',
      'child_context_id', coalesce(
        change ->> 'child_context_id',
        change ->> 'membership_id'
      ),
      'child_unit_link_id', change ->> 'child_unit_link_id',
      'child_group_link_id', change ->> 'child_group_link_id',
      'institution_id', change ->> 'institution_id',
      'scope_unit_id', change ->> 'unit_id',
      'scope_group_id', change ->> 'group_id',
      'unit_id', change ->> 'unit_id',
      'group_id', change ->> 'group_id',
      'role_code', coalesce(change ->> 'role_code', change ->> 'role')
    )), '[]'::jsonb)
    into normalized_changes
    from jsonb_array_elements(case
      when person_type = 'child'
        then coalesce(p_update -> 'child_context_changes', '[]'::jsonb)
      else coalesce(p_update -> 'membership_changes', '[]'::jsonb)
    end) change;
  end if;

  perform app_private.update_superadmin_person(
    person_id,
    expected_updated_at,
    p_update
      - 'person_id'
      - 'expected_updated_at'
      - 'context_changes'
      - 'membership_changes'
      - 'child_context_changes',
    normalized_changes
  );

  return app_private.superadmin_person_payload(person_id);
end
$$;


ALTER FUNCTION "public"."superadmin_people_update"("p_update" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_person_detail_v2"("p_person_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  context_record app_private.superadmin_internal_context;
  correlation_id uuid:=gen_random_uuid();
  response_data jsonb;
  error_code text;
  error_detail text;
begin
  begin
    select * into strict context_record
    from app_private.require_superadmin_internal_context('people.read');

    if p_person_id is null
      or context_record.platform_role_code<>'owner'
      or context_record.scope_kind not in('platform','institution') then
      raise insufficient_privilege using
        message='internal person access denied',
        detail='SAI_PERMISSION_DENIED';
    end if;

    response_data:=app_private.superadmin_person_detail_payload_v2(
      p_person_id,
      context_record.scope_kind,
      context_record.scope_institution_id
    );
    if response_data is null then
      raise insufficient_privilege using
        message='internal person access denied',
        detail='SAI_PERMISSION_DENIED';
    end if;
  exception
    when insufficient_privilege then
      get stacked diagnostics error_detail=pg_exception_detail;
      error_code:=case when error_detail in(
        'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
        'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED',
        'SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED'
      ) then error_detail else 'SAI_INTERNAL_ERROR' end;
    when others then
      error_code:='SAI_INTERNAL_ERROR';
  end;

  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'people.read','person.detail',error_code,correlation_id,null);
    return app_private.superadmin_internal_error_envelope(
      error_code,correlation_id);
  end if;

  perform app_private.audit_append_superadmin_internal(
    context_record.internal_identity_id,
    context_record.internal_auth_link_id,
    context_record.internal_membership_id,
    context_record.session_id,
    'people.read',
    context_record.aal,
    'person.detail',
    'success',
    null,
    correlation_id,
    case when context_record.scope_kind='institution'
      then context_record.scope_institution_id else null end,
    'person',
    p_person_id
  );

  return jsonb_build_object(
    'ok',true,
    'data',response_data,
    'error',null
  );
end
$$;


ALTER FUNCTION "public"."superadmin_person_detail_v2"("p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_person_handle_availability"("p_handle" "text", "p_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized text := app_private.normalize_person_handle(p_handle);
  reason text := 'ok';
begin
  if (select auth.uid()) is null then
    raise insufficient_privilege using message = 'person handle permission denied';
  end if;
  if not app_private.person_handle_is_valid(normalized) then
    reason := 'invalid_format';
  elsif app_private.person_handle_is_reserved(normalized) then
    reason := 'reserved';
  elsif exists (select 1 from public.person_handles h
                where h.normalized_handle = normalized and h.status = 'active' and h.revoked_at is null
                  and (p_person_id is null or h.person_id <> p_person_id)) then
    reason := 'taken';
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'handle', normalized, 'available', reason = 'ok', 'reason', reason), 'error', null);
end
$$;


ALTER FUNCTION "public"."superadmin_person_handle_availability"("p_handle" "text", "p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_person_handle_get"("p_person_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  handle_record public.person_handles%rowtype;
  last_change timestamptz;
begin
  if not app_private.person_handle_actor_can(p_person_id, false) then
    raise insufficient_privilege using message = 'person handle permission denied';
  end if;
  select * into handle_record from public.person_handles h
  where h.person_id = p_person_id and h.status = 'active' and h.revoked_at is null;
  if not found then
    return jsonb_build_object('ok', true, 'data', null, 'error', null);
  end if;
  select max(l.changed_at) into last_change
  from app_private.person_identity_correction_ledger l
  where l.person_id = p_person_id and l.correction_kind = 'handle' and l.old_value is not null;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'person_id', p_person_id,
    'handle', handle_record.normalized_handle,
    'last_changed_at', last_change,
    'can_change_at', case when last_change is null then now() else last_change + interval '30 days' end,
    'can_edit', app_private.person_handle_actor_can(p_person_id, true)), 'error', null);
end
$$;


ALTER FUNCTION "public"."superadmin_person_handle_get"("p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_person_handle_set"("p_request_id" "uuid", "p_person_id" "uuid", "p_handle" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized text := app_private.normalize_person_handle(p_handle);
  availability jsonb;
  current_handle text;
begin
  if not app_private.person_handle_actor_can(p_person_id, true) then
    raise insufficient_privilege using message = 'person handle permission denied';
  end if;
  if p_request_id is null or nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise invalid_parameter_value using message = 'request id and reason are required';
  end if;
  select h.normalized_handle into current_handle from public.person_handles h
  where h.person_id = p_person_id and h.status = 'active' and h.revoked_at is null;
  if current_handle = normalized then
    return public.superadmin_person_handle_get(p_person_id);
  end if;
  availability := public.superadmin_person_handle_availability(normalized, p_person_id);
  if not (availability->'data'->>'available')::boolean then
    raise invalid_parameter_value using
      message = 'person handle unavailable', detail = availability->'data'->>'reason';
  end if;
  perform set_config('coelo.identity_change_reason', btrim(p_reason), true);
  if current_handle is null then
    insert into public.person_handles(person_id, normalized_handle, visibility, status)
    values (p_person_id, normalized, 'private', 'active');
  else
    begin
      update public.person_handles set normalized_handle = normalized
      where person_id = p_person_id and status = 'active' and revoked_at is null;
    exception when check_violation then
      raise invalid_parameter_value using
        message = 'person handle unavailable', detail = 'cooldown';
    end;
  end if;
  return public.superadmin_person_handle_get(p_person_id);
end
$$;


ALTER FUNCTION "public"."superadmin_person_handle_set"("p_request_id" "uuid", "p_person_id" "uuid", "p_handle" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_plan_get"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_result jsonb;
begin
  perform app_private.assert_plan_permission('platform.read',false);
  select jsonb_build_object(
    'id',p.id,'name',p.name,'code',p.code,'description',p.description,'status',p.status::text,'revision',p.revision,
    'used_by_institution_count',(select count(*) from public.institution_subscriptions s where s.plan_id=p.id and s.status in ('active','draft')),
    'entitlements',coalesce((select jsonb_object_agg(pe.entitlement_key,pe.value_json) from public.plan_entitlements pe where pe.plan_id=p.id and pe.status='active'),'{}'::jsonb),
    'linked_institutions',coalesce((select jsonb_agg(jsonb_build_object(
      'id',i.id,'name',i.legal_name,'subscription_status',s.status::text,'starts_at',s.starts_at,'units_with_override',0
    ) order by i.legal_name,i.id) from public.institution_subscriptions s join public.institutions i on i.id=s.institution_id where s.plan_id=p.id),'[]'::jsonb)
  ) into v_result from public.plans p where p.id=p_plan_id;
  if v_result is null then raise exception using errcode='P0002',message='plan_not_found'; end if;
  return v_result;
end; $$;


ALTER FUNCTION "public"."superadmin_plan_get"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_plan_save"("p_request_id" "uuid", "p_plan_id" "uuid", "p_expected_revision" bigint, "p_payload" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid; v_plan public.plans%rowtype; v_existing public.plans%rowtype; v_key text; v_value jsonb; v_action text;
  v_status text := coalesce(p_payload->>'status','active');
begin
  v_actor:=app_private.assert_plan_permission('plan.change',true);
  if p_request_id is null then raise exception using errcode='22023',message='request_id_required'; end if;
  if coalesce(char_length(trim(p_reason)),0) not between 1 and 1000 then raise exception using errcode='22023',message='reason_required'; end if;
  if coalesce(char_length(trim(p_payload->>'name')),0) not between 1 and 160 or coalesce(char_length(trim(p_payload->>'description')),0) not between 1 and 2000 then
    raise exception using errcode='22023',message='invalid_plan_identity';
  end if;
  if v_status not in ('active','archived') then raise exception using errcode='22023',message='invalid_status'; end if;
  select p.* into v_existing from public.plans p join public.plan_change_receipts r on r.plan_id=p.id where r.request_id=p_request_id;
  if found then return public.superadmin_plan_get(v_existing.id); end if;
  if p_plan_id is null then
    if coalesce(p_payload->>'code','') !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception using errcode='22023',message='invalid_plan_code'; end if;
    insert into public.plans(code,name,description,status,billing_mode,revision,created_by_person_id,updated_by_person_id)
    values(p_payload->>'code',trim(p_payload->>'name'),trim(p_payload->>'description'),v_status::public.record_status,'manual',1,v_actor,v_actor)
    returning * into v_plan;
    v_action:='create';
  else
    select * into v_existing from public.plans where id=p_plan_id for update;
    if not found then raise exception using errcode='P0002',message='plan_not_found'; end if;
    if p_expected_revision is null or p_expected_revision<>v_existing.revision then raise exception using errcode='40001',message='plan_revision_conflict'; end if;
    if p_payload?'code' and p_payload->>'code'<>v_existing.code then raise exception using errcode='22023',message='plan_code_immutable'; end if;
    update public.plans set name=trim(p_payload->>'name'),description=trim(p_payload->>'description'),
      status=v_status::public.record_status,revision=revision+1,updated_at=now(),updated_by_person_id=v_actor
    where id=p_plan_id returning * into v_plan;
    v_action:=case when v_existing.status='active' and v_plan.status='archived' then 'archive'
      when v_existing.status='archived' and v_plan.status='active' then 'restore' else 'update' end;
  end if;
  delete from public.plan_entitlements where plan_id=v_plan.id;
  for v_key,v_value in select key,value from jsonb_each(coalesce(p_payload->'entitlements','{}'::jsonb)) loop
    if v_key not in ('feature.communication','feature.agenda','feature.invitations','feature.chat','feature.notices','feature.routine','feature.happens','feature.now','feature.moments','limit.units','limit.memberships','limit.storage_gb','limit.media_gb') then
      raise exception using errcode='22023',message='invalid_entitlement';
    end if;
    if v_key like 'feature.%' and jsonb_typeof(v_value->'enabled')<>'boolean' then raise exception using errcode='22023',message='invalid_feature_value'; end if;
    if v_key like 'limit.%' and (jsonb_typeof(v_value->'value')<>'number' or (v_value->>'value')::numeric<0 or (v_value->>'value')::numeric>100000000) then
      raise exception using errcode='22023',message='invalid_limit_value';
    end if;
    insert into public.plan_entitlements(plan_id,entitlement_key,value_kind,value_json,status)
    values(v_plan.id,v_key,case when v_key like 'feature.%' then 'boolean' else 'integer' end,v_value,'active');
  end loop;
  insert into public.plan_change_receipts(request_id,plan_id,actor_person_id,action,previous_revision,next_revision,reason)
  values(p_request_id,v_plan.id,v_actor,v_action,v_existing.revision,v_plan.revision,trim(p_reason));
  return public.superadmin_plan_get(v_plan.id);
exception when unique_violation then raise exception using errcode='23505',message='plan_code_or_request_conflict';
end; $_$;


ALTER FUNCTION "public"."superadmin_plan_save"("p_request_id" "uuid", "p_plan_id" "uuid", "p_expected_revision" bigint, "p_payload" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_plans_list"("p_search" "text" DEFAULT ''::"text", "p_status" "text" DEFAULT NULL::"text", "p_feature" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 11) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_offset integer; v_result jsonb;
begin
  perform app_private.assert_plan_permission('platform.read',false);
  if p_page<1 or p_page_size<1 or p_page_size>100 then raise exception using errcode='22023',message='invalid_pagination'; end if;
  if p_status is not null and p_status not in ('active','archived') then raise exception using errcode='22023',message='invalid_status'; end if;
  if p_feature is not null and p_feature not in ('communication','agenda','invitations','chat','notices','routine','happens','now','moments') then
    raise exception using errcode='22023',message='invalid_feature';
  end if;
  v_offset := (p_page-1)*p_page_size;
  with filtered as (
    select p.* from public.plans p
    where (coalesce(trim(p_search),'')='' or p.name ilike '%'||trim(p_search)||'%' or p.code ilike '%'||trim(p_search)||'%')
      and (p_status is null or p.status::text=p_status)
      and (p_feature is null or exists(
        select 1 from public.plan_entitlements pe where pe.plan_id=p.id and pe.entitlement_key='feature.'||p_feature
          and pe.status='active' and coalesce((pe.value_json->>'enabled')::boolean,false)
      ))
  ), page_rows as (
    select * from filtered order by name,id limit p_page_size offset v_offset
  )
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',pr.id,'name',pr.name,'code',pr.code,'description',pr.description,'status',pr.status::text,'revision',pr.revision,
      'used_by_institution_count',(select count(*) from public.institution_subscriptions s where s.plan_id=pr.id and s.status in ('active','draft')),
      'entitlements',coalesce((select jsonb_object_agg(pe.entitlement_key,pe.value_json) from public.plan_entitlements pe where pe.plan_id=pr.id and pe.status='active'),'{}'::jsonb)
    ) order by pr.name,pr.id),'[]'::jsonb),
    'total_items',(select count(*) from filtered),'page',p_page,'page_size',p_page_size
  ) into v_result from page_rows pr;
  return v_result;
end; $$;


ALTER FUNCTION "public"."superadmin_plans_list"("p_search" "text", "p_status" "text", "p_feature" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


