CREATE OR REPLACE FUNCTION "public"."superadmin_publication_contexts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid := app_private.current_person_id();
  actor_aal text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'aal',
    'aal1'
  );
  result jsonb;
begin
  if (select auth.uid()) is null or actor_person_id is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;

  select jsonb_build_object(
    'contexts',
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'tenant_id', c.institution_id,
          'institution_id', c.institution_id,
          'institution_name', c.institution_name,
          'unit_id', c.unit_id,
          'unit_name', c.unit_name,
          'group_id', c.group_id,
          'group_name', c.group_name,
          'allowed_audiences', jsonb_build_array(
            'families', 'students', 'school_staff', 'guardians_only'
          ),
          'max_video_duration_seconds',
            app_private.profile_about_publication_max_video_seconds(c.institution_id),
          'can_update_profile_about_official_data',
            c.about_update_official and actor_aal = 'aal2',
          'capabilities', jsonb_build_object(
            'now', jsonb_build_object(
              'read', false,
              'create', c.now_create,
              'publish', c.now_publish
            ),
            'moments', jsonb_build_object(
              'read', c.moments_read,
              'create', c.moments_create,
              'publish', c.moments_publish
            ),
            'happens', jsonb_build_object(
              'read', c.happens_read,
              'create', c.happens_create,
              'publish', c.happens_publish
            ),
            'circulars', jsonb_build_object(
              'read', c.circulars_read,
              'create', c.circulars_create,
              'publish', c.circulars_publish
            ),
            'about', jsonb_build_object(
              'read', c.about_read,
              'manage', c.about_manage,
              'publish', c.about_publish,
              'update_official_data', c.about_update_official and actor_aal = 'aal2'
            )
          )
        )
        order by lower(c.institution_name), lower(c.unit_name), lower(c.group_name), c.group_id
      ),
      '[]'::jsonb
    )
  )
  into result
  from (
    select
      i.id as institution_id,
      i.public_name as institution_name,
      u.id as unit_id,
      u.name as unit_name,
      g.id as group_id,
      g.name as group_name,
      app_private.has_institution_permission(
        i.id, 'now.publications.create', u.id, g.id, false
      ) as now_create,
      app_private.has_institution_permission(
        i.id, 'now.publications.publish', u.id, g.id, false
      ) as now_publish,
      app_private.has_institution_permission(
        i.id, 'moments.publications.read', u.id, g.id, false
      ) as moments_read,
      app_private.has_institution_permission(
        i.id, 'moments.publications.create', u.id, g.id, false
      ) as moments_create,
      app_private.has_institution_permission(
        i.id, 'moments.publications.publish', u.id, g.id, false
      ) as moments_publish,
      app_private.has_institution_permission(
        i.id, 'happens.posts.read', u.id, g.id, false
      ) as happens_read,
      app_private.has_institution_permission(
        i.id, 'happens.posts.create', u.id, g.id, false
      ) as happens_create,
      app_private.has_institution_permission(
        i.id, 'happens.posts.publish', u.id, g.id, false
      ) as happens_publish,
      app_private.has_institution_permission(
        i.id, 'circulars.circulars.read', u.id, g.id, false
      ) as circulars_read,
      app_private.has_institution_permission(
        i.id, 'circulars.circulars.create', u.id, g.id, false
      ) as circulars_create,
      app_private.has_institution_permission(
        i.id, 'circulars.circulars.publish', u.id, g.id, false
      ) as circulars_publish,
      app_private.has_institution_permission(
        i.id, 'profiles.about.read', u.id, g.id, false
      ) as about_read,
      app_private.has_institution_permission(
        i.id, 'profiles.about.manage', u.id, g.id, false
      ) as about_manage,
      app_private.has_institution_permission(
        i.id, 'profiles.about.publish', u.id, g.id, false
      ) as about_publish,
      app_private.has_institution_permission(
        i.id, 'profiles.about.update_official_data', u.id, g.id, false
      ) as about_update_official
    from public.institution_memberships m
    join public.institutions i
      on i.id = m.institution_id and i.status = 'active'
    join public.units u
      on u.institution_id = i.id and u.status = 'active'
    join public.groups g
      on g.institution_id = i.id and g.unit_id = u.id and g.status = 'active'
    where m.person_id = actor_person_id
      and m.status = 'active'
      and m.revoked_at is null
  ) c
  where c.now_create
    or c.now_publish
    or c.moments_read
    or c.moments_create
    or c.moments_publish
    or c.happens_read
    or c.happens_create
    or c.happens_publish
    or c.circulars_read
    or c.circulars_create
    or c.circulars_publish
    or c.about_read
    or c.about_manage
    or c.about_publish
    or c.about_update_official;

  return result;
end
$$;


