CREATE OR REPLACE FUNCTION "public"."superadmin_support_create"("p_request_id" "uuid", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_subject" "text", "p_menu" "text", "p_screen" "text", "p_reported_issue" "text", "p_requester_label" "text", "p_priority" "text" DEFAULT 'normal'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; session_id uuid; result jsonb;
begin
  actor_id := app_private.assert_support_permission();
  if p_request_id is null or char_length(trim(coalesce(p_subject,''))) not between 1 and 160
    or char_length(trim(coalesce(p_menu,''))) not between 1 and 80
    or char_length(trim(coalesce(p_screen,''))) not between 1 and 120
    or char_length(trim(coalesce(p_requester_label,''))) not between 1 and 160
    or char_length(trim(coalesce(p_reported_issue,''))) not between 1 and 10000
    or p_priority not in ('low','normal','high','urgent')
    or (p_unit_id is not null and p_institution_id is null) then
    raise exception using errcode = '22023', message = 'invalid_support_request';
  end if;
  select support_session_id into session_id from public.support_command_receipts where request_id = p_request_id;
  if session_id is not null then return public.superadmin_support_get(session_id); end if;
  insert into public.support_sessions(
    opened_by_person_id, institution_id, unit_id, subject, menu_code, screen_code,
    requester_label, reported_issue, priority, ticket_status, updated_at,
    scope_kind, reason_code
  ) values (
    actor_id, p_institution_id, p_unit_id, trim(p_subject), trim(p_menu), trim(p_screen),
    trim(p_requester_label), trim(p_reported_issue), p_priority, 'new', now(),
    case when p_institution_id is null then 'platform' else 'institution' end,
    'internal_report'
  ) returning id into session_id;
  insert into audit.support_session_actions(support_session_id, action_code, object_type, object_id, metadata_json)
    values (session_id, 'support.create', 'support_session', session_id, jsonb_build_object('actor_person_id', actor_id));
  result := public.superadmin_support_get(session_id);
  insert into public.support_command_receipts(request_id, support_session_id, actor_person_id, action_code, response_json)
    values (p_request_id, session_id, actor_id, 'create', result);
  return result;
end;
$$;


ALTER FUNCTION "public"."superadmin_support_create"("p_request_id" "uuid", "p_institution_id" "uuid", "p_unit_id" "uuid", "p_subject" "text", "p_menu" "text", "p_screen" "text", "p_reported_issue" "text", "p_requester_label" "text", "p_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_support_get"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.assert_support_permission();
  select jsonb_build_object(
    'id', s.id, 'subject', s.subject, 'menu', s.menu_code, 'screen', s.screen_code,
    'description', s.reported_issue, 'requester', s.requester_label,
    'institution_id', s.institution_id, 'unit_id', s.unit_id,
    'status', s.ticket_status, 'priority', s.priority, 'revision', s.revision,
    'created_at', s.opened_at, 'updated_at', s.updated_at,
    'assignee_membership_id', s.assigned_to_membership_id,
    'closure_reason', case when s.status in ('expired','revoked') then s.status::text end,
    'messages', coalesce((select jsonb_agg(jsonb_build_object(
      'id', m.id, 'text', m.message_text,
      'author', case when m.author_membership_id is null then 'requester' else 'support' end,
      'created_at', m.created_at, 'read', m.deleted_at is not null
    ) order by m.created_at, m.id) from public.support_messages m
      where m.support_session_id = s.id and m.deleted_at is null), '[]'::jsonb),
      'activities', coalesce((select jsonb_agg(jsonb_build_object(
      'id', a.id, 'action', a.action_code, 'outcome', a.outcome::text,
      'occurred_at', a.occurred_at, 'metadata', a.metadata_json
    ) order by a.occurred_at, a.id) from audit.support_session_actions a
      where a.support_session_id = s.id), '[]'::jsonb)
  ) into result
  from public.support_sessions s where s.id = p_session_id;
  if result is null then raise exception using errcode = 'P0002', message = 'support_session_not_found'; end if;
  return result;
end;
$$;


ALTER FUNCTION "public"."superadmin_support_get"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_support_list"("p_search" "text" DEFAULT ''::"text", "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_menus" "text"[] DEFAULT NULL::"text"[], "p_screens" "text"[] DEFAULT NULL::"text"[], "p_assignee_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_unread_only" boolean DEFAULT false, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.assert_support_permission();
  if p_page < 1 or p_page_size not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_pagination';
  end if;
  if coalesce(char_length(p_search), 0) > 200 then
    raise exception using errcode = '22023', message = 'invalid_search';
  end if;
  with filtered as (
    select s.*,
      exists(select 1 from public.support_messages m
        where m.support_session_id = s.id and m.deleted_at is null
          and m.author_membership_id is null) as unread
    from public.support_sessions s
    where (coalesce(trim(p_search), '') = '' or s.subject ilike '%' || trim(p_search) || '%'
      or s.reported_issue ilike '%' || trim(p_search) || '%'
      or s.requester_label ilike '%' || trim(p_search) || '%')
      and (p_statuses is null or s.ticket_status = any(p_statuses))
      and (p_menus is null or s.menu_code = any(p_menus))
      and (p_screens is null or s.screen_code = any(p_screens))
      and (p_assignee_ids is null or s.assigned_to_membership_id = any(p_assignee_ids))
      and (not coalesce(p_unread_only, false) or exists(select 1 from public.support_messages m
        where m.support_session_id = s.id and m.deleted_at is null
          and m.author_membership_id is null))
  ), page_rows as (
    select * from filtered order by updated_at desc, id desc
    limit p_page_size offset ((p_page - 1) * p_page_size)
  )
  select jsonb_build_object(
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'id', id, 'subject', subject, 'menu', menu_code, 'screen', screen_code,
      'description', reported_issue, 'requester', requester_label,
      'institution_id', institution_id, 'unit_id', unit_id,
      'status', ticket_status, 'priority', priority, 'revision', revision,
      'created_at', opened_at, 'updated_at', updated_at, 'unread', unread,
      'assignee_membership_id', assigned_to_membership_id,
      'closure_reason', case when status in ('expired','revoked') then status::text end
    ) order by updated_at desc, id desc), '[]'::jsonb),
    'total_items', (select count(*) from filtered), 'page', p_page, 'page_size', p_page_size
  ) into result from page_rows;
  return result;
end;
$$;


ALTER FUNCTION "public"."superadmin_support_list"("p_search" "text", "p_statuses" "text"[], "p_menus" "text"[], "p_screens" "text"[], "p_assignee_ids" "uuid"[], "p_unread_only" boolean, "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_support_reply"("p_request_id" "uuid", "p_session_id" "uuid", "p_message" "text", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; current_revision bigint; result jsonb;
begin
  actor_id := app_private.assert_support_permission();
  if p_request_id is null or char_length(trim(coalesce(p_message,''))) not between 1 and 10000 then
    raise exception using errcode = '22023', message = 'invalid_support_message';
  end if;
  if exists(select 1 from public.support_command_receipts where request_id = p_request_id) then
    select response_json into result from public.support_command_receipts where request_id = p_request_id;
    return result;
  end if;
  select revision into current_revision from public.support_sessions where id = p_session_id for update;
  if current_revision is null then raise exception using errcode = 'P0002', message = 'support_session_not_found'; end if;
  if p_expected_revision is null or p_expected_revision <> current_revision then
    raise exception using errcode = '40001', message = 'support_revision_conflict';
  end if;
  insert into public.support_messages(support_session_id, author_person_id, author_membership_id, message_text)
    values (p_session_id, actor_id, actor_id, trim(p_message));
  update public.support_sessions set revision = revision + 1, updated_at = now() where id = p_session_id;
  insert into audit.support_session_actions(support_session_id, action_code, object_type, object_id, metadata_json)
    values (p_session_id, 'support.reply', 'support_session', p_session_id, jsonb_build_object('actor_person_id', actor_id));
  result := public.superadmin_support_get(p_session_id);
  insert into public.support_command_receipts(request_id, support_session_id, actor_person_id, action_code, response_json)
    values (p_request_id, p_session_id, actor_id, 'reply', result);
  return result;
end;
$$;


ALTER FUNCTION "public"."superadmin_support_reply"("p_request_id" "uuid", "p_session_id" "uuid", "p_message" "text", "p_expected_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_support_set_assignee"("p_request_id" "uuid", "p_session_id" "uuid", "p_expected_revision" bigint, "p_assignee_membership_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; current_revision bigint; previous_assignee uuid; result jsonb;
begin
  actor_id := app_private.assert_support_permission();
  if p_request_id is null or p_session_id is null then
    raise exception using errcode = '22023', message = 'invalid_support_request';
  end if;
  if exists(select 1 from public.support_command_receipts where request_id = p_request_id) then
    select response_json into result from public.support_command_receipts where request_id = p_request_id;
    return result;
  end if;
  if p_assignee_membership_id is not null and not exists (
    select 1 from public.platform_memberships m
    where m.id = p_assignee_membership_id and m.status = 'active' and m.revoked_at is null
      and m.scope_kind = 'platform' and m.scope_institution_id is null
  ) then
    raise exception using errcode = '22023', message = 'assignee_invalid';
  end if;
  select revision, assigned_to_membership_id into current_revision, previous_assignee
    from public.support_sessions where id = p_session_id for update;
  if current_revision is null then raise exception using errcode = 'P0002', message = 'support_session_not_found'; end if;
  if p_expected_revision is null or p_expected_revision <> current_revision then
    raise exception using errcode = '40001', message = 'support_revision_conflict';
  end if;
  update public.support_sessions set assigned_to_membership_id = p_assignee_membership_id,
    revision = revision + 1, updated_at = now() where id = p_session_id;
  insert into audit.support_session_actions(support_session_id, action_code, object_type, object_id, metadata_json)
    values (p_session_id, 'support.assign', 'support_session', p_session_id,
      jsonb_build_object('actor_person_id', actor_id,
        'assignee_membership_id', p_assignee_membership_id,
        'previous_assignee_membership_id', previous_assignee));
  result := public.superadmin_support_get(p_session_id);
  insert into public.support_command_receipts(request_id, support_session_id, actor_person_id, action_code, response_json)
    values (p_request_id, p_session_id, actor_id, 'assign', result);
  return result;
end;
$$;


ALTER FUNCTION "public"."superadmin_support_set_assignee"("p_request_id" "uuid", "p_session_id" "uuid", "p_expected_revision" bigint, "p_assignee_membership_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."superadmin_support_set_assignee"("p_request_id" "uuid", "p_session_id" "uuid", "p_expected_revision" bigint, "p_assignee_membership_id" "uuid") IS 'Atribui (ou limpa, com nulo) o responsavel de um chamado de Suporte. Recibo idempotente por request_id, revisao otimista (40001), membership de plataforma ativa obrigatoria (22023 assignee_invalid), evento support.assign auditado.';



CREATE OR REPLACE FUNCTION "public"."superadmin_support_set_status"("p_request_id" "uuid", "p_session_id" "uuid", "p_status" "text", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; result jsonb;
begin
  actor_id := app_private.assert_support_permission();
  if p_status not in ('new','in_progress','waiting_requester','completed') then
    raise exception using errcode = '22023', message = 'invalid_support_status';
  end if;
  if exists(select 1 from public.support_command_receipts where request_id = p_request_id) then
    select response_json into result from public.support_command_receipts where request_id = p_request_id; return result;
  end if;
  update public.support_sessions set ticket_status = p_status, revision = revision + 1,
    updated_at = now(), status = case p_status
      when 'completed' then 'resolved'::public.support_session_status
      when 'new' then 'open'::public.support_session_status
      else 'pending'::public.support_session_status end
    where id = p_session_id and revision = p_expected_revision;
  if not found then raise exception using errcode = '40001', message = 'support_revision_conflict'; end if;
  insert into audit.support_session_actions(support_session_id, action_code, object_type, object_id, metadata_json)
    values (p_session_id, 'support.status', 'support_session', p_session_id, jsonb_build_object('actor_person_id', actor_id, 'status', p_status));
  result := public.superadmin_support_get(p_session_id);
  insert into public.support_command_receipts(request_id, support_session_id, actor_person_id, action_code, response_json)
    values (p_request_id, p_session_id, actor_id, 'status', result);
  return result;
end;
$$;


ALTER FUNCTION "public"."superadmin_support_set_status"("p_request_id" "uuid", "p_session_id" "uuid", "p_status" "text", "p_expected_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_support_team_members"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.assert_support_permission();
  with support_permission as (
    select p.id from public.platform_permissions p
    where p.code = 'support.manage' and p.status = 'active'
  ), team as (
    select m.id as membership_id, m.person_id, r.code as role_code,
      trim(coalesce(nullif(trim(p.display_name), ''),
        concat_ws(' ', nullif(trim(p.first_name), ''), nullif(trim(p.last_name), '')))) as display_name,
      m.created_at
    from public.platform_memberships m
    join public.platform_roles r on r.id = m.role_id and r.status = 'active'
    join public.people p on p.id = m.person_id and p.deleted_at is null and p.status = 'active'
    where m.status = 'active' and m.revoked_at is null
      and m.scope_kind = 'platform' and m.scope_institution_id is null
      and (
        p.person_type = 'service'
        or r.code = 'owner'
        or exists (
          select 1 from public.platform_role_permissions rp
          cross join support_permission sp
          where rp.role_id = r.id and rp.permission_id = sp.id
            and rp.status = 'active' and rp.revoked_at is null and rp.effect = 'allow'
        )
      )
  ), named as (
    select t.*,
      (select array_agg(u.w order by u.ord)
       from unnest(regexp_split_to_array(
         regexp_replace(t.display_name, '[^[:alpha:][:space:]]', '', 'g'), '\s+'))
         with ordinality as u(w, ord)
       where u.w <> '') as words
    from team t
  ), shaped as (
    select membership_id, person_id, display_name, role_code,
      case when words is null or cardinality(words) = 0 then 'EQ'
        when cardinality(words) = 1 then upper(left(words[1], 1))
        else upper(left(words[1], 1) || left(words[cardinality(words)], 1)) end as initials,
      created_at
    from named
  )
  select jsonb_build_object(
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'membership_id', membership_id, 'person_id', person_id,
      'display_name', display_name, 'initials', initials, 'role', role_code
    ) order by display_name, created_at, membership_id), '[]'::jsonb),
    'total', count(*)
  ) into result from shaped;
  return result;
end;
$$;


ALTER FUNCTION "public"."superadmin_support_team_members"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."superadmin_support_team_members"() IS 'Equipe de suporte do Superadmin: memberships de plataforma ativas cujo papel concede support.manage ou cuja pessoa e pessoa de servico da ponte interna. Exige sessao e support.manage.';



CREATE OR REPLACE FUNCTION "public"."superadmin_unit_care_policy_get_v1"("p_unit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid := gen_random_uuid(); code text; detail text;
  unit_record public.units%rowtype; payload jsonb;
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context('units.read');
    select * into unit_record from public.units where id = p_unit_id;
    if unit_record.id is null or (ctx.scope_kind = 'institution' and unit_record.institution_id is distinct from ctx.scope_institution_id) then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    payload := app_private.unit_care_policy_payload_v1(p_unit_id);
  exception when others then
    get stacked diagnostics detail = pg_exception_detail;
    code := case when detail like 'SAI_%' then detail else 'SAI_INTERNAL_ERROR' end;
  end;
  if code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified('units.read', 'unit.care_policy.read', code, correlation,
      case when ctx.scope_kind = 'institution' then ctx.scope_institution_id end);
    return app_private.superadmin_internal_error_envelope(code, correlation);
  end if;
  return jsonb_build_object('ok', true, 'data', payload, 'error', null);
end $$;


ALTER FUNCTION "public"."superadmin_unit_care_policy_get_v1"("p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_unit_care_policy_set_v1"("p_request_id" "uuid", "p_unit_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx app_private.superadmin_internal_context; correlation uuid := gen_random_uuid(); code text; detail text;
  unit_record public.units%rowtype; unknown_key text; request_hash bytea; prior app_private.unit_care_policy_receipts%rowtype;
  cs_mode text; med_mode text; n_unit boolean; n_hier boolean; n_guard boolean; result_version bigint; replayed boolean := false;
begin
  begin
    select * into strict ctx from app_private.require_superadmin_internal_context('care_policies.manage');
    select * into unit_record from public.units where id = p_unit_id for share;
    if unit_record.id is null or (ctx.scope_kind = 'institution' and unit_record.institution_id is distinct from ctx.scope_institution_id) then
      raise insufficient_privilege using detail='SAI_PERMISSION_DENIED';
    end if;
    if p_request_id is null or p_payload is null or jsonb_typeof(p_payload) <> 'object' or p_payload = '{}'::jsonb then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    select k into unknown_key from jsonb_object_keys(p_payload) k
    where k not in ('child_safety_mode','medication_mode','notify_unit','notify_child_hierarchy','notify_other_guardians') limit 1;
    if unknown_key is not null then raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT'; end if;
    cs_mode := p_payload ->> 'child_safety_mode'; med_mode := p_payload ->> 'medication_mode';
    if (p_payload ? 'child_safety_mode' and cs_mode not in ('accept_to_release','inclusion_only','exclusion_only'))
      or (p_payload ? 'medication_mode' and med_mode not in ('accept_to_release','inclusion_only','exclusion_only','not_tracked'))
      or (p_payload ? 'notify_unit' and jsonb_typeof(p_payload -> 'notify_unit') <> 'boolean')
      or (p_payload ? 'notify_child_hierarchy' and jsonb_typeof(p_payload -> 'notify_child_hierarchy') <> 'boolean')
      or (p_payload ? 'notify_other_guardians' and jsonb_typeof(p_payload -> 'notify_other_guardians') <> 'boolean') then
      raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
    end if;
    request_hash := extensions.digest(convert_to(jsonb_build_object('unit_id', p_unit_id, 'payload', p_payload)::text, 'UTF8'), 'sha256');
    perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
    select * into prior from app_private.unit_care_policy_receipts where request_id = p_request_id;
    if prior.request_id is not null then
      if prior.actor_internal_identity_id is distinct from ctx.internal_identity_id or prior.unit_id is distinct from p_unit_id
        or prior.request_hash is distinct from request_hash then
        raise invalid_parameter_value using detail='SAI_INVALID_ARGUMENT';
      end if;
      replayed := true; result_version := prior.result_version;
    else
      insert into public.unit_care_policies(unit_id, institution_id, updated_by_internal_identity_id)
      values (p_unit_id, unit_record.institution_id, ctx.internal_identity_id)
      on conflict (unit_id) do nothing;
      update public.unit_care_policies p set
        child_safety_mode = coalesce(cs_mode, p.child_safety_mode),
        medication_mode = coalesce(med_mode, p.medication_mode),
        notify_unit = coalesce((p_payload ->> 'notify_unit')::boolean, p.notify_unit),
        notify_child_hierarchy = coalesce((p_payload ->> 'notify_child_hierarchy')::boolean, p.notify_child_hierarchy),
        notify_other_guardians = coalesce((p_payload ->> 'notify_other_guardians')::boolean, p.notify_other_guardians),
        management_version = p.management_version + 1,
        updated_by_internal_identity_id = ctx.internal_identity_id,
        updated_at = now()
      where p.unit_id = p_unit_id
      returning management_version into result_version;
      insert into app_private.unit_care_policy_receipts(request_id, actor_internal_identity_id, unit_id, request_hash, result_version)
      values (p_request_id, ctx.internal_identity_id, p_unit_id, request_hash, result_version);
      perform app_private.audit_append_superadmin_internal(ctx.internal_identity_id, ctx.internal_auth_link_id,
        ctx.internal_membership_id, ctx.session_id, 'care_policies.manage', ctx.aal, 'unit.care_policy.set', 'success',
        null, correlation, unit_record.institution_id, 'unit', p_unit_id);
    end if;
  exception when others then
    get stacked diagnostics detail = pg_exception_detail;
    code := case when detail like 'SAI_%' then detail else 'SAI_INTERNAL_ERROR' end;
  end;
  if code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified('care_policies.manage', 'unit.care_policy.set', code, correlation,
      case when ctx.scope_kind = 'institution' then ctx.scope_institution_id end);
    return app_private.superadmin_internal_error_envelope(code, correlation);
  end if;
  return jsonb_build_object('ok', true, 'data',
    app_private.unit_care_policy_payload_v1(p_unit_id) || jsonb_build_object('replayed', replayed, 'correlation_id', correlation), 'error', null);
end $$;


ALTER FUNCTION "public"."superadmin_unit_care_policy_set_v1"("p_request_id" "uuid", "p_unit_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_unit_detail_v2"("p_unit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  context_record app_private.superadmin_internal_context;
  correlation_id uuid:=gen_random_uuid();
  target_institution_id uuid;
  response_data jsonb;
  error_code text;
  error_detail text;
begin
  begin
    select * into strict context_record
    from app_private.require_superadmin_internal_context('platform.read');

    if p_unit_id is null then
      raise insufficient_privilege using
        message='internal unit access denied',
        detail='SAI_PERMISSION_DENIED';
    end if;

    if context_record.platform_role_code not in('owner','operations','auditor') then
      raise insufficient_privilege using
        message='internal unit access denied',
        detail='SAI_PERMISSION_DENIED';
    end if;

    if context_record.scope_kind not in('platform','institution') then
      raise insufficient_privilege using
        message='internal unit access denied',
        detail='SAI_PERMISSION_DENIED';
    end if;

    select unit_record.institution_id
      into target_institution_id
    from public.units unit_record
    join public.institutions institution
      on institution.id=unit_record.institution_id
     and institution.deleted_at is null
    where unit_record.id=p_unit_id
      and (
        context_record.scope_kind='platform'
        or (
          context_record.scope_kind='institution'
          and context_record.scope_institution_id=unit_record.institution_id
        )
      )
    for share of unit_record,institution;

    if target_institution_id is null then
      raise insufficient_privilege using
        message='internal unit access denied',
        detail='SAI_PERMISSION_DENIED';
    end if;

    response_data:=app_private.superadmin_unit_detail_payload_v2(p_unit_id);
    if response_data is null then
      raise insufficient_privilege using
        message='internal unit access denied',
        detail='SAI_PERMISSION_DENIED';
    end if;
  exception
    when insufficient_privilege then
      get stacked diagnostics error_detail=pg_exception_detail;
      error_code:=case when error_detail in(
        'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
        'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED',
        'SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED'
      ) then error_detail else 'SAI_INTERNAL_ERROR' end;
    when others then
      error_code:='SAI_INTERNAL_ERROR';
  end;

  if error_code is not null then
    perform app_private.audit_superadmin_internal_denial_if_identified(
      'platform.read','unit.detail',error_code,correlation_id,null);
    return app_private.superadmin_internal_error_envelope(
      error_code,correlation_id);
  end if;

  perform app_private.audit_append_superadmin_internal(
    context_record.internal_identity_id,
    context_record.internal_auth_link_id,
    context_record.internal_membership_id,
    context_record.session_id,
    'platform.read',
    context_record.aal,
    'unit.detail',
    'success',
    null,
    correlation_id,
    target_institution_id,
    'unit',
    p_unit_id
  );

  return jsonb_build_object(
    'ok',true,
    'data',response_data,
    'error',null
  );
end
$$;


