    CONSTRAINT "form_multipart_uploads_provider_ck" CHECK (((("artifact_provider" = 'supabase_mvp'::"text") AND ("bucket_id" = 'coelo-forms-private'::"text") AND ("object_path" ~ '^[0-9a-f]{2}/[0-9a-f-]{36}$'::"text") AND ("media_asset_id" IS NULL) AND ("worker_attempt" IS NULL) AND ("attempt_owner" IS NULL) AND ("snapshot_format_version" IS NULL) AND ("snapshot_row_count" IS NULL) AND ("checksum_sha256" IS NULL)) OR (("artifact_provider" = 'r2'::"text") AND ("bucket_id" = 'coelo-transient-prod'::"text") AND ("media_asset_id" IS NOT NULL) AND ("worker_attempt" IS NOT NULL) AND (("worker_attempt" >= 1) AND ("worker_attempt" <= 20)) AND ("attempt_owner" IS NOT NULL) AND (("length"("attempt_owner") >= 1) AND ("length"("attempt_owner") <= 240)) AND ("snapshot_format_version" IS NOT NULL) AND ("snapshot_format_version" = ANY (ARRAY[1, 2])) AND ("snapshot_row_count" IS NOT NULL) AND ("snapshot_row_count" >= 0) AND ("object_path" ~ '^tenants/[0-9a-f-]{36}/exports/forms/[0-9a-f-]{36}/[0-9a-f-]{36}/responses[.]xlsx$'::"text") AND ((("state" = 'completed'::"text") AND ("checksum_sha256" IS NOT NULL) AND ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text")) OR (("state" <> 'completed'::"text") AND ("checksum_sha256" IS NULL)))))),
