    CONSTRAINT "form_multipart_uploads_terminal_ck" CHECK (((("state" = 'completed'::"text") = ("completed_at" IS NOT NULL)) AND (("state" = 'aborted'::"text") = ("aborted_at" IS NOT NULL)))),
    CONSTRAINT "form_multipart_uploads_upload_id_ck" CHECK (((("length"("btrim"("upload_id")) >= 1) AND ("length"("btrim"("upload_id")) <= 1024)) AND ("upload_id" !~ '[[:cntrl:]]'::"text")))
);

