    "street" "text" DEFAULT ''::"text" NOT NULL,
    "address_number" "text" DEFAULT ''::"text" NOT NULL,
    "complement" "text" DEFAULT ''::"text" NOT NULL,
    "neighborhood" "text" DEFAULT ''::"text" NOT NULL,
    "city" "text" DEFAULT ''::"text" NOT NULL,
    "state" "text" DEFAULT ''::"text" NOT NULL,
    "country" "text" DEFAULT 'Brasil'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "version" bigint DEFAULT 1 NOT NULL,
    CONSTRAINT "superadmin_internal_profiles_additional_phone_check" CHECK (("length"("additional_phone") <= 24)),
    CONSTRAINT "superadmin_internal_profiles_address_number_check" CHECK (("length"("address_number") <= 24)),
    CONSTRAINT "superadmin_internal_profiles_city_check" CHECK (("length"("city") <= 120)),
    CONSTRAINT "superadmin_internal_profiles_complement_check" CHECK (("length"("complement") <= 120)),
    CONSTRAINT "superadmin_internal_profiles_country_check" CHECK ((("length"("country") >= 1) AND ("length"("country") <= 80))),
    CONSTRAINT "superadmin_internal_profiles_cpf_check" CHECK (("cpf" ~ '^[0-9]{11}$'::"text")),
    CONSTRAINT "superadmin_internal_profiles_department_check" CHECK (("length"("department") <= 120)),
    CONSTRAINT "superadmin_internal_profiles_display_name_check" CHECK (("length"("display_name") <= 160)),
    CONSTRAINT "superadmin_internal_profiles_first_name_check" CHECK ((("length"("btrim"("first_name")) >= 1) AND ("length"("btrim"("first_name")) <= 80))),
    CONSTRAINT "superadmin_internal_profiles_internal_function_check" CHECK (("length"("internal_function") <= 120)),
    CONSTRAINT "superadmin_internal_profiles_job_title_check" CHECK ((("length"("btrim"("job_title")) >= 1) AND ("length"("btrim"("job_title")) <= 120))),
    CONSTRAINT "superadmin_internal_profiles_last_name_check" CHECK ((("length"("btrim"("last_name")) >= 1) AND ("length"("btrim"("last_name")) <= 120))),
    CONSTRAINT "superadmin_internal_profiles_mobile_check" CHECK (("length"("mobile") <= 24)),
    CONSTRAINT "superadmin_internal_profiles_neighborhood_check" CHECK (("length"("neighborhood") <= 120)),
    CONSTRAINT "superadmin_internal_profiles_postal_code_check" CHECK (("length"("postal_code") <= 12)),
    CONSTRAINT "superadmin_internal_profiles_professional_email_check" CHECK ((("professional_email" = "lower"("btrim"("professional_email"))) AND ("length"("professional_email") <= 254) AND ("professional_email" ~~ '%@%'::"text"))),
    CONSTRAINT "superadmin_internal_profiles_professional_notes_check" CHECK (("length"("professional_notes") <= 1000)),
    CONSTRAINT "superadmin_internal_profiles_state_check" CHECK (("length"("state") <= 80)),
    CONSTRAINT "superadmin_internal_profiles_street_check" CHECK (("length"("street") <= 160)),
    CONSTRAINT "superadmin_internal_profiles_version_check" CHECK (("version" > 0))
);

