    CONSTRAINT "access_profile_templates_domain_check" CHECK (("domain" = ANY (ARRAY['platform'::"text", 'institution'::"text", 'principal'::"text"]))),
    CONSTRAINT "access_profile_templates_name_check" CHECK ((("char_length"("btrim"("name")) >= 2) AND ("char_length"("btrim"("name")) <= 120))),
    CONSTRAINT "access_profile_templates_scope_check" CHECK (((("domain" = 'platform'::"text") AND ("max_scope_kind" = ANY (ARRAY['platform'::"text", 'institution'::"text"]))) OR (("domain" = 'institution'::"text") AND ("max_scope_kind" = ANY (ARRAY['institution'::"text", 'unit'::"text", 'group'::"text"]))) OR (("domain" = 'principal'::"text") AND ("max_scope_kind" = 'child_context'::"text")))),
