    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "linked_by_actor_kind" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("linked_by_person_id" IS NULL) THEN 'superadmin_internal'::"text"
    ELSE 'person'::"text"
END) STORED,
    CONSTRAINT "activity_unit_links_dates_check" CHECK ((("ends_at" IS NULL) OR ("ends_at" > "starts_at")))
);

