    CONSTRAINT "attendance_records_revert_check" CHECK (((("status" = 'active'::"public"."record_status") AND ("reverted_by_person_id" IS NULL) AND ("reverted_at" IS NULL) AND ("revert_reason" IS NULL)) OR (("status" = 'inactive'::"public"."record_status") AND ("reverted_by_person_id" IS NOT NULL) AND ("reverted_at" IS NOT NULL) AND ("btrim"("revert_reason") <> ''::"text"))))
);

