CREATE OR REPLACE VIEW "public"."attendance_summary" WITH ("security_invoker"='true') AS
 SELECT "session_row"."institution_id",
    "session_row"."unit_id",
    "session_row"."group_id",
    "session_row"."activity_id",
    "record_row"."child_context_id",
    "count"(*) FILTER (WHERE ("record_row"."outcome" = 'present'::"text")) AS "present_count",
    "count"(*) FILTER (WHERE ("record_row"."outcome" = 'absent'::"text")) AS "absent_count",
    "count"(*) AS "official_count",
    "round"(((100.0 * ("count"(*) FILTER (WHERE ("record_row"."outcome" <> 'absent'::"text")))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "attendance_percentage"
   FROM ("public"."attendance_records" "record_row"
     JOIN "public"."attendance_sessions" "session_row" ON (("session_row"."id" = "record_row"."attendance_session_id")))
  WHERE ("record_row"."status" = 'active'::"public"."record_status")
  GROUP BY "session_row"."institution_id", "session_row"."unit_id", "session_row"."group_id", "session_row"."activity_id", "record_row"."child_context_id";


ALTER VIEW "public"."attendance_summary" OWNER TO "postgres";


