CREATE TABLE IF NOT EXISTS "public"."routine_applications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "unit_id" "uuid",
    "group_id" "uuid",
    "activity_id" "uuid",
    "scope_kind" "text" DEFAULT 'institution'::"text" NOT NULL,
    "source_model_version_id" "uuid",
    "parent_application_id" "uuid",
    "inheritance_mode" "text" DEFAULT 'inherited'::"text" NOT NULL,
    "visibility" "text" DEFAULT 'authorized_guardians'::"text" NOT NULL,
    "valid_from" "date",
    "valid_until" "date",
    "starts_at" time without time zone,
    "ends_at" time without time zone,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "management_version" bigint DEFAULT 0 NOT NULL,
    "created_by_person_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "routine_applications_inheritance_mode_check" CHECK (("inheritance_mode" = ANY (ARRAY['inherited'::"text", 'customized'::"text"]))),
    CONSTRAINT "routine_applications_parent_check" CHECK (("parent_application_id" <> "id")),
    CONSTRAINT "routine_applications_scope_check" CHECK (((("scope_kind" = 'institution'::"text") AND ("unit_id" IS NULL) AND ("group_id" IS NULL) AND ("activity_id" IS NULL)) OR (("scope_kind" = 'unit'::"text") AND ("unit_id" IS NOT NULL) AND ("group_id" IS NULL) AND ("activity_id" IS NULL)) OR (("scope_kind" = 'group'::"text") AND ("unit_id" IS NOT NULL) AND ("group_id" IS NOT NULL) AND ("activity_id" IS NULL)) OR (("scope_kind" = 'activity'::"text") AND ("unit_id" IS NOT NULL) AND ("group_id" IS NOT NULL) AND ("activity_id" IS NOT NULL)))),
    CONSTRAINT "routine_applications_scope_kind_check" CHECK (("scope_kind" = ANY (ARRAY['institution'::"text", 'unit'::"text", 'group'::"text", 'activity'::"text"]))),
    CONSTRAINT "routine_applications_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'inactive'::"text", 'archived'::"text"]))),
    CONSTRAINT "routine_applications_validity_check" CHECK ((("valid_until" IS NULL) OR ("valid_from" IS NULL) OR ("valid_until" >= "valid_from"))),
    CONSTRAINT "routine_applications_visibility_check" CHECK (("visibility" = ANY (ARRAY['authorized_guardians'::"text", 'institution_staff'::"text", 'unit_staff'::"text"]))),
    CONSTRAINT "routine_applications_window_check" CHECK ((("ends_at" IS NULL) OR ("starts_at" IS NULL) OR ("ends_at" > "starts_at")))
);

ALTER TABLE ONLY "public"."routine_applications" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."routine_applications" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."daily_routine_effective_applications" WITH ("security_invoker"='true') AS
 SELECT "application_row"."id",
    "application_row"."institution_id",
    "application_row"."unit_id",
    "application_row"."group_id",
    "application_row"."activity_id",
    "application_row"."scope_kind",
    "application_row"."status",
    "application_row"."inheritance_mode",
    "application_row"."visibility",
    "application_row"."valid_from",
    "application_row"."valid_until",
    "application_row"."starts_at",
    "application_row"."ends_at",
    "application_row"."management_version",
    "application_row"."parent_application_id",
    "application_row"."source_model_version_id",
    "revision_row"."id" AS "revision_id",
    "revision_row"."revision_no",
    "revision_row"."origin_application_id",
    "revision_row"."effective_definition",
    "application_row"."updated_at"
   FROM ("public"."routine_applications" "application_row"
     LEFT JOIN LATERAL ( SELECT "candidate"."id",
            "candidate"."application_id",
            "candidate"."revision_no",
            "candidate"."source_model_version_id",
            "candidate"."origin_application_id",
            "candidate"."effective_definition",
            "candidate"."created_by_person_id",
            "candidate"."created_at"
           FROM "public"."routine_application_revisions" "candidate"
          WHERE ("candidate"."application_id" = "application_row"."id")
          ORDER BY "candidate"."revision_no" DESC
         LIMIT 1) "revision_row" ON (true));


ALTER VIEW "public"."daily_routine_effective_applications" OWNER TO "postgres";


