CREATE OR REPLACE VIEW "public"."institution_directory" WITH ("security_invoker"='true') AS
 SELECT "i"."id",
    "i"."public_name",
    "i"."trade_name",
    "i"."legal_name",
    "i"."primary_domain",
    ("i"."status")::"text" AS "status",
    "i"."institution_type_id",
    "it"."code" AS "type_code",
    "it"."name" AS "type_name",
    "ia"."country",
    "ia"."state",
    "ia"."city",
    "ia"."district",
    "ia"."street",
    "ia"."number",
    "ia"."complement",
    "ia"."postal_code",
    "latest_subscription"."plan_id",
    "latest_subscription"."plan_name",
    "latest_subscription"."subscription_status",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."units" "u"
          WHERE (("u"."institution_id" = "i"."id") AND ("u"."status" <> 'archived'::"public"."record_status"))) AS "units_count",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."groups" "g"
          WHERE (("g"."institution_id" = "i"."id") AND ("g"."status" <> 'archived'::"public"."record_status"))) AS "groups_count",
    "lower"("concat_ws"(' '::"text", "i"."public_name", "i"."trade_name", "i"."legal_name")) AS "search_name",
    "ic"."email" AS "contact_email",
    "ic"."phone" AS "contact_phone",
    "ic"."mobile_phone" AS "contact_mobile_phone"
   FROM (((("public"."institutions" "i"
     LEFT JOIN "public"."institution_types" "it" ON (("it"."id" = "i"."institution_type_id")))
     LEFT JOIN "public"."institution_addresses" "ia" ON (("ia"."institution_id" = "i"."id")))
     LEFT JOIN "public"."institution_contacts" "ic" ON ((("ic"."institution_id" = "i"."id") AND ("ic"."status" <> 'archived'::"public"."record_status"))))
     LEFT JOIN LATERAL ( SELECT "subscription"."plan_id",
            "plan"."name" AS "plan_name",
            ("subscription"."status")::"text" AS "subscription_status"
           FROM ("public"."institution_subscriptions" "subscription"
             LEFT JOIN "public"."plans" "plan" ON (("plan"."id" = "subscription"."plan_id")))
          WHERE ("subscription"."institution_id" = "i"."id")
          ORDER BY "subscription"."created_at" DESC, "subscription"."id" DESC
         LIMIT 1) "latest_subscription" ON (true))
  WHERE ("i"."deleted_at" IS NULL);


ALTER VIEW "public"."institution_directory" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."institution_directory_locations" WITH ("security_invoker"='true') AS
 SELECT DISTINCT "ia"."state",
    "ia"."city",
    "ia"."district"
   FROM ("public"."institutions" "i"
     JOIN "public"."institution_addresses" "ia" ON (("ia"."institution_id" = "i"."id")))
  WHERE (("i"."deleted_at" IS NULL) AND ("ia"."status" <> 'archived'::"public"."record_status") AND ("ia"."state" IS NOT NULL));


