CREATE TABLE IF NOT EXISTS "public"."now_media_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "publication_id" "uuid" NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "owner_person_id" "uuid" NOT NULL,
    "kind" "public"."now_asset_kind" NOT NULL,
    "storage_provider" "text" DEFAULT 'r2'::"text" NOT NULL,
    "bucket_id" "text" NOT NULL,
    "object_key" "text" NOT NULL,
    "original_name" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "byte_size" bigint NOT NULL,
    "duration_seconds" numeric(7,3),
    "rights_confirmed" boolean DEFAULT false NOT NULL,
    "checksum_sha256" "text",
    "status" "public"."now_asset_status" DEFAULT 'pending'::"public"."now_asset_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finalized_at" timestamp with time zone,
    CONSTRAINT "now_media_assets_bucket_ck" CHECK (((("storage_provider" = 'supabase_mvp'::"text") AND ("bucket_id" = 'coelo-now-mvp'::"text")) OR (("storage_provider" = 'r2'::"text") AND ("bucket_id" = 'coelo-media-prod'::"text")))),
    CONSTRAINT "now_media_assets_byte_size_check" CHECK (("byte_size" > 0)),
    CONSTRAINT "now_media_assets_check" CHECK ((("kind" <> 'audio'::"public"."now_asset_kind") OR "rights_confirmed")),
    CONSTRAINT "now_media_assets_checksum_format_ck" CHECK ((("checksum_sha256" IS NULL) OR ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "now_media_assets_mime_type_check" CHECK (("mime_type" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text", 'video/mp4'::"text", 'audio/mpeg'::"text", 'audio/mp4'::"text", 'audio/wav'::"text", 'audio/aac'::"text"]))),
    CONSTRAINT "now_media_assets_r2_key_shape_ck" CHECK ((("storage_provider" <> 'r2'::"text") OR ("object_key" ~ (((((((((('^tenants/'::"text" || ("institution_id")::"text") || '/now/publication/'::"text") || ("publication_id")::"text") || '/'::"text") || ("kind")::"text") || '/'::"text") || ("id")::"text") || '/original/'::"text") || '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'::"text") ||
CASE "mime_type"
    WHEN 'image/jpeg'::"text" THEN '[.]jpg$'::"text"
    WHEN 'image/png'::"text" THEN '[.]png$'::"text"
    WHEN 'image/webp'::"text" THEN '[.]webp$'::"text"
    WHEN 'video/mp4'::"text" THEN '[.]mp4$'::"text"
    WHEN 'audio/mpeg'::"text" THEN '[.]mp3$'::"text"
    WHEN 'audio/mp4'::"text" THEN '[.]m4a$'::"text"
    WHEN 'audio/wav'::"text" THEN '[.]wav$'::"text"
    WHEN 'audio/aac'::"text" THEN '[.]aac$'::"text"
    ELSE '$a'::"text"
END)))),
    CONSTRAINT "now_media_assets_r2_ready_integrity_ck" CHECK ((("storage_provider" <> 'r2'::"text") OR ("status" <> 'ready'::"public"."now_asset_status") OR (("checksum_sha256" IS NOT NULL) AND ("finalized_at" IS NOT NULL)))),
    CONSTRAINT "now_media_assets_storage_provider_check" CHECK (("storage_provider" = ANY (ARRAY['supabase_mvp'::"text", 'r2'::"text"])))
);

