CREATE TABLE IF NOT EXISTS "public"."person_contacts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "person_id" "uuid" NOT NULL,
    "contact_type" "text" NOT NULL,
    "normalized_value_hash" "text" NOT NULL,
    "masked_value" "text",
    "verified_at" timestamp with time zone,
    "status" "public"."record_status" DEFAULT 'active'::"public"."record_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "confirmation_method" "text",
    "confirmed_at" timestamp with time zone,
    CONSTRAINT "person_contacts_verification_method_check" CHECK (((("confirmation_method" IS NULL) AND ("confirmed_at" IS NULL) AND ("verified_at" IS NULL)) OR (("confirmation_method" = ANY (ARRAY['email_link'::"text", 'phone_otp'::"text", 'identity_provider'::"text", 'administrative_evidence'::"text", 'verified_email_attestation'::"text", 'legacy_unspecified'::"text"])) AND ("confirmed_at" IS NOT NULL) AND (("verified_at" IS NULL) OR ("confirmation_method" = ANY (ARRAY['email_link'::"text", 'phone_otp'::"text", 'identity_provider'::"text", 'administrative_evidence'::"text", 'legacy_unspecified'::"text"]))) AND (NOT (("confirmation_method" = 'verified_email_attestation'::"text") AND ("verified_at" IS NOT NULL))))))
);


ALTER TABLE "public"."person_contacts" OWNER TO "postgres";


COMMENT ON COLUMN "public"."person_contacts"."confirmation_method" IS 'How a contact claim was confirmed. verified_email_attestation is not phone-possession verification.';



CREATE OR REPLACE VIEW "public"."person_directory" WITH ("security_invoker"='true') AS
 SELECT "id",
    "person_type",
    "display_name",
    "status",
    (EXISTS ( SELECT 1
           FROM "public"."person_auth_links" "auth_link"
          WHERE (("auth_link"."person_id" = "person"."id") AND ("auth_link"."status" = 'active'::"public"."record_status") AND ("auth_link"."revoked_at" IS NULL)))) AS "has_active_login",
    ( SELECT "count"(*) AS "count"
           FROM "public"."institution_memberships" "membership"
          WHERE (("membership"."person_id" = "person"."id") AND ("membership"."status" = 'active'::"public"."record_status") AND ("membership"."revoked_at" IS NULL))) AS "institution_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."guardian_links" "guardian_link"
          WHERE (("guardian_link"."guardian_person_id" = "person"."id") AND ("guardian_link"."status" = 'active'::"public"."record_status") AND ("guardian_link"."revoked_at" IS NULL))) AS "child_count"
   FROM "public"."people" "person"
  WHERE (("deleted_at" IS NULL) AND ("id" = ( SELECT "app_private"."current_person_id"() AS "current_person_id")));


ALTER VIEW "public"."person_directory" OWNER TO "postgres";


