CREATE TABLE IF NOT EXISTS "public"."unit_type_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "request_id" "uuid" NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "requested_description" "text" NOT NULL,
    "context_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "public"."unit_type_request_status" DEFAULT 'pending'::"public"."unit_type_request_status" NOT NULL,
    "requested_by_person_id" "uuid" NOT NULL,
    "reviewed_by_person_id" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_reason" "text",
    "approved_unit_type_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "unit_type_requests_context_json_check" CHECK (("jsonb_typeof"("context_json") = 'object'::"text")),
    CONSTRAINT "unit_type_requests_requested_description_check" CHECK (("btrim"("requested_description") <> ''::"text")),
    CONSTRAINT "unit_type_requests_review_check" CHECK (((("status" = 'pending'::"public"."unit_type_request_status") AND ("reviewed_by_person_id" IS NULL) AND ("reviewed_at" IS NULL) AND ("approved_unit_type_id" IS NULL)) OR (("status" = 'approved'::"public"."unit_type_request_status") AND ("reviewed_by_person_id" IS NOT NULL) AND ("reviewed_at" IS NOT NULL) AND ("approved_unit_type_id" IS NOT NULL)) OR (("status" = 'rejected'::"public"."unit_type_request_status") AND ("reviewed_by_person_id" IS NOT NULL) AND ("reviewed_at" IS NOT NULL) AND ("approved_unit_type_id" IS NULL) AND (NULLIF("btrim"("review_reason"), ''::"text") IS NOT NULL)) OR ("status" = 'withdrawn'::"public"."unit_type_request_status")))
);

