ALTER TABLE "public"."circular_media_assets"
    ADD CONSTRAINT "circular_media_assets_bucket_ck" CHECK (((("storage_provider" = 'supabase'::"text") AND ("bucket_id" = 'coelo-circulars-private'::"text")) OR (("storage_provider" = 'r2'::"text") AND ("bucket_id" =
CASE
    WHEN ("mime_type" = 'application/pdf'::"text") THEN 'coelo-documents-prod'::"text"
    ELSE 'coelo-media-prod'::"text"
END)))) NOT VALID;



ALTER TABLE "public"."circular_media_assets"
    ADD CONSTRAINT "circular_media_assets_checksum_format_ck" CHECK ((("checksum_sha256" IS NULL) OR ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text"))) NOT VALID;



ALTER TABLE ONLY "public"."circular_media_assets"
    ADD CONSTRAINT "circular_media_assets_circular_id_upload_request_id_key" UNIQUE ("circular_id", "upload_request_id");



ALTER TABLE ONLY "public"."circular_media_assets"
    ADD CONSTRAINT "circular_media_assets_object_key_key" UNIQUE ("object_key");



ALTER TABLE ONLY "public"."circular_media_assets"
    ADD CONSTRAINT "circular_media_assets_pkey" PRIMARY KEY ("id");



ALTER TABLE "public"."circular_media_assets"
    ADD CONSTRAINT "circular_media_assets_r2_key_shape_ck" CHECK ((("storage_provider" <> 'r2'::"text") OR ("object_key" ~ (((((((('^tenants/'::"text" || ("institution_id")::"text") || '/circulars/circular/'::"text") || ("circular_id")::"text") || '/attachment/'::"text") || ("id")::"text") || '/original/'::"text") || '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'::"text") ||
CASE "mime_type"
    WHEN 'image/jpeg'::"text" THEN '[.]jpg$'::"text"
    WHEN 'image/png'::"text" THEN '[.]png$'::"text"
    WHEN 'image/webp'::"text" THEN '[.]webp$'::"text"
    WHEN 'video/mp4'::"text" THEN '[.]mp4$'::"text"
    WHEN 'application/pdf'::"text" THEN '[.]pdf$'::"text"
    ELSE '$a'::"text"
END)))) NOT VALID;



ALTER TABLE "public"."circular_media_assets"
    ADD CONSTRAINT "circular_media_assets_r2_ready_integrity_ck" CHECK ((("storage_provider" <> 'r2'::"text") OR ("status" <> 'ready'::"public"."circular_media_status") OR (("checksum_sha256" IS NOT NULL) AND ("byte_size" IS NOT NULL) AND ("finalized_at" IS NOT NULL)))) NOT VALID;



