ALTER TABLE "public"."media_assets"
    ADD CONSTRAINT "media_assets_happens_bucket_ck" CHECK ((("catalog_kind" <> 'legacy-happens'::"text") OR (("storage_provider" = 'supabase_mvp'::"text") AND ("bucket_id" = 'coelo-happens-mvp'::"text")) OR (("storage_provider" = 'r2'::"text") AND ("bucket_id" = 'coelo-media-prod'::"text")))) NOT VALID;



ALTER TABLE "public"."media_assets"
    ADD CONSTRAINT "media_assets_happens_checksum_format_ck" CHECK ((("catalog_kind" <> 'legacy-happens'::"text") OR ("checksum_sha256" IS NULL) OR ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text"))) NOT VALID;



ALTER TABLE "public"."media_assets"
    ADD CONSTRAINT "media_assets_happens_r2_key_shape_ck" CHECK ((("catalog_kind" <> 'legacy-happens'::"text") OR ("storage_provider" <> 'r2'::"text") OR ("object_key" ~ (((((((('^tenants/'::"text" || ("institution_id")::"text") || '/happens/post/'::"text") || ("post_id")::"text") || '/attachment/'::"text") || ("id")::"text") || '/original/'::"text") || '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'::"text") ||
CASE "mime_type"
    WHEN 'image/jpeg'::"text" THEN '[.]jpg$'::"text"
    WHEN 'image/png'::"text" THEN '[.]png$'::"text"
    WHEN 'image/webp'::"text" THEN '[.]webp$'::"text"
    WHEN 'video/mp4'::"text" THEN '[.]mp4$'::"text"
    ELSE '$a'::"text"
END)))) NOT VALID;



ALTER TABLE "public"."media_assets"
    ADD CONSTRAINT "media_assets_happens_r2_ready_integrity_ck" CHECK ((("catalog_kind" <> 'legacy-happens'::"text") OR ("storage_provider" <> 'r2'::"text") OR ("status" <> 'ready'::"public"."happens_media_status") OR (("checksum_sha256" IS NOT NULL) AND ("finalized_at" IS NOT NULL)))) NOT VALID;



